CARDIO.register({"item":"231","meta":{"num":231,"short":"ECG","title":"Électrocardiogramme","section":"III","chapter":15,"pages":"367-417","sdd":[{"num":4,"label":"Douleur abdominale"},{"num":21,"label":"Asthénie"},{"num":42,"label":"Hypertension artérielle"},{"num":43,"label":"Découverte d'une hypotension artérielle"},{"num":50,"label":"Malaise/perte de connaissance"},{"num":121,"label":"Déficit neurologique sensitif et/ou moteur"},{"num":159,"label":"Bradycardie"},{"num":160,"label":"Détresse respiratoire aiguë"},{"num":161,"label":"Douleur thoracique"},{"num":162,"label":"Dyspnée"},{"num":165,"label":"Palpitations"},{"num":166,"label":"Tachycardie"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"},{"num":185,"label":"Réalisation et interprétation d'un électrocardiogramme (ECG)"},{"num":200,"label":"Dyscalcémie"},{"num":201,"label":"Dyskaliémie"},{"num":204,"label":"Élévation des enzymes cardiaques"},{"num":266,"label":"Consultation de suivi d'un patient polymédiqué"},{"num":287,"label":"Consultation de suivi et éducation thérapeutique d'un patient insuffisant cardiaque"}]},"objectives":[{"id":"231-obj-01","rank":"A","rubric":"Diagnostic positif","title":"Connaître les modalités d'interprétation d'un ECG normal","desc":"Morphologies normales et paramètres numériques"},{"id":"231-obj-02","rank":"A","rubric":"Identifier une urgence","title":"Connaître les signes de gravité de l'ECG","desc":"Anomalies électrocardiographiques devant amener une réponse thérapeutique urgente"},{"id":"231-obj-03","rank":"B","rubric":"Diagnostic positif","title":"Identifier les hypertrophies atriales","desc":"Reconnaître formes droites et gauches"},{"id":"231-obj-04","rank":"B","rubric":"Diagnostic positif","title":"Identifier les hypertrophies ventriculaires droites","desc":"Reconnaître les différents aspects y compris dans l'embolie pulmonaire"},{"id":"231-obj-05","rank":"A","rubric":"Diagnostic positif","title":"Identifier les hypertrophies ventriculaires gauches","desc":"Reconnaître les deux formes principales"},{"id":"231-obj-06","rank":"A","rubric":"Diagnostic positif","title":"Identifier les blocs complets de branche, les hémiblocs et les blocs bifasciculaires","desc":"Reconnaître BBD, BBG complets, HBAG, HBPG et associations"},{"id":"231-obj-07","rank":"B","rubric":"Diagnostic positif","title":"Identifier les blocs incomplets de branche et les blocs fonctionnels","desc":"Reconnaître le BBD ou le BBG incomplet, les aberrations de conduction"},{"id":"231-obj-08","rank":"A","rubric":"Diagnostic positif","title":"Identifier les blocs atrioventriculaires en rythme sinusal","desc":"Reconnaître les BAV de 3e degré et de tous types, blocs de haut degré et blocs rythmés"},{"id":"231-obj-09","rank":"B","rubric":"Diagnostic positif","title":"Identifier les blocs atrioventriculaires associés aux troubles du rythme","desc":"Reconnaître les BAV du 3e degré associés à la FA ou aux flutters"},{"id":"231-obj-10","rank":"A","rubric":"Diagnostic positif","title":"Identifier la dysfonction sinusale","desc":"Reconnaître une dysfonction sinusale"},{"id":"231-obj-11","rank":"B","rubric":"Diagnostic positif","title":"Connaître les mécanismes et les variantes de dysfonction sinusale","desc":"BSA du 2e degré et maladie de l'oreillette"},{"id":"231-obj-12","rank":"A","rubric":"Diagnostic positif","title":"Savoir différencier une tachycardie sinusale d'une tachycardie supraventriculaire non sinusale","desc":"Savoir faire le diagnostic positif et différencier tachycardie sinusale et troubles du rythme supraventriculaire"},{"id":"231-obj-13","rank":"A","rubric":"Diagnostic positif","title":"Identifier la fibrillation atriale","desc":""},{"id":"231-obj-14","rank":"A","rubric":"Diagnostic positif","title":"Identifier les flutters atriaux","desc":"Reconnaître un flutter atrial"},{"id":"231-obj-15","rank":"A","rubric":"Diagnostic positif","title":"Tachycardies jonctionnelles","desc":""},{"id":"231-obj-16","rank":"B","rubric":"Diagnostic positif","title":"Connaître l'intérêt des manœuvres vagales dans les troubles du rythme","desc":"Réalisation et apport des manœuvres vagales et médicaments purinergiques"},{"id":"231-obj-17","rank":"A","rubric":"Diagnostic positif","title":"Identifier les extrasystoles","desc":"Reconnaître une extrasystole atriale ou ventriculaire"},{"id":"231-obj-18","rank":"A","rubric":"Diagnostic positif","title":"Identifier la tachycardie ventriculaire","desc":"Reconnaître une TV"},{"id":"231-obj-19","rank":"A","rubric":"Diagnostic positif","title":"Identifier la fibrillation ventriculaire","desc":"Reconnaître une FV"},{"id":"231-obj-20","rank":"B","rubric":"Diagnostic positif","title":"Identifier les torsades de pointes","desc":"Reconnaître une torsade de pointes et un allongement de QT hors hypokaliémie"},{"id":"231-obj-21","rank":"A","rubric":"Diagnostic positif","title":"Identifier les dyskaliémies","desc":"Reconnaître les anomalies ECG des dyskaliémies y compris QT long"},{"id":"231-obj-22","rank":"A","rubric":"Diagnostic positif","title":"Identifier l'allongement de QT","desc":"Médicamenteuse, congénitale, ionique, etc."},{"id":"231-obj-23","rank":"B","rubric":"Diagnostic positif","title":"Identifier les péricardites aiguës","desc":"Différences ECG entre péricardites aiguës et syndromes coronariens aigus"},{"id":"231-obj-24","rank":"A","rubric":"Diagnostic positif","title":"Identifier la maladie coronarienne et les syndromes coronariens aigus","desc":"Ondes Q, territoires, anomalies du segment ST et de l'onde T, séquelles"},{"id":"231-obj-25","rank":"B","rubric":"Diagnostic positif","title":"Identifier le Wolff-Parkinson-White","desc":""},{"id":"231-obj-26","rank":"B","rubric":"Diagnostic positif","title":"Identifier la présence d'un électroentraînement atrial, ventriculaire ou séquentiel","desc":"Savoir reconnaître la présence d'un électroentraînement atrial, ventriculaire ou séquentiel"},{"id":"231-obj-27","rank":"A","rubric":"Diagnostic positif","title":"Connaître les indications d'un ECG","desc":"Principales indications des cardioscopes et des ECG de repos (12-15 ou 18 dérivations) ; indications en urgence : défaillance(s) d'organe(s), douleur thoracique, palpitations, syncope, troubles hydroélectrolytiques (K, Ca) ; savoir réaliser un ECG 12 dérivations"},{"id":"231-obj-28","rank":"B","rubric":"Examens complémentaires","title":"Connaître la méthode Holter","desc":"Indications des enregistrements externes de longue durée"}],"course":{"sections":[{"id":"231-sec-01","title":"Conduction et genèse du signal ECG","rank":"A","objectives":["231-obj-01"],"content":"### Conduction atrioventriculaire\n- [B] Physiologiquement, le **NAV est le seul passage** entre oreillettes et ventricules : le reste du plan de l'anneau isole totalement l'oreillette du ventricule.\n- QRS **fin** quand le ventricule est activé par les voies de conduction naturelles (ex. complexe de capture) ; QRS **large** quand la dépolarisation ventriculaire progresse lentement **de proche en proche**, hors de ces voies : **tachycardie ventriculaire**, née sous la bifurcation hissienne et ne passant pas par le NAV, le His, les branches et le Purkinje ; [B] **stimulation ventriculaire droite** par pacemaker (QRS large d'aspect BBG).\n- Un **bloc de branche** complet élargit aussi le QRS (> 120 ms) : une tachycardie supraventriculaire associée à un bloc de branche donne donc des QRS larges.\n\n### Rythmes d'échappement\n- Dysfonction sinusale marquée : **échappement jonctionnel** (onde P absente devant le QRS, parfois rétrograde).\n- BAV complet : rythme d'échappement **lent et régulier** ; à **QRS fins**, il traduit un bloc **nodal** (suprahissien). [B] Le Collège évoque aussi les « échappements à QRS larges des BAV bas situés » (cause de bradycardie extrême et de QT long).\n\n### Électrogenèse\n[B] Rang B.\n\n- L'ECG enregistre sur le thorax la **somme des potentiels d'action** suivant un front de dépolarisation : **P** (oreillettes) puis **QRS** (ventricules) ; **T** = repolarisation graduelle.\n- Dépolarisation **vers** l'électrode → **positive** ; s'en **éloignant** → **négative** ; perpendiculaire → **isodiphasique** (positive puis négative).\n- T est **concordante** au QRS sur l'ECG normal, car la dépolarisation ventriculaire va de l'endocarde vers l'épicarde et la repolarisation en sens inverse.","keyPoints":["Le NAV est le seul passage physiologique entre oreillettes et ventricules (le reste du plan de l'anneau est isolant) (B).","QRS fin = activation par les voies de conduction ; QRS large = conduction lente de proche en proche (TV ; stimulation ventriculaire droite, B) ou bloc de branche.","Front de dépolarisation vers l'électrode = onde positive ; s'en éloignant = onde négative (B).","Ondes T normalement concordantes aux QRS ; explication (B) : dépolarisation endocarde → épicarde, repolarisation en sens inverse.","Échappement à QRS fins (BAV complet) = bloc nodal (suprahissien)."],"pitfalls":["Une onde T de même polarité que le QRS est normale (concordance) : ne pas la prendre pour une anomalie."],"src":"p. 371, 378, 387, 390, 398, 401, 404, 410, 414"},{"id":"231-sec-02","title":"Dérivations, territoires et axe du QRS","rank":"A","objectives":["231-obj-01","231-obj-27"],"content":"### Dérivations\n- **Frontales** (plan vertical) : D1, D2, D3 (I, II, III) obtenues à partir des membres, complétées par les unipolaires **aVR, aVL, aVF**.\n- **Précordiales** (plan horizontal) : **V1 à V9**, complétées **parfois** par **V3R et V4R** chez l'enfant ou en cas de suspicion de SCA.\n- Placement : électrodes précordiales **isodistantes** (même écart entre elles).\n\n> **Piège de pose** : V1 et V2 sont trop souvent placées trop haut et trop écartées (confusion avec les foyers auscultatoires aortique et pulmonaire) → faux aspect de **pseudonécrose** ou d'atypie de repolarisation antérieure.\n\n- **Dérivations de Lewis** : pour démasquer une activité atriale peu visible. Électrode rouge (bras droit) sur la fourchette sternale, électrode jaune (bras gauche) au 5e espace intercostal droit ; l'activité atriale est alors bien lue en **D1**.\n\n### Territoires explorés (utiles à la localisation des infarctus)\n| Territoire | Dérivations | Paroi |\n|---|---|---|\n| Antéroseptal | V1, V2, V3 | paroi antérieure du VG et septum |\n| Apical | V4 | apex |\n| Latéral haut | D1, aVL | paroi latérale |\n| Latéral bas | V5, V6 | paroi latérale |\n| Inférieur (diaphragmatique) | D2, D3, aVF | face inférieure du VG |\n| Postérieur | V7, V8, V9 | face basale et inférieure du VG |\n| Ventricule droit | V1, V2, V3R, V4R | VD |\n\n### Axe du QRS\n- Mesuré dans le plan frontal sur le **double triaxe de Bailey** : dérivations graduées de 30° en 30° dans le sens horaire, D1 à l'horizontale (0°).\n- Méthode rapide par la polarité de D1 et aVF :\n\n| D1 | aVF | Axe |\n|---|---|---|\n| + | + | 0 à +90° : **normal** |\n| + | – | 0 à –90° : normal si D2 positif (0 à –30°), sinon **hypergauche** |\n| – | + | +90 à +180° : **hyperdroit** |\n| – | – | –90 à –180° : **axe extrême** |\n\n- **Axe normal : –30° à +90°** (de aVL à aVF ; valeurs théoriques –45° à +110°).\n- Variations anatomiques : cœur **vertical** du sujet filiforme → axe proche de 90° ; cœur **horizontal** de l'obèse ou de la cardiomégalie → axe proche de 0°.\n- Axe anormal en cas d'**hémibloc** gauche ou d'anomalie morphologique marquée d'un ventricule.\n- Onde **isodiphasique** : composantes positive et négative d'égale importance (aspect sinusoïdal).","keyPoints":["Frontales D1-D2-D3 + aVR-aVL-aVF ; précordiales V1–V9 (+ V3R, V4R pour le VD).","Antéroseptal V1-V3, apical V4, latéral D1-aVL (haut) et V5-V6 (bas), inférieur D2-D3-aVF, postérieur V7-V9.","Axe normal du QRS : –30° à +90° ; D1+ et aVF+ = axe normal.","D1+ aVF– : normal si D2 positif, hypergauche sinon ; D1– aVF+ = hyperdroit.","Dérivations de Lewis : mieux voir l'activité atriale en D1."],"pitfalls":["V1-V2 posées trop haut → pseudonécrose antérieure ou repolarisation atypique.","Un D1 négatif fait d'abord évoquer une inversion de positionnement des électrodes frontales (P alors négative en D1 aussi)."],"src":"p. 371-375, 383"},{"id":"231-sec-03","title":"ECG normal : valeurs de référence et lecture systématique","rank":"A","objectives":["231-obj-01"],"content":"### Étalonnage\n- Vitesse **25 mm/s** : 1 mm = **40 ms**, un grand carreau (5 mm) = **200 ms**. Amplitude : 1 mm = **0,1 mV**.\n\n### Valeurs normales\n| Paramètre | Normale |\n|---|---|\n| Fréquence cardiaque | 60–100 bpm |\n| Durée de P | < 120 ms (théorique < 110 ms) |\n| Axe de P | 60° (maximum en D2) |\n| Amplitude de P | < 2,5 mm en D2 |\n| PR (début P → début QRS) | 120–200 ms inclus |\n| Durée QRS | 70–110 ms |\n| Axe QRS | –30° à +90° |\n| Onde Q physiologique | < 1/3 du QRS et < 40 ms |\n| QT corrigé | < 450 ms à 60 bpm (en pratique 470–480 ms) |\n\n### Rythme sinusal\n- Le nœud sinusal est en haut à droite de l'OD : activation atriale de haut à droite vers bas à gauche → P **positive en D1 et en inférieur**.\n- Rythme sinusal = chaque P suivie d'un QRS **et** chaque QRS précédé d'une P. Des P sinusales régulières non conduites (BAV3) ne sont **plus** un rythme sinusal.\n- Le rythme peut naître de tout étage (atrial, jonctionnel, ventriculaire) ou être électroentraîné.\n- Bradycardie < 60 bpm, tachycardie > 100 bpm (valeurs de l'adulte, attention au nouveau-né). Bradycardie sinusale physiologique de l'athlète (tonus vagal) ; variation respiratoire chez le jeune.\n- FC = 60 / RR (s) ; en pratique FC = **300 / nombre de grands carreaux** entre deux QRS (1 carreau = 300, 2 = 150…).\n\n### Genèse du QRS [B]\nTrois phases : septale (avant, droite, haut → petite **q** latérale et petit **r** en V1), puis vers la jambe gauche et l'avant (grande **R** en V3-V4 et D2), puis vers le haut et l'arrière (petite **S** inférieure et latérale) : d'où le caractère polyphasique.\n\n### PR et QT\n- Le **PR** explore toute la conduction, de la sortie du nœud sinusal au réseau de Purkinje, pas seulement le NAV.\n- **QT** : du début de Q à la fin de T, mesuré dans la dérivation où T est la plus ample et la plus longue (souvent V2-V3), par la **tangente** à l'onde T. Ne jamais inclure une **onde U**.\n- **Bazett** : QTc = QT mesuré / √RR (RR en secondes) → une seule norme, celle de 60 bpm (RR = 1 s).\n\n### Affirmer qu'un ECG est normal : être systématique\n1. **Rythme** : sinusal (P + en D1, D2, un QRS après chaque P, une P avant chaque QRS), 60–100 bpm.\n2. **Conduction** : P < 120 ms, PR 120–200 ms, QRS fins 70–110 ms, axe –30° à +90° (positif en D1 et D2).\n3. **Repolarisation** : point J (fin du QRS) et ST isoélectriques ; T positives partout sauf **aVR et V1**, parfois **D3 et aVL** ; QT < 450 ms.\n4. **Morphologie** : amplitudes de P et QRS normales (**Sokolow < 35 mm**), transition normale de V1 à V6 (R croît, S décroît — vérifie aussi la bonne pose des électrodes), pas d'onde Q de nécrose (> 40 ms et > 1/3 du QRS).\n\n> Chez le jeune, surtout l'homme, un point J sus-décalé de V1 à V4 avec ST jonctionnel ascendant est une **repolarisation physiologique**.","keyPoints":["25 mm/s : 1 mm = 40 ms, grand carreau = 200 ms ; 1 mm = 0,1 mV.","FC 60–100, P < 120 ms, PR 120–200 ms, QRS 70–110 ms, axe –30/+90°, QTc < 450 ms.","Rythme sinusal : P positive en D1 et en inférieur, une P par QRS et un QRS par P.","FC = 300 / nombre de grands carreaux entre deux QRS.","QTc de Bazett = QT / √RR ; mesure par la tangente, en V2-V3, sans l'onde U.","Lecture systématique : rythme, conduction, repolarisation, morphologie.","T normalement négatives possibles en aVR, V1, parfois D3 et aVL."],"pitfalls":["Des P régulières sans conduction (BAV3) ne définissent pas un rythme sinusal.","Inclure l'onde U dans le QT le surestime.","Point J sus-décalé V1–V4 chez le jeune homme : repolarisation physiologique, pas un SCA."],"src":"p. 375-378"},{"id":"231-sec-04","title":"Blocs de branche, hémiblocs et blocs bifasciculaires","rank":"A","objectives":["231-obj-06","231-obj-07"],"content":"Un bloc de branche = interruption ou ralentissement marqué de la conduction dans une branche. **Toujours décrire d'abord le rythme atrial** : l'association TSV + bloc de branche n'est pas rare.\n\n### Blocs complets (QRS > 120 ms)\n| | BBD complet | BBG complet |\n|---|---|---|\n| V1 | QRS globalement **positif**, aspect **RsR'** | QRS globalement **négatif**, aspect **rS ou QS** |\n| V6 (et D1, aVL pour le BBG) | **qRs** avec S traînante, le plus souvent arrondie | **notch** (double pic : septum puis paroi latérale tardive), R souvent exclusive |\n\nOrdre de lecture : rythme sinusal ? → QRS > 120 ms ? → V1 positif (BBD probable) ou négatif (BBG probable) → aspect inverse en V6.\n\n### Discordance appropriée\nQRS larges → trouble de repolarisation secondaire : T **discordante** du QRS. QRS négatif → T positive avec petit sus-ST ; QRS positif → T négative avec petit sous-ST. Dans le BBG, le ST ascendant en V1-V2 peut mimer un SCA ST+.\n\n> Douleur thoracique persistante + BBG : évoquer l'**infarctus antérieur** et obtenir une évaluation cardiologique rapide **sans attendre la troponine** (sémiologie de la douleur, effet de la TNT, signes de choc, ETT).\n\n### Blocs incomplets et fonctionnels [B]\n- Incomplets : mêmes anomalies avec QRS **110–120 ms**, faible intérêt sémiologique.\n- Fonctionnel : bloc n'existant qu'à partir d'une fréquence donnée — apparition d'un BBG ou d'un BBD lors d'une **tachycardie** ou d'une **bradycardie**.\n\n### Hémiblocs (blocs fasciculaires)\n- QRS très modérément élargi (**> 110 ms**), pouvant dépasser 120 ms si autre bloc de branche associé ou cardiopathie marquée, + **déviation axiale**.\n- **HBAG** : axe au-delà de **–30°** (D2 négatif). **Fréquent** : branche fragile (superficielle et de petite taille).\n- **HBPG** : axe > **+90°** (D1 négatif, aspect S1Q3) en l'absence de pathologie du VD, de morphologie longiligne ou d'infarctus latéral. **Rare** : branche profonde.\n\n> D1 négatif : penser d'abord à une **inversion des électrodes** frontales (P alors négative en D1) avant l'HBPG.\n\n### Blocs bifasciculaires\nSémiologie additive : **HBAG + BBD** ou **HBPG + BBD**, QRS > 120 ms. [B] Le BBG complet est aussi considéré comme un bloc bifasciculaire.\n\n### Pourquoi diagnostiquer les blocs ?\n[B] Rang B.\n\n- Hémibloc isolé ou bloc incomplet : atteinte débutante, risque de BAV infrahissien faible.\n- Bloc bifasciculaire (BBG complet, ou BBD + hémibloc) : risque de BAV complet infrahissien intermittent (syncope, mort subite). **Syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie.**\n- BBG complet → **désynchronisation** du VG pouvant créer ou aggraver une cardiopathie ; sa correction est indiquée en cas d'apparition de signes d'insuffisance cardiaque.","keyPoints":["Bloc complet : QRS > 120 ms ; V1 positif (RsR') = BBD, V1 négatif (rS/QS, notch latéral) = BBG.","Discordance appropriée : avec un QRS large, T et ST s'inversent par rapport au QRS.","BBG + douleur thoracique persistante : suspecter un infarctus antérieur sans attendre la troponine.","Hémibloc = QRS > 110 ms + déviation axiale : HBAG < –30° (fréquent), HBPG > +90° (rare).","Bifasciculaire = HBAG ou HBPG + BBD (QRS > 120 ms) ; le BBG complet compte aussi comme bifasciculaire (B).","Syncope + bloc bifasciculaire = hospitalisation avec télémétrie (risque de BAV infrahissien) (B).","BBG complet : désynchronisation du VG pouvant aggraver une cardiopathie (correction si insuffisance cardiaque) (B)."],"pitfalls":["Décrire un bloc de branche sans avoir analysé le rythme atrial (TSV + bloc fréquents).","Prendre la discordance appropriée du BBG pour un sus-décalage ischémique.","Conclure à un HBPG devant un D1 négatif sans vérifier l'inversion des électrodes.","Les blocs de branche ne donnent pas de bradycardie."],"src":"p. 378-383"},{"id":"231-sec-05","title":"Blocs atrioventriculaires, dysfonction sinusale et bradycardie","rank":"A","objectives":["231-obj-08","231-obj-10","231-obj-11"],"content":"### Sémiologie des BAV (détail au chapitre 14)\nDans un BAV, les ondes P sont **régulières et à fréquence normale**.\n\n| Type | Aspect | Siège |\n|---|---|---|\n| BAV1 | PR **constant > 200 ms**, aucune P bloquée | – |\n| BAV2 Mobitz 1 (Luciani-Wenckebach) | PR s'allonge progressivement puis une P est bloquée | suprahissien |\n| BAV 2/1 | une P bloquée sur deux | infrahissien si QRS larges ; suprahissien si QRS fins et Mobitz 1 à d'autres moments |\n| BAV2 Mobitz 2 | PR constant puis P bloquée inopinée | infrahissien |\n| BAV3 | dissociation atrioventriculaire complète, P dissociées (bien vues en V1) | échappement à QRS fins = bloc nodal (suprahissien) |\n\n> Une onde P « bloquée » **plus précoce** que les autres peut être en fait une **extrasystole atriale bloquée** (exemple du Mobitz 1 du Collège).\n\n### Dysfonction sinusale\n- Cas simples : **asystole** (tracé plat, sans activité cardiaque).\n- [B] **Pauses** par absence intermittente d'une onde P = **bloc sinoatrial intermittent du 2e degré**, la pause correspondant au double de l'intervalle PP (RR) normal, avec absence complète de P-QRS-T (objectif 231-obj-11, rang B).\n- Dysfonction marquée : **échappement jonctionnel** ; P non visible devant le QRS, parfois **rétrograde** derrière lui (dans le ST), **négative en D2** (activation atriale de bas en haut).\n- Aspects pratiques : P trop lentes, P manquante, pause sinusale, P inexistante avec P' rétrograde.\n- Sur l'exemple de BSA du Collège, des T négatives dans toutes les précordiales sont pathologiques : la 1re étiologie à éliminer est l'**ischémie** myocardique.\n\n### Algorithme devant une bradycardie (FC des QRS < 50 bpm)\nSeules deux structures défaillantes donnent une bradycardie : le **nœud sinusal** (dysfonction sinusale) ou le **NAV** (BAV2 ou 3). Les blocs de branche ne donnent pas de bradycardie.\n1. **Regarder les ondes P.**\n2. P régulières à fréquence normale, ou activité atriale rapide (FA, flutter, TAF), avec **plus de P que de QRS** → le problème est le passage au ventricule → **BAV**.\n3. P **trop lentes ou absentes** → le problème est le nœud sinusal → **dysfonction sinusale**.","keyPoints":["BAV1 : PR > 200 ms constant. Mobitz 1 : PR croissant puis P bloquée (suprahissien). Mobitz 2 : PR fixe puis P bloquée (infrahissien).","BAV 2/1 : infrahissien si QRS larges, suprahissien si QRS fins avec Mobitz 1 ailleurs.","BAV3 : dissociation AV complète ; échappement à QRS fins = bloc nodal.","BSA du 2e degré : pause = 2 × PP, sans aucune onde P (B).","Échappement jonctionnel : pas de P avant le QRS, P' rétrograde négative en D2 possible.","Bradycardie : plus de P que de QRS = BAV ; P lentes ou absentes = dysfonction sinusale."],"pitfalls":["Dans le BAV les P restent régulières et à fréquence normale ; des P absentes orientent vers le nœud sinusal.","Une ESA bloquée peut simuler une onde P bloquée de BAV2."],"src":"p. 385-389"},{"id":"231-sec-06","title":"Tachycardies supraventriculaires : filtre du NAV, manœuvres vagales, tachycardie sinusale, FA","rank":"A","objectives":["231-obj-12","231-obj-13","231-obj-09","231-obj-16"],"content":"### Généralités\n- TSV = activation trop rapide des oreillettes ou de la jonction (NAV, His) ; au-delà de la bifurcation hissienne = trouble du rythme **ventriculaire**. Mécanismes : réentrée, hyperautomatisme, mécanismes complexes.\n- QRS **fins (< 120 ms)** le plus souvent ; larges si bloc de branche associé.\n- Sémantique : « trouble du rythme » = tachycardie ; les bradycardies sont des **troubles de la conduction**.\n\n### Filtre du NAV (conduction décrémentielle)\nAu-delà d'une certaine fréquence atriale, le ventricule ne suit plus en 1/1 : passage en 2/1, alternance 1/1-2/1 ou 2/1-3/1 (conduction variable) selon la fréquence atriale et l'intensité du filtre (âge, tonus vagal, ralentisseurs du NAV). Ce filtre est vital : sans lui, chaque passage en FA entraînerait une FV et tout flutter à 300 bpm donnerait une tachycardie à 300 bpm dans le ventricule.\n\n### Créer un BAV transitoire\n[B] Rang B.\n\n- **Manœuvres vagales** : Valsalva (expiration forcée à glotte fermée) ; compression carotidienne **unilatérale** (contre-indiquée si athérome important ou souffle carotidien) ; grand verre d'eau froide. La compression oculaire bilatérale n'est plus recommandée (décollement de rétine du myope).\n- **Adénosine IV** si échec : vagomimétique via les récepteurs purinergiques, en **flash IV**, effet d'une **dizaine de secondes**. Contre-indications : **asthme** (peut, rarement, provoquer un bronchospasme intense transitoire, même chez un non-asthmatique), **hypotension artérielle** (encadré p. 390, B), et FA sur voie accessoire (super-Wolff, p. 411, B). L'item 237 (p. 421, rang A) cite pour sa part : **asthme** et **HTA non contrôlée**.\n- Intérêt : diagnostic différentiel des tachycardies, réduction des tachycardies jonctionnelles.\n\n### Tachycardie sinusale vs TSV\n- P sinusales : positives en **D1, D2, D3 et aVF**.\n- FC **variable progressivement** (courbe de scope, télémétrie, holter, ou massage sinocarotidien) ; une TSV varie par **« marches d'escalier »**.\n- Contexte : au repos, une tachycardie marquée sans cause d'hypermétabolisme (fièvre, stress, douleur) n'est pas sinusale.\n\n### Fibrillation atriale\n- Activation atriale **anarchique** (état fibrillatoire). Tachycardie fréquente **100–200 bpm**, QRS **« irrégulièrement irréguliers »** (RR non multiples d'une valeur commune).\n- QRS fins sans bloc associé ; ligne de base : **mailles amples** ou **fine trémulation**. Manœuvres vagales si l'activité atriale est difficile à analyser.\n- [B] Formes difficiles :\n  - **FA + BAV complet** : rythme ventriculaire **lent et régulier** (échappement automatique) ;\n  - **maladie de l'oreillette** (maladie rythmique atriale, syndrome tachycardie-bradycardie) : alternance FA / bradycardie sinusale, **pauses de régularisation** à l'arrêt de la FA ;\n  - **FA + bloc de branche** (fréquent), préexistant ou fonctionnel : tachycardie **irrégulière à QRS larges**.","keyPoints":["TSV : QRS fins < 120 ms sauf bloc de branche associé.","Le NAV filtre (conduction décrémentielle) : 1/1, 2/1, conduction variable.","Manœuvres vagales (B) : Valsalva, compression carotidienne unilatérale, grand verre d'eau froide ; adénosine IV en flash si échec (effet d'une dizaine de secondes).","Adénosine contre-indiquée (B) : asthme, hypotension artérielle (p. 390), FA sur voie accessoire (p. 411) ; item 237 (p. 421, A) : asthme et HTA non contrôlée.","Tachycardie sinusale : P positives D1-D2-D3-aVF, fréquence variant progressivement, contexte.","FA : 100–200 bpm, RR irrégulièrement irréguliers, mailles ou trémulation.","FA lente et régulière = FA + BAV3 ; FA irrégulière à QRS larges = FA + bloc de branche (B)."],"pitfalls":["Une FA devenue régulière et lente signe un BAV complet associé (B).","Compression carotidienne interdite si souffle carotidien ou athérome important ; compression oculaire abandonnée (B)."],"src":"p. 389-393, 411"},{"id":"231-sec-07","title":"Flutters, tachycardies jonctionnelles et extrasystoles","rank":"A","objectives":["231-obj-14","231-obj-15","231-obj-17","231-obj-16"],"content":"### Flutters atriaux\n- Troubles du rythme **fréquents** : boucle d'activation atriale se répétant à l'identique autour d'un ou plusieurs obstacles anatomiques ou fonctionnels (modèle de la **réentrée**), activation « organisée » ≠ FA « fibrillatoire ». Flutters **droits beaucoup plus fréquents que gauches** (zones propices dans l'OD même sans cardiopathie ; flutters gauches le plus souvent après remodelage de l'OG par une cardiopathie ou après une intervention). Facteurs prédisposants communs à la FA.\n- ECG : activité atriale **monomorphe**, ≈ **300 bpm (240–340)**, **sans retour à la ligne isoélectrique** dans au moins une dérivation ; ondes **F** en toit d'usine / dents de scie, parfois démasquées par manœuvre vagale.\n- **Flutter typique (commun) antihoraire**, le plus fréquent : circuit de l'OD par l'**isthme cavotricuspide** (entre tricuspide et veine cave inférieure) ; 300 bpm (plus lent si dilatation) ; F **négatives en D2, D3, aVF, positives en V1, négatives en V6**. Typique horaire : polarités inversées.\n- **Flutters atypiques** : isthme non impliqué, droits, gauches ou biatriaux, **120–320 bpm**, F variables. Parler de flutter « d'aspect » typique/atypique ; diagnostic formel par la fréquence ou l'exploration électrophysiologique avant ablation par radiofréquence.\n- Ventricule : classiquement **150 bpm (2/1)**, ou 100 (3/1), 75… ; régulier le plus souvent, sinon **conduction variable** ; la manœuvre vagale ralentit et démasque les F (utile en 1/1 ou 2/1).\n\n### Manœuvres vagales et tachycardies atriales\nSur l'algorithme devant une tachycardie, manœuvres vagales ou adénosine ralentissent le passage au ventricule et **démasquent l'activité atriale** d'une tachycardie atriale (sinusale, flutter, TAF), ce qui fait le diagnostic.\n\n### Tachycardies jonctionnelles (maladie de Bouveret)\nFréquentes, **très régulières**, souvent rapides ≈ **200 bpm** (130 à 260 bpm selon le mécanisme et le tonus sympathique). Deux formes :\n- **réentrée intranodale** : mécanisme de réentrée dans le NAV ; activité atriale invisible ou devinée dans le ST (activation atriale et ventriculaire quasi synchrone) ;\n- **rythme réciproque** : réentrée par une **voie accessoire** (faisceau de Kent).\n- [B] Réduites par les manœuvres vagales ou l'adénosine IV.\n\n### Extrasystoles\nActivation prématurée d'une cavité. Fréquentes, observées de façon physiologique sur cœur sain ; charge/24 h croissant avec l'âge et la cardiopathie ; **fréquentes ou polymorphes → rechercher une cardiopathie**.\n- **Atriale** : P précoce de morphologie différente puis QRS fin ; P parfois cachée dans la T précédente (dont elle modifie la polarité).\n- **Jonctionnelle** : QRS fin ± P' rétrograde ; rare, traduit le plus souvent une pathologie de la jonction nodohissienne.\n- **Ventriculaire** : QRS large ± P' rétrograde (trouble du rythme ventriculaire).\n- Répétitives : doublets, triplets, salves. Rythmées : **bigéminisme** (1 battement sur 2), **trigéminisme** (1 sur 3).","keyPoints":["Flutter : ondes F monomorphes ≈ 300 bpm sans retour à la ligne isoélectrique ; ventricule à 150 (2/1) le plus souvent.","Flutter typique antihoraire : isthme cavotricuspide, F négatives en D2-D3-aVF, positives en V1, négatives en V6.","Tachycardie atriale (sinusale, flutter, TAF) : la manœuvre vagale ralentit le passage au ventricule et démasque l'activité atriale.","Tachycardie jonctionnelle : très régulière ≈ 200 bpm ; réentrée intranodale (P invisible ou devinée dans le ST) ou par voie accessoire (faisceau de Kent).","Manœuvres vagales et adénosine IV réduisent les tachycardies jonctionnelles (retour en rythme sinusal) (B).","ESA : P précoce différente + QRS fin ; ESV : QRS large ; bigéminisme = 1 sur 2."],"pitfalls":["Flutter 2/1 à 150 bpm : QRS serrés masquant les F → manœuvre vagale.","L'aspect ECG typique/atypique du flutter n'est pas parfaitement fiable.","Une ESA peut se cacher dans l'onde T précédente."],"src":"p. 393-398"},{"id":"231-sec-08","title":"Troubles du rythme ventriculaire et algorithme devant une tachycardie","rank":"A","objectives":["231-obj-18","231-obj-19","231-obj-20","231-obj-02"],"content":"> Objectif prioritaire : mort subite et syncopes. Ces tachycardies naissent **sous la bifurcation hissienne**, court-circuitent les voies de conduction → conduction lente de proche en proche → **QRS large**.\n\n### Tachycardie ventriculaire\n- Mécanismes : **réentrée** (le plus fréquent sur cardiopathie : réentrée autour d'une zone de fibrose secondaire à une nécrose d'infarctus ou à une cardiopathie) ; **automatisme anormal** (le plus fréquent sur cœur sain).\n- **Toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire.** État instable prémonitoire de l'arrêt cardiaque (> la moitié des morts subites) : TV → FV → asystolie.\n- Suspicion : **FC > 100 bpm + QRS > 120 ms sur ≥ 3 battements consécutifs** → alerte (15, préparer la réanimation).\n- **TV non soutenue** : 3 battements à 30 s ; **soutenue** : > 30 s. Préciser **monomorphe** / **polymorphe**.\n- **Certitude** : **dissociation ventriculoatriale** (plus de QRS que de P ⇒ origine ventriculaire ; ≠ dissociation AV du BAV3) ; complexes de **capture** (QRS fin précédé d'une P) et de **fusion** (QRS intermédiaire), possibles seulement s'il y a dissociation.\n- **En faveur** : cardiopathie sous-jacente +++ ; **concordance** positive ou négative de V1 à V6 ; **axe extrême** (QRS positif en aVR, ce qui ne se voit ni dans un BBD ni dans un BBG) ; QRS larges d'aspect atypique de bloc de branche.\n\n### Fibrillation ventriculaire\n**Urgence absolue** : choc électrique immédiat avant tout autre geste, massage cardiaque en attendant. Perte de connaissance en quelques secondes (débit nul), pouls carotidien aboli = arrêt cardiaque. ECG : tachycardie **irrégulière à QRS larges polymorphes**.\n\n### Torsades de pointes\n[B] Rang B.\n\n- TV **polymorphe** s'arrêtant spontanément ou dégénérant en FV ; installée, elle est indiscernable d'une FV → diagnostic sur le **QT long préalable** et le contexte (FV surtout sur ischémie ou cardiopathie évoluée).\n- [A] Causes de QT long (objectif 231-obj-22 [A] : médicamenteuse, congénitale, ionique) : **bradycardie extrême** (échappements des BAV bas situés, intoxication aux bradycardisants), **hypokaliémie**, **hypocalcémie**, **hypomagnésémie**, **association de médicaments allongeant le QT** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…), **QT long congénital**.\n- Tout QT allongé doit alerter → vérifier les médicaments et le ionogramme pour corriger l'allongement du QT et éviter une mort subite. Prise en charge : corriger les troubles ioniques, **accélérer la fréquence cardiaque**, arrêter les médicaments allongeant le QT.\n- Torsade possible à QT normal, déclenchée par deux ESV dont la 2e tombe sur la T de la 1re.\n\n### Algorithme devant une tachycardie (FC > 100 bpm)\n1. **Irrégulière** → **FA** (diagnostic différentiel : ESA).\n2. **Régulière à QRS larges** → ventriculaire jusqu'à preuve du contraire (ou TSV + bloc de branche).\n3. **Régulière à QRS fins** → supraventriculaire.\n- **Mauvaise tolérance hémodynamique → cardioversion électrique externe.**\n- Bonne tolérance → manœuvres vagales ± adénosine si échec (BAV transitoire), utiles dès que le diagnostic n'est pas évident :\n  - **démasque l'activité atriale** → sinusale, flutter, TAF ;\n  - **arrête la tachycardie** → jonctionnelle (réentrée dépendante du NAV) ;\n  - **aucun effet** → TV (ne dépend pas du NAV) ; certitude si dissociation AV (plus de QRS que d'ondes P).","keyPoints":["Tachycardie régulière à QRS larges = TV jusqu'à preuve du contraire.","TV : FC > 100, QRS > 120 ms, ≥ 3 battements ; non soutenue ≤ 30 s, soutenue > 30 s.","Certitude de TV : dissociation VA (plus de QRS que de P), captures, fusions.","En faveur de TV : cardiopathie, concordance V1–V6, aVR positif, aspect atypique de bloc.","FV = choc électrique immédiat, massage cardiaque en attendant.","Torsade (B) = TV polymorphe sur QT long ; causes du QT long (A) : ions (K, Ca, Mg), bradycardie extrême, médicaments, congénital ; traitement (B) : corriger les ions, accélérer la FC, arrêter les médicaments.","Tachycardie mal tolérée = cardioversion électrique ; bien tolérée = manœuvres vagales ± adénosine."],"pitfalls":["Confondre bloc de branche (sans conséquence immédiate) et TV (mortelle si non prise en charge) devant un QRS large.","Confondre dissociation ventriculoatriale de la TV et dissociation AV du BAV3.","Torsade installée = aspect de FV : chercher le QT long sur les tracés antérieurs (B)."],"src":"p. 398-405"},{"id":"231-sec-09","title":"Hypertrophies atriales et ventriculaires","rank":"A","objectives":["231-obj-03","231-obj-04","231-obj-05"],"content":"« Hypertrophie » (terme historique) = augmentation de la quantité de myocytes d'une cavité, par **dilatation** et/ou **épaississement** ; parfois corrélée au degré de fibrose.\n\n### Hypertrophies atriales\n[B] Rang B.\n\n| | Onde P |\n|---|---|\n| **HAD** (le plus souvent par dilatation) | amplitude **> 2,5 mm en D2** (souvent pointue) ou **> 2 mm en V1-V2** |\n| **HAG** | durée **> 110 ms** (120 ms en pratique), composante **négative > 40 ms en V1** |\n\n### Hypertrophie ventriculaire gauche\n- Dilatation ou épaississement du VG (volume myocardique augmenté).\n- **Indice de Sokolow** = S (V1 ou V2) + R (V5 ou V6) ; normal **< 35 mm**.\n- **Forme sévère** (historiquement « surcharge systolique ») : T **négative** ± **sous-ST** dans les latérales (D1, aVL, V5, V6) par anomalie secondaire de repolarisation, et **disparition de la q septale** dans ces dérivations. Forme modérée dite « diastolique » (termes sans valeur mécanistique).\n- Déviation axiale gauche modeste ; QRS pouvant être un peu élargis (masse myocardique, fibrose) mais restant souvent **< 120 ms**.\n- Étiologie la plus fréquente : **HTA**, puis **rétrécissement aortique**.\n\n> Pièges : aspect **QS en V1-V2** (pseudonécrose) et **pseudo sus-décalage du ST** en V1-V2 mimant une séquelle d'infarctus ou un SCA.\n\n### Hypertrophie ventriculaire droite\n[B] Rang B.\n\n- Intérêt modeste à l'ère de l'échographie ; utile chez les patients **BPCO** ou à atteinte pulmonaire sévère.\n- Signe le plus précoce : **axe > 110°** (90° en pratique). Autres : **R > 6 mm en V1**, **S > 7 mm en V5-V6**, association fréquente à une **HAD** et à un **microvoltage** (BPCO) ; BBD souvent associé.\n- T négative asymétrique en V1 (parfois V2-V3) dans les formes sévères : ne pas confondre avec une ischémie.\n- Même aspect possible dans l'**HBPG** ou comme variante du sujet **longiligne**.\n- **Embolie pulmonaire** : une hypertrophie aiguë peut donner un aspect **S1Q3T3** (S en D1, Q en D3, T négative en D3) ; l'ECG d'EP du Collège montre aussi une déviation axiale droite et une FA.","keyPoints":["HAD : P > 2,5 mm en D2 ou > 2 mm en V1-V2 ; HAG : P > 120 ms avec négativité > 40 ms en V1 (B).","Sokolow = S V1/V2 + R V5/V6 ; normal < 35 mm.","HVG sévère : T négatives et sous-ST latéraux, disparition de la q septale.","HVG : étiologie la plus fréquente HTA, puis rétrécissement aortique ; QRS restant souvent < 120 ms.","HVD : axe > 110° (90° en pratique), R V1 > 6 mm, S V5-V6 > 7 mm, HAD, microvoltage, BBD (B).","Embolie pulmonaire : S1Q3T3 (B)."],"pitfalls":["HVG importante : QS et sus-ST en V1-V2 = pseudonécrose, pas un infarctus.","T négatives asymétriques V1-V3 de l'HVD : pas forcément une ischémie (B).","HBPG et sujet longiligne miment l'HVD (B)."],"src":"p. 406-408"},{"id":"231-sec-10","title":"Dyskaliémies, QT long, péricardite aiguë et préexcitation","rank":"A","objectives":["231-obj-21","231-obj-22","231-obj-23","231-obj-25"],"content":"### Dyskaliémies\n| | Hypokaliémie | Hyperkaliémie |\n|---|---|---|\n| Onde T | **plate ou négative**, diffuse, avec **sous-ST** | **ample, pointue, symétrique** (géante) |\n| PR | – | **allongé** |\n| QRS | normal | **élargi** |\n| QT / U | **QT allongé**, apparition d'une **onde U** (exclue du QT) | – |\n| Rythme | ESV, TV, **torsade de pointes**, FV | **BAV**, TV, **dysfonction sinusale** (échappement jonctionnel) |\n\n### Allongement du QT\nCauses du QT long (objectif 231-obj-22 [A]) : **médicamenteuses** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…), **ioniques** (hypoK, hypoCa, hypoMg), **bradycardie extrême**, **congénitale** (syndrome du QT long).\n\n[B] Un QT long expose à la torsade de pointes. Conduite : vérifier les médicaments et le ionogramme pour corriger l'allongement du QT (prévenir la mort subite).\n\n### Péricardite aiguë : 4 phases\n[B] Évolution classique :\n1. Phase 1, brève : **microvoltage** (d'autant plus important que la péricardite est liquidienne), **sus-ST concave vers le haut, diffus, concordant, sans miroir**, **sous-décalage de PQ (PR)**.\n2. T plates partout, ST isoélectrique.\n3. T **négatives** persistantes.\n4. Retour progressif à la normale.\n\n> Ne pas conclure à une péricardite devant un SCA ST+ dont le miroir manque.\n\n### Préexcitation et Wolff-Parkinson-White\n[B] Rang B.\n\n- Physiologiquement le NAV est l'unique passage AV. Une **voie accessoire (faisceau de Kent)** = fibre musculaire ectopique atrioventriculaire en compétition avec le NAV ; une voie accessoire typique peut conduire dans les deux sens.\n- Si elle conduit vite en antérograde : **préexcitation** — **PR court < 120 ms**, **élargissement du QRS par empâtement de son pied = onde delta** (zone préexcitée), **anomalies de repolarisation** souvent associées dans le territoire de la voie.\n- Bloquer le NAV (massage, adénosine) force le passage par la voie accessoire et démasque une préexcitation minime — **jamais en cas de FA**.\n- **Syndrome de WPW** = voie accessoire antérograde + palpitations par tachycardie jonctionnelle.\n- **Risque de mort subite** si période réfractaire courte : la voie n'a pas de propriété décrémentielle ; en FA, tachycardie **irrégulière, très rapide, à QRS de largeur variable « en accordéon »** (super-Wolff), pouvant dégénérer en FV. Le Collège en fait une contre-indication de l'adénosine (avec l'asthme, p. 411) ; l'encadré p. 390 cite aussi l'hypotension artérielle, l'item 237 (p. 421, A) l'asthme et l'HTA non contrôlée.","keyPoints":["HypoK : T plates/négatives + sous-ST, QT long, onde U, risque de torsade.","HyperK : T amples pointues symétriques, PR long, QRS large, BAV, dysfonction sinusale.","QT long : causes (A) médicaments, hypoK/hypoCa/hypoMg, bradycardie extrême, congénital ; conduite (B) : vérifier ionogramme et traitements.","Péricardite (B) : sus-ST diffus concave sans miroir + sous-PQ + microvoltage, puis T plates, T négatives, normalisation.","Préexcitation (B) : PR < 120 ms, onde delta, repolarisation anormale.","FA + voie accessoire = tachycardie irrégulière à QRS larges variables : pas d'adénosine (B)."],"pitfalls":["Inclure l'onde U de l'hypokaliémie dans la mesure du QT.","Un SCA ST+ peut être sans miroir visible : ne pas l'étiqueter péricardite (B).","Manœuvre vagale ou adénosine chez un patient préexcité en FA (B)."],"src":"p. 408-411"},{"id":"231-sec-11","title":"Maladie coronarienne et syndromes coronariens aigus","rank":"A","objectives":["231-obj-24","231-obj-02"],"content":"### Analyse de la repolarisation\n- La polarité des T suit celle des QRS ; T positives partout sauf **aVR**, parfois **V1, aVL ou D3** selon l'orientation du cœur.\n- **Deux T négatives dans un même territoire = pathologique** (ex. D2 et D3 → territoire inférieur).\n\n### SCA avec sus-décalage de ST\n- **Traquer le sus-décalage** (il indique le territoire de la coronaire occluse), **puis** chercher le **miroir** (sous-décalage), pas l'inverse.\n- Un sous-ST en V1-V3 peut être le miroir d'un sus-ST **postérieur (V7-V9)** → **ECG 18 dérivations** devant toute douleur thoracique.\n- Sus-ST significatif : **≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes**. S'il englobe la T : **onde de Pardee**.\n- **BBG complet + douleur thoracique aiguë** → éliminer un SCA ST+ (échographie ± coronarographie).\n- Évolution : régression rapide si reperfusion ; plusieurs jours sans reperfusion ; persistance indéfinie si **anévrisme** de la paroi infarcie. Après 48 h, **T négative « ischémique »**, parfois très prolongée.\n\n### Cinq étiologies de sus-décalage du ST\n[B] Encadré de rang B.\n\n1. **SCA ST+** (Pardee avec miroir).\n2. **Anévrisme ventriculaire** (persistance après un infarctus à séquelle marquée).\n3. **Repolarisation précoce** (dérivations inférolatérales).\n4. **Angor de Prinzmetal** (spasme coronarien).\n5. **Péricardite** (diffus, concave vers le haut, sans miroir).\n\n[B] Diagnostics différentiels : **BBG ou stimulation ventriculaire** par pacemaker (sus-ST approprié dans les dérivations à QRS négatif) ; **HVG marquée** (sous-décalage dans les latérales et sus-décalage en V1-V2).\n\n### Ondes Q de nécrose\n- Apparaissent en principe vers la **6e heure**, parfois plus tôt au cours du SCA ST+ ; elles ne doivent pas faire considérer à tort qu'une reperfusion serait inutile car trop tardive.\n- Critères : **≥ 1/3 (ou 1/4) de l'amplitude du QRS** et **> 30–40 ms**. Équivalent : **rabotage (écrêtement) de l'onde R**, surtout décrit en V2-V3-V4.\n\n### SCA sans sus-décalage de ST\nPossibles : **sous-ST** (lésion sous-endocardique), **inversion des T** (ischémie sous-épicardique), **pseudo-normalisation** de T auparavant négatives, **aplatissement** des T, ou **ECG normal**. Un pacemaker peut masquer ces anomalies.","keyPoints":["Deux T négatives dans un même territoire signent une pathologie.","Sus-ST significatif : ≥ 2 mm V1-V3, ≥ 1 mm ailleurs, ≥ 2 dérivations adjacentes ; miroir cherché ensuite.","Sous-ST V1-V3 = possible miroir postérieur → ECG 18 dérivations.","Cinq causes de sus-ST (B) : SCA, anévrisme, repolarisation précoce, Prinzmetal, péricardite.","Onde Q de nécrose : ≥ 1/3 du QRS, > 30–40 ms, vers la 6e heure ; équivalent = rabotage de R surtout en V2-V3-V4.","SCA non ST+ : sous-ST, T inversées, pseudo-normalisation, T plates ou ECG normal."],"pitfalls":["Confondre la lésion et son miroir.","Prendre un élargissement du QRS (BBG, stimulation) pour une onde de Pardee.","Étiqueter péricardite un SCA ST+ dont le miroir est absent (B).","Des ondes Q ne rendent pas la reperfusion inutile."],"src":"p. 411-412, 415"},{"id":"231-sec-12","title":"ECG et stimulateur cardiaque, prothèses rythmiques","rank":"B","objectives":["231-obj-26"],"content":"### Indications du pacemaker\n- **Bradycardies symptomatiques** : dysfonction sinusale, BAV2 Mobitz 1, bradycardie sinusale.\n- **BAV infrahissiens** (BAV2 Mobitz 2, BAV3) : **même sans symptôme**.\n\n### Les prothèses cardiaques\n| Problème | Prothèse |\n|---|---|\n| Bradycardie | **pacemaker** (stimulation locale de quelques myocytes puis conduction de proche en proche) |\n| TV / FV | **défibrillateur** (champ électrique réinitialisant tous les myocytes) ; fait toujours pacemaker, sauf sous-cutané |\n| BBG désynchronisant le VG avec insuffisance cardiaque | **resynchronisation cardiaque** (stimulateur, donc toujours pacemaker) |\n\nLes trois fonctions peuvent être associées : défibrillateur de resynchronisation.\n\n### Reconnaître l'électroentraînement\n- **Spike** de stimulation : impulsion de **0,4 à 1 ms**, plus courte que tout phénomène physiologique → **pathognomonique** d'une stimulation (pacemaker ou sonde d'entraînement électrosystolique).\n- **Unipolaire** (bout de sonde ↔ boîtier) : spike bien visible ; **bipolaire** (bout de sonde ↔ électrode proche) : spike peu visible.\n- **Dysfonction sinusale** → stimulation atriale : une **onde P suit le spike**.\n- **BAV** → le pacemaker écoute l'oreillette et stimule le ventricule après un **délai AV programmé** (synchronisation AV) : **QRS large d'aspect BBG** après le spike (stimulation du VD transmise de proche en proche).\n- Les anomalies ischémiques peuvent être masquées par un pacemaker.","keyPoints":["Pacemaker : bradycardies symptomatiques (DS, Mobitz 1, bradycardie sinusale) ; BAV infrahissien (Mobitz 2, BAV3) même asymptomatique.","Spike de 0,4–1 ms = pathognomonique d'une stimulation.","Stimulation atriale : P après le spike ; stimulation ventriculaire : QRS large type BBG après le spike.","Unipolaire = spike bien visible ; bipolaire = peu visible.","Défibrillateur et resynchronisation assurent aussi la fonction pacemaker (sauf défibrillateur sous-cutané)."],"pitfalls":["Un pacemaker masque les anomalies de repolarisation d'un SCA.","Le spike bipolaire peut passer inaperçu sur l'ECG de surface."],"src":"p. 412-414"},{"id":"231-sec-13","title":"Indications de l'ECG : monitorage, ECG 12 dérivations, Holter","rank":"A","objectives":["231-obj-27","231-obj-28"],"content":"### En urgence (objectifs de rang A)\nConnaître les principales indications de l'ECG en urgence : **défaillance(s) d'organe(s)**, **douleur thoracique**, **palpitations**, **syncope**, **troubles hydroélectrolytiques (K, Ca)** ; savoir réaliser un ECG 12 dérivations.\n\n### Monitorage ECG (cardioscope)\n- Toute **urgence**, réanimation et **transfert médicalisé**.\n- Surveillance en **soins intensifs cardiologiques** pour pathologie aiguë (ex. syndrome coronarien).\n- **Syncope** avec cause rythmique suspectée.\n- **Peropératoire** et salle de réveil postanesthésique.\n- Certains exercices de **réadaptation cardiaque**.\n\n### ECG conventionnel 12 dérivations ou plus\n- Systématique dans les centres de santé (bilans de santé).\n- **Aptitude** professionnelle (conducteurs, pilotes) ou sportive (sports à risque, compétition, professionnels).\n- **Bilan préopératoire** : patients **> 65 ans**, patients à risque, interventions à risque.\n- **Enquêtes familiales** de certaines cardiopathies héréditaires.\n- **Symptômes** : palpitations, douleur thoracique, dyspnée aiguë ou chronique, malaise, perte de connaissance, syncope.\n- **Obligatoire dans le bilan de l'HTA**.\n- Bilan initial et surveillance des pathologies cardiaques, ou non cardiaques à risque de complications cardiovasculaires (diabète, AVC).\n- Rappel : ECG **18 dérivations** (V7-V9, V3R-V4R) devant une douleur thoracique.\n\n### Méthode Holter\n[B] Rang B.\n\n- ECG de longue durée, **2 à 12 dérivations** simultanées, **24 à 96 h maximum**, support numérique, analyse en différé (centre de lecture).\n- Indications : malaises, syncopes, pertes de connaissance ou palpitations **épisodiques** quand l'ECG standard n'a rien montré et que les symptômes ont une probabilité de récidiver pendant l'enregistrement.\n- Symptômes rares : ECG ambulatoire de très longue durée (**jusqu'à 21 jours**) ou **enregistreurs d'événements** (outils dédiés, montres connectées ECG).\n- **Holter implantable** (moniteur ECG implantable sous-cutané) : suivi **jusqu'à 3 ans** ; diagnostic étiologique des syncopes inexpliquées ou d'une FA silencieuse.\n- Holter de 24 h aussi pour : efficacité des **bradycardisants**, surveillance et réglage des **pacemakers**, évaluation du **risque rythmique** (salves de TV asymptomatiques après infarctus ou dans les cardiomyopathies).","keyPoints":["Scope : urgences/réa/transferts, USIC, syncope rythmique suspectée, bloc opératoire et réveil, réadaptation.","ECG 12 dérivations : bilans de santé, aptitude, préop > 65 ans ou à risque, enquêtes familiales, symptômes, HTA (obligatoire), suivi des cardiopathies, diabète, AVC.","Holter : 2–12 dérivations, 24–96 h, si symptômes épisodiques probables pendant l'enregistrement (B).","Symptômes rares : enregistrement jusqu'à 21 jours, enregistreurs d'événements ; implantable jusqu'à 3 ans (B).","Holter 24 h : bradycardisants, réglage de pacemaker, TV asymptomatiques post-infarctus (B)."],"pitfalls":["Holter de 24 h inutile si les symptômes sont trop rares pour survenir pendant l'enregistrement (B)."],"src":"p. 367-368, 411, 414-415"},{"id":"231-sec-14","title":"Prise en charge complète par situation","rank":"A","objectives":["231-obj-02","231-obj-27","231-obj-12","231-obj-18","231-obj-19","231-obj-21","231-obj-22","231-obj-24"],"content":"Synthèse de ce que le chapitre ECG du Collège dit de la conduite à tenir, situation par situation. Les traitements de fond de chaque maladie sont dans leur item (SCA : item 339 ; FA : 232 ; troubles de conduction : 236 ; palpitations : 237 ; malaise : 342).\n\n### 1. Douleur thoracique : suspicion de SCA\n1. **ECG en urgence**, **18 dérivations** (V7-V9, V3R-V4R) devant toute douleur thoracique.\n2. **Traquer le sus-décalage du ST** (territoire de l'artère occluse), puis chercher le **miroir** : significatif si **≥ 2 mm de V1 à V3** et **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes** ; s'il englobe l'onde T = onde de Pardee.\n3. **Sous-décalage en V1-V3** : possible miroir d'un sus-décalage **postérieur (V7-V9)**.\n4. **BBG complet + douleur thoracique aiguë** : éliminer un SCA ST+ (échographie ± coronarographie) ; évaluation cardiologique rapide **sans attendre la troponine** (sémiologie de la douleur dont l'effet de la TNT, signes de choc, ETT).\n5. Des **ondes Q** (vers la 6e heure) ne rendent **pas** la reperfusion inutile.\n6. **SCA sans sus-décalage** : sous-ST, T inversées, pseudo-normalisation, T plates, ou **ECG normal** ; anomalies parfois masquées par un pacemaker.\n7. Ne pas conclure à une **péricardite** devant un SCA ST+ dont le miroir manque.\n8. **Surveillance** : monitorage ECG en soins intensifs cardiologiques ; le sus-ST régresse vite si reperfusion, dure plusieurs jours sinon, persiste si anévrisme ; T négative « ischémique » après 48 h.\n\n### 2. Tachycardie (FC > 100 bpm)\n1. **Monitorage ECG** (urgence) ; évaluer la **tolérance hémodynamique** : mauvaise tolérance → **cardioversion électrique externe**.\n2. Analyser **régularité** et **largeur des QRS** :\n   - **irrégulière** → **FA** (diagnostic différentiel : ESA) ; irrégulière à QRS larges → FA + bloc de branche [B] ; FA lente et régulière → FA + BAV complet [B] ;\n   - **régulière à QRS larges** → **TV jusqu'à preuve du contraire** (ou TSV + bloc de branche) : **alerte (15)**, se préparer à une réanimation ;\n   - **régulière à QRS fins** → supraventriculaire.\n3. Bonne tolérance et diagnostic non évident → **manœuvres vagales**, puis **adénosine IV** si échec : elles bloquent transitoirement le NAV et donnent le diagnostic dans la majorité des cas (fig. 15.51, A). [B] Modalités : Valsalva ; compression carotidienne **unilatérale**, contre-indiquée si athérome important ou souffle carotidien ; grand verre d'eau froide ; plus de compression oculaire ; adénosine **en flash**, effet d'une dizaine de secondes, contre-indiquée si **asthme**, **hypotension artérielle** (p. 390) ou **FA sur voie accessoire** (p. 411). L'item 237 (p. 421, A) cite : asthme et **HTA non contrôlée**.\n4. Réponse : **démasque l'activité atriale** → sinusale, flutter, TAF ; **arrête** → tachycardie jonctionnelle [B : réduite par manœuvres vagales ou adénosine IV] ; **aucun effet** → TV (certitude : plus de QRS que d'ondes P, captures, fusions).\n5. **FA préexcitée** (tachycardie irrégulière, très rapide, QRS larges « en accordéon ») [B] : **ne pas bloquer le NAV** (ni massage, ni adénosine) ; risque de dégénérescence en FV.\n\n### 3. Fibrillation ventriculaire (arrêt cardiaque)\n1. Tachycardie irrégulière à QRS larges polymorphes, perte de connaissance en quelques secondes, pouls carotidien aboli.\n2. **Choc électrique immédiat avant tout autre geste**, **massage cardiaque en attendant** le choc.\n\n### 4. QT long et torsades de pointes [B]\n1. Tout **QT allongé** doit alerter : vérifier les **médicaments** et le **ionogramme**.\n2. Causes (rang A, objectif 231-obj-22) : bradycardie extrême, hypokaliémie, hypocalcémie, hypomagnésémie, association de médicaments allongeant le QT, QT long congénital.\n3. Prise en charge : **corriger les troubles ioniques**, **accélérer la fréquence cardiaque**, **arrêter les médicaments** allongeant le QT.\n\n### 5. Bradycardie (FC des QRS < 50 bpm)\n1. **Regarder les ondes P** : plus de P que de QRS (P normales, ou FA/flutter/TAF) → **BAV** ; P trop lentes ou absentes → **dysfonction sinusale**.\n2. Préciser le type de BAV : Mobitz 1 suprahissien ; Mobitz 2 infrahissien ; 2/1 infrahissien si QRS larges ; BAV3 avec échappement à QRS fins = bloc nodal.\n3. Penser à l'**hyperkaliémie**, qui peut donner un BAV ou une dysfonction sinusale (avec T amples pointues symétriques, PR long, QRS large).\n4. **Pacemaker** [B] : bradycardies **symptomatiques** (dysfonction sinusale, BAV2 Mobitz 1, bradycardie sinusale) ; **BAV infrahissiens** (Mobitz 2, BAV3) **même sans symptôme**.\n\n### 6. Syncope, malaise, palpitations épisodiques\n1. **ECG 12 dérivations** ; **monitorage** si cause rythmique suspectée.\n2. **Syncope + bloc bifasciculaire** [B] : **hospitalisation en cardiologie avec télémétrie** (risque de BAV complet infrahissien).\n3. ECG non contributif [B] : **Holter** 24 à 96 h si les symptômes ont une probabilité de se répéter pendant l'enregistrement ; symptômes rares : ECG ambulatoire jusqu'à **21 jours** ou enregistreurs d'événements ; **holter implantable** jusqu'à **3 ans** (syncope inexpliquée, FA silencieuse).\n\n### 7. Dyskaliémie\n1. ECG en urgence devant un trouble hydroélectrolytique (K, Ca).\n2. **Hypokaliémie** : T plates ou négatives, sous-ST, QT long, onde U (hors mesure du QT) ; risque d'ESV, TV, **torsade de pointes**, FV.\n3. **Hyperkaliémie** : T amples, pointues, symétriques ; PR long ; QRS large ; BAV, TV, dysfonction sinusale.","keyPoints":["Douleur thoracique : ECG 18 dérivations, sus-ST puis miroir ; BBG + douleur = avis cardiologique sans attendre la troponine.","Tachycardie mal tolérée = cardioversion électrique ; bien tolérée = manœuvres vagales ± adénosine.","Tachycardie régulière à QRS larges = TV jusqu'à preuve du contraire : alerte (15), préparer la réanimation.","FV : choc immédiat, massage en attendant.","QT long (B) : médicaments + ionogramme ; corriger les ions, accélérer la FC, arrêter les médicaments.","Bradycardie : regarder les P ; pacemaker (B) si bradycardie symptomatique ou BAV infrahissien même asymptomatique."],"pitfalls":["Adénosine ou massage chez un patient en FA préexcitée (B).","Attendre la troponine devant une douleur thoracique avec BBG.","Conclure à une péricardite parce que le miroir manque."],"src":"p. 368, 381, 383, 389-390, 392-393, 397-399, 402-405, 408, 410-412, 414-415"}],"essentials":[{"id":"231-ess-01","rank":"A","text":"À 25 mm/s, un petit carreau (1 mm) vaut 40 ms et un grand carreau (5 mm) vaut 200 ms ; 1 mm d'amplitude vaut 0,1 mV.","src":"p. 375","q":"À 25 mm/s, quelle durée représentent un petit et un grand carreau, et quelle amplitude vaut 1 mm ?"},{"id":"231-ess-02","rank":"A","text":"Le rythme sinusal se définit par une onde P positive en D1 et dans les dérivations inférieures, suivie d'un QRS, chaque QRS étant précédé d'une P.","src":"p. 376","q":"Comment définit-on le rythme sinusal à l'ECG ?"},{"id":"231-ess-03","rank":"A","text":"L'axe normal du QRS va de –30° à +90° : D1 et aVF positifs suffisent à l'affirmer entre 0 et 90°.","src":"p. 375","q":"Quelles sont les bornes de l'axe normal du QRS et comment l'affirmer avec D1 et aVF ?"},{"id":"231-ess-04","rank":"A","text":"Le QTc de Bazett se calcule en divisant le QT mesuré par la racine carrée de l'intervalle RR en secondes, sans inclure l'onde U.","src":"p. 377","q":"Comment calcule-t-on le QTc de Bazett, et que ne faut-il pas inclure ?"},{"id":"231-ess-05","rank":"A","text":"Les ondes T sont normalement positives partout sauf en aVR et V1, parfois en D3 et aVL ; deux T négatives dans un même territoire sont pathologiques.","src":"p. 377, 411","q":"Où les ondes T sont-elles normalement positives ou négatives, et quand sont-elles pathologiques ?"},{"id":"231-ess-06","rank":"A","text":"Un ECG normal s'affirme par une lecture systématique : rythme, conduction, repolarisation, morphologie.","src":"p. 377","q":"Comment affirmer qu'un ECG est normal (étapes de lecture) ?"},{"id":"231-ess-07","rank":"A","text":"Bloc complet de branche : QRS > 120 ms ; V1 globalement positif avec aspect RsR' = BBD (S traînante en V6) ; V1 globalement négatif (rS ou QS) avec notch en V6, D1, aVL = BBG.","src":"p. 378-380","q":"Comment définir un bloc complet de branche et distinguer BBD et BBG en V1 ?"},{"id":"231-ess-08","rank":"A","text":"Avec un QRS large, la polarité de l'onde T s'inverse par rapport au QRS (T positive avec petit sus-ST si QRS négatif, T négative avec petit sous-ST si QRS positif) ; avec un ST ascendant en V1-V2 dans le BBG, elle peut faire évoquer à tort un SCA ST+.","src":"p. 381","q":"Qu'est-ce que la discordance appropriée de l'onde T avec un QRS large, et quel piège crée-t-elle dans le BBG ?"},{"id":"231-ess-09","rank":"A","text":"Évoquer un infarctus antérieur et obtenir une évaluation cardiologique rapide, sans attendre la troponine (sémiologie de la douleur dont l'effet de la TNT, signes de choc, ETT).","src":"p. 381","q":"Quelle conduite devant une douleur thoracique persistante avec BBG ?"},{"id":"231-ess-10","rank":"A","text":"L'hémibloc antérieur gauche dévie l'axe au-delà de –30° (D2 négatif) ; l'hémibloc postérieur gauche le dévie au-delà de +90° (D1 négatif, S1Q3).","src":"p. 382","q":"Comment l'hémibloc antérieur gauche et l'hémibloc postérieur gauche modifient-ils l'axe du QRS ?"},{"id":"231-ess-11","rank":"B","text":"Syncope associée à un bloc bifasciculaire impose l'hospitalisation en cardiologie sous télémétrie en raison du risque de BAV complet infrahissien.","src":"p. 383","q":"Quelle conduite devant une syncope associée à un bloc bifasciculaire, et pourquoi ?"},{"id":"231-ess-12","rank":"B","text":"Les BAV infrahissiens (Mobitz 2, BAV3) justifient un pacemaker même en l'absence de symptôme.","src":"p. 412","q":"Quels BAV justifient un pacemaker même sans symptôme ?"},{"id":"231-ess-13","rank":"A","text":"Dans un BAV, les ondes P restent régulières et à fréquence normale ; le BAV1 est un allongement fixe et constant du PR au-delà de 200 ms sans onde P bloquée.","src":"p. 385-386","q":"Comment sont les ondes P dans un BAV, et comment définit-on le BAV1 ?"},{"id":"231-ess-14","rank":"A","text":"Mobitz 1 : allongement progressif du PR puis P bloquée (suprahissien) ; Mobitz 2 : PR constant puis P bloquée inopinée (infrahissien).","src":"p. 385","q":"Distinguez le BAV2 Mobitz 1 du Mobitz 2 : aspect du PR et siège du bloc."},{"id":"231-ess-15","rank":"A","text":"Devant une bradycardie, plus de P que de QRS signe un BAV ; des P trop lentes ou absentes signent une dysfonction sinusale.","src":"p. 389","q":"Devant une bradycardie, que signent plus de P que de QRS, et des P trop lentes ou absentes ?"},{"id":"231-ess-16","rank":"B","text":"Le bloc sinoatrial du 2e degré se traduit par une pause sans P-QRS-T égale au double de l'intervalle PP normal.","src":"p. 387","q":"Comment se traduit le bloc sinoatrial du 2e degré à l'ECG ?"},{"id":"231-ess-17","rank":"A","text":"En échappement jonctionnel, l'onde P disparaît devant le QRS et peut apparaître rétrograde derrière lui, négative en D2.","src":"p. 388","q":"Quel est l'aspect de l'onde P en échappement jonctionnel ?"},{"id":"231-ess-18","rank":"A","text":"La tachycardie sinusale a des P positives en D1, D2, D3, aVF et une fréquence qui varie progressivement, contrairement aux marches d'escalier des TSV.","src":"p. 390-391","q":"Comment reconnaître une tachycardie sinusale par rapport à une TSV ?"},{"id":"231-ess-19","rank":"B","text":"Manœuvres vagales (Valsalva, compression carotidienne unilatérale, eau froide) puis adénosine IV en flash créent un BAV transitoire à visée diagnostique.","src":"p. 390","q":"Quelles manœuvres et quel médicament créent un BAV transitoire à visée diagnostique devant une tachycardie ?"},{"id":"231-ess-20","rank":"B","text":"Asthme (bronchospasme intense transitoire, rare), hypotension artérielle (p. 390) et FA conduite par une voie accessoire (super-Wolff, p. 411). L'item 237 (p. 421, rang A) cite : asthme et HTA non contrôlée.","src":"p. 390, 411 ; item 237 p. 421","q":"Quelles sont les contre-indications de l'adénosine ?"},{"id":"231-ess-21","rank":"A","text":"La fibrillation atriale est le seul diagnostic devant une tachycardie complètement irrégulière à QRS fins.","src":"p. 392, 415","q":"Quel diagnostic devant une tachycardie complètement irrégulière à QRS fins ?"},{"id":"231-ess-22","rank":"B","text":"Une FA dont les QRS deviennent lents et réguliers traduit un BAV complet associé avec rythme d'échappement.","src":"p. 392","q":"Que signifie une FA dont les QRS deviennent lents et réguliers ?"},{"id":"231-ess-23","rank":"A","text":"Le flutter donne une activité atriale monomorphe vers 300 bpm sans retour à la ligne isoélectrique, avec des ventricules le plus souvent à 150 bpm (2/1).","src":"p. 393-394","q":"Décrivez l'activité atriale et ventriculaire du flutter (fréquences, ligne isoélectrique) ?"},{"id":"231-ess-24","rank":"A","text":"Le flutter typique antihoraire emprunte l'isthme cavotricuspide : ondes F négatives en D2, D3, aVF, positives en V1, négatives en V6.","src":"p. 394","q":"Quel circuit emprunte le flutter typique antihoraire et quelle est la polarité de ses ondes F ?"},{"id":"231-ess-25","rank":"A","text":"Tachycardie très régulière, souvent rapide autour de 200 bpm (130 à 260 bpm), par réentrée intranodale ou par réentrée sur une voie accessoire (faisceau de Kent, rythme réciproque).","src":"p. 395-396","q":"Décrivez la tachycardie jonctionnelle (Bouveret) : régularité, fréquence, mécanismes ?"},{"id":"231-ess-26","rank":"A","text":"Une extrasystole atriale est une P prématurée de morphologie différente suivie d'un QRS fin ; l'extrasystole ventriculaire est un QRS large prématuré.","src":"p. 397","q":"Distinguez extrasystole atriale et extrasystole ventriculaire à l'ECG ?"},{"id":"231-ess-27","rank":"A","text":"Toute tachycardie régulière à QRS larges est une tachycardie ventriculaire jusqu'à preuve du contraire.","src":"p. 398","q":"Comment considérer toute tachycardie régulière à QRS larges ?"},{"id":"231-ess-28","rank":"A","text":"La dissociation ventriculoatriale (plus de QRS que de P), les captures et les fusions sont les arguments de certitude d'une TV.","src":"p. 400","q":"Quels sont les arguments de certitude d'une tachycardie ventriculaire ?"},{"id":"231-ess-29","rank":"A","text":"La fibrillation ventriculaire est une tachycardie irrégulière à QRS larges polymorphes imposant un choc électrique immédiat, massage cardiaque en attendant.","src":"p. 402-403","q":"Définissez la fibrillation ventriculaire à l'ECG et sa prise en charge ?"},{"id":"231-ess-30","rank":"B","text":"La torsade de pointes est une TV polymorphe survenant sur QT long ; son traitement corrige les ions, accélère la fréquence et arrête les médicaments en cause.","src":"p. 403-404","q":"Définissez la torsade de pointes et son traitement ?"},{"id":"231-ess-31","rank":"A","text":"Une tachycardie mal tolérée sur le plan hémodynamique impose une cardioversion électrique externe.","src":"p. 405","q":"Quelle conduite devant une tachycardie mal tolérée sur le plan hémodynamique ?"},{"id":"231-ess-32","rank":"A","text":"L'indice de Sokolow : amplitude de S en V1 ou V2 + amplitude de R en V5 ou V6 (normal < 35 mm) ; ce diagnostic peut s'associer à des anomalies de repolarisation.","src":"p. 406, 415","q":"Quel indice est le marqueur d'HVG à retenir, comment se calcule-t-il et que lui associe-t-on ?"},{"id":"231-ess-33","rank":"B","text":"L'embolie pulmonaire peut donner un aspect S1Q3T3 par hypertrophie ventriculaire droite aiguë.","src":"p. 407","q":"Quel aspect ECG peut donner l'embolie pulmonaire et par quel mécanisme ?"},{"id":"231-ess-34","rank":"A","text":"Hypokaliémie : T plates ou négatives, sous-ST, QT long et onde U ; hyperkaliémie : T amples pointues symétriques, PR long, QRS large.","src":"p. 408","q":"Quelles sont les anomalies ECG de l'hypokaliémie et de l'hyperkaliémie ?"},{"id":"231-ess-35","rank":"B","text":"La péricardite aiguë débute par un sus-ST diffus concave vers le haut sans miroir, un sous-décalage de PQ et un microvoltage.","src":"p. 409","q":"Quels sont les signes ECG du début de la péricardite aiguë ?"},{"id":"231-ess-36","rank":"B","text":"La préexcitation associe PR court < 120 ms, onde delta empâtant le pied du QRS et troubles de repolarisation.","src":"p. 410","q":"Quels sont les signes ECG de la préexcitation ?"},{"id":"231-ess-37","rank":"A","text":"Dans un SCA ST+, on repère d'abord le sus-décalage qui désigne l'artère occluse, puis son miroir ; un sous-ST V1-V3 impose de chercher un sus-ST postérieur en V7-V9.","src":"p. 411","q":"Comment lire l'ECG d'un SCA ST+ (artère, miroir) et que faire devant un sous-ST V1-V3 ?"},{"id":"231-ess-38","rank":"B","text":"Les cinq causes de sus-décalage du ST sont le SCA, l'anévrisme ventriculaire, la repolarisation précoce, l'angor de Prinzmetal et la péricardite.","src":"p. 412","q":"Quelles sont les 5 causes de sus-décalage du ST ?"},{"id":"231-ess-39","rank":"B","text":"Le spike de stimulation, long de 0,4 à 1 ms, est pathognomonique d'un pacemaker ; la stimulation ventriculaire droite donne un QRS large d'aspect BBG.","src":"p. 413-414","q":"Quel signe ECG est pathognomonique d'un pacemaker, et quel QRS donne la stimulation ventriculaire droite ?"},{"id":"231-ess-40","rank":"A","text":"L'ECG 12 dérivations est obligatoire dans le bilan de l'HTA et indiqué en préopératoire après 65 ans ou en cas de risque.","src":"p. 414","q":"Quand l'ECG 12 dérivations est-il obligatoire ou indiqué (HTA, préopératoire) ?"},{"id":"231-ess-51","rank":"A","q":"Quelles dérivations explorent chaque territoire cardiaque (antéroseptal, apical, latéral, inférieur, postérieur, ventricule droit) ?","text":"Antéroseptales V1-V3 ; apicale V4 ; latérales D1, aVL (hautes) et V5, V6 (basses) ; inférieures D2, D3, aVF ; postérieures V7-V9 ; le VD est exploré par V1, V2, V3R, V4R.","src":"p. 374","kind":"liste"},{"id":"231-ess-52","rank":"B","q":"Citez les 3 phases du QRS et leur traduction ECG ?","text":"1) Dépolarisation septale vers l'avant/la droite/le haut : q fine latérale, petit r en V1 ; 2) vers la jambe gauche et l'avant : grande R en V3-V4 et D2 ; 3) vers le haut et l'arrière : petite S inférieure et latérale.","src":"p. 376","kind":"liste"},{"id":"231-ess-53","rank":"B","q":"Citez les 3 formes de FA plus difficiles à reconnaître à l'ECG ?","text":"FA + BAV complet (activité ventriculaire lente et régulière) ; alternance FA / dysfonction sinusale (syndrome tachycardie-bradycardie, maladie de l'oreillette, pauses de régularisation) ; FA + bloc de branche (tachycardie irrégulière à QRS larges).","src":"p. 392-393","kind":"liste"},{"id":"231-ess-54","rank":"A","q":"Citez les variétés de flutter atrial et leurs critères ?","text":"Typique antihoraire, le plus fréquent (boucle de l'OD par l'isthme cavotricuspide, 300 bpm sur oreillette normale, F négatives en D2-D3-aVF, positives en V1, négatives en V6) ; typique horaire (polarités strictement inversées) ; atypiques (isthme cavotricuspide hors circuit, 120-320 bpm, F de morphologies diverses).","src":"p. 394","kind":"liste"},{"id":"231-ess-55","rank":"A","q":"Citez les 2 mécanismes des tachycardies jonctionnelles (Bouveret) ?","text":"Réentrée **intranodale** (activité atriale souvent non visible ou devinée dans le ST) et rythme **réciproque** par une voie accessoire (faisceau de Kent). Rang B : réduites par manœuvres vagales ou adénosine IV.","src":"p. 395-397","kind":"liste"},{"id":"231-ess-56","rank":"A","q":"Citez les 3 types d'extrasystoles et leurs aspects ECG ?","text":"Atriale : P prématurée de morphologie différente + QRS fin. Jonctionnelle : QRS fin ± P' rétrograde (rare). Ventriculaire : QRS large ± P' rétrograde.","src":"p. 397-398","kind":"liste"},{"id":"231-ess-57","rank":"A","q":"Citez les arguments en faveur d'une tachycardie ventriculaire (hors certitude) ?","text":"Cardiopathie sous-jacente ; concordance positive ou négative en V1-V6 ; déviation axiale extrême (QRS positif en aVR) ; QRS larges différents d'un bloc de branche habituel.","src":"p. 400","kind":"liste"},{"id":"231-ess-58","rank":"A","q":"Citez les 6 situations d'allongement du QT favorisant les torsades de pointes ?","text":"Bradycardie extrême (échappements des BAV bas), hypokaliémie, hypocalcémie, hypomagnésémie, médicaments allongeant le QT, QT long congénital.","src":"p. 404","kind":"liste"},{"id":"231-ess-59","rank":"B","q":"Citez les 3 volets de la prise en charge d'une torsade de pointes ?","text":"Corriger les troubles ioniques ; accélérer la fréquence cardiaque ; arrêter les médicaments allongeant le QT.","src":"p. 404","kind":"liste"},{"id":"231-ess-60","rank":"B","q":"Citez les 4 phases ECG de la péricardite aiguë ?","text":"1) Microvoltage, sus-ST concave diffus sans miroir, sous-décalage PQ ; 2) T plates, ST isoélectrique ; 3) T négatives persistantes ; 4) retour à la normale.","src":"p. 409","kind":"liste"},{"id":"231-ess-61","rank":"A","q":"Citez les aspects ECG possibles d'un SCA sans sus-décalage du ST ?","text":"Sous-décalage de ST, inversion des ondes T, pseudo-normalisation de T antérieurement négatives, aplatissement des T, ou ECG normal ; anomalies parfois masquées par un pacemaker.","src":"p. 412","kind":"liste"},{"id":"231-ess-62","rank":"A","q":"Citez les indications du monitorage ECG ?","text":"Urgence/réanimation et transferts médicalisés ; soins intensifs cardiologiques (SCA) ; syncope d'origine rythmique suspectée ; peropératoire et salle de réveil ; certains exercices de réadaptation cardiaque.","src":"p. 414","kind":"liste"},{"id":"231-ess-63","rank":"A","q":"Si D1 est négative avec onde P négative, quel est le 1er diagnostic à évoquer avant un HBPG ?","text":"Une **inversion des électrodes frontales** (P négative en D1 aussi). L'HBAG est fréquent (branche fragile, superficielle), l'HBPG rare (branche profonde).","src":"p. 383","kind":"piege"},{"id":"231-ess-64","rank":"A","q":"Un rythme avec ondes P régulières est-il toujours sinusal ?","text":"Non : il peut y avoir des P régulières **sans conduction** aux ventricules (BAV3) ; le rythme sinusal exige un QRS après chaque P et une P avant chaque QRS, P positive en D1-D2.","src":"p. 376","kind":"piege"},{"id":"231-ess-65","rank":"A","q":"Que décrire en premier avant de décrire un bloc de branche, et pourquoi ?","text":"Le **rythme atrial**, pour ne pas manquer une tachycardie supraventriculaire, dont l'association à un bloc de branche n'est pas rare.","src":"p. 378, 381","kind":"piege"},{"id":"231-ess-66","rank":"A","q":"Que mesure l'intervalle PR, et comment mesurer correctement le QT ?","text":"PR (début P à début QRS) : **toute la conduction** jusqu'au réseau de Purkinje. QT : dérivation où T est la plus ample (V2-V3), tangente à T, **sans inclure l'onde U**.","src":"p. 376-377","kind":"piege"},{"id":"231-ess-67","rank":"B","q":"Quelles sont les contre-indications des manœuvres vagales et de l'adénosine ?","text":"Compression carotidienne : athérome important ou souffle carotidien. Compression oculaire bilatérale : plus recommandée (décollement de rétine du myope). Adénosine : asthme, hypotension artérielle (p. 390), FA sur voie accessoire (super-Wolff, p. 411) ; item 237 (p. 421, A) : asthme et HTA non contrôlée.","src":"p. 390, 411 ; item 237 p. 421","kind":"piege"},{"id":"231-ess-68","rank":"A","q":"Comment distinguer tachycardie sinusale et tachycardie supraventriculaire ?","text":"Sinusale : P sinusales positives en D1-D2-D3-aVF, fréquence qui varie **progressivement**, contexte (fièvre, stress). Supraventriculaire : fréquence en « marches d'escalier ».","src":"p. 390-391","kind":"piege"},{"id":"231-ess-69","rank":"A","q":"Qu'est-ce qui distingue la dissociation ventriculoatriale de la TV de celle du BAV complet ?","text":"TV : **plus de QRS que d'ondes P** (ondes P plus lentes et dissociées des QRS), captures et fusions possibles seulement s'il y a dissociation. BAV complet : dissociation atrioventriculaire avec ondes P régulières à fréquence normale, plus nombreuses que les QRS.","src":"p. 400-401","kind":"piege"},{"id":"231-ess-70","rank":"A","q":"Quels sont les critères de suspicion de TV, de TV non soutenue et soutenue, et que faut-il décrire ?","text":"FC > 100 bpm et QRS > 120 ms sur au moins 3 battements consécutifs. Non soutenue : de 3 battements à 30 s ; soutenue : > 30 s. Décrire monomorphe ou polymorphe. La suspicion impose l'alerte (15) et de se préparer à une réanimation.","src":"p. 399-400","kind":"piege"},{"id":"231-ess-71","rank":"B","q":"Comment distinguer torsade de pointes et fibrillation ventriculaire sur l'ECG ?","text":"Parfois impossible sur l'aspect : seuls un **QT long** avant le trouble et le contexte permettent le diagnostic (FV : ischémie, cardiopathie évoluée). La torsade peut s'arrêter spontanément.","src":"p. 403","kind":"piege"},{"id":"231-ess-72","rank":"A","q":"Quelle est la prise en charge immédiate d'une FV ?","text":"Urgence absolue : **cardioversion (choc) électrique immédiate** avant tout autre geste, massage cardiaque en attendant le choc. ECG : tachycardie irrégulière à QRS larges polymorphes ; perte de connaissance en quelques secondes, pouls carotidien aboli.","src":"p. 402","kind":"piege"},{"id":"231-ess-73","rank":"A","q":"Les ondes Q de nécrose rendent-elles inutile la reperfusion d'un SCA ST+ ?","text":"Non : elles apparaissent en principe vers la **6e heure** (parfois plus tôt) et ne doivent pas faire considérer à tort qu'une reperfusion serait inutile car trop tardive.","src":"p. 412","kind":"piege"},{"id":"231-ess-74","rank":"A","q":"Quels pièges de repolarisation créent l'HVG électrique importante et le BBG en V1-V2 ?","text":"HVG : aspect QS (pseudonécrose) et/ou sus-décalage du ST en V1-V2 mimant une séquelle d'infarctus ou un SCA. BBG : discordance appropriée avec ST ascendant en V1-V2, pouvant faire évoquer à tort un SCA ST+.","src":"p. 381, 406","kind":"piege"},{"id":"231-ess-75","rank":"B","q":"Pourquoi les ondes T sont-elles concordantes avec les QRS à l'ECG normal ?","text":"La dépolarisation progresse de l'**endocarde vers l'épicarde** alors que la repolarisation va de l'**épicarde vers l'endocarde** : T positive si QRS positif, négative si QRS négatif.","src":"p. 371","kind":"B"},{"id":"231-ess-76","rank":"A","q":"Quel est le rôle de filtre du nœud atrioventriculaire (conduction décrémentielle) ?","text":"Au-delà d'une certaine fréquence atriale, les ventricules ne suivent plus en 1/1 (2/1, alternance 1/1-2/1 ou 2/1-3/1, conduction variable). Ce filtre est vital : sans lui, une FA entraînerait une FV et un flutter à 300 bpm une tachycardie à 300 bpm dans le ventricule.","src":"p. 390","kind":""},{"id":"231-ess-77","rank":"A","q":"Que signifie « trouble du rythme » en français et comment sont classés les troubles supraventriculaires ?","text":"Synonyme de **tachycardie** (les bradycardies sont des troubles de la conduction). Supraventriculaires : QRS fins (< 120 ms) dans la majorité, larges si trouble de conduction intraventriculaire associé.","src":"p. 390","kind":""},{"id":"231-ess-78","rank":"B","q":"Quels sont les mécanismes d'une préexcitation ventriculaire et son risque ?","text":"Voie accessoire (faisceau de Kent) conduisant en compétition avec le NAV : PR court, onde delta. Si FA, la voie ne filtre pas (non décrémentielle) : tachycardie irrégulière « en accordéon », risque de FV.","src":"p. 410-411","kind":"B"},{"id":"231-ess-79","rank":"B","q":"Quand le blocage du NAV est-il utile pour démasquer une préexcitation, et quand le proscrire ?","text":"Massage ou adénosine forcent le passage par la voie accessoire (utile si préexcitation minime) ; **à ne pas faire en cas de FA**.","src":"p. 410","kind":"B"},{"id":"231-ess-80","rank":"B","q":"Quels sont les risques d'un bloc bifasciculaire et d'un BBG complet ?","text":"Bifasciculaire (BBG complet ou BBD + hémibloc) : risque que la 3e branche dysfonctionne de façon intermittente → BAV complet infrahissien (syncopes, voire mort subite). BBG complet : désynchronisation des parois du VG pouvant contribuer à créer ou aggraver une cardiopathie ; sa correction est indiquée en cas de signes d'insuffisance cardiaque.","src":"p. 383","kind":"B"},{"id":"231-ess-81","rank":"B","q":"Qu'est-ce qu'un stimulateur cardiaque produit à l'ECG selon l'indication (sinusal, BAV) ?","text":"Spike (0,4-1 ms, pathognomonique). Dysfonction sinusale : stimulation atriale, P après le spike. BAV : stimulation ventriculaire droite, QRS large d'aspect BBG. Unipolaire : visible ; bipolaire : peu visible.","src":"p. 413-414","kind":"B"},{"id":"231-ess-82","rank":"B","q":"Citez les types de prothèses cardiaques et leur fonction ?","text":"Pacemaker (bradycardie), défibrillateur (TV/FV, fait aussi fonction pacemaker sauf sous-cutané), resynchronisation (BBG et insuffisance cardiaque, toujours pacemaker) ; association possible.","src":"p. 413","kind":"B"},{"id":"231-ess-83","rank":"A","q":"Quelles sont les indications de l'ECG 12 dérivations hors urgence ?","text":"Bilans de santé ; aptitude professionnelle ou sportive ; préopératoire > 65 ans ou à risque ; enquêtes familiales ; symptômes ; bilan HTA ; surveillance de pathologies à complications CV (diabète, AVC).","src":"p. 414","kind":""},{"id":"231-ess-84","rank":"B","q":"Quelles sont les indications du Holter et des enregistrements plus longs ?","text":"Holter 24-96 h : malaises, syncopes, palpitations si ECG non contributif. Symptômes rares : jusqu'à 21 jours ou enregistreurs d'événements ; holter implanté jusqu'à 3 ans (syncope inexpliquée, FA silencieuse).","src":"p. 415","kind":"B"},{"id":"231-ess-85","rank":"A","q":"À quoi servent les dérivations de Lewis et quels sont les pièges de positionnement des précordiales ?","text":"Lewis : démasquer une activité atriale peu visible (visible en D1). V1-V2 trop hautes ou trop écartées (confusion avec foyers auscultatoires) : pseudonécrose ou atypie de repolarisation antérieure.","src":"p. 373","kind":""},{"id":"231-ess-86","rank":"A","q":"Devant une tachycardie bien tolérée dont le diagnostic n'est pas évident, que faire, et quelles sont les 3 réponses possibles ?","text":"Manœuvres vagales ± adénosine si échec (BAV transitoire). Démasque l'activité atriale → tachycardie atriale (sinusale, flutter, TAF) ; arrête la tachycardie → tachycardie jonctionnelle (réentrée dépendante du NAV) ; aucun effet → TV (ne dépend pas du NAV).","src":"p. 405"},{"id":"231-ess-87","rank":"A","q":"Quelles sont les deux seules structures dont la défaillance donne une bradycardie ?","text":"Le nœud sinusal (dysfonction sinusale) et le nœud atrioventriculaire (BAV2 ou 3). Les blocs de branche ne donnent pas de bradycardie.","src":"p. 389, 415"},{"id":"231-ess-88","rank":"A","q":"Quelles sont les anomalies ECG de la forme sévère d'hypertrophie ventriculaire gauche ?","text":"Onde T négative, souvent avec sous-décalage du ST, dans les dérivations latérales (D1, aVL, V5, V6) et disparition de l'onde q septale dans ces mêmes dérivations.","src":"p. 406"},{"id":"231-ess-89","rank":"A","q":"Quelle est l'étiologie la plus fréquente de l'HVG électrique, et la suivante ?","text":"L'HTA, puis le rétrécissement aortique.","src":"p. 407"},{"id":"231-ess-90","rank":"A","q":"Quel aspect du point J et du ST peut être physiologique chez le sujet jeune, surtout l'homme ?","text":"Un point J sus-décalé de V1 à V4 avec un segment ST jonctionnel en pente ascendante vers l'onde T : repolarisation physiologique.","src":"p. 377"},{"id":"231-ess-91","rank":"A","q":"Quelles sont les principales indications de l'ECG en urgence (objectif de rang A) ?","text":"Défaillance(s) d'organe(s), douleur thoracique, palpitations, syncope, troubles hydroélectrolytiques (K, Ca).","src":"p. 368"},{"id":"231-ess-92","rank":"A","q":"Comment évolue le sus-décalage du ST d'un SCA ST+ selon la reperfusion ?","text":"Il régresse rapidement avec la reperfusion et dure plusieurs jours sans reperfusion ; il peut persister indéfiniment en cas d'évolution anévrismale. Après 48 heures, évolution normale vers une onde T négative « ischémique », parfois très prolongée.","src":"p. 412"},{"id":"231-ess-93","rank":"A","q":"Quelle conduite impose la suspicion d'une tachycardie ventriculaire ?","text":"Donner l'alerte (appeler le 15) et se préparer à une réanimation ; si mauvaise tolérance hémodynamique : cardioversion électrique externe.","src":"p. 399, 405"}],"numbers":[{"id":"231-num-01","rank":"A","label":"Vitesse de déroulement standard","value":"25 mm/s : 1 mm = 40 ms, grand carreau (5 mm) = 200 ms","src":"p. 375"},{"id":"231-num-02","rank":"A","label":"Étalonnage d'amplitude","value":"1 mm = 0,1 mV","src":"p. 375"},{"id":"231-num-03","rank":"A","label":"Fréquence cardiaque normale de repos (adulte)","value":"60–100 bpm (bradycardie < 60, tachycardie > 100)","src":"p. 375-376"},{"id":"231-num-04","rank":"A","label":"Durée normale de l'onde P","value":"< 120 ms (théorique < 110 ms)","src":"p. 375"},{"id":"231-num-05","rank":"A","label":"Axe et amplitude normaux de P","value":"Axe 60° (positivité maximale en D2) ; amplitude < 2,5 mm en D2","src":"p. 375"},{"id":"231-num-06","rank":"A","label":"Intervalle PR normal","value":"120–200 ms (inclus)","src":"p. 375-376"},{"id":"231-num-07","rank":"A","label":"Durée normale du QRS","value":"70–110 ms","src":"p. 375"},{"id":"231-num-08","rank":"A","label":"Axe normal du QRS","value":"–30° à +90° (théorique –45° à +110°)","src":"p. 375"},{"id":"231-num-09","rank":"A","label":"Onde Q physiologique","value":"< 1/3 de l'amplitude du QRS et < 40 ms","src":"p. 375"},{"id":"231-num-10","rank":"A","label":"QT corrigé normal","value":"< 450 ms à 60 bpm (en pratique 470–480 ms)","src":"p. 375"},{"id":"231-num-12","rank":"A","label":"Calcul rapide de la FC","value":"FC = 300 / nombre de grands carreaux entre deux QRS (1 carreau = 300 bpm, 2 = 150 bpm)","src":"p. 376"},{"id":"231-num-13","rank":"A","label":"Graduation du double triaxe de Bailey","value":"Dérivations de 30° en 30°, sens horaire, D1 = 0°","src":"p. 375"},{"id":"231-num-14","rank":"A","label":"Durée du QRS dans un bloc complet de branche","value":"> 120 ms (bloc incomplet : 110–120 ms)","src":"p. 378-381"},{"id":"231-num-15","rank":"A","label":"Hémiblocs : durée et axe","value":"QRS > 110 ms ; HBAG axe < –30° ; HBPG axe > +90°","src":"p. 382"},{"id":"231-num-16","rank":"A","label":"Définition du BAV1","value":"PR constant > 200 ms sans onde P bloquée","src":"p. 386"},{"id":"231-num-17","rank":"A","label":"Seuil de bradycardie de l'algorithme diagnostique","value":"FC des QRS < 50 bpm","src":"p. 389"},{"id":"231-num-18","rank":"B","label":"Pause du bloc sinoatrial du 2e degré","value":"Égale au double de l'intervalle PP (RR) normal","src":"p. 387"},{"id":"231-num-19","rank":"B","label":"Durée d'effet de l'adénosine IV","value":"Une dizaine de secondes (flash IV)","src":"p. 390"},{"id":"231-num-20","rank":"A","label":"Fréquence ventriculaire de la FA","value":"100–200 bpm, QRS irrégulièrement irréguliers","src":"p. 392"},{"id":"231-num-21","rank":"A","label":"Fréquence atriale du flutter","value":"≈ 300 bpm (240–340) ; flutter atypique 120–320 bpm","src":"p. 393-394"},{"id":"231-num-22","rank":"A","label":"Fréquence ventriculaire du flutter","value":"150 bpm (2/1) le plus souvent, ou plus lente : 100 bpm (3/1), 75 bpm, etc.","src":"p. 394"},{"id":"231-num-23","rank":"A","label":"Fréquence des tachycardies jonctionnelles","value":"≈ 200 bpm (130–260 bpm)","src":"p. 395"},{"id":"231-num-25","rank":"A","label":"Critères de suspicion de TV","value":"FC > 100 bpm et QRS > 120 ms sur ≥ 3 battements consécutifs","src":"p. 399"},{"id":"231-num-26","rank":"A","label":"TV non soutenue vs soutenue","value":"Non soutenue : 3 battements à 30 s ; soutenue : > 30 s","src":"p. 399"},{"id":"231-num-27","rank":"A","label":"Part de la TV dans les morts subites","value":"Prémonitoire de l'arrêt cardiaque dans plus de la moitié des morts subites","src":"p. 398"},{"id":"231-num-28","rank":"A","label":"Indice de Sokolow","value":"S (V1 ou V2) + R (V5 ou V6) ; normal < 35 mm","src":"p. 406"},{"id":"231-num-29","rank":"B","label":"Hypertrophie atriale droite","value":"P > 2,5 mm en D2 ou > 2 mm en V1-V2","src":"p. 406"},{"id":"231-num-30","rank":"B","label":"Hypertrophie atriale gauche","value":"P > 110 ms (120 ms en pratique), composante négative > 40 ms en V1","src":"p. 406"},{"id":"231-num-31","rank":"B","label":"Hypertrophie ventriculaire droite","value":"Axe > 110° (90° en pratique) ; R > 6 mm en V1 ; S > 7 mm en V5-V6","src":"p. 407"},{"id":"231-num-32","rank":"B","label":"PR de la préexcitation","value":"< 120 ms","src":"p. 410"},{"id":"231-num-33","rank":"A","label":"Sus-décalage du ST significatif","value":"≥ 2 mm en V1-V3, ≥ 1 mm ailleurs, sur ≥ 2 dérivations adjacentes","src":"p. 412"},{"id":"231-num-34","rank":"A","label":"Onde Q de nécrose","value":"≥ 1/3 (ou 1/4) du QRS en amplitude et > 30–40 ms ; apparaît en principe vers la 6e heure","src":"p. 412"},{"id":"231-num-35","rank":"A","label":"Délai d'apparition de l'onde T négative ischémique","value":"Après 48 heures","src":"p. 412"},{"id":"231-num-36","rank":"B","label":"Durée du spike de stimulation","value":"0,4 à 1 ms","src":"p. 413"},{"id":"231-num-37","rank":"B","label":"Paramètres du Holter ECG","value":"2 à 12 dérivations, 24 à 96 h maximum","src":"p. 415"},{"id":"231-num-38","rank":"B","label":"Enregistrements de très longue durée","value":"ECG ambulatoire jusqu'à 21 jours ; holter implantable jusqu'à 3 ans","src":"p. 415"},{"id":"231-num-39","rank":"A","label":"Âge de l'ECG préopératoire systématique","value":"> 65 ans (ou patient / intervention à risque)","src":"p. 414"},{"id":"231-num-40","rank":"A","label":"Dérivations précordiales","value":"V1 à V9, complétées parfois par V3R et V4R (enfant, suspicion de SCA)","src":"p. 371"},{"id":"231-num-41","rank":"A","label":"Largeur des QRS des troubles du rythme supraventriculaire","value":"QRS fins (< 120 ms) dans la majorité des cas ; larges si trouble de conduction intraventriculaire associé","src":"p. 390"}],"mnemonics":[{"id":"231-mn-01","rank":"A","title":"Lecture systématique de l'ECG normal","mnemonic":"« Regarde Chaque Rythme Méthodiquement »","expansion":"- **R**ythme : sinusal, 60–100 bpm\n- **C**onduction : P < 120 ms, PR 120–200 ms, QRS 70–110 ms, axe –30° à +90°\n- **R**epolarisation : point J et ST isoélectriques, T positives sauf aVR/V1 (± D3, aVL), QT < 450 ms\n- **M**orphologie : amplitudes normales (Sokolow < 35 mm), transition V1→V6, pas de Q de nécrose","src":"p. 377"},{"id":"231-mn-02","rank":"A","title":"BBD ou BBG : la polarité de V1","mnemonic":"« Droit = V1 Dressé, Gauche = V1 Gisant »","expansion":"- **D**roit : QRS **d**ressé (globalement positif) en V1, aspect RsR', S traînante en V6\n- **G**auche : QRS **g**isant (globalement négatif) en V1, aspect rS/QS, notch et R exclusive en V6-D1-aVL\n- Dans les deux cas QRS > 120 ms et aspect inverse en V6","src":"p. 378-381"},{"id":"231-mn-03","rank":"A","title":"Arguments ECG de tachycardie ventriculaire","mnemonic":"« Des Cœurs Cassés Cognent Avec Ardeur »","expansion":"Certitude :\n- **D**issociation ventriculoatriale (plus de QRS que de P)\n- **C**aptures et fusions\n\nEn faveur :\n- **C**ardiopathie sous-jacente\n- **C**oncordance positive ou négative de V1 à V6\n- **A**xe extrême (QRS positif en aVR)\n- **A**spect des QRS larges différent d'un bloc de branche habituel","src":"p. 400"},{"id":"231-mn-04","rank":"A","title":"Causes d'allongement du QT (torsades de pointes)","mnemonic":"« Bébé Koala Calme Mange Mes Cookies »","expansion":"- **B**radycardie extrême (échappements des BAV bas situés, intoxication aux bradycardisants)\n- **K** : hypo**k**aliémie\n- **Ca** : hypo**ca**lcémie\n- **M**g : hypo**m**agnésémie\n- **M**édicaments allongeant le QT (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens)\n- **C**ongénital : syndrome du QT long","src":"p. 404"},{"id":"231-mn-05","rank":"B","title":"Les cinq étiologies de sus-décalage du ST","mnemonic":"« Ses Amis Reprennent un Petit Pain »","expansion":"- **S**CA avec sus-décalage du ST (onde de Pardee avec miroir)\n- **A**névrisme ventriculaire (sus-ST persistant après l'infarctus)\n- **R**epolarisation précoce (dérivations inférolatérales)\n- **P**rinzmetal (spasme coronarien)\n- **P**éricardite (diffus, concave vers le haut, sans miroir)","src":"p. 412"},{"id":"231-mn-06","rank":"B","title":"Les quatre phases ECG de la péricardite aiguë","mnemonic":"« Sa Péricardite N'est Normale qu'à la fin »","expansion":"1. **S**us-décalage diffus concave sans miroir + sous-PQ + microvoltage\n2. T **P**lates, ST isoélectrique\n3. T **N**égatives persistantes\n4. Retour à la **N**ormale","src":"p. 409"},{"id":"231-mn-07","rank":"B","title":"Les manœuvres vagales du livre","mnemonic":"« Vite Calme Et détendu »","expansion":"- **V**alsalva (expiration forcée à glotte fermée)\n- **C**ompression carotidienne unilatérale (contre-indiquée si athérome important ou souffle carotidien)\n- **E**au froide : boire un grand verre\n\nEn cas d'échec : adénosine IV en flash (contre-indiquée si asthme, hypotension, FA préexcitée). La compression oculaire n'est plus recommandée.","src":"p. 390"},{"id":"231-mn-08","rank":"A","title":"Indications du monitorage ECG (scope)","mnemonic":"« Un Scope Surveille les Patients Réanimés »","expansion":"- **U**rgences, réanimation, transferts médicalisés\n- **S**oins intensifs cardiologiques (pathologie aiguë, ex. syndrome coronarien)\n- **S**yncope de cause rythmique suspectée\n- **P**eropératoire et salle de réveil\n- **R**éadaptation cardiaque (certains exercices)","src":"p. 414"},{"id":"231-mn-09","rank":"B","title":"Indications du pacemaker","mnemonic":"Pacemaker « SI » : Symptomatique ou Infrahissien","expansion":"- **S**ymptomatique : bradycardies symptomatiques par dysfonction sinusale, BAV2 Mobitz 1 ou bradycardie sinusale\n- **I**nfrahissien : BAV2 Mobitz 2 et BAV3, **même sans symptôme**","src":"p. 412"},{"id":"231-mn-10","rank":"A","title":"Signes ECG de l'hyperkaliémie","mnemonic":"« Toujours Plus Que Bien »","expansion":"- **T** : onde T ample, pointue, symétrique\n- **P** : PR allongé\n- **Q** : QRS élargi\n- **B** : BAV (et aussi TV, dysfonction sinusale)","src":"p. 408"},{"id":"231-mn-11","rank":"A","title":"Territoires des dérivations précordiales","mnemonic":"« Septe, Pointe, Côté, Dos »","expansion":"- V1-V2-V3 → **septe** : antéroseptal (paroi antérieure du VG et septum)\n- V4 → **pointe** : apical\n- V5-V6 → **côté** : latéral bas (D1, aVL = latéral haut)\n- V7-V8-V9 → **dos** : postérieur (face basale et inférieure du VG)\n- D2, D3, aVF → inférieur ; V1, V2, V3R, V4R → ventricule droit","src":"p. 374"}]},"questions":[{"id":"231-qcm-001","type":"QRM","rank":"A","objective":"231-obj-01","tags":["définition","ECG"],"difficulty":1,"stem":"Parmi les valeurs suivantes, lesquelles correspondent à des paramètres normaux de l'ECG de l'adulte au repos ?","options":[{"t":"La durée du QRS est comprise entre 70 et 110 ms","ok":true,"why":"QRS normal 70-110 ms ; 110-120 = bloc incomplet, > 120 = bloc de branche complet (tableau 15.2, p. 375, 381)."},{"t":"Le QT corrigé normal doit être supérieur à 450 ms à 60 bpm","ok":false,"why":"Inversé : le QTc normal est < 450 ms à 60 bpm (en pratique 470-480) ; un QT allongé expose aux torsades (p. 375, 404)."},{"t":"L'espace PR est compris entre 120 et 200 ms","ok":true,"why":"PR normal = 120 à 200 ms (inclus) ; > 200 ms = BAV1, < 120 ms = PR court, l'un des signes de la préexcitation par voie accessoire (avec l'onde delta) (p. 375-376, 410)."},{"t":"La fréquence cardiaque de repos normale est comprise entre 60 et 100 bpm","ok":true,"why":"Norme de l'adulte au repos ; < 60 = bradycardie, > 100 = tachycardie (attention au nouveau-né) (p. 376)."},{"t":"L'axe normal du QRS se situe entre 90° et 180°","ok":false,"why":"L'axe normal du QRS est situé entre -30° et +90°, pas entre 90° et 180° qui correspond à un axe hyperdroit."}],"explanation":"Le tableau des valeurs normales doit être connu par cœur : FC 60-100 bpm, PR 120-200 ms, QRS 70-110 ms, axe -30 à +90°, QTc < 450 ms à 60 bpm.","src":"p. 375-376","deep":"**Pourquoi** : c'est le tableau des valeurs normales à connaître par cœur : FC 60-100 bpm, P < 120 ms, PR 120-200 ms, QRS 70-110 ms, axe -30 à +90°, QTc < 450 ms à 60 bpm (p. 375-376).\n**À relier** : FC < 60 = bradycardie, > 100 = tachycardie (p. 376) ; attention, l'algorithme de la fig. 15.27 retient « bradycardie = FC < 50 bpm » (p. 389) : les deux seuils coexistent dans le Collège.\n**Piège** : le QTc normal est INFÉRIEUR à 450 ms, et l'axe normal est -30/+90° (90-180° = hyperdroit)."},{"id":"231-qcm-004","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":1,"stem":"Parmi les associations dérivation(s)-territoire suivantes, laquelle ou lesquelles sont exactes ?","options":[{"t":"V1, V2 et V3 explorent le territoire antéroseptal","ok":true,"why":"V1-V3 font face à la paroi antérieure du VG et au septum : territoire antéroseptal ; V4 est apical (p. 374)."},{"t":"V7, V8 et V9 explorent un territoire antérieur","ok":false,"why":"Faux : V7-V9 (dans le dos) explorent la face basale et inférieure, postérieure, du VG ; un sous-ST V1-V3 peut en être le miroir (p. 374, 411)."},{"t":"V4 explore uniquement le territoire septal profond","ok":false,"why":"Faux : V4 est la dérivation apicale ; le septum est vu par V1-V3 (p. 374)."},{"t":"D2, D3 et aVF explorent un territoire latéral","ok":false,"why":"Faux : D2, D3, aVF = territoire inférieur (diaphragmatique) ; le latéral est D1, aVL (haut) et V5, V6 (bas) (p. 374)."},{"t":"D1 et aVL explorent un territoire inférieur","ok":false,"why":"Faux : D1 et aVL sont latérales hautes ; l'inférieur est D2, D3, aVF (p. 374)."}],"explanation":"Seule l'association V1-V2-V3 = antéroseptal est correcte ici ; les autres inversent les territoires (D2-D3-aVF = inférieur, V7-V9 = postérieur, D1-aVL = latéral haut).","src":"p. 373-374","deep":"**Pourquoi** : le territoire dépend simplement de la position de l'électrode par rapport au cœur (p. 373-374).\n**À relier** : V1-V3 antéroseptal, V4 apical, D1-aVL (haut) et V5-V6 (bas) latéral, D2-D3-aVF inférieur, V7-V9 postérieur ; le VD est exploré par V1, V2, V3R, V4R.\n**Piège** : V7-V9 sont postérieurs (pas antérieurs) et D1-aVL sont latéraux hauts (pas inférieurs)."},{"id":"231-qcm-005","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","pièges"],"difficulty":2,"stem":"Concernant une erreur fréquente de positionnement des électrodes précordiales, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Elle ne peut jamais affecter le territoire antérieur","ok":false,"why":"Faux : V1-V2 trop hautes et trop écartées donnent justement une pseudonécrose ou une repolarisation atypique antérieure (p. 373)."},{"t":"V1 et V2 sont souvent placées trop haut et trop écartées, ce qui peut simuler une pseudonécrose antérieure","ok":true,"why":"Erreur classique : on les place sur les foyers auscultatoires aortique et pulmonaire, trop hauts ; d'où pseudonécrose ou repolarisation atypique en antérieur (p. 373)."},{"t":"Elle est corrigée en utilisant systématiquement les dérivations de Lewis","ok":false,"why":"Faux : les dérivations de Lewis servent à démasquer l'activité atriale (lue en D1) ; la correction est de replacer les précordiales isodistantes (p. 373)."},{"t":"Cette erreur de position n'a aucune conséquence sur l'interprétation de l'ECG","ok":false,"why":"Faux : elle crée de faux aspects (pseudonécrose, repolarisation atypique antérieure) ; vérifier la progression R/S de V1 à V6 (p. 373, 378)."},{"t":"Cette erreur concerne exclusivement les dérivations des membres","ok":false,"why":"Faux : il s'agit des précordiales V1-V2 ; aux membres, c'est l'inversion d'électrodes qui piège (D1 et P négatives en D1) (p. 373, 383)."}],"explanation":"Le placement trop haut de V1-V2 est un piège classique source de faux aspects pathologiques en antérieur : bien vérifier l'équidistance des électrodes précordiales.","trap":"Ne pas confondre le bon positionnement des électrodes avec les repères auscultatoires (foyers aortique et pulmonaire), qui sont trop hauts.","src":"p. 373","deep":"**Pourquoi** : V1 et V2 sont souvent posées trop haut et trop écartées car on les confond avec les foyers auscultatoires aortique et pulmonaire : on obtient un faux aspect de pseudonécrose ou d'atypie de repolarisation antérieure (p. 373).\n**À relier** : les précordiales doivent être isodistantes ; vérifie la transition de V1 à V6 (R grandit, S diminue).\n**Piège** : les dérivations de Lewis servent à voir l'activité atriale, pas à corriger les précordiales."},{"id":"231-qcm-006","type":"QRM","rank":"A","objective":"231-obj-01","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Concernant l'onde P sinusale normale, quelles propositions sont exactes ?","options":[{"t":"Sa durée normale est supérieure à 120 ms","ok":false,"why":"Inversé : P normale < 110 ms (en pratique 120) ; une P plus longue évoque une hypertrophie atriale gauche (p. 375, 406)."},{"t":"Elle est positive dans les dérivations inférieures","ok":true,"why":"Le nœud sinusal est en haut à droite de l'OD : l'activation descend vers la gauche, d'où P positive en D2, D3, aVF (p. 375-376)."},{"t":"Son axe normal est proche de 60°","ok":true,"why":"Axe de P = 60°, donc maximum en D2 (et amplitude normale < 2,5 mm en D2) (p. 375)."},{"t":"Elle est positive en D1","ok":true,"why":"Activation de droite à gauche : P positive en D1 ; une P négative en D1 doit faire penser à une inversion d'électrodes (p. 376, 383)."},{"t":"En rythme sinusal, chaque onde P est suivie d'un complexe QRS","ok":true,"why":"Rythme sinusal = P sinusale ET conduite : chaque P suivie d'un QRS, chaque QRS précédé d'une P ; des P régulières non conduites (BAV3) ne sont plus un rythme sinusal (p. 376)."}],"explanation":"L'onde P sinusale est positive en D1 et dans les dérivations inférieures, d'axe proche de 60°, de durée < 120 ms, et chaque P est suivie d'un QRS en rythme sinusal normal.","src":"p. 375-376","deep":"**Pourquoi** : le nœud sinusal est en haut à droite de l'OD, l'activation des oreillettes va donc vers le bas et la gauche : P positive en D1, D2, D3, aVF, axe 60° (maximum en D2) (p. 375-376).\n**À relier** : rythme sinusal = P positive en D1-D2 + chaque P suivie d'un QRS et chaque QRS précédé d'une P ; P < 120 ms et < 2,5 mm en D2.\n**Piège** : des P régulières non conduites (BAV3) ne font pas un rythme sinusal."},{"id":"231-qcm-007","type":"QRM","rank":"A","objective":"231-obj-01","tags":["physiopathologie","ECG"],"difficulty":2,"stem":"Concernant la séquence normale de dépolarisation ventriculaire, quelle proposition est exacte ?","options":[{"t":"La première phase, septale, explique la présence d'une petite onde positive en V1","ok":true,"why":"Le septum se dépolarise d'abord vers l'avant et la droite : petite onde positive en V1 et Q fine en latéral (p. 376)."},{"t":"Cette séquence rend le QRS strictement monophasique","ok":false,"why":"Faux : trois vecteurs successifs d'orientations différentes rendent le QRS polyphasique (p. 376)."},{"t":"La deuxième phase est orientée vers l'arrière et le haut","ok":false,"why":"Faux : la 2e phase va vers la jambe gauche et l'avant (grande R en V3-V4, D2) ; c'est la 3e qui va vers le haut et l'arrière (p. 376)."},{"t":"La phase septale est absente chez le sujet sain","ok":false,"why":"Faux : elle est physiologique et explique la Q fine latérale normale (< 40 ms, < 1/3 du QRS) (p. 375-376)."},{"t":"La troisième phase génère la plus grande amplitude du QRS","ok":false,"why":"Faux : la 3e phase ne donne qu'une petite S inférieure et latérale ; la grande R vient de la 2e phase (p. 376)."}],"explanation":"Le QRS normal résulte de trois phases successives (septale vers l'avant, la droite et le haut ; vers la jambe gauche et l'avant ; vers le haut et l'arrière) qui expliquent son caractère polyphasique.","src":"p. 375-376","deep":"**Pourquoi** : le QRS se décompose en 3 phases : (1) septale, vers l'avant/droite/haut : petite onde positive en V1 et Q fine en latéral ; (2) vers la jambe gauche et l'avant : grande R en V3-V4 et D2 ; (3) vers le haut et l'arrière : petite S inférieure/latérale (p. 375-376).\n**Astuce** : septum d'abord, grande R ensuite, petite S à la fin.\n**Piège** : ne pas inverser les phases 2 et 3."},{"id":"231-qcm-008","type":"QRM","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Parmi les aspects suivants en V1, lequel (ou lesquels) évoque(nt) un bloc complet de branche droite ?","options":[{"t":"Un aspect QS profond","ok":false,"why":"QS (ou rS) en V1 = QRS négatif, aspect du BBG ; le BBD est positif en V1 (p. 380-381)."},{"t":"Un QRS globalement positif avec un aspect RsR'","ok":true,"why":"BBD complet : QRS > 120 ms, V1 positif RsR', V6 qRs avec S traînante arrondie (p. 378)."},{"t":"Un sus-décalage isolé et majeur du segment ST","ok":false,"why":"Le BBD se définit par la durée et la morphologie du QRS ; le ST n'y est modifié que par la discordance appropriée (QRS positif → T négative avec petit sous-ST ; QRS négatif → T positive avec souvent petit sus-ST) (p. 378, 381)."},{"t":"Un QRS globalement négatif en rS","ok":false,"why":"rS négatif en V1 = BBG (avec notch en V6, D1, aVL) (p. 380)."},{"t":"Une onde delta","ok":false,"why":"L'onde delta (empâtement du pied du QRS) signe une préexcitation par voie accessoire, avec PR court (p. 410)."}],"explanation":"Le BBD complet associe une durée de QRS > 120 ms, un aspect RsR' positif en V1 et un aspect qRs avec onde S traînante en V6.","src":"p. 378-379","deep":"**Pourquoi** : dans le BBD complet (QRS > 120 ms), V1 est globalement positif avec un aspect RsR' et V6 montre un qRs avec S traînante, souvent arrondie (p. 378-379).\n**À relier** : BBG = V1 négatif (rS ou QS) et notch en V6, D1, aVL.\n**Astuce** : V1 positif = bloc droit, V1 négatif = bloc gauche.\n**Piège** : un QS en V1 appartient au BBG ; l'onde delta est un signe de préexcitation."},{"id":"231-qcm-009","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant la méthode rapide de détermination de l'axe du QRS à partir de la polarité de D1 et aVF, quelles propositions sont exactes ?","options":[{"t":"D1 et aVF positifs correspondent à un axe normal entre 0 et 90°","ok":true,"why":"D1 (0°) et aVF (+90°) positifs placent l'axe dans le cadran 0/+90°, inclus dans la norme -30/+90° (p. 375)."},{"t":"D1 et aVF négatifs correspondent à un axe extrême","ok":true,"why":"D1 et aVF négatifs = cadran -90/-180° : axe extrême ; en tachycardie à QRS larges (QRS positif en aVR) c'est un argument de TV (p. 375, 400)."},{"t":"L'axe normal du QRS se situe entre -90° et -180°","ok":false,"why":"Faux : -90/-180° est l'axe extrême ; la norme est -30/+90° (aVL à aVF) (p. 375)."},{"t":"Un axe hypergauche s'accompagne d'une négativité de D2","ok":true,"why":"Dans le cadran D1+/aVF-, D2 tranche : positif = axe normal (0/-30°), négatif = hypergauche (au-delà de -30°, ex. HBAG) (p. 375, 382)."},{"t":"D1 négatif et aVF positif correspondent à un axe hyperdroit","ok":true,"why":"D1-/aVF+ = 90-180° : hyperdroit (HBPG, HVD, longiligne… mais d'abord éliminer une inversion d'électrodes) (p. 375, 383, 407)."}],"explanation":"La méthode des quadrants D1/aVF permet de classer rapidement l'axe : normal, hyperdroit, hypergauche (selon D2) ou extrême.","src":"p. 375","deep":"**Pourquoi** : on regarde D1 (0°) et aVF (90°) : cela donne 4 cadrans. D1+ aVF+ = axe 0/90° normal ; D1+ aVF- = 0/-90° (normal si D2+, sinon hypergauche) ; D1- aVF+ = 90/180° hyperdroit ; D1- aVF- = extrême (p. 375).\n**Astuce** : D2 sert d'arbitre dans le cadran D1+/aVF-.\n**Piège** : l'axe normal va de -30 à +90° ; hypergauche = au-delà de -30° (D2 négatif)."},{"id":"231-qcm-011","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"stem":"Concernant les dérivations de l'ECG, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"aVR, aVL et aVF sont des dérivations bipolaires des membres","ok":false,"why":"Faux : aVR, aVL, aVF sont les dérivations dites unipolaires des membres, associées à D1, D2, D3 (p. 371)."},{"t":"V3R et V4R remplacent systématiquement V1 et V2","ok":false,"why":"Faux : V3R et V4R s'ajoutent (enfant, suspicion de SCA) pour explorer le VD, avec V1-V2 (p. 371, 374)."},{"t":"Les dérivations précordiales sont numérotées de V1 à V9","ok":true,"why":"Les précordiales (plan horizontal) vont de V1 à V9 ; V3R et V4R s'ajoutent chez l'enfant ou si l'on suspecte un SCA (p. 371)."},{"t":"Les dérivations frontales explorent le plan horizontal","ok":false,"why":"Faux : frontales (membres) = plan vertical ; précordiales = plan horizontal (p. 371)."},{"t":"Le plan horizontal est exploré par D1, D2 et D3","ok":false,"why":"Faux : D1, D2, D3 sont des dérivations frontales (plan vertical), utilisées pour l'axe (p. 371, 375)."}],"explanation":"Seules les dérivations précordiales V1 à V9 explorent le plan horizontal ; D1-D2-D3 et les dérivations unipolaires aVR/aVL/aVF explorent le plan frontal.","src":"p. 371","deep":"**Pourquoi** : les dérivations frontales (D1-D2-D3 et aVR-aVL-aVF, dites unipolaires) explorent le plan vertical ; les précordiales V1 à V9 explorent le plan horizontal (p. 371).\n**À relier** : V3R et V4R complètent chez l'enfant ou en cas de suspicion de SCA ; ECG 18 dérivations devant toute douleur thoracique.\n**Piège** : aVR/aVL/aVF sont unipolaires ; D1-D3 explorent le plan frontal, pas l'horizontal."},{"id":"231-qcm-012","type":"QRM","rank":"B","objective":"231-obj-01","tags":["physiopathologie","ECG"],"difficulty":2,"stem":"Concernant la polarité du signal électrocardiographique, quelles propositions sont exactes ?","options":[{"t":"Une onde de dépolarisation qui s'éloigne de l'électrode s'inscrit comme une négativité","ok":true,"why":"Règle de base : front qui s'éloigne = négatif, qui s'approche = positif (fig. 15.3, p. 371)."},{"t":"L'onde T normale a une polarité opposée à celle du QRS sur une même dérivation","ok":false,"why":"Faux : les T normales sont concordantes ; la discordance n'est « appropriée » qu'avec des QRS larges (bloc de branche) (p. 371, 381)."},{"t":"Cette concordance T-QRS s'explique par le sens inverse de la dépolarisation et de la repolarisation transmurales","ok":true,"why":"Dépolarisation endocarde → épicarde, repolarisation épicarde → endocarde : les deux fronts « inversés » donnent la même polarité (p. 371)."},{"t":"Un courant perpendiculaire à l'électrode donne une déflexion isodiphasique","ok":true,"why":"Le front s'approche puis s'éloigne de l'électrode : déflexion positive puis négative, d'amplitudes égales (fig. 15.3, p. 371)."},{"t":"Une onde de dépolarisation qui se dirige vers l'électrode s'inscrit comme une positivité","ok":true,"why":"Principe de l'ECG : un front qui vient vers l'électrode est positif ; c'est ce qui explique la P positive en D2 (p. 371, 375)."}],"explanation":"Le signal ECG dépend de l'orientation du front de dépolarisation par rapport à l'électrode ; la concordance T-QRS normale s'explique par le sens opposé de la dépolarisation et de la repolarisation transmurales.","src":"p. 371","deep":"**Pourquoi** : un front de dépolarisation qui va vers l'électrode s'inscrit positif, qui s'en éloigne négatif, perpendiculaire isodiphasique. La T est concordante au QRS car la dépolarisation va de l'endocarde vers l'épicarde et la repolarisation en sens inverse (p. 371).\n**Piège** : « contre toute attente », T et QRS ont la même polarité (T positive si QRS positif).\n**À relier** : avec un QRS large (bloc de branche), la concordance disparaît : discordance appropriée."},{"id":"231-qcm-013","type":"QRM","rank":"A","objective":"231-obj-01","tags":["définition","ECG"],"difficulty":1,"stem":"Concernant l'étalonnage standard de l'enregistrement ECG, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"1 mm d'amplitude correspond à 1 mV","ok":false,"why":"Faux : 1 mm = 0,1 mV ; c'est avec cet étalonnage qu'on lit Sokolow (< 35 mm) ou la P (< 2,5 mm) (p. 375)."},{"t":"Un grand carreau correspond à 40 ms","ok":false,"why":"Faux : grand carreau (5 mm) = 200 ms ; 40 ms = petit carreau (p. 375)."},{"t":"La vitesse standard est de 50 mm/s","ok":false,"why":"Faux : 25 mm/s (40 ms/mm) ; c'est ce qui donne FC = 300 / grands carreaux (p. 375-376)."},{"t":"La vitesse standard est de 25 mm/s, soit un grand carreau pour 200 ms","ok":true,"why":"À 25 mm/s, 1 mm = 40 ms, donc un grand carreau de 5 mm = 200 ms ; d'où FC = 300 / nombre de grands carreaux (p. 375-376)."},{"t":"Un petit carreau correspond à 200 ms","ok":false,"why":"Faux : petit carreau = 40 ms ; 200 ms = grand carreau, soit la borne haute du PR (p. 375-376)."}],"explanation":"L'étalonnage standard est 25 mm/s (grand carreau = 200 ms, petit carreau = 40 ms) et 1 mm = 0,1 mV en amplitude.","src":"p. 375","deep":"**Pourquoi** : à 25 mm/s, 1 mm = 40 ms, donc un grand carreau (5 mm) = 200 ms ; en amplitude 1 mm = 0,1 mV (p. 375).\n**À relier** : FC = 300 / nombre de grands carreaux entre 2 QRS (1 carreau = 300 bpm, 2 = 150).\n**Astuce** : PR normal 120-200 ms = 3 à 5 petits carreaux, soit un grand carreau au maximum.\n**Piège** : confondre petit carreau (40 ms) et grand carreau (200 ms)."},{"id":"231-qcm-014","type":"QRM","rank":"A","objective":"231-obj-01","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant l'onde Q physiologique et les critères d'amplitude normaux, quelles propositions sont exactes ?","options":[{"t":"Une onde Q physiologique dure moins de 40 ms","ok":true,"why":"La Q physiologique reflète la dépolarisation septale initiale : fine (< 40 ms) et peu profonde (< 1/3 du QRS) (tableau 15.2, p. 375)."},{"t":"Une onde Q physiologique représente moins d'1/3 de l'amplitude du QRS","ok":true,"why":"Second critère : profondeur < 1/3 du QRS, en plus de la durée < 40 ms ; les deux sont nécessaires (p. 375, 377)."},{"t":"Une onde Q large (> 40 ms) et profonde (> 1/3 du QRS) évoque une séquelle de nécrose","ok":true,"why":"Au-delà de ces deux seuils (durée > 40 ms et profondeur > 1/3 du QRS), la Q n'est plus septale mais de nécrose (p. 377)."},{"t":"Une onde Q physiologique est toujours présente en V1","ok":false,"why":"Faux : la phase septale donne une petite onde positive en V1 ; la Q fine physiologique est latérale (p. 376)."},{"t":"Le critère de Sokolov normal est inférieur à 35 mm","ok":true,"why":"Sokolow (S en V1/V2 + R en V5/V6) < 35 mm fait partie de la vérification morphologique d'un ECG normal ; au-delà, HVG (p. 377, 406)."}],"explanation":"L'onde Q physiologique est fine (< 40 ms) et peu profonde (< 1/3 du QRS) ; au-delà, elle évoque une séquelle de nécrose. Le critère de Sokolov normal est < 35 mm.","src":"p. 375-377","deep":"**Pourquoi** : une Q physiologique est fine (< 40 ms) ET peu profonde (< 1/3 du QRS) ; elle reflète la dépolarisation septale initiale en latéral. Une Q large (> 40 ms) et profonde (> 1/3) évoque une séquelle de nécrose (p. 375-377).\n**À relier** : Sokolow normal < 35 mm.\n**Piège** : p. 412 (SCA), le Collège donne une autre version des Q de nécrose : au moins 1/3 (ou 1/4) du QRS et > 30-40 ms ; les deux versions coexistent. Les deux critères (durée ET amplitude) sont nécessaires ; V1 ne montre pas de Q physiologique mais une petite onde r."},{"id":"231-qcm-015","type":"QRM","rank":"A","objective":"231-obj-01","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant la repolarisation normale, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Une onde T négative isolée en D3 est toujours pathologique","ok":false,"why":"Faux : une T négative isolée en D3 (ou aVL) peut être normale ; ce sont deux T négatives d'un même territoire qui sont pathologiques (p. 377, 411)."},{"t":"Le segment ST doit être nettement sous-décalé au point J chez le sujet normal","ok":false,"why":"Faux : point J et ST sont isoélectriques ; un sous-ST oriente vers une lésion sous-endocardique (SCA sans sus-ST) (p. 377, 412)."},{"t":"Le QT normal doit être supérieur à 450 ms","ok":false,"why":"Inversé : QT < 450 ms ; un QT long fait vérifier médicaments et ionogramme (p. 377, 404)."},{"t":"Le point J ne peut jamais être sus-décalé chez le sujet sain","ok":false,"why":"Faux : chez le jeune, surtout l'homme, un J sus-décalé V1-V4 avec ST ascendant est une repolarisation physiologique (p. 377)."},{"t":"Les ondes T sont positives dans toutes les dérivations sauf en aVR et V1","ok":true,"why":"T concordantes aux QRS : positives partout sauf aVR et V1 (parfois D3 et aVL) ; deux T négatives dans un même territoire sont pathologiques (p. 377, 411)."}],"explanation":"La repolarisation normale se caractérise par un point J et un ST isoélectriques, des ondes T positives partout sauf aVR/V1 (et parfois D3/aVL), et un QT < 450 ms.","src":"p. 377","deep":"**Pourquoi** : repolarisation normale = point J et ST isoélectriques, T positives partout sauf en aVR et V1 (parfois D3 et aVL), QT < 450 ms (p. 377).\n**À relier** : chez le jeune, surtout l'homme, un J sus-décalé de V1 à V4 avec ST ascendant est une repolarisation physiologique.\n**Piège** : une T négative isolée en D3 peut être normale, mais deux T négatives dans un même territoire (D2 et D3) sont pathologiques."},{"id":"231-qru-001","type":"QRU","rank":"A","objective":"231-obj-01","tags":["définition"],"difficulty":1,"stem":"Quelle est la fréquence cardiaque de repos considérée comme normale chez l'adulte ?","options":[{"t":"Entre 100 et 150 bpm","ok":false,"why":"Au-delà de 100 bpm = tachycardie ; au repos sans cause (fièvre, stress, douleur), elle fait chercher un trouble du rythme (p. 376, 391)."},{"t":"Entre 60 et 100 bpm","ok":true,"why":"Norme de repos de l'adulte : 60-100 bpm ; le nouveau-né fait exception, l'athlète a une bradycardie sinusale physiologique (tonus vagal) (p. 376)."},{"t":"Plus de 150 bpm","ok":false,"why":"Franche tachycardie ; 150 bpm est d'ailleurs la cadence typique d'un flutter conduit en 2/1 (p. 376, 394)."},{"t":"Elle varie sans aucune limite définie","ok":false,"why":"Faux : bornes fixes, < 60 bpm = bradycardie et > 100 bpm = tachycardie (p. 376)."},{"t":"Moins de 60 bpm","ok":false,"why":"< 60 bpm = bradycardie (physiologique chez l'athlète par tonus vagal) (p. 376)."}],"explanation":"La fréquence cardiaque de repos normale de l'adulte est comprise entre 60 et 100 bpm ; en dessous c'est une bradycardie, au-dessus une tachycardie.","src":"p. 376","deep":"**Pourquoi** : la FC de repos normale de l'adulte est de 60 à 100 bpm ; le nouveau-né fait exception (p. 376).\n**À relier** : athlète = bradycardie sinusale physiologique (tonus vagal important) ; sujet jeune = variation de la fréquence avec la respiration.\n**Piège** : bradycardie = FC < 60, tachycardie = FC > 100 (p. 376) ; mais l'algorithme de la bradycardie (fig. 15.27, p. 389) utilise FC < 50 bpm : deux seuils coexistent dans le Collège."},{"id":"231-qru-002","type":"QRU","rank":"A","objective":"231-obj-01","tags":["définition","ECG"],"difficulty":1,"stem":"Quel est l'axe normal de l'onde P sinusale ?","options":[{"t":"60°","ok":true,"why":"L'onde P normale a un axe à 60°, avec une positivité maximale en D2, car le nœud sinusal est situé en haut à droite de l'oreillette droite."},{"t":"0°","ok":false,"why":"Un axe à 0° pointerait vers D1 ; or l'activation atriale descend du nœud sinusal (haut de l'OD) vers le bas et la gauche, d'où 60° (p. 375)."},{"t":"120°","ok":false,"why":"120° est un axe dirigé vers la droite (proche de D3) ; l'onde P normale est à 60°, maximale en D2 (p. 375)."},{"t":"90°","ok":false,"why":"90° donnerait une positivité maximale en aVF ; l'onde P normale est à 60°, maximale en D2 (p. 375)."},{"t":"30°","ok":false,"why":"30° est trop horizontal : l'onde P sinusale est orientée à 60° (D2), le nœud sinusal étant en haut à droite de l'OD (p. 375)."}],"explanation":"L'onde P sinusale normale a un axe de 60°, avec une positivité maximale en D2, du fait de la position du nœud sinusal en haut à droite de l'oreillette.","src":"p. 375","deep":"**Pourquoi** : le nœud sinusal est en haut à droite de l'OD ; l'activation va vers le bas et la gauche : axe de P = 60°, positivité maximale en D2 (p. 375).\n**Astuce** : P = 60° (D2) ; QRS = -30 à +90°.\n**Piège** : ne pas confondre l'axe de P (60°) avec l'axe du QRS."},{"id":"231-qru-003","type":"QRU","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":2,"stem":"Pour mesurer l'intervalle QT, quelles dérivations le livre recommande-t-il de privilégier ?","options":[{"t":"D1","ok":false,"why":"D1 n'a rien de privilégié : on choisit la dérivation où T est la plus ample et la plus longue, souvent V2-V3 (p. 376)."},{"t":"V6","ok":false,"why":"On ne choisit pas une dérivation fixe : on prend celle où la T est la plus ample et la plus longue, souvent V2-V3 (p. 376)."},{"t":"aVR","ok":false,"why":"En aVR la T est normalement négative et peu ample : mauvaise dérivation pour repérer la fin de T (p. 376-377)."},{"t":"aVL","ok":false,"why":"En aVL la T peut être physiologiquement négative ; on préfère la T la plus ample et la plus longue (souvent V2-V3) (p. 376-377)."},{"t":"V2-V3","ok":true,"why":"On mesure le QT là où la T est la plus ample et la plus longue (souvent V2-V3), en traçant la tangente à la fin de T, sans l'onde U (p. 376-377)."}],"explanation":"Pour mesurer le QT, il faut choisir la dérivation où l'onde T est la plus ample et la plus longue, souvent V2-V3, et tracer la tangente à l'onde T.","src":"p. 376","deep":"**Pourquoi** : on mesure le QT du début de Q à la fin de T dans la dérivation où T est la plus ample et la plus longue (souvent V2-V3), en traçant la tangente à la T (p. 376).\n**À relier** : ne pas inclure l'onde U ; puis correction par Bazett.\n**Piège** : aVR a une T négative et D1 n'est pas la dérivation de choix : on cherche la meilleure T, pas une dérivation « par défaut »."},{"id":"231-qru-004","type":"QRU","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":2,"stem":"Quelle formule permet de calculer le QT corrigé (QTc) selon Bazett ?","options":[{"t":"QTc = QT mesuré × intervalle RR","ok":false,"why":"Bazett divise par la racine du RR : à 60 bpm (RR = 1 s) le QTc égale le QT mesuré ; une multiplication ne normalise rien (p. 377)."},{"t":"QTc = QT mesuré / fréquence cardiaque","ok":false,"why":"Faux : Bazett divise par la racine carrée du RR en secondes, pas par la FC ; à 60 bpm le QTc égale le QT (p. 377)."},{"t":"QTc = QT mesuré / racine carrée de l'intervalle RR (en secondes)","ok":true,"why":"Bazett ramène le QT à une FC de 60 bpm (RR = 1 s), ce qui permet une norme unique (QTc < 450 ms) au lieu d'abaques (p. 377)."},{"t":"QTc = QT mesuré − intervalle RR","ok":false,"why":"Faux : ce n'est pas une soustraction mais QT / racine du RR (s) (p. 377)."},{"t":"QTc = QT mesuré × fréquence cardiaque","ok":false,"why":"Faux : on divise le QT par la racine carrée du RR exprimé en secondes, pas par (ni avec) la FC (p. 377)."}],"explanation":"La formule de Bazett normalise le QT mesuré en le divisant par la racine carrée de l'intervalle RR (en secondes), pour obtenir une valeur comparable à une fréquence de 60 bpm.","src":"p. 377","deep":"**Pourquoi** : le QT varie avec la FC ; Bazett le ramène à une FC de 60 bpm (RR = 1 s) : QTc = QT / racine carrée du RR (en secondes) (p. 377).\n**Astuce** : à 60 bpm, RR = 1 s donc QTc = QT mesuré (racine de 1 = 1).\n**À relier** : QTc normal < 450 ms.\n**Piège** : c'est une division par la racine carrée du RR en SECONDES, pas par la FC."},{"id":"231-qru-005","type":"QRU","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Un homme de 58 ans a un ECG systématique : QRS à 140 ms, en V1 un aspect globalement positif de type RsR', en V6 un aspect qRs avec une onde S traînante. Quel est le diagnostic le plus probable ?","options":[{"t":"Bloc atrioventriculaire du 1er degré","ok":false,"why":"Le BAV1 touche le PR (> 200 ms fixe), pas la morphologie du QRS (p. 386)."},{"t":"Hémibloc antérieur gauche isolé","ok":false,"why":"Un HBAG isolé élargit à peine le QRS (> 110 ms) et dévie l'axe à gauche, sans RsR' en V1 (p. 382)."},{"t":"Extrasystole ventriculaire isolée","ok":false,"why":"Une ESV est un battement prématuré isolé à QRS large ; ici l'aspect est stable sur tout le tracé (p. 397)."},{"t":"Bloc complet de branche gauche","ok":false,"why":"Le BBG est négatif en V1 (rS/QS) avec notch en V6 ; RsR' positif en V1 = BBD (p. 380)."},{"t":"Bloc complet de branche droite","ok":true,"why":"L'association QRS > 120 ms, RsR' positif en V1 et qRs avec onde S traînante en V6 est la définition du bloc complet de branche droite."}],"explanation":"L'aspect RsR' positif en V1 associé à un qRs avec onde S traînante en V6 et un QRS > 120 ms définit le bloc complet de branche droite.","src":"p. 378-379","deep":"**Pourquoi** : QRS > 120 ms + V1 globalement positif RsR' + V6 qRs avec S traînante = bloc complet de branche DROITE (p. 378-379).\n**À relier** : BBG = V1 rS/QS négatif ; hémibloc = QRS à peine élargi avec déviation axiale.\n**Piège** : décris d'abord le rythme atrial (une tachycardie supraventriculaire peut s'associer à un bloc de branche) ; un bloc de branche seul est sans conséquence immédiate, à ne pas confondre avec une TV."},{"id":"231-qroc-002","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":1,"question":"Quelle formule pratique permet d'estimer la fréquence cardiaque à partir du nombre de grands carreaux séparant deux QRS ?","answer":"FC = 300 / nombre de grands carreaux","accept":["300 divisé par le nombre de grands carreaux","300/nombre de grands carreaux","300 / nb de grands carreaux","300/nb de grands carreaux"],"keywords":["300","grands carreaux"],"explanation":"À 25 mm/s, un grand carreau vaut 200 ms : RR d'un carreau = 300 bpm, deux = 150, trois = 100, etc. ; formule exacte FC = 60 / RR (s) (p. 375-376).","src":"p. 376","deep":"**Pourquoi** : un intervalle RR d'un grand carreau = 300 bpm, de deux = 150, de trois = 100, etc. : FC = 300 / nombre de grands carreaux (p. 376).\n**À relier** : formule exacte FC = 60 / période (RR en secondes).\n**Piège** : compte des GRANDS carreaux (5 mm = 200 ms), pas des petits."},{"id":"231-qroc-003","type":"QROC","rank":"A","objective":"231-obj-01","tags":["définition"],"difficulty":2,"question":"Quel intervalle explore la totalité de la conduction depuis la sortie du nœud sinusal jusqu'aux extrémités du réseau de Purkinje ?","answer":"L'intervalle PR","accept":["intervalle PR","espace PR","PR","l'espace PR"],"keywords":["pr"],"explanation":"Le PR (début de P → début du QRS) explore toute la conduction, de la sortie du nœud sinusal au réseau de Purkinje, pas seulement le NAV ; normal 120-200 ms (p. 376).","src":"p. 376","deep":"**Pourquoi** : le PR (début de P au début de QRS) explore toute la conduction, de la sortie du nœud sinusal jusqu'aux extrémités du réseau de Purkinje (p. 376).\n**À relier** : normal 120-200 ms ; > 200 = BAV1 ; < 120 ms = PR court, un des signes de préexcitation avec l'onde delta (p. 410).\n**Piège** : croire que le PR ne mesure que la traversée du nœud atrioventriculaire."},{"id":"231-qroc-004","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":1,"question":"Quelle formule, préférée aux abaques, permet de corriger l'intervalle QT en fonction de la fréquence cardiaque ?","answer":"La formule de Bazett","accept":["Bazett","formule de Bazett","QT / racine du RR"],"keywords":["bazett"],"explanation":"Le QT varie avec la FC : Bazett (QT / racine du RR en s) le ramène à 60 bpm, ce qui donne une norme unique (QTc < 450 ms) au lieu d'abaques (p. 377).","src":"p. 377","deep":"**Pourquoi** : le QT dépend de la FC ; plutôt que des abaques, on le normalise avec la formule de Bazett : QTc = QT / racine du RR (s), pour une seule norme à 60 bpm (p. 377).\n**À relier** : QTc < 450 ms à 60 bpm (en pratique 470-480) ; mesure en V2-V3 sans l'onde U.\n**Piège** : ne jamais intégrer l'onde U dans le QT."},{"id":"231-qroc-005","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quel est l'axe normal du QRS en pratique clinique ?","answer":"Entre -30° et +90°","accept":["-30 à 90 degrés","de -30° à +90°","-30 à +90","entre -30 et +90 degrés","-30° à 90°"],"keywords":["-30","90"],"explanation":"Axe normal -30° à +90° (aVL à aVF) en valeurs arrondies (-45/+110° exactement) ; au-delà de -30° = hypergauche (HBAG), au-delà de +90° = hyperdroit (p. 375, 382).","src":"p. 375","deep":"**Pourquoi** : l'axe normal du QRS est arrondi à -30° / +90° en pratique (aVL à aVF) ; valeurs « exactes » -45 à +110° (p. 375).\n**À relier** : au-delà de -30° = hypergauche (HBAG) ; au-delà de +90° = hyperdroit (HBPG, HVD).\n**Piège** : « 0 à 90° » ne correspond qu'au cadran D1+/aVF+ ; la norme descend jusqu'à -30°."},{"id":"231-qroc-006","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":2,"question":"Quelles sont les deux dérivations utilisées dans la méthode rapide de détermination de l'axe du QRS ?","answer":"D1 et aVF","accept":["DI et aVF","D1-aVF","D1 aVF","DI, aVF","D1 et AVF","I et aVF"],"keywords":["d1","avf"],"explanation":"D1 (0°) et aVF (+90°) découpent le plan frontal en 4 cadrans ; dans le cadran D1+/aVF-, D2 tranche entre normal et hypergauche (p. 375).","src":"p. 375","deep":"**Pourquoi** : D1 (0°, horizontale) et aVF (90°, verticale) découpent le plan frontal en 4 cadrans, d'où l'axe en un coup d'œil (p. 375).\n**À relier** : D1+ aVF+ normal ; D1+ aVF- = D2 tranche (D2+ normal, sinon hypergauche) ; D1- aVF+ hyperdroit ; D1- aVF- extrême.\n**Piège** : D2 n'intervient que dans le cadran D1+/aVF-."},{"id":"231-qroc-007","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":3,"question":"Comment se nomment les dérivations obtenues par un repositionnement particulier des électrodes pour mieux visualiser l'activité atriale ?","answer":"Les dérivations de Lewis","accept":["dérivations de Lewis","Lewis leads","Lewis","dérivation de Lewis","les dérivations de Lewis"],"keywords":["lewis"],"explanation":"Dérivations de Lewis : électrode bras droit sur la fourchette sternale, bras gauche au 5e EIC droit ; l'activité atriale se lit alors en D1 (fig. 15.6, p. 373).","src":"p. 373","deep":"**Pourquoi** : quand l'activité atriale est difficile à voir, on déplace les électrodes (bras droit sur la fourchette sternale, bras gauche au 5e EIC droit) : elle devient lisible en D1 (p. 373).\n**À relier** : autre aide pour démasquer l'activité atriale : les manœuvres vagales.\n**Piège** : la dérivation de lecture est D1 (pas V1)."},{"id":"231-qroc-009","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quel territoire cardiaque est exploré par les dérivations V7, V8 et V9 ?","answer":"Le territoire postérieur du ventricule gauche","accept":["postérieur","territoire postérieur basal et inférieur","territoire postérieur","face basale et inférieure","paroi postérieure"],"keywords":["posterieur"],"explanation":"V7-V9, posées dans le dos, explorent la face basale et inférieure (postérieure) du VG ; un sous-ST V1-V3 peut être le miroir d'un sus-ST postérieur (p. 374, 411).","src":"p. 374","deep":"**Pourquoi** : V7-V9 sont posées dans le dos et explorent la face basale et inférieure (postérieure) du VG (p. 374).\n**À relier** : un sous-décalage en V1-V3 peut être le miroir d'un sus-décalage postérieur : ECG 18 dérivations devant toute douleur thoracique.\n**Piège** : ne pas confondre V7-V9 (postérieur) avec V3R-V4R (ventricule droit)."},{"id":"231-qroc-010","type":"QROC","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":1,"question":"À partir de quelle durée de QRS parle-t-on de bloc de branche complet plutôt qu'incomplet ?","answer":"120 ms","accept":["> 120 ms","120 millisecondes","plus de 120 ms","supérieur à 120 ms","120"],"keywords":["120"],"explanation":"Bloc complet = QRS > 120 ms ; entre 110 et 120 ms, mêmes aspects mais bloc incomplet, de faible intérêt sémiologique (p. 378, 381).","src":"p. 378","deep":"**Pourquoi** : bloc de branche complet = QRS > 120 ms ; bloc incomplet = QRS entre 110 et 120 ms avec les mêmes aspects (faible intérêt sémiologique) (p. 378).\n**À relier** : QRS normal 70-110 ms ; hémibloc = QRS > 110 ms à peine élargi.\n**Piège** : la limite du bloc complet est 120 ms, pas 110."},{"id":"231-qroc-011","type":"QROC","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":1,"question":"Quel aspect caractéristique retrouve-t-on en V1 dans le bloc complet de branche droite ?","answer":"Un aspect RsR' avec QRS globalement positif","accept":["RsR'","aspect RSR prime","rSR'","RSR'","rsR'","RsR' en V1","QRS positif RsR'"],"keywords":["rsr"],"explanation":"BBD complet : QRS > 120 ms, V1 globalement positif RsR', V6 qRs avec S traînante ; V1 négatif (rS/QS) = BBG (p. 378, 380).","src":"p. 378-379","deep":"**Pourquoi** : dans le BBD complet (QRS > 120 ms), V1 est globalement positif avec un aspect RsR' ; en V6 on voit un qRs avec S traînante, arrondie (p. 378-379).\n**Astuce** : V1 positif = droit, V1 négatif = gauche.\n**À relier** : BBG = V1 rS/QS négatif + notch en V6, D1, aVL.\n**Piège** : vérifie d'abord le rythme (sinusal ?) puis QRS > 120 ms, avant de regarder V1."},{"id":"231-qroc-012","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quelle est la valeur seuil normale du critère de Sokolov utilisée pour vérifier la morphologie de l'ECG ?","answer":"Moins de 35 mm","accept":["< 35 mm","inférieur à 35 mm","35 mm","35","< 35"],"keywords":["35"],"explanation":"Sokolow = S en V1/V2 + R en V5/V6, normal < 35 mm ; au-delà, HVG (HTA puis rétrécissement aortique) (p. 377, 406-407).","src":"p. 377","deep":"**Pourquoi** : Sokolow = onde S en V1 ou V2 + onde R en V5 ou V6 ; normal < 35 mm, au-delà évoque une HVG (p. 377).\n**À relier** : HVG sévère = T négative + ST sous-décalé en latéral (D1, aVL, V5, V6) ; peut mimer une pseudonécrose en V1-V2.\n**Piège** : c'est S (V1/V2) + R (V5/V6), pas l'inverse."},{"id":"231-open-01","type":"OPEN","rank":"A","objective":"231-obj-01","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Un homme de 45 ans, asymptomatique, réalise un ECG systématique lors d'un bilan de santé. Le tracé montre un rythme régulier à 72 bpm avec une onde P positive en D1, D2 et aVF précédant chaque QRS, un espace PR à 160 ms, des QRS fins à 90 ms d'axe +45°, un segment ST isoélectrique, des ondes T positives sauf en aVR, et un QT à 400 ms. Décrivez la démarche systématique permettant d'affirmer que cet ECG est normal, en analysant successivement le rythme, la conduction, la repolarisation et la morphologie.","rubric":[{"point":"Rythme : onde P positive en D1/D2/aVF, un QRS après chaque P et une P avant chaque QRS, fréquence 60-100 bpm → rythme sinusal normal","weight":2},{"point":"Conduction : durée de P < 120 ms, PR 120-200 ms (ici 160 ms, normal)","weight":1.5},{"point":"Conduction : QRS fins 70-110 ms (ici 90 ms) avec axe entre -30° et +90° (ici +45°, normal)","weight":1.5},{"point":"Repolarisation : point J et segment ST isoélectriques, ondes T positives sauf aVR/V1, QT < 450 ms (ici 400 ms)","weight":2},{"point":"Morphologie : amplitude des ondes P et QRS normale (Sokolov < 35 mm), transition R/S normale en précordial, absence d'onde Q de nécrose","weight":1.5},{"point":"Conclusion explicite : ECG normal car les quatre étapes (rythme, conduction, repolarisation, morphologie) sont toutes normales","weight":1.5}],"model":"**Rythme** : l'onde P est positive en D1, D2 et aVF, chaque QRS est précédé d'une onde P et chaque onde P est suivie d'un QRS, à une fréquence de 72 bpm (60-100 bpm) : il s'agit d'un rythme sinusal normal.\n\n**Conduction** : le PR à 160 ms est dans la norme (120-200 ms) et les QRS fins à 90 ms respectent la fourchette normale (70-110 ms) avec un axe à +45°, compris entre -30° et +90°.\n\n**Repolarisation** : le segment ST est isoélectrique au point J, les ondes T sont positives dans toutes les dérivations sauf en aVR (physiologique), et le QT à 400 ms est inférieur à 450 ms.\n\n**Morphologie** : en l'absence de précision contraire, on vérifie l'amplitude des ondes P et des QRS (Sokolov < 35 mm), une transition R/S normale de V1 à V6, et l'absence d'onde Q de nécrose (large > 40 ms et profonde > 1/3 du QRS).\n\n**Conclusion** : les quatre étapes systématiques étant toutes normales, cet ECG est normal.","src":"p. 376-378"},{"id":"231-open-02","type":"OPEN","rank":"A","objective":"231-obj-01","tags":["ECG","diagnostic"],"difficulty":2,"prompt":"Expliquez la méthode rapide de détermination de l'axe du QRS à partir de la polarité de D1 et aVF, puis appliquez-la au cas suivant : D1 positif, aVF négatif, D2 négatif.","rubric":[{"point":"Principe : regarder la polarité de D1 et aVF pour situer l'axe dans l'un des quatre cadrans","weight":2},{"point":"Cadran D1+/aVF+ : axe normal entre 0 et 90°","weight":1},{"point":"Cadran D1+/aVF- : axe entre 0 et -90°, à préciser avec D2 (normal si D2+, hypergauche si D2-)","weight":2},{"point":"Cadran D1-/aVF+ : axe hyperdroit entre 90 et 180°","weight":1},{"point":"Cadran D1-/aVF- : axe extrême entre -90 et -180°","weight":1},{"point":"Application au cas donné : D1+, aVF-, D2- → axe hypergauche","weight":2}],"model":"La méthode rapide consiste à regarder la polarité de D1 et aVF pour situer l'axe du QRS dans l'un des quatre cadrans du plan frontal :\n- D1 et aVF positifs → axe normal entre 0 et 90° ;\n- D1 positif et aVF négatif → axe entre 0 et -90° ; on précise alors avec D2 : si D2 est positif, l'axe reste normal (entre 0 et -30°), sinon l'axe est hypergauche ;\n- D1 négatif et aVF positif → axe hyperdroit entre 90 et 180° ;\n- D1 et aVF négatifs → axe extrême entre -90° et -180°.\n\n**Application** : D1 positif et aVF négatif place l'axe dans le cadran 0 à -90°. Comme D2 est négatif, l'axe n'est pas simplement normal mais **hypergauche** (au-delà de -30°).","src":"p. 375"},{"id":"231-open-04","type":"OPEN","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Énumérez les critères électrocardiographiques du bloc complet de branche droite et expliquez pourquoi ce diagnostic peut, à tort, faire évoquer une autre pathologie si l'analyse est trop rapide.","rubric":[{"point":"Critère 1 : durée du QRS > 120 ms","weight":1.5},{"point":"Critère 2 : aspect RsR' globalement positif en V1","weight":1.5},{"point":"Critère 3 : aspect qRs avec onde S traînante en V6","weight":1.5},{"point":"Nécessité de vérifier d'abord le rythme atrial avant de décrire un trouble de conduction","weight":1.5},{"point":"Risque de méconnaître une tachycardie supraventriculaire associée si l'analyse se limite au QRS large","weight":2}],"model":"Le bloc complet de branche droite se reconnaît sur trois critères : une durée de QRS supérieure à 120 ms, un aspect globalement positif de type RsR' en V1, et un aspect qRs avec une onde S traînante et arrondie en V6.\n\nAvant de décrire ce trouble de conduction, il faut toujours commencer par analyser le rythme atrial : l'association d'une tachycardie supraventriculaire et d'un bloc de branche n'est pas rare, et une analyse trop rapide centrée sur le seul élargissement du QRS risquerait de faire passer à côté d'un trouble du rythme supraventriculaire sous-jacent.","src":"p. 378"},{"id":"231-qcm-101","type":"QRM","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant le bloc complet de branche gauche (BBG), quelles propositions sont exactes ?","options":[{"t":"Le BBG ne modifie jamais l'analyse de la repolarisation","ok":false,"why":"Faux : la discordance appropriée du BBG rend la repolarisation antérieure difficile à lire et peut mimer un SCA ST+ (p. 381)."},{"t":"En V1, le QRS est globalement négatif, en aspect rS ou QS","ok":true,"why":"Aspect du BBG en V1 (QRS négatif) ; positif en V1 = BBD (p. 380-381)."},{"t":"En V6, D1 et aVL, on observe un notch avec le plus souvent une onde R exclusive","ok":true,"why":"Notch = double pic : septum puis paroi latérale activée tardivement ; cette activation tardive explique la désynchronisation du VG (p. 380, 383)."},{"t":"La durée du QRS est supérieure à 120 ms","ok":true,"why":"Tout bloc de branche complet a un QRS > 120 ms ; 110-120 ms = incomplet (p. 380-381)."},{"t":"En V1, le QRS est globalement positif avec un aspect RsR'","ok":false,"why":"Faux : RsR' positif en V1 = BBD ; le BBG est négatif en V1 (p. 378, 380)."}],"explanation":"Le BBG complet associe QRS > 120 ms, aspect rS/QS négatif en V1, et notch avec onde R exclusive en V6, D1, aVL ; il s'accompagne d'un trouble secondaire de la repolarisation.","src":"p. 380","deep":"**Pourquoi** : BBG complet = QRS > 120 ms, V1 globalement négatif (rS ou QS), notch en V6, D1, aVL (double pic : septum puis paroi latérale tardive) avec R exclusive (p. 380).\n**À relier** : le trouble de dépolarisation entraîne un trouble de repolarisation (discordance appropriée) : l'antérieur devient difficile à interpréter.\n**Piège** : un RsR' positif en V1 est un BBD, pas un BBG."},{"id":"231-qcm-102","type":"QRM","rank":"A","objective":"231-obj-06","tags":["diagnostic","pièges"],"difficulty":1,"stem":"Concernant l'interprétation d'un ECG avec QRS larges suspects de bloc de branche, quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Il n'est pas nécessaire de vérifier le rythme atrial avant de décrire le trouble de conduction","ok":false,"why":"Faux : décrire d'abord le rythme atrial, car une TSV associée à un bloc de branche n'est pas rare (p. 378)."},{"t":"L'aspect en V6 doit être identique à celui de V1","ok":false,"why":"Faux : V6 montre l'aspect inverse de V1 (BBD : V1 positif, V6 qRs ; BBG : V1 négatif, V6 R exclusive) (p. 381)."},{"t":"Un QRS globalement négatif en V1 oriente vers un bloc de branche droit","ok":false,"why":"Faux : V1 négatif = bloc gauche ; V1 positif = bloc droit (p. 381)."},{"t":"Il faut vérifier dans l'ordre : rythme sinusal, durée du QRS, aspect en V1, aspect en V6","ok":true,"why":"Ordre du Collège : rythme d'abord (une TSV avec bloc de branche n'est pas rare), puis QRS > 120 ms, puis V1 (positif = droit, négatif = gauche), puis aspect inverse en V6 (p. 378, 381)."},{"t":"Un QRS globalement positif en V1 oriente vers un bloc de branche gauche","ok":false,"why":"Faux : V1 positif = bloc droit (RsR') ; le BBG est négatif en V1 (p. 381)."}],"explanation":"La démarche systématique est : rythme sinusal, durée QRS > 120 ms, aspect en V1 (positif = BBD probable, négatif = BBG probable), puis vérification de l'aspect inverse en V6.","src":"p. 381","deep":"**Pourquoi** : démarche systématique : rythme sinusal, QRS > 120 ms, aspect en V1 (positif = BBD probable, négatif = BBG probable), puis aspect inverse en V6 (p. 381).\n**À relier** : décris toujours le rythme atrial d'abord : une tachycardie supraventriculaire associée à un bloc de branche n'est pas rare.\n**Piège** : V6 doit être l'inverse de V1, pas identique."},{"id":"231-qcm-103","type":"QRM","rank":"A","objective":"231-obj-06","tags":["diagnostic","urgence","pièges"],"difficulty":3,"stem":"Concernant la discordance appropriée observée dans les blocs de branche, quelles propositions sont exactes ?","options":[{"t":"Cette discordance appropriée ne peut jamais faire évoquer à tort un syndrome coronarien aigu","ok":false,"why":"Faux : avec un ST ascendant en V1-V2, la discordance du BBG peut faire évoquer à tort un SCA ST+ (p. 381)."},{"t":"Elle correspond à une polarité opposée entre le QRS et l'onde T","ok":true,"why":"Un QRS large = dépolarisation anormale, donc repolarisation secondairement anormale : T de polarité opposée au QRS (p. 381)."},{"t":"Si le QRS est positif, l'onde T est négative avec un petit sous-décalage de ST","ok":true,"why":"Discordance appropriée : QRS positif, T négative avec petit sous-ST (et l'inverse si QRS négatif) ; c'est attendu, pas ischémique (p. 381)."},{"t":"Si le QRS est négatif, l'onde T est positive avec souvent un petit sus-décalage de ST","ok":true,"why":"C'est l'aspect décrit par le Collège (encadré « Attention », p. 381) : QRS négatif, T positive avec souvent un petit sus-décalage du ST."},{"t":"Devant une douleur thoracique persistante avec BBG, il faut attendre le résultat de la troponine avant de solliciter le cardiologue","ok":false,"why":"Faux : douleur persistante + BBG = évoquer un infarctus antérieur, avis cardiologique rapide sans attendre la troponine (TNT, signes de choc, ETT) (p. 381)."}],"explanation":"La discordance appropriée (T de polarité opposée au QRS large) est normale dans les blocs de branche, mais rend l'interprétation du territoire antérieur difficile en cas de BBG, imposant une évaluation clinique rapide devant une douleur thoracique.","trap":"Ne pas confondre discordance appropriée physiologique (due au trouble de dépolarisation) avec une authentique ischémie ; la clinique prime.","src":"p. 381","deep":"**Pourquoi** : un QRS large = dépolarisation anormale, donc repolarisation secondairement anormale : T de polarité opposée au QRS avec petit décalage du ST (QRS négatif : T positive, souvent petit sus-ST ; QRS positif : T négative, petit sous-ST) (p. 381).\n**À relier** : un ST ascendant en V1-V2 d'un BBG peut faire évoquer à tort un SCA ST+ ; douleur thoracique persistante + BBG = évoquer un infarctus antérieur, avis cardio rapide.\n**Piège** : n'attends pas la troponine."},{"id":"231-qcm-104","type":"QRM","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":3,"stem":"Concernant les hémiblocs (blocs fasciculaires), quelles propositions sont exactes ?","options":[{"t":"Une déviation axiale droite au-delà de +90° suffit à retenir un HBPG, même en cas d'hypertrophie ventriculaire droite","ok":false,"why":"Faux : HBPG = diagnostic d'exclusion ; HVD, morphologie longiligne et infarctus latéral donnent le même axe (p. 382, 407)."},{"t":"L'HBAG se traduit par une déviation axiale du QRS à gauche au-delà de -30°","ok":true,"why":"Critère de l'HBAG : axe au-delà de -30° avec D2 négatif, et QRS à peine élargi (> 110 ms) ; l'HBPG dévie au contraire à droite (> +90°) (p. 382)."},{"t":"Les hémiblocs entraînent classiquement un élargissement majeur du QRS au-delà de 140 ms","ok":false,"why":"Faux : élargissement très modéré (> 110 ms) ; > 120 ms seulement si autre bloc associé ou cardiopathie marquée (p. 382)."},{"t":"Devant un DI négatif, le premier diagnostic à évoquer est toujours l'HBPG","ok":false,"why":"Faux : d'abord une inversion des électrodes frontales (la P est alors aussi négative en D1) ; l'HBPG est rare (p. 383)."},{"t":"L'hémibloc postérieur gauche (HBPG) est plus fréquent que l'hémibloc antérieur gauche (HBAG)","ok":false,"why":"Faux : HBAG fréquent (branche superficielle, petite, fragile), HBPG rare (branche profonde) (p. 383)."}],"explanation":"HBAG (fréquent, branche superficielle et fragile) : axe gauche au-delà de -30° avec négativité de D2 ; HBPG (rare, branche profonde) : axe droit au-delà de +90°, aspect S1Q3, retenu seulement après avoir éliminé une inversion d'électrodes, une pathologie du ventricule droit, une morphologie longiligne ou un infarctus latéral.","trap":"Un DI négatif doit d'abord faire suspecter une inversion des électrodes des membres avant d'évoquer un HBPG.","src":"p. 382-383","deep":"**Pourquoi** : un hémibloc = atteinte d'un fascicule de la branche gauche : QRS à peine élargi (> 110 ms) + déviation axiale. HBAG : axe au-delà de -30° (D2 négatif) ; HBPG : axe au-delà de +90° (S1Q3), retenu seulement sans pathologie du VD, morphologie longiligne ou infarctus latéral (p. 382-383).\n**Astuce** : HBAG fréquent (branche superficielle, fine, fragile), HBPG rare (branche profonde).\n**Piège** : D1 négatif = d'abord une inversion d'électrodes (P aussi négative en D1)."},{"id":"231-qcm-105","type":"QRM","rank":"B","objective":"231-obj-06","tags":["diagnostic","complications","urgence"],"difficulty":3,"stem":"Concernant le bloc bifasciculaire et les blocs de branche à risque, quelles propositions sont exactes ?","options":[{"t":"Un BBG complet isolé peut contribuer à une désynchronisation ventriculaire aggravant une cardiopathie","ok":true,"why":"L'activation tardive de la paroi latérale désynchronise le VG ; corriger ce BBG (resynchronisation) est indiqué s'il y a des signes d'IC (p. 383, 413)."},{"t":"Il associe un hémibloc (antérieur ou postérieur gauche) à un bloc de branche droit","ok":true,"why":"Sémiologie additionnée : HBAG ou HBPG + BBD, QRS > 120 ms ; le BBG complet compte aussi comme bifasciculaire (p. 383)."},{"t":"Une syncope associée à un bloc bifasciculaire ne nécessite pas d'hospitalisation en urgence","ok":false,"why":"Faux : la 3e branche peut lâcher par intermittence (BAV complet infrahissien) ; syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie (p. 383)."},{"t":"Le QRS reste inférieur à 120 ms, l'élargissement étant très modéré","ok":false,"why":"Faux : avec le BBD associé le QRS dépasse 120 ms ; seul l'hémibloc isolé reste très modérément élargi (p. 382-383)."},{"t":"Il fait craindre un risque accru de bloc atrioventriculaire complet infrahissien","ok":true,"why":"Une seule branche reste fonctionnelle : si elle lâche par intermittence, BAV complet infrahissien (syncope, mort subite) (p. 383)."}],"explanation":"Le bloc bifasciculaire (hémibloc + BBD) traduit une atteinte de deux des trois branches, avec un risque de BAV complet infrahissien justifiant une hospitalisation en urgence en cas de syncope.","trap":"Toute syncope chez un patient porteur d'un bloc bifasciculaire est une urgence cardiologique avec télémétrie.","src":"p. 383","deep":"**Pourquoi** : bloc bifasciculaire = HBAG ou HBPG + BBD (QRS > 120 ms) ; le Collège range aussi le BBG complet parmi les blocs bifasciculaires. Si la dernière branche lâche par intermittence : BAV complet infrahissien (syncope, mort subite) (p. 383).\n**À relier** : syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie ; un BBG complet désynchronise le VG et peut créer/aggraver une IC (correction si signes d'IC).\n**Piège** : un QRS < 120 ms ne s'observe que dans l'hémibloc isolé."},{"id":"231-qcm-106","type":"QRM","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Concernant le bloc atrioventriculaire du premier degré (BAV1), quelle(s) proposition(s) est/sont exacte(s) ?","options":[{"t":"Il se caractérise par un allongement progressif du PR jusqu'à une onde P bloquée","ok":false,"why":"C'est le Mobitz 1 (Wenckebach) ; dans le BAV1 le PR est long mais fixe et aucune P n'est bloquée (p. 385-386)."},{"t":"Une onde P sur deux y est bloquée","ok":false,"why":"C'est le BAV2 2/1 ; dans le BAV1 toutes les P sont conduites, avec retard (p. 385)."},{"t":"Le PR y est variable d'un cycle à l'autre","ok":false,"why":"Faux : dans le BAV1 le PR est long mais fixe ; un PR qui s'allonge puis une P bloquée = Mobitz 1 (p. 385-386)."},{"t":"Il correspond à un allongement fixe et constant de l'espace PR au-delà de 200 ms, sans onde P bloquée","ok":true,"why":"BAV1 = PR > 200 ms (borne haute normale), fixe et constant ; chaque P est conduite, juste en retard (fig. 15.21, p. 386)."},{"t":"Il se caractérise par une dissociation atrioventriculaire complète","ok":false,"why":"C'est le BAV3 : aucune P conduite, échappement ventriculaire ; dans le BAV1 toutes les P passent (p. 385)."}],"explanation":"Le BAV1 se définit par un allongement fixe et constant du PR (> 200 ms) sans aucune onde P bloquée : toutes les ondes P sont conduites, mais avec retard.","src":"p. 385-386","deep":"**Pourquoi** : BAV1 = allongement fixe et constant du PR (> 200 ms) : toutes les P sont conduites, avec retard (p. 385-386).\n**À relier** : Mobitz 1 = PR qui s'allonge puis P bloquée ; Mobitz 2 = PR constant puis P bloquée ; BAV3 = dissociation AV complète.\n**Piège** : un PR variable ou une P bloquée n'est jamais un BAV1."},{"id":"231-qcm-107","type":"QRM","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant le bloc atrioventriculaire du 2e degré Mobitz 1 (Luciani-Wenckebach), quelles propositions sont exactes ?","options":[{"t":"Il se caractérise par un allongement progressif du PR jusqu'à une onde P bloquée","ok":true,"why":"Wenckebach : le PR s'allonge à chaque cycle jusqu'à une P non conduite ; siège suprahissien (fig. 15.20, p. 385)."},{"t":"Il correspond à une dissociation atrioventriculaire complète","ok":false,"why":"Faux : dissociation complète = BAV3 ; dans le Mobitz 1 la plupart des P sont conduites (p. 385)."},{"t":"Il est habituellement de siège infrahissien","ok":false,"why":"Faux : le Mobitz 1 est suprahissien (pacemaker seulement s'il est symptomatique) ; le Mobitz 2 est infrahissien (p. 385, 412)."},{"t":"Il se caractérise par un PR constant puis une onde P bloquée de façon inopinée","ok":false,"why":"C'est le Mobitz 2, infrahissien (pacemaker même sans symptôme) ; dans le Mobitz 1 le PR s'allonge avant le blocage (p. 385, 412)."},{"t":"Une onde P prématurée peut parfois être bloquée en raison d'une extrasystole atriale et non d'un vrai trouble conductif","ok":true,"why":"Sur la fig. 15.22, la P bloquée plus précoce que les autres est une extrasystole atriale bloquée : vérifier la régularité des P avant de parler de BAV (p. 386)."}],"explanation":"Le BAV2 Mobitz 1 (Wenckebach) est un allongement progressif du PR jusqu'à une onde P bloquée, habituellement suprahissien ; attention à ne pas confondre une onde P bloquée avec une extrasystole atriale bloquée.","trap":"Une onde P bloquée plus précoce que les autres peut être une extrasystole atriale bloquée, et non un vrai BAV2.","src":"p. 385-386","deep":"**Pourquoi** : Mobitz 1 (Luciani-Wenckebach) = PR qui s'allonge progressivement jusqu'à une P bloquée ; siège suprahissien (p. 385-386).\n**À relier** : Mobitz 2 = PR constant puis P bloquée inopinée, infrahissien (pacemaker même sans symptôme).\n**Piège** : une P bloquée plus précoce que les autres est une extrasystole atriale bloquée, pas un vrai BAV."},{"id":"231-qcm-108","type":"QRM","rank":"A","objective":"231-obj-08","tags":["diagnostic","urgence"],"difficulty":2,"stem":"Concernant le bloc atrioventriculaire complet (BAV3), quelles propositions sont exactes ?","options":[{"t":"Le rythme ventriculaire d'échappement est toujours rapide et irrégulier","ok":false,"why":"Faux : l'échappement est automatique, donc régulier et lent ; c'est aussi ce qui régularise une FA associée à un BAV3 (p. 387, 392)."},{"t":"Les ondes P sont trop lentes ou absentes, ce qui explique la bradycardie","ok":false,"why":"Faux : dans un BAV les P sont régulières et à fréquence normale (plus de P que de QRS) ; P lentes/absentes = dysfonction sinusale (p. 385, 389)."},{"t":"Il existe une dissociation atrioventriculaire complète","ok":true,"why":"BAV3 : les P, régulières et à fréquence normale, ne sont jamais conduites ; les ventricules suivent un échappement régulier et lent (p. 385, 387)."},{"t":"Un échappement à QRS fins traduit un bloc de siège infrahissien","ok":false,"why":"Faux : un échappement à QRS fins, régulier et lent, traduit un bloc nodal (suprahissien) (fig. 15.23, p. 387)."},{"t":"Toutes les ondes P sont suivies d'un QRS","ok":false,"why":"C'est l'inverse : dans le BAV3 aucune P n'est conduite aux ventricules (plus de P que de QRS, dissociation complète) (p. 385)."}],"explanation":"Le BAV3 associe une dissociation atrioventriculaire complète, des ondes P régulières non conduites, et un rythme d'échappement régulier et lent ; un échappement à QRS fins traduit un bloc nodal (suprahissien).","src":"p. 387","deep":"**Pourquoi** : BAV3 = dissociation AV complète : P régulières à fréquence normale, aucune conduite ; les ventricules suivent un échappement régulier et lent (p. 387).\n**À relier** : échappement à QRS fins = bloc nodal (suprahissien) ; BAV infrahissiens (Mobitz 2, BAV3) = pacemaker même sans symptôme.\n**Piège** : dans un BAV les P sont normales ; des P lentes ou absentes évoquent une dysfonction sinusale."},{"id":"231-qcm-109","type":"QRM","rank":"B","objective":"231-obj-10","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant la dysfonction sinusale, quelles propositions sont exactes ?","options":[{"t":"Dans un bloc sinoatrial du 2e degré, la pause correspond à une onde P présente mais bloquée","ok":false,"why":"Faux : c'est tout le complexe P-QRS-T qui manque (pause = 2 × PP) ; une P présente non suivie de QRS = BAV (p. 387)."},{"t":"L'onde P rétrograde d'un échappement jonctionnel est positive en D2","ok":false,"why":"Faux : l'oreillette est activée de bas en haut depuis la jonction : P' négative en D2, souvent dans le ST (p. 388)."},{"t":"Elle peut se manifester par une pause correspondant au double de l'intervalle PP ou RR normal","ok":true,"why":"Bloc sinoatrial du 2e degré : un cycle P-QRS-T entier manque, la pause vaut le double du PP/RR (fig. 15.24, p. 387)."},{"t":"En cas de dysfonction marquée, un rythme d'échappement jonctionnel peut apparaître","ok":true,"why":"Si le nœud sinusal fait défaut, la jonction prend le relais : P absente devant le QRS ou rétrograde derrière (p. 388)."},{"t":"Elle peut se manifester par une asystole avec un tracé plat sans activité cardiaque visible","ok":true,"why":"Asystole (tracé plat) et pauses de bloc sinoatrial sont les deux aspects « simples » de dysfonction sinusale (p. 387)."}],"explanation":"La dysfonction sinusale regroupe l'asystole, les pauses par bloc sinoatrial (durée double du cycle normal) et, si marquée, l'échappement jonctionnel avec onde P rétrograde négative en D2.","src":"p. 387-388","deep":"**Pourquoi** : dysfonction sinusale = asystole, pauses par bloc sinoatrial du 2e degré (pause = double du PP/RR normal), P trop lentes ; si marquée, échappement jonctionnel avec P rétrograde (derrière le QRS, négative en D2 car activation de bas en haut) (p. 387-388).\n**À relier** : devant une bradycardie, P lentes/absentes = nœud sinusal ; plus de P que de QRS = BAV.\n**Piège** : la P rétrograde est négative en D2, jamais positive."},{"id":"231-qcm-110","type":"QRM","rank":"A","objective":"231-obj-10","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Devant une bradycardie, quelle(s) proposition(s) concernant l'algorithme diagnostique est/sont exacte(s) ?","options":[{"t":"Il faut analyser les ondes P pour orienter le diagnostic étiologique","ok":true,"why":"Algorithme de la bradycardie : regarder les P ; lentes/absentes = nœud sinusal ; normales ou rapides mais plus nombreuses que les QRS = BAV (fig. 15.27, p. 389)."},{"t":"Une fibrillation atriale ne peut jamais coexister avec une bradycardie","ok":false,"why":"Faux : une FA ou un flutter avec BAV donne plus d'activité atriale que de QRS, donc une bradycardie ventriculaire (ex. FA + BAV3, p. 389, 392)."},{"t":"Des ondes P régulières à fréquence normale mais plus nombreuses que les QRS orientent vers un bloc atrioventriculaire","ok":true,"why":"Le nœud sinusal marche mais le passage AV est bloqué : plus de P que de QRS = BAV (fig. 15.27, p. 389)."},{"t":"Des ondes P trop lentes ou inexistantes orientent vers une dysfonction sinusale","ok":true,"why":"P trop lentes ou absentes = défaut du nœud sinusal (dysfonction sinusale) (fig. 15.27, p. 389)."},{"t":"Seul le nœud atrioventriculaire peut être responsable d'une bradycardie","ok":false,"why":"Faux : deux structures seulement, nœud sinusal ou NAV ; les blocs de branche ne donnent pas de bradycardie (p. 389, 415)."}],"explanation":"Devant une bradycardie, seules deux structures peuvent être en cause : le nœud sinusal (dysfonction sinusale, P trop lentes ou absentes) ou le nœud atrioventriculaire (BAV, plus de P que de QRS).","src":"p. 389","deep":"**Pourquoi** : seules deux structures donnent une bradycardie : nœud sinusal (P trop lentes ou inexistantes) ou NAV (P régulières à fréquence normale, voire tachycardes, mais plus de P que de QRS) (p. 389).\n**Astuce** : compare le nombre de P au nombre de QRS.\n**Attention** : cet algorithme définit la bradycardie comme une FC (des QRS) < 50 bpm (fig. 15.27, p. 389), alors que la p. 376 retient FC < 60 bpm : deux seuils dans le Collège.\n**Piège** : une FA ou un flutter (activité atriale rapide) peut coexister avec une bradycardie s'il existe un BAV."},{"id":"231-qcm-111","type":"QRM","rank":"B","objective":"231-obj-16","tags":["traitement","ECG"],"difficulty":2,"stem":"Concernant les manœuvres vagales et l'adénosine utilisées pour l'analyse des tachycardies, quelles propositions sont exactes ?","options":[{"t":"L'adénosine intraveineuse est contre-indiquée en cas d'asthme en raison d'un risque de bronchospasme","ok":true,"why":"Elle peut, rarement, provoquer un bronchospasme intense transitoire, même sans asthme ; autres CI : hypotension, FA préexcitée (p. 390, 411)."},{"t":"La manœuvre de Valsalva consiste en une expiration forcée à glotte fermée","ok":true,"why":"Valsalva = expiration forcée à glotte fermée ; comme les autres manœuvres vagales, elle intensifie le filtre du NAV (encadré 15.1, p. 390)."},{"t":"La compression carotidienne unilatérale est contre-indiquée en cas d'athérome important ou de souffle carotidien","ok":true,"why":"Elle doit rester unilatérale et est contre-indiquée en cas d'athérome important ou de souffle carotidien (encadré 15.1, p. 390)."},{"t":"La compression oculaire bilatérale reste recommandée en première intention","ok":false,"why":"Faux : elle n'est plus recommandée (risque de décollement de rétine chez le myope) (p. 390)."},{"t":"Ces manœuvres agissent en intensifiant le filtre atrioventriculaire du NAV","ok":true,"why":"Elles créent un BAV transitoire (filtre AV renforcé) qui ralentit les QRS et démasque l'activité atriale (p. 390)."}],"explanation":"Les manœuvres vagales (Valsalva, compression carotidienne unilatérale sauf contre-indication, eau froide) et l'adénosine IV intensifient transitoirement le filtre du NAV ; la compression oculaire bilatérale n'est plus recommandée.","src":"p. 390","deep":"**Pourquoi** : manœuvres vagales et adénosine créent un BAV transitoire (filtre AV intensifié) pour démasquer ou interrompre une tachycardie. Adénosine : flash IV, ≈ 10 s, vagomimétique (récepteurs purinergiques) (p. 390).\n**À relier** : CI de l'adénosine : asthme (bronchospasme), hypotension (p. 390) ; la p. 411 fait de la FA sur voie accessoire (super-Wolff) « la seule autre CI avec l'asthme », et l'item 237 (p. 421) cite asthme et HTA non contrôlée : versions différentes selon la page. Valsalva, compression carotidienne unilatérale (CI athérome/souffle), eau froide.\n**Piège** : la compression oculaire bilatérale n'est plus recommandée (décollement de rétine)."},{"id":"231-qcm-112","type":"QRM","rank":"A","objective":"231-obj-12","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Concernant la différenciation entre tachycardie sinusale et tachycardie supraventriculaire non sinusale, quelles propositions sont exactes ?","options":[{"t":"Une tachycardie sinusale se définit toujours par des QRS larges","ok":false,"why":"Faux : sa définition repose sur des P sinusales (positives en D1, D2, D3, aVF) ; les QRS ne sont larges qu'avec un bloc associé (p. 390)."},{"t":"Un massage sinocarotidien ne peut jamais aider à ce diagnostic différentiel","ok":false,"why":"Le livre indique au contraire que le massage sinocarotidien permet de mettre en évidence la variabilité de fréquence typique de la tachycardie sinusale."},{"t":"Dans la tachycardie sinusale, les ondes P sont négatives en D2, D3 et aVF","ok":false,"why":"Faux : les ondes P sinusales sont positives en D1, D2, D3 et aVF ; une onde P négative en D2 traduit une activation atriale de bas en haut (onde P rétrograde)."},{"t":"Une tachycardie marquée chez un sujet au repos, sans fièvre, douleur ni stress, oriente d'abord vers une tachycardie sinusale","ok":false,"why":"Faux : une personne au repos ne doit pas être très tachycarde en l'absence de cause évidente d'augmentation du métabolisme (fièvre, stress, douleur) ; ce contexte doit faire rechercher un trouble du rythme supraventriculaire."},{"t":"Dans la tachycardie sinusale, la fréquence varie progressivement, contrairement à la tachycardie supraventriculaire qui varie « en marches d'escalier »","ok":true,"why":"Le nœud sinusal suit le tonus neurovégétatif : accélération et ralentissement progressifs ; une TSV change par paliers brusques (p. 391)."}],"explanation":"La tachycardie sinusale se distingue par des ondes P sinusales, une fréquence qui varie progressivement (et non en « marches d'escalier »), et un contexte clinique expliquant l'accélération.","src":"p. 390-391","deep":"**Pourquoi** : tachycardie sinusale = P sinusales (positives en D1, D2, D3, aVF), fréquence qui varie progressivement (scope, holter, massage sinocarotidien) et contexte explicatif ; la TSV varie en « marches d'escalier » (p. 390-391).\n**À relier** : un sujet au repos très tachycarde sans cause évidente (fièvre, stress, douleur) doit faire chercher un trouble du rythme.\n**Piège** : une P négative en D2 est rétrograde, pas sinusale."},{"id":"231-qcm-113","type":"QRM","rank":"A","objective":"231-obj-13","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Concernant la fibrillation atriale (FA), quelles propositions sont exactes ?","options":[{"t":"L'activité atriale peut se traduire par des mailles amples ou une fine trémulation de la ligne de base","ok":true,"why":"L'activité sinusale est remplacée par des mailles amples ou une fine trémulation ; si elle est peu lisible, manœuvres vagales (p. 392)."},{"t":"Dans sa forme tachycarde fréquente, la FA s'inscrit entre 100 et 200 bpm","ok":true,"why":"Forme fréquente : 100-200 bpm, QRS irrégulièrement irréguliers ; plus lente si conduction lente, lente ET régulière si BAV3 (p. 392)."},{"t":"Les QRS sont typiquement « irrégulièrement irréguliers »","ok":true,"why":"Les RR ne sont pas multiples d'une valeur commune : seul diagnostic d'une tachycardie complètement irrégulière à QRS fins (p. 392, 415)."},{"t":"En l'absence de trouble de conduction associé, les QRS sont classiquement larges","ok":false,"why":"Faux : sans bloc de branche ni trouble intraventriculaire, les QRS de la FA sont fins (p. 392)."},{"t":"Elle correspond à une activation atriale anarchique","ok":true,"why":"FA = activation atriale anarchique (fibrillatoire), à l'opposé du flutter, organisé en circuit (p. 391, 393)."}],"explanation":"La FA se caractérise par une activation atriale anarchique, des QRS fins irrégulièrement irréguliers (sauf trouble de conduction associé), une fréquence ventriculaire souvent entre 100 et 200 bpm, et une activité atriale en mailles ou trémulation.","src":"p. 391-392","deep":"**Pourquoi** : la FA est une activation atriale anarchique (fibrillatoire), contrairement au flutter organisé en circuit. À l'ECG : QRS irrégulièrement irréguliers (RR non multiples d'une valeur commune), activité atriale en mailles amples ou fine trémulation (p. 391-392).\n**À relier** : seul diagnostic devant une tachycardie complètement irrégulière à QRS fins.\n**Piège** : les QRS ne sont larges que s'il existe un bloc de branche associé."},{"id":"231-qcm-114","type":"QRM","rank":"B","objective":"231-obj-13","tags":["diagnostic","complications","ECG"],"difficulty":3,"stem":"Concernant la fibrillation atriale associée à un trouble de la conduction atrioventriculaire, quelles propositions sont exactes ?","options":[{"t":"Une FA à conduction normale présente un RR parfaitement constant","ok":false,"why":"Faux : FA à conduction normale = RR irréguliers ; un RR constant fait évoquer un BAV3 associé (fig. 15.31, p. 392)."},{"t":"En cas de FA associée à un BAV3, le rythme ventriculaire reste rapide et irrégulier","ok":false,"why":"Faux : les ventricules suivent un échappement automatique, lent et régulier (p. 392)."},{"t":"Une FA à petites mailles (trémulation de la ligne de base bien visible en D2, D3, aVF) peut s'associer à un BAV complet","ok":true,"why":"Le Collège illustre ce cas par une FA à petites mailles avec trémulation visible en D2, D3, aVF et activité ventriculaire régulière lente."},{"t":"L'association FA et bloc atrioventriculaire complet doit être évoquée lorsque l'activité ventriculaire devient lente et régulière","ok":true,"why":"En cas de BAV complet associé à une FA, la dépolarisation ventriculaire se fait par un rythme d'échappement automatique, donc régulier et lent."},{"t":"Le rythme d'échappement observé dans ce contexte est de mécanisme automatique","ok":true,"why":"En BAV complet, les ventricules sont commandés par un échappement automatique, donc régulier : c'est ce qui régularise une FA (p. 392)."}],"explanation":"Devant une FA dont l'activité ventriculaire devient régulière et lente, il faut évoquer un BAV3 associé, avec un rythme d'échappement automatique régulier remplaçant la conduction irrégulière habituelle de la FA.","trap":"Une FA dont l'activité ventriculaire devient lente et régulière doit faire évoquer un BAV complet associé, avec un rythme d'échappement automatique (Collège p. 392).","src":"p. 392","deep":"**Pourquoi** : dans un BAV complet, les ventricules sont commandés par un échappement automatique : même avec une FA, l'activité ventriculaire devient lente et RÉGULIÈRE (p. 392).\n**À relier** : FA à conduction normale = RR irréguliers ; FA + BAV3 = RR constant.\n**Piège** : une FA à cadence lente et régulière n'est pas « normale » : pense au BAV3 associé."},{"id":"231-qcm-115","type":"QRM","rank":"B","objective":"231-obj-16","tags":["physiopathologie","ECG"],"difficulty":2,"stem":"Concernant la fonction de « filtre » du nœud atrioventriculaire (NAV), quelles propositions sont exactes ?","options":[{"t":"Le NAV présente une conduction dite « décrémentielle »","ok":true,"why":"Conduction décrémentielle : au-delà d'une certaine fréquence atriale, le NAV ne conduit plus en 1/1 ; c'est le « filtre » qui protège les ventricules (p. 390)."},{"t":"Sans cette fonction de filtre, un flutter atrial à 300 bpm entraînerait une cadence ventriculaire à 300 bpm","ok":true,"why":"Sans filtre, le flutter à 300/min serait conduit en 1/1 ; grâce au NAV il l'est habituellement en 2/1 (150/min) (p. 390, 394)."},{"t":"Le passage atrioventriculaire peut se faire en 1/1, 2/1, ou en alternance selon l'intensité du filtre","ok":true,"why":"Selon la fréquence atriale et le filtre (âge, tonus vagal, ralentisseurs) : 1/1, 2/1, alternances, conduction variable (p. 390)."},{"t":"Cette fonction de filtre protège contre le risque de fibrillation ventriculaire en cas de passage en FA","ok":true,"why":"Sans filtre, chaque FA serait conduite telle quelle et donnerait une FV : c'est le danger de la voie accessoire, non décrémentielle (super-Wolff) (p. 390, 411)."},{"t":"L'intensité du filtre du NAV est indépendante du tonus vagal","ok":false,"why":"Faux : le filtre dépend de l'âge, du tonus vagal et des ralentisseurs du NAV ; c'est pourquoi les manœuvres vagales le renforcent (p. 390)."}],"explanation":"Le NAV a une fonction de filtre à conduction décrémentielle, protectrice, qui limite la transmission ventriculaire des tachycardies atriales (FA, flutter) ; son intensité dépend de l'âge, du tonus vagal et des médicaments ralentisseurs.","src":"p. 390","deep":"**Pourquoi** : le NAV est un filtre vital (conduction décrémentielle) : au-delà d'une certaine fréquence atriale, les ventricules ne suivent plus en 1/1 ; sans filtre, chaque FA donnerait une FV et un flutter à 300 donnerait 300 aux ventricules (p. 390).\n**À relier** : intensité du filtre selon âge, tonus vagal, médicaments ralentisseurs ; rapports 1/1, 2/1, 3/1 ou variables.\n**Piège** : la voie accessoire n'a pas ce filtre (super-Wolff)."},{"id":"231-qru-101","type":"QRU","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Une patiente présente en V1 un aspect rS avec un QRS à 150 ms, et en V6 un notch avec onde R exclusive. Quel est le diagnostic le plus probable ?","options":[{"t":"Hémibloc antérieur gauche isolé","ok":false,"why":"Un HBAG isolé élargit à peine le QRS (> 110 ms) et dévie l'axe à gauche ; QRS à 150 ms avec rS en V1 = bloc complet (p. 382)."},{"t":"Bloc complet de branche droite","ok":false,"why":"Le BBD est positif en V1 (RsR') ; rS négatif en V1 + notch en V6 = BBG (p. 378, 380)."},{"t":"Rythme jonctionnel","ok":false,"why":"Un rythme jonctionnel se reconnaît à l'absence de P devant le QRS (P' rétrograde), non à cette morphologie V1/V6 (p. 388)."},{"t":"Bloc atrioventriculaire du 2e degré","ok":false,"why":"Un BAV2 se lit sur la relation P-QRS (P bloquées), pas sur la forme du QRS (p. 385)."},{"t":"Bloc complet de branche gauche","ok":true,"why":"L'association QRS large, aspect rS en V1 et notch avec R exclusive en V6 définit le bloc complet de branche gauche."}],"explanation":"L'aspect rS/QS négatif en V1 associé à un notch avec onde R exclusive en V6/D1/aVL et un QRS > 120 ms définit le bloc complet de branche gauche.","src":"p. 380","deep":"**Pourquoi** : QRS large (150 ms), V1 négatif en rS et notch avec R exclusive en V6 = BBG complet (p. 380).\n**À relier** : BBD = RsR' positif en V1. Le BBG rend l'antérieur difficile à lire (discordance appropriée).\n**Piège** : douleur thoracique persistante + BBG = évoquer un infarctus antérieur et demander un avis cardio rapide."},{"id":"231-qru-102","type":"QRU","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Quelle déviation axiale caractérise l'hémibloc antérieur gauche (HBAG) ?","options":[{"t":"Une déviation axiale droite au-delà de +90°, avec aspect S1Q3","ok":false,"why":"C'est l'HBPG (rare), retenu seulement sans pathologie du VD, morphologie longiligne ni infarctus latéral (p. 382)."},{"t":"Un axe hyperdroit avec positivité de D2","ok":false,"why":"Un axe hyperdroit (> +90°) est l'aspect de l'HBPG ; l'HBAG dévie l'axe à gauche avec D2 négatif (p. 382)."},{"t":"Un axe normal entre -30° et +90°","ok":false,"why":"Un hémibloc se définit par une déviation axiale pathologique : axe normal = pas d'hémibloc (p. 382)."},{"t":"Une déviation axiale gauche au-delà de -30°, avec négativité de D2","ok":true,"why":"HBAG : axe au-delà de -30° (D2 négatif), QRS peu élargi (> 110 ms) ; fréquent car la branche antérieure est superficielle et fine (p. 382-383)."},{"t":"Une absence totale de modification de l'axe du QRS","ok":false,"why":"Faux : le diagnostic d'hémibloc se fait sur l'axe (points clés) (p. 382, 415)."}],"explanation":"L'HBAG se traduit par une déviation axiale gauche au-delà de -30° avec négativité de D2, contrairement à l'HBPG qui dévie l'axe à droite au-delà de +90° avec aspect S1Q3.","src":"p. 382","deep":"**Pourquoi** : l'HBAG dévie l'axe vers la gauche au-delà de -30° (D2 négatif) (p. 382).\n**Astuce** : Antérieur = axe vers la Gauche ; Postérieur = axe vers la Droite.\n**Piège** : l'HBPG donne un axe droit > +90° avec S1Q3, et ne se retient qu'après avoir éliminé une inversion d'électrodes, une pathologie du VD, une morphologie longiligne ou un infarctus latéral."},{"id":"231-qru-103","type":"QRU","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Quel type de bloc atrioventriculaire se caractérise par un allongement progressif du PR jusqu'à une onde P bloquée ?","options":[{"t":"BAV1","ok":false,"why":"BAV1 = PR fixe > 200 ms sans P bloquée (p. 386)."},{"t":"BAV3","ok":false,"why":"BAV3 = dissociation AV complète, aucune P conduite (p. 385)."},{"t":"BAV2 Mobitz 1 (Wenckebach)","ok":true,"why":"Luciani-Wenckebach : PR qui s'allonge cycle après cycle jusqu'à une P bloquée ; siège suprahissien (p. 385)."},{"t":"BAV2 Mobitz 2","ok":false,"why":"Mobitz 2 = PR constant puis P bloquée inopinée, infrahissien (p. 385)."},{"t":"BAV 2/1","ok":false,"why":"BAV 2/1 = une P sur deux bloquée ; siège selon la largeur du QRS et l'existence de Mobitz 1 ailleurs (p. 385)."}],"explanation":"Le BAV2 Mobitz 1 (Wenckebach) se définit par un allongement progressif du PR jusqu'à une onde P bloquée, généralement de siège suprahissien.","src":"p. 385-386","deep":"**Pourquoi** : Mobitz 1 (Wenckebach) = PR qui s'allonge progressivement puis une P bloquée ; siège suprahissien (p. 385-386).\n**Astuce** : Mobitz 1 : « ça s'allonge, ça s'allonge, ça bloque » ; Mobitz 2 : le blocage est inopiné.\n**Piège** : Mobitz 2 = PR constant avant la P bloquée ; BAV 2/1 = une P sur deux."},{"id":"231-qru-104","type":"QRU","rank":"A","objective":"231-obj-10","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Chez un patient en échappement jonctionnel par dysfonction sinusale marquée, quelle est la caractéristique attendue de l'onde P rétrograde en D2 ?","options":[{"t":"Négative","ok":true,"why":"L'oreillette est activée de bas en haut depuis la jonction : P' négative en D2, souvent visible dans le ST (p. 388)."},{"t":"Identique à l'onde P sinusale antérograde","ok":false,"why":"Faux : la P sinusale (haut → bas) est positive en D2, la P' rétrograde (bas → haut) négative (p. 375, 388)."},{"t":"Absente de façon constante","ok":false,"why":"Faux : la P' rétrograde est souvent visible derrière le QRS, dans le ST (fig. 15.25, p. 388)."},{"t":"Biphasique dans toutes les dérivations","ok":false,"why":"Faux : l'oreillette activée de bas en haut depuis la jonction donne une P' négative en D2, souvent cachée dans le ST (p. 388)."},{"t":"Positive","ok":false,"why":"Faux : positive en D2 = activation haut → bas, donc sinusale ; la rétrograde est négative (p. 388)."}],"explanation":"En cas d'échappement jonctionnel, l'activation atriale rétrograde (de la jonction vers l'oreillette, donc de bas en haut) donne une onde P négative en D2.","src":"p. 388","deep":"**Pourquoi** : en échappement jonctionnel, l'oreillette est activée de bas en haut à partir de la jonction (activation rétrograde) : P négative en D2, visible derrière le QRS (dans le ST) (p. 388).\n**À relier** : l'échappement jonctionnel apparaît en cas de dysfonction sinusale marquée.\n**Piège** : la P sinusale est positive en D2 ; la P rétrograde est négative."},{"id":"231-qru-105","type":"QRU","rank":"A","objective":"231-obj-12","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Quel élément évolutif permet de différencier une tachycardie sinusale d'une tachycardie supraventriculaire non sinusale sur une courbe de fréquence de scope ou de holter ?","options":[{"t":"Une fréquence toujours strictement identique dans les deux cas","ok":false,"why":"Faux : c'est justement le profil de fréquence qui les distingue (progressif vs marches d'escalier) (p. 391)."},{"t":"Une accélération brutale uniquement dans la tachycardie sinusale","ok":false,"why":"Inversé : brusque (marches d'escalier) = TSV ; la sinusale varie progressivement (p. 391)."},{"t":"L'absence totale d'onde P dans la tachycardie sinusale","ok":false,"why":"Faux : la tachycardie sinusale a des P sinusales positives en D1, D2, D3, aVF (p. 390)."},{"t":"Une fréquence toujours supérieure à 200 bpm dans la tachycardie sinusale","ok":false,"why":"Faux : aucun seuil de FC ne tranche ; ce sont les P, le profil évolutif et le contexte (p. 390-391)."},{"t":"Une variation progressive de la fréquence dans la tachycardie sinusale, contre des « marches d'escalier » dans la tachycardie supraventriculaire","ok":true,"why":"La tachycardie sinusale suit le tonus neurovégétatif (variation progressive) ; une TSV démarre et change par paliers (p. 391)."}],"explanation":"Sur la courbe de fréquence, la tachycardie sinusale varie progressivement alors que la tachycardie supraventriculaire non sinusale varie brutalement, en « marches d'escalier ».","src":"p. 390-391","deep":"**Pourquoi** : la fréquence de la tachycardie sinusale varie progressivement (reflet du tonus sympathique/parasympathique et du contexte), celle d'une TSV fait des « marches d'escalier » (p. 390-391).\n**À relier** : courbe de fréquence d'un scope, d'une télémétrie ou d'un holter, ou massage sinocarotidien.\n**Piège** : aucune valeur de FC seule ne tranche ; regarde le profil évolutif."},{"id":"231-qroc-101","type":"QROC","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":1,"question":"Quel aspect du QRS en V1 est caractéristique du bloc complet de branche gauche ?","answer":"Un aspect rS ou QS globalement négatif","accept":["rS","QS","aspect négatif en V1","rS ou QS","QRS négatif","QRS globalement négatif en V1","négatif"],"keywords":["v1","negatif"],"explanation":"BBG : V1 globalement négatif (rS ou QS), notch avec R exclusive en V6, D1, aVL ; QRS > 120 ms (p. 380).","src":"p. 380","deep":"**Pourquoi** : en BBG, le QRS est globalement négatif en V1 (rS ou QS) ; en V6, D1, aVL, notch avec R exclusive (p. 380).\n**Astuce** : V1 négatif = bloc gauche, V1 positif = bloc droit.\n**Piège** : l'aspect RsR' positif en V1 est celui du BBD."},{"id":"231-qroc-102","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG"],"difficulty":2,"question":"Dans la démarche d'interprétation d'un bloc de branche, après avoir vérifié le rythme sinusal, quelles sont les trois étapes suivantes, dans l'ordre ?","answer":"Durée du QRS, puis aspect en V1, puis aspect en V6","accept":["QRS puis V1 puis V6","QRS, V1, V6","durée du QRS puis V1 puis V6","QRS > 120 ms, V1, V6"],"keywords":["qrs","v1","v6"],"explanation":"Après avoir vérifié le rythme sinusal, il faut vérifier la durée du QRS (> 120 ms), l'aspect en V1, puis l'aspect inverse attendu en V6.","src":"p. 381","deep":"**Pourquoi** : démarche systématique pour ne rien oublier : rythme sinusal, puis durée du QRS (> 120 ms), puis aspect en V1, puis aspect inverse en V6 (p. 381).\n**À relier** : V1 positif = BBD probable ; V1 négatif = BBG probable.\n**Piège** : commence par le rythme atrial (une TSV peut s'associer à un bloc de branche)."},{"id":"231-qroc-103","type":"QROC","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"question":"Comment se nomme le phénomène par lequel la polarité de l'onde T devient opposée à celle du QRS en cas de bloc de branche ?","answer":"La discordance appropriée","accept":["discordance appropriée","discordance","discordance appropriée des ondes T"],"keywords":["discordance"],"explanation":"QRS large = dépolarisation anormale, donc repolarisation secondairement anormale : T opposée au QRS ; elle peut mimer un SCA ST+ dans le BBG (p. 381).","src":"p. 381","deep":"**Pourquoi** : un QRS large traduit un trouble de dépolarisation, qui entraîne une repolarisation secondairement anormale : T de polarité opposée au QRS, avec petit décalage de ST (p. 381).\n**À relier** : un ST ascendant en V1-V2 du BBG peut faire évoquer à tort un SCA ST+.\n**Piège** : « appropriée » = attendue, pas pathologique ; mais elle gêne la lecture de l'antérieur."},{"id":"231-qroc-104","type":"QROC","rank":"A","objective":"231-obj-06","tags":["diagnostic"],"difficulty":2,"question":"Quelle branche du réseau de conduction, fragile car superficielle et de petite taille, est le plus souvent atteinte dans les hémiblocs ?","answer":"La branche antérieure gauche (fascicule antérieur gauche)","accept":["branche antérieure gauche","HBAG","fascicule antérieur gauche","hémibloc antérieur gauche","branche antérieure"],"keywords":["anterieur","gauche"],"explanation":"La branche antérieure gauche est superficielle et fine, donc fragile : HBAG fréquent (axe au-delà de -30°) ; la postérieure, profonde, s'atteint rarement (p. 383).","src":"p. 383","deep":"**Pourquoi** : la branche antérieure gauche est superficielle et de petite taille, donc fragile : l'HBAG est fréquent ; la branche postérieure est profonde, l'HBPG est rare (p. 383).\n**Astuce** : superficiel = fragile.\n**À relier** : HBAG = axe au-delà de -30° (D2 négatif).\n**Piège** : devant un D1 négatif, pense d'abord à une inversion des électrodes."},{"id":"231-qroc-105","type":"QROC","rank":"B","objective":"231-obj-06","tags":["complications","urgence"],"difficulty":2,"question":"Quelle association clinico-électrique impose une hospitalisation en cardiologie avec télémétrie ?","answer":"Syncope associée à un bloc bifasciculaire","accept":["syncope et bloc bifasciculaire","syncope + bloc bifasciculaire"],"keywords":["syncope","bifasciculaire"],"explanation":"Bloc bifasciculaire : une seule branche reste ; si elle lâche par intermittence, BAV complet infrahissien (syncope, mort subite) : syncope = cardiologie + télémétrie (p. 383).","src":"p. 383","deep":"**Pourquoi** : un bloc bifasciculaire fait craindre que la 3e branche dysfonctionne par intermittence : BAV complet infrahissien, syncope, voire mort subite (p. 383).\n**Astuce** : syncope + bloc bifasciculaire = cardiologie + télémétrie.\n**Piège** : un hémibloc isolé ou un bloc incomplet ont un risque faible de BAV infrahissien."},{"id":"231-qroc-106","type":"QROC","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":1,"question":"Quel type de bloc atrioventriculaire correspond à une dissociation atrioventriculaire complète ?","answer":"Le bloc atrioventriculaire du 3e degré (BAV3)","accept":["BAV3","BAV complet","BAV 3","BAV du 3e degré","bloc atrioventriculaire complet","BAV de 3e degré"],"keywords":["bav3","complet"],"explanation":"BAV3 : P régulières à fréquence normale, aucune conduite ; les ventricules suivent un échappement régulier et lent ; à distinguer de la dissociation VA de la TV (plus de QRS que de P) (p. 385, 400).","src":"p. 387","deep":"**Pourquoi** : BAV3 = aucune onde P conduite : dissociation AV complète, avec P régulières et QRS commandés par un échappement (p. 387).\n**À relier** : échappement à QRS fins, régulier et lent = bloc nodal.\n**Piège** : ne confonds pas la dissociation AV du BAV3 (P plus nombreuses que les QRS) avec la dissociation ventriculoatriale de la TV (plus de QRS que de P)."},{"id":"231-qroc-107","type":"QROC","rank":"A","objective":"231-obj-08","tags":["diagnostic"],"difficulty":2,"question":"Dans un BAV3, quel type de QRS d'échappement oriente vers un bloc de siège nodal (suprahissien) ?","answer":"Un échappement à QRS fins","accept":["QRS fins","échappement fin","échappement à QRS étroits"],"keywords":["fins"],"explanation":"Échappement à QRS fins, régulier et lent = bloc nodal (suprahissien) ; en BAV 2/1, ce sont des QRS larges qui orientent vers l'infrahissien (p. 385, 387).","src":"p. 387","deep":"**Pourquoi** : un échappement régulier, lent, à QRS fins traduit un bloc nodal (suprahissien) (p. 387).\n**À relier** : BAV infrahissiens (Mobitz 2, BAV3) = pacemaker même asymptomatique.\n**Piège** : c'est dans le BAV 2/1 (pas dans l'échappement du BAV3) que les QRS larges orientent vers l'infrahissien."},{"id":"231-qroc-108","type":"QROC","rank":"B","objective":"231-obj-10","tags":["diagnostic","ECG"],"difficulty":2,"question":"Quelle est la durée de la pause observée dans un bloc sinoatrial du 2e degré, par rapport au cycle PP ou RR normal ?","answer":"Le double de l'intervalle PP ou RR normal","accept":["double du PP","double du RR","2 fois l'intervalle PP","le double","double du cycle normal"],"keywords":["double"],"explanation":"Bloc sinoatrial du 2e degré : un cycle P-QRS-T entier manque, la pause vaut le double du PP/RR ; une P présente non conduite serait un BAV (p. 387).","src":"p. 387","deep":"**Pourquoi** : dans le bloc sinoatrial du 2e degré, un cycle P-QRS-T entier manque : la pause dure le double de l'intervalle PP ou RR normal (p. 387).\n**À relier** : autres aspects de dysfonction sinusale : asystole, P trop lentes, échappement jonctionnel.\n**Piège** : ici c'est la P elle-même qui manque (pas de P bloquée), contrairement à un BAV."},{"id":"231-qroc-109","type":"QROC","rank":"A","objective":"231-obj-10","tags":["diagnostic"],"difficulty":1,"question":"Devant une bradycardie, quelles sont les deux structures dont le dysfonctionnement peut être en cause ?","answer":"Le nœud sinusal et le nœud atrioventriculaire","accept":["nœud sinusal, NAV","nœud sinusal et NAV","noeud sinusal et noeud atrioventriculaire","nœud sinusal, nœud atrioventriculaire"],"keywords":["sinusal","atrioventriculaire"],"explanation":"Seuls le nœud sinusal (P lentes ou absentes) et le NAV (P normales mais bloquées) donnent une bradycardie ; les blocs de branche n'en donnent pas (p. 389, 415).","src":"p. 389","deep":"**Pourquoi** : la bradycardie vient soit du nœud sinusal (P trop lentes ou absentes), soit du nœud AV (P normales mais bloquées) (p. 389).\n**À relier** : algorithme : regarde les P ; plus de P que de QRS = BAV.\n**Piège** : les blocs de branche ne donnent pas de bradycardie."},{"id":"231-qroc-110","type":"QROC","rank":"B","objective":"231-obj-16","tags":["traitement"],"difficulty":2,"question":"Quelle molécule administrée en flash intraveineux permet de créer un bloc atrioventriculaire transitoire en cas d'échec des manœuvres vagales ?","answer":"L'adénosine","accept":["adénosine IV","adénosine","adenosine","adénosine intraveineuse"],"keywords":["adenosine"],"explanation":"Adénosine IV en flash : vagomimétique via les récepteurs purinergiques, BAV transitoire d'environ 10 s ; CI : asthme, hypotension, FA préexcitée (p. 390, 411).","src":"p. 390","deep":"**Pourquoi** : l'adénosine IV (flash) agit comme un vagomimétique via les récepteurs purinergiques : BAV transitoire d'une dizaine de secondes, utile quand les manœuvres vagales échouent (p. 390).\n**À relier** : CI : asthme (bronchospasme), hypotension, FA préexcitée (super-Wolff).\n**Piège** : effet très bref (≈ 10 s)."},{"id":"231-qroc-111","type":"QROC","rank":"A","objective":"231-obj-13","tags":["diagnostic","ECG"],"difficulty":1,"question":"Comment qualifie-t-on classiquement les intervalles RR au cours d'une fibrillation atriale ?","answer":"Irrégulièrement irréguliers","accept":["RR irrégulièrement irréguliers","irrégulièrement irréguliers","totalement irrégulier","complètement irréguliers"],"keywords":["irregulierement","irreguliers"],"explanation":"Dans la FA, les RR ne sont pas multiples d'une valeur commune (irrégulièrement irréguliers) ; un flutter à conduction variable reste fait de multiples du cycle F (p. 392, 394).","src":"p. 392","deep":"**Pourquoi** : dans la FA, les RR ne sont pas multiples d'une valeur commune : aucun motif répétitif, d'où « irrégulièrement irréguliers » (p. 392).\n**À relier** : seul diagnostic devant une tachycardie complètement irrégulière à QRS fins (diagnostic différentiel : ESA).\n**Piège** : un flutter à conduction variable est irrégulier mais avec des RR multiples d'un cycle commun."},{"id":"231-qroc-112","type":"QROC","rank":"B","objective":"231-obj-13","tags":["diagnostic","complications"],"difficulty":2,"question":"Quel élément électrocardiographique doit faire évoquer une fibrillation atriale associée à un bloc atrioventriculaire complet ?","answer":"Une activité ventriculaire devenue lente et régulière","accept":["rythme ventriculaire lent et régulier","RR réguliers et lents","bradycardie régulière","activité ventriculaire lente et régulière"],"keywords":["lent","regulier"],"explanation":"En BAV complet, l'échappement automatique est régulier : une FA devient lente ET régulière (fig. 15.32, p. 392).","src":"p. 392","deep":"**Pourquoi** : dans un BAV complet, les ventricules suivent un échappement automatique, régulier et lent ; associé à une FA, l'activité ventriculaire devient lente et régulière (p. 392).\n**À relier** : FA normale = RR irréguliers.\n**Piège** : une FA à cadence lente ET régulière n'est pas normale : cherche le BAV3."},{"id":"231-open-11","type":"OPEN","rank":"A","objective":"231-obj-06","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Comparez le bloc complet de branche droite et le bloc complet de branche gauche selon trois axes : la durée du QRS, l'aspect en V1, et l'aspect en V6. Précisez également en quoi le bloc de branche gauche complique l'interprétation d'une douleur thoracique.","rubric":[{"point":"Point commun : durée de QRS > 120 ms dans les deux blocs","weight":1.5},{"point":"BBD : aspect RsR' globalement positif en V1","weight":1.5},{"point":"BBD : aspect qRs avec onde S traînante en V6","weight":1},{"point":"BBG : aspect rS ou QS globalement négatif en V1","weight":1.5},{"point":"BBG : notch avec onde R exclusive en V6, D1, aVL","weight":1},{"point":"BBG : discordance appropriée T/QRS rendant le territoire antérieur difficile à interpréter, imposant une évaluation cardiologique rapide devant une douleur thoracique persistante sans attendre la troponine","weight":2.5}],"model":"**Durée du QRS** : dans les deux blocs, le QRS dépasse 120 ms.\n\n**Bloc de branche droite** : en V1, le QRS est globalement positif avec un aspect RsR' ; en V6, on observe un aspect qRs avec une onde S traînante, arrondie.\n\n**Bloc de branche gauche** : en V1, le QRS est globalement négatif, en aspect rS ou QS ; en V6 (ainsi qu'en D1 et aVL), on observe un notch, correspondant à l'activation successive du septum puis de la paroi latérale, avec le plus souvent une onde R exclusive.\n\n**Difficulté diagnostique du BBG** : les QRS larges du BBG s'accompagnent d'une discordance appropriée, où la polarité de l'onde T est opposée à celle du QRS. Associée à un segment ST parfois ascendant en V1-V2, cette discordance peut simuler à tort un syndrome coronarien aigu avec sus-décalage. Devant une douleur thoracique persistante chez un patient porteur d'un BBG, le diagnostic d'infarctus antérieur doit donc être évoqué et conduire à une évaluation cardiologique rapide, sans attendre le dosage de troponine.","src":"p. 378-381"},{"id":"231-open-12","type":"OPEN","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Décrivez les principaux types de blocs atrioventriculaires en rythme sinusal (BAV1, BAV2 Mobitz 1, BAV2 Mobitz 2, BAV2 2/1, BAV3) en précisant pour chacun la relation entre onde P et complexe QRS.","rubric":[{"point":"BAV1 : allongement fixe et constant du PR, sans onde P bloquée","weight":1.5},{"point":"BAV2 Mobitz 1 (Wenckebach) : allongement progressif du PR puis une onde P bloquée, siège suprahissien","weight":1.5},{"point":"BAV2 Mobitz 2 : PR constant puis onde P bloquée de façon inopinée, siège infrahissien","weight":1.5},{"point":"BAV2 2/1 : une onde P bloquée sur deux, siège suprahissien ou infrahissien selon le contexte","weight":1.5},{"point":"BAV3 : dissociation atrioventriculaire complète, aucune onde P conduite, ondes P régulières et à fréquence normale","weight":2},{"point":"Orientation vers le siège du bloc selon la largeur du QRS et la présence d'un Mobitz 1 à d'autres moments","weight":2}],"model":"**BAV1** : allongement fixe et constant de l'espace PR au-delà de 200 ms, sans aucune onde P bloquée.\n\n**BAV2 Mobitz 1 (Luciani-Wenckebach)** : allongement progressif du PR cycle après cycle, jusqu'à une onde P qui n'est pas suivie de QRS (onde P bloquée). Ce type est habituellement de siège suprahissien.\n\n**BAV2 Mobitz 2** : le PR reste constant, puis une onde P est bloquée de façon inopinée, sans allongement préalable. Ce type est de siège infrahissien.\n\n**BAV2 2/1** : une onde P sur deux est bloquée de façon régulière ; le siège (suprahissien ou infrahissien) s'oriente selon la largeur du QRS (fin = plutôt suprahissien, large = plutôt infrahissien) et la présence ou non d'un Mobitz 1 à d'autres moments du tracé.\n\n**BAV3 (complet)** : dissociation atrioventriculaire complète ; les ondes P restent régulières et à une fréquence normale, mais aucune n'est conduite aux ventricules, un rythme d'échappement (jonctionnel ou ventriculaire) prenant le relais.","src":"p. 385-387"},{"id":"231-open-13","type":"OPEN","rank":"B","objective":"231-obj-10","tags":["diagnostic","ECG"],"difficulty":2,"prompt":"Une patiente de 70 ans présente sur son holter des pauses sinusales avec, par moments, un rythme lent régulier à QRS fins sans onde P visible devant le QRS. Expliquez le mécanisme évoqué et la manière de le reconnaître sur l'ECG, en distinguant les différents aspects possibles de dysfonction sinusale.","rubric":[{"point":"Mécanisme : dysfonction sinusale marquée, responsable d'un rythme d'échappement jonctionnel","weight":2},{"point":"Aspect 1 : asystole, tracé plat sans activité visible","weight":1},{"point":"Aspect 2 : pause par bloc sinoatrial du 2e degré, durée double du cycle PP/RR normal","weight":1.5},{"point":"Aspect 3 : échappement jonctionnel, onde P absente devant le QRS ou rétrograde négative en D2","weight":2},{"point":"Lien avec le cas présenté : QRS fins réguliers sans P visible devant = échappement jonctionnel évocateur de dysfonction sinusale marquée","weight":1.5}],"model":"Chez cette patiente, l'absence d'onde P devant des QRS fins, réguliers et lents évoque un **rythme d'échappement jonctionnel** : il apparaît en cas de **dysfonction sinusale marquée**, le nœud sinusal (pacemaker physiologique dominant) étant défaillant.\n\nLa dysfonction sinusale peut se manifester sous plusieurs aspects : une asystole (tracé plat sans aucune activité), une pause par bloc sinoatrial du 2e degré (absence complète d'un cycle P-QRS-T, de durée égale au double de l'intervalle PP ou RR normal), ou, comme ici, un échappement jonctionnel où l'onde P n'est plus visible devant le QRS — elle peut être rétrograde, visible derrière le QRS et négative en D2 du fait du sens rétrograde de l'activation atriale à partir de la jonction.","src":"p. 376, 387-389"},{"id":"231-open-14","type":"OPEN","rank":"A","objective":"231-obj-13","tags":["diagnostic","physiopathologie"],"difficulty":2,"prompt":"Un homme de 68 ans présente des palpitations. Son ECG montre des QRS fins à une fréquence ventriculaire de 140 bpm, avec des intervalles RR irrégulièrement irréguliers et une absence d'onde P identifiable, remplacée par une trémulation de la ligne de base. Expliquez le diagnostic évoqué, son mécanisme électrophysiologique global, et le rôle protecteur du nœud atrioventriculaire dans cette situation.","rubric":[{"point":"Diagnostic : fibrillation atriale (activation atriale anarchique)","weight":2},{"point":"Argument QRS fins et irrégulièrement irréguliers (RR non multiples d'une valeur commune)","weight":1.5},{"point":"Argument trémulation de la ligne de base remplaçant l'activité sinusale","weight":1},{"point":"Rôle de filtre décrémentiel du NAV empêchant une conduction 1/1","weight":2},{"point":"Conséquence : sans ce filtre, risque de fibrillation ventriculaire ou de tachycardie extrême","weight":1.5},{"point":"Mention que le passage AV peut se faire en 1/1, 2/1 ou en alternance selon le tonus vagal, l'âge et les médicaments","weight":1.5}],"model":"Le tableau (QRS fins, RR irrégulièrement irréguliers, absence d'onde P remplacée par une trémulation de la ligne de base, fréquence ventriculaire à 140 bpm) est celui d'une **fibrillation atriale**, correspondant à une activation atriale anarchique.\n\nLe nœud atrioventriculaire (NAV) joue ici un rôle protecteur essentiel grâce à sa fonction de « filtre » à conduction décrémentielle : au-delà d'une certaine fréquence atriale, les ventricules ne suivent plus en 1 pour 1. Sans ce filtre, chaque épisode de FA entraînerait une fibrillation ventriculaire.\n\nSelon la fréquence atriale et l'intensité du filtre (qui dépend de l'âge, du tonus vagal et des médicaments ralentisseurs du NAV), le passage aux ventricules peut se faire en 1/1, en 2/1, en alternance 1/1-2/1, ou selon un bloc à conduction variable, ce qui explique la fréquence ventriculaire observée chez ce patient.","src":"p. 390-392"},{"id":"231-qcm-201","type":"QRM","rank":"A","objective":"231-obj-14","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Un homme de 70 ans consulte pour des palpitations régulières. L'ECG montre une activité atriale organisée à environ 300/min, en dents de scie dans les dérivations inférieures. Concernant le flutter atrial :","options":[{"t":"La fréquence atriale peut être plus lente en cas de dilatation atriale","ok":true,"why":"Le front met plus de temps à parcourir un circuit plus long : fréquence atriale < 300/min sur oreillette dilatée (p. 394)."},{"t":"Dans la forme typique (commune) antihoraire, les ondes F sont négatives en D2, D3 et aVF","ok":true,"why":"Typique antihoraire (isthme cavotricuspide) : F négatives en D2, D3, aVF, positives en V1, négatives en V6 ; horaire = polarités inversées (p. 394)."},{"t":"Le mécanisme est une réentrée organisée autour d'un obstacle anatomique ou fonctionnel","ok":true,"why":"Le flutter est le modèle de la réentrée : boucle atriale qui se répète à l'identique, d'où une activité monomorphe (p. 393)."},{"t":"Le diagnostic de certitude repose toujours sur la seule morphologie des ondes F à l'ECG","ok":false,"why":"Faux : typique/atypique n'est pas fiable à l'ECG (« d'aspect typique ») ; certitude par la fréquence sur cœur sain ou par l'exploration électrophysiologique (p. 394)."},{"t":"L'activité atriale est fibrillatoire, sans onde F identifiable","ok":false,"why":"Faux : fibrillatoire = FA ; le flutter a des ondes F organisées, sans retour à la ligne de base dans au moins une dérivation (p. 393)."}],"explanation":"Le flutter atrial est une arythmie par réentrée organisée, le plus souvent autour de l'isthme cavotricuspide pour la forme typique, avec une fréquence atriale habituelle proche de 300/min et une polarité caractéristique des ondes F.","src":"p. 393-394","deep":"**Pourquoi** : le flutter est une réentrée organisée (boucle atriale qui se répète à l'identique) : activité atriale monomorphe à ≈ 300/min (240-340), sans retour à la ligne isoélectrique, en dents de scie (p. 393-394).\n**À relier** : typique antihoraire = isthme cavotricuspide, ondes F négatives en D2-D3-aVF, positives en V1 ; une oreillette dilatée ralentit la fréquence.\n**Piège** : typique/atypique n'est pas parfaitement fiable à l'ECG : on parle de flutter d'aspect typique."},{"id":"231-qcm-202","type":"QRM","rank":"A","objective":"231-obj-14","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant la conduction ventriculaire au cours d'un flutter atrial :","options":[{"t":"Une manœuvre vagale peut ralentir transitoirement la cadence ventriculaire et démasquer les ondes F","ok":true,"why":"Elle renforce le filtre du NAV : moins de QRS, les F apparaissent ; utile surtout en 1/1 ou 2/1 où les QRS sont serrés (p. 395)."},{"t":"La cadence ventriculaire est toujours parfaitement régulière","ok":false,"why":"Faux : le filtrage du NAV peut varier (2/1, 3/1, 4/1…) : flutter à conduction variable, irrégulier (p. 394)."},{"t":"Une conduction 3/1 correspond à une fréquence ventriculaire proche de 100/min","ok":true,"why":"Activité atriale ≈ 300/min divisée par 3 = 100/min ; 2/1 = 150, 4/1 = 75 (p. 394)."},{"t":"La conduction 1/1 est le mode de transmission habituel du flutter","ok":false,"why":"Faux : la forme usuelle est 2/1 (≈ 150/min) ; un 1/1 donnerait ≈ 300/min aux ventricules (p. 390, 394)."},{"t":"La conduction 2/1 donne une cadence ventriculaire proche de 150/min","ok":true,"why":"300/min atrial ÷ 2 = 150/min : forme usuelle de conduction du flutter (3/1 = 100, 4/1 = 75) (p. 394)."}],"explanation":"La cadence ventriculaire du flutter dépend du degré de filtrage nodal (2/1 le plus souvent, parfois 3/1 ou variable) ; les manœuvres vagales aident à démasquer l'activité atriale sous-jacente.","src":"p. 394-395","deep":"**Pourquoi** : le NAV filtre l'activité atriale : 2/1 → ≈ 150/min (forme usuelle), 3/1 → ≈ 100, 4/1 → ≈ 75 ; le filtrage peut varier (conduction variable) (p. 394-395).\n**À relier** : une manœuvre vagale ralentit transitoirement les QRS et démasque les ondes F, surtout en flutter 1/1 ou 2/1.\n**Piège** : la conduction usuelle est 2/1 (pas 1/1) et la cadence n'est pas toujours régulière."},{"id":"231-qcm-203","type":"QRM","rank":"A","objective":"231-obj-15","tags":["ECG","diagnostic"],"difficulty":2,"stem":"À propos des tachycardies jonctionnelles :","options":[{"t":"Dans la réentrée intranodale, l'activité atriale rétrograde est habituellement bien visible avant le QRS","ok":false,"why":"Faux : oreillettes et ventricules sont activés quasi simultanément : P invisible ou devinée dans le ST (p. 395-396)."},{"t":"Les tachycardies jonctionnelles sont rares","ok":false,"why":"Faux : elles sont fréquentes (maladie de Bouveret), très régulières, souvent ≈ 200/min (p. 395)."},{"t":"La réentrée intranodale est un mécanisme de réentrée au sein du nœud atrioventriculaire","ok":true,"why":"1re forme : boucle dans le NAV ; réduite par manœuvres vagales ou adénosine car elle dépend du NAV (p. 395, 397)."},{"t":"La tachycardie par rythme réciproque correspond à une réentrée par une voie accessoire (faisceau de Kent)","ok":true,"why":"2e forme : la boucle emprunte NAV + faisceau de Kent ; cette voie accessoire peut aussi donner une préexcitation (p. 396, 410)."},{"t":"Ces tachycardies sont volontiers très régulières, souvent autour de 200/min","ok":true,"why":"Très régulières, ≈ 200/min (130-260 selon le mécanisme et le tonus sympathique) (p. 395)."}],"explanation":"Les tachycardies jonctionnelles, fréquentes et très régulières (souvent autour de 200/min), relèvent d'une réentrée intranodale (activité atriale souvent invisible) ou d'un rythme réciproque par voie accessoire (faisceau de Kent).","src":"p. 395-396","deep":"**Pourquoi** : tachycardie jonctionnelle (maladie de Bouveret) = très régulière, souvent ≈ 200/min (130-260), de deux types : réentrée intranodale ou rythme réciproque par voie accessoire (faisceau de Kent) (p. 395-396).\n**À relier** : dans l'intranodale, l'activation atriale et ventriculaire est quasi synchrone : la P est invisible ou devinée dans le ST. Réduction par manœuvres vagales ou adénosine IV.\n**Piège** : ces tachycardies sont fréquentes, pas rares."},{"id":"231-qcm-204","type":"QRM","rank":"B","objective":"231-obj-16","tags":["diagnostic","traitement"],"difficulty":2,"stem":"Concernant l'intérêt des manœuvres vagales et de l'adénosine devant une tachycardie :","options":[{"t":"Elles sont indiquées en première intention en cas de mauvaise tolérance hémodynamique","ok":false,"why":"Faux : mauvaise tolérance = cardioversion électrique externe d'emblée ; manœuvres vagales ± adénosine si bonne tolérance (fig. 15.51, p. 405)."},{"t":"Elles bloquent transitoirement le nœud atrioventriculaire","ok":true,"why":"Elles créent un BAV transitoire : effet diagnostique (démasquent l'activité atriale) ou thérapeutique (arrêtent une réentrée nodale) (p. 390, 405)."},{"t":"Elles sont utiles pour préciser le diagnostic lorsque celui-ci n'est pas évident","ok":true,"why":"En ralentissant le passage AV, elles démasquent l'activité atriale et font le diagnostic dans la majorité des cas (p. 405)."},{"t":"Elles n'ont habituellement aucun effet sur la fréquence ventriculaire d'un flutter","ok":false,"why":"Faux : elles ralentissent transitoirement la cadence ventriculaire et démasquent les ondes F (p. 395)."},{"t":"Elles arrêtent la tachycardie jonctionnelle en interrompant la réentrée dépendante du nœud atrioventriculaire","ok":true,"why":"Le Collège précise que les tachycardies jonctionnelles sont réduites (retour en rythme sinusal) par les manœuvres vagales ou l'adénosine IV."}],"explanation":"Les manœuvres vagales et l'adénosine bloquent transitoirement le nœud atrioventriculaire : elles démasquent l'activité atriale (flutter, TAF) ou arrêtent la tachycardie si elle en dépend (jonctionnelle), mais ne remplacent pas la cardioversion en cas de mauvaise tolérance.","src":"p. 396-397, 405","deep":"**Pourquoi** : manœuvres vagales et adénosine bloquent transitoirement le NAV (BAV transitoire) : elles démasquent l'activité atriale (flutter) ou réduisent une tachycardie jonctionnelle, et aident au diagnostic dans la majorité des cas (p. 396-397, 405).\n**À relier** : bonne tolérance = vagales ± adénosine ; mauvaise tolérance = cardioversion électrique externe.\n**Piège** : chez un patient instable, ne retarde pas le choc par des manœuvres."},{"id":"231-qcm-205","type":"QRM","rank":"A","objective":"231-obj-17","tags":["ECG","diagnostic"],"difficulty":1,"stem":"Concernant les extrasystoles :","options":[{"t":"Une extrasystole atriale se traduit par une onde P précoce, de morphologie différente de la P sinusale, suivie d'un QRS fin","ok":true,"why":"Foyer ectopique atrial : P' précoce de forme différente, conduite normalement (QRS fin) ; elle peut se cacher dans la T précédente (p. 397-398)."},{"t":"Elles correspondent à une activation retardée (trop tardive) d'une cavité cardiaque par rapport à l'activation attendue","ok":false,"why":"Faux : une extrasystole est une activation prématurée (trop précoce) par rapport à l'activation attendue ; elle peut être atriale, jonctionnelle ou ventriculaire (p. 397)."},{"t":"Une extrasystole ventriculaire se traduit par un QRS fin précédé d'une onde P normale","ok":false,"why":"Faux : l'ESV naît sous le His, se propage de proche en proche : QRS large, ± P' rétrograde (p. 397-398)."},{"t":"Des extrasystoles fréquentes ou polymorphes ne doivent jamais faire rechercher de cardiopathie sous-jacente","ok":false,"why":"Faux : fréquentes ou polymorphes, elles doivent faire rechercher une cardiopathie (p. 397)."},{"t":"Leur charge (nombre par 24 heures) augmente avec l'âge et la présence d'une cardiopathie","ok":true,"why":"Les extrasystoles sont physiologiques sur cœur sain, mais leur charge/24 h croît avec l'âge et la cardiopathie ; fréquentes ou polymorphes = chercher une cardiopathie (p. 397)."}],"explanation":"Les extrasystoles sont fréquentes et souvent physiologiques sur cœur sain, mais leur caractère fréquent, polymorphe ou leur charge élevée doit faire rechercher une cardiopathie sous-jacente.","src":"p. 397","deep":"**Pourquoi** : une extrasystole est une activation prématurée. Atriale : P' précoce de morphologie différente + QRS fin (P parfois masquée dans la T précédente) ; jonctionnelle : QRS fin ± P' rétrograde (rare) ; ventriculaire : QRS large ± P' rétrograde (p. 397).\n**À relier** : la charge (nombre/24 h) augmente avec l'âge et la cardiopathie ; ESV fréquentes ou polymorphes = chercher une cardiopathie.\n**Piège** : une ESV est à QRS LARGE."},{"id":"231-qcm-206","type":"QRM","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic","urgence"],"difficulty":2,"stem":"Une patiente de 55 ans, connue coronarienne, présente une tachycardie régulière à QRS larges (140 ms) à 160/min, mal tolérée. Concernant le diagnostic et la conduite à tenir :","options":[{"t":"Une TV ne peut jamais dégénérer en fibrillation ventriculaire","ok":false,"why":"Faux : la TV est un état électrique instable qui dégénère en FV puis asystolie (anoxie), présente dans plus de la moitié des morts subites (p. 398)."},{"t":"Le mécanisme le plus fréquent de TV sur cardiopathie est un automatisme anormal","ok":false,"why":"Faux : sur cardiopathie = réentrée autour d'une fibrose (post-infarctus) ; l'automatisme anormal domine sur cœur sain (p. 398-399)."},{"t":"Toute tachycardie régulière à QRS larges doit être considérée comme une tachycardie ventriculaire jusqu'à preuve du contraire","ok":true,"why":"Règle de sécurité : une TV méconnue est mortelle, alors qu'un bloc de branche est sans conséquence immédiate (p. 398, 415)."},{"t":"L'existence d'une cardiopathie sous-jacente est un argument en faveur d'une TV","ok":true,"why":"La plupart des TV sont favorisées par une cardiopathie (fibrose d'infarctus) : argument en faveur (encadré 15.2, p. 400)."},{"t":"Il s'agit certainement d'une tachycardie supraventriculaire car la patiente est symptomatique et mal tolérée","ok":false,"why":"Faux : la tolérance hémodynamique décide de la conduite (mauvaise tolérance = cardioversion électrique externe, p. 405), pas du mécanisme ; régulière à QRS larges = TV jusqu'à preuve du contraire, et la cardiopathie est un argument en faveur de la TV (p. 398, 400)."}],"explanation":"Devant une tachycardie régulière à QRS larges, le diagnostic de TV doit être retenu par défaut, en particulier sur cardiopathie connue, car il s'agit d'un état instable pouvant se compliquer d'arrêt cardiaque.","src":"p. 398-400","trap":"Toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire : c'est un état électrique instable, prémonitoire de l'arrêt cardiaque (Collège p. 398).","deep":"**Pourquoi** : une tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire : elle naît sous la bifurcation hissienne et se propage de proche en proche (QRS large). Sur cardiopathie, mécanisme le plus fréquent = réentrée autour d'une fibrose post-infarctus (p. 398-400).\n**À relier** : état instable, prémonitoire d'arrêt (TV → FV → asystolie) ; mal tolérée = cardioversion électrique externe.\n**Piège** : ne conclus pas à une TSV avec bloc de branche par défaut."},{"id":"231-qcm-207","type":"QRM","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic"],"difficulty":3,"stem":"Concernant les arguments électrocardiographiques en faveur du diagnostic de tachycardie ventriculaire :","options":[{"t":"Une déviation axiale extrême, avec QRS positif en aVR, est en faveur d'une TV","ok":true,"why":"Un QRS positif en aVR (axe extrême) ne se voit ni dans le BBD ni dans le BBG : argument en faveur de la TV (p. 400, 402)."},{"t":"Les complexes de capture et de fusion ne peuvent exister qu'en l'absence de dissociation ventriculo-atriale","ok":false,"why":"Inversé : ils supposent des P indépendantes qui « capturent » le ventricule, donc une dissociation VA (p. 400)."},{"t":"Une concordance positive ou négative de V1 à V6 est en faveur d'une TV","ok":true,"why":"QRS tout positifs (R) ou tout négatifs (QS) de V1 à V6 : argument en faveur, pas de certitude (p. 400)."},{"t":"Un aspect de bloc de branche typique élimine formellement le diagnostic de TV","ok":false,"why":"Faux : seul un aspect DIFFÉRENT d'un bloc habituel est un argument pour la TV ; un aspect typique n'élimine rien (règle « jusqu'à preuve du contraire ») (p. 398, 400)."},{"t":"La dissociation ventriculo-atriale, avec plus d'ondes P que de QRS, est un argument de certitude","ok":false,"why":"Faux : l'argument de certitude est d'avoir plus de QRS que d'ondes P (la tachycardie vient alors forcément du ventricule) ; plus d'ondes P que de QRS évoque au contraire la dissociation atrioventriculaire d'un BAV."}],"explanation":"Les arguments de certitude de TV sont la dissociation ventriculo-atriale (plus de QRS que d'ondes P, à ne pas confondre avec la dissociation atrioventriculaire du BAV complet) et les complexes de capture/fusion ; la concordance et l'axe extrême en aVR sont des arguments en faveur, tout comme la cardiopathie sous-jacente.","src":"p. 400-402","deep":"**Pourquoi** : arguments de CERTITUDE : dissociation ventriculo-atriale (plus de QRS que de P), complexes de capture/fusion (possibles seulement s'il y a dissociation). Arguments EN FAVEUR : cardiopathie, concordance V1-V6, axe extrême (QRS positif en aVR), QRS larges différents d'un bloc habituel (p. 400-402).\n**Piège** : plus de QRS que de P = TV ; plus de P que de QRS = dissociation d'un BAV."},{"id":"231-qcm-208","type":"QRM","rank":"A","objective":"231-obj-18","tags":["ECG","pièges"],"difficulty":3,"stem":"Concernant les complexes de capture et de fusion observés au cours d'une tachycardie ventriculaire :","options":[{"t":"Ils traduisent l'absence de toute activité atriale résiduelle pendant la TV","ok":false,"why":"Faux : ils prouvent qu'une P indépendante a atteint le ventricule, donc une activité atriale dissociée persistante (p. 400-401)."},{"t":"Un complexe de fusion résulte de la compétition entre l'activation ventriculaire par la TV et par l'influx sinusal","ok":true,"why":"Le ventricule est activé à la fois par la TV et par l'influx sinusal : QRS intermédiaire (fig. 15.43, p. 401)."},{"t":"Un complexe de capture correspond à un QRS fin, entièrement dépolarisé par l'influx sinusal via les voies de conduction normales","ok":true,"why":"L'influx sinusal emprunte le His-Purkinje avant que la TV n'active le ventricule : QRS fin (p. 401)."},{"t":"Ils ne s'observent que dans les torsades de pointes","ok":false,"why":"Faux : ce sont des arguments de certitude de TV, possibles dès qu'il y a dissociation VA (p. 400)."},{"t":"Ces complexes sont précédés d'une onde P","ok":true,"why":"C'est une P (dissociée) qui passe par les voies normales : QRS fin (capture) ou intermédiaire (fusion) (p. 400)."}],"explanation":"Les complexes de capture (QRS fin) et de fusion (QRS intermédiaire) sont des arguments de certitude de TV, car ils supposent qu'une onde P a pu, ponctuellement, dépolariser le ventricule par les voies normales.","src":"p. 400-401","deep":"**Pourquoi** : capture = QRS fin précédé d'une P (l'influx sinusal passe par les voies de conduction et dépolarise le ventricule avant la TV) ; fusion = QRS intermédiaire (compétition entre TV et influx sinusal) (p. 400-401).\n**À relier** : ils n'existent que s'il y a dissociation ventriculo-atriale : arguments de certitude de TV.\n**Astuce** : capture = QRS fin ; fusion = mélange, QRS intermédiaire."},{"id":"231-qcm-209","type":"QRM","rank":"A","objective":"231-obj-19","tags":["urgence","ECG"],"difficulty":1,"stem":"Concernant la fibrillation ventriculaire :","options":[{"t":"Le pouls carotidien reste perçu malgré la perte de connaissance","ok":false,"why":"Faux : en FV le débit est nul, le pouls carotidien est aboli : arrêt cardiaque (p. 403)."},{"t":"Elle se traduit à l'ECG par une tachycardie régulière à QRS fins","ok":false,"why":"Faux : FV = tachycardie irrégulière à QRS larges polymorphes (p. 403)."},{"t":"Elle correspond à un arrêt cardiaque","ok":true,"why":"Débit cardiaque nul → perte de connaissance en quelques secondes, pouls aboli : arrêt cardiaque, choc immédiat (p. 402-403)."},{"t":"Elle peut être bien tolérée dans tous les cas et ne nécessite pas de prise en charge urgente","ok":false,"why":"Faux : urgence absolue, choc électrique immédiat avant tout autre geste, massage en attendant (p. 402)."},{"t":"La perte de connaissance survient habituellement après quelques secondes, du fait d'un débit cardiaque nul","ok":true,"why":"Le débit est nul : perte de connaissance en quelques secondes, pouls carotidien aboli ; choc électrique en urgence (p. 403)."}],"explanation":"La fibrillation ventriculaire est une tachycardie irrégulière à QRS larges polymorphes qui entraîne un arrêt cardiaque en quelques secondes et impose un choc électrique immédiat.","src":"p. 402-403","deep":"**Pourquoi** : en FV l'activité ventriculaire est anarchique, le débit cardiaque est nul : perte de connaissance en quelques secondes, pouls carotidien aboli = arrêt cardiaque. ECG : tachycardie irrégulière à QRS larges polymorphes (p. 402-403).\n**À relier** : choc électrique immédiat avant tout autre geste, massage cardiaque en attendant.\n**Piège** : la FV n'est jamais régulière ni à QRS fins."},{"id":"231-qcm-210","type":"QRM","rank":"A","objective":"231-obj-20","tags":["ECG","biologie","étiologie"],"difficulty":2,"stem":"Parmi les situations suivantes, lesquelles favorisent la survenue de torsades de pointes par allongement de l'intervalle QT ?","options":[{"t":"Hyperkaliémie","ok":false,"why":"Faux : c'est l'HYPOkaliémie qui allonge le QT ; l'hyperkaliémie donne T pointues, PR long, QRS larges (p. 404, 408)."},{"t":"Hypercalcémie","ok":false,"why":"Faux : c'est l'HYPOcalcémie qui allonge le QT et expose aux torsades (p. 404)."},{"t":"Tachycardie sinusale rapide","ok":false,"why":"Faux : c'est au contraire la bradycardie extrême qui allonge le QT et favorise les torsades ; le traitement comporte d'ailleurs l'accélération de la fréquence cardiaque."},{"t":"Hypomagnésémie","ok":true,"why":"L'hypomagnésémie fait partie, avec l'hypokaliémie et l'hypocalcémie, des causes ioniques d'allongement du QT (p. 404)."},{"t":"Association de médicaments allongeant l'intervalle QT","ok":true,"why":"Antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens… : vérifier l'ordonnance devant un QT long (p. 404)."}],"explanation":"Les torsades de pointes surviennent sur un terrain d'allongement du QT : hypokaliémie, hypocalcémie, hypomagnésémie, bradycardie extrême, médicaments allongeant le QT ou QT long congénital.","src":"p. 403-404","deep":"**Pourquoi** : la torsade de pointes survient sur un QT allongé : bradycardie extrême, hypokaliémie, hypocalcémie, hypomagnésémie, association de médicaments allongeant le QT, QT long congénital (p. 403-404).\n**Astuce** : « hypo » (K, Ca, Mg) = QT long.\n**Piège** : l'hyperkaliémie donne T pointues, PR long et QRS large ; c'est la bradycardie extrême, pas la tachycardie, qui favorise les torsades."},{"id":"231-qcm-211","type":"QRM","rank":"B","objective":"231-obj-20","tags":["traitement","urgence"],"difficulty":2,"stem":"Concernant la prise en charge d'une torsade de pointes :","options":[{"t":"Elle consiste à ralentir la fréquence cardiaque","ok":false,"why":"Faux : la bradycardie allonge le QT ; on ACCÉLÈRE la FC (p. 404)."},{"t":"Elle consiste à corriger les troubles ioniques en cause","ok":true,"why":"Hypokaliémie, hypocalcémie, hypomagnésémie allongent le QT : leur correction fait partie du traitement (p. 404)."},{"t":"Elle justifie d'introduire un antiarythmique allongeant le QT pour prévenir les récidives","ok":false,"why":"Faux : plusieurs antiarythmiques figurent parmi les médicaments allongeant le QT ; il faut au contraire arrêter les médicaments responsables, corriger les ions et accélérer la FC."},{"t":"Elle peut dégénérer spontanément en fibrillation ventriculaire","ok":true,"why":"TV polymorphe qui s'arrête seule ou dégénère en FV, dont elle est alors indiscernable (p. 403)."},{"t":"Un allongement isolé du QT sur l'ECG ne justifie jamais de vérifier l'ordonnance du patient","ok":false,"why":"Faux : un QT long doit alerter : vérifier médicaments et ionogramme pour prévenir une mort subite (p. 404)."}],"explanation":"La torsade de pointes impose de corriger les troubles ioniques, d'arrêter les médicaments responsables et d'accélérer la fréquence cardiaque ; elle peut s'arrêter spontanément ou dégénérer en fibrillation ventriculaire.","src":"p. 404","deep":"**Pourquoi** : le traitement agit sur les causes de l'allongement du QT : corriger les troubles ioniques, arrêter les médicaments allongeant le QT, accélérer la fréquence cardiaque (p. 404).\n**À relier** : une torsade est une TV polymorphe qui s'arrête spontanément ou dégénère en FV (indiscernable de la FV une fois installée).\n**Piège** : ne ralentis pas la FC et n'ajoute pas un médicament allongeant le QT."},{"id":"231-qcm-212","type":"QRM","rank":"A","objective":"231-obj-17","tags":["ECG"],"difficulty":1,"stem":"Concernant la description des extrasystoles :","options":[{"t":"Un battement sur deux définit un bigéminisme","ok":true,"why":"Extrasystoles rythmées : une extrasystole un battement sur deux = bigéminisme (p. 398)."},{"t":"Un battement sur trois définit un trigéminisme","ok":true,"why":"Une extrasystole un battement sur trois = trigéminisme ; à distinguer des formes répétitives (doublet, triplet, salve) (p. 398)."},{"t":"Une salve désigne une extrasystole strictement isolée","ok":false,"why":"Faux : la salve est une forme répétitive (après doublet et triplet), plusieurs extrasystoles successives (p. 398)."},{"t":"Un doublet correspond à une extrasystole survenant un battement sur deux","ok":false,"why":"Faux : une extrasystole un battement sur deux définit le bigéminisme (extrasystoles rythmées) ; le doublet est une forme répétitive, avec deux extrasystoles qui se suivent."},{"t":"Les extrasystoles jonctionnelles sont les plus fréquentes des trois types (atriales, jonctionnelles, ventriculaires)","ok":false,"why":"Faux : les jonctionnelles sont rares et traduisent le plus souvent une pathologie de la jonction nodohissienne (p. 397)."}],"explanation":"Les extrasystoles peuvent être répétitives (doublets, triplets, salves) ou rythmées (bigéminisme, trigéminisme) ; les formes jonctionnelles sont les plus rares des trois topographies.","src":"p. 397-398","deep":"**Pourquoi** : les extrasystoles peuvent être répétitives (doublets, triplets, salves) ou rythmées (bigéminisme = 1 battement sur 2, trigéminisme = 1 sur 3) (p. 397-398).\n**À relier** : topographie : atriale (P' précoce + QRS fin), jonctionnelle (rare, pathologie de la jonction nodohissienne), ventriculaire (QRS large).\n**Piège** : un doublet (2 extrasystoles qui se suivent) n'est pas un bigéminisme (rythme 1 sur 2)."},{"id":"231-qcm-214","type":"QRM","rank":"A","objective":"231-obj-12","tags":["ECG","diagnostic","urgence"],"difficulty":2,"stem":"Devant une tachycardie (FC > 100/min) bien tolérée sur le plan hémodynamique, selon la démarche décisionnelle du Collège :","options":[{"t":"Les manœuvres vagales (ou l'adénosine en cas d'échec) permettent, dans la majorité des cas, de préciser le diagnostic","ok":true,"why":"En créant un BAV transitoire, elles démasquent l'activité atriale (flutter, TAF) ou arrêtent une jonctionnelle : diagnostic dans la majorité des cas (fig. 15.51, p. 405)."},{"t":"Si elles arrêtent la tachycardie, le diagnostic le plus probable est une tachycardie jonctionnelle","ok":true,"why":"La réentrée jonctionnelle passe par le NAV : le bloquer l'interrompt (retour en sinusal) (p. 397, 405)."},{"t":"Une tachycardie complètement irrégulière à QRS fins oriente en premier lieu vers une fibrillation atriale","ok":true,"why":"Seul diagnostic d'une tachycardie complètement irrégulière à QRS fins ; diagnostic différentiel : extrasystoles atriales (p. 405, 415)."},{"t":"La cardioversion électrique externe est le traitement de première intention en cas de bonne tolérance hémodynamique","ok":false,"why":"Faux : le choc d'emblée est réservé à la mauvaise tolérance ; en bonne tolérance, manœuvres vagales ± adénosine (p. 405)."},{"t":"Si elles démasquent une activité atriale organisée en dents de scie, le diagnostic est un flutter","ok":true,"why":"Le ralentissement des QRS révèle les ondes F monomorphes en dents de scie : flutter (p. 393, 405)."}],"explanation":"L'algorithme distingue d'abord tachycardie régulière/irrégulière, puis QRS fins/larges ; les manœuvres vagales/adénosine sont l'outil diagnostique et parfois thérapeutique de première intention en bonne tolérance hémodynamique.","src":"p. 405","deep":"**Pourquoi** : algorithme : tachycardie = FC > 100 ; irrégulière = FA (diagnostic différentiel : ESA) ; régulière : largeur des QRS. Bonne tolérance : manœuvres vagales ± adénosine (BAV transitoire), souvent diagnostiques (p. 405).\n**À relier** : si la tachycardie s'arrête = jonctionnelle ; si des ondes F en dents de scie apparaissent = flutter. Mauvaise tolérance = cardioversion électrique externe.\n**Piège** : le choc n'est pas le traitement de 1re intention en cas de bonne tolérance."},{"id":"231-qru-201","type":"QRU","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":1,"stem":"Quelle définition correspond à une tachycardie ventriculaire non soutenue (TVNS) ?","options":[{"t":"Une tachycardie ventriculaire durant entre 3 battements consécutifs et 30 secondes","ok":true,"why":"Il faut au moins 3 battements consécutifs à QRS > 120 ms pour parler de TV ; jusqu'à 30 s = non soutenue, au-delà = soutenue (p. 399)."},{"t":"Une tachycardie ventriculaire durant plus d'une minute","ok":false,"why":"Faux : le seuil est 30 s ; au-delà la TV est soutenue (p. 399)."},{"t":"Une tachycardie ventriculaire durant moins de 3 battements","ok":false,"why":"Faux : il faut au moins 3 battements consécutifs à QRS > 120 ms ; en dessous, extrasystoles (doublet) (p. 398-399)."},{"t":"Une tachycardie ventriculaire durant plus de 30 secondes","ok":false,"why":"Faux : > 30 s = TV soutenue ; la TVNS va de 3 battements à 30 s (p. 399)."},{"t":"Une tachycardie ventriculaire de n'importe quelle durée, dès qu'elle est asymptomatique","ok":false,"why":"Faux : la distinction se fait sur la durée, pas sur les symptômes ; toute suspicion de TV impose l'alerte (15) (p. 399)."}],"explanation":"La TVNS dure entre 3 battements et 30 secondes ; au-delà de 30 secondes, on parle de TV soutenue.","src":"p. 399","deep":"**Pourquoi** : TV = FC > 100 avec QRS > 120 ms sur au moins 3 battements consécutifs ; entre 3 battements et 30 s = non soutenue ; > 30 s = soutenue (p. 399).\n**À relier** : décris aussi monomorphe/polymorphe (conséquences étiologiques et hémodynamiques).\n**Piège** : le seuil dépend de la durée (30 s), pas de la présence de symptômes."},{"id":"231-qru-202","type":"QRU","rank":"A","objective":"231-obj-19","tags":["urgence","ECG"],"difficulty":1,"stem":"Quelle est la conduite à tenir immédiate devant une fibrillation ventriculaire ?","options":[{"t":"Cardioversion électrique différée après bilan biologique complet","ok":false,"why":"Faux : en FV, choc électrique immédiat avant tout autre geste ; aucun bilan ne doit le retarder (p. 402)."},{"t":"Manœuvre vagale en première intention","ok":false,"why":"Faux : les manœuvres vagales concernent les tachycardies bien tolérées ; la FV est un arrêt cardiaque (p. 402, 405)."},{"t":"Massage cardiaque en attendant un choc électrique en urgence absolue","ok":true,"why":"FV = arrêt cardiaque : le choc réinitialise l'activité électrique ; le massage maintient un débit en attendant (p. 402, 413)."},{"t":"Administration d'adénosine intraveineuse","ok":false,"why":"Faux : l'adénosine bloque le NAV (tachycardies dépendantes du NAV) ; elle n'a aucune place dans la FV (p. 390, 402)."},{"t":"Surveillance simple sans geste immédiat","ok":false,"why":"Faux : sans choc, la FV évolue vers l'asystolie ; urgence absolue (p. 398, 402)."}],"explanation":"La fibrillation ventriculaire est une urgence absolue : choc électrique immédiat, massage cardiaque en attendant le choc.","src":"p. 402","deep":"**Pourquoi** : la FV est un arrêt cardiaque : urgence absolue, choc électrique immédiat avant tout autre geste, avec massage cardiaque en attendant le choc (p. 402).\n**À relier** : perte de connaissance en quelques secondes, pouls carotidien aboli.\n**Piège** : manœuvres vagales et adénosine ne concernent que les tachycardies dépendantes du NAV."},{"id":"231-qru-203","type":"QRU","rank":"B","objective":"231-obj-20","tags":["ECG","pièges"],"difficulty":2,"stem":"Quel élément permet le mieux de différencier une torsade de pointes déjà installée d'une fibrillation ventriculaire ?","options":[{"t":"La durée du QRS mesurée pendant l'arythmie","ok":false,"why":"Les deux donnent des QRS larges polymorphes et, une fois installées, un aspect indiscernable : la largeur du QRS ne tranche pas (p. 403)."},{"t":"La présence d'un pouls carotidien perçu","ok":false,"why":"Faux : les deux arythmies, une fois installées, entraînent perte de connaissance et pouls aboli (p. 403)."},{"t":"La présence d'un QT long avant le trouble du rythme, associée au contexte clinique","ok":true,"why":"Une fois installée, la torsade ressemble à une FV ; seuls le QT long préalable et le contexte (ions, médicaments, bradycardie) tranchent (p. 403-404)."},{"t":"La fréquence cardiaque pendant l'arythmie","ok":false,"why":"Faux : la fréquence ne distingue pas deux tachycardies polymorphes rapides (p. 403)."},{"t":"La régularité du rythme ventriculaire","ok":false,"why":"Faux : une fois installée, la torsade a l'aspect irrégulier polymorphe d'une FV (p. 403)."}],"explanation":"La torsade de pointes installée peut être indiscernable d'une FV ; le QT long préexistant et le contexte (FV plutôt sur ischémie/cardiopathie évoluée, torsade dans les situations d'allongement du QT) orientent le diagnostic.","src":"p. 403-404","deep":"**Pourquoi** : une torsade installée est parfois indiscernable d'une FV à l'ECG ; seuls un QT long avant le trouble du rythme et le contexte permettent de trancher (FV : ischémie, cardiopathie évoluée ; torsade : hypo K/Ca/Mg, bradycardie extrême, médicaments, QT long congénital) (p. 403-404).\n**À relier** : traitement de la torsade = ions, arrêt des médicaments, accélérer la FC.\n**Piège** : pouls, fréquence, régularité ne différencient pas les deux."},{"id":"231-qru-204","type":"QRU","rank":"A","objective":"231-obj-14","tags":["ECG"],"difficulty":1,"stem":"Quelle est la fréquence atriale habituelle d'un flutter atrial typique sur cœur sain ?","options":[{"t":"100/min","ok":false,"why":"100/min est la cadence VENTRICULAIRE d'un flutter conduit en 3/1, pas la fréquence atriale (p. 394)."},{"t":"60/min","ok":false,"why":"60/min est une fréquence sinusale normale de repos ; le flutter tourne ≈ 300/min dans l'oreillette (p. 376, 393)."},{"t":"150/min","ok":false,"why":"150/min correspond à la cadence VENTRICULAIRE usuelle (conduction 2/1), pas à la fréquence atriale."},{"t":"500/min","ok":false,"why":"Trop rapide : le flutter tourne le plus souvent à 300/min (240-340), les atypiques de 120 à 320 (p. 393-394)."},{"t":"300/min (entre 240 et 340/min)","ok":true,"why":"Boucle autour de l'isthme cavotricuspide sur oreillette normale : ≈ 300/min ; plus lente si l'oreillette est dilatée (p. 393-394)."}],"explanation":"L'activité atriale du flutter est rapide, le plus souvent autour de 300/min (240 à 340/min).","src":"p. 393","deep":"**Pourquoi** : dans le flutter typique sur cœur sain, la boucle atriale tourne à ≈ 300/min (240-340) ; les ventricules reçoivent souvent 1 influx sur 2 : 150/min (p. 393).\n**Astuce** : 300 / 2 = 150 (3/1 = 100, 4/1 = 75).\n**Piège** : ne confonds pas la fréquence atriale (300) avec la cadence ventriculaire (150)."},{"id":"231-qru-205","type":"QRU","rank":"A","objective":"231-obj-15","tags":["ECG"],"difficulty":2,"stem":"Comment nomme-t-on la tachycardie jonctionnelle par réentrée empruntant une voie accessoire de type faisceau de Kent ?","options":[{"t":"Une tachycardie par rythme réciproque","ok":true,"why":"Rythme réciproque = réentrée par voie accessoire (faisceau de Kent), 2e forme de tachycardie jonctionnelle (p. 396)."},{"t":"Une extrasystole jonctionnelle répétitive","ok":false,"why":"Faux : une extrasystole jonctionnelle est un battement prématuré isolé (QRS fin ± P'), rare ; pas une réentrée soutenue (p. 397)."},{"t":"Une tachycardie par réentrée intranodale","ok":false,"why":"Faux : la réentrée intranodale reste dans le NAV, sans voie accessoire (p. 395)."},{"t":"Une fibrillation atriale préexcitée (« super-Wolff »)","ok":false,"why":"Le super-Wolff est une FA conduite par la voie accessoire (tachycardie irrégulière à QRS larges de largeur variable), et non une réentrée jonctionnelle."},{"t":"Un flutter atypique","ok":false,"why":"Faux : le flutter atypique est une réentrée atriale hors isthme cavotricuspide, sans voie accessoire (p. 394)."}],"explanation":"La réentrée par voie accessoire (faisceau de Kent) définit les tachycardies par rythme réciproque, à distinguer de la réentrée intranodale.","src":"p. 396, 411","deep":"**Pourquoi** : deux formes de tachycardie jonctionnelle : réentrée intranodale (boucle dans le NAV) ou rythme réciproque (boucle qui emprunte une voie accessoire, faisceau de Kent) (p. 396, 411).\n**À relier** : super-Wolff = FA conduite par une voie accessoire très perméable (irrégulière, QRS larges variables) ; adénosine contre-indiquée.\n**Piège** : rythme réciproque = régulier ; super-Wolff = irrégulier."},{"id":"231-qroc-201","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG"],"difficulty":1,"question":"Quel terme désigne les ondes d'activité atriale caractéristiques du flutter atrial à l'ECG ?","answer":"Ondes F","accept":["onde F","ondes F","les ondes F"],"keywords":["onde","f"],"explanation":"Ondes F du flutter : activité atriale monomorphe ≈ 300/min, sans retour à la ligne isoélectrique (en dents de scie) dans au moins une dérivation ; parfois démasquées par une manœuvre vagale (p. 393).","src":"p. 393","deep":"**Pourquoi** : le flutter est une boucle de réentrée : activité atriale monomorphe à ≈ 300/min, ondes F enchaînées sans retour à la ligne isoélectrique (dans au moins une dérivation), en toit d'usine ou dents de scie (p. 393).\n**À relier** : parfois démasquées seulement après manœuvre vagale.\n**Piège** : FA = activité anarchique (mailles/trémulation) ; flutter = ondes F organisées."},{"id":"231-qroc-202","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG"],"difficulty":2,"question":"Quelle structure anatomique est empruntée par la boucle de réentrée du flutter atrial typique (commun) ?","answer":"L'isthme cavotricuspide","accept":["isthme cavo-tricuspide","isthme cavotricuspidien","isthme cavo tricuspide","isthme"],"keywords":["isthme","cavotricuspide"],"explanation":"Le flutter typique tourne dans l'OD en empruntant l'isthme cavotricuspide (entre tricuspide et veine cave inférieure) ; sans isthme = flutter atypique (p. 394).","src":"p. 394","deep":"**Pourquoi** : le flutter typique (commun) antihoraire tourne dans l'OD autour de l'isthme cavotricuspide (entre valve tricuspide et veine cave inférieure) : F négatives en D2-D3-aVF, positives en V1, négatives en V6 (p. 394).\n**À relier** : flutter atypique = circuit sans l'isthme (droit, gauche ou biatrial, 120-320/min).\n**Piège** : le flutter horaire a toutes les polarités inversées."},{"id":"231-qroc-203","type":"QROC","rank":"A","objective":"231-obj-15","tags":["ECG"],"difficulty":1,"question":"Quel est le nom de la voie accessoire responsable des tachycardies jonctionnelles par rythme réciproque ?","answer":"Le faisceau de Kent","accept":["voie accessoire de Kent","Kent","faisceau de Kent","le faisceau de Kent"],"keywords":["kent"],"explanation":"Le faisceau de Kent est une fibre musculaire atrio-ventriculaire ectopique : réentrée (rythme réciproque) ou préexcitation (PR court, onde delta) (p. 396, 410).","src":"p. 396","deep":"**Pourquoi** : le faisceau de Kent est une fibre musculaire ectopique atrio-ventriculaire : seconde voie en plus du NAV, qui permet la réentrée (rythme réciproque) ou la préexcitation (PR court, onde delta) (p. 396).\n**À relier** : WPW = voie antérograde avec tachycardie jonctionnelle ; super-Wolff en cas de FA.\n**Piège** : contrairement au NAV, la voie accessoire n'a pas de propriété décrémentielle."},{"id":"231-qroc-204","type":"QROC","rank":"A","objective":"231-obj-15","tags":["ECG"],"difficulty":1,"question":"Quel nom est couramment donné en France aux tachycardies jonctionnelles ?","answer":"Maladie de Bouveret","accept":["Bouveret","maladie de Bouveret","syndrome de Bouveret"],"keywords":["bouveret"],"explanation":"Bouveret = tachycardie jonctionnelle, fréquente, très régulière, ≈ 200/min ; deux mécanismes : réentrée intranodale ou rythme réciproque (p. 395-396).","src":"p. 395","deep":"**Pourquoi** : les tachycardies jonctionnelles sont fréquentes, très régulières (≈ 200/min, 130-260) et couramment appelées maladie de Bouveret en France (p. 395).\n**À relier** : deux mécanismes : réentrée intranodale ou rythme réciproque par voie accessoire ; réduction par manœuvres vagales/adénosine.\n**Piège** : un même nom pour deux mécanismes différents."},{"id":"231-qroc-205","type":"QROC","rank":"B","objective":"231-obj-16","tags":["traitement"],"difficulty":2,"question":"Citez les deux moyens (l'un non médicamenteux, l'autre médicamenteux) qui permettent de réduire une tachycardie jonctionnelle.","answer":"Manœuvres vagales et adénosine intraveineuse","accept":["manœuvres vagales et adénosine","manœuvres vagales et adénosine IV","manœuvres vagales, adénosine","manœuvres vagales, adénosine IV","vagale et adénosine IV","Valsalva et adénosine","adénosine IV et manœuvres vagales","adénosine et manœuvres vagales","manœuvre vagale et adénosine"],"keywords":["vagales","adénosine"],"explanation":"Le NAV fait partie de la boucle de réentrée : le bloquer transitoirement (vagal, puis adénosine si échec) la coupe et rétablit le rythme sinusal (p. 397, 405).","src":"p. 397","deep":"**Pourquoi** : la tachycardie jonctionnelle dépend du NAV : le bloquer transitoirement (manœuvres vagales, sinon adénosine IV) coupe la réentrée et rétablit le rythme sinusal (p. 397).\n**À relier** : bonne tolérance = vagales d'abord, adénosine si échec.\n**Piège** : adénosine contre-indiquée en cas d'asthme ou d'hypotension."},{"id":"231-qroc-206","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG"],"difficulty":1,"question":"Une extrasystole est une activation de quel type (adjectif) d'une cavité cardiaque par rapport à l'activation attendue ?","answer":"Prématurée (trop précoce)","accept":["activation prématurée","prématurée","précoce","trop précoce","prématuré"],"keywords":["prematur","precoce"],"explanation":"Extrasystole = activation trop précoce par rapport à l'activation attendue : atriale (P' précoce, QRS fin), jonctionnelle (rare) ou ventriculaire (QRS large) (p. 397).","src":"p. 397","deep":"**Pourquoi** : une extrasystole est une activation trop précoce d'une cavité : atriale (P' précoce, QRS fin), jonctionnelle (QRS fin ± P' rétrograde), ventriculaire (QRS large) (p. 397).\n**Astuce** : extra-systole = systole en trop, arrivée trop tôt.\n**Piège** : prématurée ne veut pas dire tardive ; l'ESV est à QRS large."},{"id":"231-qroc-207","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":1,"question":"Au-delà de quelle durée de QRS (pour au moins 3 battements consécutifs) suspecte-t-on une tachycardie ventriculaire ?","answer":"120 ms","accept":["> 120 ms","120 millisecondes","plus de 120 ms","supérieur à 120 ms","120"],"keywords":["120"],"explanation":"TV suspectée si FC > 100/min et QRS > 120 ms sur au moins 3 battements consécutifs : donner l'alerte (15) et se préparer à réanimer (p. 399).","src":"p. 399","deep":"**Pourquoi** : suspicion de TV = FC > 100/min et QRS > 120 ms sur au moins 3 battements consécutifs (p. 399).\n**À relier** : donner l'alerte (faire le 15), se préparer à une réanimation ; 3 battements à 30 s = TV non soutenue.\n**Piège** : le seuil de QRS est 120 ms (comme pour les blocs de branche complets), pas 110."},{"id":"231-qroc-208","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":1,"question":"Quelle durée sépare une tachycardie ventriculaire non soutenue d'une tachycardie ventriculaire soutenue ?","answer":"30 secondes","accept":["30 s","30"],"keywords":["30","secondes"],"explanation":"TV non soutenue : de 3 battements à 30 s ; soutenue au-delà de 30 s ; décrire aussi monomorphe ou polymorphe (p. 399-400).","src":"p. 399","deep":"**Pourquoi** : TV non soutenue = de 3 battements à 30 secondes ; TV soutenue = > 30 secondes (p. 399).\n**À relier** : décris monomorphe ou polymorphe ; TV = état instable, prémonitoire d'arrêt cardiaque.\n**Piège** : il faut au moins 3 battements consécutifs pour parler de TV."},{"id":"231-qroc-209","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":2,"question":"Quel signe électrocardiographique, correspondant à davantage de QRS que d'ondes P, affirme avec certitude le diagnostic de tachycardie ventriculaire ?","answer":"La dissociation ventriculo-atriale","accept":["dissociation AV","dissociation ventriculoatriale","dissociation VA","dissociation ventriculo atriale","dissociation auriculo-ventriculaire"],"keywords":["dissociation"],"explanation":"Plus de QRS que de P : la tachycardie vient forcément du ventricule ; à ne pas confondre avec la dissociation AV du BAV complet (plus de P que de QRS) (p. 400).","src":"p. 400","deep":"**Pourquoi** : s'il y a plus de QRS que d'ondes P, la tachycardie vient forcément du ventricule : certitude de TV (p. 400).\n**À relier** : capture et fusion ne peuvent exister que s'il y a cette dissociation.\n**Piège** : la dissociation AV du BAV3 (plus de P que de QRS) est un autre phénomène."},{"id":"231-qroc-210","type":"QROC","rank":"A","objective":"231-obj-19","tags":["urgence"],"difficulty":1,"question":"Quel geste doit être réalisé en urgence absolue devant une fibrillation ventriculaire, avant tout autre geste ?","answer":"Une cardioversion électrique (choc électrique) immédiate","accept":["choc électrique","choc électrique externe","défibrillation","cardioversion","choc électrique immédiat"],"keywords":["choc","electrique"],"explanation":"FV = arrêt cardiaque (débit nul) : choc électrique immédiat avant tout autre geste, massage cardiaque en attendant (p. 402-403).","src":"p. 402","deep":"**Pourquoi** : la FV est un arrêt cardiaque (débit nul, perte de connaissance en quelques secondes) : la réinitialisation de l'activité électrique se fait par le choc (p. 402).\n**À relier** : massage cardiaque en attendant le choc.\n**Piège** : aucun médicament ni manœuvre vagale ici."},{"id":"231-qroc-211","type":"QROC","rank":"B","objective":"231-obj-20","tags":["ECG"],"difficulty":2,"question":"Quel élément ECG, présent avant le trouble du rythme, aide à distinguer une torsade de pointes d'une fibrillation ventriculaire ?","answer":"Un intervalle QT long","accept":["QT long","QT allongé","allongement du QT","intervalle QT allongé"],"keywords":["qt","long"],"explanation":"Torsade installée ≈ FV à l'ECG : le QT long AVANT le trouble du rythme et le contexte (ions, médicaments, bradycardie) orientent (p. 403-404).","src":"p. 403-404","deep":"**Pourquoi** : une torsade installée est indiscernable d'une FV ; le QT long préalable et le contexte (médicaments, hypoK/Ca/Mg, bradycardie extrême) font le diagnostic (p. 403-404).\n**À relier** : FV = surtout ischémie ou cardiopathie évoluée.\n**Piège** : on parle du QT AVANT le trouble du rythme."},{"id":"231-qroc-212","type":"QROC","rank":"A","objective":"231-obj-12","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quel est le seul diagnostic à évoquer devant une tachycardie complètement irrégulière à QRS fins ?","answer":"La fibrillation atriale","accept":["FA","fibrillation auriculaire"],"keywords":["fibrillation","atriale"],"explanation":"Tachycardie complètement irrégulière à QRS fins = FA (diagnostic différentiel : extrasystoles atriales) ; irrégulière à QRS larges : FA + bloc de branche ou super-Wolff (p. 393, 405, 411).","src":"p. 405","deep":"**Pourquoi** : une tachycardie complètement irrégulière à QRS fins = FA ; ses RR sont irrégulièrement irréguliers (p. 405).\n**À relier** : diagnostic différentiel = extrasystolie atriale.\n**Piège** : irrégulière à QRS larges = FA + bloc de branche, ou FA préexcitée (super-Wolff)."},{"id":"231-open-21","type":"OPEN","rank":"A","objective":"231-obj-14","tags":["ECG","diagnostic"],"difficulty":2,"prompt":"Un patient de 65 ans consulte pour des palpitations régulières rapides à 150/min. Décrivez la démarche électrocardiographique permettant de distinguer un flutter atrial d'une tachycardie jonctionnelle, en précisant l'apport des manœuvres vagales.","rubric":[{"point":"Décrire le mécanisme du flutter : réentrée organisée en circuit, activité atriale monomorphe en dents de scie","weight":2},{"point":"Décrire le(s) mécanisme(s) de la tachycardie jonctionnelle : réentrée intranodale ou par voie accessoire, activité atriale souvent peu visible","weight":2},{"point":"Préciser l'effet attendu des manœuvres vagales/adénosine dans le flutter : ralentissement transitoire de la conduction démasquant les ondes F, sans arrêt de l'arythmie","weight":2},{"point":"Préciser l'effet attendu dans la tachycardie jonctionnelle : arrêt de la tachycardie car la réentrée dépend du nœud atrioventriculaire","weight":2},{"point":"Conclure sur l'intérêt diagnostique et parfois thérapeutique de ces manœuvres en cas de doute","weight":1}],"model":"**Flutter atrial** : réentrée organisée en circuit (le plus souvent autour de l'isthme cavotricuspide), donnant une activité atriale monomorphe rapide (ondes F, environ 300/min) sans retour à la ligne isoélectrique.\n\n**Tachycardie jonctionnelle** : réentrée intranodale ou par voie accessoire (rythme réciproque), avec une activité atriale souvent invisible ou devinée dans le segment ST.\n\n**Manœuvres vagales/adénosine** : en bloquant transitoirement le nœud atrioventriculaire, elles démasquent l'activité atriale sous-jacente du flutter (les ondes F apparaissent alors que la cadence ventriculaire ralentit) sans arrêter l'arythmie, alors qu'elles interrompent la tachycardie jonctionnelle en coupant la boucle de réentrée dépendante du nœud atrioventriculaire. Elles sont donc utiles au diagnostic dans les deux cas, et parfois curatives dans la tachycardie jonctionnelle.","src":"p. 393-397, 405"},{"id":"231-open-22","type":"OPEN","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic","urgence"],"difficulty":3,"prompt":"Détaillez les arguments électrocardiographiques permettant d'affirmer le diagnostic de tachycardie ventriculaire devant une tachycardie régulière à QRS larges.","rubric":[{"point":"Rappeler la règle de base : toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire","weight":1},{"point":"Citer les critères de suspicion simples : fréquence > 100/min, QRS > 120 ms pour au moins 3 battements consécutifs","weight":2},{"point":"Citer les arguments de certitude : dissociation ventriculo-atriale, complexes de capture ou de fusion","weight":3},{"point":"Citer les arguments en faveur : cardiopathie sous-jacente, concordance positive/négative de V1 à V6, déviation axiale extrême (QRS positif en aVR)","weight":3},{"point":"Mentionner la nécessité de décrire le caractère monomorphe ou polymorphe, qui conditionne l'étiologie et la tolérance hémodynamique","weight":1}],"model":"**Règle de base** : toute tachycardie régulière à QRS larges est une tachycardie ventriculaire jusqu'à preuve du contraire.\n\n**Suspicion** : fréquence > 100/min et QRS > 120 ms sur au moins 3 battements consécutifs.\n\n**Arguments de certitude** : dissociation ventriculo-atriale (plus de QRS que d'ondes P, à ne pas confondre avec la dissociation atrioventriculaire du bloc complet) ; complexes de capture (QRS fin précédé d'une onde P, correspondant à une capture ventriculaire par l'influx sinusal) ou de fusion (QRS de morphologie intermédiaire).\n\n**Arguments en faveur** : cardiopathie sous-jacente ; concordance positive ou négative des précordiales (V1 à V6) ; déviation axiale extrême avec QRS positif en aVR ; aspect de QRS large différent d'un bloc de branche habituel.\n\n**Description complémentaire** : préciser le caractère monomorphe ou polymorphe, qui oriente l'étiologie et conditionne les conséquences hémodynamiques.","src":"p. 398-402"},{"id":"231-open-23","type":"OPEN","rank":"B","objective":"231-obj-19","tags":["ECG","urgence"],"difficulty":2,"prompt":"Comparez, sur le plan électrocardiographique et sur le plan de la prise en charge, la fibrillation ventriculaire et la torsade de pointes.","rubric":[{"point":"Décrire l'aspect ECG de la FV : tachycardie irrégulière à QRS larges polymorphes","weight":2},{"point":"Décrire l'aspect ECG de la torsade de pointes : forme particulière de TV polymorphe, pouvant s'arrêter spontanément ou dégénérer en FV","weight":2},{"point":"Préciser l'élément différentiel une fois l'arythmie installée : présence d'un QT long préalable et le contexte","weight":2},{"point":"Décrire la prise en charge immédiate de la FV : cardioversion électrique immédiate avant tout autre geste, massage cardiaque en attendant le choc","weight":2},{"point":"Préciser la prise en charge spécifique de la torsade : correction des troubles ioniques, arrêt des médicaments allongeant le QT, accélération de la fréquence cardiaque","weight":2}],"model":"**Fibrillation ventriculaire** : tachycardie irrégulière à QRS larges et polymorphes, urgence absolue entraînant un arrêt cardiaque (perte de connaissance, pouls carotidien aboli) en quelques secondes, nécessitant une cardioversion électrique immédiate, précédée d'un massage cardiaque en attendant le choc.\n\n**Torsade de pointes** : forme particulière de TV polymorphe, pouvant s'arrêter spontanément ou dégénérer en FV. Une fois installée, elle est indiscernable de la FV à l'ECG ; seuls la présence d'un QT long avant le trouble du rythme et le contexte (hypokaliémie, hypocalcémie, hypomagnésémie, bradycardie extrême, médicaments allongeant le QT, QT long congénital) permettent de l'évoquer plutôt qu'une FV.\n\n**Prise en charge spécifique de la torsade** : correction des troubles ioniques, arrêt des médicaments allongeant le QT, accélération de la fréquence cardiaque.","src":"p. 402-404"},{"id":"231-open-24","type":"OPEN","rank":"A","objective":"231-obj-17","tags":["ECG","diagnostic"],"difficulty":2,"prompt":"Expliquez comment différencier, sur l'ECG, une extrasystole ventriculaire isolée d'un début de tachycardie ventriculaire, et précisez les formes rythmées ou répétitives des extrasystoles.","rubric":[{"point":"Rappeler la définition commune : activation prématurée par rapport au rythme attendu","weight":1},{"point":"Décrire l'aspect de l'extrasystole ventriculaire : QRS large, ± onde P' rétrograde, isolée","weight":2},{"point":"Préciser le critère de nombre qui distingue l'extrasystolie répétitive d'une TV naissante : au moins 3 battements consécutifs à QRS large > 120 ms pour parler de TV","weight":2},{"point":"Citer les formes répétitives : doublet, triplet, salve","weight":1},{"point":"Citer les formes rythmées : bigéminisme (1 battement sur 2), trigéminisme (1 battement sur 3)","weight":1}],"model":"**Extrasystole ventriculaire** : activation prématurée naissant sous la bifurcation hissienne, donnant un QRS large, parfois suivi d'une onde P' rétrograde, isolée au sein d'un rythme de base.\n\n**Critère de distinction avec la TV** : dès que 3 battements consécutifs ou plus à QRS large (> 120 ms) et à fréquence > 100/min se succèdent, on ne parle plus d'extrasystoles répétitives mais de tachycardie ventriculaire (non soutenue si ≤ 30 secondes, soutenue au-delà).\n\n**Formes répétitives** : doublet (deux extrasystoles consécutives), triplet, salve (plusieurs extrasystoles successives).\n\n**Formes rythmées** : bigéminisme (une extrasystole toutes les deux systoles), trigéminisme (une extrasystole toutes les trois systoles).","src":"p. 397-399"},{"id":"231-qcm-301","type":"QRM","rank":"A","objective":"231-obj-05","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant l'hypertrophie ventriculaire gauche (HVG) électrique :","options":[{"t":"Dans les formes sévères, on observe une onde T positive ample dans les dérivations latérales","ok":false,"why":"Faux : forme sévère = T négative + sous-ST latéral (D1, aVL, V5, V6) avec disparition de la Q septale (p. 406)."},{"t":"L'HVG électrique peut mimer une séquelle d'infarctus (pseudonécrose) en V1-V2","ok":true,"why":"Une HVG importante peut donner un QS en V1-V2 (pseudonécrose) et/ou un pseudo sus-ST (fig. 15.53, p. 406-407)."},{"t":"La déviation axiale associée est habituellement extrême, vers la droite","ok":false,"why":"Faux : déviation modeste vers la GAUCHE ; un axe droit oriente vers le VD (HVD) (p. 406-407)."},{"t":"L'indice de Sokolow additionne l'amplitude de l'onde R en V1 ou V2 et celle de l'onde S en V5 ou V6","ok":false,"why":"Faux : l'indice de Sokolow additionne l'amplitude de l'onde S en V1 ou V2 et celle de l'onde R en V5 ou V6."},{"t":"Une valeur de Sokolow inférieure à 45 mm est considérée comme normale","ok":false,"why":"Faux : Sokolow normal < 35 mm (S V1/V2 + R V5/V6) (p. 406)."}],"explanation":"L'indice de Sokolow (S en V1 ou V2 + R en V5 ou V6) est normal en dessous de 35 mm ; l'HVG électrique s'accompagne d'une déviation axiale modeste vers la gauche et, dans les formes sévères, d'ondes T négatives avec sous-décalage du ST en latéral ; un aspect QS en V1-V2 peut mimer une séquelle d'infarctus (pseudonécrose).","src":"p. 406-407","deep":"**Pourquoi** : Sokolow = S en V1 ou V2 + R en V5 ou V6, normal < 35 mm. HVG sévère : T négative + ST sous-décalé en latéral (D1, aVL, V5, V6), disparition de la Q septale ; axe modérément dévié à gauche, QRS peu élargi (p. 406-407).\n**À relier** : un QS en V1-V2 et un pseudo sus-décalage du ST miment une séquelle d'infarctus.\n**Piège** : le seuil est 35 mm (pas 45) et c'est S (V1/V2) + R (V5/V6), pas l'inverse."},{"id":"231-qcm-302","type":"QRM","rank":"A","objective":"231-obj-05","tags":["étiologie","ECG"],"difficulty":1,"stem":"Concernant l'étiologie et certaines particularités de l'HVG à l'ECG :","options":[{"t":"Un sus-décalage trompeur du segment ST peut être observé en V1-V2 associé à un aspect de pseudonécrose","ok":true,"why":"Une HVG électrique importante peut donner un QS en V1-V2 et/ou un pseudo sus-ST, mimant une séquelle d'infarctus (p. 406-407)."},{"t":"Le terme historique « surcharge diastolique » désigne la forme sévère","ok":false,"why":"Inversé : forme sévère = « surcharge systolique », modérée = « diastolique », termes sans valeur de mécanisme (p. 406)."},{"t":"L'hypertension artérielle est l'étiologie la plus fréquente","ok":true,"why":"L'HTA est la 1re cause d'HVG, puis le rétrécissement aortique ; et l'ECG est par ailleurs « obligatoire » dans le bilan de l'HTA (p. 407, 414)."},{"t":"L'embolie pulmonaire est citée comme deuxième étiologie","ok":false,"why":"Faux : 2e cause d'HVG = rétrécissement aortique ; l'EP surcharge le VD (S1Q3T3) (p. 407)."},{"t":"La durée du QRS dépasse habituellement très largement 160 ms","ok":false,"why":"Faux : QRS un peu élargi (masse, fibrose) mais le plus souvent < 120 ms (p. 406)."}],"explanation":"L'HTA puis le rétrécissement aortique sont les principales étiologies de l'HVG ; le QRS reste le plus souvent < 120 ms malgré un possible élargissement modéré, et des pièges de pseudonécrose/pseudo-sus-décalage existent en V1-V2.","src":"p. 406-407","deep":"**Pourquoi** : l'HVG est liée à une augmentation de la masse myocardique du VG ; étiologie la plus fréquente = HTA, puis rétrécissement aortique (p. 406-407).\n**À relier** : forme sévère = « surcharge systolique », forme modérée = « diastolique » (termes historiques sans valeur de mécanisme) ; QRS souvent < 120 ms.\n**Piège** : l'embolie pulmonaire réalise une surcharge aiguë du VD (S1Q3T3), pas du VG."},{"id":"231-qcm-303","type":"QRM","rank":"B","objective":"231-obj-04","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant l'hypertrophie ventriculaire droite (HVD) à l'ECG :","options":[{"t":"Elle est fréquemment associée à une hypertrophie atriale droite et à un microvoltage chez le patient BPCO","ok":true,"why":"Chez le BPCO, l'HVD s'associe souvent à une HAD et à un microvoltage ; c'est là que l'ECG garde un intérêt clinique (p. 407)."},{"t":"On observe en V1 une onde R ample supérieure à 6 mm","ok":true,"why":"En V1, onde R ample > 6 mm, et en V5-V6, onde S ample > 7 mm ; le 1er signe reste l'axe droit (p. 407)."},{"t":"Un bloc de branche gauche est fréquemment associé à l'HVD","ok":false,"why":"Faux : c'est un bloc de branche DROIT qui accompagne souvent l'HVD (p. 407)."},{"t":"Le signe le plus précoce est une déviation axiale droite supérieure à 90-110°","ok":true,"why":"Signe le plus précoce : axe > 110° (90° en pratique) ; même aspect possible dans l'HBPG ou chez le longiligne (p. 407)."},{"t":"L'onde S en V5-V6 est habituellement de faible amplitude, inférieure à 2 mm","ok":false,"why":"Faux : S ample > 7 mm en V5-V6 (avec R > 6 mm en V1) (p. 407)."}],"explanation":"L'HVD associe déviation axiale droite, onde R ample en V1, onde S ample en V5-V6, et souvent bloc de branche droit et hypertrophie atriale droite (notamment chez le patient BPCO).","src":"p. 407","deep":"**Pourquoi** : signe le plus précoce de l'HVD = déviation axiale droite du QRS > 110° (90° en pratique) ; puis R ample > 6 mm en V1, S ample > 7 mm en V5-V6. Chez le BPCO : HAD + microvoltage (p. 407).\n**À relier** : BBD souvent associé ; T négative asymétrique en V1 (V2-V3) dans les formes sévères, à ne pas confondre avec une ischémie.\n**Piège** : c'est le bloc de branche DROIT, pas gauche."},{"id":"231-qcm-304","type":"QRM","rank":"B","objective":"231-obj-04","tags":["ECG","étiologie"],"difficulty":2,"stem":"Une patiente présente une dyspnée aiguë ; l'ECG montre une onde S en D1, une onde Q en D3 et une onde T négative en D3. Concernant ce tableau :","options":[{"t":"Un bloc de branche gauche est souvent associé à cette surcharge droite","ok":false,"why":"Faux : l'HVD s'associe souvent à un BBD ; le tracé d'EP du Collège montre axe droit, S1Q3 et FA (p. 407-408)."},{"t":"Cet aspect élimine formellement une atteinte du ventricule droit","ok":false,"why":"Faux : S1Q3T3 traduit précisément une hypertrophie (surcharge) aiguë du VD, classique dans l'EP (p. 407)."},{"t":"L'onde T négative en V1 à V3 ne peut jamais être observée dans ce contexte","ok":false,"why":"Faux : dans les HVD sévères, T négative asymétrique en V1 (parfois V2-V3), à ne pas confondre avec une ischémie (p. 407)."},{"t":"Cet aspect peut traduire une hypertrophie aiguë du ventricule droit au cours d'une embolie pulmonaire","ok":true,"why":"Dans l'EP, la surcharge aiguë du VD peut donner S1Q3T3, avec axe droit (fig. 15.54, p. 407-408)."},{"t":"Il s'agit d'un aspect S1Q3T3","ok":true,"why":"S en D1 + Q en D3 + T négative en D3 = S1Q3T3, traduisant une surcharge aiguë du VD (p. 407)."}],"explanation":"L'aspect S1Q3T3 (S en D1, Q et T négative en D3) est un signe électrique de surcharge aiguë du ventricule droit, classiquement décrit au cours de l'embolie pulmonaire, pouvant s'associer à une fibrillation atriale.","src":"p. 407-408","deep":"**Pourquoi** : S en D1 + Q en D3 + T négative en D3 = S1Q3T3 : traduit une hypertrophie (surcharge) aiguë du VD, classique dans l'embolie pulmonaire (avec axe droit, FA possible) (p. 407-408).\n**À relier** : devant une dyspnée aiguë, ce tracé oriente vers l'EP.\n**Piège** : un axe droit/S1Q3 isolé peut aussi être un HBPG ou une variante chez le longiligne ; et il s'associe plutôt à un BBD qu'à un BBG."},{"id":"231-qcm-305","type":"QRM","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":1,"stem":"Concernant les anomalies ECG de l'hypokaliémie :","options":[{"t":"Onde T plate ou négative, diffuse, avec sous-décalage du ST","ok":true,"why":"HypoK : T plate ou négative diffuse avec ST sous-décalé ; l'inverse de l'hyperK (T ample et pointue) (p. 408)."},{"t":"Raccourcissement de l'intervalle QT","ok":false,"why":"Inversé : l'hypoK ALLONGE le QT (risque de torsades) (p. 404, 408)."},{"t":"Apparition possible d'une onde U, à ne pas intégrer dans la mesure du QT","ok":true,"why":"L'onde U suit la T ; l'inclure surestimerait le QT (p. 377, 408)."},{"t":"Allongement de l'intervalle QT","ok":true,"why":"L'hypokaliémie fait partie des causes d'allongement du QT exposant aux torsades de pointes (p. 404, 408)."},{"t":"Élargissement constant et majeur du QRS","ok":false,"why":"Faux : QRS normal dans l'hypoK ; c'est l'hyperK qui élargit le QRS (p. 408)."}],"explanation":"L'hypokaliémie associe onde T plate ou négative, sous-décalage du ST, allongement du QT et apparition possible d'une onde U, avec un QRS normal ; elle expose au risque de torsades de pointes.","src":"p. 408","deep":"**Pourquoi** : hypokaliémie = T plate ou négative diffuse avec ST sous-décalé, QRS normal, QT allongé avec onde U ; risque d'ESV, TV, torsades, FV (p. 408).\n**Astuce** : hypoK = tout s'aplatit (T), le QT s'allonge, une onde U apparaît.\n**Piège** : l'onde U ne s'inclut pas dans le QT ; le QRS reste normal (l'hyperK l'élargit)."},{"id":"231-qcm-306","type":"QRM","rank":"A","objective":"231-obj-21","tags":["ECG","biologie","urgence"],"difficulty":2,"stem":"Concernant les anomalies ECG de l'hyperkaliémie :","options":[{"t":"Onde T ample, pointue et symétrique","ok":true,"why":"Signe de l'hyperK : T ample, pointue, symétrique (« géante »), parfois avant l'élargissement des QRS (fig. 15.55, p. 408-409)."},{"t":"Allongement de l'intervalle PR","ok":true,"why":"HyperK : PR allongé ; elle peut aller jusqu'au BAV (p. 408)."},{"t":"L'onde U est le signe le plus précoce et le plus spécifique de l'hyperkaliémie","ok":false,"why":"L'onde U se décrit dans l'HYPOkaliémie ; l'hyperkaliémie donne une T ample, pointue et symétrique."},{"t":"Élargissement du QRS","ok":true,"why":"HyperK : QRS élargi (après les T géantes, fig. 15.55) ; risque de TV (p. 408-409)."},{"t":"Elle ne s'associe jamais à un bloc atrioventriculaire","ok":false,"why":"Faux : l'hyperK peut donner BAV, TV, dysfonction sinusale (échappement jonctionnel, fig. 15.55) (p. 408-409)."}],"explanation":"L'hyperkaliémie associe onde T ample et pointue, allongement du PR, élargissement du QRS, et peut se compliquer de BAV, de tachycardie ventriculaire ou de dysfonction sinusale.","src":"p. 408","deep":"**Pourquoi** : hyperkaliémie = T ample, pointue et symétrique, PR allongé, QRS élargi ; complications : BAV, TV, dysfonction sinusale (p. 408).\n**Astuce** : hyperK = tout s'élargit (PR, QRS) et la T devient géante ; hypoK = T plate + U + QT long.\n**Piège** : l'onde U est un signe d'HYPOkaliémie."},{"id":"231-qcm-307","type":"QRM","rank":"B","objective":"231-obj-23","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant les anomalies ECG de la péricardite aiguë en phase initiale :","options":[{"t":"Le sus-décalage de ST est convexe vers le haut et limité à un territoire coronaire","ok":false,"why":"Faux : péricardite = sus-ST concave vers le haut, diffus, concordant, sans miroir ; systématisé à un territoire = SCA (p. 409, 411)."},{"t":"L'évolution se fait toujours directement vers un ST isoélectrique, sans phase d'onde T négative","ok":false,"why":"Faux : 4 phases, dont T plates (2) puis T négatives persistantes (3) avant la normalisation (p. 409)."},{"t":"Le microvoltage est d'autant plus marqué que la péricardite est sèche, sans épanchement","ok":false,"why":"Faux : il est d'autant plus important que la péricardite est liquidienne (p. 409)."},{"t":"On observe un sous-décalage du segment PQ (PR)","ok":true,"why":"Le sous-décalage de PQ (PR) fait partie de la phase 1, avec le sus-ST diffus concave sans miroir et le microvoltage ; sur la fig. 15.56 il est bien visible en V5, V6 et en inférieur (p. 409)."},{"t":"Il existe habituellement une image en miroir franche, comme dans le SCA avec sus-décalage de ST","ok":false,"why":"Faux : pas de miroir dans la péricardite ; mais l'absence de miroir n'élimine pas un SCA ST+ (p. 409)."}],"explanation":"La péricardite aiguë évolue en 4 phases : microvoltage et sus-décalage de ST diffus concave sans miroir avec sous-décalage de PQ, puis onde T plate, puis onde T négative persistante, puis normalisation.","src":"p. 409","deep":"**Pourquoi** : péricardite, phase 1 (brève) : microvoltage (d'autant plus que péricardite liquidienne), sus-ST concave vers le haut, diffus, concordant, SANS miroir, avec sous-décalage de PQ (PR) (p. 409).\n**À relier** : 4 phases : (2) T plates, ST iso ; (3) T négatives persistantes ; (4) retour à la normale.\n**Piège** : l'absence de miroir peut exister dans un SCA ST+ : ne conclus pas à tort à une péricardite."},{"id":"231-qcm-308","type":"QRM","rank":"B","objective":"231-obj-25","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant la préexcitation ventriculaire par voie accessoire (faisceau de Kent) :","options":[{"t":"Des anomalies de repolarisation sont fréquemment associées, dans le territoire de la voie accessoire","ok":true,"why":"La zone préexcitée s'est dépolarisée anormalement, donc se repolarise anormalement (fig. 15.58, p. 410)."},{"t":"Le blocage du nœud atrioventriculaire par manœuvre vagale ou adénosine est recommandé pour démasquer la voie accessoire, y compris en cas de fibrillation atriale","ok":false,"why":"Faux : bloquer le NAV force l'influx par la voie accessoire (utile si préexcitation minime) mais pas en FA (super-Wolff) (p. 410-411)."},{"t":"Un syndrome de Wolff-Parkinson-White désigne une voie accessoire antérograde occasionnant des palpitations par tachycardie jonctionnelle","ok":true,"why":"Préexcitation seule ≠ WPW : on parle de syndrome de WPW quand la voie accessoire donne des palpitations par tachycardie jonctionnelle (p. 411)."},{"t":"Elle se traduit par un élargissement du QRS avec empâtement du pied de QRS, appelé onde delta","ok":true,"why":"Onde delta = partie du ventricule préexcitée par la voie accessoire, superposée à l'activation par le NAV (fig. 15.57, p. 410)."},{"t":"Elle se traduit par un PR court, inférieur à 120 ms","ok":true,"why":"La voie accessoire excite le ventricule avant la dépolarisation physiologique par le NAV (préexcitation), d'où un PR < 120 ms (p. 410)."}],"explanation":"La préexcitation associe PR court, onde delta et anomalies de repolarisation ; le blocage du nœud atrioventriculaire est utile pour la démasquer, sauf en cas de fibrillation atriale associée.","src":"p. 410-411","deep":"**Pourquoi** : voie accessoire rapide = préexcitation du ventricule avant le NAV : PR court (< 120 ms), QRS élargi par l'onde delta (partie préexcitée), anomalies de repolarisation associées. WPW = voie antérograde + tachycardie jonctionnelle (p. 410-411).\n**À relier** : bloquer le NAV (vagal, adénosine) force le passage par la voie accessoire et démasque une préexcitation minime.\n**Piège** : jamais en cas de FA (risque de super-Wolff)."},{"id":"231-qcm-309","type":"QRM","rank":"B","objective":"231-obj-25","tags":["ECG","urgence","pièges"],"difficulty":3,"stem":"Concernant le risque rythmique du syndrome de Wolff-Parkinson-White :","options":[{"t":"Le risque de mort subite est lié à une voie accessoire peu perméable (période réfractaire longue)","ok":false,"why":"Inversé : danger si la voie est très perméable (période réfractaire courte), car elle laisse passer la FA vers les ventricules (p. 411)."},{"t":"En cas de super-Wolff, l'adénosine est contre-indiquée (comme dans l'asthme)","ok":true,"why":"Le super-Wolff est, avec l'asthme, l'autre contre-indication à l'adénosine citée par le Collège."},{"t":"Le passage en fibrillation atriale rapide chez un patient à voie accessoire très perméable est appelé « super-Wolff »","ok":true,"why":"Super-Wolff = FA rapide conduite par une voie accessoire non décrémentielle : tachycardie irrégulière à QRS larges variables, risque de FV (p. 411)."},{"t":"La fibrillation atriale sur voie accessoire très perméable donne une tachycardie régulière à QRS fins","ok":false,"why":"Faux : tachycardie IRRÉGULIÈRE (FA), extrêmement rapide, à QRS larges de taille variable « en accordéon » (fig. 15.59, p. 411)."},{"t":"La voie accessoire possède, comme le nœud atrioventriculaire, une propriété « décrémentielle » qui filtre efficacement les influx","ok":false,"why":"Faux : la voie accessoire n'est pas décrémentielle ; c'est pourquoi elle ne filtre pas la FA (p. 411)."}],"explanation":"Le WPW à voie accessoire très perméable expose au « super-Wolff » en cas de FA (tachycardie irrégulière à QRS larges variables, potentiellement dégénérant en FV), l'adénosine y étant contre-indiquée.","src":"p. 411","deep":"**Pourquoi** : la voie accessoire n'a pas de propriété décrémentielle : si elle est très perméable (période réfractaire courte), elle ne filtre pas la FA : tachycardie irrégulière, extrêmement rapide, à QRS larges de taille variable « en accordéon » (super-Wolff), pouvant dégénérer en FV (p. 411).\n**À relier** : adénosine contre-indiquée (seule autre CI avec l'asthme).\n**Piège** : le danger vient d'une voie TRÈS perméable, pas peu perméable."},{"id":"231-qcm-310","type":"QRM","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic","urgence"],"difficulty":2,"stem":"Concernant le diagnostic électrocardiographique d'un syndrome coronarien aigu avec sus-décalage du segment ST :","options":[{"t":"Le sus-décalage doit être retrouvé sur au moins 2 dérivations adjacentes","ok":true,"why":"Critère de significativité : ≥ 2 dérivations adjacentes (même territoire) ; il localise l'artère occluse (p. 411-412)."},{"t":"L'apparition d'ondes Q de nécrose élimine toute indication de reperfusion","ok":false,"why":"Faux : des Q (vers la 6e heure, parfois plus tôt) ne doivent pas faire juger la reperfusion inutile (p. 412)."},{"t":"Un sus-décalage englobant l'onde T réalise l'onde de Pardee","ok":true,"why":"Onde de Pardee = sus-ST qui englobe la T ; à ne pas confondre avec un élargissement du QRS (points clés, p. 412, 415)."},{"t":"Un sus-décalage de 1,5 mm en V2 est considéré comme significatif","ok":false,"why":"Faux : en V1-V3 il faut ≥ 2 mm (1 mm ailleurs) ; un J sus-décalé V1-V4 peut être physiologique chez le jeune (p. 377, 412)."},{"t":"Il faut chercher le miroir sous forme de sous-décalage seulement après avoir identifié le sus-décalage","ok":true,"why":"Le sus-ST désigne le territoire de la coronaire occluse ; le sous-décalage n'est que son miroir : partir du miroir fait se tromper de lésion (p. 411, 415)."}],"explanation":"Le diagnostic de SCA ST+ repose sur un sus-décalage ≥ 2 mm en V1-V3 (≥ 1 mm ailleurs) sur au moins 2 dérivations adjacentes, avec recherche du miroir après identification du sus-décalage ; les ondes Q ne contre-indiquent pas la reperfusion.","src":"p. 411-412","deep":"**Pourquoi** : le sus-décalage est significatif à ≥ 2 mm de V1 à V3 et ≥ 1 mm ailleurs, sur au moins 2 dérivations adjacentes ; s'il englobe l'onde T = onde de Pardee. On traque d'abord le sus-décalage (territoire de la coronaire occluse), puis le miroir (p. 411-412).\n**À relier** : les Q de nécrose (≈ 6e heure) n'empêchent pas la reperfusion.\n**Piège** : 1,5 mm en V2 n'atteint pas le seuil de 2 mm."},{"id":"231-qcm-311","type":"QRM","rank":"B","objective":"231-obj-24","tags":["ECG","pièges","diagnostic"],"difficulty":3,"stem":"Concernant les pièges diagnostiques d'un sus-décalage du segment ST :","options":[{"t":"L'angor de Prinzmetal peut mimer un sus-décalage de type SCA, par spasme coronarien","ok":true,"why":"Le spasme coronarien de Prinzmetal donne un sus-ST semblable à celui du SCA : une des 5 étiologies de sus-ST (p. 412)."},{"t":"Un anévrisme ventriculaire peut expliquer la persistance d'un sus-décalage bien après la phase aiguë","ok":true,"why":"Le sus-ST régresse vite avec la reperfusion ; s'il persiste indéfiniment, penser à l'évolution anévrismale de la paroi infarcie (p. 412)."},{"t":"La repolarisation précoce ne donne jamais de sus-décalage du segment ST","ok":false,"why":"Faux : la repolarisation précoce donne un sus-ST inférolatéral ; c'est une des 5 étiologies de sus-ST (p. 412)."},{"t":"Un sous-décalage en V1-V3 ne justifie pas de réaliser un ECG 18 dérivations","ok":false,"why":"Faux : un sous-ST V1-V3 peut être le miroir d'un sus-ST postérieur (V7-V9), d'où l'ECG 18 dérivations devant toute douleur thoracique (p. 411)."},{"t":"Un bloc de branche gauche complet en contexte de douleur thoracique aiguë doit faire éliminer un SCA avec sus-décalage de ST","ok":true,"why":"La discordance appropriée du BBG masque ou mime un sus-ST : devant une douleur aiguë, éliminer un SCA ST+ (échographie ± coronarographie) (p. 381, 412)."}],"explanation":"Cinq étiologies de sus-décalage du ST sont à connaître : SCA ST+, anévrisme ventriculaire, repolarisation précoce, angor de Prinzmetal, péricardite ; le bloc de branche gauche et l'HVG marquée sont des diagnostics différentiels à connaître.","src":"p. 412","deep":"**Pourquoi** : 5 étiologies de sus-ST : SCA ST+, anévrisme ventriculaire (sus-ST persistant), repolarisation précoce (inférolatéral), angor de Prinzmetal (spasme), péricardite. Diagnostics différentiels : BBG/stimulation, HVG marquée (p. 412).\n**À relier** : BBG complet + douleur thoracique aiguë = éliminer un SCA ST+ (écho ± coronarographie).\n**Piège** : un sous-décalage en V1-V3 peut être le miroir d'un sus-décalage postérieur (V7-V9)."},{"id":"231-qcm-312","type":"QRM","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant les syndromes coronariens aigus sans sus-décalage du segment ST :","options":[{"t":"Une inversion des ondes T peut traduire une ischémie sous-épicardique","ok":true,"why":"T inversées = ischémie sous-épicardique ; le sous-ST, lui, traduit un courant de lésion sous-endocardique (p. 412)."},{"t":"Les anomalies ne peuvent jamais être masquées par un pacemaker","ok":false,"why":"Faux : un pacemaker peut masquer ces anomalies (le QRS stimulé a un ST décalé de manière appropriée, comme un BBG) (p. 412)."},{"t":"L'ECG est nécessairement anormal","ok":false,"why":"Faux : un ECG normal n'élimine pas un SCA sans sus-décalage (p. 412)."},{"t":"Une pseudo-normalisation d'ondes T antérieurement négatives est possible","ok":true,"why":"Des T auparavant négatives qui redeviennent positives (pseudo-normalisation) font partie des présentations du SCA sans sus-ST (p. 412)."},{"t":"On peut observer un sous-décalage du segment ST","ok":true,"why":"Sous-ST = courant de lésion sous-endocardique, une des présentations du SCA sans sus-ST (p. 412)."}],"explanation":"Les SCA sans sus-décalage du ST peuvent donner un sous-décalage du ST, une inversion ou un aplatissement des ondes T, une pseudo-normalisation d'ondes T négatives, voire un ECG normal ; un pacemaker peut masquer ces anomalies.","src":"p. 412-413","deep":"**Pourquoi** : SCA sans sus-ST : sous-décalage de ST (courant de lésion sous-endocardique), inversion des T (ischémie sous-épicardique), aplatissement, pseudo-normalisation de T négatives, ou ECG normal (p. 412-413).\n**À relier** : un pacemaker peut masquer les anomalies.\n**Piège** : un ECG normal n'élimine pas un SCA sans sus-décalage."},{"id":"231-qcm-313","type":"QRM","rank":"B","objective":"231-obj-26","tags":["ECG","traitement"],"difficulty":2,"stem":"Concernant les pacemakers, défibrillateurs et la resynchronisation cardiaque, quelles propositions sont exactes ?","options":[{"t":"La resynchronisation cardiaque peut être associée à la fonction défibrillateur","ok":true,"why":"Les trois fonctions (pacemaker, défibrillateur, resynchronisation) peuvent être réunies dans un défibrillateur de resynchronisation (fig. 15.60, p. 413)."},{"t":"Les BAV infrahissiens (Mobitz 2, BAV3) sont une indication même en l'absence de symptôme","ok":true,"why":"Le BAV infrahissien expose aux syncopes, voire à la mort subite : pacemaker même asymptomatique, contrairement au Mobitz 1 (p. 383, 412)."},{"t":"Le BAV2 Mobitz 1 symptomatique est une indication","ok":true,"why":"Le Mobitz 1 (suprahissien) n'est appareillé que s'il est symptomatique, comme la dysfonction sinusale (p. 412)."},{"t":"Un défibrillateur implantable n'assure jamais la fonction pacemaker","ok":false,"why":"Faux : le défibrillateur fait toujours pacemaker, sauf s'il est sous-cutané (p. 413)."},{"t":"Les bradycardies symptomatiques par dysfonction sinusale sont une indication","ok":true,"why":"Dysfonction sinusale = pacemaker si symptomatique ; à l'inverse les BAV infrahissiens s'appareillent même sans symptôme (p. 412)."}],"explanation":"Pacemaker : bradycardies symptomatiques (dysfonction sinusale, Mobitz 1, bradycardie sinusale) et BAV infrahissiens même asymptomatiques (p. 412). Le défibrillateur fait toujours pacemaker (sauf sous-cutané) et la resynchronisation est un stimulateur ; les trois fonctions peuvent s'associer (p. 413).","src":"p. 412-413","deep":"**Pourquoi** : pacemaker : bradycardies symptomatiques (dysfonction sinusale, Mobitz 1, bradycardie sinusale) ; BAV infrahissiens (Mobitz 2, BAV3) même sans symptôme. Le défibrillateur fait toujours pacemaker (sauf sous-cutané) ; la resynchronisation traite le BBG qui désynchronise le VG avec IC (p. 412-413).\n**Astuce** : les trois fonctions peuvent être associées.\n**Piège** : Mobitz 1 = symptomatique ; infrahissien = indication même asymptomatique."},{"id":"231-qcm-314","type":"QRM","rank":"B","objective":"231-obj-26","tags":["ECG"],"difficulty":2,"stem":"Concernant l'ECG d'un patient porteur d'un stimulateur cardiaque (pacemaker) :","options":[{"t":"Le spike est pathognomonique de la présence d'une stimulation cardiaque","ok":true,"why":"Il dure 0,4 à 1 ms : rien de physiologique n'est aussi bref sur l'ECG, d'où sa valeur pathognomonique (p. 413)."},{"t":"En cas de BAV, le QRS stimulé après le spike a un aspect de bloc de branche droit","ok":false,"why":"Faux : la sonde stimule le VD et l'influx gagne le reste de proche en proche : QRS large d'aspect BBG (p. 414)."},{"t":"La stimulation bipolaire est habituellement bien visible sur l'ECG de surface, contrairement à l'unipolaire","ok":false,"why":"Inversé : unipolaire (bout de sonde-boîtier) bien visible, bipolaire (deux pôles proches) peu visible (p. 414)."},{"t":"En cas de dysfonction sinusale, le pacemaker stimule le ventricule sans stimuler l'oreillette","ok":false,"why":"Faux : en dysfonction sinusale il stimule l'oreillette (P après le spike) ; en BAV il stimule le ventricule (p. 414)."},{"t":"Le spike de stimulation dure entre 40 et 100 ms","ok":false,"why":"Faux : 0,4 à 1 ms ; 40-100 ms serait la durée d'une onde physiologique (P, QRS) (p. 375, 413)."}],"explanation":"Le spike de stimulation (0,4 à 1 ms) est pathognomonique d'une stimulation cardiaque ; selon le mode (oreillette en cas de dysfonction sinusale, ventricule en cas de BAV avec aspect de BBG), et selon le montage (unipolaire bien visible, bipolaire peu visible).","src":"p. 413-414","deep":"**Pourquoi** : le spike dure 0,4-1 ms (rien de physiologique n'est aussi bref) : pathognomonique d'une stimulation. En dysfonction sinusale, stimulation de l'oreillette (P après le spike) ; en BAV, stimulation du ventricule : QRS large d'aspect BBG (conduction de proche en proche) (p. 413-414).\n**À relier** : unipolaire = spike bien visible ; bipolaire = peu visible.\n**Piège** : BBG (pas BBD), et ne confonds pas ms et dizaines de ms."},{"id":"231-qcm-315","type":"QRM","rank":"A","objective":"231-obj-27","tags":["diagnostic","clinique"],"difficulty":1,"stem":"Parmi les situations suivantes, lesquelles constituent une indication à un ECG conventionnel (12 dérivations ou plus) ?","options":[{"t":"Enquête familiale pour certaines cardiopathies héréditaires","ok":true,"why":"L'ECG 12 dérivations sert aux enquêtes familiales de certaines cardiopathies héréditaires (p. 414)."},{"t":"Palpitations ou douleur thoracique","ok":true,"why":"Tout symptôme (palpitations, douleur thoracique, dyspnée, malaise, syncope) justifie un ECG 12 dérivations (p. 414)."},{"t":"Bilan préopératoire systématique dès 40 ans, même sans risque particulier","ok":false,"why":"Faux : préopératoire après 65 ans, ou chez les patients à risque et avant les interventions à risque (p. 414)."},{"t":"Seulement chez les patients symptomatiques, jamais dans un bilan de santé systématique","ok":false,"why":"Faux : l'ECG est systématique dans les centres de santé lors des bilans de santé, et pour l'aptitude (p. 414)."},{"t":"Bilan initial de l'hypertension artérielle, seulement en présence de symptômes","ok":false,"why":"Faux : l'ECG est « obligatoirement » indiqué dans le bilan de l'HTA, sans condition de symptôme (p. 414) ; l'HTA est d'ailleurs la 1re cause d'HVG électrique (p. 407)."}],"explanation":"L'ECG conventionnel est indiqué systématiquement en bilan de santé, en bilan préopératoire après 65 ans, dans les aptitudes professionnelles/sportives, en enquête familiale, devant tout symptôme cardiovasculaire, et obligatoirement dans le bilan de l'HTA.","src":"p. 414","deep":"**Pourquoi** : ECG 12 dérivations indiqué : bilans de santé, aptitude professionnelle/sportive, préopératoire > 65 ans ou à risque, enquêtes familiales, symptômes (palpitations, douleur thoracique, dyspnée, malaise, syncope), suivi des maladies à complications cardiovasculaires ; obligatoire dans le bilan de l'HTA (p. 414).\n**Piège** : préopératoire = patients de plus de 65 ans, patients à risque ou interventions à risque (pas « dès 40 ans ») ; HTA = obligatoire même sans symptôme."},{"id":"231-qru-301","type":"QRU","rank":"B","objective":"231-obj-03","tags":["ECG"],"difficulty":2,"stem":"Quelle définition correspond à l'hypertrophie atriale gauche à l'ECG ?","options":[{"t":"Une onde P de durée supérieure à 110 ms (en pratique 120 ms), avec une composante négative > 40 ms en V1","ok":true,"why":"HAG = critère de DURÉE : P > 110 ms (120 en pratique) avec composante négative > 40 ms en V1 ; l'HAD, elle, augmente l'AMPLITUDE de P (p. 406)."},{"t":"Un PR raccourci inférieur à 120 ms","ok":false,"why":"PR court < 120 ms = un des signes de préexcitation (voie accessoire, avec l'onde delta) ; l'HAG touche la durée de P (p. 406, 410)."},{"t":"Une onde P pointue en V1 supérieure à 2 mm","ok":false,"why":"Critère d'amplitude en V1-V2 = hypertrophie atriale DROITE (p. 406)."},{"t":"Une onde P d'amplitude supérieure à 2,5 mm en D2","ok":false,"why":"P > 2,5 mm en D2 = HAD (souvent par dilatation) ; l'HAG allonge la P (p. 406)."},{"t":"Un indice de Sokolow supérieur à 35 mm","ok":false,"why":"Sokolow (S V1/V2 + R V5/V6) > 35 mm = HVG, ventriculaire et non atriale (p. 406)."}],"explanation":"L'hypertrophie atriale gauche se traduit par un allongement de la durée de l'onde P (> 110-120 ms) avec une composante négative terminale en V1 supérieure à 40 ms.","src":"p. 406","deep":"**Pourquoi** : HAG = P de durée > 110 ms (en pratique 120) avec composante négative > 40 ms en V1 (p. 406).\n**Astuce** : gauche = P LARGE (durée) ; droite = P AMPLE (amplitude).\n**Piège** : P > 2,5 mm en D2 ou > 2 mm en V1-V2 = HAD ; Sokolow = ventriculaire."},{"id":"231-qru-302","type":"QRU","rank":"B","objective":"231-obj-04","tags":["ECG"],"difficulty":2,"stem":"Quel critère définit l'hypertrophie atriale droite à l'ECG ?","options":[{"t":"Une onde P de durée supérieure à 120 ms","ok":false,"why":"Critère de DURÉE = hypertrophie atriale GAUCHE (avec composante négative > 40 ms en V1) (p. 406)."},{"t":"Une onde P d'amplitude supérieure à 2,5 mm en D2, ou supérieure à 2 mm en V1/V2","ok":true,"why":"HAD (le plus souvent par dilatation) = P ample, souvent pointue ; fréquente avec l'HVD du BPCO (p. 406-407)."},{"t":"Une onde delta au pied du QRS","ok":false,"why":"L'onde delta signe une préexcitation (voie accessoire, PR court) (p. 410)."},{"t":"Un QT supérieur à 0,44 seconde","ok":false,"why":"Le QT explore la repolarisation ventriculaire, pas l'oreillette (p. 376)."},{"t":"Un axe de QRS inférieur à 0°","ok":false,"why":"L'axe du QRS concerne les ventricules (ex. HBAG au-delà de -30°) ; l'HAD se lit sur l'onde P (p. 382, 406)."}],"explanation":"L'hypertrophie atriale droite se traduit par une onde P ample (> 2,5 mm en D2 ou > 2 mm en V1-V2), souvent pointue.","src":"p. 406","deep":"**Pourquoi** : HAD (le plus souvent par dilatation) = P ample et souvent pointue : > 2,5 mm en D2 ou > 2 mm en V1-V2 (p. 406).\n**Astuce** : droite = P AMPLE (amplitude) ; gauche = P LARGE (durée).\n**Piège** : une P de durée > 110-120 ms est le critère de l'HAG."},{"id":"231-qru-303","type":"QRU","rank":"B","objective":"231-obj-23","tags":["ECG"],"difficulty":2,"stem":"Combien de phases classiques décrit-on dans l'évolution électrocardiographique d'une péricardite aiguë ?","options":[{"t":"Une seule phase, stable jusqu'à guérison","ok":false,"why":"Faux : l'ECG évolue en 4 phases successives, le sus-ST n'étant présent qu'en phase 1, brève (p. 409)."},{"t":"Six phases","ok":false,"why":"Il y en a quatre : sus-ST diffus + sous-PQ (brève), T plates, T négatives persistantes, retour à la normale (p. 409)."},{"t":"Quatre phases","ok":true,"why":"Phase 1 brève (sus-ST diffus concave, sous-PQ, microvoltage), 2 (T plates), 3 (T négatives persistantes), 4 (retour à la normale) (p. 409)."},{"t":"Trois phases","ok":false,"why":"Il manque une phase : sus-ST, puis T plates, puis T négatives persistantes, puis retour progressif à la normale (p. 409)."},{"t":"Deux phases","ok":false,"why":"Il y en a quatre ; ne pas oublier les phases intermédiaires de T plates puis de T négatives persistantes (p. 409)."}],"explanation":"L'évolution ECG de la péricardite aiguë comporte 4 phases : sus-décalage diffus concave avec sous-décalage de PQ, onde T plate, onde T négative persistante, puis normalisation.","src":"p. 409","deep":"**Pourquoi** : 4 phases : (1) brève, sus-ST concave diffus sans miroir + sous-décalage de PQ ± microvoltage ; (2) T plates, ST iso ; (3) T négatives persistantes ; (4) retour progressif à la normale (p. 409).\n**Astuce** : ST+ → T plate → T négative → normale.\n**Piège** : le sus-décalage n'est présent qu'en phase 1."},{"id":"231-qru-304","type":"QRU","rank":"A","objective":"231-obj-27","tags":["diagnostic"],"difficulty":1,"stem":"Pour quel bilan initial le Collège précise-t-il que l'ECG est obligatoire ?","options":[{"t":"Systématiquement avant tout vaccin","ok":false,"why":"Non cité : les indications d'ECG 12 dérivations sont bilans de santé, aptitude, préopératoire > 65 ans/à risque, enquêtes familiales, symptômes, bilan d'HTA (p. 414)."},{"t":"Uniquement chez le sujet de plus de 80 ans","ok":false,"why":"Aucun seuil de 80 ans : l'âge n'intervient qu'en préopératoire (> 65 ans) ; l'ECG est obligatoire dans le bilan d'HTA quel que soit l'âge (p. 414)."},{"t":"Avant toute prescription d'antalgique simple","ok":false,"why":"Non cité parmi les indications de l'ECG 12 dérivations (bilans de santé, aptitude, préopératoire, enquêtes familiales, symptômes, HTA) (p. 414)."},{"t":"Dans le bilan initial d'une dyslipidémie isolée","ok":false,"why":"Non cité comme obligatoire ; seul le bilan de l'HTA rend l'ECG obligatoire (p. 414)."},{"t":"Dans le bilan initial de l'hypertension artérielle","ok":true,"why":"L'ECG est obligatoire dans le bilan de l'HTA : l'HTA est par ailleurs la 1re cause d'HVG électrique (Sokolow > 35 mm) (p. 407, 414)."}],"explanation":"L'ECG conventionnel est explicitement indiqué comme obligatoire dans le cadre du bilan de l'hypertension artérielle.","src":"p. 414","deep":"**Pourquoi** : l'ECG est obligatoire dans le bilan de l'HTA ; il est aussi systématique en centre de santé/bilans de santé, pour l'aptitude, et en préopératoire > 65 ans (p. 414).\n**À relier** : l'HTA est la 1re cause d'HVG électrique, devant le rétrécissement aortique (Sokolow > 35 mm) (p. 407).\n**Piège** : obligatoire = même sans symptôme."},{"id":"231-qru-305","type":"QRU","rank":"A","objective":"231-obj-24","tags":["ECG"],"difficulty":2,"stem":"Quel seuil de sus-décalage du segment ST est exigé dans les dérivations V1 à V3 pour être considéré comme significatif ?","options":[{"t":"Au moins 0,5 mm","ok":false,"why":"Trop bas : en V1-V3, où un J sus-décalé peut être physiologique chez le jeune, il faut au moins 2 mm (p. 377, 412)."},{"t":"Au moins 1 mm","ok":false,"why":"1 mm est le seuil des autres dérivations ; en V1-V3 il faut 2 mm (p. 412)."},{"t":"Au moins 5 mm","ok":false,"why":"Trop haut : le seuil est 2 mm en V1-V3 et 1 mm ailleurs, sur 2 dérivations adjacentes (p. 412)."},{"t":"Aucun seuil n'est requis en V1-V3","ok":false,"why":"Faux : seuil de 2 mm en V1-V3, où un J sus-décalé peut être physiologique chez le jeune (p. 377, 412)."},{"t":"Au moins 2 mm","ok":true,"why":"≥ 2 mm en V1-V3, ≥ 1 mm ailleurs, sur au moins 2 dérivations adjacentes ; puis chercher le miroir (p. 411-412)."}],"explanation":"Le sus-décalage du ST est considéré comme significatif à partir de 2 mm de V1 à V3, et de 1 mm dans les autres dérivations, retrouvé sur au moins 2 dérivations adjacentes.","src":"p. 412","deep":"**Pourquoi** : sus-ST significatif : ≥ 2 mm en V1-V3, ≥ 1 mm dans les autres dérivations, sur au moins 2 dérivations adjacentes (p. 412).\n**Astuce** : « 2 en V1-V3, 1 partout ailleurs ».\n**Piège** : 1 mm est le seuil des autres dérivations, pas de V1-V3."},{"id":"231-qroc-301","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG"],"difficulty":1,"question":"Quel indice ECG, comparant l'onde S en V1/V2 et l'onde R en V5/V6, sert au diagnostic d'hypertrophie ventriculaire gauche ?","answer":"L'indice de Sokolow","accept":["Sokolow","indice de Sokolow","critère de Sokolow","index de Sokolow"],"keywords":["sokolow"],"explanation":"Sokolow = S en V1/V2 + R en V5/V6, normal < 35 mm ; ne pas inverser S et R (p. 406).","src":"p. 406","deep":"**Pourquoi** : Sokolow = S en V1 ou V2 + R en V5 ou V6, normal < 35 mm ; l'HVG = augmentation de la masse (dilatation ou épaississement) (p. 406).\n**À relier** : forme sévère : T négative + ST sous-décalé en latéral.\n**Piège** : pseudonécrose en V1-V2 possible dans l'HVG importante."},{"id":"231-qroc-302","type":"QROC","rank":"A","objective":"231-obj-05","tags":["étiologie"],"difficulty":1,"question":"Quelle est l'étiologie la plus fréquente d'une hypertrophie ventriculaire gauche électrique ?","answer":"L'hypertension artérielle","accept":["HTA","hypertension","hypertension artérielle"],"keywords":["hta","hypertension"],"explanation":"HTA = 1re cause d'HVG, puis rétrécissement aortique ; l'ECG est par ailleurs obligatoire dans le bilan d'HTA (p. 407, 414).","src":"p. 407","deep":"**Pourquoi** : l'HTA est la première étiologie de l'HVG, suivie du rétrécissement aortique (p. 407).\n**À relier** : ECG obligatoire dans le bilan d'HTA ; indice de Sokolow < 35 mm.\n**Piège** : l'EP charge le VD, pas le VG."},{"id":"231-qroc-303","type":"QROC","rank":"B","objective":"231-obj-04","tags":["ECG","étiologie"],"difficulty":2,"question":"Quel aspect ECG triphasique (S-Q-T) évoque une hypertrophie aiguë du ventricule droit au cours d'une embolie pulmonaire ?","answer":"L'aspect S1Q3T3","accept":["S1Q3T3","S1 Q3 T3","S1Q3","S1-Q3-T3"],"keywords":["s1q3t3"],"explanation":"S en D1 + Q en D3 + T négative en D3 = S1Q3T3 : surcharge aiguë du VD (EP), souvent avec axe droit (p. 407-408).","src":"p. 407","deep":"**Pourquoi** : onde S en D1 + onde Q en D3 + onde T négative en D3 = hypertrophie (surcharge) aiguë du VD, classique dans l'EP (p. 407).\n**À relier** : déviation axiale droite, FA possible sur le tracé d'EP.\n**Piège** : un axe droit isolé peut être un HBPG ou une variante chez le longiligne."},{"id":"231-qroc-304","type":"QROC","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":1,"question":"Quelle anomalie ionique se caractérise par une onde T ample, pointue et symétrique, un allongement du PR et un élargissement du QRS ?","answer":"L'hyperkaliémie","accept":["hyperK","hyperkaliémie","hyper K","hyperkaliemie"],"keywords":["hyperkaliemie"],"explanation":"HyperK : T ample, pointue, symétrique, PR allongé, QRS élargi ; risque de BAV, TV, dysfonction sinusale (p. 408).","src":"p. 408","deep":"**Pourquoi** : T ample, pointue et symétrique + PR long + QRS large = hyperkaliémie (risque de BAV, TV, dysfonction sinusale) (p. 408).\n**Astuce** : hyperK = tout s'élargit et la T devient géante.\n**Piège** : hypoK = T plate, QT long et onde U."},{"id":"231-qroc-305","type":"QROC","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":1,"question":"Quelle onde ECG supplémentaire, à ne pas intégrer dans la mesure du QT, peut apparaître en cas d'hypokaliémie ?","answer":"L'onde U","accept":["onde U","l'onde U","U"],"keywords":["onde","u"],"explanation":"L'onde U suit la T en hypokaliémie ; l'intégrer surestimerait le QT (p. 377, 408).","src":"p. 408","deep":"**Pourquoi** : en hypokaliémie, une onde supplémentaire apparaît derrière la T : l'onde U (p. 408).\n**À relier** : T plate ou négative, ST sous-décalé, QT allongé → torsades de pointes.\n**Piège** : ne jamais l'inclure dans la mesure du QT (on le surestimerait)."},{"id":"231-qroc-306","type":"QROC","rank":"B","objective":"231-obj-23","tags":["ECG"],"difficulty":2,"question":"Quel segment est typiquement sous-décalé lors de la phase initiale d'une péricardite aiguë ?","answer":"Le segment PQ (PR)","accept":["segment PR","PQ","PR","segment PQ","sous-décalage de PQ","sous-décalage du segment PR"],"keywords":["pq","pr"],"explanation":"Phase 1 de la péricardite : sous-PQ (PR), visible en V5-V6 et inférieur, avec sus-ST diffus concave sans miroir et microvoltage (p. 409).","src":"p. 409","deep":"**Pourquoi** : en phase 1 de la péricardite, le segment PQ (PR) est sous-décalé, bien visible en V5-V6 et en inférieur, avec sus-ST diffus concave sans miroir (p. 409).\n**À relier** : phases 2-4 : T plates, T négatives, normalisation.\n**Piège** : sus-décalage du ST (diffus) et sous-décalage de PQ vont ensemble."},{"id":"231-qroc-307","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG"],"difficulty":1,"question":"Quel intervalle est raccourci (inférieur à 120 ms) en cas de préexcitation ventriculaire ?","answer":"L'intervalle PR","accept":["PR court","PR","l'espace PR","intervalle PR"],"keywords":["pr"],"explanation":"La voie accessoire excite le ventricule avant le NAV : PR < 120 ms, QRS élargi par l'onde delta (p. 410).","src":"p. 410","deep":"**Pourquoi** : la voie accessoire conduit vite l'influx de l'oreillette au ventricule : préexcitation avec PR court (< 120 ms), QRS élargi par l'onde delta (p. 410).\n**À relier** : bloquer le NAV (vagal/adénosine) démasque une préexcitation minime, sauf en FA.\n**Piège** : PR > 200 ms = BAV1 (l'inverse)."},{"id":"231-qroc-308","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG"],"difficulty":1,"question":"Quel nom est donné à l'empâtement du pied du QRS observé en cas de préexcitation ventriculaire ?","answer":"L'onde delta","accept":["onde delta","delta","l'onde delta"],"keywords":["onde","delta"],"explanation":"Onde delta = empâtement du pied du QRS, partie du ventricule préexcitée par la voie accessoire (p. 410).","src":"p. 410","deep":"**Pourquoi** : l'onde delta est l'empâtement du pied du QRS, correspondant à la partie du ventricule préexcitée par la voie accessoire (superposition des activations NAV et voie accessoire) (p. 410).\n**À relier** : PR court + onde delta + anomalies de repolarisation.\n**Piège** : ne pas la confondre avec une onde Q de nécrose."},{"id":"231-qroc-309","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG"],"difficulty":1,"question":"Comment nomme-t-on un sus-décalage du segment ST qui englobe l'onde T ?","answer":"L'onde de Pardee","accept":["Pardee","onde de Pardee","l'onde de Pardee"],"keywords":["pardee"],"explanation":"Onde de Pardee = sus-ST englobant la T, typique du SCA ST+ (avec miroir) ; à ne pas confondre avec un élargissement du QRS (p. 412, 415).","src":"p. 412","deep":"**Pourquoi** : l'onde de Pardee est un sus-décalage de ST englobant l'onde T, typique du SCA ST+ (avec miroir) (p. 412).\n**À relier** : traquer le sus-décalage puis chercher le miroir (≥ 2 mm V1-V3, ≥ 1 mm ailleurs, 2 dérivations adjacentes).\n**Piège** : péricardite = sus-ST concave, diffus, sans miroir."},{"id":"231-qroc-310","type":"QROC","rank":"B","objective":"231-obj-26","tags":["ECG"],"difficulty":1,"question":"Comment appelle-t-on l'impulsion électrique très brève, pathognomonique d'une stimulation cardiaque, visible sur l'ECG ?","answer":"Le spike de stimulation","accept":["spike","le spike","spike de stimulation","impulsion de stimulation"],"keywords":["spike"],"explanation":"Spike = impulsion de 0,4-1 ms, plus brève que tout phénomène physiologique : pathognomonique d'une stimulation (p. 413).","src":"p. 413","deep":"**Pourquoi** : l'impulsion de pacemaker dure 0,4-1 ms : rien de physiologique n'est aussi bref, donc le spike est pathognomonique d'une stimulation (pacemaker ou sonde d'entraînement) (p. 413).\n**À relier** : unipolaire = bien visible ; bipolaire = peu visible.\n**Piège** : après un spike ventriculaire, le QRS est large d'aspect BBG."},{"id":"231-qroc-311","type":"QROC","rank":"B","objective":"231-obj-28","tags":["paraclinique"],"difficulty":2,"question":"Quelle est la durée maximale de suivi permise par un moniteur ECG implantable (holter sous-cutané) ?","answer":"3 ans","accept":["trois ans","3"],"keywords":["3","ans"],"explanation":"Moniteur ECG implantable : suivi jusqu'à 3 ans, pour syncopes inexpliquées ou FA silencieuse ; Holter classique 24-96 h (p. 415).","src":"p. 415","deep":"**Pourquoi** : le moniteur ECG implantable (holter sous-cutané) enregistre jusqu'à 3 ans : syncopes inexpliquées, FA silencieuse (p. 415).\n**À relier** : Holter classique 24-96 h ; ECG ambulatoire très long jusqu'à 21 jours.\n**Piège** : ne confonds pas les durées (jours / 21 jours / 3 ans)."},{"id":"231-qroc-312","type":"QROC","rank":"B","objective":"231-obj-28","tags":["paraclinique"],"difficulty":2,"question":"Quelle est la durée maximale (en jours) des méthodes d'ECG ambulatoire de très longue durée, non implantables, utilisées en cas de symptômes rares ?","answer":"21 jours","accept":["3 semaines","21","trois semaines"],"keywords":["21","jours"],"explanation":"Symptômes rares : ECG ambulatoire jusqu'à 21 jours ou enregistreurs d'événements (montres ECG) ; au-delà, holter implantable (p. 415).","src":"p. 415","deep":"**Pourquoi** : pour des symptômes rares, un Holter de 24-96 h est trop court : on utilise l'ECG ambulatoire de très longue durée (jusqu'à 21 jours) ou des enregistreurs d'événements (outils dédiés, montres ECG) (p. 415).\n**À relier** : holter implantable jusqu'à 3 ans.\n**Piège** : 21 jours (pas 96 h, pas 3 ans)."},{"id":"231-open-31","type":"OPEN","rank":"A","objective":"231-obj-05","tags":["ECG","diagnostic"],"difficulty":2,"prompt":"Décrivez la démarche diagnostique électrocardiographique de l'hypertrophie ventriculaire gauche, les anomalies observées dans les formes sévères, et les pièges d'interprétation associés.","rubric":[{"point":"Définir l'indice de Sokolow et son seuil normal (< 35 mm)","weight":2},{"point":"Décrire la déviation axiale associée : modeste, vers la gauche","weight":1},{"point":"Décrire les anomalies de repolarisation des formes sévères : onde T négative et sous-décalage du ST en latéral, disparition de l'onde Q septale","weight":2},{"point":"Citer le piège de pseudonécrose/pseudo-sus-décalage en V1-V2","weight":2},{"point":"Citer les principales étiologies : HTA puis rétrécissement aortique","weight":1}],"model":"**Diagnostic** : l'indice de Sokolow (somme de l'onde S en V1/V2 et de l'onde R en V5/V6) est l'indice le plus utilisé, normal sous 35 mm. La déviation axiale associée est modeste, orientée vers la gauche, et les QRS restent le plus souvent inférieurs à 120 ms malgré un possible élargissement lié à la masse myocardique.\n\n**Formes sévères** : anomalie secondaire de la repolarisation avec onde T négative et sous-décalage du ST dans les dérivations latérales (D1, aVL, V5, V6), et disparition de l'onde Q septale dans ces mêmes dérivations.\n\n**Pièges** : une HVG électrique importante peut donner en V1-V2 un aspect QS mimant une séquelle d'infarctus (pseudonécrose) et/ou un sus-décalage trompeur du segment ST.\n\n**Étiologies** : l'hypertension artérielle est la plus fréquente, suivie du rétrécissement aortique.","src":"p. 406-407"},{"id":"231-open-32","type":"OPEN","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":2,"prompt":"Comparez les anomalies électrocardiographiques de l'hypokaliémie et de l'hyperkaliémie, ainsi que leurs principaux risques rythmiques.","rubric":[{"point":"Décrire les signes ECG de l'hypokaliémie : onde T plate/négative, sous-décalage du ST, QT allongé, onde U","weight":3},{"point":"Décrire les signes ECG de l'hyperkaliémie : onde T ample et pointue, PR allongé, QRS élargi","weight":3},{"point":"Citer les risques rythmiques de l'hypokaliémie : extrasystoles, TV, torsades de pointes, FV","weight":2},{"point":"Citer les risques rythmiques de l'hyperkaliémie : BAV, TV, dysfonction sinusale","weight":2}],"model":"**Hypokaliémie** : onde T plate ou négative diffuse avec sous-décalage du ST, QRS normal, allongement du QT avec apparition possible d'une onde U (à ne pas intégrer à la mesure du QT). Elle expose à l'extrasystolie, à la tachycardie ventriculaire, à la torsade de pointes et à la fibrillation ventriculaire.\n\n**Hyperkaliémie** : onde T ample, pointue et symétrique, allongement du PR, élargissement du QRS. Elle expose au bloc atrioventriculaire, à la tachycardie ventriculaire et à la dysfonction sinusale.","src":"p. 408"},{"id":"231-open-33","type":"OPEN","rank":"B","objective":"231-obj-24","tags":["ECG","urgence","pièges"],"difficulty":3,"prompt":"Détaillez les critères électrocardiographiques du syndrome coronarien aigu avec sus-décalage du segment ST, ainsi que les principaux pièges diagnostiques à connaître.","rubric":[{"point":"Citer les seuils de sus-décalage significatif : ≥ 2 mm en V1-V3, ≥ 1 mm ailleurs, sur au moins 2 dérivations adjacentes","weight":2},{"point":"Décrire l'onde de Pardee (sus-décalage englobant l'onde T)","weight":1},{"point":"Décrire la démarche : traquer le sus-décalage puis chercher le miroir (sous-décalage), pas l'inverse","weight":1},{"point":"Citer au moins 3 des 5 étiologies de sus-décalage du ST (SCA ST+, anévrisme ventriculaire, repolarisation précoce, angor de Prinzmetal, péricardite)","weight":2},{"point":"Citer les diagnostics différentiels/pièges : bloc de branche gauche complet, HVG marquée, sous-décalage antérieur miroir d'un sus-décalage postérieur (justifiant un ECG 18 dérivations)","weight":2},{"point":"Préciser que les ondes Q de nécrose n'excluent pas une indication de reperfusion","weight":1}],"model":"**Critères** : sus-décalage ≥ 2 mm de V1 à V3 et ≥ 1 mm dans les autres dérivations, retrouvé sur au moins 2 dérivations adjacentes ; lorsqu'il englobe l'onde T, il réalise l'onde de Pardee. La démarche consiste à identifier le sus-décalage puis à chercher son miroir, et non l'inverse.\n\n**Cinq étiologies de sus-décalage du ST** : SCA avec sus-décalage (onde de Pardee avec miroir), anévrisme ventriculaire (persistance après infarctus séquellaire marqué), repolarisation précoce (inférolatérale), angor de Prinzmetal (spasme coronarien), péricardite (diffus, concave, sans miroir).\n\n**Pièges** : un bloc de branche gauche complet en contexte de douleur thoracique aiguë doit faire éliminer un SCA ST+ ; une HVG marquée peut donner un sous-décalage dans les dérivations latérales et un sus-décalage en V1-V2 (alors que dans le BBG ou la stimulation ventriculaire par pacemaker, c'est dans les dérivations où le QRS est négatif que le ST est sus-décalé de manière appropriée) ; un sous-décalage antérieur (V1-V3) peut être le miroir d'un sus-décalage postérieur (V7-V9), justifiant un ECG 18 dérivations devant toute douleur thoracique. Enfin, la présence d'ondes Q de nécrose ne doit pas faire renoncer à tort à une reperfusion jugée trop tardive.","src":"p. 411-412"},{"id":"231-open-34","type":"OPEN","rank":"B","objective":"231-obj-26","tags":["ECG","traitement"],"difficulty":2,"prompt":"Expliquez comment reconnaître, sur l'ECG, la présence d'une stimulation cardiaque (pacemaker), et précisez les principales indications à son implantation.","rubric":[{"point":"Décrire le spike de stimulation : impulsion très brève (0,4-1 ms), pathognomonique","weight":2},{"point":"Décrire l'aspect en cas de stimulation atriale (dysfonction sinusale) : onde P après le spike","weight":1},{"point":"Décrire l'aspect en cas de stimulation ventriculaire (BAV) : QRS large d'aspect de bloc de branche gauche après le spike","weight":2},{"point":"Opposer stimulation unipolaire (bien visible) et bipolaire (peu visible) sur l'ECG de surface","weight":1},{"point":"Citer les indications : bradycardies symptomatiques (dysfonction sinusale, Mobitz 1, bradycardie sinusale) et BAV infrahissiens (Mobitz 2, BAV3) même asymptomatiques","weight":2}],"model":"**Reconnaissance** : le spike de stimulation est une impulsion électrique très brève (0,4 à 1 ms), pathognomonique d'une stimulation cardiaque, rien de physiologique n'étant aussi court sur un ECG. En cas de dysfonction sinusale, le pacemaker stimule l'oreillette (onde P après le spike). En cas de BAV, il stimule le ventricule avec un délai AV programmé, donnant un QRS large après le spike, d'aspect de bloc de branche gauche (la stimulation ventriculaire droite se propageant de proche en proche vers le reste des ventricules). La stimulation unipolaire (entre le bout de la sonde et le boîtier) est bien visible sur l'ECG de surface, la bipolaire (entre le bout de la sonde et une électrode proche) est peu visible.\n\n**Indications** : bradycardies symptomatiques (dysfonction sinusale, BAV2 Mobitz 1, bradycardie sinusale) et BAV infrahissiens (BAV2 Mobitz 2, BAV3), ces derniers même en l'absence de symptôme.","src":"p. 412-414"},{"id":"231-qroc-401","type":"QROC","rank":"A","objective":"231-obj-01","tags":["examens"],"difficulty":1,"question":"À 25 mm/s, quelle durée représente un petit carreau (1 mm) de l'ECG ?","answer":"40 ms","accept":["40 ms","0,04 s","0.04","40 millisecondes","0,04 seconde","40"],"keywords":["40"],"explanation":"À 25 mm/s : 1 mm = 40 ms, 5 mm (grand carreau) = 200 ms ; le PR normal fait donc 3 à 5 petits carreaux (p. 375-376).","src":"p. 375","deep":"**Pourquoi** : à 25 mm/s, 1 mm = 40 ms et un grand carreau (5 mm) = 200 ms (p. 375).\n**À relier** : PR normal 120-200 ms = 3 à 5 petits carreaux ; FC = 300 / nombre de grands carreaux.\n**Piège** : 40 ms = petit carreau ; 200 ms = grand carreau."},{"id":"231-qroc-402","type":"QROC","rank":"A","objective":"231-obj-01","tags":["définition"],"difficulty":1,"question":"Quelles sont les bornes normales de l'intervalle PR ?","answer":"120 à 200 ms","accept":["120-200","120 a 200","120-200 ms","entre 120 et 200 ms","120 à 200","de 120 à 200 ms"],"keywords":["120","200"],"explanation":"PR normal 120-200 ms (bornes incluses) ; > 200 ms fixe = BAV1, < 120 ms = PR court, un des signes de préexcitation (avec l'onde delta) (p. 375-376, 410).","src":"p. 375","deep":"**Pourquoi** : le PR (début de P au début de QRS) mesure toute la conduction, du sinus au réseau de Purkinje ; normal de 120 à 200 ms, bornes incluses (p. 375).\n**À relier** : > 200 ms = BAV1 ; < 120 ms = PR court, évocateur de préexcitation s'il s'associe à une onde delta (p. 410).\n**Piège** : ne dis pas « PR = temps de traversée du NAV seul »."},{"id":"231-qroc-403","type":"QROC","rank":"A","objective":"231-obj-01","tags":["définition"],"difficulty":2,"question":"Dans le tableau des valeurs normales, quel seuil le QT corrigé (à 60 bpm) ne doit-il pas dépasser ?","answer":"450 ms","accept":["450","< 450 ms","inférieur à 450 ms","0,45 s"],"keywords":["450"],"explanation":"QTc < 450 ms à 60 bpm (en pratique 470-480) ; un QT long fait vérifier médicaments et ionogramme (risque de torsades) (p. 375, 404).","src":"p. 375","deep":"**Pourquoi** : le QT varie avec la FC ; on le normalise (Bazett) et le QTc normal est < 450 ms à 60 bpm (en pratique 470-480 ms) (p. 375).\n**À relier** : QT allongé = médicaments, ions (hypoK, hypoCa, hypoMg), QT long congénital → risque de torsades.\n**Piège** : c'est une limite supérieure : le QTc normal est INFÉRIEUR à 450."},{"id":"231-qroc-404","type":"QROC","rank":"A","objective":"231-obj-24","tags":["diagnostic"],"difficulty":2,"question":"Quelle amplitude minimale de sus-décalage du ST est significative en V1-V3 ?","answer":"2 mm (≥ 2 mm)","accept":["2 mm","≥ 2","≥ 2 mm","au moins 2 mm","deux millimètres"],"keywords":["2"],"explanation":"≥ 2 mm en V1-V3 (où un J sus-décalé peut être physiologique chez le jeune), ≥ 1 mm ailleurs, sur 2 dérivations adjacentes (p. 377, 412).","src":"p. 412","deep":"**Pourquoi** : le sus-ST est significatif s'il atteint ≥ 2 mm de V1 à V3 (≥ 1 mm ailleurs), sur au moins 2 dérivations adjacentes (p. 412).\n**À relier** : s'il englobe la T = onde de Pardee ; chercher ensuite le miroir.\n**Piège** : 1 mm est le seuil des autres dérivations."},{"id":"231-qroc-406","type":"QROC","rank":"A","objective":"231-obj-08","tags":["définition","diagnostic"],"difficulty":1,"question":"Au-delà de quelle valeur de l'intervalle PR (constant, sans onde P bloquée) parle-t-on de BAV du 1er degré ?","answer":"PR > 200 ms","accept":["pr > 200","pr allonge","pr long","200 ms","> 200 ms","supérieur à 200 ms","PR > 200","plus de 200 ms"],"keywords":["200"],"explanation":"BAV1 = PR fixe > 200 ms, toutes les P conduites ; PR qui s'allonge puis P bloquée = Mobitz 1 (p. 385-386).","src":"p. 386","deep":"**Pourquoi** : BAV1 = PR fixe et constant > 200 ms, toutes les P étant conduites (retard sans blocage) (p. 386).\n**À relier** : Mobitz 1 = PR qui s'allonge puis P bloquée ; Mobitz 2 = PR constant puis P bloquée.\n**Piège** : PR variable ou P bloquée = jamais un BAV1."},{"id":"231-qroc-407","type":"QROC","rank":"A","objective":"231-obj-08","tags":["diagnostic"],"difficulty":2,"question":"Quel est le siège habituel d'un BAV2 Mobitz 2 ?","answer":"Infrahissien","accept":["infrahissien","infra-hissien","sous-hissien","siège infrahissien"],"keywords":["infra"],"explanation":"Mobitz 2 (PR constant puis P bloquée inopinée) = infrahissien : pacemaker même sans symptôme ; Mobitz 1 = suprahissien (p. 385, 412).","src":"p. 385","deep":"**Pourquoi** : Mobitz 2 = PR constant puis P bloquée de façon inopinée ; siège infrahissien (p. 385).\n**À relier** : BAV infrahissien (Mobitz 2, BAV3) = pacemaker même sans symptôme.\n**Piège** : Mobitz 1 (PR qui s'allonge) est suprahissien."},{"id":"231-qroc-408","type":"QROC","rank":"A","objective":"231-obj-21","tags":["diagnostic","urgence"],"difficulty":2,"question":"Quelle TV polymorphe peut compliquer l'allongement du QT de l'hypokaliémie ?","answer":"La torsade de pointes","accept":["torsade","tdp","torsade de pointes","torsades de pointes","torsades"],"keywords":["torsade"],"explanation":"L'hypokaliémie allonge le QT et expose aux ESV, TV, torsades de pointes et FV (p. 404, 408).","src":"p. 408","deep":"**Pourquoi** : l'hypokaliémie allonge le QT et expose aux ESV, TV, torsades de pointes et FV (p. 408).\n**À relier** : prise en charge de la torsade : corriger les ions, arrêter les médicaments allongeant le QT, accélérer la FC.\n**Piège** : la torsade est une TV polymorphe sur QT long ; elle peut dégénérer en FV."},{"id":"231-qroc-409","type":"QROC","rank":"A","objective":"231-obj-14","tags":["diagnostic"],"difficulty":1,"question":"Quelle est la fréquence ventriculaire classique d'un flutter atrial conduit en 2/1 ?","answer":"150 bpm","accept":["150","150/min","150 battements par minute"],"keywords":["150"],"explanation":"Flutter ≈ 300/min atrial conduit 1 sur 2 : 150/min aux ventricules ; 3/1 = 100, 4/1 = 75 (p. 394).","src":"p. 394","deep":"**Pourquoi** : le NAV laisse passer un influx sur deux : 300 / 2 = 150 bpm en conduction 2/1 (p. 394).\n**À relier** : 3/1 = 100 bpm, 4/1 = 75 bpm ; une manœuvre vagale ralentit la cadence et démasque les ondes F.\n**Piège** : 300 est la fréquence atriale, 150 la cadence ventriculaire."},{"id":"231-qroc-410","type":"QROC","rank":"A","objective":"231-obj-15","tags":["diagnostic"],"difficulty":2,"question":"Quelle est la fréquence habituelle d'une tachycardie jonctionnelle ?","answer":"Environ 200 bpm (130-260)","accept":["200","200 bpm","autour de 200","environ 200","200/min"],"keywords":["200"],"explanation":"Tachycardie jonctionnelle : très régulière, ≈ 200/min (130-260 selon mécanisme et tonus sympathique), réduite par manœuvres vagales ou adénosine (p. 395, 397).","src":"p. 395","deep":"**Pourquoi** : tachycardie jonctionnelle (Bouveret) = tachycardie très régulière, souvent ≈ 200 bpm (130-260 selon mécanisme et tonus sympathique), à QRS fins (p. 395).\n**À relier** : réduction par manœuvres vagales ou adénosine IV.\n**Piège** : FA = 100-200 mais irrégulière ; flutter = 300 atriale / 150 ventriculaire."},{"id":"231-qroc-411","type":"QROC","rank":"A","objective":"231-obj-12","tags":["diagnostic"],"difficulty":2,"question":"Comment varie la fréquence d'une TSV non sinusale, par opposition à la variation progressive de la tachycardie sinusale ?","answer":"Par « marches d'escalier »","accept":["marche d'escalier","marches d'escalier","escalier","en marches d'escalier","paliers"],"keywords":["escalier"],"explanation":"Tachycardie sinusale = variation progressive (tonus neurovégétatif) ; TSV = variation par « marches d'escalier » sur la courbe de fréquence (p. 391).","src":"p. 390-391","deep":"**Pourquoi** : la tachycardie sinusale accélère et ralentit progressivement (tonus sympathique/parasympathique, contexte) ; la TSV non sinusale démarre et varie par paliers (p. 390-391).\n**À relier** : visible sur la courbe de fréquence d'un scope, d'une télémétrie, d'un holter ou au massage sinocarotidien.\n**Piège** : la fréquence absolue ne permet pas de trancher."},{"id":"231-qroc-412","type":"QROC","rank":"A","objective":"231-obj-18","tags":["diagnostic"],"difficulty":2,"question":"Outre la dissociation ventriculoatriale, quels complexes affirment avec certitude une TV ?","answer":"Les complexes de capture et de fusion","accept":["capture et fusion","captures et fusions","complexes de capture et de fusion","fusion et capture"],"keywords":["captur","fusion"],"explanation":"Capture (QRS fin précédé d'une P) et fusion (QRS intermédiaire) supposent une dissociation VA : arguments de certitude de TV (p. 400-401).","src":"p. 400","deep":"**Pourquoi** : capture = QRS fin précédé d'une P (l'influx sinusal gagne la course) ; fusion = QRS intermédiaire (compétition TV / influx sinusal). Ils n'existent que s'il y a dissociation ventriculoatriale (p. 400).\n**À relier** : autres arguments de certitude : plus de QRS que de P.\n**Piège** : ce sont des QRS plus fins que la TV, pas des QRS plus larges."},{"id":"231-qroc-413","type":"QROC","rank":"A","objective":"231-obj-02","tags":["urgence","traitement"],"difficulty":1,"question":"Quel traitement s'impose devant une tachycardie mal tolérée sur le plan hémodynamique ?","answer":"La cardioversion électrique externe","accept":["cardioversion","choc electrique","cee","cardioversion électrique","choc électrique externe","CEE","choc électrique"],"keywords":["electri"],"explanation":"Tachycardie mal tolérée = cardioversion électrique externe d'emblée ; si bonne tolérance, manœuvres vagales ± adénosine (fig. 15.51, p. 405).","src":"p. 405","deep":"**Pourquoi** : une tachycardie mal tolérée n'attend pas : cardioversion électrique externe d'emblée (p. 405).\n**À relier** : bonne tolérance = manœuvres vagales ± adénosine (BAV transitoire) ; TV = alerte, faire le 15.\n**Piège** : ne retarde pas le choc par des manœuvres chez un patient instable."},{"id":"231-qroc-414","type":"QROC","rank":"A","objective":"231-obj-06","tags":["diagnostic"],"difficulty":2,"question":"Au-delà de quelle valeur d'axe du QRS parle-t-on d'hémibloc antérieur gauche ?","answer":"Au-delà de –30° (D2 négatif)","accept":["-30","–30","-30°","-30 degrés","au-delà de -30","moins 30","−30°"],"keywords":["30"],"explanation":"HBAG = axe au-delà de -30° (D2 négatif) avec QRS à peine élargi ; HBPG = au-delà de +90° (D1 négatif), d'exclusion (p. 382-383).","src":"p. 382","deep":"**Pourquoi** : HBAG = déviation de l'axe vers la gauche au-delà de -30° (D2 négatif) (p. 382).\n**Astuce** : Antérieur = Gauche (axe gauche) ; l'HBPG = axe droit au-delà de +90°.\n**Piège** : l'axe normal est -30/+90° ; l'HBAG est fréquent (branche fragile), l'HBPG rare."},{"id":"231-qroc-415","type":"QROC","rank":"A","objective":"231-obj-24","tags":["diagnostic"],"difficulty":1,"question":"Quelles sont les trois dérivations qui explorent le territoire inférieur du ventricule gauche ?","answer":"D2, D3, aVF","accept":["d2 d3 avf","ii, iii, avf","ii iii avf","DII, DIII, aVF","D2 D3 aVF","II, III, aVF","D2, D3 et aVF","DII DIII aVF"],"keywords":["avf"],"explanation":"D2, D3, aVF = territoire inférieur (diaphragmatique) du VG ; deux T négatives en D2-D3 sont pathologiques (p. 374, 411).","src":"p. 374","deep":"**Pourquoi** : D2, D3 et aVF regardent la face inférieure (diaphragmatique) du VG (p. 374).\n**À relier** : latéral = D1, aVL, V5, V6 ; antéroseptal = V1-V3 ; apical = V4 ; postérieur = V7-V9.\n**Astuce** : les trois dérivations « du bas » du plan frontal."},{"id":"231-qroc-416","type":"QROC","rank":"B","objective":"231-obj-03","tags":["diagnostic"],"difficulty":2,"question":"Quelle amplitude de l'onde P en D2 définit une hypertrophie atriale droite ?","answer":"Plus de 2,5 mm","accept":["2,5","2.5","2,5 mm","> 2,5 mm","plus de 2,5 mm","supérieure à 2,5 mm"],"keywords":["2"],"explanation":"HAD = P ample (> 2,5 mm en D2 ou > 2 mm en V1-V2), souvent pointue ; HAG = P longue (> 110-120 ms) (p. 406).","src":"p. 406","deep":"**Pourquoi** : l'HAD (surtout par dilatation) donne une P ample, souvent pointue : > 2,5 mm en D2 ou > 2 mm en V1-V2 (p. 406).\n**Astuce** : droite = P AMPLE ; gauche = P LARGE (> 110-120 ms).\n**Piège** : le critère de durée est celui de l'HAG."},{"id":"231-qroc-417","type":"QROC","rank":"B","objective":"231-obj-16","tags":["traitement"],"difficulty":2,"question":"Quelle pathologie respiratoire contre-indique l'adénosine IV ?","answer":"L'asthme","accept":["asthme","l'asthme","asthme sévère"],"keywords":["asthm"],"explanation":"L'adénosine peut provoquer un bronchospasme intense transitoire (même sans asthme) ; autres CI : hypotension, FA préexcitée (super-Wolff) (p. 390, 411).","src":"p. 390","deep":"**Pourquoi** : l'adénosine peut provoquer un bronchospasme intense transitoire, même chez un non-asthmatique (p. 390).\n**À relier** : autres CI : hypotension artérielle, FA préexcitée (super-Wolff).\n**Piège** : effet très bref (≈ 10 s) mais contre-indication ferme en cas d'asthme."},{"id":"231-qroc-418","type":"QROC","rank":"B","objective":"231-obj-28","tags":["examens"],"difficulty":2,"question":"Quelle est la durée d'enregistrement d'un Holter ECG classique ?","answer":"24 à 96 heures","accept":["24 a 96","24-96","24 h","24 à 96 h","24-96 h","de 24 à 96 heures"],"keywords":["24"],"explanation":"Holter : 2 à 12 dérivations, 24 à 96 h, lecture différée ; symptômes rares : jusqu'à 21 jours ou holter implantable (3 ans) (p. 415).","src":"p. 415","deep":"**Pourquoi** : le Holter enregistre 2 à 12 dérivations pendant 24 à 96 h, avec analyse différée ; il faut une bonne probabilité que les symptômes se répètent (p. 415).\n**À relier** : symptômes rares → jusqu'à 21 jours ou enregistreurs d'événements ; holter implantable jusqu'à 3 ans.\n**Piège** : ne confonds pas les trois échelles de durée."},{"id":"231-qroc-419","type":"QROC","rank":"B","objective":"231-obj-25","tags":["diagnostic","urgence"],"difficulty":3,"question":"Quel terme image décrit les QRS larges de taille variable d'une FA rapide conduite par une voie accessoire (super-Wolff) ?","answer":"QRS « en accordéon »","accept":["accordeon","accordéon","en accordéon","QRS en accordéon","aspect en accordéon"],"keywords":["accord"],"explanation":"FA conduite par une voie accessoire très perméable (non décrémentielle) : tachycardie irrégulière très rapide à QRS « en accordéon », risque de FV ; adénosine CI (p. 411).","src":"p. 410-411","deep":"**Pourquoi** : en FA, une voie accessoire très perméable (sans filtre décrémentiel) transmet les influx atriaux : tachycardie irrégulière, très rapide, à QRS larges de largeur variable « en accordéon » (super-Wolff), risque de FV (p. 410-411).\n**À relier** : adénosine contre-indiquée, pas de blocage du NAV.\n**Piège** : irrégulière (FA), pas régulière comme un rythme réciproque."},{"id":"231-qroc-420","type":"QROC","rank":"B","objective":"231-obj-26","tags":["diagnostic"],"difficulty":2,"question":"Quel aspect de QRS suit le spike d'une stimulation ventriculaire droite par pacemaker ?","answer":"QRS large d'aspect BBG","accept":["bbg","branche gauche","QRS large de type BBG","bloc de branche gauche","QRS larges avec aspect de bloc de branche gauche","BBG"],"keywords":["gauche"],"explanation":"La sonde stimule le VD ; l'influx gagne le reste des ventricules de proche en proche : QRS large d'aspect BBG après le spike (p. 414).","src":"p. 413-414","deep":"**Pourquoi** : le pacemaker stimule le ventricule droit : l'influx se propage de proche en proche, lentement, hors du réseau His-Purkinje : QRS large d'aspect BBG après le spike (p. 413-414).\n**À relier** : en dysfonction sinusale, le pacemaker stimule l'oreillette (P après le spike).\n**Piège** : aspect de BBG (pas BBD)."},{"id":"231-qcm-501","type":"QRM","rank":"B","objective":"231-obj-01","tags":["électrophysiologie","physiologie"],"difficulty":2,"stem":"Concernant la genèse du signal ECG et la conduction atrioventriculaire, quelles propositions sont exactes ?","options":[{"t":"La dépolarisation ventriculaire progresse de l'épicarde vers l'endocarde, la repolarisation en sens inverse.","ok":false,"why":"Inversé : dépolarisation endocarde → épicarde, repolarisation épicarde → endocarde ; d'où des T concordantes (p. 371)."},{"t":"Il existe physiologiquement plusieurs passages électriques entre oreillettes et ventricules.","ok":false,"why":"Faux : le NAV est le seul passage, l'anneau étant isolant ; une voie accessoire (Kent) est anormale (préexcitation) (p. 410)."},{"t":"Sur l'ECG normal, les ondes T sont discordantes par rapport aux QRS.","ok":false,"why":"Faux : T concordantes ; la discordance appropriée n'apparaît qu'avec des QRS larges (p. 371, 381)."},{"t":"Un front de dépolarisation qui se dirige vers l'électrode inscrit une onde positive.","ok":true,"why":"Front qui vient vers l'électrode = positif, qui s'éloigne = négatif, perpendiculaire = isodiphasique (fig. 15.3, p. 371)."},{"t":"L'activité enregistrée par l'ECG provient de la somme des potentiels d'action cellulaires.","ok":true,"why":"L'ECG recueille à distance la somme des potentiels d'action suivant un front de dépolarisation (P atriale, puis QRS) (p. 371)."}],"explanation":"L'ECG enregistre la somme des potentiels d'action ; un front qui se dirige vers l'électrode est positif ; les T sont concordantes car la repolarisation progresse de l'épicarde vers l'endocarde ; le NAV est le seul passage atrioventriculaire physiologique.","src":"p. 371, 410","deep":"**Pourquoi** : l'ECG enregistre la somme des potentiels d'action ; un front qui se dirige vers l'électrode s'inscrit positif. La dépolarisation va de l'endocarde vers l'épicarde et la repolarisation en sens inverse : T concordantes aux QRS (p. 371, 410).\n**À relier** : le NAV est le seul passage physiologique oreillette-ventricule (anneau isolant).\n**Piège** : inverser le sens endocarde/épicarde."},{"id":"231-qcm-502","type":"QRM","rank":"A","objective":"231-obj-01","tags":["axe","ECG normal"],"difficulty":2,"stem":"Concernant l'axe du QRS dans le plan frontal, quelles propositions sont exactes ?","options":[{"t":"Un hémibloc gauche peut rendre l'axe du QRS anormal.","ok":true,"why":"L'hémibloc se diagnostique justement sur l'axe : HBAG au-delà de -30°, HBPG au-delà de +90° (p. 375, 382)."},{"t":"Chez le sujet filiforme au cœur vertical, l'axe est proche de 90°.","ok":true,"why":"L'axe suit l'anatomie : cœur vertical du filiforme ≈ 90°, cœur horizontal de l'obèse ou de la cardiomégalie ≈ 0° (p. 375)."},{"t":"Chez l'obèse au cœur horizontal, l'axe est proche de 0°.","ok":true,"why":"Cœur horizontal (obèse, cardiomégalie) ≈ 0° ; cœur vertical (filiforme) ≈ 90° ; ces variantes restent normales (p. 375)."},{"t":"Une onde isodiphasique a une composante positive nettement prédominante.","ok":false,"why":"Faux : isodiphasique = composantes positive et négative d'égale importance (aspect sinusoïde) (p. 375)."},{"t":"Le double triaxe de Bailey gradue les dérivations de 30° en 30° dans le sens horaire, D1 étant à 0°.","ok":true,"why":"Bailey : dérivations frontales tous les 30°, sens horaire, D1 à 0° (aVF à +90°, aVL à -30°) (p. 375)."}],"explanation":"L'axe se mesure sur le double triaxe de Bailey ; il varie avec la morphologie (cœur vertical ≈ 90°, horizontal ≈ 0°) et devient anormal en cas d'hémibloc gauche ou d'anomalie ventriculaire marquée.","src":"p. 375","deep":"**Pourquoi** : le double triaxe de Bailey gradue les dérivations frontales de 30° en 30° dans le sens horaire, D1 = 0°. L'axe varie avec la morphologie : cœur vertical (filiforme) ≈ 90°, horizontal (obèse, cardiomégalie) ≈ 0° (p. 375).\n**À relier** : axe anormal en cas d'hémibloc gauche ou d'anomalie ventriculaire marquée.\n**Piège** : isodiphasique = composantes + et - égales."},{"id":"231-qcm-503","type":"QRM","rank":"A","objective":"231-obj-01","tags":["repolarisation","piège"],"difficulty":2,"stem":"Concernant l'interprétation de la repolarisation, quelles propositions sont exactes ?","options":[{"t":"Chez l'homme jeune, un point J sus-décalé de V1 à V4 avec un ST jonctionnel ascendant peut correspondre à une repolarisation physiologique.","ok":true,"why":"Chez le jeune, surtout l'homme, un J sus-décalé V1-V4 avec ST ascendant vers la T est physiologique : ne pas le prendre pour un SCA (p. 377)."},{"t":"L'onde U doit être incluse dans la mesure du QT.","ok":false,"why":"Faux : l'onde U (2e onde de repolarisation, ex. hypoK) ne s'inclut jamais dans le QT (p. 377, 408)."},{"t":"Une onde T négative en aVR est pathologique.","ok":false,"why":"Faux : T normalement négative en aVR (et V1, parfois D3, aVL), car le QRS y est négatif (concordance) (p. 377)."},{"t":"Des ondes T négatives en D2 et D3 sont pathologiques.","ok":true,"why":"Deux T négatives dans un même territoire (D2 + D3 = inférieur) sont pathologiques (p. 411)."},{"t":"Des ondes T négatives dans toutes les précordiales sont pathologiques et doivent d'abord faire éliminer une ischémie.","ok":true,"why":"T négatives dans toutes les précordiales : pathologiques, difficiles à interpréter sans contexte ; 1re cause à éliminer = ischémie (fig. 15.24, p. 387)."}],"explanation":"T négative physiologique en aVR et V1 (parfois D3, aVL) ; deux T négatives dans un même territoire ou dans toutes les précordiales sont pathologiques. Le sus-décalage du point J V1-V4 du sujet jeune est une variante physiologique.","src":"p. 377, 387, 411","deep":"**Pourquoi** : les T sont positives partout sauf aVR et V1 (parfois D3, aVL) ; deux T négatives dans un même territoire (D2 + D3) ou dans toutes les précordiales sont pathologiques (éliminer d'abord une ischémie) (p. 377, 387, 411).\n**À relier** : chez le jeune, J sus-décalé V1-V4 avec ST ascendant = physiologique.\n**Piège** : l'onde U ne s'inclut jamais dans le QT."},{"id":"231-qcm-504","type":"QRM","rank":"B","objective":"231-obj-07","tags":["blocs de branche","bloc fonctionnel"],"difficulty":2,"stem":"Concernant les blocs de branche incomplets et fonctionnels, quelles propositions sont exactes ?","options":[{"t":"Un bloc fonctionnel n'existe qu'à partir d'une fréquence cardiaque donnée.","ok":true,"why":"Bloc fonctionnel : il n'apparaît qu'à partir d'une certaine FC, lors d'une tachycardie ou d'une bradycardie (p. 381)."},{"t":"Un bloc de branche fonctionnel peut n'apparaître que lors d'une tachycardie.","ok":true,"why":"Le bloc fonctionnel apparaît à partir d'une FC donnée, en tachycardie (ex. FA avec QRS larges) ou en bradycardie (p. 381, 393)."},{"t":"Un bloc incomplet reproduit les anomalies du bloc complet avec un QRS de 110 à 120 ms.","ok":true,"why":"Mêmes aspects en V1/V6 mais QRS 110-120 ms ; > 120 ms = complet (p. 381)."},{"t":"Le bloc incomplet a un intérêt sémiologique majeur.","ok":false,"why":"Faux : mêmes anomalies que le bloc complet avec QRS 110-120 ms, faible intérêt sémiologique ; un hémibloc isolé ou un bloc incomplet ne fait craindre qu'un faible risque de BAV (p. 381, 383)."},{"t":"Un bloc fonctionnel est présent quelle que soit la fréquence cardiaque.","ok":false,"why":"Faux : par définition il n'existe qu'à partir d'une certaine FC (tachycardie ou bradycardie) (p. 381)."}],"explanation":"Bloc incomplet : mêmes anomalies avec un QRS de 110-120 ms, faible intérêt sémiologique. Bloc fonctionnel : n'existe qu'à partir d'une fréquence donnée, en tachycardie ou en bradycardie.","src":"p. 380-381","deep":"**Pourquoi** : un bloc incomplet reproduit les anomalies du bloc complet avec un QRS de 110-120 ms (faible intérêt sémiologique) ; un bloc fonctionnel n'apparaît qu'à partir d'une certaine FC, en tachycardie ou en bradycardie (p. 380-381).\n**À relier** : bloc complet = QRS > 120 ms.\n**Piège** : un bloc fonctionnel n'est pas présent à toutes les fréquences."},{"id":"231-qcm-506","type":"QRM","rank":"A","objective":"231-obj-08","tags":["BAV","piège"],"difficulty":3,"stem":"Concernant la sémiologie des blocs atrioventriculaires, quelles propositions sont exactes ?","options":[{"t":"Une onde P « bloquée » survenant plus précocement que les autres signe un BAV2 Mobitz 2.","ok":false,"why":"Faux : une onde P bloquée plus précoce que les autres correspond en fait à une extrasystole atriale bloquée, à ne pas confondre avec un vrai BAV du 2e degré."},{"t":"Dans un BAV, les ondes P sont régulières et à fréquence normale.","ok":true,"why":"Le nœud sinusal fonctionne : P régulières à fréquence normale, c'est le passage AV qui fait défaut (P plus nombreuses que les QRS) (p. 385, 389)."},{"t":"Un BAV 2/1 à QRS fins avec des périodes de Mobitz 1 à d'autres moments oriente vers un siège suprahissien.","ok":true,"why":"QRS fins + Wenckebach à d'autres moments = BAV 2/1 probablement suprahissien (nodal) (fig. 15.20, p. 385)."},{"t":"Un BAV 2/1 avec des QRS larges oriente vers un siège suprahissien.","ok":false,"why":"Faux : un BAV 2/1 à QRS larges oriente vers un siège infrahissien ; c'est le BAV 2/1 à QRS fins, avec du Mobitz 1 à d'autres moments, qui oriente vers un siège suprahissien."},{"t":"Le BAV2 Mobitz 2 se caractérise par un allongement progressif du PR avant l'onde P bloquée.","ok":false,"why":"Faux : Mobitz 2 = PR constant puis P bloquée inopinée (infrahissien) ; l'allongement progressif = Mobitz 1 (p. 385)."}],"explanation":"Dans un BAV, les P sont régulières à fréquence normale. Le siège d'un BAV 2/1 s'oriente sur la largeur des QRS et l'existence de Mobitz 1 ; une P bloquée prématurée est une ESA bloquée.","src":"p. 385-386","deep":"**Pourquoi** : dans un BAV, les P sont régulières à fréquence normale. BAV 2/1 : QRS larges = infrahissien ; QRS fins avec du Mobitz 1 à d'autres moments = suprahissien (p. 385-386).\n**À relier** : Mobitz 1 = PR qui s'allonge puis P bloquée ; Mobitz 2 = PR constant puis P bloquée inopinée.\n**Piège** : une P « bloquée » plus précoce que les autres est une ESA bloquée."},{"id":"231-qcm-507","type":"QRM","rank":"A","objective":"231-obj-14","tags":["flutter","flutter atypique"],"difficulty":2,"stem":"Concernant les différentes formes de flutter atrial, quelles propositions sont exactes ?","options":[{"t":"Dans le flutter typique horaire, les ondes F sont négatives en D2, D3 et aVF comme dans la forme antihoraire.","ok":false,"why":"Faux : l'horaire tourne en sens inverse, toutes les polarités sont inversées (F positives en inférieur) (p. 394)."},{"t":"Les flutters gauches surviennent surtout après un remodelage ou une intervention.","ok":true,"why":"L'OG n'a pas de zone constitutionnellement propice : flutter gauche = remodelage par cardiopathie ou lésions d'intervention (p. 393)."},{"t":"La fréquence atriale d'un flutter atypique est toujours comprise entre 280 et 320/min.","ok":false,"why":"Faux : 120 à 320/min selon la longueur du circuit et la fibrose atriale ; ondes F de morphologies diverses (p. 394)."},{"t":"Les flutters droits sont beaucoup plus fréquents que les flutters gauches.","ok":true,"why":"L'OD a constitutionnellement des zones propices au flutter même sans cardiopathie ; les flutters gauches demandent un remodelage ou une intervention (p. 393)."},{"t":"Les flutters atypiques sont définis par un circuit passant par l'isthme cavotricuspide.","ok":false,"why":"Faux : c'est le flutter typique qui emprunte l'isthme cavotricuspide ; les flutters atypiques regroupent tous ceux dont le circuit n'inclut pas l'isthme (droits, gauches ou biatriaux)."}],"explanation":"Le flutter typique emprunte l'isthme cavotricuspide (antihoraire : F négatives en inférieur ; horaire : polarités inversées). Les flutters atypiques n'impliquent pas l'isthme et ont une fréquence de 120 à 320 bpm.","src":"p. 393-394","deep":"**Pourquoi** : typique = circuit par l'isthme cavotricuspide (antihoraire : F négatives en inférieur ; horaire : polarités inversées) ; atypique = sans l'isthme (droit, gauche ou biatrial), 120-320/min (p. 393-394).\n**À relier** : flutters droits ≫ gauches (zones propices dans l'OD même sans cardiopathie) ; flutters gauches après remodelage ou intervention.\n**Piège** : l'isthme définit le typique."},{"id":"231-qcm-508","type":"QRM","rank":"A","objective":"231-obj-02","tags":["tachycardie","algorithme","urgence"],"difficulty":2,"stem":"Devant une tachycardie (FC > 100 bpm), selon l'algorithme proposé, quelles propositions sont exactes ?","options":[{"t":"Une tachycardie régulière à QRS larges peut correspondre à une tachycardie supraventriculaire avec bloc de branche.","ok":true,"why":"Une TSV s'associe à des QRS larges en cas de trouble de conduction intraventriculaire (bloc de branche complet) ; c'est pourquoi l'origine ventriculaire n'est que « jusqu'à preuve du contraire »."},{"t":"Une tachycardie régulière à QRS larges est d'origine supraventriculaire jusqu'à preuve du contraire.","ok":false,"why":"Inversé : ventriculaire jusqu'à preuve du contraire, car une TV méconnue est mortelle (p. 398, 415)."},{"t":"Une tachycardie irrégulière oriente d'abord vers une fibrillation atriale, le diagnostic différentiel étant les extrasystoles atriales.","ok":true,"why":"Irrégulière = FA (RR non multiples d'une valeur commune) ; diagnostic différentiel : extrasystoles atriales (fig. 15.51, p. 405)."},{"t":"En cas de mauvaise tolérance hémodynamique, les manœuvres vagales doivent précéder toute cardioversion.","ok":false,"why":"Mauvaise tolérance hémodynamique → cardioversion électrique externe ; les manœuvres vagales sont réservées aux tachycardies bien tolérées."},{"t":"Les troubles du rythme supraventriculaire ont des QRS fins dans la majorité des cas","ok":true,"why":"Les TSV sont à QRS fins dans la majorité des cas ; ils ne sont larges qu'en cas de trouble de conduction intraventriculaire (ex. bloc de branche complet)."}],"explanation":"Irrégulière → FA ; régulière à QRS larges → TV jusqu'à preuve du contraire (ou TSV + bloc de branche) ; les TSV ont des QRS fins dans la majorité des cas. Mauvaise tolérance → cardioversion électrique externe.","src":"p. 405","deep":"**Pourquoi** : tachycardie = FC > 100 ; irrégulière = FA (diagnostic différentiel : ESA) ; régulière à QRS larges = TV jusqu'à preuve du contraire ; les TSV sont à QRS fins dans la majorité des cas (p. 405).\n**À relier** : mauvaise tolérance = cardioversion électrique externe ; bonne tolérance = manœuvres vagales ± adénosine.\n**Piège** : ne pars jamais d'une origine supraventriculaire par défaut devant des QRS larges."},{"id":"231-qcm-509","type":"QRM","rank":"A","objective":"231-obj-18","tags":["tachycardie ventriculaire","mécanisme"],"difficulty":2,"stem":"Concernant la tachycardie ventriculaire (TV), quelles propositions sont exactes ?","options":[{"t":"Elle naît au-dessus de la bifurcation hissienne.","ok":false,"why":"Faux : la TV naît sous la bifurcation hissienne, hors voies de conduction : propagation de proche en proche, QRS large (p. 398)."},{"t":"Elle peut évoluer vers une fibrillation atriale puis une asystolie.","ok":false,"why":"Faux : la TV, état électrique instable, dégénère en fibrillation ventriculaire (et non atriale), puis en asystolie du fait de l'anoxie cellulaire."},{"t":"Un QRS positif en aVR (axe extrême) est fréquent dans les blocs de branche banals.","ok":false,"why":"Un QRS positif en aVR ne se voit ni dans un BBD ni dans un BBG (axe extrême) : c'est un argument en faveur de la TV (fig. 15.46, p. 400, 402)."},{"t":"Sur cardiopathie, son mécanisme le plus fréquent est une réentrée autour d'une zone de fibrose post-infarctus.","ok":true,"why":"La réentrée est le mécanisme le plus fréquent sur cardiopathie, autour d'une zone de fibrose (nécrose d'infarctus ou cardiopathie) ; sur cœur sain, c'est l'automatisme anormal (p. 398-399)."},{"t":"Sur cœur sain, elle relève le plus souvent d'une réentrée intranodale.","ok":false,"why":"Faux : la réentrée intranodale est le mécanisme d'une tachycardie jonctionnelle (supraventriculaire) ; sur cœur sain, la TV relève le plus souvent d'un automatisme anormal."}],"explanation":"La TV naît sous la bifurcation hissienne (QRS larges), par réentrée sur fibrose ou automatisme anormal sur cœur sain ; elle peut dégénérer en FV puis asystolie. L'axe extrême (QRS positif en aVR) plaide en sa faveur.","src":"p. 398-400","deep":"**Pourquoi** : la TV naît sous la bifurcation hissienne : conduction de proche en proche = QRS large. Mécanisme : réentrée autour d'une fibrose sur cardiopathie ; automatisme anormal sur cœur sain. Elle dégénère en FV puis asystolie (p. 398-400).\n**À relier** : arguments : cardiopathie, concordance, QRS positif en aVR.\n**Piège** : la TV dégénère en FV (pas en FA) ; la réentrée intranodale est jonctionnelle."},{"id":"231-qcm-510","type":"QRM","rank":"B","objective":"231-obj-23","tags":["péricardite","évolution"],"difficulty":2,"stem":"Concernant l'évolution électrocardiographique d'une péricardite aiguë, quelles propositions sont exactes ?","options":[{"t":"En phase 2, les ondes T s'aplatissent partout, avec un ST isoélectrique.","ok":true,"why":"Phase 2 : le sus-ST disparaît (ST isoélectrique) et les T s'aplatissent dans toutes les dérivations (p. 409)."},{"t":"En phase 3, les ondes T deviennent négatives de façon persistante.","ok":true,"why":"Phase 3 : T négatives persistantes, avant le retour progressif à la normale (phase 4) (p. 409)."},{"t":"Devant un sus-décalage du ST, l'absence de miroir suffit à conclure à une péricardite plutôt qu'à un SCA ST+.","ok":false,"why":"Faux : le miroir peut manquer dans un SCA ST+ ; conclure à tort à une péricardite est un piège cité dans les points clés (p. 409, 415)."},{"t":"La phase 1, avec sus-décalage du ST, dure plusieurs semaines.","ok":false,"why":"Faux : la phase 1 (microvoltage, sus-décalage du ST concave et diffus sans miroir, sous-décalage de PQ) est brève."},{"t":"La phase 4 est marquée par l'apparition d'ondes Q de nécrose.","ok":false,"why":"Faux : la phase 4 correspond à un retour progressif à la normale ; les ondes Q de nécrose appartiennent à l'évolution d'un SCA avec sus-décalage du ST."}],"explanation":"La péricardite évolue en 4 phases : sus-ST bref, T plates avec ST isoélectrique, T négatives persistantes, puis normalisation. L'absence de miroir n'élimine pas à elle seule un SCA ST+.","src":"p. 409","deep":"**Pourquoi** : 4 phases : (1) brève : microvoltage, sus-ST concave diffus sans miroir, sous-décalage de PQ ; (2) T plates, ST iso ; (3) T négatives persistantes ; (4) retour à la normale (p. 409).\n**Astuce** : ST+ → T plate → T négative → normale.\n**Piège** : l'absence de miroir peut exister dans un SCA ST+ : elle ne suffit pas à conclure à une péricardite."},{"id":"231-qcm-511","type":"QRM","rank":"A","objective":"231-obj-24","tags":["SCA","onde Q","séquelles"],"difficulty":2,"stem":"Concernant les ondes Q de nécrose et l'évolution de l'ECG après un SCA avec sus-décalage du ST, quelles propositions sont exactes ?","options":[{"t":"Après 48 heures apparaît une onde T négative « ischémique », parfois très prolongée.","ok":true,"why":"Évolution normale après 48 h : T négative « ischémique », parfois très longtemps ; si le sus-ST persiste, penser anévrisme (p. 412)."},{"t":"Les ondes Q de nécrose apparaissent en principe vers le 6e jour.","ok":false,"why":"Faux : vers la 6e heure (parfois plus tôt) ; elles ne contre-indiquent pas la reperfusion (p. 412)."},{"t":"Un sus-décalage du ST persistant indéfiniment doit faire évoquer un anévrisme de la paroi infarcie.","ok":true,"why":"Sus-ST : régresse vite si reperfusion, dure plusieurs jours sinon, persiste indéfiniment si la paroi évolue en anévrisme (p. 412)."},{"t":"La présence d'ondes Q signifie qu'une reperfusion est devenue inutile.","ok":false,"why":"Faux : les Q (vers la 6e heure, parfois plus tôt) ne doivent pas faire juger la reperfusion trop tardive (p. 412)."},{"t":"Les ondes Q de nécrose peuvent être remplacées par un écrêtement (rabotage) de l'onde R, surtout décrit en V2-V3-V4.","ok":true,"why":"Le Collège (p. 412) précise que les ondes Q peuvent être remplacées par un écrêtement ou rabotage de l'onde R, surtout décrit en V2-V3-V4."}],"explanation":"Ondes Q vers la 6e heure (sans remettre en cause la reperfusion), rabotage de R comme équivalent, T négative ischémique après 48 h, sus-ST persistant en cas d'anévrisme.","src":"p. 411-412","deep":"**Pourquoi** : les Q de nécrose apparaissent vers la 6e heure (au moins 1/3, ou 1/4, du QRS en amplitude, > 30-40 ms ; la p. 377 donne > 40 ms et > 1/3 du QRS : deux versions dans le Collège) et ne signifient pas qu'une reperfusion est inutile ; elles peuvent être remplacées par un rabotage de R (surtout V2-V3-V4) (p. 411-412).\n**À relier** : sus-ST : régresse vite après reperfusion, plusieurs jours sans reperfusion, indéfini si anévrisme ; après 48 h, T négative « ischémique ».\n**Piège** : 6e heure, pas 6e jour."},{"id":"231-qcm-512","type":"QRM","rank":"B","objective":"231-obj-26","tags":["prothèses rythmiques","stimulation"],"difficulty":2,"stem":"Concernant les prothèses rythmiques cardiaques et leur aspect ECG, quelles propositions sont exactes ?","options":[{"t":"Un spike de stimulation bipolaire est habituellement plus visible qu'un spike unipolaire.","ok":false,"why":"Inversé : unipolaire (sonde-boîtier, pôles éloignés) bien visible ; bipolaire (pôles proches) peu visible (p. 414)."},{"t":"Le défibrillateur agit en stimulant localement quelques myocytes.","ok":false,"why":"Faux : il délivre un champ électrique qui réinitialise tous les myocytes ; la stimulation locale est le principe du pacemaker (fig. 15.60, p. 413)."},{"t":"La resynchronisation cardiaque est indiquée pour un BBG désynchronisant le VG avec insuffisance cardiaque.","ok":true,"why":"Le BBG active tardivement la paroi latérale : désynchronisation qui crée ou aggrave une IC ; la resynchronisation la corrige (p. 383, 413)."},{"t":"En stimulation atriale pour dysfonction sinusale, une onde P suit le spike.","ok":true,"why":"Le nœud sinusal fait défaut : le pacemaker stimule l'oreillette, d'où une P après le spike (p. 414)."},{"t":"Un défibrillateur assure toujours une fonction de pacemaker, sauf s'il est sous-cutané.","ok":true,"why":"Défibrillateur = toujours pacemaker (sauf sous-cutané) ; la resynchronisation est elle aussi un stimulateur (p. 413)."}],"explanation":"Pacemaker : stimulation locale ; défibrillateur : champ électrique global (fait aussi pacemaker, sauf sous-cutané) ; resynchronisation : BBG désynchronisant avec IC. Le spike unipolaire est plus visible que le bipolaire.","src":"p. 413-414","deep":"**Pourquoi** : pacemaker = stimulation locale de quelques myocytes puis conduction de proche en proche ; défibrillateur = champ électrique qui réinitialise tous les myocytes (fait aussi pacemaker, sauf sous-cutané) ; resynchronisation = BBG qui désynchronise le VG avec IC (p. 413-414).\n**À relier** : unipolaire = spike bien visible ; bipolaire = peu visible.\n**Piège** : inverser unipolaire/bipolaire ou pacemaker/défibrillateur."},{"id":"231-qcm-513","type":"QRM","rank":"A","objective":"231-obj-27","tags":["indications","monitorage"],"difficulty":1,"stem":"Parmi les situations suivantes, lesquelles sont citées comme indications d'un monitorage ECG continu (cardioscope) ?","options":[{"t":"Documentation de palpitations survenant quelques fois par mois chez un patient ambulatoire.","ok":false,"why":"Faux : symptômes rares = ECG ambulatoire jusqu'à 21 jours, enregistreurs d'événements, voire holter implantable (p. 415)."},{"t":"Transfert médicalisé.","ok":true,"why":"Urgences, réanimation et transferts médicalisés relèvent du monitorage continu (cardioscope) (p. 414)."},{"t":"Syncope avec cause rythmique suspectée.","ok":true,"why":"Une syncope d'origine rythmique suspectée justifie un monitorage continu pour capter l'arythmie (p. 414)."},{"t":"Bilan préopératoire systématique d'un patient de plus de 65 ans.","ok":false,"why":"Faux : c'est une indication de l'ECG 12 dérivations ponctuel ; le monitorage se fait en peropératoire et en salle de réveil (p. 414)."},{"t":"Enquête familiale d'une cardiopathie héréditaire.","ok":false,"why":"Faux : enquête familiale = ECG conventionnel 12 dérivations, pas monitorage (p. 414)."}],"explanation":"Le cardioscope s'utilise en urgence, réanimation, transfert médicalisé, soins intensifs cardiologiques, syncope d'origine rythmique suspectée, peropératoire/réveil et certaines séances de réadaptation.","src":"p. 414-415","deep":"**Pourquoi** : le cardioscope s'utilise en urgence/réanimation/transferts médicalisés, soins intensifs cardio (SCA), syncope à cause rythmique suspectée, peropératoire et réveil, certaines séances de réadaptation (p. 414-415).\n**À relier** : bilan préopératoire > 65 ans et enquêtes familiales = ECG 12 dérivations ; symptômes rares = ECG de longue durée ou enregistreurs d'événements.\n**Piège** : ne pas confondre monitorage continu et ECG ponctuel."},{"id":"231-qcm-514","type":"QRM","rank":"B","objective":"231-obj-28","tags":["Holter","examens complémentaires"],"difficulty":2,"stem":"Concernant la méthode Holter et les enregistrements ECG de longue durée, quelles propositions sont exactes ?","options":[{"t":"Le Holter implantable est indiqué dans les syncopes inexpliquées et la recherche de FA silencieuse.","ok":true,"why":"Holter sous-cutané : jusqu'à 3 ans, pour le diagnostic étiologique des syncopes inexpliquées ou d'une FA silencieuse (p. 415)."},{"t":"La lecture du Holter se fait en temps réel, pendant l'enregistrement.","ok":false,"why":"Faux : enregistrement numérique avec analyse différée (centre de lecture) ; le temps réel, c'est le monitorage (p. 414-415)."},{"t":"Le Holter enregistre 2 à 12 dérivations simultanées.","ok":true,"why":"Holter = 2 à 12 dérivations simultanées pendant 24 à 96 h maximum (p. 415)."},{"t":"Il permet d'évaluer le risque rythmique, par exemple des salves de TV asymptomatiques après infarctus.","ok":true,"why":"Détecter des salves de TV asymptomatiques après infarctus ou dans les cardiomyopathies évalue le risque rythmique (p. 415)."},{"t":"Un Holter de 24 h peut servir à évaluer l'efficacité d'un traitement bradycardisant.","ok":true,"why":"Le Holter 24 h sert aussi à juger l'efficacité des bradycardisants et à surveiller/régler les pacemakers (p. 415)."}],"explanation":"Le Holter (2-12 dérivations, 24-96 h, lecture différée) documente des symptômes épisodiques, contrôle les bradycardisants et les pacemakers et évalue le risque rythmique ; le Holter implantable couvre jusqu'à 3 ans.","src":"p. 415","deep":"**Pourquoi** : le Holter enregistre 2 à 12 dérivations pendant 24-96 h, lecture différée ; indiqué pour malaises, syncopes, palpitations épisodiques quand l'ECG standard n'a rien montré et que les symptômes peuvent se répéter (p. 415).\n**À relier** : efficacité des bradycardisants, réglage des pacemakers, risque rythmique (salves de TV asymptomatiques) ; implantable jusqu'à 3 ans.\n**Piège** : lecture en différé, pas en temps réel."},{"id":"231-qcm-515","type":"QRM","rank":"B","objective":"231-obj-06","tags":["axe","hémibloc","piège"],"difficulty":3,"stem":"Un ECG montre un QRS négatif en D1. Quelles propositions sont exactes ?","options":[{"t":"Une hypertrophie ventriculaire droite s'accompagne d'une déviation axiale gauche.","ok":false,"why":"Faux : le signe le plus précoce d'HVD est un axe droit (> 110°, 90° en pratique), d'où un D1 négatif possible (p. 407)."},{"t":"L'hémibloc postérieur gauche est fréquent car sa branche est superficielle et fine.","ok":false,"why":"Faux : c'est l'HBAG qui est fréquent (branche superficielle, fine) ; l'HBPG est rare (branche profonde) (p. 383)."},{"t":"Il faut d'abord évoquer un hémibloc postérieur gauche, l'inversion des électrodes étant exceptionnelle.","ok":false,"why":"Faux : le premier diagnostic devant un D1 négatif est une inversion de positionnement des électrodes frontales (l'onde P est alors aussi négative en D1), avant l'HBPG qui est rare."},{"t":"Au cours d'une embolie pulmonaire, un aspect S1Q3T3 peut s'associer à une déviation axiale droite.","ok":true,"why":"La surcharge aiguë du VD de l'EP donne axe droit et S1Q3T3 (fig. 15.54, p. 407-408)."},{"t":"L'hémibloc postérieur gauche ne se retient qu'en l'absence de pathologie du VD, de morphologie longiligne ou d'infarctus latéral.","ok":true,"why":"Ces situations donnent le même axe droit : l'HBPG est un diagnostic d'exclusion (p. 382, 407)."}],"explanation":"Devant un D1 négatif : éliminer d'abord une inversion d'électrodes, puis discuter HBPG (rare, diagnostic d'exclusion), HVD, morphologie longiligne ou embolie pulmonaire (S1Q3T3).","src":"p. 382, 407","deep":"**Pourquoi** : devant un D1 négatif, d'abord une inversion des électrodes frontales (P aussi négative en D1) ; ensuite HBPG (rare, d'exclusion), HVD (axe droit), morphologie longiligne, EP (S1Q3T3) (p. 382, 407).\n**À relier** : HBAG fréquent (branche superficielle, fine), HBPG rare (profonde).\n**Piège** : l'HBPG ne se retient qu'en l'absence de pathologie du VD, de morphologie longiligne et d'infarctus latéral."},{"id":"231-qru-501","type":"QRU","rank":"B","objective":"231-obj-04","tags":["HVD"],"difficulty":2,"stem":"Quel est le signe électrocardiographique le plus précoce d'une hypertrophie ventriculaire droite ?","options":[{"t":"Un indice de Sokolow ≥ 35 mm.","ok":false,"why":"Sokolow ≥ 35 mm signe une HVG, pas une HVD (p. 406)."},{"t":"Un microvoltage.","ok":false,"why":"Le microvoltage accompagne souvent l'HVD du BPCO mais n'est pas le signe le plus précoce, qui est l'axe droit (p. 407)."},{"t":"Une déviation axiale droite (axe > 110°, 90° en pratique).","ok":true,"why":"Le Collège fait de l'axe droit (> 110°, 90° en pratique) le signe le plus précoce, avant R > 6 mm en V1 et S > 7 mm en V5-V6 (p. 407)."},{"t":"Une onde R > 6 mm en V1.","ok":false,"why":"Critère d'HVD, mais il vient après la déviation axiale droite (p. 407)."},{"t":"Une onde T négative asymétrique en V1.","ok":false,"why":"Signe des formes sévères (V1, parfois V2-V3), piège à ne pas prendre pour une ischémie ; pas un signe précoce (p. 407)."}],"explanation":"Signe le plus précoce d'HVD : axe > 110° (90° en pratique) ; autres signes : R > 6 mm en V1, S > 7 mm en V5-V6, HAD, microvoltage (BPCO), T négative en V1 dans les formes sévères.","src":"p. 407","deep":"**Pourquoi** : le signe le plus précoce de l'HVD est la déviation axiale droite du QRS > 110° (90° en pratique) (p. 407).\n**À relier** : puis R > 6 mm en V1, S > 7 mm en V5-V6, HAD, microvoltage chez le BPCO, T négative asymétrique en V1 dans les formes sévères.\n**Piège** : Sokolow = HVG."},{"id":"231-qru-503","type":"QRU","rank":"A","objective":"231-obj-05","tags":["HVG"],"difficulty":2,"stem":"Dans l'hypertrophie ventriculaire gauche, quelle est habituellement la durée des QRS ?","options":[{"t":"Un peu élargis mais le plus souvent inférieurs à 120 ms.","ok":true,"why":"La masse à dépolariser et la fibrose retardent un peu la conduction, mais le QRS reste le plus souvent < 120 ms (p. 406)."},{"t":"Variables « en accordéon » d'un battement à l'autre.","ok":false,"why":"QRS larges de taille variable « en accordéon » = FA conduite par une voie accessoire (super-Wolff) (p. 411)."},{"t":"Toujours inférieurs à 70 ms.","ok":false,"why":"Faux : < 70 ms serait sous la norme (70-110 ms) ; l'HVG tend au contraire à élargir un peu le QRS (p. 375, 406)."},{"t":"Constamment supérieurs à 120 ms, par définition.","ok":false,"why":"Faux : QRS un peu élargi mais le plus souvent < 120 ms ; > 120 ms fait chercher un bloc de branche (p. 406)."},{"t":"Supérieurs à 160 ms avec aspect RsR' en V1.","ok":false,"why":"QRS large + RsR' en V1 = BBD complet, pas HVG (p. 378)."}],"explanation":"Dans l'HVG, les QRS sont un peu élargis (masse, fibrose) mais restent le plus souvent < 120 ms, avec une déviation axiale gauche modeste.","src":"p. 406","deep":"**Pourquoi** : dans l'HVG, la masse myocardique élevée et la fibrose peuvent élargir un peu le QRS, mais il reste le plus souvent < 120 ms ; l'axe dévie modestement à gauche (p. 406).\n**À relier** : forme sévère : T négative + ST sous-décalé en latéral.\n**Piège** : QRS « en accordéon » = FA préexcitée ; RsR' + QRS large = BBD."},{"id":"231-qroc-501","type":"QROC","rank":"A","objective":"231-obj-01","tags":["dérivations","activité atriale"],"difficulty":3,"question":"Avec les dérivations de Lewis, dans quelle dérivation l'activité atriale est-elle bien lue ?","answer":"D1","accept":["dérivation D1","DI","dérivation I"],"keywords":["D1"],"explanation":"Avec les dérivations de Lewis (rouge sur la fourchette sternale, jaune au 5e EIC droit), l'activité atriale se lit en D1 (p. 373).","src":"p. 373","deep":"**Pourquoi** : pour voir une activité atriale cachée, on déplace les électrodes (rouge sur la fourchette sternale, jaune au 5e EIC droit) : l'activité atriale se lit alors bien en D1 (p. 373).\n**À relier** : autre aide : manœuvres vagales.\n**Piège** : la dérivation de lecture est D1, pas V1."},{"id":"231-qroc-504","type":"QROC","rank":"A","objective":"231-obj-17","tags":["extrasystoles"],"difficulty":1,"question":"Comment nomme-t-on la succession rythmée d'un battement normal et d'une extrasystole (1 battement sur 2) ?","answer":"Bigéminisme","accept":["bigéminisme extrasystolique","bigeminisme","bigéminisme","un bigéminisme"],"keywords":["bigemin"],"explanation":"Extrasystole un battement sur deux = bigéminisme, un sur trois = trigéminisme ; doublet, triplet, salve = formes répétitives (p. 398).","src":"p. 398","deep":"**Pourquoi** : extrasystoles rythmées : 1 battement sur 2 = bigéminisme ; 1 sur 3 = trigéminisme (p. 398).\n**À relier** : répétitives = doublets, triplets, salves.\n**Piège** : un doublet (2 ESV de suite) n'est pas un bigéminisme."},{"id":"231-qroc-506","type":"QROC","rank":"A","objective":"231-obj-24","tags":["sus-décalage ST","séquelles"],"difficulty":2,"question":"Quelle complication doit évoquer un sus-décalage du ST persistant indéfiniment après un infarctus ?","answer":"Anévrisme ventriculaire","accept":["anévrisme de la paroi infarcie","anévrisme du VG","anévrisme","anévrisme ventriculaire","anévrisme du ventricule gauche"],"keywords":["anevrism"],"explanation":"Le sus-ST régresse vite avec la reperfusion, dure quelques jours sans ; persistant indéfiniment = anévrisme de la paroi infarcie (une des 5 étiologies de sus-ST) (p. 412).","src":"p. 411-412","deep":"**Pourquoi** : le sus-ST régresse vite avec la reperfusion et dure plusieurs jours sans reperfusion ; s'il persiste indéfiniment, la paroi infarcie a évolué en anévrisme ventriculaire (p. 411-412).\n**À relier** : une des 5 étiologies de sus-ST.\n**Piège** : après 48 h, l'évolution normale est une T négative ischémique, pas un sus-ST."},{"id":"231-qroc-507","type":"QROC","rank":"B","objective":"231-obj-04","tags":["HVD"],"difficulty":2,"question":"Quelle amplitude de l'onde R en V1 constitue un critère d'hypertrophie ventriculaire droite ?","answer":"Supérieure à 6 mm","accept":["> 6 mm","plus de 6 mm","R > 6 mm","6 mm","supérieure à 6 mm"],"keywords":["6 mm"],"explanation":"HVD : axe droit (signe le plus précoce), R > 6 mm en V1, S > 7 mm en V5-V6 ; BBD souvent associé (p. 407).","src":"p. 407","deep":"**Pourquoi** : en HVD, R ample > 6 mm en V1 et S ample > 7 mm en V5-V6, après le signe précoce (axe > 110°) (p. 407).\n**À relier** : HAD et microvoltage chez le BPCO, BBD fréquent.\n**Piège** : R en V1 (HVD) vs S en V1 (Sokolow, HVG)."},{"id":"231-qroc-508","type":"QROC","rank":"A","objective":"231-obj-27","tags":["dérivations","SCA"],"difficulty":1,"question":"Quelles sont les deux dérivations droites qui complètent les précordiales chez l'enfant ou en cas de suspicion de SCA ?","answer":"V3R et V4R","accept":["V3R V4R","V3R-V4R","V3R, V4R","V3R + V4R","V4R et V3R"],"keywords":["V3R","V4R"],"explanation":"Les précordiales V1 à V9 sont complétées par V3R et V4R (dérivations droites) chez l'enfant ou en cas de suspicion de SCA (p. 371) ; le VD est exploré par V1, V2, V3R et V4R (p. 374).","src":"p. 371","deep":"**Pourquoi** : les précordiales V1 à V9 se complètent par V3R et V4R (droites) chez l'enfant ou en cas de suspicion de SCA (p. 371, 374).\n**À relier** : le VD est exploré par V1, V2, V3R, V4R (p. 374) ; le postérieur par V7-V9, dont un sous-ST V1-V3 peut être le miroir (p. 374, 411).\n**Piège** : ne confonds pas V3R-V4R (droites) et V7-V9 (postérieures)."},{"id":"231-qroc-509","type":"QROC","rank":"B","objective":"231-obj-16","tags":["manœuvres vagales"],"difficulty":1,"question":"Quelle manœuvre vagale consiste en une expiration forcée à glotte fermée ?","answer":"Manœuvre de Valsalva","accept":["Valsalva","manœuvre de Valsalva","le Valsalva"],"keywords":["valsalva"],"explanation":"Valsalva = expiration forcée glotte fermée ; autres manœuvres : compression carotidienne unilatérale (CI athérome/souffle), grand verre d'eau froide (p. 390).","src":"p. 390","deep":"**Pourquoi** : les manœuvres vagales intensifient le filtre du NAV : Valsalva = expiration forcée glotte fermée (p. 390).\n**À relier** : compression carotidienne unilatérale (CI athérome/souffle), eau froide ; compression oculaire plus recommandée.\n**Piège** : le Valsalva est une expiration forcée à glotte FERMÉE."},{"id":"231-qroc-601","type":"QROC","rank":"A","objective":"231-obj-27","tags":["urgence","biologie"],"difficulty":2,"question":"Quels sont les deux ions dont les troubles justifient la réalisation d'un ECG en urgence ?","answer":"Le potassium et le calcium (dyskaliémies, dyscalcémies)","accept":["dyskaliémie et dyscalcémie","potassium et calcium","K et Ca","kaliémie et calcémie"],"keywords":["kali","calc"],"explanation":"Parmi les principales indications de l'ECG en urgence figurent les défaillances d'organe, la douleur thoracique, les palpitations, la syncope et les troubles hydroélectrolytiques portant sur le potassium et le calcium.","src":"p. 368","deep":"**Pourquoi** : K et Ca sont les deux ions dont les troubles modifient directement l'ECG et peuvent donner des arythmies graves : hypoK = T plate, onde U, QT long, TV/torsade ; hyperK = T pointue, PR et QRS élargis, BAV (p. 408) ; hypocalcémie = QT long (p. 404).\n**Piège** : le tableau d'objectifs cite K et Ca ; le magnésium allonge aussi le QT (p. 404) mais n'est pas dans cette liste d'indications urgentes.\n**À relier** : les 4 autres indications urgentes : défaillance d'organe, douleur thoracique, palpitations, syncope (p. 368)."},{"id":"231-qroc-602","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Pourquoi le QRS est-il large dans une tachycardie ventriculaire ou lors d'une stimulation ventriculaire par pacemaker ?","answer":"L'influx se propage de proche en proche, hors du réseau spécialisé","accept":["de proche en proche","conduction lente de proche en proche","hors du réseau de conduction","conduction de proche en proche"],"keywords":["proche"],"explanation":"Une TV naît sous la bifurcation hissienne et un pacemaker stimule directement le ventricule : l'influx ne passe pas par le réseau de conduction (NAV, His, branches, Purkinje) et se propage lentement de proche en proche, ce qui élargit le QRS.","src":"p. 398, 414","deep":"**Pourquoi** : une TV naît sous la bifurcation hissienne et une sonde stimule directement le ventricule : l'influx n'emprunte pas les voies de conduction (NAV, His, branches, Purkinje) et avance lentement de proche en proche, d'où un QRS large (p. 398, 414).\n**Piège** : l'ESV donne aussi un QRS large prématuré (p. 397) : un QRS large ne dit pas à lui seul « bloc » ou « TV » ; devant une tachycardie régulière à QRS larges, c'est une TV jusqu'à preuve du contraire (p. 398).\n**À relier** : stimulation du VD → QRS large d'aspect BBG après le spike (p. 414)."},{"id":"231-qroc-603","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":1,"question":"Quelles sont les quatre dérivations qui explorent le territoire latéral du ventricule gauche (deux hautes, deux basses) ?","answer":"D1 et aVL (hautes), V5 et V6 (basses)","accept":["D1, aVL, V5, V6","D1 aVL V5 V6","DI, aVL, V5, V6","DI aVL V5 V6","D1 et aVL, V5 et V6"],"keywords":["avl","v5","v6"],"explanation":"Les dérivations latérales sont D1 et aVL (latérales hautes) et V5, V6 (latérales basses) ; les inférieures sont D2, D3 et aVF, les antéroseptales V1 à V3, l'apicale V4.","src":"p. 374","deep":"**Pourquoi** : chaque dérivation « regarde » la paroi en face de son électrode : D1-aVL voient le latéral haut, V5-V6 le latéral bas (p. 374).\n**Piège** : aVL est latéral haut, pas inférieur (inférieur = D2, D3, aVF) ; V4 est apical, pas latéral.\n**À relier** : le latéral est le territoire des anomalies de l'HVG sévère (T négative + ST sous-décalé, p. 406) et du notch du BBG (V6, D1, aVL, p. 380)."},{"id":"231-qroc-604","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":1,"question":"Quelle est la durée normale de l'onde P, en pratique ?","answer":"Moins de 120 ms","accept":["< 120 ms","inférieure à 120 ms","120 ms","moins de 120 ms"],"keywords":["120"],"explanation":"Dans un ECG normal, l'onde P dure moins de 120 ms (110 ms en théorie), avec une amplitude < 2,5 mm en D2 ; le PR normal est de 120 à 200 ms.","src":"p. 375, 377","deep":"**Pourquoi** : la P représente la dépolarisation des deux oreillettes : sa durée théorique est < 110 ms, arrondie en pratique à 120 ms ; amplitude < 2,5 mm en D2 (tableau 15.2, p. 375).\n**Piège** : ne confonds pas durée et amplitude : la durée allongée oriente vers l'oreillette GAUCHE (HAG, P > 110-120 ms), l'amplitude > 2,5 mm en D2 vers la DROITE (HAD) (p. 406, rang B).\n**À relier** : PR normal 120-200 ms, du début de P au début du QRS (p. 376)."},{"id":"231-qroc-605","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG"],"difficulty":1,"question":"Quelle formule permet de calculer la fréquence cardiaque à partir de l'intervalle RR exprimé en secondes ?","answer":"FC = 60 / période (intervalle RR)","accept":["60/RR","60 / RR","60 divisé par l'intervalle RR","60/période","FC = 60/RR"],"keywords":["60"],"explanation":"La période est l'intervalle RR (entre deux QRS) en secondes et FC = 60 / période. En pratique, FC = 300 / nombre de grands carreaux séparant deux QRS.","src":"p. 376","deep":"**Pourquoi** : la période est l'intervalle RR en secondes ; 60 s divisées par la durée d'un cycle donnent le nombre de battements par minute (p. 376).\n**Piège** : le RR doit être en secondes ; au lit du malade, plus rapide : FC = 300 / nombre de grands carreaux entre deux QRS (1 grand carreau = 200 ms à 25 mm/s, p. 375-376).\n**À relier** : même RR en secondes dans la formule de Bazett du QTc (p. 377)."},{"id":"231-qroc-606","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","physiopathologie"],"difficulty":1,"question":"Pourquoi les athlètes présentent-ils souvent une bradycardie sinusale physiologique ?","answer":"Un tonus vagal important","accept":["tonus vagal","tonus parasympathique important","hypertonie vagale","tonus parasympathique","tonus vagal important","hypervagotonie"],"keywords":["vagal"],"explanation":"La fréquence du nœud sinusal dépend du tonus sympathique et parasympathique : le tonus vagal important de l'athlète explique sa bradycardie sinusale physiologique, et la fréquence sinusale du sujet jeune peut varier avec la respiration.","src":"p. 376","deep":"**Pourquoi** : la fréquence du nœud sinusal est modulée par les tonus sympathique et parasympathique : le tonus vagal important de l'athlète abaisse physiologiquement sa fréquence sinusale (p. 376).\n**Piège** : une bradycardie sinusale de l'athlète n'est pas une dysfonction sinusale ; de même, la variation de fréquence avec la respiration chez le jeune est physiologique (p. 376).\n**À relier** : bradycardie = FC < 60 bpm ; normale 60-100 bpm chez l'adulte (attention au nouveau-né) (p. 376)."},{"id":"231-qroc-607","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG"],"difficulty":2,"question":"Quel aspect présente le QRS en V6 dans un bloc complet de branche droite ?","answer":"Un aspect qRs avec onde S traînante, arrondie","accept":["onde S traînante","S traînante","S traînante arrondie","qRs avec S traînante","qRs"],"keywords":["traîn"],"explanation":"Le BBD complet associe un QRS > 120 ms, un QRS globalement positif en V1 avec aspect RsR' et, en V6, un aspect qRs avec onde S traînante, le plus souvent arrondie.","src":"p. 378","deep":"**Pourquoi** : dans le BBD, le VD est activé en retard par la gauche : la fin du QRS est orientée vers la droite, d'où S large et traînante en V6 (aspect qRs) et QRS positif RsR' en V1, avec QRS > 120 ms (p. 378).\n**Piège** : le notch (double pic) en V6, D1, aVL est le signe du BBG, pas du BBD (p. 380).\n**À relier** : règle rapide : V1 positif = BBD, V1 négatif = BBG, aspect inverse en V6 (p. 381)."},{"id":"231-qroc-608","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG"],"difficulty":1,"question":"Comment nomme-t-on le double pic du QRS observé en V6, D1 et aVL dans un bloc complet de branche gauche ?","answer":"Un notch","accept":["notch","le notch","encoche"],"keywords":["notch"],"explanation":"Dans le BBG complet, le QRS est négatif en V1 (rS ou QS) et présente en V6, D1 et aVL un notch (double pic : activation du septum puis de la paroi latérale tardive), avec le plus souvent une onde R exclusive.","src":"p. 380","deep":"**Pourquoi** : le BBG retarde l'activation de la paroi latérale : 1er pic = septum, 2e pic = paroi latérale tardive, d'où le notch en V6, D1, aVL, souvent avec R exclusive (p. 380).\n**Piège** : le notch se cherche en latéral (V6, D1, aVL), pas en V1 où le QRS du BBG est négatif (rS ou QS).\n**À relier** : BBG + douleur thoracique persistante = penser infarctus antérieur, avis cardiologique rapide sans attendre la troponine (p. 381)."},{"id":"231-qroc-609","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","pièges"],"difficulty":2,"question":"Quelle déviation axiale caractérise l'hémibloc postérieur gauche ?","answer":"Une déviation axiale droite au-delà de +90° (aspect S1Q3)","accept":["axe droit","déviation axiale droite","déviation à droite","au-delà de +90°","axe > 90°"],"keywords":["droit"],"explanation":"L'HBPG, rare car la branche postérieure est profonde, donne une déviation axiale du QRS à droite (> +90°, négativité en D1), à condition d'éliminer une pathologie du ventricule droit, une morphologie longiligne ou un infarctus latéral. Devant un D1 négatif, on pense d'abord à une inversion des électrodes frontales.","src":"p. 382-383","deep":"**Pourquoi** : l'hémibranche postérieure bloquée, l'activation part par l'antérieure et finit vers le bas et la droite : axe > +90°, D1 négatif (S1Q3) (p. 382).\n**Piège** : avant de parler d'HBPG, pense d'abord à une inversion des électrodes frontales (la P est alors aussi négative en D1) ; il faut aussi exclure atteinte du VD, morphologie longiligne, infarctus latéral (p. 382-383).\n**À relier** : HBAG = axe au-delà de -30° (D2 négatif), fréquent car branche fragile ; HBPG rare car branche profonde (p. 382-383)."},{"id":"231-qroc-611","type":"QROC","rank":"A","objective":"231-obj-08","tags":["ECG"],"difficulty":2,"question":"Quel aspect caractérise le bloc atrioventriculaire du 2e degré de type Mobitz 2 ?","answer":"PR constant, puis une onde P bloquée de façon inopinée","accept":["PR constant puis onde P bloquée","onde P bloquée inopinée","onde P bloquée brutale","PR constant puis P bloquée","P bloquée inopinée","PR fixe puis P bloquée"],"keywords":["constant","puis"],"explanation":"Dans le Mobitz 2, le PR reste constant puis une onde P est bloquée de façon inopinée, contrairement au Mobitz 1 où le PR s'allonge progressivement ; ce bloc est de siège infrahissien.","src":"p. 385","deep":"**Pourquoi** : dans le Mobitz 2, le PR reste constant, sans allongement préalable, jusqu'à une P bloquée inopinée ; siège infrahissien (fig. 15.20, p. 385).\n**Piège** : le Mobitz 1 (Wenckebach) allonge progressivement le PR avant la P bloquée et est suprahissien (p. 385).\n**À relier** : Mobitz 2 et BAV3 = BAV infrahissiens, indication de pacemaker même sans symptôme (p. 412, rang B)."},{"id":"231-qroc-612","type":"QROC","rank":"A","objective":"231-obj-08","tags":["ECG"],"difficulty":3,"question":"Dans un BAV 2/1, quel aspect des QRS oriente vers un siège infrahissien ?","answer":"Des QRS larges","accept":["QRS larges","QRS élargis","QRS larges (élargis)"],"keywords":["larges"],"explanation":"Dans un BAV 2/1, des QRS larges orientent vers un siège infrahissien ; des QRS fins, surtout s'il existe du Mobitz 1 à d'autres moments, orientent vers un siège suprahissien.","src":"p. 385","deep":"**Pourquoi** : un QRS large signe une atteinte de la conduction sous le His (branches) : dans un BAV 2/1, il oriente vers un siège infrahissien ; QRS fins + Mobitz 1 à d'autres moments → suprahissien (p. 385).\n**Piège** : le BAV 2/1 peut être supra- OU infrahissien : on ne peut pas le classer sur le seul rapport 2/1, il faut la largeur des QRS et le reste du tracé.\n**À relier** : même logique pour le BAV3 : échappement à QRS fins = bloc nodal suprahissien (p. 387)."},{"id":"231-qroc-613","type":"QROC","rank":"A","objective":"231-obj-13","tags":["ECG","définition"],"difficulty":2,"question":"Que signifie le terme « irrégulièrement irréguliers » pour les QRS d'une fibrillation atriale ?","answer":"Les intervalles RR ne sont pas multiples d'une valeur commune","accept":["RR non multiples","pas multiples d'une valeur commune","intervalles RR non multiples","RR non multiples d'une valeur commune"],"keywords":["multiple"],"explanation":"Dans la FA, tachycardie entre 100 et 200/min, les QRS sont « irrégulièrement irréguliers » : les intervalles RR ne sont pas multiples d'une valeur commune ; en l'absence de trouble de conduction, les QRS sont fins.","src":"p. 392","deep":"**Pourquoi** : l'activation atriale de la FA est anarchique (p. 391) : les QRS n'ont aucun motif répétitif, les RR ne sont pas multiples d'une valeur commune (p. 392).\n**Piège** : si les QRS deviennent lents et RÉGULIERS sur une FA, pense à une FA + BAV complet (échappement régulier) (p. 392, rang B) ; une ESA est le diagnostic différentiel d'une tachycardie irrégulière (p. 405).\n**À relier** : la FA est le seul diagnostic devant une tachycardie complètement irrégulière à QRS fins (points clés, p. 415)."},{"id":"231-qroc-614","type":"QROC","rank":"B","objective":"231-obj-11","tags":["ECG"],"difficulty":2,"question":"Comment nomme-t-on l'alternance de bradycardie sinusale et de tachycardie par fibrillation atriale ?","answer":"Le syndrome tachycardie-bradycardie (maladie de l'oreillette)","accept":["syndrome tachycardie-bradycardie","maladie de l'oreillette","maladie rythmique atriale","syndrome tachy-brady"],"keywords":["oreillette"],"explanation":"L'alternance de FA (tachycardie) et de dysfonction sinusale (bradycardie) réalise le syndrome tachycardie-bradycardie, ou maladie de l'oreillette ; des pauses de régularisation peuvent s'observer à l'arrêt de la FA.","src":"p. 393","deep":"**Pourquoi** : la maladie de l'oreillette associe deux anomalies atriales : FA (versant tachycardie) et dysfonction sinusale (versant bradycardie) (p. 393).\n**Piège** : à l'arrêt de la FA, la reprise du rythme sinusal peut être lente : ce sont les pauses de régularisation, à ne pas prendre pour un simple artefact (p. 393).\n**À relier** : devant une bradycardie, regarder les P : trop lentes ou absentes = nœud sinusal ; plus nombreuses que les QRS = BAV (p. 389)."},{"id":"231-qroc-615","type":"QROC","rank":"B","objective":"231-obj-13","tags":["ECG"],"difficulty":2,"question":"Quel aspect donne l'association d'une fibrillation atriale et d'un bloc de branche ?","answer":"Une tachycardie irrégulière à QRS larges","accept":["tachycardie irrégulière à QRS larges","QRS larges irréguliers","irrégulière et QRS larges"],"keywords":["irrégul","larges"],"explanation":"Un bloc de branche est fréquent dans la FA, préexistant ou fonctionnel (apparaissant seulement en tachycardie) : l'ECG montre alors une tachycardie irrégulière à QRS larges.","src":"p. 393","deep":"**Pourquoi** : le bloc de branche élargit le QRS quel que soit le rythme ; il peut être préexistant ou fonctionnel (n'apparaissant qu'en tachycardie) : FA + bloc = tachycardie irrégulière à QRS larges (p. 393).\n**Piège** : une tachycardie irrégulière à QRS larges et de largeur variable, très rapide, évoque aussi une FA sur voie accessoire (super-Wolff, p. 411) ; une tachycardie RÉGULIÈRE à QRS larges est une TV jusqu'à preuve du contraire (p. 398).\n**À relier** : avant de décrire un bloc, toujours décrire le rythme atrial pour ne pas manquer une tachycardie supraventriculaire associée (p. 378)."},{"id":"231-qroc-616","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG"],"difficulty":2,"question":"Quelle particularité de la ligne de base caractérise l'activité atriale du flutter atrial ?","answer":"Pas de retour à la ligne isoélectrique (au moins dans une dérivation)","accept":["pas de retour à la ligne isoélectrique","absence de retour à la ligne isoélectrique","sans retour à la ligne isoélectrique","sans retour à la ligne de base","pas de ligne isoélectrique"],"keywords":["isoélectr"],"explanation":"Dans le flutter, l'activité atriale est monomorphe et permanente (boucle de réentrée) : les ondes F s'enchaînent sans retour à la ligne isoélectrique dans au moins une dérivation, d'où l'aspect sinusoïdal, en toit d'usine ou en dents de scie.","src":"p. 393","deep":"**Pourquoi** : le flutter est une boucle de réentrée qui tourne en permanence dans l'oreillette : il y a toujours une activité électrique atriale, donc pas de retour à la ligne isoélectrique dans au moins une dérivation (p. 393).\n**Piège** : en FA, l'activité est anarchique (mailles ou trémulation) ; en flutter, elle est monomorphe (même aspect sur une dérivation), le plus souvent à 300 bpm (240-340) (p. 391-393).\n**À relier** : flutter typique antihoraire : ondes F négatives en D2, D3, aVF, positives en V1 (p. 394)."},{"id":"231-qroc-617","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG"],"difficulty":1,"question":"Citez un des aspects classiques de l'enchaînement des ondes F du flutter atrial.","answer":"Sinusoïdal, en toit d'usine ou en dents de scie","accept":["dents de scie","toit d'usine","sinusoïdal","aspect sinusoïdal","en dents de scie","en toit d'usine"],"keywords":["scie"],"explanation":"Le flutter produit une activité atriale rapide et monomorphe, le plus souvent à 300/min ; les ondes F successives dessinent une ligne sinusoïdale, en toit d'usine ou en dents de scie, que seule une manœuvre vagale révèle parfois.","src":"p. 393","deep":"**Pourquoi** : les ondes F monomorphes s'enchaînent sans pause (activité permanente de la boucle) : la ligne de base dessine une sinusoïde, un toit d'usine ou des dents de scie (p. 393).\n**Piège** : en flutter 2/1 ou 1/1, les QRS sont si rapprochés que les F sont cachées : une manœuvre vagale ralentit les QRS et les démasque (p. 393-395).\n**À relier** : forme usuelle : F à 300 bpm et QRS à 150 bpm (transmission 2/1), parfois 100 bpm (3/1) (p. 394)."},{"id":"231-qroc-618","type":"QROC","rank":"A","objective":"231-obj-15","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Pourquoi l'activité atriale est-elle souvent invisible dans une tachycardie par réentrée intranodale ?","answer":"Les activations atriale et ventriculaire sont quasi synchrones","accept":["quasi synchrones","activation atriale et ventriculaire quasi synchrone","activations simultanées","activations quasi synchrones"],"keywords":["synchron"],"explanation":"Dans la réentrée intranodale, l'activation des oreillettes et celle des ventricules sont quasi synchrones : l'activité atriale n'est souvent pas visible, ou seulement devinée dans le segment ST, sur une tachycardie très régulière à QRS fins.","src":"p. 395","deep":"**Pourquoi** : la réentrée tourne dans le NAV et active oreillettes et ventricules presque en même temps : la P est noyée dans le QRS ou devinée dans le ST (p. 395).\n**Piège** : P invisible ne veut pas dire absence d'activité atriale ; l'autre forme de tachycardie jonctionnelle est la réentrée par voie accessoire (faisceau de Kent, rythme réciproque) (p. 396).\n**À relier** : tachycardie très régulière, souvent ≈ 200 bpm (130-260), réduite par manœuvres vagales ou adénosine IV (p. 395-397)."},{"id":"231-qroc-619","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG"],"difficulty":2,"question":"Quel aspect ECG caractérise une extrasystole ventriculaire ?","answer":"Un QRS large prématuré, avec ou sans onde P' rétrograde","accept":["QRS large","QRS large prématuré","QRS élargi","QRS larges prématurés"],"keywords":["large"],"explanation":"L'extrasystole ventriculaire est un QRS large survenant prématurément, avec ou sans onde P' rétrograde ; l'extrasystole atriale donne une onde P précoce de morphologie différente de la P sinusale suivie d'un QRS fin.","src":"p. 397","deep":"**Pourquoi** : l'ESV naît dans le myocarde ventriculaire, hors des voies de conduction : propagation de proche en proche, donc QRS large et prématuré, ± P' rétrograde (p. 397-398).\n**Piège** : QRS fin prématuré = ESA (P' précoce de morphologie différente) ou extrasystole jonctionnelle (rare, ± P' rétrograde) (p. 397).\n**À relier** : extrasystoles rythmées : 1 sur 2 = bigéminisme, 1 sur 3 = trigéminisme ; répétitives : doublets, triplets, salves (p. 398)."},{"id":"231-qroc-620","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG","étiologie"],"difficulty":1,"question":"Que doivent faire rechercher des extrasystoles fréquentes ou polymorphes ?","answer":"Une cardiopathie","accept":["cardiopathie","cardiopathie sous-jacente","une cardiopathie sous-jacente"],"keywords":["cardiopath"],"explanation":"Les extrasystoles sont fréquentes et peuvent être physiologiques sur cœur sain ; leur charge (nombre sur 24 heures) augmente avec l'âge et la cardiopathie, et des extrasystoles fréquentes ou polymorphes doivent faire rechercher une cardiopathie.","src":"p. 397","deep":"**Pourquoi** : des extrasystoles peuvent exister sur cœur sain, mais leur charge (nombre/24 h) augmente avec l'âge et la cardiopathie : nombreuses ou polymorphes, elles deviennent un signe d'alerte (p. 397).\n**Piège** : « physiologiques sur cœur sain » ne veut pas dire toujours bénignes : la fréquence et le polymorphisme orientent vers une cardiopathie.\n**À relier** : de même, une TV est le plus souvent une réentrée autour d'une zone de fibrose (infarctus, cardiopathie) (p. 399)."},{"id":"231-qroc-621","type":"QROC","rank":"A","objective":"231-obj-18","tags":["urgence","ECG"],"difficulty":1,"question":"Que faut-il faire dès la suspicion d'une tachycardie ventriculaire ?","answer":"Donner l'alerte (faire le 15) et se préparer à une réanimation","accept":["donner l'alerte","faire le 15","appeler le 15","15","alerter"],"keywords":["alerte"],"explanation":"Une TV (tachycardie > 100/min avec QRS > 120 ms sur au moins 3 battements) est un état électrique instable qui peut dégénérer en FV puis en asystolie : sa suspicion impose de donner l'alerte (faire le 15) et de se préparer à une réanimation.","src":"p. 399","deep":"**Pourquoi** : la TV est un état électrique instable qui peut dégénérer en FV puis en asystolie ; elle est observée dans plus de la moitié des morts subites (p. 398) : alerte (15) et préparation à la réanimation dès la suspicion (p. 399).\n**Piège** : la suspicion suffit (FC > 100 bpm et QRS > 120 ms sur ≥ 3 battements) : on ne retarde pas l'alerte pour affiner le diagnostic (p. 399).\n**À relier** : TVNS = 3 battements à 30 s ; TV soutenue > 30 s (p. 399)."},{"id":"231-qroc-622","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":2,"question":"Comment nomme-t-on, dans une tachycardie à QRS larges, l'aspect de QRS entièrement positifs ou entièrement négatifs de V1 à V6, en faveur d'une TV ?","answer":"La concordance (positive ou négative) dans les précordiales","accept":["concordance","concordance positive","concordance négative","concordance précordiale"],"keywords":["concordan"],"explanation":"Une concordance positive (QRS entièrement positifs) ou négative (QS) de V1 à V6 est un argument en faveur d'une TV, comme une cardiopathie sous-jacente, une déviation axiale extrême ou des QRS larges d'aspect différent d'un bloc de branche habituel.","src":"p. 400","deep":"**Pourquoi** : QRS tous positifs (R) ou tous négatifs (QS) de V1 à V6 : l'activation vient d'un foyer ventriculaire et non d'un bloc de branche habituel, d'où l'argument en faveur d'une TV (p. 400).\n**Piège** : c'est un argument EN FAVEUR, pas de certitude : la certitude repose sur la dissociation ventriculoatriale (plus de QRS que de P) et les complexes de capture/fusion (p. 400).\n**À relier** : autres arguments en faveur : cardiopathie sous-jacente, QRS positif en aVR, QRS d'aspect différent d'un bloc habituel (p. 400)."},{"id":"231-qroc-623","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG"],"difficulty":3,"question":"Dans une tachycardie à QRS larges, quel aspect du QRS en aVR est un argument en faveur d'une TV ?","answer":"Un QRS positif en aVR (axe extrême)","accept":["QRS positif en aVR","positivité exclusive en aVR","déviation axiale extrême","positif en aVR","axe extrême"],"keywords":["positif"],"explanation":"Un QRS positif en aVR correspond à une déviation axiale extrême, que l'on ne rencontre ni dans un BBD ni dans un BBG : c'est un argument en faveur d'une TV.","src":"p. 400, 402","deep":"**Pourquoi** : un QRS positif en aVR signifie que l'activation va vers le haut et la droite (axe extrême) : un tel axe ne se voit ni dans un BBD ni dans un BBG, donc il plaide pour une TV (p. 400, 402).\n**Piège** : argument en faveur, pas de certitude (certitude = dissociation ventriculoatriale, capture, fusion) (p. 400).\n**À relier** : méthode de l'axe : D1 et aVF négatifs = axe extrême entre -90 et -180° (p. 375)."},{"id":"231-qroc-624","type":"QROC","rank":"A","objective":"231-obj-19","tags":["ECG","urgence"],"difficulty":2,"question":"Quel aspect ECG caractérise la fibrillation ventriculaire ?","answer":"Une tachycardie irrégulière à QRS larges polymorphes","accept":["QRS larges polymorphes","larges fuseaux","tachycardie irrégulière polymorphe","irrégulière à QRS larges"],"keywords":["irrégul","polymorph"],"explanation":"La FV est une urgence absolue : tachycardie irrégulière à QRS larges polymorphes, avec perte de connaissance en quelques secondes (débit cardiaque nul) et pouls carotidien aboli ; elle impose un choc électrique immédiat.","src":"p. 402-403","deep":"**Pourquoi** : la FV est une activation ventriculaire anarchique sans contraction efficace : débit nul, perte de connaissance en quelques secondes, pouls carotidien aboli = arrêt cardiaque (p. 403).\n**Piège** : une torsade de pointes installée peut être indiscernable d'une FV : seuls un QT long préalable et le contexte font la différence (p. 403, rang B).\n**À relier** : urgence absolue : cardioversion électrique immédiate avant tout autre geste, massage cardiaque en attendant le choc (p. 402)."},{"id":"231-qroc-625","type":"QROC","rank":"A","objective":"231-obj-22","tags":["ECG","étiologie"],"difficulty":1,"question":"Selon le tableau des connaissances, quelles trois origines sont citées pour un allongement du QT ?","answer":"Médicamenteuse, congénitale, ionique","accept":["médicaments, génétique, troubles ioniques","médicamenteuse, congénitale et ionique","médicaments, congénital, ionique","médicamenteux, congénital, ionique"],"keywords":["médicament","congénit","ioni"],"explanation":"Un QT allongé peut être d'origine médicamenteuse (association de médicaments allongeant le QT), congénitale (syndrome du QT long congénital, maladie génétique) ou ionique (kaliémie, calcémie, magnésémie).","src":"p. 368, 404","deep":"**Pourquoi** : le QT mesure la durée de la repolarisation ventriculaire ; le tableau d'objectifs résume ses causes en trois familles : médicamenteuse, congénitale, ionique (p. 368), détaillées p. 404.\n**Piège** : ne mesure pas le QT avec l'onde U (p. 377) ; une bradycardie extrême allonge aussi le QT (p. 404).\n**À relier** : ionique = hypokaliémie, hypocalcémie, hypomagnésémie ; médicaments = antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens (p. 404) ; QTc normal < 450 ms à 60 bpm (p. 375)."},{"id":"231-qroc-626","type":"QROC","rank":"A","objective":"231-obj-22","tags":["ECG","biologie"],"difficulty":2,"question":"Quels sont les deux troubles ioniques, en dehors de l'hypokaliémie, qui allongent le QT ?","answer":"L'hypocalcémie et l'hypomagnésémie","accept":["hypocalcémie et hypomagnésémie","hypoCa et hypoMg","calcium et magnésium bas","hypomagnésémie et hypocalcémie"],"keywords":["hypocalc","hypomagn"],"explanation":"Outre l'hypokaliémie, l'hypocalcémie et l'hypomagnésémie allongent le QT et exposent aux torsades de pointes.","src":"p. 404","deep":"**Pourquoi** : la torsade de pointes survient sur QT allongé ; trois troubles ioniques « hypo » allongent le QT : hypokaliémie, hypocalcémie, hypomagnésémie (p. 404).\n**Piège** : l'hyperkaliémie a d'autres signes : T ample pointue symétrique, PR allongé, QRS élargi, BAV (p. 408) — ne la range pas dans les causes de QT long.\n**À relier** : conduite devant un QT long : vérifier les médicaments et le ionogramme pour corriger et éviter la mort subite (p. 404, rang B)."},{"id":"231-qroc-627","type":"QROC","rank":"B","objective":"231-obj-22","tags":["ECG","urgence"],"difficulty":2,"question":"Devant un QT allongé sur l'ECG, quels deux éléments faut-il vérifier pour éviter une mort subite ?","answer":"Les médicaments responsables et le ionogramme","accept":["médicaments et ionogramme","médicaments et ionogramme sanguin","ionogramme et médicaments","médicaments et kaliémie, calcémie, magnésémie"],"keywords":["médicament","ionogramme"],"explanation":"Un QT allongé doit alerter : on recherche les médicaments responsables et on contrôle le ionogramme afin de corriger l'allongement du QT et d'éviter une mort subite.","src":"p. 404","deep":"**Pourquoi** : un QT long expose à la torsade de pointes, qui peut dégénérer en FV : plusieurs de ses causes sont corrigeables (médicaments, troubles ioniques) : le Collège demande donc de vérifier les médicaments responsables et le ionogramme pour corriger l'allongement du QT (p. 404).\n**Piège** : ne t'arrête pas à la mesure du QT : c'est la recherche d'une cause réversible qui prévient la mort subite ; pense aux ASSOCIATIONS de médicaments allongeant le QT (p. 404).\n**À relier** : prise en charge des torsades : corriger les troubles ioniques, accélérer la FC, arrêter les médicaments allongeant le QT (p. 404)."},{"id":"231-qroc-628","type":"QROC","rank":"B","objective":"231-obj-20","tags":["traitement","urgence"],"difficulty":2,"question":"Quelle mesure portant sur la fréquence cardiaque fait partie de la prise en charge des torsades de pointes ?","answer":"Accélérer la fréquence cardiaque","accept":["accélérer la fréquence cardiaque","accélérer la FC","augmenter la fréquence cardiaque","accélérer le rythme cardiaque"],"keywords":["accél"],"explanation":"Face à une torsade de pointes, on rétablit l'équilibre ionique, on accélère le rythme cardiaque et on interrompt tout médicament qui allonge le QT.","src":"p. 404","deep":"**Pourquoi** : une bradycardie allonge le QT et favorise la torsade : accélérer la fréquence cardiaque raccourcit le QT, d'où ce volet du traitement, avec la correction ionique et l'arrêt des médicaments allongeant le QT (p. 404).\n**Piège** : la bradycardie extrême (échappement à QRS larges des BAV bas situés, intoxication par bradycardisant) est elle-même une cause de QT long : ralentir le cœur aggraverait la situation (p. 404).\n**À relier** : la torsade peut s'arrêter seule ou dégénérer en FV (p. 403)."},{"id":"231-qroc-629","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG"],"difficulty":2,"question":"Dans l'HVG sévère, dans quel territoire observe-t-on une onde T négative avec sous-décalage du ST ?","answer":"Le territoire latéral (D1, aVL, V5, V6)","accept":["D1, aVL, V5, V6","latérales","latéral","dérivations latérales","territoire latéral"],"keywords":["lat"],"explanation":"Dans la forme sévère de l'HVG, la repolarisation est secondairement anormale (onde T négative, sous-décalage du ST) dans les dérivations latérales D1, aVL, V5, V6, avec disparition de l'onde Q septale dans ces mêmes dérivations.","src":"p. 406","deep":"**Pourquoi** : dans l'HVG sévère, l'excès de masse du VG perturbe secondairement la repolarisation dans les dérivations qui regardent le VG : latérales D1, aVL, V5, V6 (T négative + ST sous-décalé, perte de la Q septale) (p. 406).\n**Piège** : en V1-V2, l'HVG peut au contraire mimer une séquelle d'infarctus (aspect QS, pseudonécrose) ou un sus-décalage du ST (p. 406-407).\n**À relier** : Sokolow = S V1 ou V2 + R V5 ou V6, normal < 35 mm ; causes les plus fréquentes : HTA puis rétrécissement aortique (p. 406-407)."},{"id":"231-qroc-630","type":"QROC","rank":"B","objective":"231-obj-23","tags":["ECG","pièges"],"difficulty":2,"question":"Quelle image, présente dans le sus-décalage du ST d'un SCA ST+, est typiquement absente dans la péricardite aiguë ?","answer":"L'image en miroir","accept":["miroir","image en miroir","sous-décalage en miroir","image miroir"],"keywords":["miroir"],"explanation":"Le sus-décalage de la péricardite est diffus, concave vers le haut, concordant, sans image en miroir. Attention : l'image en miroir peut aussi manquer dans un SCA avec sus-décalage, donc son absence ne suffit pas à conclure à une péricardite.","src":"p. 409","deep":"**Pourquoi** : dans la péricardite, l'atteinte est diffuse et non systématisée à un territoire coronaire : sus-ST concave vers le haut, diffus, concordant, sans image en miroir (p. 409).\n**Piège** : le miroir peut manquer dans un SCA ST+ : son absence ne suffit pas pour conclure à une péricardite (encadré « Attention », p. 409 ; points clés p. 415).\n**À relier** : autres signes de phase 1 : sous-décalage de PQ et microvoltage, d'autant plus marqué que la péricardite est liquidienne (p. 409)."},{"id":"231-qroc-631","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG","pièges"],"difficulty":3,"question":"Dans quelle situation rythmique ne faut-il pas bloquer le NAV (massage, adénosine) pour démasquer une préexcitation ?","answer":"En cas de fibrillation atriale","accept":["en cas de FA","fibrillation atriale","FA","FA préexcitée"],"keywords":["fibrillation"],"explanation":"Bloquer le NAV force l'influx à passer par la voie accessoire et démasque une préexcitation minime, mais il ne faut pas le faire en cas de FA : une FA rapide conduite par une voie accessoire perméable donne une tachycardie irrégulière à QRS larges (« super-Wolff ») pouvant dégénérer en FV (p. 410-411).","src":"p. 410-411","deep":"**Pourquoi** : bloquer le NAV force l'influx à passer par la voie accessoire, qui n'a pas de conduction décrémentielle : en FA, tous les influx atriaux rapides pourraient gagner le ventricule (super-Wolff) avec risque de FV (p. 410-411).\n**Piège** : contre-indications de l'adénosine : la légende p. 411 cite le super-Wolff comme seule autre CI avec l'asthme, alors que l'encadré p. 390 cite asthme et hypotension artérielle ; connais les deux.\n**À relier** : préexcitation = PR court < 120 ms + onde delta élargissant le QRS + troubles de repolarisation dans le territoire de la voie accessoire (p. 410)."},{"id":"231-qroc-632","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Combien de dérivations faut-il enregistrer devant toute douleur thoracique, pour ne pas méconnaître un sus-décalage postérieur ?","answer":"18 dérivations","accept":["18","ECG 18 dérivations"],"keywords":["18"],"explanation":"Un sous-décalage du ST en V1-V3 peut être le miroir d'un sus-décalage postérieur (V7-V9) : on réalise donc un ECG 18 dérivations devant toute douleur thoracique.","src":"p. 411","deep":"**Pourquoi** : le territoire postérieur (V7-V9) n'est pas vu par l'ECG 12 dérivations : son sus-décalage n'apparaît qu'en miroir, sous forme de sous-décalage en V1-V3, d'où l'ECG 18 dérivations (p. 411).\n**Piège** : un sous-décalage isolé en V1-V3 n'est pas forcément un SCA sans ST : pense au miroir d'un ST+ postérieur ; on traque d'abord le sus-décalage, puis le miroir, pas l'inverse (p. 411).\n**À relier** : V3R et V4R explorent le ventricule droit (p. 371, 374)."},{"id":"231-qroc-633","type":"QROC","rank":"B","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Dans quelles dérivations observe-t-on le sus-décalage du ST de la repolarisation précoce ?","answer":"Les dérivations inférolatérales","accept":["inférolatérales","inféro-latérales","inférieures et latérales","territoire inférolatéral"],"keywords":["latéral"],"explanation":"La repolarisation précoce est l'une des cinq étiologies de sus-décalage du ST à connaître (SCA avec sus-décalage, anévrisme ventriculaire, repolarisation précoce, angor de Prinzmetal, péricardite) ; son sus-décalage siège dans les dérivations inférolatérales.","src":"p. 412","deep":"**Pourquoi** : la repolarisation précoce fait partie des 5 étiologies de sus-ST à connaître ; son sus-décalage siège en inférolatéral (encadré, p. 412).\n**Piège** : un sus-ST n'est pas toujours un SCA : SCA ST+ (Pardee + miroir), anévrisme ventriculaire, repolarisation précoce, Prinzmetal, péricardite (p. 412).\n**À relier** : chez le jeune homme, un point J sus-décalé de V1 à V4 avec ST ascendant est une repolarisation physiologique (p. 377)."},{"id":"231-qroc-634","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quel sus-décalage minimal du ST est exigé dans les dérivations autres que V1 à V3 pour être significatif ?","answer":"1 mm","accept":["1 mm","≥ 1 mm","un millimètre","au moins 1 mm"],"keywords":["1 mm"],"explanation":"Pour être significatif, le sus-décalage du ST doit mesurer au moins 2 mm en V1-V3 et au moins 1 mm dans les autres dérivations, et être présent sur deux dérivations adjacentes ou plus.","src":"p. 412","deep":"**Pourquoi** : le Collège fixe deux seuils de sus-décalage significatif : au moins 2 mm de V1 à V3, au moins 1 mm dans les autres dérivations (p. 412).\n**Piège** : ne pas inverser les deux seuils ; et le sus-ST doit être présent sur au moins 2 dérivations adjacentes (p. 412).\n**À relier** : si le sus-décalage englobe l'onde T, c'est l'onde de Pardee (p. 412) ; chez le jeune homme, un point J sus-décalé de V1 à V4 avec ST ascendant est une repolarisation physiologique (p. 377)."},{"id":"231-qroc-635","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":1,"question":"Combien de dérivations voisines doivent présenter le sus-décalage du ST pour qu'il soit significatif ?","answer":"Au moins 2 dérivations adjacentes","accept":["2 dérivations","deux dérivations","au moins 2 dérivations","au moins deux dérivations","2 dérivations contiguës","2 dérivations adjacentes"],"keywords":["adjacent"],"explanation":"Un sus-décalage du ST n'est retenu que s'il touche au moins deux dérivations adjacentes, avec un seuil de 2 mm en V1-V3 et de 1 mm ailleurs.","src":"p. 412","deep":"**Pourquoi** : une occlusion coronaire lèse un territoire, vu par plusieurs dérivations voisines : un sus-ST isolé sur une seule dérivation n'a pas la même valeur (p. 412).\n**Piège** : il faut à la fois le seuil (≥ 2 mm en V1-V3, ≥ 1 mm ailleurs) ET au moins 2 dérivations adjacentes (p. 412).\n**À relier** : le territoire du sus-décalage indique la coronaire occluse ; on cherche ensuite le miroir (p. 411)."},{"id":"231-qroc-636","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","physiopathologie"],"difficulty":2,"question":"À quel type de courant de lésion correspond un sous-décalage du segment ST dans un SCA sans sus-décalage ?","answer":"Un courant de lésion sous-endocardique","accept":["sous-endocardique","lésion sous-endocardique","courant de lésion sous-endocardique"],"keywords":["endocard"],"explanation":"Dans un SCA sans sus-décalage, on peut observer un sous-décalage du ST (courant de lésion sous-endocardique), une inversion des ondes T, une pseudo-normalisation d'ondes T négatives, un aplatissement des ondes T, voire un ECG normal.","src":"p. 412","deep":"**Pourquoi** : dans un SCA sans sus-décalage, la souffrance prédomine sous l'endocarde : elle s'exprime par un sous-décalage du ST (courant de lésion sous-endocardique) (p. 412).\n**Piège** : ne pas inverser : inversion des ondes T = ischémie sous-ÉPIcardique ; et un ECG normal n'élimine pas un SCA sans ST (p. 412).\n**À relier** : autres aspects : pseudo-normalisation d'ondes T antérieurement négatives, aplatissement des T ; anomalies parfois masquées par un pacemaker (p. 412)."},{"id":"231-qroc-637","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Quel type d'ischémie traduit une inversion des ondes T dans un SCA sans sus-décalage du ST ?","answer":"Une ischémie sous-épicardique","accept":["sous-épicardique","ischémie sous-épicardique","sous épicardique"],"keywords":["épicard"],"explanation":"L'inversion des ondes T d'un SCA sans sus-décalage traduit une ischémie sous-épicardique, alors que le sous-décalage du ST correspond à un courant de lésion sous-endocardique.","src":"p. 412","deep":"**Pourquoi** : dans un SCA sans sus-décalage, l'inversion des ondes T traduit une ischémie sous-épicardique (p. 412).\n**Piège** : deux ondes T négatives dans un même territoire sont pathologiques (ex. D2 et D3), alors qu'une T négative isolée en aVR, V1, parfois D3 ou aVL peut être normale (p. 377, 411).\n**À relier** : après un SCA ST+, l'évolution normale après 48 h se fait vers une onde T négative « ischémique », parfois durable (p. 412)."},{"id":"231-qroc-638","type":"QROC","rank":"B","objective":"231-obj-26","tags":["traitement","ECG"],"difficulty":2,"question":"Quels sont les deux types de bloc atrioventriculaire qui constituent une indication de pacemaker même en l'absence de symptôme ?","answer":"Les BAV infrahissiens (BAV2 Mobitz 2 et BAV3)","accept":["infrahissiens","BAV infrahissiens","Mobitz 2 et BAV3","Mobitz 2 et BAV 3","BAV2 Mobitz 2 et BAV3","Mobitz 2 et BAV complet"],"keywords":["mobitz"],"explanation":"Les BAV infrahissiens (BAV2 Mobitz 2 et BAV3) sont une indication de pacemaker même asymptomatiques ; pour la dysfonction sinusale, le BAV2 Mobitz 1 et la bradycardie sinusale, la stimulation concerne les formes symptomatiques.","src":"p. 412","deep":"**Pourquoi** : les BAV infrahissiens (Mobitz 2 et BAV3) siègent sous le His ; un BAV complet infrahissien peut provoquer syncope, voire mort subite (p. 383) : le pacemaker est indiqué même sans symptôme (p. 412).\n**Piège** : dysfonction sinusale, BAV2 Mobitz 1 et bradycardie sinusale ne relèvent du pacemaker que s'ils sont symptomatiques (p. 412).\n**À relier** : en cas de BAV, le pacemaker écoute l'oreillette et stimule le ventricule (QRS large d'aspect BBG après le spike) (p. 414)."},{"id":"231-qroc-639","type":"QROC","rank":"B","objective":"231-obj-28","tags":["paraclinique","ECG"],"difficulty":2,"question":"À quelle condition un Holter ECG de 24 à 96 heures est-il pertinent devant des palpitations épisodiques, quand l'ECG standard n'a pas fait le diagnostic ?","answer":"S'il est probable que les symptômes se répètent pendant l'enregistrement","accept":["probabilité que les symptômes se répètent","symptômes fréquents","si les symptômes se répètent","symptômes susceptibles de se répéter pendant l'enregistrement"],"keywords":["répèt"],"explanation":"Le Holter s'adresse aux malaises, syncopes, pertes de connaissance ou palpitations épisodiques quand l'ECG de repos n'a pas permis de conclure, à condition que les symptômes aient une bonne chance de survenir pendant l'enregistrement ; pour des symptômes rares, on recourt à des enregistrements plus longs (jusqu'à 21 jours) ou à des enregistreurs d'événements.","src":"p. 415","deep":"**Pourquoi** : le Holter (2 à 12 dérivations, 24 à 96 h, analyse différée) ne voit que ce qui survient pendant l'enregistrement : il n'est utile que si les symptômes ont une bonne probabilité de se répéter pendant cette durée (p. 415).\n**Piège** : pour des symptômes rares, un Holter court risque d'être normal à tort : on passe à l'ECG ambulatoire jusqu'à 21 jours ou aux enregistreurs d'événements (p. 415).\n**À relier** : holter implantable (sous-cutané, jusqu'à 3 ans) : syncopes inexpliquées ou FA silencieuse (p. 415)."},{"id":"231-qroc-701","type":"QROC","rank":"A","objective":"231-obj-27","tags":["urgence","indication"],"difficulty":1,"question":"Citez deux des principales situations d'urgence qui justifient la réalisation d'un ECG.","answer":"Douleur thoracique, palpitations, syncope, défaillance d'organe, K/Ca","accept":["douleur thoracique","palpitations","syncope","défaillance d'organe","défaillances d'organe","perte de connaissance","dyskaliémie","dyscalcémie","troubles hydroélectrolytiques","trouble ionique","hypokaliémie","hyperkaliémie","hypocalcémie","hypercalcémie"],"keywords":[],"explanation":"Le Collège cite parmi les indications de l'urgence les défaillances d'organe, la douleur thoracique, les palpitations, la syncope et les troubles hydroélectrolytiques portant sur le potassium et le calcium.","src":"p. 368","deep":"**Pourquoi** : le tableau d'objectifs (rang A) liste 5 familles d'urgence où l'ECG change la conduite immédiate : défaillance d'organe, douleur thoracique, palpitations, syncope, troubles du K ou du Ca (p. 368).\n**Piège** : les troubles ioniques cités sont le potassium et le calcium ; et l'ECG doit être un vrai 12 dérivations (18 devant toute douleur thoracique, p. 411).\n**À relier** : hors urgence, l'ECG est aussi obligatoire dans le bilan d'une HTA et indiqué en préopératoire après 65 ans (p. 414). Astuce « DOPS + K/Ca »."},{"id":"231-qroc-702","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Quel plan explorent les dérivations des membres (D1, D2, D3, aVR, aVL, aVF) ?","answer":"Le plan frontal (vertical)","accept":["frontal","plan frontal","vertical","plan vertical","frontales","coronal"],"keywords":["frontal"],"explanation":"Les dérivations frontales explorent le plan frontal, alors que les précordiales explorent le plan horizontal.","src":"p. 371","deep":"**Pourquoi** : les électrodes des membres (D1, D2, D3 et aVR, aVL, aVF) dessinent le double triaxe de Bailey dans le plan vertical du corps vu de face (p. 371, 375).\n**Piège** : c'est dans ce plan frontal, et seulement là, qu'on calcule l'axe du QRS (p. 375).\n**À relier** : les précordiales V1-V9 explorent le plan horizontal (p. 371)."},{"id":"231-qroc-703","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Quel plan explorent les dérivations précordiales ?","answer":"Le plan horizontal (transversal)","accept":["horizontal","plan horizontal","transversal","plan transversal","horizontale"],"keywords":[],"explanation":"Les précordiales (V1 à V9, complétées parfois par V3R et V4R) explorent le plan horizontal, aussi appelé transversal.","src":"p. 371","deep":"**Pourquoi** : les électrodes précordiales sont posées autour du thorax, à hauteur du cœur : elles le « coupent » dans un plan horizontal (transversal) (p. 371).\n**Piège** : V1 et V2 sont souvent placées trop haut et trop écartées (confusion avec les foyers aortique et pulmonaire) : risque de pseudonécrose ou d'atypie de repolarisation antérieure (p. 373).\n**À relier** : V3R et V4R s'ajoutent chez l'enfant ou en cas de suspicion de SCA ; V7-V9 explorent le postérieur (p. 371, 374)."},{"id":"231-qroc-704","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":2,"question":"Quelles dérivations explorent le ventricule droit ?","answer":"V1, V2, V3R et V4R","accept":["v1, v2, v3r et v4r","v1 v2 v3r v4r","v3r et v4r","v3r, v4r","v3r","v1, v2, v3r, v4r"],"keywords":["v3r","v4r"],"explanation":"Le ventricule droit est exploré par V1, V2 et par les dérivations droites V3R et V4R, ajoutées chez l'enfant ou en cas de suspicion de SCA.","src":"p. 371, 374","deep":"**Pourquoi** : le VD est en avant et à droite : il est vu par V1, V2 et par les dérivations droites V3R, V4R (p. 374).\n**Piège** : V3R/V4R (droites) ne sont pas V7-V9 (postérieures, face basale et inférieure du VG) (p. 374).\n**À relier** : V3R et V4R sont ajoutées chez l'enfant ou en cas de suspicion de SCA (p. 371)."},{"id":"231-qroc-705","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Quelle dérivation précordiale est qualifiée d'« apicale » ?","answer":"V4","accept":["v4","v 4","apicale"],"keywords":["v4"],"explanation":"Les territoires dépendent de la position de l'électrode : V1-V3 sont antéroseptales, V4 apicale, V5-V6 latérales basses.","src":"p. 374","deep":"**Pourquoi** : V4, au 5e espace intercostal sur la ligne médioclaviculaire gauche, est en regard de la pointe : dérivation apicale (p. 372, 374).\n**Piège** : V1-V3 sont antéroseptales et V5-V6 latérales basses : V4 n'appartient à aucun des deux groupes.\n**À relier** : D1 et aVL = latéral haut ; D2, D3, aVF = inférieur (p. 374)."},{"id":"231-qroc-706","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","définition"],"difficulty":1,"question":"À quoi sert surtout, en pratique, de savoir quel territoire cardiaque explore chaque dérivation ?","answer":"À localiser les infarctus","accept":["localiser les infarctus","localisation des infarctus","localiser l'infarctus","infarctus","localiser un infarctus","localisation de l'infarctus","localiser le territoire de l'infarctus"],"keywords":["infarctus"],"explanation":"Le principe des territoires concerne surtout les ventricules et est très utile à la localisation des infarctus.","src":"p. 374","deep":"**Pourquoi** : les territoires sont liés à la position des électrodes par rapport au cœur ; le principe vaut surtout pour les ventricules et sert à localiser l'infarctus : le sus-ST indique le territoire de la coronaire occluse (p. 374, 411).\n**Piège** : on traque d'abord le sus-décalage, puis on cherche le miroir (sous-décalage), pas l'inverse (p. 411).\n**À relier** : inférieur D2-D3-aVF, antéroseptal V1-V3, apical V4, latéral D1-aVL-V5-V6, postérieur V7-V9 (p. 374)."},{"id":"231-qroc-707","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Dans le double triaxe de Bailey, de combien de degrés sont espacées les dérivations frontales successives (D1 étant à 0°) ?","answer":"30° (dans le sens horaire à partir de D1)","accept":["30° en 30°","30 en 30","30 degrés","30°","trente degrés"],"keywords":["30"],"explanation":"Le double triaxe de Bailey place D1 à l'horizontale (0°) et gradue les dérivations de 30 en 30° dans le sens des aiguilles d'une montre.","src":"p. 375","deep":"**Pourquoi** : le double triaxe de Bailey superpose les 6 dérivations frontales ; à partir de D1 à 0°, elles sont graduées de 30 en 30° dans le sens horaire, ce qui permet de chiffrer l'axe (p. 375).\n**Piège** : sens horaire : aVF est à +90° (en bas), aVL à -30° ; un axe « négatif » est dirigé vers le haut.\n**À relier** : axe normal en pratique de -30° (aVL) à +90° (aVF) (p. 375)."},{"id":"231-qroc-708","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","axe"],"difficulty":2,"question":"Si D1 est positif et aVF négatif, quelle dérivation permet de distinguer un axe normal d'un axe hypergauche ?","answer":"D2 (positif : axe normal ; négatif : hypergauche)","accept":["d2","dii","d 2","d ii","dérivation ii","d2 positif"],"keywords":["d2"],"explanation":"D1+ et aVF- placent l'axe entre 0 et -90° ; si D2 est positif, l'axe est entre 0 et -30° (normal), sinon il est hypergauche.","src":"p. 375","deep":"**Pourquoi** : D1+ et aVF- placent l'axe entre 0 et -90° ; D2 (à +60°) est perpendiculaire à -30° : s'il est positif, l'axe ne dépasse pas -30° (normal), sinon il est hypergauche (p. 375).\n**Piège** : D1+ et aVF- n'est donc pas forcément pathologique ; l'HBAG se définit justement par un axe au-delà de -30° avec D2 négatif (p. 382).\n**À relier** : D1+/aVF+ = 0 à 90° normal ; D1-/aVF+ = hyperdroit ; D1-/aVF- = extrême (p. 375)."},{"id":"231-qroc-709","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","axe"],"difficulty":1,"question":"Quel axe du QRS correspond à un QRS négatif à la fois en D1 et en aVF ?","answer":"Un axe extrême (entre -90° et -180°)","accept":["axe extrême","extrême","extreme","-90 et -180","entre -90 et -180","entre -90° et -180°","déviation extrême"],"keywords":["extr"],"explanation":"D1 et aVF négatifs : le quadrant exploré est celui de l'axe extrême, entre -90 et -180°.","src":"p. 375","deep":"**Pourquoi** : D1 et aVF négatifs : le vecteur s'éloigne à la fois de D1 (0°) et d'aVF (+90°), il est donc dans le quadrant opposé, entre -90 et -180° (p. 375).\n**Piège** : un QRS positif en aVR (axe extrême) devant une tachycardie à QRS larges est un argument en faveur d'une TV : un tel axe ne se voit ni en BBD ni en BBG (p. 400, 402).\n**À relier** : D1-/aVF+ = hyperdroit (90 à 180°) (p. 375)."},{"id":"231-qroc-710","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","axe"],"difficulty":1,"question":"Quel axe du QRS correspond à un QRS négatif en D1 et positif en aVF ?","answer":"Un axe hyperdroit (entre 90° et 180°)","accept":["hyperdroit","hyper droit","axe droit","dévié à droite","90 et 180","axe dévié à droite","déviation axiale droite"],"keywords":["droit"],"explanation":"D1- et aVF+ désignent le quadrant 90 à 180° : axe hyperdroit.","src":"p. 375","deep":"**Pourquoi** : D1 négatif = le vecteur va vers la droite (au-delà de +90°) ; aVF positif = il va vers le bas : quadrant 90 à 180°, axe hyperdroit (p. 375).\n**Piège** : devant un D1 négatif, pense d'abord à une inversion des électrodes frontales (P aussi négative en D1) (p. 383).\n**À relier** : causes d'axe droit : HBPG (diagnostic d'exclusion), HVD (signe le plus précoce), sujet longiligne (p. 382, 407)."},{"id":"231-qroc-711","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","axe"],"difficulty":2,"question":"Entre quelles valeurs se situe l'axe normal du QRS lorsque l'on ne l'arrondit pas ?","answer":"De -45° à +110°","accept":["-45 et +110","-45 à +110","-45° et +110°","45 et 110","-45","-45° à +110°","-45 à 110","entre -45 et +110"],"keywords":["45","110"],"explanation":"L'axe normal du QRS est compris entre -45 et +110° ; en pratique on utilise les valeurs arrondies de -30° à +90° (de aVL à aVF).","src":"p. 375","deep":"**Pourquoi** : la norme théorique de l'axe du QRS va de -45 à +110° ; on l'arrondit en pratique à -30/+90°, c'est-à-dire de aVL à aVF (p. 375).\n**Piège** : ne mélange pas les deux jeux de valeurs : le tableau 15.2 retient -30 à +90°.\n**À relier** : même logique d'arrondi pour la P : < 110 ms en théorie, 120 ms en pratique (p. 375)."},{"id":"231-qroc-712","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Quelle amplitude correspond à 1 mm de hauteur sur l'ECG standard ?","answer":"0,1 mV","accept":["0,1 mv","0.1 mv","0,1 millivolt","0,1","0,1 mv/mm","0.1 millivolt","0,1mv"],"keywords":[],"explanation":"À l'étalonnage normal, 1 mm en amplitude vaut 0,1 mV ; la vitesse normale est de 25 mm/s.","src":"p. 375","deep":"**Pourquoi** : à l'étalonnage standard, 1 mm vertical vaut 0,1 mV (p. 375).\n**Piège** : ne confonds pas avec l'échelle horizontale : à 25 mm/s, 1 mm = 40 ms et un grand carreau de 5 mm = 200 ms (p. 375).\n**À relier** : les seuils d'amplitude se lisent en mm : P < 2,5 mm en D2, Sokolow < 35 mm, sus-ST ≥ 2 mm en V1-V3 (p. 375, 406, 412)."},{"id":"231-qroc-713","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Pourquoi l'onde P sinusale a-t-elle une positivité maximale en D2 (axe de 60°) ?","answer":"Nœud sinusal en haut à droite de l'OD : activation vers le bas et la gauche","accept":["en haut à droite","haut à droite","du haut à droite vers le bas à gauche","haut et à droite","en haut à droite de l'oreillette droite","activation du haut vers le bas","vecteur vers le bas et la gauche"],"keywords":["haut","droite"],"explanation":"Le nœud sinusal est situé en haut à droite de l'oreillette droite : les oreillettes sont activées de haut en bas et de droite à gauche, d'où une P maximale en D2.","src":"p. 375","deep":"**Pourquoi** : le nœud sinusal est en haut à droite de l'OD : les oreillettes sont activées du haut à droite vers le bas à gauche, vecteur d'environ +60°, soit l'axe de D2 (p. 375).\n**Piège** : une P négative en D2 n'est pas sinusale : P' rétrograde d'un échappement jonctionnel (activation atriale de bas en haut) (p. 388).\n**À relier** : P sinusale = positive en D1 et en inférieur, chaque P suivie d'un QRS et chaque QRS précédé d'une P (p. 376)."},{"id":"231-qroc-714","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Quelle est la durée normale du QRS ?","answer":"70 à 110 ms","accept":["70 à 110","70-110","70 et 110","moins de 110","< 110","70-110 ms","moins de 110 ms","< 110 ms"],"keywords":["110"],"explanation":"Un QRS normal dure entre 70 et 110 ms ; il est dit « fin ». Un QRS > 120 ms est large.","src":"p. 375","deep":"**Pourquoi** : 70 à 110 ms est la norme du tableau 15.2 ; le QRS est fin quand les ventricules sont activés par les voies de conduction (His, branches, Purkinje), alors qu'une propagation de proche en proche l'élargit (p. 375, 398).\n**Piège** : 110-120 ms = bloc incomplet (rang B) ; > 120 ms = bloc de branche complet ; hémibloc = QRS > 110 ms avec déviation axiale (p. 378, 381-382).\n**À relier** : à ne pas confondre avec le PR (120-200 ms) (p. 375)."},{"id":"231-qroc-715","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Quelles sont les deux limites (durée et amplitude relative) d'une onde Q physiologique ?","answer":"Durée < 40 ms et amplitude < 1/3 du QRS","accept":["< 40 ms","moins de 40 ms","40 ms et","< 40 ms et < 1/3","40 ms et 1/3","moins de 40 ms et moins du tiers"],"keywords":["40"],"explanation":"Une onde Q est physiologique si elle dure moins de 40 ms et fait moins du tiers de l'amplitude du QRS ; une Q large et profonde évoque une nécrose.","src":"p. 375, 377","deep":"**Pourquoi** : la Q septale normale est fine et peu profonde (< 40 ms et < 1/3 du QRS) ; une Q large (> 40 ms) et profonde (> 1/3 du QRS) est une onde Q de nécrose (p. 375, 377).\n**Piège** : il faut les deux critères ; au chapitre SCA, la Q de nécrose est décrite à au moins 1/3 (ou 1/4) du QRS et > 30-40 ms (p. 412).\n**À relier** : une HVG importante peut donner un aspect QS en V1-V2 qui mime une séquelle d'infarctus (pseudonécrose) (p. 406)."},{"id":"231-qroc-716","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":2,"question":"Que désigne le « rythme cardiaque » sur l'ECG ?","answer":"Le mécanisme à l'origine des battements ventriculaires (QRS)","accept":["mécanisme à l'origine des qrs","mécanisme électrophysiologique","origine des battements","origine des qrs","origine des battements ventriculaires","ce qui déclenche les qrs","mécanisme à l'origine des battements"],"keywords":["mecanisme"],"explanation":"Le rythme est le mécanisme électrophysiologique qui déclenche les QRS : automatisme normal, trouble du rythme, étage atrial, jonctionnel, ventriculaire, ou électroentraînement.","src":"p. 376","deep":"**Pourquoi** : le rythme est le mécanisme électrophysiologique qui déclenche les QRS : automatisme normal ou trouble du rythme, d'origine atriale, jonctionnelle, ventriculaire, ou électroentraînement (p. 376).\n**Piège** : rythme ≠ fréquence : on peut avoir des P sinusales régulières sans rythme sinusal (BAV3) (p. 376).\n**À relier** : le rythme sinusal est le rythme physiologique car le nœud sinusal est le pacemaker dominant (p. 376)."},{"id":"231-qroc-717","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","pièges"],"difficulty":2,"question":"Pourquoi des ondes P régulières n'impliquent-elles pas toujours un rythme sinusal (exemple du BAV3) ?","answer":"Elles peuvent n'être pas conduites aux ventricules (pas de QRS après chaque P)","accept":["pas conduites","non conduites","sans conduction","pas suivie d'un qrs","pas suivies d'un qrs","non conduite","p non conduites","pas suivies de qrs","dissociées des qrs"],"keywords":["conduit"],"explanation":"En rythme sinusal, chaque P est suivie d'un QRS et chaque QRS précédé d'une P. Des P sinusales régulières sans conduction ventriculaire (BAV3) ne constituent pas un rythme sinusal.","src":"p. 376","deep":"**Pourquoi** : le rythme sinusal exige que le nœud sinusal commande les ventricules : chaque P suivie d'un QRS et chaque QRS précédé d'une P ; dans le BAV3, les P ne sont pas conduites (p. 376).\n**Piège** : dans le BAV, les P sont régulières à fréquence normale : ne conclus pas « sinusal » sans vérifier le lien P-QRS (p. 385).\n**À relier** : devant une bradycardie : P plus nombreuses que les QRS = BAV ; P lentes ou absentes = dysfonction sinusale (p. 389)."},{"id":"231-qroc-718","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Quelle phase de la dépolarisation ventriculaire donne la grande onde R en V3, V4 et D2 ?","answer":"La 2e phase (vers la jambe gauche et l'avant)","accept":["2e phase","deuxième phase","2eme phase","seconde phase","phase 2","2e"],"keywords":[],"explanation":"La séquence comporte 3 phases : septale (petite R en V1, Q fine latérale), puis phase dirigée vers la jambe gauche et l'avant (grande R en V3-V4 et D2), puis phase vers le haut et l'arrière (petite S).","src":"p. 376","deep":"**Pourquoi** : le QRS a 3 phases : 1) septale vers l'avant, la droite et le haut ; 2) vers la jambe gauche et l'avant, grande R en V3-V4 et D2 ; 3) vers le haut et l'arrière, petite S (p. 376).\n**Piège** : la petite R de V1 et la Q fine latérale viennent de la 1re phase (septale), pas de la 2e.\n**À relier** : cette séquence explique l'aspect polyphasique du QRS et la transition normale de V1 à V6 (R croissante, S décroissante) (p. 376, 378)."},{"id":"231-qroc-719","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Chez l'adulte, entre quelles valeurs se situe la fréquence cardiaque normale de repos ?","answer":"Entre 60 et 100 bpm","accept":["60 à 100","60-100","60 et 100","entre 60 et 100","60 à 100 bpm","60-100 bpm","60 et 100 bpm","de 60 à 100 bpm","entre 60 et 100 battements par minute"],"keywords":["60","100"],"explanation":"Au repos, l'adulte a normalement 60 à 100 bpm : en dessous de 60 bpm on parle de bradycardie, au-dessus de 100 bpm de tachycardie.","src":"p. 376","deep":"**Pourquoi** : 60-100 bpm est la norme de repos de l'adulte : < 60 = bradycardie, > 100 = tachycardie (p. 376).\n**Piège** : attention au nouveau-né (normes différentes) ; l'algorithme diagnostique de bradycardie part d'une FC des QRS < 50 bpm (p. 389), et une bradycardie de l'athlète peut être physiologique (p. 376).\n**À relier** : FC = 60 / RR (s), ou 300 / nombre de grands carreaux (p. 376)."},{"id":"231-qroc-720","type":"QROC","rank":"A","objective":"231-obj-12","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Pourquoi la fréquence sinusale peut-elle varier avec la respiration chez le sujet jeune sans que ce soit pathologique ?","answer":"Innervation neurovégétative importante (tonus sympathique et parasympathique)","accept":["innervation neurovégétative","neurovégétative","neurovegetative","système nerveux autonome","tonus parasympathique","arythmie sinusale respiratoire","tonus vagal","système neurovégétatif","innervation autonome"],"keywords":["neurov"],"explanation":"La fréquence du nœud sinusal est soumise aux variations du tonus sympathique et parasympathique ; l'innervation neurovégétative importante du sujet jeune explique cette variation respiratoire physiologique.","src":"p. 376","deep":"**Pourquoi** : la fréquence sinusale est modulée par les tonus sympathique et parasympathique ; chez le sujet jeune, l'innervation neurovégétative importante la fait varier avec la respiration, sans pathologie (p. 376).\n**Piège** : cette variation progressive est le propre du sinus : une tachycardie supraventriculaire non sinusale change de fréquence en « marches d'escalier » (p. 391).\n**À relier** : même mécanisme pour la bradycardie sinusale physiologique de l'athlète (tonus vagal) (p. 376)."},{"id":"231-qroc-721","type":"QROC","rank":"A","objective":"231-obj-22","tags":["ECG","définition"],"difficulty":1,"question":"Quel phénomène l'intervalle QT explore-t-il ?","answer":"La durée de la repolarisation (ventriculaire)","accept":["repolarisation","la repolarisation","repolarisation ventriculaire","durée de la repolarisation"],"keywords":["repolarisation"],"explanation":"Le QT va du début de Q à la fin de T et reflète la durée de la repolarisation, alors que le PR explore toute la conduction de l'oreillette aux extrémités du réseau de Purkinje.","src":"p. 376","deep":"**Pourquoi** : le QT, du début de Q à la fin de T, englobe la dépolarisation puis la repolarisation ventriculaire : il sert à apprécier la durée de la repolarisation (p. 376).\n**Piège** : l'onde U (2e onde de repolarisation) ne doit pas être incluse dans la mesure (p. 377).\n**À relier** : un QT long expose à la torsade de pointes ; causes : hypoK, hypoCa, hypoMg, médicaments, congénital, bradycardie extrême (p. 404)."},{"id":"231-qroc-722","type":"QROC","rank":"A","objective":"231-obj-22","tags":["ECG","méthode"],"difficulty":2,"question":"Comment repère-t-on la fin de l'onde T pour mesurer l'intervalle QT ?","answer":"En traçant la tangente à l'onde T","accept":["tangente","tracer la tangente","tangente à l'onde t","méthode de la tangente","tracer la tangente à t","tangente de t"],"keywords":["tangente"],"explanation":"On mesure le QT dans la dérivation où T est la plus ample et la plus longue (souvent V2-V3), en traçant la tangente à l'onde T ; l'onde U éventuelle est exclue.","src":"p. 376-377","deep":"**Pourquoi** : la fin de l'onde T est progressive et difficile à situer : on trace la tangente à sa pente descendante, dans la dérivation où T est la plus ample et la plus longue, souvent V2-V3 (p. 376).\n**Piège** : une onde U présente ne doit pas être intégrée dans la mesure du QT (p. 377).\n**À relier** : le QT mesuré doit ensuite être corrigé selon la fréquence (Bazett) (p. 377)."},{"id":"231-qroc-723","type":"QROC","rank":"A","objective":"231-obj-22","tags":["ECG","définition"],"difficulty":2,"question":"Pourquoi normalise-t-on le QT avec la formule de Bazett plutôt que d'utiliser des abaques ?","answer":"Le QT varie avec la fréquence : une seule norme à 60 bpm","accept":["une seule norme","varie avec la fréquence","variabilité","norme unique","60 bpm","dépend de la fréquence","varie avec fc","norme unique à 60 bpm","pour avoir une seule norme"],"keywords":["norme"],"explanation":"Comme le QT dépend de la fréquence cardiaque, le QTc de Bazett ramène la mesure à une fréquence de 60 bpm et permet de ne retenir qu'une seule norme.","src":"p. 377","deep":"**Pourquoi** : le QT varie avec la fréquence cardiaque ; Bazett (QTc = QT / √RR en secondes) ramène la mesure à 60 bpm, ce qui donne une seule norme plutôt que des abaques (p. 377).\n**Piège** : le QTc n'est proche du QT mesuré qu'autour de 60 bpm (RR ≈ 1 s) (p. 377-378).\n**À relier** : norme : QTc < 450 ms à 60 bpm, en pratique 470-480 ms (tableau 15.2, p. 375)."},{"id":"231-qroc-724","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","méthode"],"difficulty":1,"question":"Quels sont les volets de l'analyse systématique pour affirmer qu'un ECG est normal ?","answer":"Rythme, conduction, repolarisation, morphologie","accept":["rythme, conduction, repolarisation","rythme conduction repolarisation","rythme, conduction, repolarisation et morphologie","rythme conduction repolarisation morphologie","rythme, conduction, repolarisation, morphologie"],"keywords":["rythme","conduction","repolarisation"],"explanation":"Le Collège insiste sur la méthode systématique : rythme, conduction (P, PR, QRS, axe), repolarisation (point J, ST, T, QT) et morphologie (amplitudes, Sokolow, transition, absence d'onde Q de nécrose).","src":"p. 377","deep":"**Pourquoi** : le Collège insiste : la seule façon d'affirmer qu'un ECG est normal est d'être systématique, en 4 volets (p. 377).\n**Piège** : ne t'arrête pas à la première anomalie trouvée, et décris le rythme avant tout trouble de conduction (p. 378).\n**À relier** : rythme (sinusal 60-100) ; conduction (P < 120 ms, PR 120-200, QRS 70-110, axe -30/+90) ; repolarisation (J et ST isoélectriques, T, QT < 450) ; morphologie (Sokolow < 35 mm, transition, pas de Q de nécrose) (p. 377)."},{"id":"231-qroc-725","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Qu'appelle-t-on le « point J » ?","answer":"Le point qui termine le QRS","accept":["fin du qrs","termine le qrs","fin de qrs","point qui termine","jonction qrs-st","fin du qrs et début du st","fin du complexe qrs"],"keywords":["qrs"],"explanation":"Le point J marque la fin du QRS et le début du segment ST ; sur un ECG normal, point J et segment ST sont isoélectriques.","src":"p. 377","deep":"**Pourquoi** : le point J marque la fin du QRS et le début du ST : c'est le repère pour juger un sus- ou sous-décalage du ST (p. 377).\n**Piège** : chez le jeune, surtout l'homme, un J sus-décalé de V1 à V4 avec ST ascendant est une repolarisation physiologique, pas un SCA (p. 377).\n**À relier** : sus-ST significatif : ≥ 2 mm en V1-V3, ≥ 1 mm ailleurs, sur au moins 2 dérivations adjacentes (p. 412)."},{"id":"231-qroc-726","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Sur un ECG normal, quel doit être l'aspect du point J et du segment ST ?","answer":"Isoélectriques","accept":["isoélectrique","isoelectrique","isoélectriques","sur la ligne de base","plat"],"keywords":["isoel"],"explanation":"Dans le volet « repolarisation » de l'analyse, le point J et le ST doivent être isoélectriques, les ondes T positives (sauf aVR et V1) et le QT < 450 ms.","src":"p. 377","deep":"**Pourquoi** : sur un ECG normal, la repolarisation ne crée aucun décalage : point J et ST sont isoélectriques (p. 377).\n**Piège** : exception physiologique : ST jonctionnel sus-décalé en V1-V4 chez le jeune homme (p. 377) ; à l'inverse un ECG normal n'élimine pas un SCA sans ST (p. 412).\n**À relier** : autres critères de repolarisation normale : T positives sauf aVR et V1 (parfois D3, aVL), QT < 450 ms (p. 377)."},{"id":"231-qroc-727","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","pièges"],"difficulty":2,"question":"Outre aVR et V1, dans quelles dérivations une onde T négative peut-elle s'observer sur un ECG normal ?","answer":"Parfois en D3 et aVL","accept":["d3","avl","d3 et avl","dIII","d3 ou avl","avl et d3","iii et avl"],"keywords":[],"explanation":"Les ondes T sont positives partout sauf en aVR et V1, et parfois en D3 et aVL selon l'orientation anatomique du cœur.","src":"p. 377, 411","deep":"**Pourquoi** : la polarité des T suit globalement celle des QRS ; selon l'orientation anatomique du cœur, une T peut être négative en D3 ou aVL, en plus d'aVR et V1 (p. 377, 411).\n**Piège** : une T négative isolée peut être normale, mais deux T négatives dans un même territoire (ex. D2 et D3) sont pathologiques (p. 411).\n**À relier** : cette concordance T/QRS vient du sens inverse de la dépolarisation (endocarde → épicarde) et de la repolarisation (épicarde → endocarde) (p. 371, rang B)."},{"id":"231-qroc-728","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","pièges"],"difficulty":2,"question":"Combien d'ondes T négatives dans un même territoire suffisent à parler de pathologie ?","answer":"Deux (exemple : D2 et D3, territoire inférieur)","accept":["deux","2 ondes","2 t","d2 et d3","2","2 dérivations","deux ondes t négatives"],"keywords":[],"explanation":"Une onde T négative isolée peut être normale (D3, aVL), mais deux ondes T négatives dans le même territoire, par exemple D2 et D3, signent une pathologie.","src":"p. 411","deep":"**Pourquoi** : une T négative isolée peut tenir à l'orientation du cœur (D3, aVL), alors que deux T négatives dans un même territoire traduisent une anomalie de la paroi correspondante (p. 411).\n**Piège** : D3 seul négatif peut être normal ; D2 + D3 négatifs (inférieur) ne l'est pas.\n**À relier** : dans un SCA sans ST, l'inversion des T traduit une ischémie sous-épicardique (p. 412)."},{"id":"231-qroc-729","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","méthode"],"difficulty":2,"question":"Que vérifie-t-on de V1 à V6 pour s'assurer du bon positionnement des électrodes précordiales et d'une morphologie ventriculaire normale ?","answer":"La transition : onde R croissante et onde S décroissante","accept":["transition","r qui grandit","onde r qui grandit","r croissante","la transition","transition r/s","onde r croissante"],"keywords":["transition"],"explanation":"La transition normale de V1 à V6 voit l'onde R grandir progressivement et l'onde S diminuer progressivement.","src":"p. 378","deep":"**Pourquoi** : de V1 à V6, l'onde R grandit et l'onde S diminue progressivement : une transition normale atteste à la fois du bon placement des précordiales et d'une morphologie ventriculaire normale (p. 378).\n**Piège** : V1-V2 trop hautes et trop écartées peuvent créer une fausse pseudonécrose ou une atypie de repolarisation antérieure (p. 373).\n**À relier** : les précordiales doivent être isodistantes (p. 373)."},{"id":"231-qroc-730","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","définition"],"difficulty":1,"question":"Comment définit-on un bloc de branche ?","answer":"Interruption ou ralentissement marqué de la conduction dans une branche","accept":["interruption","ralentissement marqué","ralentissement de la conduction","interruption de la conduction","retard de conduction dans une branche","bloc de la conduction dans une branche"],"keywords":["branche"],"explanation":"Les blocs de branche correspondent à une interruption ou à un ralentissement marqué de la conduction dans l'une des deux branches du faisceau de His.","src":"p. 378","deep":"**Pourquoi** : si une branche du His est interrompue ou très ralentie, le ventricule correspondant est activé tardivement, de proche en proche, d'où un QRS > 120 ms (p. 378).\n**Piège** : les blocs de branche ne donnent pas de bradycardie (points clés, p. 415) : une bradycardie relève du nœud sinusal ou du NAV.\n**À relier** : V1 globalement positif = BBD, négatif = BBG, aspect inverse en V6 (p. 381)."},{"id":"231-qroc-731","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","pièges"],"difficulty":2,"question":"Pourquoi faut-il décrire le rythme atrial avant de décrire un bloc de branche ?","answer":"Pour ne pas méconnaître une tachycardie supraventriculaire associée","accept":["tachycardie supraventriculaire","tsv","ne pas passer à côté","tachycardie supra","ne pas manquer une tachycardie supraventriculaire","tachycardie atriale"],"keywords":["supra"],"explanation":"L'association d'une tachycardie supraventriculaire et d'un bloc de branche n'est pas rare : il faut d'abord analyser le rythme.","src":"p. 378","deep":"**Pourquoi** : l'association tachycardie supraventriculaire + bloc de branche n'est pas rare : si on regarde d'emblée les QRS larges, on peut manquer une FA ou un flutter sous-jacent (p. 378).\n**Piège** : devant des QRS larges, ne confonds pas un bloc de branche (sans conséquence immédiate) avec une TV (mortelle si non prise en charge) (p. 415).\n**À relier** : FA + bloc de branche (préexistant ou fonctionnel) = tachycardie irrégulière à QRS larges (p. 393)."},{"id":"231-qroc-732","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Que traduit le deuxième pic du notch observé en V6, D1 et aVL dans le BBG ?","answer":"L'activation tardive de la paroi latérale (le 1er pic = le septum)","accept":["paroi latérale","activation latérale tardive","latérale tardive","paroi latérale tardive","paroi latérale du vg","activation tardive de la paroi latérale","latéral tardif"],"keywords":["lat"],"explanation":"Le notch est un double pic : le premier correspond à l'activation du septum, le second à celle de la paroi latérale, tardive.","src":"p. 380","deep":"**Pourquoi** : en BBG, le septum est activé d'abord (1er pic), puis la paroi latérale, en retard faute de branche gauche (2e pic) : c'est le notch en V6, D1, aVL (p. 380).\n**Piège** : ce retard d'activation de la paroi latérale désynchronise le VG et peut créer ou aggraver une insuffisance cardiaque (p. 383, rang B).\n**À relier** : en V1 le BBG est négatif (rS ou QS) (p. 380)."},{"id":"231-qroc-733","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","pièges"],"difficulty":2,"question":"Dans un bloc de branche, quel diagnostic la discordance appropriée associée à un ST ascendant en V1-V2 peut-elle faire évoquer à tort ?","answer":"Un SCA avec sus-décalage du segment ST","accept":["sca avec sus-décalage","sca st+","sca st +","sus-décalage du st","infarctus","sca avec sus-décalage de st","sus-décalage de st","infarctus antérieur"],"keywords":[],"explanation":"Chez un patient avec bloc de branche, la repolarisation de la région antérieure est difficile à interpréter : le tableau peut simuler un SCA ST+, d'où l'importance de la clinique.","src":"p. 381","deep":"**Pourquoi** : un QRS large entraîne une repolarisation secondairement anormale : T de polarité opposée au QRS (discordance appropriée) ; avec un ST souvent ascendant en V1-V2, cela peut simuler un SCA ST+ (p. 381).\n**Piège** : QRS négatif → T positive avec souvent petit sus-ST ; QRS positif → T négative avec petit sous-ST : c'est attendu, pas forcément ischémique (p. 381).\n**À relier** : même difficulté avec la stimulation ventriculaire et l'HVG marquée, cités comme diagnostics différentiels du sus-ST (p. 412)."},{"id":"231-qroc-734","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","urgence","pièges"],"difficulty":2,"question":"Devant une douleur thoracique persistante avec un BBG, que faut-il faire sans attendre le dosage de troponine ?","answer":"Une évaluation rapide par un cardiologue (recherche d'arguments pour un SCA)","accept":["cardiologue","avis cardiologique","évaluation rapide","évaluation cardiologique","avis cardiologique rapide","appel du cardiologue","évaluation par un cardiologue"],"keywords":["cardiolog"],"explanation":"Le diagnostic d'infarctus antérieur doit être évoqué et conduire à une évaluation cardiologique rapide, sans attendre la troponine.","src":"p. 381","deep":"**Pourquoi** : en BBG, la repolarisation antérieure est ininterprétable ; attendre la troponine ferait perdre du temps : douleur persistante + BBG = évoquer un infarctus antérieur et faire évaluer rapidement par un cardiologue (p. 381).\n**Piège** : un BBG en contexte de douleur thoracique aiguë doit faire éliminer un SCA ST+ (échographie ± coronarographie) (p. 412).\n**À relier** : arguments à chercher : sémiologie de la douleur (effet de la TNT), signes de choc, ETT (p. 381)."},{"id":"231-qroc-735","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":3,"question":"Citez deux éléments à rechercher, devant une douleur thoracique avec BBG, pour étayer un SCA.","answer":"Sémiologie de la douleur (effet de la TNT), signes de choc, ETT","accept":["tnt","trinitrine","effet de la tnt","signes de choc","choc","ett","échographie","sémiologie de la douleur","analyse de la douleur","echographie cardiaque","effet de la trinitrine"],"keywords":[],"explanation":"Faute de pouvoir interpréter la repolarisation antérieure, on analyse la douleur (dont l'effet de la trinitrine), on cherche des signes de choc et on réalise une échographie transthoracique.","src":"p. 381","deep":"**Pourquoi** : comme l'ECG ne tranche pas en BBG, le cardiologue s'appuie sur la clinique et l'écho : analyse de la douleur dont l'effet de la trinitrine, signes de choc, ETT (p. 381).\n**Piège** : la troponine n'est pas l'élément à attendre dans cette situation (p. 381).\n**À relier** : p. 412 : BBG + douleur thoracique aiguë = éliminer un SCA ST+ (échographie ± coronarographie)."},{"id":"231-qroc-736","type":"QROC","rank":"B","objective":"231-obj-07","tags":["ECG","définition"],"difficulty":1,"question":"Quelle durée de QRS caractérise un bloc de branche incomplet ?","answer":"Entre 110 et 120 ms","accept":["110 et 120","110-120","110 à 120","entre 110 et 120","entre 110 et 120 ms","110 à 120 ms","110-120 ms"],"keywords":["110","120"],"explanation":"Un bloc incomplet reproduit les anomalies du bloc complet avec un QRS de 110 à 120 ms ; il présente peu d'intérêt sémiologique.","src":"p. 381","deep":"**Pourquoi** : le bloc incomplet reproduit les mêmes anomalies morphologiques que le bloc complet, avec un QRS seulement entre 110 et 120 ms ; son intérêt sémiologique est faible (p. 381).\n**Piège** : > 120 ms = complet ; 110-120 ms = incomplet ; un QRS > 110 ms avec déviation axiale évoque un hémibloc (p. 378, 382).\n**À relier** : un bloc incomplet isolé montre une atteinte débutante mais un risque faible de BAV infrahissien (p. 383)."},{"id":"231-qroc-737","type":"QROC","rank":"B","objective":"231-obj-07","tags":["ECG","définition"],"difficulty":1,"question":"Comment qualifie-t-on un bloc de branche qui n'existe qu'à partir d'une certaine fréquence cardiaque ?","answer":"Un bloc fonctionnel","accept":["fonctionnel","bloc fonctionnel","aberration de conduction"],"keywords":["fonctionnel"],"explanation":"Un bloc de branche, ou tout autre bloc de conduction, est dit fonctionnel s'il n'apparaît qu'à partir d'une fréquence donnée.","src":"p. 381","deep":"**Pourquoi** : un bloc fonctionnel n'existe qu'à partir d'une fréquence donnée : le BBG ou BBD apparaît lors d'une tachycardie ou d'une bradycardie (p. 381).\n**Piège** : un QRS large apparu en tachycardie n'est pas forcément permanent ; mais toute tachycardie régulière à QRS larges reste une TV jusqu'à preuve du contraire (p. 398).\n**À relier** : en FA, le bloc de branche est fréquent, préexistant ou fonctionnel (p. 393)."},{"id":"231-qroc-738","type":"QROC","rank":"B","objective":"231-obj-07","tags":["ECG","définition"],"difficulty":2,"question":"Un bloc de branche fonctionnel peut apparaître lors de quelles variations de la fréquence cardiaque ?","answer":"Lors d'une tachycardie ou d'une bradycardie","accept":["tachycardie","bradycardie","tachycardie et bradycardie","lors d'une tachycardie","lors d'une bradycardie"],"keywords":[],"explanation":"Un bloc fonctionnel apparaît à partir d'une fréquence donnée : lors d'une tachycardie ou d'une bradycardie. En FA, le bloc de branche peut être préexistant ou fonctionnel (apparaissant uniquement en tachycardie).","src":"p. 381, 393","deep":"**Pourquoi** : le bloc fonctionnel dépend de la fréquence : il apparaît lors d'une tachycardie ou d'une bradycardie (p. 381).\n**Piège** : en FA, le Collège décrit le bloc fonctionnel « apparaissant uniquement en tachycardie », donnant une tachycardie irrégulière à QRS larges (p. 393).\n**À relier** : devant QRS larges, décrire d'abord le rythme atrial (p. 378)."},{"id":"231-qroc-739","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","définition"],"difficulty":2,"question":"Quel aspect du QRS caractérise les hémiblocs, en dehors de la déviation axiale ?","answer":"Un élargissement très modéré (> 110 ms)","accept":["très modéré","modéré","110","élargissement très modéré","élargissement modéré","qrs un peu élargi","peu élargi"],"keywords":["modere"],"explanation":"Les hémiblocs donnent un élargissement très modéré du QRS (> 110 ms), qui peut dépasser 120 ms en cas de bloc de branche associé ou de cardiopathie marquée, plus une déviation axiale.","src":"p. 382","deep":"**Pourquoi** : une hémibranche bloquée retarde peu l'activation globale (QRS > 110 ms, très modérément élargi) mais change sa direction : déviation axiale (p. 382).\n**Piège** : le QRS peut dépasser 120 ms si un bloc de branche est associé ou en cas de cardiopathie marquée (p. 382).\n**À relier** : points clés : bloc de branche = durée du QRS ; hémibloc = axe du QRS (p. 415)."},{"id":"231-qroc-740","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Pourquoi l'hémibloc postérieur gauche est-il rare ?","answer":"Sa branche est profonde, donc protégée","accept":["branche profonde","profonde","est profonde","branche postérieure profonde","branche profonde et protégée"],"keywords":["profond"],"explanation":"L'HBAG est fréquent car la branche antérieure est fragile (superficielle et petite) ; l'HBPG est rare car la branche postérieure est profonde.","src":"p. 383","deep":"**Pourquoi** : la branche postérieure gauche est profonde, donc protégée : l'HBPG est rare ; l'antérieure, superficielle et petite, est fragile : l'HBAG est fréquent (p. 383).\n**Piège** : parce qu'il est rare, l'HBPG est un diagnostic d'exclusion : inversion d'électrodes, atteinte du VD, longiligne, infarctus latéral d'abord (p. 382-383).\n**À relier** : HBAG = axe au-delà de -30° (D2 négatif) ; HBPG = axe > +90° (D1 négatif, S1Q3) (p. 382)."},{"id":"231-qroc-741","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","pièges"],"difficulty":3,"question":"Citez deux situations à éliminer avant d'attribuer une déviation axiale droite à un hémibloc postérieur gauche.","answer":"Pathologie du VD, morphologie longiligne, infarctus latéral","accept":["pathologie du ventricule droit","pathologie du vd","hvd","longiligne","infarctus latéral","hypertrophie ventriculaire droite","sujet longiligne","infarctus lateral","patient longiligne"],"keywords":[],"explanation":"L'HBPG ne se retient qu'en l'absence de pathologie du ventricule droit, de morphologie longiligne ou d'infarctus latéral.","src":"p. 382","deep":"**Pourquoi** : une déviation axiale droite a des causes plus fréquentes que l'HBPG : pathologie du VD, morphologie longiligne, infarctus latéral (p. 382).\n**Piège** : le même aspect se voit dans l'HVD et comme variante normale chez le longiligne (p. 407, rang B) ; et un D1 négatif fait d'abord penser à une inversion d'électrodes (p. 383).\n**À relier** : HBPG rare car branche profonde (p. 383)."},{"id":"231-qroc-742","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","pièges"],"difficulty":2,"question":"Devant un QRS négatif en D1, quel est le premier diagnostic à évoquer, avant un HBPG ?","answer":"Une inversion des électrodes frontales","accept":["inversion des électrodes","inversion de positionnement","électrodes inversées","inversion des électrodes frontales","erreur de branchement","inversion des électrodes des bras","inversion bras droit et gauche"],"keywords":["invers"],"explanation":"Un D1 négatif doit d'abord faire penser à une erreur de branchement des électrodes des membres, et non à un hémibloc postérieur.","src":"p. 383","deep":"**Pourquoi** : l'HBPG est rare ; une erreur de branchement des électrodes frontales est plus probable et doit être éliminée en premier (p. 383).\n**Piège** : l'indice qui trahit l'inversion : la P est aussi négative en D1 (p. 383).\n**À relier** : une P sinusale normale est positive en D1 et en inférieur (p. 376)."},{"id":"231-qroc-743","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","pièges"],"difficulty":2,"question":"Quel signe renforce l'hypothèse d'une inversion des électrodes frontales devant un QRS négatif en D1 ?","answer":"Une onde P également négative en D1","accept":["p négative","onde p négative","p également négative","p aussi négative","p négative en d1","onde p négative en d1","p inversée"],"keywords":["negati"],"explanation":"En cas d'inversion des électrodes frontales, l'onde P est elle aussi négative en D1, ce qui n'est pas le cas dans un hémibloc.","src":"p. 383","deep":"**Pourquoi** : l'activation des oreillettes reste normale dans un hémibloc : la P sinusale garde sa positivité en D1 ; si P ET QRS sont négatifs en D1, ce sont les électrodes qui sont inversées (p. 383).\n**Piège** : ne pose pas un HBPG (rare) sur un simple D1 négatif (p. 383).\n**À relier** : P sinusale : axe à 60°, positive en D1, D2 (p. 375-376)."},{"id":"231-qroc-744","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","définition"],"difficulty":1,"question":"Qu'associe un bloc bifasciculaire ?","answer":"Un hémibloc (antérieur ou postérieur gauche) et un bloc de branche droit","accept":["hbag + bbd","hbpg + bbd","hémibloc et bbd","hémibloc + bbd","hémibloc + bloc de branche droit","hémibloc et bloc de branche droit","hémibloc et un bloc de branche droit","bbd + hbag","bbd + hbpg","hemibloc + bbd","hémibloc antérieur ou postérieur gauche et bbd","bloc de branche droit et hémibloc"],"keywords":["hemibloc"],"explanation":"La sémiologie s'additionne : HBAG + BBD ou HBPG + BBD, avec un QRS supérieur à 120 ms.","src":"p. 383","deep":"**Pourquoi** : deux des trois voies de conduction ventriculaire sont atteintes : la sémiologie s'additionne, HBAG + BBD ou HBPG + BBD, avec QRS > 120 ms (p. 383).\n**Piège** : l'encadré « Pour comprendre » range aussi le BBG complet parmi les blocs bifasciculaires (p. 383, rang B) ; ne réduis pas le risque à la seule forme BBD + hémibloc.\n**À relier** : syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie (risque de BAV complet infrahissien) (p. 383, rang B)."},{"id":"231-qroc-745","type":"QROC","rank":"B","objective":"231-obj-06","tags":["ECG","complications"],"difficulty":2,"question":"Quel risque évolutif justifie l'attention portée à un bloc bifasciculaire ?","answer":"Un BAV complet infrahissien (syncope, mort subite)","accept":["bav complet","bav infrahissien","bloc atrioventriculaire complet","troisième branche","3e branche","bav complet infrahissien","bav3","bloc atrioventriculaire complet infrahissien"],"keywords":["bav"],"explanation":"Le bloc bifasciculaire fait craindre une défaillance intermittente de la troisième branche, donc un BAV complet infrahissien pouvant induire syncopes voire mort subite.","src":"p. 383","deep":"**Pourquoi** : avec deux fascicules atteints, il ne reste qu'une voie : si elle lâche de façon intermittente, c'est un BAV complet infrahissien, avec syncope voire mort subite (p. 383).\n**Piège** : le risque est faible pour un hémibloc isolé ou un bloc incomplet ; il est plus important pour un bloc bifasciculaire (BBG complet ou BBD + hémibloc) (p. 383).\n**À relier** : syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie (p. 383) ; BAV infrahissien = pacemaker même sans symptôme (p. 412)."},{"id":"231-qroc-746","type":"QROC","rank":"B","objective":"231-obj-06","tags":["ECG","complications"],"difficulty":2,"question":"Quelle est la probabilité de BAV infrahissien en cas d'hémibloc isolé ou de bloc incomplet ?","answer":"Faible (le reste du réseau est fonctionnel)","accept":["faible","peu probable","risque faible","probabilité faible","faible probabilité"],"keywords":["faible"],"explanation":"Un hémibloc isolé ou un bloc incomplet montre une atteinte débutante des voies de conduction, mais le reste du réseau semble fonctionnel, donc le risque de BAV infrahissien est faible.","src":"p. 383","deep":"**Pourquoi** : l'hémibloc isolé ou le bloc incomplet montre une atteinte débutante des voies de conduction, mais le reste du réseau semble fonctionnel : le risque de BAV infrahissien est faible (p. 383).\n**Piège** : leur intérêt est de signaler une atteinte débutante, pas un risque immédiat ; c'est le bloc bifasciculaire qui fait craindre un BAV complet (p. 383).\n**À relier** : syncope + bloc bifasciculaire = télémétrie (p. 383)."},{"id":"231-qroc-747","type":"QROC","rank":"B","objective":"231-obj-06","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Par quel mécanisme un BBG complet peut-il créer ou aggraver une cardiopathie ?","answer":"Désynchronisation de la contraction des parois ventriculaires","accept":["désynchronisation","desynchronisation","contraction désynchronisée","désynchronisation ventriculaire","contraction asynchrone","asynchronisme","dyssynchronie"],"keywords":["desynchro"],"explanation":"L'activation tardive de la paroi latérale désynchronise la contraction du VG et altère son efficacité hémodynamique.","src":"p. 383","deep":"**Pourquoi** : en BBG, la paroi latérale est activée tard : les parois du VG ne se contractent plus ensemble, ce qui altère l'efficacité hémodynamique de la contraction (p. 383).\n**Piège** : le BBG n'est donc pas seulement un « signe ECG » : il peut contribuer à créer ou aggraver une cardiopathie (p. 383, 413).\n**À relier** : sa correction (resynchronisation) est indiquée en cas d'apparition de signes d'insuffisance cardiaque (p. 383)."},{"id":"231-qroc-748","type":"QROC","rank":"B","objective":"231-obj-06","tags":["ECG","traitement"],"difficulty":2,"question":"Quelle correction est indiquée en cas de signes d'insuffisance cardiaque liés à un BBG complet désynchronisant ?","answer":"La resynchronisation cardiaque","accept":["resynchronisation","resynchronisation cardiaque","stimulation biventriculaire","crt","stimulateur de resynchronisation"],"keywords":["resynchro"],"explanation":"La correction du BBG, par resynchronisation cardiaque, peut améliorer voire guérir ce type de cardiopathie ; elle est indiquée dès l'apparition de signes d'insuffisance cardiaque.","src":"p. 383, 413","deep":"**Pourquoi** : le BBG désynchronise les parois du VG ; corriger ce retard par resynchronisation cardiaque peut améliorer, voire guérir, ce type de cardiopathie : indiquée en cas de signes d'insuffisance cardiaque (p. 383, 413).\n**Piège** : pacemaker = problème de bradycardie, défibrillateur = TV/FV, resynchronisation = problème hémodynamique ; la resynchronisation est un stimulateur, donc assure toujours la fonction pacemaker (fig. 15.60, p. 413).\n**À relier** : un défibrillateur de resynchronisation associe les trois fonctions (p. 413)."},{"id":"231-qroc-749","type":"QROC","rank":"A","objective":"231-obj-08","tags":["ECG","définition"],"difficulty":1,"question":"Quel est le siège habituel d'un BAV du 2e degré de type Mobitz 1 ?","answer":"Suprahissien (nodal)","accept":["suprahissien","supra-hissien","nodal","supra hissien","au niveau du nav"],"keywords":[],"explanation":"Le Mobitz 1 (Luciani-Wenckebach) est suprahissien, alors que le Mobitz 2 est infrahissien.","src":"p. 385","deep":"**Pourquoi** : le Mobitz 1 (Luciani-Wenckebach) : PR qui s'allonge progressivement puis P bloquée : siège suprahissien (fig. 15.20, p. 385).\n**Piège** : le Mobitz 2 (PR constant puis P bloquée inopinée) est infrahissien ; un BAV 2/1 peut être l'un ou l'autre (p. 385).\n**À relier** : pacemaker : Mobitz 1 seulement s'il est symptomatique, Mobitz 2 et BAV3 même sans symptôme (p. 412, rang B)."},{"id":"231-qroc-750","type":"QROC","rank":"A","objective":"231-obj-08","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quels éléments orientent vers un siège suprahissien devant un BAV 2/1 ?","answer":"QRS fins et épisodes de Mobitz 1 à d'autres moments","accept":["qrs fins","mobitz 1","mobitz i","wenckebach","qrs fins et mobitz 1","mobitz 1 par moments"],"keywords":["fins"],"explanation":"Dans un BAV 2/1, des QRS larges orientent vers un siège infrahissien, des QRS fins avec du Mobitz 1 à d'autres moments vers un siège suprahissien.","src":"p. 385","deep":"**Pourquoi** : des QRS fins suggèrent que l'influx, une fois passé, emprunte normalement le His et les branches : le blocage est plutôt au-dessus (suprahissien) ; du Mobitz 1, lui-même suprahissien, à d'autres moments renforce l'argument (p. 385).\n**Piège** : le rapport 2/1 seul ne permet pas de trancher : il peut être supra- ou infrahissien (fig. 15.20, p. 385).\n**À relier** : QRS larges = infrahissien, qui relève du pacemaker même sans symptôme (p. 412, rang B)."},{"id":"231-qroc-751","type":"QROC","rank":"A","objective":"231-obj-08","tags":["ECG","définition"],"difficulty":1,"question":"Que note-t-on sur les ondes P au cours d'un BAV ?","answer":"Elles sont régulières et à fréquence normale","accept":["régulières","regulieres","régulières et à fréquence normale","fréquence normale","régulières à fréquence normale","p régulières"],"keywords":["reguli"],"explanation":"Dans un BAV, l'activité atriale est normale : ondes P régulières et de fréquence normale, mais elles ne sont pas toutes conduites.","src":"p. 385","deep":"**Pourquoi** : dans un BAV, le nœud sinusal fonctionne : les P sont régulières à fréquence normale ; c'est leur passage au ventricule qui est bloqué, d'où plus de P que de QRS (p. 385, 389).\n**Piège** : des P régulières n'impliquent pas un rythme sinusal si elles ne sont pas conduites (BAV3) (p. 376) ; à l'inverse, P lentes ou absentes = dysfonction sinusale (p. 389).\n**À relier** : les P peuvent aussi être remplacées par une activité tachycarde (FA, flutter) associée au BAV (p. 389, 392)."},{"id":"231-qroc-752","type":"QROC","rank":"B","objective":"231-obj-10","tags":["ECG","définition"],"difficulty":2,"question":"Que traduisent des pauses par manque intermittent d'une onde P sur l'ECG ?","answer":"Un bloc sinoatrial intermittent du 2e degré","accept":["bloc sinoatrial","bsa","bloc sino-atrial","bloc sinoauriculaire","bloc sinoatrial du 2e degré","bsa 2","bloc sino-auriculaire"],"keywords":[],"explanation":"Des pauses avec absence complète du complexe P-QRS-T traduisent un bloc sinoatrial du 2e degré ; la pause correspond au double de l'intervalle PP ou RR habituel.","src":"p. 387","deep":"**Pourquoi** : dans le bloc sinoatrial du 2e degré, l'influx sinusal ne sort pas par intermittence : il manque un complexe P-QRS-T entier, et la pause vaut le double de l'intervalle PP ou RR (p. 387).\n**Piège** : dans un BAV, la P est présente mais non suivie de QRS ; dans le BSA, la P elle-même manque (p. 385, 387).\n**À relier** : BSA du 2e degré et maladie de l'oreillette = objectif de rang B (p. 368) ; l'asystole est l'autre aspect simple de dysfonction sinusale (p. 387)."},{"id":"231-qroc-753","type":"QROC","rank":"A","objective":"231-obj-10","tags":["ECG","définition"],"difficulty":1,"question":"Quel aspect a l'ECG d'une asystole ?","answer":"Un tracé plat, sans activité cardiaque visible","accept":["tracé plat","ligne plate","plat","sans activité","ligne isoélectrique","absence d'activité électrique"],"keywords":["plat"],"explanation":"L'asystole est l'un des aspects de dysfonction sinusale à l'analyse simple : tracé plat sans aucune activité cardiaque visible.","src":"p. 387","deep":"**Pourquoi** : l'asystole est l'absence de toute activité électrique : tracé plat, aucun complexe visible (p. 387).\n**Piège** : une pause du BSA est un manque transitoire d'un complexe P-QRS-T (double du PP) entouré de complexes normaux, pas un tracé plat (p. 387).\n**À relier** : l'asystolie est aussi l'aboutissement d'une TV puis FV non prises en charge (p. 398)."},{"id":"231-qroc-754","type":"QROC","rank":"A","objective":"231-obj-10","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Pourquoi l'onde P rétrograde d'un échappement jonctionnel est-elle négative en D2 ?","answer":"L'oreillette est activée de bas en haut à partir de la jonction","accept":["de bas en haut","bas en haut","activation rétrograde","sens ventriculoatrial","activation de bas en haut","sens rétrograde","oreillette activée de bas en haut"],"keywords":["bas","haut"],"explanation":"L'influx part de la jonction et remonte vers l'oreillette (sens ventriculoatrial) : l'activation atriale va de bas en haut, d'où une P' négative en D2.","src":"p. 388","deep":"**Pourquoi** : dans un échappement jonctionnel, l'oreillette est activée à rebours, de la jonction vers le haut (sens ventriculoatrial) : le vecteur s'éloigne de D2, d'où une P' négative (p. 388).\n**Piège** : une P sinusale est au contraire positive en D2 (activation du haut à droite vers le bas à gauche) (p. 375).\n**À relier** : la P' rétrograde se voit derrière le QRS, dans le ST (p. 388) ; même P' rétrograde possible dans les extrasystoles jonctionnelles et ventriculaires (p. 397)."},{"id":"231-qroc-755","type":"QROC","rank":"A","objective":"231-obj-10","tags":["ECG","diagnostic"],"difficulty":2,"question":"Où repère-t-on l'activité atriale lors d'un échappement jonctionnel par dysfonction sinusale ?","answer":"Derrière le QRS (dans le segment ST) : onde P' rétrograde","accept":["derrière le qrs","après le qrs","segment st","dans le st","p' rétrograde","dans le segment st","p' rétrograde derrière le qrs","activité atriale rétrograde"],"keywords":[],"explanation":"Pas d'onde P devant les QRS ni de P bloquée : l'activité atriale est visible derrière le QRS, dans le segment ST.","src":"p. 388","deep":"**Pourquoi** : l'échappement jonctionnel active d'abord le ventricule puis l'oreillette de façon rétrograde : la P' apparaît derrière le QRS, dans le segment ST (p. 388).\n**Piège** : pas d'onde P devant les QRS et pas de P bloquée : ce n'est pas un BAV (P bloquées) mais une dysfonction sinusale (p. 388).\n**À relier** : dans la réentrée intranodale aussi, l'activité atriale est cachée ou devinée dans le ST (p. 395)."},{"id":"231-qroc-756","type":"QROC","rank":"A","objective":"231-obj-10","tags":["ECG","diagnostic"],"difficulty":2,"question":"Citez deux aspects ECG possibles d'une dysfonction sinusale.","answer":"P trop lentes, pause (P manquante), P inexistante avec P' rétrograde","accept":["p trop lentes","ondes p lentes","pause sinusale","p manquante","onde p manquante","p inexistante","échappement jonctionnel","asystole","p' rétrograde","pauses","p trop lente","bradycardie sinusale","bloc sinoatrial","onde p inexistante"],"keywords":[],"explanation":"La dysfonction sinusale se présente par des ondes P trop lentes, une onde P manquante (pause sinusale) ou une onde P inexistante avec P' rétrograde dans l'échappement jonctionnel.","src":"p. 388","deep":"**Pourquoi** : le nœud sinusal défaillant peut être trop lent (P lentes), s'arrêter par moments (P manquante, pause) ou ne plus fonctionner (P inexistante, échappement jonctionnel avec P' rétrograde) (fig. 15.26, p. 388).\n**Piège** : ces aspects sont à distinguer du BAV, où les P sont normales mais non conduites (p. 389).\n**À relier** : algorithme : bradycardie → regarder les P (p. 389) ; asystole et BSA du 2e degré sont les cas d'analyse simple (p. 387)."},{"id":"231-qroc-757","type":"QROC","rank":"A","objective":"231-obj-12","tags":["ECG","définition"],"difficulty":2,"question":"Comment définit-on un trouble du rythme supraventriculaire ?","answer":"Activation trop rapide des oreillettes ou de la jonction AV (NAV ou His)","accept":["oreillettes ou de la jonction","oreillettes ou jonction","jonction atrioventriculaire","fréquence trop élevée","activation trop rapide des oreillettes","activation rapide de l'oreillette ou de la jonction","au-dessus de la bifurcation hissienne"],"keywords":["jonction"],"explanation":"Un trouble du rythme supraventriculaire est une activation à fréquence trop élevée des oreillettes ou de la jonction atrioventriculaire (NAV ou His).","src":"p. 389","deep":"**Pourquoi** : « supraventriculaire » = au-dessus de la bifurcation hissienne : activation trop rapide des oreillettes ou de la jonction AV (NAV, His) (p. 389).\n**Piège** : ces troubles sont à QRS fins dans la majorité des cas, mais peuvent avoir des QRS larges en cas de bloc de branche associé (p. 390).\n**À relier** : au-delà de la bifurcation hissienne, on parle de trouble du rythme ventriculaire (p. 389)."},{"id":"231-qroc-758","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","définition"],"difficulty":2,"question":"À partir de quelle structure anatomique parle-t-on de trouble du rythme ventriculaire ?","answer":"Au-delà de la bifurcation hissienne","accept":["bifurcation hissienne","bifurcation du his","au-delà de la bifurcation","sous la bifurcation","bifurcation du faisceau de his","sous la bifurcation du his","au delà de la bifurcation hissienne"],"keywords":["bifurcation"],"explanation":"Au-delà de la bifurcation hissienne, on parle de troubles du rythme ventriculaire ; ils naissent sous la bifurcation et ne passent donc pas par le réseau de conduction rapide.","src":"p. 389, 398","deep":"**Pourquoi** : la bifurcation hissienne sépare les étages : en dessous, la tachycardie ne passe plus par le réseau de conduction et se propage de proche en proche, d'où des QRS larges (p. 389, 398).\n**Piège** : la jonction (NAV, His) appartient encore au supraventriculaire (p. 389).\n**À relier** : toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire (p. 398)."},{"id":"231-qroc-759","type":"QROC","rank":"A","objective":"231-obj-12","tags":["ECG","définition"],"difficulty":2,"question":"En français, quel terme désigne les bradycardies, qui ne sont pas des « troubles du rythme » ?","answer":"Des troubles de la conduction","accept":["troubles de la conduction","trouble de la conduction","troubles conductifs"],"keywords":["conduction"],"explanation":"Le terme « trouble du rythme » est synonyme de tachycardie, supraventriculaire ou ventriculaire ; les bradycardies relèvent des troubles de la conduction.","src":"p. 390","deep":"**Pourquoi** : le Collège précise un point sémantique : « trouble du rythme » est synonyme de tachycardie (supra- ou ventriculaire) ; les bradycardies sont des troubles de la conduction (p. 390).\n**Piège** : un BAV ou une dysfonction sinusale n'est pas un « trouble du rythme » au sens français.\n**À relier** : les deux seules structures responsables de bradycardie : nœud sinusal et NAV (p. 389)."},{"id":"231-qroc-760","type":"QROC","rank":"A","objective":"231-obj-12","tags":["ECG","diagnostic"],"difficulty":2,"question":"Dans quelle situation un trouble du rythme supraventriculaire donne-t-il des QRS larges ?","answer":"En cas de trouble de conduction intraventriculaire associé (ex. bloc de branche)","accept":["bloc de branche","trouble de conduction intraventriculaire","conduction intraventriculaire","bloc de branche complet","bloc de branche fonctionnel","trouble de conduction"],"keywords":[],"explanation":"Les troubles du rythme supraventriculaires sont à QRS fins (< 120 ms) dans la majorité des cas, sauf s'ils s'associent à un bloc de branche complet par exemple.","src":"p. 390","deep":"**Pourquoi** : l'origine reste au-dessus du His, mais si la conduction intraventriculaire est anormale (bloc de branche complet, préexistant ou fonctionnel), les QRS s'élargissent (p. 390, 393).\n**Piège** : devant une tachycardie RÉGULIÈRE à QRS larges, on retient une TV jusqu'à preuve du contraire, même si une TSV avec bloc est possible (p. 398).\n**À relier** : FA + bloc de branche = tachycardie irrégulière à QRS larges (p. 393)."},{"id":"231-qroc-761","type":"QROC","rank":"B","objective":"231-obj-16","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Citez deux facteurs qui modulent l'intensité du filtre atrioventriculaire.","answer":"L'âge, le tonus vagal, les médicaments ralentisseurs du NAV","accept":["âge","tonus vagal","médicaments ralentisseurs","ralentisseurs du nav","médicaments","médicaments ralentisseurs du nav","bêtabloquants"],"keywords":[],"explanation":"L'intensité du filtre du NAV dépend de l'âge, du tonus vagal et des médicaments ralentisseurs du NAV ; elle détermine le rythme de conduction 1/1, 2/1, etc.","src":"p. 390","deep":"**Pourquoi** : le NAV filtre les influx atriaux trop rapides (conduction décrémentielle) ; l'intensité du filtre dépend de l'âge, du tonus vagal et des médicaments ralentisseurs du NAV (p. 390).\n**Piège** : ce filtre est vital : sans lui, chaque FA donnerait une FV et un flutter à 300 bpm une tachycardie ventriculaire à 300 bpm (p. 390).\n**À relier** : selon le filtre, conduction 1/1, 2/1, alternée ou variable (p. 390) ; la voie accessoire n'a pas ce filtre (super-Wolff, p. 411)."},{"id":"231-qroc-762","type":"QROC","rank":"B","objective":"231-obj-16","tags":["ECG","physiopathologie"],"difficulty":1,"question":"Quel effet cherche-t-on sur le NAV avec les manœuvres vagales ou l'adénosine ?","answer":"Un bloc atrioventriculaire transitoire (intensifier le filtre AV)","accept":["bloc atrioventriculaire transitoire","bav transitoire","bloc transitoire","intensifier le filtre","intensification du filtre","bloc av transitoire","intensifier le filtre atrioventriculaire","bloquer le nav"],"keywords":[],"explanation":"Ces gestes créent un bloc atrioventriculaire transitoire, ce qui permet d'élucider le diagnostic des tachycardies.","src":"p. 390-391","deep":"**Pourquoi** : en intensifiant le filtre du NAV, on crée un bloc AV transitoire : la réponse ventriculaire ralentit et l'activité atriale (P, F, mailles) devient visible ; une tachycardie qui passe par le NAV (jonctionnelle) s'arrête (p. 390, 397).\n**Piège** : on ne bloque pas le NAV en cas de FA sur préexcitation : l'influx passerait par la voie accessoire, sans filtre (p. 410-411).\n**À relier** : algorithme : tachycardie bien tolérée → manœuvres vagales ± adénosine si échec ; mauvaise tolérance → cardioversion électrique (fig. 15.51, p. 405)."},{"id":"231-qroc-763","type":"QROC","rank":"B","objective":"231-obj-16","tags":["traitement","ECG"],"difficulty":1,"question":"Quelle est la durée d'effet de l'adénosine IV ?","answer":"Une dizaine de secondes","accept":["dizaine de secondes","10 secondes","10 s","quelques secondes","environ 10 secondes","une dizaine de s","10 sec"],"keywords":[],"explanation":"L'adénosine, vagomimétique, s'administre en flash intraveineux et son effet dure une dizaine de secondes.","src":"p. 390","deep":"**Pourquoi** : l'adénosine crée un bloc AV très bref : flash IV, effet d'une dizaine de secondes (p. 390).\n**Piège** : la durée est de secondes, pas de minutes ; elle s'utilise après échec des manœuvres vagales (p. 390).\n**À relier** : contre-indications : asthme et hypotension (encadré p. 390) ; super-Wolff (p. 411) ; HTA non contrôlée au chapitre palpitations (item 237, p. 421)."},{"id":"231-qroc-764","type":"QROC","rank":"B","objective":"231-obj-16","tags":["traitement","ECG"],"difficulty":2,"question":"Par quels récepteurs l'adénosine exerce-t-elle son effet vagomimétique ?","answer":"Les récepteurs purinergiques","accept":["purinergique","purinergiques","récepteurs purinergiques","p1"],"keywords":["purinergique"],"explanation":"Le mécanisme de l'adénosine est vagomimétique via les récepteurs purinergiques.","src":"p. 390","deep":"**Pourquoi** : l'adénosine a un mécanisme vagomimétique via les récepteurs purinergiques : elle reproduit l'effet d'une manœuvre vagale sur le NAV (p. 390).\n**Piège** : c'est un médicament de 2e temps, en cas d'inefficacité des manœuvres vagales (p. 390).\n**À relier** : le tableau d'objectifs (rang B) associe manœuvres vagales et médicaments purinergiques (p. 368)."},{"id":"231-qroc-765","type":"QROC","rank":"B","objective":"231-obj-16","tags":["traitement","pièges"],"difficulty":2,"question":"Quel risque justifie la contre-indication de l'adénosine chez l'asthmatique ?","answer":"Un bronchospasme intense transitoire","accept":["bronchospasme","bronchospasme intense","bronchospasme intense transitoire","crise d'asthme","bronchoconstriction"],"keywords":["bronchospasme"],"explanation":"L'adénosine peut, rarement, provoquer un bronchospasme intense transitoire, même chez un sujet non asthmatique.","src":"p. 390","deep":"**Pourquoi** : l'adénosine peut, rarement, provoquer un bronchospasme intense transitoire, même chez un sujet non asthmatique : chez l'asthmatique, c'est une contre-indication (p. 390).\n**Piège** : le risque existe aussi, rarement, chez le non-asthmatique ; l'adénosine ne s'utilise qu'en cas d'inefficacité des manœuvres vagales (p. 390).\n**À relier** : autres CI : hypotension (p. 390) ; super-Wolff, présenté p. 411 comme « seule autre CI avec l'asthme » : deux versions à connaître."},{"id":"231-qroc-766","type":"QROC","rank":"B","objective":"231-obj-16","tags":["traitement","pièges"],"difficulty":2,"question":"Hormis l'asthme, quelle anomalie hémodynamique contre-indique l'adénosine selon l'encadré sur le bloc AV transitoire ?","answer":"L'hypotension artérielle","accept":["hypotension","hypotension artérielle","pression artérielle basse","tension basse"],"keywords":["hypotension"],"explanation":"L'encadré 15.1 contre-indique l'adénosine en cas d'asthme et en cas d'hypotension artérielle. Dans la préexcitation, la FA rapide sur voie accessoire est une autre situation à risque.","src":"p. 390","deep":"**Pourquoi** : l'encadré 15.1 contre-indique l'adénosine en cas d'asthme (risque de bronchospasme) ou d'hypotension artérielle (p. 390).\n**Piège** : la liste varie selon les passages : p. 411, le super-Wolff est cité comme seule autre CI avec l'asthme ; au chapitre palpitations (item 237, p. 421), c'est l'HTA non contrôlée : seul l'asthme est commun à toutes.\n**À relier** : en cas d'échec ou de mauvaise tolérance hémodynamique, c'est la cardioversion électrique (p. 405)."},{"id":"231-qroc-767","type":"QROC","rank":"B","objective":"231-obj-16","tags":["ECG","méthode"],"difficulty":1,"question":"Citez deux manœuvres vagales.","answer":"Valsalva, compression carotidienne unilatérale, boire de l'eau froide","accept":["valsalva","compression carotidienne","massage carotidien","massage sinocarotidien","eau froide","verre d'eau froide","manœuvre de valsalva","boire de l'eau froide","massage du sinus carotidien"],"keywords":[],"explanation":"Les manœuvres vagales listées sont la manœuvre de Valsalva, la compression carotidienne unilatérale et le fait de boire un grand verre d'eau froide.","src":"p. 390","deep":"**Pourquoi** : toutes stimulent le tonus vagal sur le NAV pour créer un bloc AV transitoire : Valsalva (expiration forcée glotte fermée), compression carotidienne unilatérale, grand verre d'eau froide (p. 390).\n**Piège** : la compression oculaire bilatérale n'est plus recommandée (décollement de rétine chez le myope), et la compression carotidienne est contre-indiquée si athérome important ou souffle (p. 390).\n**À relier** : si elles échouent : adénosine IV (p. 390)."},{"id":"231-qroc-768","type":"QROC","rank":"B","objective":"231-obj-16","tags":["ECG","pièges"],"difficulty":2,"question":"Quelle manœuvre vagale n'est plus recommandée et pourquoi ?","answer":"La compression oculaire bilatérale (risque de décollement de rétine)","accept":["compression oculaire","oculaire","décollement de rétine","compression oculaire bilatérale","compression des globes oculaires","décollement de la rétine"],"keywords":["oculaire"],"explanation":"La compression oculaire bilatérale n'est plus recommandée en raison d'un risque de décollement de rétine en cas de myopie.","src":"p. 390","deep":"**Pourquoi** : la compression oculaire bilatérale expose à un décollement de rétine en cas de myopie : elle n'est plus recommandée (p. 390).\n**Piège** : la compression carotidienne reste possible, mais unilatérale et pas en cas d'athérome important ou de souffle carotidien (p. 390).\n**À relier** : manœuvres recommandées : Valsalva, compression carotidienne unilatérale, eau froide (p. 390)."},{"id":"231-qroc-769","type":"QROC","rank":"B","objective":"231-obj-16","tags":["ECG","pièges"],"difficulty":2,"question":"Dans quels cas la compression carotidienne unilatérale est-elle contre-indiquée ?","answer":"Athérome carotidien important ou souffle carotidien","accept":["athérome","souffle carotidien","souffle","athérome carotidien important","athérome important"],"keywords":[],"explanation":"La compression carotidienne unilatérale est contre-indiquée en cas d'athérome important ou de souffle carotidien.","src":"p. 390","deep":"**Pourquoi** : la compression carotidienne appuie sur une artère : en cas d'athérome important ou de souffle carotidien, elle est contre-indiquée (p. 390).\n**Piège** : elle doit être unilatérale ; l'oculaire n'est plus recommandée (p. 390).\n**À relier** : alternatives : Valsalva, verre d'eau froide, puis adénosine IV si échec (p. 390)."},{"id":"231-qroc-770","type":"QROC","rank":"A","objective":"231-obj-12","tags":["ECG","diagnostic"],"difficulty":2,"question":"En plus de la courbe de fréquence d'un scope, d'une télémétrie ou d'un Holter, quelle manœuvre peut mettre en évidence la variabilité de fréquence d'une tachycardie sinusale ?","answer":"Le massage sinocarotidien","accept":["massage sinocarotidien","massage sino-carotidien","massage carotidien","sinocarotidien","massage du sinus carotidien","compression carotidienne"],"keywords":["carotid"],"explanation":"La fréquence d'une tachycardie sinusale varie progressivement, ce qu'on voit sur une courbe de fréquence ou lors d'un massage sinocarotidien ; une TSV fait des « marches d'escalier ».","src":"p. 391","deep":"**Pourquoi** : la tachycardie sinusale accélère et ralentit progressivement (courbe de fréquence, massage sinocarotidien), alors qu'une TSV non sinusale change de fréquence en « marches d'escalier » (p. 391).\n**Piège** : trois critères pour une tachycardie sinusale : P sinusales (positives en D1, D2, D3, aVF), variabilité progressive, contexte (fièvre, stress, douleur) ; une personne au repos ne doit pas être très tachycarde sans cause évidente (p. 390-391).\n**À relier** : le massage sinocarotidien est contre-indiqué si athérome important ou souffle carotidien (p. 390)."},{"id":"231-qroc-771","type":"QROC","rank":"A","objective":"231-obj-13","tags":["ECG","définition"],"difficulty":1,"question":"Entre quelles valeurs se situe la fréquence de la tachycardie de la fibrillation atriale ?","answer":"Entre 100 et 200 bpm","accept":["100 et 200","100-200","100 à 200","entre 100 et 200 bpm","100 à 200 bpm"],"keywords":["100","200"],"explanation":"La FA est une tachycardie fréquente, habituellement entre 100 et 200 bpm, à QRS irrégulièrement irréguliers.","src":"p. 392","deep":"**Pourquoi** : la FA est une tachycardie fréquente, habituellement entre 100 et 200 bpm, à QRS irrégulièrement irréguliers ; c'est la réponse ventriculaire filtrée par le NAV (p. 390, 392).\n**Piège** : ne confonds pas avec la fréquence ATRIALE du flutter (≈ 300 bpm, 240-340) ou sa réponse 2/1 régulière à 150 bpm (p. 393-394).\n**À relier** : QRS lents et réguliers sur FA = FA + BAV complet (p. 392, rang B)."},{"id":"231-qroc-772","type":"QROC","rank":"A","objective":"231-obj-13","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quels aspects peut prendre l'activité atriale d'une FA en l'absence de bloc de branche ?","answer":"Mailles amples ou fine trémulation de la ligne de base","accept":["mailles amples","trémulation","tremulation","petites mailles","fine trémulation","mailles","trémulation de la ligne de base","grandes mailles"],"keywords":[],"explanation":"À la place de l'activité sinusale, on voit soit des mailles amples, soit une fine trémulation de la ligne de base.","src":"p. 392","deep":"**Pourquoi** : en FA, l'activité atriale est anarchique : l'activité sinusale est remplacée par des mailles amples ou par une fine trémulation de la ligne de base (p. 392).\n**Piège** : pas d'ondes F monomorphes comme dans le flutter (p. 393) ; QRS fins sauf bloc de branche associé (p. 392).\n**À relier** : en cas de difficulté pour voir l'activité atriale, manœuvres vagales (p. 392)."},{"id":"231-qroc-773","type":"QROC","rank":"A","objective":"231-obj-13","tags":["ECG","méthode"],"difficulty":1,"question":"Que peut-on faire en cas de difficulté pour analyser l'activité atriale d'une FA ?","answer":"Réaliser des manœuvres vagales","accept":["manœuvre vagale","manoeuvre vagale","manœuvres vagales","manoeuvres vagales","adénosine","manœuvre de valsalva"],"keywords":["vagal"],"explanation":"Les manœuvres vagales ralentissent la conduction ventriculaire et démasquent l'activité atriale sous-jacente.","src":"p. 392","deep":"**Pourquoi** : ralentir transitoirement le NAV espace les QRS et démasque l'activité atriale sous-jacente (p. 392).\n**Piège** : on ne bloque pas le NAV en cas de FA sur voie accessoire (préexcitation), où l'influx passerait sans filtre (p. 410-411).\n**À relier** : même intérêt dans le flutter 1/1 ou 2/1 (p. 395) et devant toute tachycardie bien tolérée au diagnostic non évident (p. 405)."},{"id":"231-qroc-774","type":"QROC","rank":"B","objective":"231-obj-09","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Quel mécanisme explique la régularité des QRS lents lorsqu'une FA s'associe à un BAV complet ?","answer":"Un rythme d'échappement automatique, régulier","accept":["échappement","rythme d'échappement","automatique","rythme d'échappement automatique","échappement automatique"],"keywords":["echappement"],"explanation":"En cas de BAV complet, la dépolarisation ventriculaire se fait grâce à un rythme d'échappement automatique, de fréquence régulière.","src":"p. 392","deep":"**Pourquoi** : en BAV complet, les influx de la FA n'atteignent plus les ventricules : ceux-ci sont commandés par un rythme d'échappement automatique, donc lent et régulier (p. 392).\n**Piège** : une FA est normalement « irrégulièrement irrégulière » : des RR réguliers et lents doivent faire évoquer un BAV complet associé (p. 392).\n**À relier** : BAV3 associé à la FA ou aux flutters = objectif de rang B (p. 368)."},{"id":"231-qroc-775","type":"QROC","rank":"B","objective":"231-obj-11","tags":["ECG","diagnostic"],"difficulty":3,"question":"Que traduisent les pauses observées à l'arrêt d'une FA dans la maladie de l'oreillette ?","answer":"Une reprise lente (retardée) du rythme sinusal","accept":["reprise lente","reprise retardée","reprise tardive","retard","reprise retardée du rythme sinusal","reprise lente du rythme sinusal","dysfonction sinusale"],"keywords":["sinusal"],"explanation":"Dans le syndrome tachycardie-bradycardie, des pauses de régularisation à l'arrêt de la FA reflètent la reprise lente ou retardée du rythme sinusal.","src":"p. 393","deep":"**Pourquoi** : dans la maladie de l'oreillette, le nœud sinusal est lui aussi malade : à l'arrêt de la FA, il redémarre lentement ou en retard, ce qui donne des pauses de régularisation (p. 393).\n**Piège** : ces pauses ne sont pas un BAV : il manque l'activité sinusale, pas la conduction.\n**À relier** : maladie de l'oreillette = alternance bradycardie sinusale / tachycardie par FA (syndrome tachycardie-bradycardie) (p. 393)."},{"id":"231-qroc-776","type":"QROC","rank":"B","objective":"231-obj-13","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quels sont les deux types de bloc de branche pouvant s'associer à une FA ?","answer":"Préexistant, ou fonctionnel (n'apparaissant qu'en tachycardie)","accept":["préexistant","fonctionnel","préexistant ou fonctionnel","bloc fonctionnel","bloc préexistant"],"keywords":[],"explanation":"L'association FA + bloc de branche est fréquente : le bloc est soit préexistant, soit fonctionnel, et donne une tachycardie irrégulière à QRS larges.","src":"p. 393","deep":"**Pourquoi** : le bloc de branche associé à une FA est soit préexistant, soit fonctionnel, n'apparaissant qu'en tachycardie ; association fréquente (p. 393).\n**Piège** : une tachycardie irrégulière à QRS larges n'est pas forcément une TV : FA + bloc ; mais pense aussi au super-Wolff (QRS de largeur variable, très rapide) (p. 393, 411).\n**À relier** : bloc fonctionnel = n'existe qu'à partir d'une certaine fréquence (p. 381)."},{"id":"231-qroc-777","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","définition"],"difficulty":2,"question":"Que signifie « activité atriale monomorphe » dans le flutter ?","answer":"Même aspect des ondes sur une dérivation donnée","accept":["même aspect","meme aspect","identique","même morphologie","même forme","ondes identiques"],"keywords":[],"explanation":"L'activité atriale du flutter est monomorphe : les ondes F ont le même aspect sur une dérivation donnée, car la boucle se répète à l'identique.","src":"p. 393, 415","deep":"**Pourquoi** : le flutter est une boucle de réentrée qui se répète à l'identique : chaque onde F a la même forme sur une dérivation donnée (p. 393).\n**Piège** : la FA, à l'inverse, est anarchique (mailles, trémulation) ; points clés : l'activité atriale du flutter est monomorphe (p. 415).\n**À relier** : flutter : ≈ 300 bpm (240-340), sans retour à la ligne isoélectrique dans au moins une dérivation (p. 393)."},{"id":"231-qroc-778","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Pourquoi les flutters de l'oreillette droite sont-ils beaucoup plus fréquents que les flutters gauches ?","answer":"L'OD comporte des zones propices à l'initiation, même sans cardiopathie","accept":["zones propices","constitutionnel","oreillette droite comporte","sans pathologie cardiaque","zones propices à l'initiation","constitutionnellement","zones favorables"],"keywords":[],"explanation":"L'oreillette droite possède de manière constitutionnelle des zones favorables au flutter, alors que les flutters gauches sont surtout induits par une pathologie ou une intervention.","src":"p. 393","deep":"**Pourquoi** : l'OD comporte de manière constitutionnelle des zones propices au déclenchement d'un flutter, même sans cardiopathie (p. 393).\n**Piège** : un flutter gauche, lui, suppose le plus souvent une cardiopathie (remodelage de l'OG) ou une intervention sur l'OG (p. 393).\n**À relier** : le flutter typique utilise l'isthme cavotricuspide de l'OD, entre valve tricuspide et VCI (p. 394)."},{"id":"231-qroc-779","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","étiologie"],"difficulty":2,"question":"Quelles sont les deux causes habituelles d'un flutter de l'oreillette gauche ?","answer":"Remodelage de l'OG par une cardiopathie, ou lésions de l'OG après intervention","accept":["remodelage","intervention","cardiopathie","ablation","lésions","remodelage de l'oreillette gauche","cicatrice d'ablation","intervention sur l'oreillette gauche","cardiopathie ou intervention"],"keywords":[],"explanation":"Les flutters gauches surviennent le plus souvent après remodelage de l'oreillette gauche lié à une cardiopathie ou après une intervention ayant créé des lésions dans l'OG.","src":"p. 393","deep":"**Pourquoi** : l'OG n'a pas de zone constitutionnellement propice au flutter : il faut un substrat acquis, remodelage par une cardiopathie ou lésions créées par une intervention (p. 393).\n**Piège** : ce sont des flutters atypiques (circuit sans isthme cavotricuspide), de fréquence 120-320 bpm (p. 394).\n**À relier** : les flutters droits sont beaucoup plus fréquents (p. 393)."},{"id":"231-qroc-780","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","définition"],"difficulty":2,"question":"Qu'ont en commun le flutter et la FA qui explique qu'un même patient les présente successivement ?","answer":"Des facteurs prédisposants communs","accept":["facteurs prédisposants communs","facteurs communs","mêmes facteurs","facteurs favorisants communs","mêmes facteurs prédisposants","facteurs de risque communs"],"keywords":["commun"],"explanation":"Les facteurs prédisposant au flutter et à la FA sont communs : il n'est donc pas rare d'observer des épisodes successifs de flutter et de FA.","src":"p. 393","deep":"**Pourquoi** : flutter et FA partagent les mêmes facteurs prédisposants : un même patient présente souvent des épisodes successifs des deux (p. 393).\n**Piège** : malgré ce lien, l'ECG les distingue : flutter = activation organisée en circuit, FA = activation fibrillatoire anarchique (p. 393).\n**À relier** : fréquence atriale du flutter ≈ 300 bpm (p. 393)."},{"id":"231-qroc-781","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","définition"],"difficulty":1,"question":"Comment nomme-t-on un flutter dont la conduction alterne entre 2/1, 3/1, 4/1, etc. ?","answer":"Un flutter à conduction variable","accept":["conduction variable","flutter à conduction variable"],"keywords":["variable"],"explanation":"L'effet de filtrage du NAV peut varier : en cas d'alternance de conduction, on parle de flutter à conduction variable.","src":"p. 394","deep":"**Pourquoi** : le filtre du NAV peut lui-même varier : quand la transmission alterne 2/1, 3/1, 4/1, on parle de flutter à conduction variable, avec des QRS irréguliers (p. 394).\n**Piège** : un flutter n'est donc pas toujours régulier ; mais l'activité atriale reste monomorphe, ce qui le distingue d'une FA (p. 393-394).\n**À relier** : forme usuelle : 2/1 à 150 bpm ; 3/1 à 100 bpm ; 75 bpm, etc. (p. 394)."},{"id":"231-qroc-782","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","méthode"],"difficulty":2,"question":"Pourquoi une manœuvre vagale est-elle surtout utile dans un flutter conduit en 1/1 ou 2/1 ?","answer":"Les QRS sont très proches et laissent peu de place à l'activité atriale","accept":["qrs très proches","qrs proches","peu de place","qrs rapprochés","qrs très rapprochés","ondes f masquées"],"keywords":[],"explanation":"Dans un flutter 1/1 ou 2/1, la cadence ventriculaire rapide masque les ondes F ; la manœuvre vagale ralentit transitoirement la conduction et démasque l'activité atriale.","src":"p. 395","deep":"**Pourquoi** : en 1/1 ou 2/1, les QRS sont si rapprochés que les ondes F sont cachées ; la manœuvre vagale ralentit transitoirement la conduction et démasque l'activité atriale (p. 395).\n**Piège** : une tachycardie régulière à 150 bpm doit faire chercher des F masquées (forme usuelle 2/1, p. 394).\n**À relier** : même usage diagnostique devant une FA difficile à analyser (p. 392)."},{"id":"231-qroc-783","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","diagnostic"],"difficulty":3,"question":"Dans un flutter typique antihoraire, quelle est la polarité des ondes F en V1 ?","answer":"Positive (négative en D2, D3, aVF et en V6)","accept":["positive","positives","positif","f positives en v1","onde positive","positive en v1"],"keywords":["posit"],"explanation":"Dans le flutter typique antihoraire, la fin de la pente lente des ondes F est négative en D2, D3, aVF et V6, positive en V1.","src":"p. 394","deep":"**Pourquoi** : dans le flutter typique antihoraire, la boucle atriale droite emprunte l'isthme cavotricuspide : la fin de la pente lente des F est négative en D2, D3, aVF et V6, positive en V1 (p. 394).\n**Piège** : dans le typique horaire, toutes ces polarités sont strictement inversées (p. 394).\n**À relier** : fréquence atriale ≈ 300 bpm sur oreillette normale, plus lente si l'oreillette est dilatée (p. 394)."},{"id":"231-qroc-784","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","diagnostic"],"difficulty":2,"question":"Par rapport au flutter typique antihoraire, quelles sont les polarités des ondes F du flutter typique horaire ?","answer":"Strictement inversées","accept":["inversées","inverse","inversé","strictement inversées","polarités inversées","l'inverse"],"keywords":["invers"],"explanation":"Le flutter typique horaire tourne dans l'autre sens : toutes les polarités sont strictement inversées par rapport à la forme antihoraire.","src":"p. 394","deep":"**Pourquoi** : le flutter horaire emprunte le même circuit en sens inverse : les polarités des F sont strictement inversées (p. 394).\n**Piège** : le caractère typique ne se juge qu'« à l'aspect » sur l'ECG (pas parfaitement fiable) (p. 394).\n**À relier** : antihoraire (le plus fréquent) : F négatives en D2, D3, aVF et V6, positives en V1 (p. 394)."},{"id":"231-qroc-785","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","définition"],"difficulty":2,"question":"Comment définit-on un flutter atypique ?","answer":"Un flutter dont le circuit n'inclut pas l'isthme cavotricuspide","accept":["sans isthme cavotricuspide","n'emprunte pas l'isthme","n'inclut pas l'isthme","ne passe pas par l'isthme","isthme cavotricuspide ne fait pas partie","isthme cavotricuspide n'est pas","n'emprunte pas l'isthme cavotricuspide","isthme cavotricuspide ne fait pas partie du circuit"],"keywords":["isthme"],"explanation":"Les flutters atypiques regroupent tous les flutters dont l'isthme cavotricuspide ne fait pas partie du circuit ; ils peuvent être atrial droit, gauche ou biatrial.","src":"p. 394","deep":"**Pourquoi** : le flutter typique est défini par une boucle passant par l'isthme cavotricuspide : tout circuit qui ne l'utilise pas est atypique (droit, gauche ou biatrial) (p. 394).\n**Piège** : la classification ECG n'est pas parfaitement fiable : on parle de flutter « d'aspect » typique ou atypique (p. 394).\n**À relier** : atypiques : 120-320 bpm, ondes F de morphologies diverses (p. 394)."},{"id":"231-qroc-786","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","diagnostic"],"difficulty":2,"question":"Entre quelles valeurs varie la fréquence atriale des flutters atypiques ?","answer":"120 à 320 bpm","accept":["120 à 320","120-320","120 et 320","entre 120 et 320 bpm"],"keywords":["120","320"],"explanation":"La fréquence des flutters atypiques dépend de la longueur du circuit et du ralentissement lié à la fibrose atriale ; les ondes F ont des morphologies diverses.","src":"p. 394","deep":"**Pourquoi** : la fréquence d'un flutter dépend de la longueur du circuit et du ralentissement induit par la fibrose atriale : 120 à 320 bpm pour les atypiques (p. 394).\n**Piège** : le typique tourne autour de 300 bpm sur oreillette normale (240-340 pour les flutters en général), plus lentement si l'oreillette est dilatée (p. 393-394).\n**À relier** : formes atypiques souvent liées à une cardiopathie ou à une intervention atriale gauche (p. 393)."},{"id":"231-qroc-787","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","pièges"],"difficulty":3,"question":"Pourquoi parle-t-on de flutter « d'aspect typique » plutôt que de flutter typique à l'ECG ?","answer":"La distinction typique/atypique à l'ECG n'est pas parfaitement fiable","accept":["pas parfaitement fiable","pas fiable","non fiable","fiabilité","manque de fiabilité"],"keywords":["fiable"],"explanation":"La détermination du caractère typique ou atypique à l'ECG n'est pas parfaitement fiable ; elle repose sur la fréquence et le terrain ou sur l'exploration électrophysiologique.","src":"p. 394","deep":"**Pourquoi** : l'ECG ne permet pas de distinguer parfaitement typique et atypique : on parle de flutter « d'aspect typique » (p. 394).\n**Piège** : un aspect typique sur cœur sain a de fortes chances d'être réellement typique, mais moins sur cœur pathologique ou opéré (p. 394).\n**À relier** : le diagnostic formel vient de l'exploration électrophysiologique précédant l'ablation par radiofréquence (p. 394)."},{"id":"231-qroc-788","type":"QROC","rank":"A","objective":"231-obj-14","tags":["ECG","examens"],"difficulty":3,"question":"Comment confirme-t-on formellement qu'un flutter est typique ?","answer":"Par l'exploration électrophysiologique précédant l'ablation","accept":["exploration électrophysiologique","électrophysiologique","exploration endocavitaire","avant l'ablation","étude électrophysiologique"],"keywords":["electrophysiolog"],"explanation":"Le diagnostic formel est fait par un argument de fréquence (flutter d'aspect typique sur cœur sain) ou par l'exploration électrophysiologique qui précède l'ablation par radiofréquence.","src":"p. 394","deep":"**Pourquoi** : la certitude que le circuit passe par l'isthme cavotricuspide vient de l'exploration électrophysiologique, réalisée avant l'ablation par radiofréquence (p. 394).\n**Piège** : l'autre argument, la fréquence (aspect typique sur cœur sain), n'est que probabiliste (p. 394).\n**À relier** : l'ECG seul ne parle que d'« aspect » typique ou atypique (p. 394)."},{"id":"231-qroc-789","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG","définition"],"difficulty":1,"question":"Que désigne la « charge » extrasystolique ?","answer":"Le nombre d'extrasystoles par 24 heures","accept":["nombre d'extrasystoles par 24","nombre par 24","par 24 h","par 24 heures","nombre d'extrasystoles sur 24 h","extrasystoles par 24 h","nombre sur 24 heures"],"keywords":["24"],"explanation":"La charge extrasystolique est le nombre d'extrasystoles sur 24 h ; elle augmente avec l'âge et la présence d'une cardiopathie.","src":"p. 397","deep":"**Pourquoi** : la charge extrasystolique est le nombre d'extrasystoles par 24 heures ; elle augmente avec l'âge et la présence d'une cardiopathie (p. 397).\n**Piège** : des extrasystoles peuvent être physiologiques sur cœur sain ; ce sont la fréquence ou le polymorphisme qui font rechercher une cardiopathie (p. 397).\n**À relier** : le Holter de 24 h est l'outil qui enregistre sur cette durée (p. 415)."},{"id":"231-qroc-790","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quel est l'aspect ECG d'une extrasystole atriale ?","answer":"Onde P' précoce, de morphologie différente de la P sinusale, puis QRS fin","accept":["onde p précoce","p précoce","p' précoce","p prématurée","p trop précoce","p' précoce puis qrs fin","onde p différente de la p sinusale","p précoce de morphologie différente"],"keywords":["precoce"],"explanation":"Dans l'extrasystole atriale, l'onde P est trop précoce et de morphologie différente de la P sinusale (point d'origine ectopique), puis le QRS est fin.","src":"p. 397","deep":"**Pourquoi** : l'ESA naît d'un foyer atrial ectopique : P' prématurée de forme différente de la P sinusale ; la conduction ventriculaire reste normale, donc QRS fin (p. 397).\n**Piège** : la P' peut être masquée par la T précédente (p. 397-398) ; une extrasystole jonctionnelle donne aussi un QRS fin mais sans P' précoce (± P' rétrograde).\n**À relier** : l'ESA est le diagnostic différentiel d'une tachycardie irrégulière (FA) dans l'algorithme (p. 405)."},{"id":"231-qroc-791","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG","pièges"],"difficulty":2,"question":"Où peut se cacher l'onde P d'une extrasystole atriale très précoce ?","answer":"Sur l'onde T qui précède","accept":["onde t précédente","onde t qui précède","sur l'onde t","dans l'onde t","onde t","sur l'onde t précédente","dans l'onde t précédente","onde t déformée"],"keywords":["t"],"explanation":"L'onde P' peut être juxtaposée ou masquée par l'onde T précédente, dont elle peut renverser la polarité.","src":"p. 397-398","deep":"**Pourquoi** : une ESA très précoce tombe sur la T précédente : sa P' s'y superpose, peut la masquer ou en renverser la polarité (fig. 15.39, p. 397-398).\n**Piège** : un QRS fin prématuré sans P' visible n'est pas forcément jonctionnel : cherche une T déformée juste avant.\n**À relier** : ESA = P' précoce de morphologie différente + QRS fin (p. 397)."},{"id":"231-qroc-792","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quel est l'aspect ECG d'une extrasystole jonctionnelle ?","answer":"QRS fin avec ou sans onde P' rétrograde","accept":["qrs fin","p' rétrograde","onde p rétrograde","qrs fin sans p précoce","qrs fin avec ou sans p' rétrograde"],"keywords":["fin"],"explanation":"L'influx naît dans la jonction et part dans les deux sens vers l'oreillette et le ventricule : QRS fin, avec ou sans P' rétrograde.","src":"p. 397","deep":"**Pourquoi** : l'influx naît dans la jonction et part simultanément vers les ventricules (par les voies normales : QRS fin) et vers les oreillettes (P' rétrograde éventuelle) (p. 397).\n**Piège** : pas de P' précoce devant le QRS, contrairement à l'ESA ; QRS fin, contrairement à l'ESV (p. 397).\n**À relier** : elles sont rares et traduisent le plus souvent une pathologie de la jonction nodohissienne (p. 397)."},{"id":"231-qroc-793","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG","étiologie"],"difficulty":3,"question":"Que traduisent le plus souvent les extrasystoles jonctionnelles, qui sont rares ?","answer":"Une pathologie de la jonction nodohissienne","accept":["jonction nodohissienne","nodohissienne","nodo-hissienne","pathologie de la jonction","pathologie de la jonction nodohissienne","jonction nodo-hissienne","atteinte de la jonction"],"keywords":["jonction"],"explanation":"Les extrasystoles jonctionnelles sont rares et traduisent le plus souvent une pathologie de la jonction nodohissienne.","src":"p. 397","deep":"**Pourquoi** : les extrasystoles jonctionnelles sont rares et traduisent le plus souvent une pathologie de la jonction nodohissienne (p. 397).\n**Piège** : contraste avec les ESA et ESV, fréquentes et souvent physiologiques sur cœur sain (p. 397).\n**À relier** : aspect : QRS fin ± P' rétrograde (p. 397)."},{"id":"231-qroc-794","type":"QROC","rank":"A","objective":"231-obj-18","tags":["urgence","définition"],"difficulty":1,"question":"Quelle problématique domine l'objectif pédagogique des troubles du rythme ventriculaire ?","answer":"La mort subite et les syncopes","accept":["mort subite","syncope","mort subite et syncope","mort subite et syncopes","syncopes"],"keywords":["mort subit"],"explanation":"Les troubles du rythme ventriculaire sont un objectif prioritaire, dominé par la problématique de la mort subite et des syncopes.","src":"p. 398","deep":"**Pourquoi** : le Collège classe les troubles du rythme ventriculaire comme objectif pédagogique prioritaire, dominé par la mort subite et les syncopes (p. 398).\n**Piège** : la TV est observée dans plus de la moitié des morts subites et peut dégénérer en FV puis asystolie (p. 398).\n**À relier** : suspicion de TV = alerte (15) et préparation à la réanimation (p. 399)."},{"id":"231-qroc-795","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Quel est le mécanisme le plus fréquent d'une TV sur cœur sain ?","answer":"Un automatisme anormal","accept":["automatisme anormal","automatisme","hyperautomatisme","foyer automatique"],"keywords":["automatisme"],"explanation":"Deux mécanismes existent : la réentrée (le plus fréquent sur cardiopathie) et l'automatisme anormal (le plus fréquent sur cœur sain).","src":"p. 398","deep":"**Pourquoi** : deux mécanismes de TV : la réentrée, le plus fréquent sur cardiopathie (autour d'une zone de fibrose), et l'automatisme anormal, le plus fréquent sur cœur sain (p. 398-399).\n**Piège** : ne pas inverser les deux : cœur malade → réentrée ; cœur sain → automatisme anormal.\n**À relier** : une cardiopathie sous-jacente est un argument en faveur d'une TV devant une tachycardie à QRS larges (p. 400)."},{"id":"231-qroc-796","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Quel est le mécanisme le plus fréquent d'une TV sur cardiopathie ?","answer":"Une réentrée autour d'une zone de fibrose","accept":["réentrée","reentree","rentrée","boucle de réentrée","boucle de réentrée autour d'une cicatrice","réentrée autour d'une fibrose","reentrée"],"keywords":["reentr"],"explanation":"La TV sur cardiopathie résulte le plus souvent d'une réentrée autour d'une zone de fibrose secondaire à une nécrose (infarctus) ou à une cardiopathie.","src":"p. 398-399","deep":"**Pourquoi** : la fibrose secondaire à une nécrose (infarctus) ou à une cardiopathie crée un obstacle autour duquel l'influx peut tourner : la réentrée est le mécanisme le plus fréquent de TV (p. 398-399).\n**Piège** : sur cœur sain, c'est l'automatisme anormal qui prédomine (p. 398).\n**À relier** : d'où l'argument « cardiopathie sous-jacente +++ » en faveur d'une TV (p. 400)."},{"id":"231-qroc-797","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic"],"difficulty":1,"question":"Comment doit-on considérer toute tachycardie régulière à QRS larges tant que le diagnostic n'est pas établi ?","answer":"Comme une TV jusqu'à preuve du contraire","accept":["tv jusqu'à preuve du contraire","tachycardie ventriculaire","tv","ventriculaire jusqu'à preuve du contraire","comme une tachycardie ventriculaire","tachycardie ventriculaire jusqu'à preuve du contraire"],"keywords":[],"explanation":"Toute tachycardie régulière à QRS larges est une tachycardie ventriculaire jusqu'à preuve du contraire : une TV est mortelle si elle n'est pas prise en charge, un bloc de branche est sans conséquence immédiate.","src":"p. 398, 415","deep":"**Pourquoi** : une TV est mortelle si elle n'est pas prise en charge, alors qu'un bloc de branche est sans conséquence immédiate : on retient le diagnostic le plus grave tant qu'il n'est pas exclu (p. 398, 415).\n**Piège** : un QRS large régulier ne doit pas être étiqueté « TSV avec bloc » sans preuve : la suspicion de TV impose l'alerte (15) et la préparation à la réanimation (p. 399).\n**À relier** : suspicion de TV : FC > 100 bpm et QRS > 120 ms sur ≥ 3 battements ; certitude : dissociation ventriculoatriale, capture, fusion (p. 399-400)."},{"id":"231-qroc-798","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","complications"],"difficulty":1,"question":"Vers quel trouble du rythme une TV non prise en charge peut-elle dégénérer, puis vers quoi ?","answer":"Vers la FV, puis l'asystole (anoxie cellulaire)","accept":["fibrillation ventriculaire","fv","asystolie","asystole","fibrillation ventriculaire puis asystolie","fv puis asystolie"],"keywords":[],"explanation":"La TV est un état électrique instable, prémonitoire d'arrêt cardiaque : elle dégénère en FV, puis en asystolie par anoxie cellulaire.","src":"p. 398","deep":"**Pourquoi** : la TV est un état électrique instable : sans prise en charge, elle dégénère en FV, puis en asystolie du fait de l'anoxie cellulaire (p. 398).\n**Piège** : la TV n'est pas « stable » parce qu'elle est bien tolérée au début : c'est un état prémonitoire de l'arrêt cardiaque (p. 398).\n**À relier** : FV = cardioversion électrique immédiate, massage en attendant le choc (p. 402)."},{"id":"231-qroc-799","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","définition"],"difficulty":1,"question":"Que signifie qu'une TV est « monomorphe » ?","answer":"Tous les QRS ont une morphologie identique","accept":["morphologie identique","même morphologie","identique","mêmes qrs","qrs identiques","même morphologie des qrs"],"keywords":["identique"],"explanation":"Une TV monomorphe a des QRS de morphologie identique ; elle est dite polymorphe si les QRS varient.","src":"p. 400","deep":"**Pourquoi** : monomorphe = QRS de morphologie identique ; polymorphe = QRS variables ; ce caractère a des conséquences sur l'étiologie et la tolérance hémodynamique (p. 400).\n**Piège** : « monomorphe » ne veut pas dire bénigne : toute TV peut dégénérer en FV (p. 398).\n**À relier** : la torsade de pointes est une TV polymorphe particulière, sur QT long (p. 403, rang B)."},{"id":"231-qroc-801","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic"],"difficulty":2,"question":"Pourquoi faut-il préciser si une TV est monomorphe ou polymorphe ?","answer":"Conséquences sur l'étiologie et sur les effets hémodynamiques","accept":["étiologie","hémodynamique","etiologie","effets hémodynamiques","étiologie et effets hémodynamiques","cause et tolérance","conséquences hémodynamiques"],"keywords":[],"explanation":"Le caractère monomorphe ou polymorphe a des conséquences directes sur l'étiologie potentielle de l'arythmie et sur ses effets hémodynamiques.","src":"p. 400","deep":"**Pourquoi** : le Collège demande de décrire la TV comme monomorphe (QRS identiques) ou polymorphe, car ce caractère a des conséquences directes sur l'étiologie possible et sur la tolérance hémodynamique (p. 400).\n**Piège** : « polymorphe » n'est pas synonyme de FV : la torsade de pointes est une TV polymorphe sur QT long, qui peut s'arrêter seule (p. 403, rang B).\n**À relier** : FV = tachycardie irrégulière à QRS larges polymorphes, débit nul (p. 403)."},{"id":"231-qroc-802","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic"],"difficulty":2,"question":"Dans une TV avec dissociation ventriculo-atriale, comment sont les ondes P par rapport aux QRS ?","answer":"Plus lentes et dissociées des QRS (donc moins nombreuses)","accept":["plus lentes","dissociées","moins nombreuses","plus de qrs que d'ondes p","moins de p que de qrs","plus de qrs que de p","p dissociées des qrs"],"keywords":[],"explanation":"Les ondes P sont habituellement plus lentes et dissociées des QRS : s'il y a plus de QRS que d'ondes P, la tachycardie vient forcément du ventricule.","src":"p. 400","deep":"**Pourquoi** : dans une TV, le ventricule bat seul, plus vite que les oreillettes qui gardent leur rythme : P plus lentes et dissociées, donc plus de QRS que de P ; c'est un argument de certitude (p. 400).\n**Piège** : ne confonds pas avec le BAV complet, où il y a au contraire plus de P que de QRS (p. 400).\n**À relier** : les complexes de capture et de fusion ne sont possibles que s'il existe cette dissociation (p. 400)."},{"id":"231-qroc-803","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","pièges"],"difficulty":3,"question":"Avec quelle autre dissociation ne faut-il pas confondre la dissociation ventriculo-atriale de la TV ?","answer":"La dissociation atrioventriculaire du BAV complet","accept":["bav complet","bloc complet","bav3","bloc atrioventriculaire complet","bav 3","bloc atrioventriculaire de 3e degré","dissociation atrioventriculaire du bav complet"],"keywords":[],"explanation":"La dissociation ventriculo-atriale de la TV (plus de QRS que de P) ne doit pas être confondue avec la dissociation atrioventriculaire du bloc complet (plus de P que de QRS).","src":"p. 400","deep":"**Pourquoi** : dans les deux cas, P et QRS sont indépendants ; ce qui les distingue, c'est qui est le plus nombreux : TV = plus de QRS que de P ; BAV complet = plus de P que de QRS (p. 400, 385).\n**Piège** : dans le BAV3, les QRS sont LENTS (échappement) ; dans la TV, ils sont rapides (> 100 bpm) et larges (p. 387, 399).\n**À relier** : fig. 15.42 : 13 QRS pour 9 ondes P = TV (p. 400)."},{"id":"231-qroc-804","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic"],"difficulty":3,"question":"Quelle condition est nécessaire pour observer des complexes de capture ou de fusion ?","answer":"Une dissociation ventriculo-atriale","accept":["dissociation ventriculo","dissociation ventriculoatriale","dissociation","dissociation av","dissociation ventriculo-atriale"],"keywords":["dissociation"],"explanation":"Les complexes de capture et de fusion ne peuvent être présents que s'il existe une dissociation ventriculo-atriale.","src":"p. 400","deep":"**Pourquoi** : capture et fusion supposent qu'une onde P « libre », non liée à la TV, passe par les voies normales et active tout ou partie du ventricule : cela n'est possible que s'il y a dissociation ventriculoatriale (p. 400).\n**Piège** : capture = QRS fin précédé d'une P ; fusion = QRS intermédiaire ; ce sont des arguments de CERTITUDE, alors que concordance précordiale et QRS positif en aVR ne sont qu'en faveur (p. 400-401).\n**À relier** : dissociation, capture et fusion sont les 3 arguments de certitude de TV (encadré 15.2, p. 400)."},{"id":"231-qroc-805","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quel QRS, de largeur intermédiaire entre le QRS sinusal et celui de la TV, constitue un argument de certitude de TV ?","answer":"Un complexe de fusion","accept":["fusion","complexe de fusion","qrs de fusion"],"keywords":["fusion"],"explanation":"Le complexe de fusion résulte de la compétition entre l'activation ventriculaire par la TV et l'influx sinusal ; le complexe de capture est un QRS fin précédé d'une P.","src":"p. 400-401","deep":"**Pourquoi** : le complexe de fusion résulte de la compétition entre l'activation du ventricule par la TV et par l'influx sinusal : son QRS est intermédiaire (p. 401).\n**Piège** : capture = QRS FIN (le sinus active seul tout le ventricule via le réseau normal) ; fusion = INTERMÉDIAIRE (p. 401).\n**À relier** : ces complexes n'existent qu'en cas de dissociation ventriculoatriale, argument de certitude (p. 400)."},{"id":"231-qroc-806","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quelle donnée clinique sous-jacente est l'un des principaux arguments en faveur d'une TV ?","answer":"Une cardiopathie sous-jacente","accept":["cardiopathie","cardiopathie sous-jacente","infarctus ancien","cardiopathie ischémique"],"keywords":["cardiopathie"],"explanation":"La plupart des TV sont favorisées par une cardiopathie : sa présence est un argument majeur en faveur du diagnostic.","src":"p. 400","deep":"**Pourquoi** : la plupart des TV sont favorisées par une cardiopathie (réentrée autour d'une zone de fibrose, souvent un infarctus) : une cardiopathie sous-jacente est un argument fort en faveur d'une TV (p. 399-400).\n**Piège** : c'est un argument EN FAVEUR, pas de certitude ; et une TV sur cœur sain existe (automatisme anormal) (p. 398, 400).\n**À relier** : autres arguments en faveur : concordance V1-V6, QRS positif en aVR, aspect différent d'un bloc habituel (p. 400)."},{"id":"231-qroc-807","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quel aspect des QRS larges, par rapport aux blocs de branche, est un argument en faveur d'une TV ?","answer":"Un aspect différent d'un bloc de branche habituel","accept":["différent d'un bloc de branche","aspect différent","pas d'un bloc de branche habituel","ne ressemble pas à un bloc de branche","différent d'un bbd ou d'un bbg","aspect atypique"],"keywords":[],"explanation":"Des QRS larges d'aspect différent d'un bloc de branche habituel plaident pour une TV, comme la concordance précordiale ou l'axe extrême.","src":"p. 400","deep":"**Pourquoi** : un bloc de branche a une morphologie stéréotypée (BBD : RsR' en V1 ; BBG : rS/QS en V1, notch en V6) ; un QRS large qui ne ressemble à aucune des deux suggère une activation d'origine ventriculaire (p. 378-380, 400).\n**Piège** : argument en faveur, pas de certitude ; la certitude = dissociation ventriculoatriale, capture, fusion (p. 400).\n**À relier** : un QRS positif en aVR (axe extrême) ne se voit ni en BBD ni en BBG : argument en faveur d'une TV (p. 402)."},{"id":"231-qroc-808","type":"QROC","rank":"A","objective":"231-obj-19","tags":["ECG","clinique"],"difficulty":1,"question":"Que constate-t-on cliniquement après quelques secondes de fibrillation ventriculaire ?","answer":"Perte de connaissance et pouls carotidien aboli (arrêt cardiaque)","accept":["perte de connaissance","pouls carotidien aboli","arrêt cardiaque","syncope","mort subite"],"keywords":[],"explanation":"Le débit cardiaque est nul : après quelques secondes le patient perd connaissance et le pouls carotidien est aboli, c'est un arrêt cardiaque.","src":"p. 403","deep":"**Pourquoi** : en FV, l'activation ventriculaire est anarchique, le débit cardiaque est nul : perte de connaissance en quelques secondes, pouls carotidien aboli = arrêt cardiaque (p. 403).\n**Piège** : il ne faut pas perdre de temps à analyser : la FV impose une cardioversion électrique immédiate avant tout autre geste, avec massage en attendant le choc (p. 402).\n**À relier** : ECG : tachycardie irrégulière à QRS larges polymorphes (p. 403)."},{"id":"231-qroc-809","type":"QROC","rank":"B","objective":"231-obj-19","tags":["ECG","étiologie"],"difficulty":2,"question":"Dans quels contextes la FV survient-elle surtout, par opposition à la torsade de pointes ?","answer":"Ischémie ou cardiopathie évoluée","accept":["ischémie","cardiopathie évoluée","ischemie","ischémie myocardique","cardiopathie","infarctus"],"keywords":[],"explanation":"La FV survient surtout en cas d'ischémie ou de cardiopathie évoluée, alors que la torsade de pointes survient lors d'un allongement du QT.","src":"p. 403","deep":"**Pourquoi** : torsade et FV peuvent être indiscernables à l'ECG ; le contexte tranche : la FV survient surtout en cas d'ischémie ou de cardiopathie évoluée, la torsade dans les situations de QT long (p. 403-404).\n**Piège** : l'autre argument est un QT long sur l'ECG avant le trouble du rythme, en faveur de la torsade (p. 403).\n**À relier** : causes de QT long : bradycardie extrême, hypoK, hypoCa, hypoMg, médicaments, QT long congénital (p. 404)."},{"id":"231-qroc-810","type":"QROC","rank":"B","objective":"231-obj-20","tags":["ECG","définition"],"difficulty":1,"question":"À quel type de tachycardie appartient la torsade de pointes ?","answer":"Une TV polymorphe","accept":["tv polymorphe","tachycardie ventriculaire polymorphe","polymorphe","tachycardie ventriculaire"],"keywords":["polymorphe"],"explanation":"La torsade de pointes est une forme particulière de tachycardie ventriculaire polymorphe.","src":"p. 403","deep":"**Pourquoi** : la torsade de pointes est une forme particulière de TV polymorphe, survenant le plus souvent sur QT long (p. 403-404).\n**Piège** : une fois installée, elle peut être impossible à distinguer d'une FV : seuls un QT long préalable et le contexte orientent (p. 403).\n**À relier** : traitement : corriger les troubles ioniques, accélérer la FC, arrêter les médicaments allongeant le QT (p. 404)."},{"id":"231-qroc-811","type":"QROC","rank":"B","objective":"231-obj-20","tags":["ECG","complications"],"difficulty":1,"question":"Quelles évolutions possibles a une torsade de pointes ?","answer":"Arrêt spontané ou dégénérescence en FV","accept":["arrêt spontané","s'arrêter spontanément","spontanément","fibrillation ventriculaire","fv","s'arrête spontanément","dégénère en fv"],"keywords":[],"explanation":"Une torsade de pointes peut s'arrêter spontanément après quelques secondes ou dégénérer en fibrillation ventriculaire.","src":"p. 403","deep":"**Pourquoi** : la torsade est instable : elle peut s'arrêter spontanément (quelques secondes) ou dégénérer en fibrillation ventriculaire (p. 403).\n**Piège** : un arrêt spontané ne la rend pas bénigne, puisqu'elle peut aussi dégénérer en FV (p. 403) : on corrige les troubles ioniques, on accélère la FC et on arrête les médicaments allongeant le QT (p. 404).\n**À relier** : un QT allongé doit alerter : vérifier médicaments et ionogramme (p. 404)."},{"id":"231-qroc-812","type":"QROC","rank":"B","objective":"231-obj-20","tags":["ECG","physiopathologie"],"difficulty":3,"question":"Comment est déclenchée une torsade de pointes survenant avec un QT normal ?","answer":"Deux ESV enchaînées, la 2e tombant sur l'onde T de la 1re","accept":["deux extrasystoles","2 extrasystoles","deux esv","2 esv","sur l'onde t","esv sur t","2e esv sur l'onde t","extrasystole sur t"],"keywords":[],"explanation":"Dans le tracé de la figure 15.50, la torsade est déclenchée par l'enchaînement de deux extrasystoles ventriculaires, la seconde tombant sur l'onde T de la première.","src":"p. 404","deep":"**Pourquoi** : la figure 15.50 montre une torsade avec QT normal, déclenchée par deux ESV enchaînées, la 2e tombant sur l'onde T de la 1re (p. 404).\n**Piège** : la torsade survient le plus souvent sur QT long, mais un QT normal ne l'exclut pas totalement (fig. 15.50).\n**À relier** : la torsade est une TV polymorphe qui peut s'arrêter seule ou dégénérer en FV (p. 403)."},{"id":"231-qroc-813","type":"QROC","rank":"A","objective":"231-obj-22","tags":["traitement","étiologie"],"difficulty":2,"question":"Citez deux classes de médicaments allongeant l'intervalle QT.","answer":"Antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens","accept":["antiarythmique","psychotrope","antibiotique","antiémétique","antiemetique","antipaludéen","anti-arythmiques","neuroleptique","macrolide","antidépresseur"],"keywords":[],"explanation":"Le Collège cite notamment les antiarythmiques, psychotropes, antibiotiques, antiémétiques et antipaludéens ; une association de médicaments allongeant le QT favorise les torsades.","src":"p. 404","deep":"**Pourquoi** : le Collège cite notamment antiarythmiques, psychotropes, antibiotiques, antiémétiques et antipaludéens ; le Collège cite l'ASSOCIATION de médicaments allongeant le QT parmi les situations de torsade (p. 404).\n**Piège** : la liste n'est pas exhaustive (le Collège renvoie au Vidal) : devant un QT long, relire toute l'ordonnance (p. 404).\n**À relier** : conduite : vérifier médicaments et ionogramme, arrêter les médicaments en cause (p. 404)."},{"id":"231-qroc-814","type":"QROC","rank":"A","objective":"231-obj-20","tags":["ECG","étiologie"],"difficulty":3,"question":"Citez une situation de bradycardie extrême qui favorise les torsades de pointes.","answer":"Échappements à QRS larges de BAV bas situés, intoxication par bradycardisants","accept":["échappement à qrs larges","échappements à qrs larges","intoxication par bradycardisant","bradycardisant","bav bas situé","bav infrahissien","bradycardisants","intoxication"],"keywords":[],"explanation":"La bradycardie extrême allonge le QT : échappements à QRS larges des blocs atrioventriculaires bas situés, intoxication par des médicaments bradycardisants.","src":"p. 404","deep":"**Pourquoi** : une bradycardie extrême allonge le QT et favorise la torsade : échappements à QRS larges des BAV bas situés, intoxication par bradycardisants (p. 404).\n**Piège** : un échappement de BAV bas situé (infrahissien) est à QRS larges ; c'est lui qui est cité, pas le BAV en général (p. 404).\n**À relier** : d'où l'intérêt d'accélérer la FC dans le traitement des torsades (p. 404)."},{"id":"231-qroc-815","type":"QROC","rank":"A","objective":"231-obj-13","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quel est le diagnostic différentiel de la FA devant une tachycardie irrégulière ?","answer":"Les extrasystoles atriales (ESA)","accept":["extrasystoles atriales","extrasystole atriale","esa","extrasystole supraventriculaire"],"keywords":[],"explanation":"L'algorithme devant une tachycardie irrégulière retient la FA, avec comme diagnostic différentiel les extrasystoles atriales.","src":"p. 405","deep":"**Pourquoi** : une tachycardie irrégulière évoque d'abord la FA ; l'algorithme cite les ESA comme diagnostic différentiel, des ESA nombreuses donnant aussi des RR irréguliers (fig. 15.51, p. 405).\n**Piège** : l'ESA se reconnaît à sa P' précoce de morphologie différente avant un QRS fin ; en FA, aucune onde P organisée (p. 392, 397).\n**À relier** : points clés : la FA est le seul diagnostic d'une tachycardie complètement irrégulière à QRS fins (p. 415)."},{"id":"231-qroc-816","type":"QROC","rank":"A","objective":"231-obj-15","tags":["ECG","méthode"],"difficulty":1,"question":"Devant une tachycardie régulière à QRS fins bien tolérée, quel est le premier geste proposé ?","answer":"Des manœuvres vagales (adénosine IV en cas d'échec)","accept":["manœuvres vagales","manoeuvre vagale","manoeuvres vagales","manœuvre vagale","adénosine","manœuvre de valsalva","adénosine iv"],"keywords":[],"explanation":"Une bonne tolérance permet de bloquer transitoirement le NAV par manœuvres vagales, puis adénosine si échec, ce qui fait le diagnostic dans la majorité des cas.","src":"p. 405","deep":"**Pourquoi** : une bonne tolérance laisse le temps de bloquer transitoirement le NAV : manœuvres vagales, puis adénosine IV si échec ; cela fait le diagnostic dans la majorité des cas et arrête une tachycardie jonctionnelle (p. 397, 405).\n**Piège** : si la tolérance hémodynamique est mauvaise, c'est la cardioversion électrique externe d'emblée (p. 405).\n**À relier** : contre-indications de l'adénosine : asthme, hypotension (p. 390), super-Wolff (p. 411)."},{"id":"231-qroc-817","type":"QROC","rank":"A","objective":"231-obj-12","tags":["ECG","méthode"],"difficulty":1,"question":"Quels deux éléments ECG analyse-t-on d'abord devant une tachycardie ?","answer":"La largeur des QRS et la régularité","accept":["largeur des qrs","régularité","regularite","qrs larges ou fins","largeur des qrs et régularité","qrs larges ou fins et régulière ou irrégulière"],"keywords":[],"explanation":"Le Collège résume : devant une tachycardie, on examine la largeur des QRS et la régularité, puis on utilise dans la majorité des cas manœuvres vagales ou adénosine.","src":"p. 405, 415","deep":"**Pourquoi** : deux questions suffisent pour classer une tachycardie : QRS fins ou larges, rythme régulier ou irrégulier (points clés, p. 415 ; fig. 15.51, p. 405).\n**Piège** : irrégulière à QRS fins = FA ; régulière à QRS larges = TV jusqu'à preuve du contraire ; régulière à QRS fins → manœuvres vagales ou adénosine (p. 405, 415).\n**À relier** : tachycardie = FC > 100 bpm (p. 405)."},{"id":"231-qroc-818","type":"QROC","rank":"B","objective":"231-obj-16","tags":["ECG","méthode"],"difficulty":2,"question":"Quand est-il utile de recourir aux manœuvres vagales ou à l'adénosine devant une tachycardie ?","answer":"Dès que le diagnostic n'est pas évident","accept":["diagnostic n'est pas évident","diagnostic pas évident","quand le diagnostic n'est pas évident","si doute diagnostique","en cas de doute"],"keywords":["evident"],"explanation":"Le blocage transitoire du NAV est utile dès que le diagnostic n'est pas évident et permet de poser le diagnostic précis dans la majorité des cas.","src":"p. 405","deep":"**Pourquoi** : le blocage transitoire du NAV (manœuvres vagales ± adénosine) démasque l'activité atriale : il est utile dès que le diagnostic n'est pas évident et fait le diagnostic précis dans la majorité des cas (p. 405).\n**Piège** : il suppose une bonne tolérance : en cas de mauvaise tolérance hémodynamique, cardioversion électrique externe (p. 405) ; pas de blocage du NAV en cas de FA sur préexcitation (p. 410).\n**À relier** : l'adénosine s'utilise si les manœuvres vagales échouent (p. 390)."},{"id":"231-qroc-819","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG","définition"],"difficulty":2,"question":"Que signifie le terme « hypertrophie » d'une cavité sur l'ECG ?","answer":"Augmentation de la quantité de cellules myocardiques d'une cavité","accept":["augmentation de la quantité de cellules","dilatation","épaississement","épaississement de la paroi","augmentation du volume de myocarde","dilatation et/ou épaississement","dilatation ou épaississement"],"keywords":[],"explanation":"Ce terme historique désigne une augmentation du volume de myocarde d'une cavité, par dilatation, épaississement de la paroi ou les deux.","src":"p. 406","deep":"**Pourquoi** : le terme historique « hypertrophie » désigne une augmentation de la quantité de cellules myocardiques d'une cavité, par dilatation, épaississement de paroi, ou les deux (p. 406).\n**Piège** : « hypertrophie » à l'ECG ne veut pas dire seulement paroi épaisse : une dilatation donne le même signe (p. 406) ; et l'échographie a réduit l'intérêt de l'HVD électrique (p. 407).\n**À relier** : le degré d'hypertrophie peut parfois être corrélé à la fibrose de la cavité (p. 406)."},{"id":"231-qroc-820","type":"QROC","rank":"B","objective":"231-obj-03","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Par quel mécanisme survient le plus souvent une hypertrophie atriale droite ?","answer":"Par dilatation de l'oreillette","accept":["dilatation","dilatation de l'oreillette","dilatation de l'oreillette droite","par dilatation","dilatation atriale"],"keywords":["dilatation"],"explanation":"L'hypertrophie atriale droite survient le plus souvent par dilatation ; elle se traduit par une onde P ample, souvent pointue.","src":"p. 406","deep":"**Pourquoi** : l'HAD survient le plus souvent par dilatation : elle donne une P ample (souvent pointue), > 2,5 mm en D2 ou > 2 mm en V1 ou V2 (p. 406).\n**Piège** : HAD = critère d'AMPLITUDE ; HAG = critère de DURÉE (P > 110 ms, en pratique 120 ms, composante négative > 40 ms en V1) (p. 406).\n**À relier** : l'HAD s'associe souvent à l'HVD, avec microvoltage chez le BPCO (p. 407)."},{"id":"231-qroc-821","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG","diagnostic"],"difficulty":2,"question":"Comment calcule-t-on l'indice de Sokolow ?","answer":"Onde S en V1 ou V2 + onde R en V5 ou V6 (normal < 35 mm)","accept":["s en v1 ou v2","s de v1 ou v2 + r de v5 ou v6","onde s en v1","s v1 + r v5","s de v1 ou v2 plus r de v5 ou v6","sv1 + rv5"],"keywords":[],"explanation":"Sokolow = amplitude de l'onde S en V1 ou V2 plus amplitude de l'onde R en V5 ou V6 ; il est normalement inférieur à 35 mm.","src":"p. 406","deep":"**Pourquoi** : Sokolow = amplitude de S en V1 ou V2 + amplitude de R en V5 ou V6 ; la valeur normale est < 35 mm (p. 406).\n**Piège** : c'est un bon marqueur d'HVG, mais l'HVG peut s'accompagner d'anomalies de repolarisation à ne pas prendre pour une ischémie (points clés, p. 415).\n**À relier** : fig. 15.53 : Sokolow à 40 mm avec pseudo sus-ST en V1-V2 et T négative en D1, aVL, V6 (p. 407)."},{"id":"231-qroc-822","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG","diagnostic"],"difficulty":3,"question":"Quelle onde de dépolarisation septale disparaît dans les dérivations latérales dans l'HVG sévère ?","answer":"L'onde Q septale","accept":["onde q","q septale","l'onde q","onde q septale","q de dépolarisation septale"],"keywords":[],"explanation":"Dans la forme sévère d'HVG, la repolarisation secondaire est anormale (T négative, ST sous-décalé en D1, aVL, V5, V6) et l'onde Q septale disparaît dans les mêmes dérivations.","src":"p. 406","deep":"**Pourquoi** : dans l'HVG sévère, la Q de dépolarisation septale disparaît dans les dérivations latérales, en même temps que la T devient négative avec ST sous-décalé (D1, aVL, V5, V6) (p. 406).\n**Piège** : c'est l'inverse d'une nécrose : on perd une petite Q normale, on n'en gagne pas une pathologique (Q de nécrose > 40 ms et > 1/3 du QRS, p. 377).\n**À relier** : Q physiologique < 40 ms et < 1/3 du QRS (p. 375)."},{"id":"231-qroc-823","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quelle déviation axiale accompagne l'HVG ?","answer":"Une déviation modeste vers la gauche","accept":["modeste","gauche","vers la gauche","axe modérément gauche","légère déviation à gauche","déviation axiale gauche modeste"],"keywords":["gauche"],"explanation":"L'HVG s'accompagne d'une déviation axiale modeste à gauche et d'un QRS un peu élargi mais le plus souvent < 120 ms.","src":"p. 406","deep":"**Pourquoi** : l'HVG dévie modestement l'axe vers la gauche ; le QRS peut s'élargir un peu (masse myocardique, fibrose) mais reste souvent < 120 ms (p. 406).\n**Piège** : une déviation au-delà de -30° avec D2 négatif définit l'HBAG (p. 382) : l'HVG ne donne qu'une déviation modeste.\n**À relier** : étiologies de l'HVG : HTA, puis rétrécissement aortique (p. 407)."},{"id":"231-qroc-824","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG","pièges"],"difficulty":2,"question":"Quel piège peut survenir en V1-V2 dans une HVG électrique importante ?","answer":"Un aspect QS de pseudonécrose, mimant une séquelle d'infarctus","accept":["pseudonécrose","pseudonecrose","qs","séquelle d'infarctus","mime une séquelle","pseudo-nécrose","qs en v1-v2","aspect qs"],"keywords":[],"explanation":"Une HVG importante peut donner en V1-V2 un aspect QS mimant une séquelle d'infarctus, et/ou un pseudo sus-décalage du ST.","src":"p. 406-407","deep":"**Pourquoi** : une HVG électrique importante peut donner en V1-V2 un aspect QS qui mime une séquelle d'infarctus (pseudonécrose), et/ou un sus-décalage du ST (p. 406-407).\n**Piège** : ne conclus pas à une nécrose ou à un SCA sans contexte : l'HVG marquée figure parmi les diagnostics différentiels du sus-ST (sus-décalage en V1-V2) (p. 412).\n**À relier** : même piège de pseudonécrose avec des électrodes V1-V2 placées trop haut (p. 373)."},{"id":"231-qroc-825","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG","étiologie"],"difficulty":1,"question":"Quelle est la deuxième étiologie de l'HVG, après l'HTA ?","answer":"Le rétrécissement aortique","accept":["rétrécissement aortique","retrecissement aortique","sténose aortique","stenose aortique","ra","rao","rétrécissement valvulaire aortique","sténose valvulaire aortique"],"keywords":["aortique"],"explanation":"L'étiologie la plus fréquente de l'HVG est l'HTA, puis le rétrécissement aortique.","src":"p. 407","deep":"**Pourquoi** : l'HVG traduit une augmentation de masse du VG ; ses deux causes les plus fréquentes sont l'HTA, puis le rétrécissement aortique (p. 407).\n**Piège** : l'ordre compte : l'HTA est la première étiologie.\n**À relier** : l'ECG est obligatoire dans le bilan d'une HTA (p. 414) ; Sokolow normal < 35 mm (p. 406)."},{"id":"231-qroc-826","type":"QROC","rank":"A","objective":"231-obj-05","tags":["ECG","définition"],"difficulty":3,"question":"Quel terme historique désigne la forme sévère d'HVG, la forme modérée étant dite « diastolique » ?","answer":"La surcharge systolique","accept":["surcharge systolique","systolique","forme systolique"],"keywords":["systolique"],"explanation":"Ces termes historiques (surcharge systolique pour la forme sévère, diastolique pour la forme modérée) n'ont pas de signification sur le mécanisme.","src":"p. 406","deep":"**Pourquoi** : historiquement, la forme sévère d'HVG est dite « surcharge systolique » et la forme modérée « diastolique » (p. 406).\n**Piège** : ces termes n'ont aucune signification sur le mécanisme : ne pas en déduire une surcharge de pression ou de volume (p. 406).\n**À relier** : la forme sévère se reconnaît aux T négatives et ST sous-décalé en latéral, avec perte de la Q septale (p. 406)."},{"id":"231-qroc-827","type":"QROC","rank":"B","objective":"231-obj-04","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quelle amplitude de l'onde S en V5-V6 constitue un critère d'hypertrophie ventriculaire droite ?","answer":"Une onde S ample > 7 mm","accept":["7 mm","> 7","supérieure à 7","plus de 7","s > 7 mm","s supérieure à 7 mm"],"keywords":["7"],"explanation":"En plus de la déviation axiale droite précoce et de la R ample > 6 mm en V1, on retrouve une onde S ample > 7 mm en V5-V6.","src":"p. 407","deep":"**Pourquoi** : après la déviation axiale droite, les autres signes d'HVD sont une R ample > 6 mm en V1 et une S ample > 7 mm en V5-V6 (p. 407).\n**Piège** : le signe le plus précoce n'est pas l'amplitude mais la déviation axiale droite > 110° (en pratique 90°) (p. 407).\n**À relier** : souvent associée : HAD, BBD, microvoltage chez le BPCO (p. 407)."},{"id":"231-qroc-828","type":"QROC","rank":"B","objective":"231-obj-04","tags":["ECG","diagnostic"],"difficulty":1,"question":"Quel trouble de conduction est souvent associé à l'hypertrophie ventriculaire droite ?","answer":"Un bloc de branche droit","accept":["bloc de branche droit","bbd","bloc droit"],"keywords":[],"explanation":"Il y a souvent un bloc de branche droit associé à l'hypertrophie ventriculaire droite.","src":"p. 407","deep":"**Pourquoi** : le Collège note qu'un bloc de branche droit est souvent associé à l'hypertrophie ventriculaire droite (p. 407).\n**Piège** : un BBD isolé n'affirme pas une HVD : il faut la déviation axiale droite, la R ample en V1, la S ample en V5-V6 (p. 407).\n**À relier** : HVD aiguë de l'embolie pulmonaire : aspect S1Q3T3 (p. 407)."},{"id":"231-qroc-829","type":"QROC","rank":"B","objective":"231-obj-04","tags":["ECG","indication"],"difficulty":2,"question":"Chez quels patients l'ECG de l'hypertrophie ventriculaire droite garde-t-il un intérêt clinique ?","answer":"Les patients avec BPCO ou atteinte pulmonaire sévère","accept":["bpco","atteinte pulmonaire","pulmonaire sévère","atteinte pulmonaire sévère","maladie respiratoire chronique"],"keywords":[],"explanation":"L'intérêt de l'HVD à l'ECG est modeste à l'ère de l'échocardiographie, sauf chez les patients avec BPCO ou atteinte pulmonaire sévère.","src":"p. 407","deep":"**Pourquoi** : à l'ère de l'échocardiographie, l'HVD électrique a un intérêt modeste, sauf chez les patients avec BPCO ou atteinte pulmonaire sévère (p. 407).\n**Piège** : chez le BPCO, l'HVD s'associe souvent à une HAD et à un microvoltage (p. 407).\n**À relier** : l'objectif de rang B inclut l'aspect de l'embolie pulmonaire (S1Q3T3) (p. 367, 407)."},{"id":"231-qroc-830","type":"QROC","rank":"B","objective":"231-obj-04","tags":["ECG","pièges"],"difficulty":3,"question":"Quelle anomalie de repolarisation de l'HVD sévère ne faut-il pas confondre avec une ischémie myocardique ?","answer":"Une onde T négative asymétrique en V1 (parfois V2-V3)","accept":["onde t négative","t négative","t négative asymétrique","t négative asymétrique en v1","onde t négative en v1"],"keywords":["negati"],"explanation":"Dans les formes sévères, l'onde T peut être négative et asymétrique en V1 (parfois V2-V3) : aspect trompeur à ne pas confondre avec une ischémie.","src":"p. 407","deep":"**Pourquoi** : dans les formes sévères d'HVD, la T peut être négative et asymétrique en V1, parfois V2-V3 : c'est une anomalie secondaire, trompeuse (p. 407).\n**Piège** : ne pas conclure à une ischémie myocardique sur ce seul aspect (p. 407).\n**À relier** : même logique en HVG : T négative + ST sous-décalé en latéral par anomalie secondaire de repolarisation (p. 406)."},{"id":"231-qroc-831","type":"QROC","rank":"B","objective":"231-obj-04","tags":["ECG","pièges"],"difficulty":2,"question":"Citez une situation sans HVD où l'on retrouve le même aspect de déviation axiale droite.","answer":"Hémibloc postérieur gauche, ou variante de la normale chez le sujet longiligne","accept":["hbpg","hémibloc postérieur","hemibloc posterieur","longiligne","hémibloc postérieur gauche","sujet longiligne"],"keywords":[],"explanation":"Une déviation axiale droite se voit aussi dans l'hémibloc postérieur gauche et comme variante de la normale chez les sujets longilignes.","src":"p. 407","deep":"**Pourquoi** : une déviation axiale droite isolée n'est pas spécifique : le même aspect se voit dans l'HBPG et comme variante normale chez le sujet longiligne (p. 407).\n**Piège** : l'HBPG lui-même ne se retient qu'après avoir exclu une pathologie du VD, une morphologie longiligne, un infarctus latéral et une inversion d'électrodes (p. 382-383).\n**À relier** : signe le plus précoce d'HVD : axe > 110° (en pratique 90°) (p. 407)."},{"id":"231-qroc-832","type":"QROC","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":1,"question":"Quel aspect de l'onde T observe-t-on en cas d'hypokaliémie ?","answer":"Onde T plate ou négative, diffuse, avec ST sous-décalé","accept":["plate","t plate","t négative","aplatie","négative","onde t plate","t plate ou négative","aplatissement de l'onde t","t négative diffuse"],"keywords":[],"explanation":"L'hypokaliémie donne une onde T plate ou négative et diffuse avec un ST sous-décalé, un QRS normal, un QT allongé et parfois une onde U.","src":"p. 408","deep":"**Pourquoi** : l'hypokaliémie touche la repolarisation : T plate ou négative, diffuse, ST sous-décalé, QT allongé et onde U (p. 408).\n**Piège** : l'onde U ne doit pas être intégrée dans le QT (p. 408) ; l'hyperkaliémie donne au contraire une T ample, pointue, symétrique (p. 408).\n**À relier** : complications : ESV, TV, torsade de pointes, FV (p. 408)."},{"id":"231-qroc-833","type":"QROC","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":2,"question":"Quel est l'aspect du QRS dans l'hypokaliémie ?","answer":"Normal (fin)","accept":["normal","qrs fin","inchangé","qrs normal"],"keywords":["normal"],"explanation":"À la différence de l'hyperkaliémie qui élargit le QRS, le QRS reste normal en cas d'hypokaliémie.","src":"p. 408","deep":"**Pourquoi** : dans l'hypokaliémie, les anomalies portent sur la repolarisation (T, ST, QT, onde U) ; le QRS reste normal (p. 408).\n**Piège** : c'est l'hyperkaliémie qui élargit le QRS et allonge le PR (p. 408).\n**À relier** : hypokaliémie = cause de QT long et de torsade (p. 404)."},{"id":"231-qroc-834","type":"QROC","rank":"A","objective":"231-obj-21","tags":["ECG","complications"],"difficulty":2,"question":"Citez deux troubles du rythme ventriculaire pouvant compliquer une hypokaliémie.","answer":"Extrasystoles, TV, torsade de pointes, fibrillation ventriculaire","accept":["extrasystole","tachycardie ventriculaire","torsade","fibrillation ventriculaire","extrasystoles ventriculaires","tv","torsades de pointes","fv"],"keywords":[],"explanation":"L'hypokaliémie expose aux extrasystoles ventriculaires, à la TV, à la torsade de pointes et à la FV, notamment par allongement du QT.","src":"p. 408","deep":"**Pourquoi** : l'hypokaliémie allonge le QT et favorise les arythmies ventriculaires : extrasystoles, TV, torsade de pointes, FV (p. 404, 408).\n**Piège** : ces complications concernent le versant ventriculaire ; l'hyperkaliémie, elle, donne surtout BAV, TV, dysfonction sinusale (p. 408).\n**À relier** : torsade : corriger les ions, accélérer la FC, arrêter les médicaments allongeant le QT (p. 404)."},{"id":"231-qroc-835","type":"QROC","rank":"A","objective":"231-obj-21","tags":["ECG","complications"],"difficulty":2,"question":"Citez deux troubles rythmiques ou conductifs qui peuvent compliquer une hyperkaliémie.","answer":"BAV, tachycardie ventriculaire, dysfonction sinusale","accept":["bav","bloc atrioventriculaire","tachycardie ventriculaire","dysfonction sinusale"],"keywords":[],"explanation":"À côté de l'onde T ample, pointue et symétrique, de l'allongement du PR et de l'élargissement du QRS, l'hyperkaliémie peut donner BAV, TV ou dysfonction sinusale.","src":"p. 408","deep":"**Pourquoi** : à côté de la T ample, pointue et symétrique, l'hyperkaliémie allonge le PR et élargit le QRS ; ses complications rythmiques et conductives sont le BAV, la TV et la dysfonction sinusale (p. 408).\n**Piège** : fig. 15.55 : les T peuvent être géantes alors que les QRS ne sont pas encore larges (p. 409).\n**À relier** : hypokaliémie : T plate, onde U, QT long, QRS normal (p. 408) ; dyskaliémie = indication d'ECG en urgence (p. 368)."},{"id":"231-qroc-836","type":"QROC","rank":"B","objective":"231-obj-23","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quelle concavité a le sus-décalage du ST d'une péricardite aiguë ?","answer":"Concave vers le haut (diffus, concordant, sans miroir)","accept":["concave","concave vers le haut","concavité vers le haut"],"keywords":["concave"],"explanation":"En phase initiale, le sus-décalage du ST est concave vers le haut, diffus, concordant, sans image en miroir.","src":"p. 409","deep":"**Pourquoi** : dans la péricardite, l'atteinte est diffuse : sus-ST concave vers le haut, diffus, concordant, sans image en miroir (phase 1, p. 409).\n**Piège** : l'absence de miroir ne suffit pas : elle peut manquer dans un SCA ST+ (p. 409).\n**À relier** : autres signes de phase 1 : sous-décalage de PQ et microvoltage (p. 409) ; points clés : ne pas évoquer à tort une péricardite au cours d'un SCA (p. 415)."},{"id":"231-qroc-837","type":"QROC","rank":"B","objective":"231-obj-23","tags":["ECG","diagnostic"],"difficulty":2,"question":"Dans quel type de péricardite le microvoltage est-il le plus marqué ?","answer":"La péricardite liquidienne (épanchement abondant)","accept":["liquidienne","épanchement","epanchement","péricardite liquidienne","épanchement abondant","épanchement péricardique"],"keywords":[],"explanation":"Le microvoltage de la phase 1 est d'autant plus important que la péricardite est liquidienne.","src":"p. 409","deep":"**Pourquoi** : le Collège lie l'intensité du microvoltage à l'épanchement : le microvoltage de phase 1 est d'autant plus marqué que la péricardite est liquidienne (p. 409).\n**Piège** : le microvoltage est un signe de phase 1, il n'est pas présent dans toutes les péricardites.\n**À relier** : microvoltage aussi chez le BPCO avec HVD (p. 407)."},{"id":"231-qroc-838","type":"QROC","rank":"B","objective":"231-obj-23","tags":["ECG","pièges"],"difficulty":3,"question":"Pourquoi l'absence d'image en miroir ne permet-elle pas de conclure à une péricardite devant un sus-décalage du ST ?","answer":"L'image en miroir peut aussi être absente dans un SCA ST+","accept":["peut être absente","peut manquer","absente","sca st","miroir absent dans un sca","peut être absent","l'image en miroir peut manquer"],"keywords":["miroir"],"explanation":"Il ne faut pas conclure à tort à une péricardite aiguë devant un SCA avec sus-décalage du ST, car l'image en miroir peut être absente.","src":"p. 409","deep":"**Pourquoi** : l'image en miroir peut être absente dans un SCA ST+ : son absence n'exclut pas un infarctus et ne prouve pas une péricardite (p. 409).\n**Piège** : ne conclus pas à tort à une péricardite (encadré « Attention », p. 409) : le contexte et la systématisation du sus-ST (2 dérivations adjacentes) comptent (p. 412).\n**À relier** : SCA ST+ : sus-ST typé onde de Pardee avec miroir (p. 412) ; péricardite : diffus, concave, PQ sous-décalé (p. 409)."},{"id":"231-qroc-839","type":"QROC","rank":"B","objective":"231-obj-23","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quel est l'aspect de la repolarisation à la phase 2 d'une péricardite aiguë ?","answer":"Ondes T plates dans toutes les dérivations, ST isoélectrique","accept":["t plates","ondes t plates","t aplaties","t plate","ondes t plates diffuses"],"keywords":[],"explanation":"Phase 2 : les ondes T s'aplatissent dans toutes les dérivations et le segment ST redevient isoélectrique.","src":"p. 409","deep":"**Pourquoi** : après la phase 1 (sus-ST), la phase 2 voit le ST revenir à l'isoélectrique et les T s'aplatir dans toutes les dérivations (p. 409).\n**Piège** : T plates (phase 2) ≠ T négatives (phase 3) : ne pas inverser l'ordre.\n**À relier** : phase 1 brève : microvoltage, sus-ST concave diffus, PQ sous-décalé ; phase 3 : T négatives persistantes ; phase 4 : normalisation (p. 409)."},{"id":"231-qroc-840","type":"QROC","rank":"B","objective":"231-obj-23","tags":["ECG","diagnostic"],"difficulty":2,"question":"Que se passe-t-il aux phases 3 et 4 de la péricardite aiguë ?","answer":"T négatives persistantes (ph. 3), puis retour progressif à la normale (ph. 4)","accept":["t négatives","t négative","onde t négative","retour à la normale","t négatives puis normalisation","t négatives persistantes"],"keywords":["negati"],"explanation":"Phase 3 : ondes T négatives persistantes ; phase 4 : retour progressif à la normale.","src":"p. 409","deep":"**Pourquoi** : l'évolution classique en 4 phases se termine par des T négatives persistantes (phase 3) puis un retour progressif à la normale (phase 4) (p. 409).\n**Piège** : des T négatives diffuses après une péricardite font partie de l'évolution attendue ; dans le SCA, la T négative « ischémique » apparaît après 48 h dans le territoire (p. 412).\n**À relier** : phase 1 : sus-ST ; phase 2 : T plates (p. 409)."},{"id":"231-qroc-841","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG","définition"],"difficulty":1,"question":"Qu'est-ce qu'un faisceau de Kent ?","answer":"Une voie accessoire : fibre musculaire reliant oreillette et ventricule","accept":["voie accessoire","fibre musculaire","oreillette au ventricule","fibre musculaire ectopique","faisceau accessoire"],"keywords":[],"explanation":"Le faisceau de Kent est une fibre musculaire ectopique connectant l'atrium au ventricule, qui ajoute un second passage possible à côté du NAV.","src":"p. 410","deep":"**Pourquoi** : normalement, le NAV est le seul passage entre oreillettes et ventricules ; le faisceau de Kent est une fibre musculaire ectopique qui crée un second passage, en compétition avec le NAV, et peut conduire dans les deux sens (p. 410).\n**Piège** : voie accessoire ≠ syndrome de WPW : le WPW suppose des palpitations par tachycardie jonctionnelle (p. 411).\n**À relier** : la tachycardie par rythme réciproque est une réentrée par le faisceau de Kent (p. 396)."},{"id":"231-qroc-842","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG","définition"],"difficulty":2,"question":"Que désigne la préexcitation ventriculaire ?","answer":"Excitation du ventricule avant sa dépolarisation physiologique par le NAV","accept":["avant sa dépolarisation","avant la dépolarisation","avant le nav","précoce du ventricule","avant la dépolarisation physiologique","excitation précoce du ventricule","ventricule activé avant le nav","avant la dépolarisation par le nav"],"keywords":["avant"],"explanation":"Si la voie accessoire conduit rapidement l'influx de l'oreillette au ventricule, une partie du ventricule est excitée avant sa dépolarisation par le NAV.","src":"p. 410","deep":"**Pourquoi** : si la voie accessoire conduit vite, une partie du ventricule est activée avant l'arrivée de l'influx par le NAV : c'est la préexcitation (p. 410).\n**Piège** : l'onde delta n'est que la partie préexcitée ; le reste du ventricule est activé normalement par le NAV, d'où la superposition des deux activations (fig. 15.57, p. 410).\n**À relier** : ECG : PR court < 120 ms, onde delta élargissant le QRS, troubles de repolarisation dans le territoire de la voie (p. 410)."},{"id":"231-qroc-843","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG","méthode"],"difficulty":2,"question":"Pourquoi bloquer le NAV (massage, adénosine) permet-il de démasquer une préexcitation minime ?","answer":"L'influx ne passe plus que par la voie accessoire","accept":["voie accessoire","seulement par la voie accessoire","uniquement par la voie accessoire","seule la voie accessoire conduit","l'influx emprunte la voie accessoire","passe uniquement par la voie accessoire"],"keywords":["accessoire"],"explanation":"Le blocage du NAV force l'influx à emprunter la seule voie accessoire, ce qui révèle la préexcitation ; on ne le fait pas en cas de FA.","src":"p. 410","deep":"**Pourquoi** : bloquer le NAV (massage, adénosine) supprime la compétition : l'influx ne passe plus que par la voie accessoire et la préexcitation devient évidente (p. 410).\n**Piège** : à ne pas faire en cas de FA : la voie accessoire, sans conduction décrémentielle, laisserait passer une FA très rapide (super-Wolff, risque de FV) (p. 410-411).\n**À relier** : préexcitation : PR < 120 ms, onde delta (p. 410)."},{"id":"231-qroc-844","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG","définition"],"difficulty":2,"question":"Comment définit-on le syndrome de Wolff-Parkinson-White ?","answer":"Voie accessoire antérograde + palpitations par tachycardie jonctionnelle","accept":["voie accessoire antérograde","tachycardie jonctionnelle","palpitations","voie accessoire","voie accessoire et palpitations","préexcitation avec palpitations"],"keywords":[],"explanation":"Le syndrome de WPW désigne une voie accessoire antérograde qui occasionne des palpitations par un mécanisme de tachycardie jonctionnelle.","src":"p. 411","deep":"**Pourquoi** : on parle de syndrome de WPW quand la voie accessoire antérograde occasionne des palpitations par tachycardie jonctionnelle (rythme réciproque) (p. 396, 411).\n**Piège** : une préexcitation sans palpitations n'est pas un « syndrome » de WPW ; le risque majeur est la FA conduite par une voie très perméable (super-Wolff) (p. 411).\n**À relier** : préexcitation = PR court, onde delta, troubles de repolarisation (p. 410)."},{"id":"231-qroc-845","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG","physiopathologie"],"difficulty":3,"question":"Pourquoi une voie accessoire bien perméable expose-t-elle à la mort subite en cas de FA ?","answer":"Pas de conduction décrémentielle : filtre mal la FA, risque de FV","accept":["pas de conduction décrémentielle","pas décrémentielle","ne filtre pas","propriété décrémentielle","absence de filtre","pas de filtre","filtre mal","propriété décrémentielle absente","conduction non décrémentielle","filtre mal les impulsions atriales"],"keywords":[],"explanation":"La voie accessoire n'a pas la propriété décrémentielle du NAV : elle filtre mal l'influx des oreillettes, d'où une tachycardie irrégulière extrêmement rapide à QRS de largeur variable, pouvant dégénérer en FV.","src":"p. 411","deep":"**Pourquoi** : le NAV a une conduction décrémentielle qui filtre les influx atriaux rapides ; la voie accessoire n'a pas cette propriété : en FA, une voie à période réfractaire courte laisse passer une tachycardie extrêmement rapide (p. 390, 411).\n**Piège** : aspect : tachycardie irrégulière à QRS larges de taille variable (« en accordéon »), pouvant dégénérer en FV ; ne pas bloquer le NAV (adénosine contre-indiquée) (p. 410-411).\n**À relier** : p. 411 : le super-Wolff est la seule autre CI à l'adénosine avec l'asthme (p. 390 cite aussi l'hypotension)."},{"id":"231-qroc-846","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG","diagnostic"],"difficulty":2,"question":"Comment nomme-t-on l'association d'une FA rapide et d'une voie accessoire qui ne ralentit pas la conduction ?","answer":"Le « super-Wolff »","accept":["super-wolff","super wolff","superwolff","fa préexcitée","super-wpw"],"keywords":["wolff"],"explanation":"Dans le super-Wolff, la FA rapide est conduite par une voie accessoire non filtrante ; c'est une contre-indication à l'adénosine, comme l'asthme.","src":"p. 411","deep":"**Pourquoi** : dans le super-Wolff, une FA rapide est conduite par une voie accessoire qui, contrairement au NAV, ne ralentit pas la conduction : tachycardie irrégulière extrêmement rapide, à QRS larges de taille variable « en accordéon » (p. 411).\n**Piège** : c'est une contre-indication à l'adénosine et à tout blocage du NAV, qui forcerait le passage par la voie accessoire (p. 410-411) ; risque de dégénérescence en FV.\n**À relier** : p. 411 cite le super-Wolff comme seule autre CI à l'adénosine avec l'asthme ; l'encadré p. 390 cite asthme et hypotension."},{"id":"231-qroc-847","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Que localise le sus-décalage du segment ST dans un SCA ST+ ?","answer":"Le territoire de la coronaire occluse","accept":["coronaire occluse","territoire","artère occluse","la coronaire occluse","territoire de la coronaire occluse"],"keywords":["coronaire"],"explanation":"Il faut d'abord traquer le sus-décalage, qui indique le territoire dont la coronaire est occluse, puis chercher le miroir sous forme de sous-décalage, et non l'inverse.","src":"p. 411","deep":"**Pourquoi** : le sus-décalage du ST apparaît dans les dérivations qui regardent la zone lésée : il indique le territoire dont la coronaire est occluse (p. 411).\n**Piège** : on traque d'abord le sus-décalage puis son miroir (sous-décalage), pas l'inverse : un sous-décalage V1-V3 peut être le miroir d'un ST+ postérieur, d'où l'ECG 18 dérivations (p. 411).\n**À relier** : territoires : inférieur D2-D3-aVF, antéroseptal V1-V3, latéral D1-aVL-V5-V6, postérieur V7-V9 (p. 374)."},{"id":"231-qroc-848","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","urgence"],"difficulty":2,"question":"Devant un BBG complet avec douleur thoracique aiguë, quels examens permettent d'éliminer un SCA ST+ ?","answer":"Une échographie, ± coronarographie","accept":["échographie","echographie","coronarographie","échographie cardiaque","ett"],"keywords":[],"explanation":"La présence d'un BBG complet dans ce contexte doit faire éliminer un SCA avec sus-décalage du ST par échographie ± coronarographie.","src":"p. 412","deep":"**Pourquoi** : en BBG, la repolarisation antérieure est difficile à interpréter (discordance appropriée) : l'ECG ne permet pas d'exclure un SCA ST+, on s'appuie sur l'échographie ± la coronarographie (p. 381, 412).\n**Piège** : un BBG n'est pas rassurant dans ce contexte : douleur thoracique persistante + BBG = évoquer un infarctus antérieur, évaluation cardiologique rapide sans attendre la troponine (p. 381).\n**À relier** : arguments à chercher : sémiologie de la douleur (effet de la TNT), signes de choc, ETT (p. 381)."},{"id":"231-qroc-849","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Comment évolue le sus-décalage du ST avec la reperfusion, et sans reperfusion ?","answer":"Il régresse rapidement avec la reperfusion, dure plusieurs jours sans","accept":["régresse rapidement","plusieurs jours","rapidement","plusieurs jours sans reperfusion","disparaît rapidement"],"keywords":["rapid","jours"],"explanation":"Le sus-décalage régresse rapidement avec la reperfusion et dure plusieurs jours en son absence ; il peut persister indéfiniment en cas d'évolution anévrismale.","src":"p. 412","deep":"**Pourquoi** : le sus-ST reflète la lésion en cours : il régresse rapidement quand l'artère est reperfusée et dure plusieurs jours en l'absence de reperfusion (p. 412).\n**Piège** : un sus-décalage qui persiste indéfiniment fait évoquer une évolution anévrismale de la paroi infarcie (p. 412).\n**À relier** : évolution normale après 48 h : onde T négative « ischémique », parfois très longtemps (p. 412)."},{"id":"231-qroc-850","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quelle évolution normale de la repolarisation observe-t-on après 48 heures d'un SCA ST+ ?","answer":"Une onde T négative « ischémique », parfois très prolongée","accept":["t négative","onde t négative","t inversée","t ischémique","t négative ischémique","t inversées"],"keywords":["negati"],"explanation":"Après 48 heures, le sus-décalage évolue normalement vers une onde T négative dite « ischémique », parfois pendant très longtemps.","src":"p. 412","deep":"**Pourquoi** : après 48 heures, l'évolution normale d'un SCA ST+ se fait vers une onde T négative dite « ischémique », qui peut persister très longtemps (p. 412).\n**Piège** : une T négative séquellaire n'est pas forcément une récidive ; à l'inverse, un sus-ST qui persiste évoque un anévrisme ventriculaire (p. 412).\n**À relier** : les ondes Q de nécrose apparaissent en principe vers la 6e heure (p. 412)."},{"id":"231-qroc-851","type":"QROC","rank":"B","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Citez deux étiologies de sus-décalage du ST autres que le SCA ST+.","answer":"Anévrisme VG, repolarisation précoce, angor de Prinzmetal, péricardite","accept":["anévrisme","repolarisation précoce","prinzmetal","péricardite","anevrisme","anévrisme ventriculaire","angor de prinzmetal","péricardite aiguë"],"keywords":[],"explanation":"Les cinq étiologies à connaître sont le SCA ST+, l'anévrisme ventriculaire, la repolarisation précoce, l'angor de Prinzmetal et la péricardite.","src":"p. 412","deep":"**Pourquoi** : le sus-ST n'est pas toujours un SCA : le Collège liste 5 étiologies, SCA ST+, anévrisme ventriculaire, repolarisation précoce, angor de Prinzmetal, péricardite (encadré p. 412).\n**Piège** : ne pas oublier les diagnostics différentiels : BBG ou stimulation ventriculaire (sus-ST approprié là où le QRS est négatif) et HVG marquée (sus-ST en V1-V2) (p. 412).\n**À relier** : le SCA ST+ se distingue par un sus-ST typé onde de Pardee avec miroir, sur ≥ 2 dérivations adjacentes (p. 412)."},{"id":"231-qroc-852","type":"QROC","rank":"B","objective":"231-obj-24","tags":["ECG","étiologie"],"difficulty":1,"question":"Quelle étiologie de sus-décalage du ST correspond à un spasme coronarien ?","answer":"L'angor de Prinzmetal","accept":["prinzmetal","angor de prinzmetal","angor spastique"],"keywords":["prinzmetal"],"explanation":"Le spasme coronarien de l'angor de Prinzmetal donne un sus-décalage semblable à celui du SCA avec sus-décalage du ST.","src":"p. 412","deep":"**Pourquoi** : dans l'angor de Prinzmetal, le spasme coronarien donne un sus-décalage semblable à celui d'un SCA ST+ (p. 412).\n**Piège** : l'aspect ECG ne suffit pas à distinguer spasme et occlusion : c'est l'une des 5 étiologies de sus-ST à garder en tête (p. 412).\n**À relier** : les 4 autres : SCA ST+, anévrisme ventriculaire, repolarisation précoce, péricardite (p. 412)."},{"id":"231-qroc-853","type":"QROC","rank":"B","objective":"231-obj-24","tags":["ECG","pièges"],"difficulty":3,"question":"Dans un BBG ou une stimulation ventriculaire, dans quelles dérivations le ST est-il sus-décalé de façon appropriée ?","answer":"Celles où le QRS est négatif","accept":["qrs négatif","qrs est négatif","où le qrs est négatif","là où le qrs est négatif","dérivations à qrs négatif","qrs négatifs"],"keywords":["negatif"],"explanation":"Dans les dérivations où le QRS est négatif, le segment ST est sus-décalé de manière appropriée (discordance), ce qui complique le diagnostic de SCA.","src":"p. 412","deep":"**Pourquoi** : quand le QRS est large (BBG, stimulation ventriculaire), la repolarisation est discordante : là où le QRS est négatif, le ST est sus-décalé de manière appropriée (p. 381, 412).\n**Piège** : ce sus-ST approprié peut faire évoquer à tort un SCA ST+ : la clinique est cruciale (p. 381).\n**À relier** : là où le QRS est positif : T négative et petit sous-décalage du ST (p. 381)."},{"id":"231-qroc-854","type":"QROC","rank":"B","objective":"231-obj-05","tags":["ECG","pièges"],"difficulty":3,"question":"Dans une HVG marquée, où trouve-t-on un sous-décalage du ST, et où un sus-décalage ?","answer":"Sous-décalage latéral ; sus-décalage en V1-V2","accept":["latéral","latérales","v1-v2","v1 et v2","sous-décalage latéral et sus-décalage en v1-v2"],"keywords":[],"explanation":"Une HVG marquée peut donner un sous-décalage de ST dans les dérivations latérales et un sus-décalage en V1-V2 : diagnostic différentiel du sus-décalage du ST.","src":"p. 412","deep":"**Pourquoi** : l'HVG marquée perturbe secondairement la repolarisation : sous-décalage du ST en latéral et sus-décalage en V1-V2 (p. 412 ; T négative en D1, aVL, V5, V6, p. 406).\n**Piège** : ce sus-ST en V1-V2 est un diagnostic différentiel du SCA ST+, avec la pseudonécrose QS (p. 406, 412).\n**À relier** : fig. 15.53 : Sokolow 40 mm, « pseudo » sus-ST V1-V2 (p. 407)."},{"id":"231-qroc-855","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":1,"question":"À quel moment apparaissent en principe les ondes Q de nécrose d'un SCA ST+ ?","answer":"Vers la 6e heure","accept":["6e heure","6 heures","sixième heure","6e h"],"keywords":["6"],"explanation":"Les ondes Q de nécrose apparaissent en principe vers la 6e heure mais peuvent être parfois plus précoces.","src":"p. 412","deep":"**Pourquoi** : la nécrose s'installe en quelques heures : les ondes Q apparaissent en principe vers la 6e heure, mais peuvent être plus précoces au cours d'un SCA ST+ (p. 412).\n**Piège** : leur présence ne signifie pas qu'il est trop tard pour reperfuser (p. 412).\n**À relier** : Q de nécrose : au moins 1/3 (ou 1/4) du QRS et > 30-40 ms ; parfois remplacées par un écrêtement de R (p. 412)."},{"id":"231-qroc-856","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","pièges"],"difficulty":2,"question":"Que ne faut-il pas conclure à tort de l'apparition d'ondes Q de nécrose ?","answer":"Qu'une reperfusion serait inutile car trop tardive","accept":["reperfusion inutile","inutile","trop tardive","trop tard","trop tard pour reperfuser","reperfusion tardive inutile"],"keywords":[],"explanation":"L'apparition d'ondes Q ne doit pas faire considérer à tort que la reperfusion est inutile car trop tardive.","src":"p. 412","deep":"**Pourquoi** : les ondes Q peuvent apparaître précocement au cours d'un SCA ST+ : leur présence ne doit pas faire considérer à tort qu'une reperfusion serait inutile car trop tardive (p. 412).\n**Piège** : « Q présente » ne veut pas dire « trop tard » : les Q apparaissent en principe vers la 6e heure mais peuvent être précoces au cours du SCA ST+ (p. 412).\n**À relier** : Q de nécrose = au moins 1/3 (ou 1/4) du QRS et > 30-40 ms, parfois remplacées par un écrêtement de R en V2-V4 (p. 412)."},{"id":"231-qroc-857","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Citez une anomalie des ondes T possible dans un SCA sans sus-décalage de ST, autre que l'inversion.","answer":"Aplatissement, ou pseudo-normalisation d'ondes T antérieurement négatives","accept":["aplatissement","pseudo-normalisation","pseudonormalisation","t plate","aplatissement des ondes t","pseudo-normalisation des t","onde t plate"],"keywords":[],"explanation":"Un SCA sans sus-décalage peut donner un sous-décalage de ST, une inversion des T, une pseudo-normalisation de T négatives, un aplatissement des T, voire un ECG normal.","src":"p. 412","deep":"**Pourquoi** : l'ECG d'un SCA sans sus-décalage est très variable : sous-décalage du ST, inversion des T, pseudo-normalisation de T antérieurement négatives, aplatissement des T (p. 412).\n**Piège** : un ECG normal n'élimine pas un SCA sans ST, et un pacemaker peut masquer les anomalies (p. 412).\n**À relier** : sous-décalage = lésion sous-endocardique ; T inversée = ischémie sous-épicardique (p. 412)."},{"id":"231-qroc-858","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","pièges"],"difficulty":2,"question":"Quel dispositif cardiaque peut masquer les anomalies ECG d'un SCA sans sus-décalage du ST ?","answer":"Un pacemaker","accept":["pacemaker","stimulateur","stimulation","stimulateur cardiaque","stimulation ventriculaire"],"keywords":[],"explanation":"Les anomalies d'un SCA sans sus-décalage peuvent être masquées par un pacemaker.","src":"p. 412","deep":"**Pourquoi** : un pacemaker stimulant le ventricule donne des QRS larges d'aspect BBG avec repolarisation secondaire : les anomalies d'un SCA sans sus-décalage peuvent être masquées (p. 412, 414).\n**Piège** : un ECG stimulé « sans anomalie visible » n'élimine pas un SCA.\n**À relier** : la stimulation ventriculaire est aussi un diagnostic différentiel du sus-ST (sus-ST approprié là où le QRS est négatif) (p. 412)."},{"id":"231-qroc-859","type":"QROC","rank":"B","objective":"231-obj-26","tags":["ECG","traitement"],"difficulty":2,"question":"Quel BAV du 2e degré n'impose un pacemaker que s'il est symptomatique ?","answer":"Le BAV2 Mobitz 1","accept":["mobitz 1","mobitz i","wenckebach","luciani","bav2 mobitz 1","bav 2 mobitz 1"],"keywords":[],"explanation":"Le pacemaker est indiqué pour les bradycardies symptomatiques (dysfonction sinusale, BAV2 Mobitz 1, bradycardie sinusale) ; les BAV infrahissiens (Mobitz 2, BAV3) l'indiquent même sans symptôme.","src":"p. 412","deep":"**Pourquoi** : le BAV2 Mobitz 1 est suprahissien : comme la dysfonction sinusale et la bradycardie sinusale, il n'indique un pacemaker que s'il est symptomatique (p. 412).\n**Piège** : ne confonds pas avec Mobitz 2 et BAV3, infrahissiens, qui l'indiquent même sans symptôme (p. 412).\n**À relier** : Mobitz 1 = allongement progressif du PR puis P bloquée (p. 385)."},{"id":"231-qroc-860","type":"QROC","rank":"B","objective":"231-obj-26","tags":["ECG","traitement"],"difficulty":1,"question":"Quel dispositif implantable est indiqué en cas de TV ou de FV ?","answer":"Un défibrillateur (implantable)","accept":["défibrillateur","defibrillateur","dai","défibrillateur automatique implantable","défibrillateur implantable"],"keywords":[],"explanation":"Le défibrillateur traite les troubles du rythme ventriculaire rapides (TV, FV), le pacemaker les bradycardies, la resynchronisation l'insuffisance cardiaque avec BBG.","src":"p. 413","deep":"**Pourquoi** : le défibrillateur traite le problème rythmique ventriculaire (TV, FV) : il délivre un champ électrique qui réinitialise l'activation de tous les myocytes du champ (fig. 15.60, p. 413).\n**Piège** : pacemaker = bradycardie ; resynchronisation = problème hémodynamique (BBG désynchronisant + insuffisance cardiaque) (p. 413).\n**À relier** : le défibrillateur fait aussi pacemaker, sauf s'il est sous-cutané (p. 413)."},{"id":"231-qroc-861","type":"QROC","rank":"B","objective":"231-obj-26","tags":["ECG","traitement"],"difficulty":3,"question":"Quelle fonction n'assure pas un défibrillateur sous-cutané ?","answer":"La fonction pacemaker (stimulation)","accept":["pacemaker","stimulation","stimulateur","fonction pacemaker"],"keywords":[],"explanation":"Un défibrillateur fait toujours fonction de pacemaker, sauf s'il est sous-cutané.","src":"p. 413","deep":"**Pourquoi** : un défibrillateur fait toujours fonction de pacemaker, sauf s'il est sous-cutané (fig. 15.60, p. 413).\n**Piège** : ne généralise pas : seul le défibrillateur sous-cutané ne stimule pas ; la resynchronisation, étant un stimulateur, assure toujours la fonction pacemaker (p. 413).\n**À relier** : les trois fonctions peuvent être associées : défibrillateur de resynchronisation (p. 413)."},{"id":"231-qroc-862","type":"QROC","rank":"B","objective":"231-obj-26","tags":["ECG","définition"],"difficulty":2,"question":"Quelle est la durée d'une impulsion de pacemaker ?","answer":"0,4 à 1 ms","accept":["0,4 à 1","0,4 et 1","0,4-1","0.4","0,4-1 ms","0.4 à 1 ms"],"keywords":["1 ms"],"explanation":"Le spike dure entre 0,4 et 1 ms : rien de physiologique n'est aussi bref sur l'ECG, d'où son caractère pathognomonique.","src":"p. 413","deep":"**Pourquoi** : une impulsion de pacemaker dure 0,4 à 1 ms : rien de physiologique n'est aussi bref sur l'ECG, d'où le « spike », pathognomonique d'une stimulation (p. 413).\n**Piège** : un spike bipolaire est peu visible sur l'ECG de surface : sa discrétion n'exclut pas une stimulation (p. 414).\n**À relier** : après le spike : P (stimulation atriale) ou QRS large d'aspect BBG (stimulation ventriculaire) (p. 414)."},{"id":"231-qroc-863","type":"QROC","rank":"B","objective":"231-obj-26","tags":["ECG","diagnostic"],"difficulty":2,"question":"En cas de dysfonction sinusale, que voit-on après le spike d'un pacemaker ?","answer":"Une onde P (stimulation atriale)","accept":["onde p","p après le spike","stimulation atriale","une onde p"],"keywords":[],"explanation":"En dysfonction sinusale, le pacemaker stimule l'oreillette : le spike est suivi d'une onde P.","src":"p. 414","deep":"**Pourquoi** : dans la dysfonction sinusale, c'est le nœud sinusal qui fait défaut : le pacemaker stimule l'oreillette, le spike est donc suivi d'une onde P (p. 414).\n**Piège** : en cas de BAV, le spike est suivi d'un QRS large (stimulation ventriculaire) (p. 414).\n**À relier** : indication : dysfonction sinusale symptomatique (p. 412)."},{"id":"231-qroc-864","type":"QROC","rank":"B","objective":"231-obj-26","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Comment fonctionne un pacemaker en cas de BAV ?","answer":"Il écoute l'oreillette et stimule le ventricule après un délai AV programmé","accept":["écoute l'oreillette","délai av","délai atrioventriculaire","stimule le ventricule","stimule le ventricule après un délai av","détecte l'oreillette","délai av programmé"],"keywords":[],"explanation":"En cas de BAV, le pacemaker détecte l'activité de l'oreillette puis stimule le ventricule avec un délai AV programmé, afin de synchroniser oreillette et ventricule.","src":"p. 414","deep":"**Pourquoi** : en cas de BAV, l'oreillette fonctionne : le pacemaker détecte son activité puis stimule le ventricule après un délai AV programmé, ce qui synchronise oreillette et ventricule (p. 414).\n**Piège** : le QRS stimulé est large, d'aspect BBG (stimulation du VD, conduction de proche en proche) : ce n'est pas un vrai BBG (p. 414).\n**À relier** : BAV infrahissien = pacemaker même sans symptôme (p. 412)."},{"id":"231-qroc-865","type":"QROC","rank":"B","objective":"231-obj-26","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Pourquoi le QRS stimulé en ventriculaire droit a-t-il un aspect de BBG ?","answer":"Propagation lente de proche en proche, hors réseau His-Purkinje","accept":["de proche en proche","hors du réseau","hors his-purkinje","conduction lente","conduction lente de proche en proche"],"keywords":["proche"],"explanation":"La stimulation ventriculaire droite est transmise au reste des ventricules par conduction lente de proche en proche, et non par le réseau de His-Purkinje : QRS large d'aspect BBG.","src":"p. 414","deep":"**Pourquoi** : la sonde stimule le VD ; l'influx gagne le reste des ventricules de proche en proche, lentement, sans emprunter le réseau de His-Purkinje : le VG est activé en dernier, d'où l'aspect de BBG (p. 414).\n**Piège** : c'est le même mécanisme que la TV ou l'ESV (QRS large par conduction de proche en proche) (p. 397-398).\n**À relier** : dans le BBG vrai aussi, la paroi latérale gauche est activée tardivement (p. 380)."},{"id":"231-qroc-866","type":"QROC","rank":"B","objective":"231-obj-26","tags":["ECG","diagnostic"],"difficulty":2,"question":"Quel type de spike, uni- ou bipolaire, est bien visible sur l'ECG de surface ?","answer":"Le spike unipolaire (bout de la sonde et boîtier)","accept":["unipolaire","uni-polaire","spike unipolaire","stimulation unipolaire"],"keywords":["unipolaire"],"explanation":"La stimulation unipolaire (entre le bout de la sonde et le boîtier) est bien visible en surface, la bipolaire est peu visible.","src":"p. 414","deep":"**Pourquoi** : en unipolaire, le courant passe entre le bout de la sonde et le boîtier, : spike bien visible ; en bipolaire, entre le bout et une autre électrode juste avant le bout : peu visible (p. 414).\n**Piège** : un spike peu visible (bipolaire) n'exclut pas un pacemaker.\n**À relier** : le spike dure 0,4 à 1 ms (p. 413)."},{"id":"231-qroc-867","type":"QROC","rank":"A","objective":"231-obj-27","tags":["indication","ECG"],"difficulty":1,"question":"Citez deux situations où un monitorage ECG continu est indiqué.","answer":"Urgence, réanimation, transfert, soins intensifs, syncope rythmique","accept":["urgence","réanimation","transfert","soins intensifs","syncope","peropératoire","salle de réveil","réadaptation","transfert médicalisé","soins intensifs cardiologiques","syncope à cause rythmique","réadaptation cardiaque"],"keywords":[],"explanation":"Le monitorage est indiqué en urgence, en réanimation et lors des transferts médicalisés, aux soins intensifs cardiologiques, en cas de syncope à cause rythmique suspectée, en péri-opératoire et pendant certains exercices de réadaptation.","src":"p. 414","deep":"**Pourquoi** : le monitorage ECG continu (cardioscope) sert là où un trouble du rythme peut survenir à tout moment : urgence, réanimation, transferts médicalisés, soins intensifs cardiologiques, syncope à cause rythmique suspectée, péri- et postopératoire, certains exercices de réadaptation (p. 414).\n**Piège** : pour la syncope, le monitorage n'est cité que si une cause rythmique est suspectée (p. 414) ; syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie (p. 383, rang B).\n**À relier** : pour des symptômes épisodiques en ambulatoire : Holter (p. 415)."},{"id":"231-qroc-868","type":"QROC","rank":"A","objective":"231-obj-27","tags":["indication","ECG"],"difficulty":1,"question":"Dans quels contextes d'aptitude un ECG de repos est-il indiqué ?","answer":"Aptitude professionnelle (conducteurs, pilotes) ou sportive","accept":["professionnelle","sportive","conducteurs","pilotes","aptitude professionnelle","aptitude sportive"],"keywords":[],"explanation":"L'ECG est indiqué pour l'aptitude professionnelle (conducteurs, pilotes) ou sportive (sports à risque, compétition, sportifs professionnels).","src":"p. 414","deep":"**Pourquoi** : l'ECG de repos est indiqué pour l'aptitude professionnelle (conducteurs, pilotes) ou sportive (sports à risque, compétition, sportifs professionnels) (p. 414).\n**Piège** : chez le sportif, une bradycardie sinusale par tonus vagal est physiologique (p. 376) ; chez le jeune homme, un ST jonctionnel V1-V4 aussi (p. 377).\n**À relier** : autres indications : bilans de santé, préopératoire > 65 ans, enquêtes familiales de cardiopathies héréditaires (p. 414)."},{"id":"231-qroc-869","type":"QROC","rank":"A","objective":"231-obj-27","tags":["indication","ECG"],"difficulty":1,"question":"Où et à quelle occasion un ECG est-il réalisé systématiquement ?","answer":"Dans les centres de santé, lors des bilans de santé","accept":["centres de santé","bilans de santé","bilan de santé","centre de santé"],"keywords":[],"explanation":"L'ECG fait partie systématiquement des bilans de santé réalisés dans les centres de santé.","src":"p. 414","deep":"**Pourquoi** : le Collège indique l'ECG de façon systématique dans les centres de santé, au moment des bilans de santé (p. 414).\n**Piège** : « systématique » ne vaut ici que pour ces bilans ; ailleurs, l'ECG est lié à un symptôme, un terrain ou un contexte (aptitude, préopératoire, HTA) (p. 414).\n**À relier** : obligatoire dans le bilan d'une HTA (p. 414)."},{"id":"231-qroc-870","type":"QROC","rank":"A","objective":"231-obj-27","tags":["indication","ECG"],"difficulty":1,"question":"À partir de quel âge un ECG est-il indiqué en bilan préopératoire (hors patient ou intervention à risque) ?","answer":"Plus de 65 ans","accept":["65 ans","65","plus de 65","> 65 ans"],"keywords":["65"],"explanation":"L'ECG préopératoire est indiqué chez les patients de plus de 65 ans, ainsi que chez les patients à risque et pour les interventions à risque.","src":"p. 414","deep":"**Pourquoi** : l'ECG préopératoire est indiqué chez les patients de plus de 65 ans, ainsi que chez les patients à risque et pour les interventions à risque (p. 414).\n**Piège** : le seuil est 65 ans ; avant cet âge, c'est le risque du patient ou de l'intervention qui décide.\n**À relier** : autres indications non symptomatiques : bilans de santé, aptitude, enquêtes familiales, HTA (p. 414)."},{"id":"231-qroc-871","type":"QROC","rank":"A","objective":"231-obj-27","tags":["indication","ECG"],"difficulty":2,"question":"Citez un exemple de pathologie non cardiaque dont le suivi justifie un ECG.","answer":"Le diabète, l'AVC","accept":["diabète","diabétique","avc","accident vasculaire cérébral","diabete","hta","hypertension artérielle"],"keywords":[],"explanation":"L'ECG fait partie de la surveillance des pathologies non cardiaques pouvant se compliquer sur le plan cardiovasculaire, par exemple le diabète ou l'AVC.","src":"p. 414","deep":"**Pourquoi** : certaines pathologies non cardiaques exposent à des complications cardiovasculaires : l'ECG fait partie de leur bilan initial ou de leur surveillance, par exemple chez le diabétique ou après un AVC (p. 414).\n**Piège** : l'HTA a sa propre règle : l'ECG y est obligatoire dans le bilan (p. 414).\n**À relier** : l'ECG sert aussi au suivi des pathologies cardiaques elles-mêmes (p. 414)."},{"id":"231-qroc-872","type":"QROC","rank":"A","objective":"231-obj-27","tags":["indication","ECG"],"difficulty":1,"question":"Citez trois symptômes qui justifient la réalisation d'un ECG.","answer":"Palpitations, douleur thoracique, dyspnée, malaise, syncope","accept":["palpitations","douleur thoracique","dyspnée","dyspnee","malaise","perte de connaissance","syncope"],"keywords":[],"explanation":"Un ECG est indiqué devant des palpitations, une douleur thoracique, une dyspnée aiguë ou chronique, un malaise, une perte de connaissance ou une syncope.","src":"p. 414","deep":"**Pourquoi** : tout symptôme pouvant traduire une cause rythmique, ischémique ou hémodynamique justifie un ECG : palpitations, douleur thoracique, dyspnée aiguë ou chronique, malaise, perte de connaissance, syncope (p. 414).\n**Piège** : devant une douleur thoracique, penser à l'ECG 18 dérivations (miroir d'un ST+ postérieur) (p. 411).\n**À relier** : en urgence : douleur thoracique, palpitations, syncope, défaillance d'organe, troubles du K/Ca (p. 368)."},{"id":"231-qroc-873","type":"QROC","rank":"B","objective":"231-obj-28","tags":["examens","ECG"],"difficulty":1,"question":"Combien de dérivations simultanées enregistre un Holter ECG ?","answer":"2 à 12","accept":["2 à 12","2-12","2 et 12","entre 2 et 12","2-12 dérivations"],"keywords":["12"],"explanation":"Le Holter est un ECG de longue durée enregistrant 2 à 12 dérivations simultanées pendant 24 à 96 heures, avec analyse en différé.","src":"p. 415","deep":"**Pourquoi** : le Holter est un ECG de longue durée : 2 à 12 dérivations simultanées, 24 à 96 heures, enregistrement numérique analysé en différé (centre de lecture) (p. 415).\n**Piège** : l'analyse est différée : ce n'est pas un monitorage en temps réel (p. 415).\n**À relier** : symptômes rares : ECG ambulatoire jusqu'à 21 jours ou enregistreur d'événements ; implantable jusqu'à 3 ans (p. 415)."},{"id":"231-qroc-874","type":"QROC","rank":"B","objective":"231-obj-28","tags":["examens","ECG"],"difficulty":2,"question":"Quel dispositif permet de n'enregistrer l'ECG qu'au moment des symptômes, pour des symptômes rares ?","answer":"Un enregistreur d'événements (outil dédié ou montre connectée ECG)","accept":["enregistreur d'événements","enregistreur d'evenements","montre connectée","enregistreur d'évènement","montre connectée ecg","holter événementiel"],"keywords":["enregistreur"],"explanation":"En cas de symptômes rares, on utilise l'ECG ambulatoire de très longue durée (jusqu'à 21 jours) ou un enregistreur d'événements, où l'ECG est réalisé en cas de symptôme.","src":"p. 415","deep":"**Pourquoi** : quand les symptômes sont rares, un Holter de 24-96 h a peu de chances de les capter : l'enregistreur d'événements fait l'ECG au moment du symptôme (outil dédié ou montre connectée ECG) (p. 415).\n**Piège** : un Holter normal n'élimine pas un trouble rythmique rare : il faut une probabilité que les symptômes se répètent pendant l'enregistrement (p. 415).\n**À relier** : autre option : ECG ambulatoire de très longue durée, jusqu'à 21 jours (p. 415)."},{"id":"231-qroc-875","type":"QROC","rank":"B","objective":"231-obj-28","tags":["examens","ECG"],"difficulty":2,"question":"Pour quelles indications utilise-t-on un moniteur ECG implantable (holter sous-cutané) ?","answer":"Syncopes inexpliquées et FA silencieuse","accept":["syncope","fa silencieuse","fibrillation atriale silencieuse","syncope inexpliquée","syncopes inexpliquées"],"keywords":[],"explanation":"Le moniteur implantable, utilisable jusqu'à 3 ans, sert au diagnostic étiologique des syncopes inexpliquées ou de la FA silencieuse.","src":"p. 415","deep":"**Pourquoi** : le moniteur ECG implantable (holter sous-cutané) suit le rythme jusqu'à 3 ans : il sert au diagnostic étiologique des syncopes inexpliquées ou de la FA silencieuse (p. 415).\n**Piège** : pour des symptômes susceptibles de se répéter en 24-96 h, le Holter classique suffit ; l'implantable vise les événements très rares (p. 415).\n**À relier** : symptômes rares : ECG ambulatoire jusqu'à 21 jours, enregistreurs d'événements (p. 415)."},{"id":"231-qroc-876","type":"QROC","rank":"B","objective":"231-obj-28","tags":["examens","ECG"],"difficulty":2,"question":"Quelle anomalie, détectée par un Holter de 24 h, évalue le risque rythmique après un infarctus ou dans une cardiomyopathie ?","answer":"Des salves asymptomatiques de tachycardie ventriculaire","accept":["salves de tv","salves de tachycardie ventriculaire","salves","tachycardie ventriculaire","salves de tv asymptomatiques","tv non soutenue","tvns"],"keywords":[],"explanation":"Le Holter de 24 h évalue le risque rythmique en détectant des salves de TV asymptomatiques après infarctus ou dans les cardiomyopathies.","src":"p. 415","deep":"**Pourquoi** : après un infarctus ou dans une cardiomyopathie, la détection de salves de TV asymptomatiques au Holter de 24 h permet d'évaluer le risque rythmique (p. 415).\n**Piège** : ces salves sont asymptomatiques : leur absence de symptôme ne les rend pas anodines.\n**À relier** : TV non soutenue = 3 battements à 30 s (p. 399) ; la réentrée autour d'une fibrose est le mécanisme le plus fréquent de TV (p. 399)."},{"id":"231-qroc-877","type":"QROC","rank":"B","objective":"231-obj-28","tags":["examens","traitement"],"difficulty":2,"question":"Quel type de traitement le Holter de 24 h permet-il d'évaluer ?","answer":"L'efficacité des médicaments bradycardisants","accept":["bradycardisant","bradycardisants","médicaments bradycardisants","bêtabloquants"],"keywords":["bradycard"],"explanation":"Le Holter de 24 h permet notamment d'évaluer l'efficacité thérapeutique des médicaments bradycardisants.","src":"p. 415","deep":"**Pourquoi** : le Holter de 24 h permet d'évaluer l'efficacité thérapeutique des médicaments bradycardisants (p. 415).\n**Piège** : un ECG ponctuel au repos ne reflète pas la fréquence sur 24 h.\n**À relier** : autres usages du Holter 24 h : surveillance/réglage des pacemakers, risque rythmique post-infarctus ou cardiomyopathie (p. 415)."},{"id":"231-qroc-878","type":"QROC","rank":"B","objective":"231-obj-28","tags":["examens","ECG"],"difficulty":2,"question":"Quel dispositif implanté peut être surveillé ou réglé grâce à un Holter de 24 h ?","answer":"Le pacemaker","accept":["pacemaker","stimulateur","stimulateur cardiaque"],"keywords":[],"explanation":"Le Holter de 24 h sert aussi à la surveillance et au réglage des pacemakers.","src":"p. 415","deep":"**Pourquoi** : le Holter de 24 h sert à la surveillance ou au réglage des pacemakers (p. 415).\n**Piège** : le spike bipolaire est peu visible : savoir qu'un patient est stimulé aide à lire le tracé (p. 414).\n**À relier** : autres usages : bradycardisants, salves de TV post-infarctus ou en cardiomyopathie (p. 415)."},{"id":"231-qroc-879","type":"QROC","rank":"A","objective":"231-obj-06","tags":["ECG","diagnostic"],"difficulty":1,"question":"Sur quel élément de l'ECG fait-on le diagnostic d'hémibloc ?","answer":"L'axe du QRS","accept":["axe","l'axe du qrs","axe du qrs","l'axe","déviation axiale"],"keywords":["axe"],"explanation":"Le diagnostic de bloc de branche repose sur la durée du QRS (V1 positif = droit, négatif = gauche), celui d'hémibloc sur l'axe du QRS.","src":"p. 415","deep":"**Pourquoi** : l'hémibloc élargit très peu le QRS (> 110 ms) mais dévie l'axe : c'est donc l'axe qui fait le diagnostic ; le bloc de branche se juge sur la durée du QRS et l'aspect de V1 (points clés, p. 415).\n**Piège** : HBAG = axe au-delà de -30° (D2 négatif) ; HBPG = axe > +90° (D1 négatif), après exclusion d'une inversion d'électrodes (p. 382-383).\n**À relier** : les blocs de branche ne donnent pas de bradycardie (p. 415)."},{"id":"231-qroc-880","type":"QROC","rank":"A","objective":"231-obj-18","tags":["ECG","pièges"],"difficulty":1,"question":"Quel diagnostic grave ne doit pas être confondu avec un bloc de branche devant un QRS large ?","answer":"Une tachycardie ventriculaire","accept":["tachycardie ventriculaire","tv","tv monomorphe"],"keywords":[],"explanation":"Le bloc de branche est sans conséquence immédiate, alors qu'une TV est mortelle si elle n'est pas prise en charge : il ne faut pas les confondre.","src":"p. 415","deep":"**Pourquoi** : devant un QRS large, le bloc de branche est sans conséquence immédiate, la TV est mortelle si elle n'est pas prise en charge : c'est la confusion à ne pas faire (points clés, p. 415).\n**Piège** : toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire (p. 398) ; on décrit le rythme atrial avant le bloc (p. 378).\n**À relier** : certitude de TV : dissociation ventriculoatriale, capture, fusion ; en faveur : cardiopathie, concordance, axe extrême (p. 400)."},{"id":"231-qroc-881","type":"QROC","rank":"B","objective":"231-obj-01","tags":["ECG","physiopathologie"],"difficulty":3,"question":"Pourquoi les ondes T sont-elles de même polarité que les QRS sur un ECG normal, alors qu'un front de repolarisation devrait inscrire l'inverse ?","answer":"Dépolarisation endocarde vers épicarde, repolarisation en sens inverse","accept":["épicarde vers l'endocarde","sens inverse","de l'épicarde vers l'endocarde","endocarde vers l'épicarde","repolarisation de l'épicarde vers l'endocarde","de l'épicarde à l'endocarde"],"keywords":["epicarde","endocarde"],"explanation":"La dépolarisation ventriculaire progresse de l'endocarde vers l'épicarde et la repolarisation en sens inverse : l'onde T est donc concordante avec le QRS.","src":"p. 371","deep":"**Pourquoi** : un front de repolarisation qui va vers l'électrode inscrit une onde négative ; mais la repolarisation va de l'épicarde vers l'endocarde, en sens inverse de la dépolarisation : les deux inversions s'annulent et T est concordante avec le QRS (p. 371).\n**Piège** : en cas de QRS large, ce schéma est rompu : T de polarité opposée au QRS (discordance appropriée) (p. 381).\n**À relier** : un courant qui va vers l'électrode s'inscrit positif, qui s'en éloigne négatif (fig. 15.3, p. 371)."},{"id":"231-qroc-882","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","pièges"],"difficulty":2,"question":"Quelle erreur de positionnement de V1 et V2 peut simuler une pseudonécrose ou une atypie de repolarisation antérieure ?","answer":"Trop hautes et trop écartées (confondues avec les foyers auscultatoires)","accept":["trop hautes","trop haut","trop écartées","foyers auscultatoires","aortique et pulmonaire","trop haut placées"],"keywords":[],"explanation":"Les électrodes précordiales doivent être isodistantes ; V1 et V2 sont souvent placées trop haut et trop écartées car confondues avec les foyers auscultatoires aortique et pulmonaire.","src":"p. 373","deep":"**Pourquoi** : V1 et V2 sont souvent placées trop haut et trop écartées, confondues avec les foyers auscultatoires aortique et pulmonaire : cela peut créer une pseudonécrose ou une atypie de repolarisation antérieure (p. 373).\n**Piège** : avant de conclure à une séquelle antérieure, vérifie le placement (précordiales isodistantes) et la transition R/S de V1 à V6 (p. 373, 378).\n**À relier** : une HVG importante peut aussi donner une pseudonécrose QS en V1-V2 (p. 406)."},{"id":"231-qroc-883","type":"QROC","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"question":"Qu'appelle-t-on une onde isodiphasique ?","answer":"Une onde dont les composantes positive et négative sont d'égale importance","accept":["égale importance","autant de positif que de négatif","sinusoïde","positive puis négative","positif et négatif égaux","positive puis négative égale"],"keywords":[],"explanation":"Une onde (P, QRS ou T) est isodiphasique quand ses composantes positive et négative sont de même importance, d'aspect sinusoïdal ; c'est le cas d'un courant perpendiculaire à l'électrode.","src":"p. 375, 371","deep":"**Pourquoi** : une onde est isodiphasique quand ses composantes positive et négative sont d'égale importance (aspect de sinusoïde) ; c'est ce que donne un courant perpendiculaire à l'électrode (p. 371, 375).\n**Piège** : isodiphasique ne veut pas dire « nulle » : le vecteur est perpendiculaire à la dérivation, ce qui aide à situer l'axe.\n**À relier** : courant vers l'électrode = positif ; qui s'éloigne = négatif (fig. 15.3, p. 371)."},{"id":"231-qroc-884","type":"QROC","rank":"A","objective":"231-obj-12","tags":["ECG","physiopathologie"],"difficulty":2,"question":"Le Collège schématise les mécanismes des arythmies en trois types. Citez-en deux.","answer":"Réentrée, hyperautomatisme (ou mécanismes complexes)","accept":["réentrée","reentree","hyperautomatisme","mécanismes complexes","automatisme"],"keywords":[],"explanation":"La figure 15.28 présente de façon simplifiée la réentrée, l'hyperautomatisme et des mécanismes complexes, qui se déclinent à chaque étage cardiaque (atrial, jonctionnel, ventriculaire).","src":"p. 389","deep":"**Pourquoi** : la figure 15.28 schématise les arythmies en réentrée, hyperautomatisme et mécanismes complexes ; en les déclinant aux étages atrial, jonctionnel et ventriculaire, on retrouve tous les troubles du rythme (p. 389).\n**Piège** : ces mécanismes sont donnés à titre indicatif et simplifiés (p. 389) : ne pas en faire une classification rigide.\n**À relier** : exemples : réentrée = flutter, tachycardie jonctionnelle, TV sur cicatrice ; automatisme anormal = TV sur cœur sain (p. 393, 395, 398)."},{"id":"231-qroc-885","type":"QROC","rank":"A","objective":"231-obj-13","tags":["ECG","définition"],"difficulty":1,"question":"Qu'est-ce qui oppose l'activation atriale de la FA à celle du flutter ?","answer":"FA : activation anarchique ; flutter : activation organisée en circuit","accept":["anarchique","fibrillatoire","organisée","en circuit","boucle","activation organisée en boucle"],"keywords":[],"explanation":"Dans le flutter, l'activation atriale est organisée en circuit (boucle qui se répète à l'identique), alors qu'elle est anarchique (fibrillatoire) dans la FA.","src":"p. 391, 393","deep":"**Pourquoi** : le flutter est une boucle d'activation organisée en circuit, qui se répète à l'identique (réentrée) ; la FA est une activation fibrillatoire, anarchique (p. 391, 393).\n**Piège** : conséquence ECG : flutter = ondes F monomorphes sans retour à la ligne isoélectrique ; FA = mailles ou trémulation, QRS irrégulièrement irréguliers (p. 392-393).\n**À relier** : facteurs prédisposants communs : un même patient peut présenter les deux (p. 393)."},{"id":"231-qroc-886","type":"QROC","rank":"A","objective":"231-obj-17","tags":["ECG","définition"],"difficulty":1,"question":"Citez deux formes répétitives d'extrasystoles.","answer":"Doublets, triplets, salves","accept":["doublet","triplet","salve","doublets","triplets","salves","extrasystoles répétitives"],"keywords":[],"explanation":"Les extrasystoles peuvent être répétitives (doublets, triplets ou salves) ou rythmées (bigéminisme, trigéminisme).","src":"p. 398","deep":"**Pourquoi** : les extrasystoles peuvent se répéter : doublets (2), triplets (3) ou salves ; ou être rythmées : bigéminisme (1 battement sur 2), trigéminisme (1 sur 3) (p. 398).\n**Piège** : ne confonds pas « répétitives » (doublets, triplets, salves) et « rythmées » (bigéminisme, trigéminisme).\n**À relier** : une tachycardie > 100 bpm à QRS > 120 ms sur au moins 3 battements consécutifs fait suspecter une TV (non soutenue si < 30 s) (p. 399)."},{"id":"231-qroc-887","type":"QROC","rank":"B","objective":"231-obj-03","tags":["ECG","diagnostic"],"difficulty":2,"question":"En cas d'hypertrophie atriale gauche, quelle composante de l'onde P apparaît en V1, et de quelle durée minimale ?","answer":"Une composante négative > 40 ms","accept":["composante négative","négative > 40","40 ms","négatif","composante négative en v1 > 40 ms","partie négative","> 40 ms"],"keywords":["40"],"explanation":"L'HAG est évoquée devant une onde P de durée > 110 ms (en pratique 120 ms) avec une composante négative > 40 ms en V1.","src":"p. 406","deep":"**Pourquoi** : l'HAG allonge la dépolarisation atriale : P > 110 ms (en pratique 120 ms) avec une composante négative > 40 ms en V1 (p. 406).\n**Piège** : HAG = critère de durée et composante négative en V1 ; HAD = critère d'amplitude (> 2,5 mm en D2 ou > 2 mm en V1/V2) (p. 406).\n**À relier** : P normale < 120 ms et < 2,5 mm en D2 (tableau 15.2, p. 375)."},{"id":"231-qroc-888","type":"QROC","rank":"A","objective":"231-obj-21","tags":["ECG","biologie"],"difficulty":1,"question":"Quelles anomalies de la conduction (PR, QRS) l'hyperkaliémie provoque-t-elle ?","answer":"Allongement du PR et élargissement du QRS","accept":["allongement du pr","pr allongé","élargissement du qrs","qrs élargi","qrs large","pr long et qrs larges","allongement de pr et élargissement de qrs","pr allongé et qrs élargi"],"keywords":["pr","qrs"],"explanation":"L'hyperkaliémie associe T ample pointue symétrique, allongement du PR, élargissement du QRS et parfois BAV, TV ou dysfonction sinusale.","src":"p. 408","deep":"**Pourquoi** : l'hyperkaliémie ralentit la conduction : allongement du PR et élargissement du QRS, à côté de la T ample, pointue, symétrique ; elle peut aller jusqu'au BAV, à la TV ou à la dysfonction sinusale (p. 408).\n**Piège** : les T peuvent être géantes avant que les QRS ne s'élargissent (fig. 15.55, p. 409) ; l'hypokaliémie laisse le QRS normal (p. 408).\n**À relier** : dyskaliémie = indication d'ECG en urgence (p. 368)."},{"id":"231-qroc-889","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG","définition"],"difficulty":2,"question":"Dans quel(s) sens une voie accessoire typique peut-elle conduire l'influx ?","answer":"Dans les deux sens (oreillette vers ventricule et inversement)","accept":["deux sens","les deux sens","bidirectionnelle","antérograde et rétrograde","dans les deux sens"],"keywords":["deux"],"explanation":"Une voie accessoire typique peut conduire dans les deux sens ; le syndrome de WPW désigne la voie accessoire antérograde qui occasionne des tachycardies jonctionnelles.","src":"p. 410","deep":"**Pourquoi** : une voie accessoire typique peut conduire dans les deux sens, de l'oreillette au ventricule et inversement (p. 410).\n**Piège** : c'est ce qui permet la tachycardie par rythme réciproque (réentrée utilisant la voie accessoire) (p. 396) ; le WPW désigne la voie accessoire antérograde responsable de palpitations (p. 411).\n**À relier** : préexcitation = conduction antérograde rapide par la voie : PR court, onde delta (p. 410)."},{"id":"231-qroc-890","type":"QROC","rank":"B","objective":"231-obj-25","tags":["ECG","physiopathologie"],"difficulty":1,"question":"Quel est, normalement, le seul passage physiologique entre l'oreillette et le ventricule ?","answer":"Le nœud atrioventriculaire (NAV)","accept":["nœud atrioventriculaire","noeud atrioventriculaire","nav","nœud auriculoventriculaire","noeud auriculoventriculaire","nœud av"],"keywords":[],"explanation":"Le reste du plan de l'anneau isole totalement l'oreillette du ventricule ; une voie accessoire crée un second passage anormal en compétition avec le NAV.","src":"p. 410","deep":"**Pourquoi** : physiologiquement, le NAV est le seul passage entre oreillettes et ventricules : le reste de l'anneau isole totalement l'oreillette du ventricule (p. 410).\n**Piège** : une voie accessoire (Kent) crée un second passage, sans conduction décrémentielle, en compétition avec le NAV (p. 410-411).\n**À relier** : c'est grâce à ce passage unique et à son filtre que la FA ne donne pas de FV (p. 390)."},{"id":"231-qroc-891","type":"QROC","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"question":"Par quel aspect l'onde R peut-elle remplacer une onde Q de nécrose, surtout en V2-V3-V4 ?","answer":"Un écrêtement (rabotage) de l'onde R","accept":["écrêtement","ecretement","rabotage","écrêtement de l'onde r","écrêtement de r","r rabotée","perte de r"],"keywords":[],"explanation":"Les ondes Q de nécrose peuvent être remplacées par un écrêtement ou rabotage de l'onde R, surtout décrit en V2-V3-V4.","src":"p. 412","deep":"**Pourquoi** : l'onde Q de nécrose peut être remplacée par un écrêtement ou rabotage de l'onde R, surtout décrit en V2-V3-V4 (p. 412).\n**Piège** : une perte de R en antérieur peut aussi venir d'électrodes V1-V2 mal placées (pseudonécrose, p. 373) : vérifier la transition R/S (p. 378).\n**À relier** : Q de nécrose : au moins 1/3 (ou 1/4) du QRS et > 30-40 ms, en principe vers la 6e heure (p. 412)."},{"id":"231-qru-701","type":"QRU","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Une femme de 82 ans consulte pour un malaise. L'ECG montre des ondes P régulières à 80/min, des QRS fins réguliers à 38/min et aucune relation fixe entre les ondes P et les QRS. Quel est le diagnostic le plus probable ?","options":[{"t":"Dysfonction sinusale avec échappement jonctionnel","ok":false,"why":"Dans la dysfonction sinusale, les P sont trop lentes ou inexistantes (p. 389) ; ici elles sont régulières à 80/min, donc le nœud sinusal fonctionne et c'est la conduction qui est en cause."},{"t":"BAV du 3e degré avec échappement jonctionnel (bloc nodal)","ok":true,"why":"Il existe une dissociation atrioventriculaire complète : P régulières à fréquence normale, QRS lents et réguliers. Un échappement à QRS fins traduit un bloc nodal (suprahissien)."},{"t":"BAV du 1er degré","ok":false,"why":"Le BAV1 est un PR fixe > 200 ms SANS onde P bloquée : chaque P reste suivie d'un QRS (p. 386) ; ici les P ne sont pas conduites et la FC est à 38/min."},{"t":"Bloc sinoatrial du 2e degré","ok":false,"why":"Il se traduit par des pauses avec absence complète du complexe P-QRS-T, égales au double de l'intervalle PP, et non par des P dissociées des QRS."},{"t":"BAV du 2e degré de type Mobitz 1","ok":false,"why":"Le Mobitz 1 associe un allongement progressif du PR puis une onde P bloquée : il existe un lien P-QRS, ce qui n'est pas le cas ici."}],"explanation":"Devant une bradycardie, on regarde les ondes P : régulières à fréquence normale mais plus nombreuses que les QRS, le problème est le passage au ventricule (BAV). Ici la dissociation complète avec échappement à QRS fins définit un BAV3 nodal.","src":"p. 385, 387, 389","deep":"**Pourquoi** : devant une bradycardie, on regarde d'abord les P : régulières à fréquence normale mais plus nombreuses que les QRS, sans lien fixe = le nœud sinusal marche, c'est le passage au ventricule qui est bloqué : BAV3 (p. 387, 389).\n**Piège** : l'échappement à QRS fins, régulier et lent, situe le bloc dans le nœud (suprahissien) ; des QRS larges l'auraient situé sous le His (p. 387).\n**À relier** : le Collège range Mobitz 2 et BAV3 parmi les BAV infrahissiens, indication de pacemaker même sans symptôme (p. 412, rang B)."},{"id":"231-qru-702","type":"QRU","rank":"B","objective":"231-obj-26","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Un homme de 79 ans est porteur d'un pacemaker pour un BAV complet. Son ECG montre une impulsion verticale très brève devant chaque QRS ; les QRS sont larges et d'aspect BBG. Quelle interprétation est exacte ?","options":[{"t":"Une préexcitation ventriculaire : l'impulsion est l'onde delta","ok":false,"why":"L'onde delta est un empâtement du pied du QRS avec PR court, et non une impulsion très brève."},{"t":"Des extrasystoles ventriculaires en bigéminisme","ok":false,"why":"Une extrasystole est un QRS large prématuré ; ici chaque QRS est précédé d'un spike régulier."},{"t":"Une stimulation ventriculaire droite : spike suivi d'un QRS large d'aspect BBG","ok":true,"why":"Le spike est pathognomonique d'une stimulation. En cas de BAV, le pacemaker stimule le ventricule : la propagation de proche en proche, hors His-Purkinje, donne un QRS large d'aspect BBG."},{"t":"Une fibrillation ventriculaire","ok":false,"why":"La FV est une tachycardie irrégulière à QRS larges polymorphes, avec arrêt cardiaque, et non un tracé régulier stimulé."},{"t":"Un BBG spontané : l'impulsion représente l'onde P","ok":false,"why":"L'impulsion de 0,4 à 1 ms n'est pas une onde P : rien de physiologique n'est aussi bref sur un ECG."}],"explanation":"Le spike de stimulation (0,4 à 1 ms) signe la présence d'une stimulation cardiaque. Dans le BAV, le pacemaker écoute l'oreillette et stimule le ventricule après un délai AV programmé.","src":"p. 413-414","deep":"**Pourquoi** : le spike (0,4 à 1 ms) n'a aucun équivalent physiologique : il signe une stimulation (p. 413) ; en cas de BAV, le pacemaker écoute l'oreillette et stimule le VD, d'où un QRS large d'aspect BBG par propagation de proche en proche (p. 414).\n**Piège** : QRS large d'aspect BBG après un spike = stimulation ventriculaire, pas un BBG spontané ; en dysfonction sinusale, le spike est suivi d'une onde P (p. 414).\n**À relier** : spike unipolaire bien visible, bipolaire peu visible (p. 414) ; un pacemaker peut masquer les anomalies d'un SCA (p. 412)."},{"id":"231-qru-703","type":"QRU","rank":"A","objective":"231-obj-21","tags":["diagnostic","biologie"],"difficulty":1,"stem":"Un patient dialysé de 60 ans est asthénique. L'ECG montre des ondes T amples, pointues et symétriques, un allongement du PR et un élargissement du QRS. Quelle est l'anomalie la plus probable ?","options":[{"t":"Une hypokaliémie","ok":false,"why":"L'hypokaliémie donne une onde T plate ou négative, un ST sous-décalé, un QRS normal, un QT allongé et une onde U."},{"t":"Une hyperkaliémie","ok":true,"why":"T ample, pointue et symétrique, allongement du PR et élargissement du QRS sont les anomalies de l'hyperkaliémie ; elle peut se compliquer de BAV, TV ou dysfonction sinusale."},{"t":"Une embolie pulmonaire","ok":false,"why":"Elle peut donner un aspect S1Q3T3 (S en D1, Q et T négative en D3), pas des T amples et symétriques."},{"t":"Une péricardite aiguë","ok":false,"why":"La péricardite donne un sus-ST diffus concave sans miroir et un sous-décalage de PQ (p. 409), sans allongement du PR ni élargissement du QRS."},{"t":"Une hypertrophie ventriculaire gauche","ok":false,"why":"L'HVG donne un Sokolow ≥ 35 mm et, dans sa forme sévère, des T NÉGATIVES latérales avec ST sous-décalé (p. 406), pas des T amples pointues avec PR allongé."}],"explanation":"Hypo- et hyperkaliémie sont à opposer : T plate/QT long/onde U (hypo) contre T géantes, PR long et QRS larges (hyper).","src":"p. 408","deep":"**Pourquoi** : T ample, pointue et symétrique, PR allongé et QRS élargi sont précisément les signes ECG de l'hyperkaliémie listés p. 408 : l'ECG oriente ici avant le ionogramme.\n**Piège** : les T peuvent être géantes avant l'élargissement du QRS (fig. 15.55, p. 409) ; l'hypokaliémie donne l'inverse (T plate, onde U, QT long, QRS normal) (p. 408).\n**À relier** : complications de l'hyperkaliémie : BAV, TV, dysfonction sinusale ; dyskaliémie = indication d'ECG en urgence (p. 368, 408)."},{"id":"231-qru-704","type":"QRU","rank":"B","objective":"231-obj-25","tags":["diagnostic","pièges"],"difficulty":3,"stem":"Un homme de 31 ans, connu pour une préexcitation ventriculaire, consulte pour des palpitations. L'ECG montre une tachycardie irrégulière, extrêmement rapide, à QRS larges de largeur variable, « en accordéon ». Quelle proposition est exacte ?","options":[{"t":"Il s'agit d'une tachycardie ventriculaire monomorphe","ok":false,"why":"Une TV monomorphe a des QRS de morphologie identique et régulière ; les QRS ici varient de largeur et sont irréguliers."},{"t":"Il s'agit d'une tachycardie sinusale d'effort","ok":false,"why":"La tachycardie sinusale a des ondes P sinusales et des QRS réguliers et fins, sans aspect « en accordéon »."},{"t":"Il s'agit d'un flutter atrial conduit en 2/1","ok":false,"why":"Le flutter 2/1 donne une cadence régulière autour de 150/min, sans QRS de largeur variable."},{"t":"Il s'agit d'une tachycardie par réentrée intranodale, à traiter d'emblée par des manœuvres vagales","ok":false,"why":"La réentrée intranodale est une tachycardie TRÈS RÉGULIÈRE à QRS fins (p. 395) ; ici elle est irrégulière à QRS larges variables, et bloquer le NAV serait dangereux en cas de FA préexcitée (p. 410)."},{"t":"Il s'agit d'une FA rapide conduite par la voie accessoire (« super-Wolff ») : l'adénosine est contre-indiquée","ok":true,"why":"La voie accessoire ne filtre pas l'influx comme le NAV : FA rapide, QRS larges de taille variable, risque de FV. Il ne faut pas bloquer le NAV en cas de FA ; c'est une contre-indication à l'adénosine, comme l'asthme."}],"explanation":"FA + voie accessoire perméable = super-Wolff : tachycardie irrégulière à QRS larges de largeur variable, extrêmement rapide, pouvant dégénérer en FV ; on ne bloque pas le NAV.","src":"p. 411","deep":"**Pourquoi** : chez un préexcité, une FA rapide passe par la voie accessoire, qui n'a pas la conduction décrémentielle du NAV : tachycardie irrégulière, extrêmement rapide, QRS de largeur variable « en accordéon », risque de FV (p. 411).\n**Piège** : ne bloque pas le NAV (adénosine, massage) en cas de FA sur voie accessoire : l'influx passerait uniquement par la voie (p. 410-411) ; p. 411 en fait la seule autre CI à l'adénosine avec l'asthme (p. 390 cite aussi l'hypotension).\n**À relier** : le WPW proprement dit = palpitations par tachycardie jonctionnelle (rythme réciproque) via la voie accessoire (p. 396, 411)."},{"id":"231-qru-705","type":"QRU","rank":"B","objective":"231-obj-28","tags":["examens","ECG"],"difficulty":2,"stem":"Une femme de 34 ans décrit des palpitations brèves survenant environ une fois par mois. L'ECG de repos est normal. Quelle exploration est la plus adaptée ?","options":[{"t":"Un Holter ECG de 24 heures","ok":false,"why":"Le Holter n'est pertinent que s'il est probable que les symptômes se répètent pendant la durée de l'enregistrement, ce qui n'est pas le cas ici."},{"t":"Un monitorage ECG continu au cardioscope","ok":false,"why":"Le monitorage continu est indiqué en urgence, réanimation et transferts médicalisés, aux soins intensifs, en cas de syncope à cause rythmique suspectée, en péri-opératoire et pendant certains exercices de réadaptation, pas pour des palpitations mensuelles."},{"t":"Un moniteur ECG implantable d'emblée","ok":false,"why":"Le Collège réserve le holter sous-cutané (suivi jusqu'à 3 ans) au diagnostic étiologique des syncopes inexpliquées ou de la FA silencieuse (p. 415), pas à des palpitations mensuelles chez qui l'ECG ambulatoire de longue durée suffit."},{"t":"Un ECG avec 18 dérivations","ok":false,"why":"Il est recommandé devant une douleur thoracique, pas pour documenter des palpitations intermittentes."},{"t":"Un ECG ambulatoire de très longue durée (jusqu'à 21 jours) ou un enregistreur d'événements","ok":true,"why":"Pour des symptômes rares, on utilise l'ECG ambulatoire de très longue durée ou des enregistreurs d'événements, y compris des montres connectées ECG."}],"explanation":"Choisir la durée d'enregistrement en fonction de la fréquence des symptômes : 24-96 h si fréquents, jusqu'à 21 jours ou événementiel si rares, implantable pour syncopes inexpliquées ou FA silencieuse.","src":"p. 415","deep":"**Pourquoi** : le choix de l'enregistrement dépend de la fréquence des symptômes : un Holter de 24-96 h n'est utile que si les symptômes ont des chances de se répéter pendant l'enregistrement ; pour des symptômes rares, ECG ambulatoire jusqu'à 21 jours ou enregistreur d'événements (p. 415).\n**Piège** : un Holter normal pour un symptôme mensuel ne rassure pas : il a simplement peu de chances de capter l'épisode (p. 415).\n**À relier** : moniteur implantable (jusqu'à 3 ans) : syncopes inexpliquées ou FA silencieuse (p. 415)."},{"id":"231-qru-706","type":"QRU","rank":"B","objective":"231-obj-06","tags":["diagnostic","urgence"],"difficulty":2,"stem":"Un homme de 74 ans a présenté une syncope brutale. L'ECG montre un rythme sinusal, un QRS à 140 ms avec un aspect RsR' en V1, et un axe à -50° avec D2, D3 et aVF négatifs. Quelle attitude est la plus adaptée ?","options":[{"t":"Rassurer le patient : il s'agit d'un BBD isolé sans conséquence","ok":false,"why":"L'association BBD + déviation axiale gauche (HBAG) est un bloc bifasciculaire, qui fait craindre un BAV complet infrahissien."},{"t":"Injecter de l'adénosine en flash IV","ok":false,"why":"L'adénosine sert au diagnostic ou à la réduction de tachycardies, pas à un trouble de conduction."},{"t":"Réaliser une cardioversion électrique externe","ok":false,"why":"Elle est réservée aux tachycardies mal tolérées ; il n'y a pas de tachycardie ici."},{"t":"Programmer un Holter ambulatoire sans hospitalisation","ok":false,"why":"La syncope associée à un bloc bifasciculaire impose la surveillance en télémétrie à l'hôpital."},{"t":"Hospitaliser en cardiologie avec télémétrie","ok":true,"why":"Syncope + bloc bifasciculaire (HBAG + BBD) = hospitalisation en cardiologie avec télémétrie, en raison du risque de BAV complet infrahissien."}],"explanation":"QRS > 120 ms avec RsR' en V1 = BBD ; axe < -30° avec négativité de D2 = HBAG ; l'association réalise un bloc bifasciculaire.","src":"p. 380, 382-383","deep":"**Pourquoi** : QRS > 120 ms avec RsR' en V1 = BBD complet ; axe au-delà de -30° avec D2 négatif = HBAG ; les deux ensemble = bloc bifasciculaire : la dernière branche peut lâcher par intermittence (BAV complet infrahissien, syncope, mort subite) (p. 378, 382-383).\n**Piège** : le rythme sinusal et l'absence de symptôme à l'arrivée ne rassurent pas : syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie (p. 383).\n**À relier** : si un BAV infrahissien (Mobitz 2, BAV3) apparaît, le pacemaker est indiqué même sans symptôme (p. 412)."},{"id":"231-qru-707","type":"QRU","rank":"A","objective":"231-obj-12","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Un homme de 40 ans fébrile à 39,5 °C est monitoré. Sa fréquence passe progressivement de 95 à 145/min sur plusieurs minutes ; des ondes P positives en D1, D2, D3 et aVF précèdent chaque QRS. Quel est le diagnostic le plus probable ?","options":[{"t":"Une tachycardie sinusale","ok":true,"why":"Ondes P sinusales positives en D1, D2, D3 et aVF, fréquence variant progressivement et contexte évident (fièvre) caractérisent la tachycardie sinusale."},{"t":"Une tachycardie jonctionnelle par réentrée intranodale","ok":false,"why":"Elle est très régulière, avec une fréquence qui fait des « marches d'escalier », et l'activité atriale est souvent invisible."},{"t":"Une tachycardie ventriculaire","ok":false,"why":"Elle donne des QRS larges (> 120 ms) ; ici chaque QRS est précédé d'une onde P sinusale."},{"t":"Une fibrillation atriale","ok":false,"why":"La FA est irrégulièrement irrégulière, sans onde P identifiable."},{"t":"Un flutter atrial conduit en 2/1","ok":false,"why":"Le flutter montre des ondes F en dents de scie sans retour à la ligne isoélectrique, et non des ondes P sinusales."}],"explanation":"Trois arguments pour une tachycardie sinusale : ondes P sinusales, variation progressive de la fréquence, contexte (fièvre, stress, douleur).","src":"p. 390-391","deep":"**Pourquoi** : trois arguments font la tachycardie sinusale : P sinusales (positives en D1, D2, D3, aVF), fréquence qui varie progressivement, contexte qui explique l'accélération (fièvre, stress, douleur) (p. 390-391).\n**Piège** : une tachycardie supraventriculaire non sinusale change de fréquence en « marches d'escalier »  ; une personne au repos ne doit pas être très tachycarde sans cause évidente d'augmentation du métabolisme : cela doit faire douter du caractère sinusal (p. 391).\n**À relier** : la variabilité peut se voir sur la courbe d'un scope ou par massage sinocarotidien (p. 391)."},{"id":"231-qru-708","type":"QRU","rank":"A","objective":"231-obj-17","tags":["diagnostic","ECG"],"difficulty":1,"stem":"Sur un tracé en rythme sinusal, un QRS fin survient prématurément. Il est précédé d'une onde P de morphologie différente de la P sinusale, qui déforme l'onde T précédente. De quelle extrasystole s'agit-il ?","options":[{"t":"Une extrasystole ventriculaire","ok":false,"why":"Elle donne un QRS large prématuré, avec ou sans onde P' rétrograde."},{"t":"Un complexe de fusion d'une tachycardie ventriculaire","ok":false,"why":"Le complexe de fusion est un QRS de largeur intermédiaire au sein d'une TV, ce qui n'est pas le cas."},{"t":"Une onde P bloquée d'un BAV2 Mobitz 2","ok":false,"why":"Une onde P bloquée n'est pas suivie de QRS, alors qu'ici le QRS fin prématuré existe."},{"t":"Une extrasystole jonctionnelle","ok":false,"why":"Elle donne un QRS fin avec ou sans onde P' rétrograde, et non une onde P précoce devant le QRS."},{"t":"Une extrasystole atriale","ok":true,"why":"Une onde P trop précoce, de morphologie différente (foyer ectopique), parfois masquée par l'onde T précédente, suivie d'un QRS fin : extrasystole atriale."}],"explanation":"L'aspect de l'extrasystole oriente son origine : P' précoce + QRS fin = atriale ; QRS fin ± P' rétrograde = jonctionnelle ; QRS large = ventriculaire.","src":"p. 397-398","deep":"**Pourquoi** : une ESA naît d'un foyer atrial ectopique : P' prématurée, de forme différente de la P sinusale, parfois cachée dans la T précédente qu'elle déforme, puis QRS fin car la conduction ventriculaire est normale (p. 397-398).\n**Piège** : une T déformée juste avant un QRS fin prématuré cache souvent une P' : ne pas conclure à une extrasystole jonctionnelle (QRS fin sans P' précoce) (p. 397).\n**À relier** : ESV = QRS large prématuré ; extrasystoles fréquentes ou polymorphes = rechercher une cardiopathie (p. 397)."},{"id":"231-qru-709","type":"QRU","rank":"B","objective":"231-obj-23","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Un homme de 28 ans consulte pour une douleur thoracique. L'ECG montre un sus-décalage du ST concave vers le haut, diffus, sans image en miroir, et un sous-décalage du segment PQ. Quel est le diagnostic le plus probable ?","options":[{"t":"Un anévrisme ventriculaire","ok":false,"why":"Il correspond à un sus-décalage persistant après un SCA ancien, dans le territoire de l'infarctus."},{"t":"Une péricardite aiguë","ok":true,"why":"Sus-décalage du ST diffus, concave vers le haut, sans miroir et sous-décalage de PQ caractérisent la phase initiale d'une péricardite aiguë."},{"t":"Une hypertrophie ventriculaire gauche marquée","ok":false,"why":"Elle peut donner un sus-décalage en V1-V2 et un sous-décalage latéral, mais pas un sus-décalage diffus avec sous-décalage de PQ."},{"t":"Un SCA avec sus-décalage du ST du territoire inférieur","ok":false,"why":"Dans un SCA ST+, le sus-décalage indique le territoire de la coronaire occluse (typé onde de Pardee), en général avec un miroir (qui peut être absent) ; ici le sus-décalage est diffus et le segment PQ est sous-décalé."},{"t":"Un angor de Prinzmetal","ok":false,"why":"Le spasme coronarien donne un sus-décalage semblable à celui d'un SCA ST+ (territoire, miroir), pas un sus-décalage diffus."}],"explanation":"Le sus-décalage diffus concave sans miroir et le sous-décalage du PQ sont les signes à retenir de la péricardite aiguë initiale.","src":"p. 409, 412","deep":"**Pourquoi** : le sus-ST de la péricardite est diffus (non systématisé à un territoire coronaire), concave vers le haut, sans miroir, avec sous-décalage de PQ : phase 1 (p. 409).\n**Piège** : l'absence de miroir ne suffit pas à elle seule, car elle peut exister dans un SCA ST+ ; ici c'est l'ensemble diffus + concave + PQ qui oriente (p. 409).\n**À relier** : 5 étiologies de sus-ST : SCA ST+, anévrisme, repolarisation précoce (inférolatérale), Prinzmetal, péricardite (p. 412)."},{"id":"231-qcm-701","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","méthode"],"difficulty":2,"stem":"Concernant les dérivations de Lewis, quelles propositions sont exactes ?","options":[{"t":"L'électrode jaune du bras gauche est placée au 5e espace intercostal gauche","ok":false,"why":"L'électrode jaune est placée au 5e espace intercostal droit."},{"t":"L'électrode rouge du bras droit est placée au niveau de la fourchette sternale","ok":true,"why":"C'est le positionnement décrit : rouge à la fourchette sternale, jaune au 5e espace intercostal droit."},{"t":"Elles servent à mesurer l'intervalle QT dans V2-V3","ok":false,"why":"Le QT se mesure dans la dérivation où l'onde T est la plus ample et la plus longue (souvent V2-V3), et non avec les dérivations de Lewis."},{"t":"Elles permettent de mieux visualiser une activité atriale peu visible sur l'ECG standard","ok":true,"why":"En cas de difficulté pour apercevoir l'activité atriale, on modifie la position des électrodes pour obtenir les dérivations de Lewis."},{"t":"L'activité atriale est alors bien visible en V1","ok":false,"why":"L'activité atriale est bien visible dans la dérivation D1 avec ce positionnement."}],"explanation":"Les dérivations de Lewis (électrode rouge sur la fourchette sternale, jaune au 5e espace intercostal droit) démasquent l'activité atriale, bien visible en D1.","src":"p. 373","deep":"**Pourquoi** : les dérivations de Lewis déplacent les électrodes (rouge à la fourchette sternale, jaune au 5e espace intercostal droit) pour démasquer une activité atriale mal visible, qui apparaît alors en D1 (p. 373).\n**Piège** : côté DROIT pour l'électrode jaune et lecture en D1, pas en V1 ; elles ne servent pas à mesurer le QT.\n**À relier** : autre façon de démasquer l'activité atriale : manœuvre vagale ou adénosine (bloc AV transitoire) (p. 390, 392)."},{"id":"231-qcm-702","type":"QRM","rank":"A","objective":"231-obj-22","tags":["ECG","méthode"],"difficulty":2,"stem":"Concernant la mesure de l'intervalle QT, quelles propositions sont exactes ?","options":[{"t":"L'onde U éventuelle doit être incluse dans la mesure","ok":false,"why":"L'onde U (seconde onde de repolarisation) ne doit pas être incluse dans la mesure du QT."},{"t":"On choisit la dérivation où l'onde T est la plus ample et la plus longue, souvent V2-V3","ok":true,"why":"C'est la dérivation recommandée pour la mesure."},{"t":"La fin de l'onde T est repérée en traçant sa tangente","ok":true,"why":"On trace la tangente à l'onde T pour déterminer sa fin."},{"t":"Le QT s'étend du début de l'onde P à la fin de l'onde T","ok":false,"why":"Le QT va du début de Q à la fin de T ; le début de P concerne l'intervalle PR."},{"t":"La formule de Bazett ramène le QT à ce qu'il serait pour une fréquence de 60 bpm","ok":true,"why":"Le QTc = QT / racine carrée de l'intervalle RR (en secondes) permet de disposer d'une seule norme à 60 bpm."}],"explanation":"Mesure du QT : Q jusqu'à la fin de T (tangente), dérivation à T ample (V2-V3), sans l'onde U, puis correction par Bazett (norme < 450 ms à 60 bpm).","src":"p. 376-377","deep":"**Pourquoi** : le QT va du début de Q à la fin de T ; la fin de T étant progressive, on trace sa tangente dans la dérivation où T est la plus ample et la plus longue (souvent V2-V3), puis on corrige par Bazett (QTc = QT / √RR en s) (p. 376-377).\n**Piège** : l'onde U ne doit pas être incluse dans la mesure (encadré « Attention », p. 377) ; le début de P concerne le PR.\n**À relier** : QTc normal < 450 ms à 60 bpm (en pratique 470-480 ms) ; causes de QT long : hypoK, hypoCa, hypoMg, médicaments, congénital, bradycardie extrême (p. 375, 404)."},{"id":"231-qcm-703","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","méthode"],"difficulty":2,"stem":"Un homme de 24 ans est asymptomatique. L'ECG de repos montre un rythme sinusal à 62/min, une onde P de 100 ms positive en D1 et D2, un PR à 170 ms, un QRS à 80 ms avec un axe à +60°, des ondes T positives sauf en aVR et V1, un point J sus-décalé de V1 à V4 avec un ST ascendant, un QTc à 430 ms et un indice de Sokolow à 28 mm. Quelles propositions sont exactes ?","options":[{"t":"L'axe du QRS est dévié à gauche","ok":false,"why":"Un axe à +60° est normal (de -30° à +90°)."},{"t":"La durée du QRS évoque un bloc de branche incomplet","ok":false,"why":"Un QRS de 80 ms est dans la norme (70 à 110 ms) ; le bloc incomplet se situe à 110-120 ms."},{"t":"Le sus-décalage du point J avec ST ascendant de V1 à V4 est une repolarisation physiologique chez le sujet jeune","ok":true,"why":"Chez le jeune, notamment l'homme, le point J peut être sus-décalé de V1 à V4 avec un segment ST jonctionnel ascendant."},{"t":"Le PR est allongé et définit un BAV du 1er degré","ok":false,"why":"Un PR de 170 ms est normal (120 à 200 ms) ; le BAV1 correspond à un PR > 200 ms."},{"t":"Le rythme est sinusal","ok":true,"why":"Onde P positive en D1 et D2, suivie d'un QRS, à 62/min : rythme sinusal normal."}],"explanation":"Pour affirmer qu'un ECG est normal, il faut être systématique : rythme, conduction, repolarisation, morphologie.","src":"p. 375, 377","deep":"**Pourquoi** : lecture systématique : rythme sinusal 60-100, conduction normale (P < 120 ms, PR 120-200, QRS 70-110, axe -30/+90), repolarisation et morphologie normales (Sokolow < 35 mm) (p. 377).\n**Piège** : le point J sus-décalé de V1 à V4 avec ST ascendant chez le jeune homme est une repolarisation physiologique, pas un SCA ni une péricardite (p. 377).\n**À relier** : seuils voisins : bloc incomplet 110-120 ms ; BAV1 > 200 ms (p. 381, 386)."},{"id":"231-qcm-704","type":"QRM","rank":"A","objective":"231-obj-06","tags":["ECG","pièges"],"difficulty":2,"stem":"Concernant les blocs de branche et les hémiblocs, quelles propositions sont exactes ?","options":[{"t":"Devant des QRS larges, il ne faut pas confondre un bloc de branche, sans conséquence immédiate, avec une TV","ok":true,"why":"Une TV est mortelle si elle n'est pas prise en charge, d'où l'importance de la distinction."},{"t":"Le diagnostic d'hémibloc repose sur l'axe du QRS","ok":true,"why":"L'hémibloc se reconnaît à la déviation axiale (HBAG au-delà de -30°, HBPG au-delà de +90°)."},{"t":"Les blocs de branche ne donnent pas de bradycardie","ok":true,"why":"Point clé du Collège (p. 415) : une bradycardie vient du nœud sinusal ou du NAV (p. 389) ; le bloc de branche modifie la durée et l'aspect du QRS, pas la fréquence."},{"t":"Le diagnostic de bloc de branche repose sur l'axe du QRS","ok":false,"why":"L'axe sert au diagnostic d'hémibloc ; le bloc de branche se diagnostique sur la DURÉE du QRS (> 120 ms) puis l'aspect en V1 (p. 381, 415)."},{"t":"Un QRS globalement positif en V1 correspond à un bloc de branche gauche","ok":false,"why":"Un QRS positif en V1 évoque un bloc de branche droit, négatif en V1 un bloc de branche gauche."}],"explanation":"Points clés du chapitre : bloc de branche = durée du QRS puis V1 ; hémibloc = axe ; ne pas confondre QRS larges bénins et TV.","src":"p. 415","deep":"**Pourquoi** : le bloc de branche se juge sur la durée du QRS (> 120 ms) puis l'aspect de V1 (positif = droit, négatif = gauche) ; l'hémibloc se juge sur l'axe ; aucun ne ralentit la fréquence (points clés, p. 415).\n**Piège** : devant un QRS large, ne pas confondre bloc de branche (sans conséquence immédiate) et TV (mortelle si non prise en charge) (p. 415).\n**À relier** : HBAG = axe au-delà de -30° ; HBPG = axe > +90° (p. 382)."},{"id":"231-qcm-705","type":"QRM","rank":"A","objective":"231-obj-08","tags":["diagnostic","ECG"],"difficulty":2,"stem":"Chez un patient de 70 ans, l'ECG montre des ondes P régulières, un PR constant à 180 ms puis une onde P bloquée de façon inopinée, avec des QRS larges. Quelles propositions sont exactes ?","options":[{"t":"Il existe une dissociation atrioventriculaire complète","ok":false,"why":"Dans le BAV3, aucune P n'est conduite ; ici la plupart des P sont conduites."},{"t":"Un pacemaker n'est indiqué qu'en cas de symptôme","ok":false,"why":"Le BAV infrahissien (Mobitz 2, BAV3) constitue une indication de pacemaker même en l'absence de symptôme."},{"t":"Le PR s'allonge progressivement avant l'onde P bloquée","ok":false,"why":"Un allongement progressif caractérise le Mobitz 1 ; ici le PR est constant."},{"t":"Il s'agit d'un BAV du 2e degré de type Mobitz 2","ok":true,"why":"PR constant puis onde P bloquée inopinée : Mobitz 2."},{"t":"Le siège du bloc est habituellement infrahissien","ok":true,"why":"Le Mobitz 2 est un BAV infrahissien, ce que renforcent les QRS larges."}],"explanation":"Mobitz 1 : suprahissien, allongement progressif du PR ; Mobitz 2 : infrahissien, PR constant puis P bloquée, pacemaker même sans symptôme.","src":"p. 385, 412","deep":"**Pourquoi** : PR constant puis P bloquée inopinée = Mobitz 2 ; c'est un bloc infrahissien, ce que renforcent les QRS larges (fig. 15.20, p. 385).\n**Piège** : Mobitz 1 = allongement PROGRESSIF du PR (suprahissien) ; et un Mobitz 2 relève du pacemaker même sans symptôme, à la différence du Mobitz 1 (p. 412).\n**À relier** : un BAV 2/1 à QRS larges oriente aussi vers l'infrahissien (p. 385) ; bloc bifasciculaire + syncope = télémétrie (p. 383)."},{"id":"231-qcm-706","type":"QRM","rank":"A","objective":"231-obj-05","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant l'ECG d'une hypertrophie ventriculaire gauche sévère, quelles propositions sont exactes ?","options":[{"t":"L'onde Q de dépolarisation septale disparaît dans les mêmes dérivations","ok":true,"why":"Dans la forme sévère, la Q septale latérale disparaît."},{"t":"Le segment ST est sous-décalé dans les dérivations latérales","ok":true,"why":"L'onde T négative est souvent associée à un sous-décalage du ST latéral."},{"t":"Les QRS sont toujours supérieurs à 120 ms","ok":false,"why":"Les QRS peuvent être un peu élargis mais restent le plus souvent inférieurs à 120 ms."},{"t":"Une onde T négative est observée en D1, aVL, V5 et V6","ok":true,"why":"C'est une anomalie secondaire de la repolarisation dans les dérivations latérales."},{"t":"La déviation axiale est modeste et dirigée vers la gauche","ok":true,"why":"La déviation axiale gauche est modeste dans l'HVG."}],"explanation":"HVG sévère : T négative + ST sous-décalé latéraux (D1, aVL, V5, V6), disparition de Q septale, axe modérément gauche, QRS souvent < 120 ms.","src":"p. 406","deep":"**Pourquoi** : l'HVG sévère perturbe secondairement la repolarisation dans les dérivations qui regardent le VG (D1, aVL, V5, V6) : T négative, ST sous-décalé, perte de la Q septale ; l'axe dévie modestement à gauche (p. 406).\n**Piège** : le QRS peut s'élargir un peu mais reste le plus souvent < 120 ms : 120 ms est le seuil du bloc de branche complet (p. 378, 406).\n**À relier** : Sokolow normal < 35 mm ; pièges en V1-V2 : pseudonécrose QS et pseudo sus-ST (p. 406-407)."},{"id":"231-qcm-707","type":"QRM","rank":"B","objective":"231-obj-23","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Un homme de 28 ans présente une douleur thoracique. L'ECG montre un sus-décalage du ST concave vers le haut et diffus, un sous-décalage du segment PQ et un microvoltage, sans image en miroir. Quelles propositions sont exactes ?","options":[{"t":"L'absence d'image en miroir exclut formellement un SCA avec sus-décalage du ST","ok":false,"why":"L'image en miroir peut être absente dans un SCA ST+ : il ne faut pas conclure à tort à une péricardite."},{"t":"Le microvoltage est d'autant plus marqué que la péricardite est liquidienne","ok":true,"why":"Plus l'épanchement liquidien est abondant, plus le microvoltage est important."},{"t":"Le tableau évoque une péricardite aiguë en phase initiale","ok":true,"why":"Sus-décalage diffus concave, PQ sous-décalé et microvoltage sont les signes de la phase 1."},{"t":"À la phase 2, les ondes T s'aplatissent dans toutes les dérivations et le ST devient isoélectrique","ok":true,"why":"C'est la deuxième phase de l'évolution classique en quatre phases."},{"t":"À la phase 3, les ondes T deviennent négatives de façon persistante","ok":true,"why":"La phase 3 de la péricardite aiguë est marquée par des ondes T négatives persistantes, avant le retour progressif à la normale de la phase 4."}],"explanation":"Évolution de la péricardite aiguë en 4 phases : (1) ST sus-décalé concave, PQ sous-décalé, microvoltage ; (2) T plates ; (3) T négatives ; (4) normalisation.","src":"p. 409","deep":"**Pourquoi** : sus-ST diffus concave vers le haut + PQ sous-décalé + microvoltage (d'autant plus marqué que la péricardite est liquidienne) = phase 1 d'une péricardite aiguë, qui évolue en 4 phases : T plates, T négatives persistantes, normalisation (p. 409).\n**Piège** : l'image en miroir peut manquer dans un SCA ST+ : son absence n'exclut rien (encadré « Attention », p. 409).\n**À relier** : SCA ST+ : onde de Pardee avec miroir, sur ≥ 2 dérivations adjacentes (p. 412)."},{"id":"231-qcm-708","type":"QRM","rank":"B","objective":"231-obj-20","tags":["ECG","urgence"],"difficulty":2,"stem":"Une femme de 60 ans, traitée par un psychotrope et un antibiotique, présente une hypokaliémie profonde. L'ECG montre un QT très allongé, puis des salves de TV polymorphe qui s'arrêtent spontanément. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit de torsades de pointes sur QT long","ok":true,"why":"Une TV polymorphe sur QT allongé correspond aux torsades de pointes, qui peuvent dégénérer en FV."},{"t":"Il faut arrêter les médicaments allongeant le QT","ok":true,"why":"L'association de médicaments allongeant le QT est un facteur favorisant des torsades."},{"t":"Il faut accélérer la fréquence cardiaque","ok":true,"why":"Accélérer la fréquence cardiaque fait partie de la prise en charge des torsades."},{"t":"Il faut ralentir la fréquence cardiaque par un bradycardisant","ok":false,"why":"La bradycardie extrême favorise les torsades ; il faut au contraire accélérer la fréquence."},{"t":"Il faut corriger les troubles ioniques, notamment l'hypokaliémie","ok":true,"why":"L'hypokaliémie, l'hypocalcémie et l'hypomagnésémie allongent le QT et doivent être corrigées."}],"explanation":"Prise en charge des torsades : corriger les troubles ioniques, accélérer la fréquence cardiaque et arrêter les médicaments allongeant le QT.","src":"p. 403-404","deep":"**Pourquoi** : QT très allongé + TV polymorphe qui s'arrête seule = torsades de pointes ; ici trois facteurs s'additionnent : hypokaliémie, psychotrope et antibiotique (classes citées p. 404) (p. 403-404).\n**Piège** : on accélère le cœur, on ne le ralentit pas : la bradycardie extrême (dont l'intoxication par bradycardisant) est elle-même une cause de QT long (p. 404).\n**À relier** : prise en charge : corriger les troubles ioniques, accélérer la FC, arrêter les médicaments allongeant le QT ; la torsade peut dégénérer en FV (p. 403-404)."},{"id":"231-qcm-709","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","axe"],"difficulty":2,"stem":"Un ECG montre un QRS positif en D1, négatif en aVF et négatif en D2. Que peut-on conclure sur l'axe du QRS ?","options":[{"t":"Un axe hypergauche au-delà de -30°","ok":true,"why":"D1+ et aVF- placent l'axe entre 0 et -90° ; D2 négatif indique qu'il dépasse -30° : axe hypergauche."},{"t":"Un axe normal entre 0 et -30°","ok":false,"why":"Cet axe correspond à un D1 positif, un aVF négatif mais un D2 positif ; ici D2 est négatif."},{"t":"Un axe hyperdroit entre 90 et 180°","ok":false,"why":"Il correspond à un D1 négatif et un aVF positif."},{"t":"Un axe normal entre 0 et 90°","ok":false,"why":"Un axe normal entre 0 et 90° impose D1 et aVF tous deux positifs."},{"t":"Un axe extrême entre -90° et -180°","ok":false,"why":"Il correspond à un D1 et un aVF négatifs."}],"explanation":"Méthode rapide : D1 et aVF donnent le cadran ; en cas de D1+ et aVF-, D2 positif signifie axe normal et D2 négatif axe hypergauche.","src":"p. 375","deep":"**Pourquoi** : D1 et aVF donnent le quadrant : D1+ et aVF- = entre 0 et -90° ; D2 (à +60°) tranche : positif = 0 à -30° (normal), négatif = au-delà de -30° (hypergauche) (p. 375).\n**Piège** : D1+ aVF- n'est pas forcément anormal : seul D2 négatif signe l'axe hypergauche, qui définit l'HBAG (p. 382).\n**À relier** : D1-/aVF+ = hyperdroit (90-180°) ; D1-/aVF- = extrême (-90 à -180°) (p. 375)."},{"id":"231-qcm-710","type":"QRM","rank":"B","objective":"231-obj-09","tags":["ECG","diagnostic"],"difficulty":3,"stem":"Une patiente de 78 ans, connue pour une FA, présente un malaise. L'ECG montre une trémulation de la ligne de base en D2, D3 et aVF, sans onde P identifiable, et des QRS fins réguliers à 38/min. Quelle proposition est exacte ?","options":[{"t":"Il s'agit d'une dysfonction sinusale avec ondes P sinusales lentes","ok":false,"why":"Il n'y a pas d'onde P sinusale identifiable : l'activité atriale est fibrillatoire."},{"t":"Il s'agit d'une FA conduite lentement, avec des QRS irrégulièrement irréguliers","ok":false,"why":"Les QRS sont ici réguliers : une FA conduite lentement garderait des intervalles RR irréguliers."},{"t":"Il s'agit d'une tachycardie jonctionnelle par réentrée intranodale","ok":false,"why":"La tachycardie jonctionnelle est rapide (130 à 260/min), pas lente à 38/min."},{"t":"Il s'agit d'une FA associée à un BAV complet avec rythme d'échappement","ok":true,"why":"Une activité ventriculaire devenue lente et régulière en FA doit faire évoquer un BAV complet : la dépolarisation ventriculaire se fait par un rythme d'échappement automatique, régulier."},{"t":"Il s'agit d'un flutter atrial conduit en 4/1","ok":false,"why":"Le flutter montre des ondes F monomorphes organisées et sans trémulation fine de la ligne de base."}],"explanation":"FA + BAV complet : QRS lents et réguliers au lieu d'irrégulièrement irréguliers, par rythme d'échappement automatique.","src":"p. 392","deep":"**Pourquoi** : en BAV complet, aucun influx de la FA n'atteint les ventricules : un rythme d'échappement automatique, lent et régulier, prend le relais ; des QRS réguliers sur une trémulation atriale signent donc FA + BAV3 (p. 392).\n**Piège** : une FA « lente » reste irrégulièrement irrégulière : la régularité des RR est l'indice clé (p. 392).\n**À relier** : BAV3 associé à la FA ou aux flutters = objectif de rang B (p. 368) ; bradycardie : regarder l'activité atriale (P normales ou tachycardes = BAV) (p. 389)."},{"id":"231-qcm-711","type":"QRM","rank":"A","objective":"231-obj-24","tags":["ECG","urgence"],"difficulty":2,"stem":"Un homme de 55 ans consulte pour une douleur thoracique. L'ECG montre un sous-décalage isolé du segment ST de V1 à V3. Quelle proposition est exacte ?","options":[{"t":"Les dérivations V3R et V4R suffisent pour explorer le territoire postérieur","ok":false,"why":"V3R et V4R explorent le ventricule droit, pas la paroi postérieure."},{"t":"Un sous-décalage en V1-V3 exclut un SCA avec sus-décalage du ST","ok":false,"why":"Il peut au contraire en être le miroir (sus-décalage postérieur en V7-V9)."},{"t":"Il s'agit forcément d'un SCA sans sus-décalage du ST, sans exploration électrique complémentaire","ok":false,"why":"Un sous-décalage antérieur peut être le miroir d'un sus-décalage postérieur : il faut compléter l'ECG."},{"t":"Il faut réaliser un ECG 18 dérivations pour rechercher un sus-décalage postérieur en V7-V9","ok":true,"why":"Devant toute douleur thoracique, un ECG 18 dérivations évite de méconnaître un sus-décalage postérieur."},{"t":"V7, V8 et V9 explorent la paroi latérale haute du ventricule gauche","ok":false,"why":"Ces dérivations explorent la face basale et inférieure (postérieure) du VG."}],"explanation":"Un sous-décalage antérieur (V1-V3) peut être le miroir d'un sus-décalage postérieur (V7-V9) : ECG 18 dérivations devant toute douleur thoracique.","src":"p. 374, 411","deep":"**Pourquoi** : un sous-décalage en V1-V3 peut être le miroir d'un sus-décalage postérieur (V7-V9), que l'ECG 12 dérivations ne voit pas : ECG 18 dérivations devant toute douleur thoracique (p. 411).\n**Piège** : on traque le sus-décalage d'abord, puis le miroir ; V3R/V4R explorent le VD, V7-V9 la face basale et inférieure du VG (p. 374, 411).\n**À relier** : sus-ST significatif : ≥ 2 mm en V1-V3, ≥ 1 mm ailleurs, sur ≥ 2 dérivations adjacentes (p. 412)."},{"id":"231-qcm-712","type":"QRM","rank":"A","objective":"231-obj-14","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Un homme de 60 ans consulte pour des palpitations régulières. L'ECG montre une tachycardie régulière à 150/min à QRS fins. Une manœuvre vagale ralentit transitoirement la cadence et fait apparaître des ondes en dents de scie négatives en D2, D3 et aVF. Quelle proposition est exacte ?","options":[{"t":"Il s'agit d'une tachycardie sinusale","ok":false,"why":"Elle montre des ondes P sinusales positives en D2, D3, aVF et une fréquence variant progressivement."},{"t":"Il s'agit d'une tachycardie jonctionnelle par réentrée intranodale, qui devrait s'arrêter brutalement","ok":false,"why":"Une réentrée intranodale serait arrêtée par la manœuvre, et son activité atriale n'est souvent pas visible."},{"t":"Il s'agit d'un flutter atrial typique antihoraire conduit en 2/1","ok":true,"why":"Les ondes F négatives en D2, D3, aVF caractérisent le flutter typique antihoraire ; la conduction 2/1 donne environ 150/min, et la manœuvre vagale démasque l'activité atriale."},{"t":"Il s'agit d'une FA","ok":false,"why":"La FA est irrégulièrement irrégulière, sans ondes en dents de scie organisées."},{"t":"Il s'agit d'une TV monomorphe","ok":false,"why":"Une TV a des QRS larges, ce qui n'est pas le cas ici."}],"explanation":"Dans un flutter conduit en 2/1, la manœuvre vagale ralentit transitoirement la réponse ventriculaire et révèle les ondes F en toit d'usine.","src":"p. 393-395, 405","deep":"**Pourquoi** : tachycardie régulière à QRS fins à 150/min = forme usuelle du flutter en 2/1 (F à 300) ; la manœuvre vagale ralentit transitoirement la réponse ventriculaire et démasque les ondes F, négatives en D2, D3, aVF dans le typique antihoraire (p. 394-395).\n**Piège** : une tachycardie jonctionnelle serait au contraire arrêtée par la manœuvre (p. 397) ; un flutter n'est que ralenti temporairement, l'activité atriale persiste.\n**À relier** : flutter typique : boucle de l'OD passant par l'isthme cavotricuspide ; horaire = polarités inversées (p. 394)."},{"id":"231-qcm-713","type":"QRM","rank":"A","objective":"231-obj-17","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant les extrasystoles, quelles propositions sont exactes ?","options":[{"t":"Des extrasystoles polymorphes sont toujours physiologiques sur cœur sain","ok":false,"why":"Des extrasystoles fréquentes ou polymorphes doivent faire rechercher une cardiopathie."},{"t":"Le trigéminisme correspond à une extrasystole un battement sur deux","ok":false,"why":"Un battement sur deux définit le bigéminisme ; le trigéminisme correspond à un battement sur trois."},{"t":"Une extrasystole atriale donne un QRS large précédé d'une onde P sinusale","ok":false,"why":"L'extrasystole atriale donne une onde P' précoce de morphologie différente, suivie d'un QRS fin."},{"t":"Une extrasystole jonctionnelle donne un QRS fin, avec ou sans onde P' rétrograde","ok":true,"why":"L'influx naît dans la jonction et part dans les deux sens vers l'oreillette et le ventricule."},{"t":"Une extrasystole ventriculaire donne un QRS large prématuré, avec ou sans onde P' rétrograde","ok":true,"why":"Le QRS est large car l'influx se propage de proche en proche."}],"explanation":"Aspect des extrasystoles : atriale = P' précoce + QRS fin ; jonctionnelle = QRS fin ± P' rétrograde ; ventriculaire = QRS large ± P' rétrograde.","src":"p. 397-398","deep":"**Pourquoi** : l'origine de l'extrasystole se lit sur le QRS et la P : atriale = P' précoce de forme différente + QRS fin ; jonctionnelle = QRS fin ± P' rétrograde ; ventriculaire = QRS large ± P' rétrograde (p. 397).\n**Piège** : bigéminisme = 1 battement sur 2, trigéminisme = 1 sur 3 ; et des extrasystoles fréquentes ou polymorphes font rechercher une cardiopathie (p. 397-398).\n**À relier** : extrasystoles jonctionnelles : rares, le plus souvent pathologie de la jonction nodohissienne (p. 397)."},{"id":"231-qcm-714","type":"QRM","rank":"B","objective":"231-obj-18","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Un homme de 66 ans, avec un infarctus ancien, porte un Holter de 24 h. L'enregistrement montre une salve asymptomatique de 12 QRS larges consécutifs à 170/min, durant 4 secondes. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une fibrillation ventriculaire","ok":false,"why":"La FV est une tachycardie irrégulière à QRS larges polymorphes, avec arrêt cardiaque."},{"t":"Le Holter permet ici d'évaluer le risque rythmique après infarctus","ok":true,"why":"La détection de salves asymptomatiques de TV est l'une des utilisations du Holter après infarctus."},{"t":"Une cardiopathie sous-jacente éloigne le diagnostic de TV","ok":false,"why":"La cardiopathie sous-jacente est au contraire un argument en faveur de la TV."},{"t":"Il s'agit d'une TV non soutenue","ok":true,"why":"Entre 3 battements consécutifs et 30 secondes, on parle de TV non soutenue."},{"t":"Il s'agit d'une TV soutenue","ok":false,"why":"Une TV soutenue dure plus de 30 secondes."}],"explanation":"TVNS : au moins 3 battements consécutifs et moins de 30 secondes ; TV soutenue au-delà de 30 secondes.","src":"p. 399, 415","deep":"**Pourquoi** : 12 QRS larges à 170/min = tachycardie > 100 bpm à QRS > 120 ms sur ≥ 3 battements : TV ; elle dure 4 s, donc entre 3 battements et 30 s : TV non soutenue (p. 399).\n**Piège** : TV soutenue = > 30 s ; une cardiopathie (infarctus ancien) est un argument EN FAVEUR de la TV, pas contre (p. 399-400).\n**À relier** : le Holter de 24 h évalue le risque rythmique après infarctus ou dans les cardiomyopathies par la détection de salves de TV asymptomatiques (p. 415)."},{"id":"231-qcm-715","type":"QRM","rank":"A","objective":"231-obj-18","tags":["ECG","urgence"],"difficulty":2,"stem":"Un homme de 62 ans, avec un infarctus ancien, présente un malaise. L'ECG montre une tachycardie régulière à QRS larges à 170/min ; la pression artérielle est à 80/50 mmHg. Quelles propositions sont exactes ?","options":[{"t":"La fréquence à 170/min permet d'affirmer un flutter conduit en 2/1","ok":false,"why":"Un flutter 2/1 donne une cadence usuelle à 150/min et, sans bloc associé, des QRS fins (p. 390, 394) ; surtout, une tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire (p. 398)."},{"t":"L'adénosine IV est le premier geste à réaliser","ok":false,"why":"En cas de mauvaise tolérance hémodynamique, la conduite est la cardioversion électrique externe ; manœuvres vagales et adénosine s'adressent aux tachycardies bien tolérées."},{"t":"Il faut attendre le dosage de troponine avant toute décision","ok":false,"why":"La suspicion de TV impose de donner l'alerte (faire le 15) et de se préparer à une réanimation."},{"t":"Il faut considérer ce tracé comme une TV jusqu'à preuve du contraire","ok":true,"why":"Toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire, d'autant qu'il existe une cardiopathie."},{"t":"La mauvaise tolérance hémodynamique conduit à une cardioversion électrique externe","ok":true,"why":"C'est la conduite devant une tachycardie mal tolérée."}],"explanation":"Tachycardie à QRS larges mal tolérée : TV jusqu'à preuve du contraire, alerte (15) et cardioversion électrique externe.","src":"p. 398-399, 405","deep":"**Pourquoi** : tachycardie régulière à QRS larges = TV jusqu'à preuve du contraire, d'autant plus sur un infarctus ancien (réentrée sur fibrose) ; la PA à 80/50 traduit une mauvaise tolérance : cardioversion électrique externe (p. 398-399, 405).\n**Piège** : manœuvres vagales et adénosine ne s'adressent qu'aux tachycardies bien tolérées ; on n'attend pas la troponine : alerte (15) et préparation à la réanimation (p. 399, 405).\n**À relier** : la TV peut dégénérer en FV puis asystolie (p. 398)."},{"id":"231-qcm-716","type":"QRM","rank":"A","objective":"231-obj-01","tags":["ECG","définition"],"difficulty":1,"stem":"Concernant l'intervalle PR, quelles propositions sont exactes ?","options":[{"t":"Il explore toute la conduction, de la sortie du nœud sinusal aux extrémités du réseau de Purkinje","ok":true,"why":"Il ne se limite donc pas à la traversée du NAV."},{"t":"Sa valeur normale est comprise entre 80 et 120 ms","ok":false,"why":"La valeur normale est de 120 à 200 ms."},{"t":"Il explore uniquement la traversée du nœud atrioventriculaire","ok":false,"why":"Il explore la totalité de la conduction, de la sortie du nœud sinusal aux extrémités du réseau de Purkinje."},{"t":"Un intervalle supérieur à 160 ms définit un BAV du 1er degré","ok":false,"why":"Le BAV1 est défini par un PR supérieur à 200 ms."},{"t":"Il est mesuré du début de l'onde P au début du QRS","ok":true,"why":"C'est la définition de l'intervalle PR."}],"explanation":"PR normal : 120-200 ms ; allongé de façon fixe > 200 ms, il définit le BAV du 1er degré.","src":"p. 376, 386","deep":"**Pourquoi** : le PR va du début de P au début du QRS et explore toute la conduction, de la sortie du nœud sinusal jusqu'aux extrémités de Purkinje, pas seulement le NAV ; normal 120-200 ms inclus (p. 376).\n**Piège** : le BAV1 est défini par un PR fixe > 200 ms (p. 386), pas > 160 ms ; un PR court < 120 ms évoque une préexcitation (p. 410).\n**À relier** : dans un bloc bifasciculaire avec BAV1, le ralentissement peut siéger dans le NAV ou dans la troisième branche (fig. 15.18, p. 384)."},{"id":"231-qcm-717","type":"QRM","rank":"A","objective":"231-obj-14","tags":["ECG","définition"],"difficulty":2,"stem":"Concernant le flutter atrial et la fibrillation atriale, quelles propositions sont exactes ?","options":[{"t":"Les flutters de l'oreillette droite sont plus fréquents que ceux de l'oreillette gauche","ok":true,"why":"L'oreillette droite comporte des zones propices à l'initiation même sans cardiopathie."},{"t":"Dans le flutter, les QRS sont habituellement irrégulièrement irréguliers","ok":false,"why":"La cadence ventriculaire du flutter est régulière le plus souvent ; ce sont les QRS de la FA qui sont irrégulièrement irréguliers."},{"t":"L'activité atriale du flutter est monomorphe, sans retour à la ligne isoélectrique dans au moins une dérivation","ok":true,"why":"La boucle d'activation permanente explique l'absence de retour à la ligne de base."},{"t":"Les ondes atriales de la FA sont organisées en dents de scie","ok":false,"why":"L'activité de la FA est anarchique (fibrillatoire) ; c'est le flutter qui donne des ondes F en dents de scie."},{"t":"Un même patient peut présenter successivement des épisodes de flutter et de FA","ok":true,"why":"Les facteurs prédisposants sont communs."}],"explanation":"Flutter = activation organisée en boucle (ondes F, QRS souvent réguliers) ; FA = activation anarchique (QRS irrégulièrement irréguliers).","src":"p. 392-393","deep":"**Pourquoi** : le flutter est une boucle organisée (ondes F monomorphes, sans retour à l'isoélectrique dans au moins une dérivation, QRS le plus souvent réguliers) ; la FA est anarchique (RR irrégulièrement irréguliers) (p. 392-394).\n**Piège** : un flutter à conduction variable peut donner des QRS irréguliers, mais son activité atriale reste monomorphe (p. 394).\n**À relier** : flutters droits plus fréquents (zones propices constitutionnelles de l'OD) ; facteurs prédisposants communs FA/flutter (p. 393)."},{"id":"231-qcm-718","type":"QRM","rank":"A","objective":"231-obj-24","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant l'évolution du sus-décalage du ST d'un SCA avec sus-décalage du ST, quelles propositions sont exactes ?","options":[{"t":"L'apparition d'ondes Q de nécrose indique que la reperfusion est devenue inutile","ok":false,"why":"Les ondes Q ne doivent pas faire considérer à tort qu'une reperfusion serait inutile car trop tardive."},{"t":"Il peut persister indéfiniment en cas d'évolution anévrismale","ok":true,"why":"Un sus-décalage persistant doit faire évoquer un anévrisme de la paroi infarcie."},{"t":"Il régresse rapidement après reperfusion","ok":true,"why":"Le sus-décalage régresse rapidement avec la reperfusion, alors qu'il dure plusieurs jours sans reperfusion (p. 412)."},{"t":"Après 48 heures, l'évolution normale se fait vers une onde T positive et ample","ok":false,"why":"L'évolution normale après 48 heures se fait vers une onde T négative dite « ischémique »."},{"t":"Il persiste plusieurs jours en l'absence de reperfusion","ok":true,"why":"Sans reperfusion, le sus-décalage dure plusieurs jours."}],"explanation":"Sus-décalage : disparaît vite si reperfusion, dure plusieurs jours sinon, persiste en cas d'anévrisme ; les T négatives « ischémiques » apparaissent après 48 h.","src":"p. 412","deep":"**Pourquoi** : le sus-ST reflète la lésion : il régresse vite après reperfusion, dure plusieurs jours sans reperfusion et persiste indéfiniment en cas d'anévrisme de la paroi infarcie (p. 412).\n**Piège** : les ondes Q (en principe vers la 6e heure, parfois plus tôt) ne signifient pas qu'il est trop tard pour reperfuser (p. 412).\n**À relier** : après 48 h, évolution normale vers une T négative « ischémique » (p. 412)."},{"id":"231-qcm-719","type":"QRM","rank":"B","objective":"231-obj-25","tags":["ECG","diagnostic"],"difficulty":2,"stem":"Concernant la préexcitation ventriculaire, quelles propositions sont exactes ?","options":[{"t":"L'onde delta correspond à un empâtement du pied du QRS","ok":true,"why":"Elle correspond à la partie préexcitée du ventricule."},{"t":"Le PR est allongé (> 200 ms)","ok":false,"why":"La préexcitation donne un PR court (< 120 ms)."},{"t":"Bloquer le NAV peut démasquer une préexcitation minime","ok":true,"why":"L'influx ne passe alors que par la voie accessoire."},{"t":"La voie accessoire filtre l'influx atrial aussi bien que le NAV","ok":false,"why":"Elle n'a pas de propriété décrémentielle : elle filtre mal l'influx en cas de FA."},{"t":"Il ne faut pas bloquer le NAV en cas de FA","ok":true,"why":"Une FA rapide conduite par la voie accessoire expose au risque de FV."}],"explanation":"Préexcitation : PR court + onde delta + anomalies de repolarisation ; on démasque en bloquant le NAV sauf en cas de FA.","src":"p. 410-411","deep":"**Pourquoi** : la voie accessoire conduit vite de l'oreillette au ventricule : PR court (< 120 ms) et onde delta (empâtement du pied du QRS = zone préexcitée) ; bloquer le NAV force l'influx par la voie et démasque une préexcitation minime (p. 410).\n**Piège** : à ne pas faire en cas de FA : la voie, sans propriété décrémentielle, filtre mal et expose au super-Wolff puis à la FV (p. 410-411).\n**À relier** : WPW = voie accessoire antérograde + palpitations par tachycardie jonctionnelle (p. 411)."},{"id":"231-qcm-720","type":"QRM","rank":"B","objective":"231-obj-28","tags":["examens","ECG"],"difficulty":2,"stem":"Concernant les enregistrements ECG de longue durée, quelles propositions sont exactes ?","options":[{"t":"Un enregistreur d'événements réalise l'ECG au moment des symptômes","ok":true,"why":"Il s'agit d'outils dédiés ou de montres connectées ECG."},{"t":"Le Holter donne une lecture en temps réel sur les 12 dérivations","ok":false,"why":"Il enregistre 2 à 12 dérivations simultanées avec analyse en différé (centre de lecture)."},{"t":"Un Holter de 24 à 96 h est pertinent pour des palpitations épisodiques si elles risquent de se répéter pendant l'enregistrement","ok":true,"why":"C'est la condition posée quand l'ECG standard n'a pas fait le diagnostic."},{"t":"Un Holter de 24 h est l'examen de première intention pour des symptômes survenant une fois par an","ok":false,"why":"Pour des symptômes rares, on utilise l'ECG ambulatoire de très longue durée ou des enregistreurs d'événements."},{"t":"Un moniteur implantable permet un suivi pouvant aller jusqu'à 3 ans","ok":true,"why":"Il est employé pour les syncopes inexpliquées ou la FA silencieuse."}],"explanation":"Choisir la méthode selon la fréquence des symptômes : Holter 24-96 h, ECG de longue durée jusqu'à 21 jours ou enregistreur d'événements, moniteur implantable.","src":"p. 415","deep":"**Pourquoi** : on adapte la durée d'enregistrement à la fréquence des symptômes : Holter 24-96 h (2 à 12 dérivations, analyse différée) si les symptômes risquent de se répéter, ECG ambulatoire jusqu'à 21 jours ou enregistreur d'événements s'ils sont rares, moniteur implantable jusqu'à 3 ans (p. 415).\n**Piège** : le Holter n'est pas un monitorage en temps réel : l'analyse est différée (centre de lecture) (p. 415).\n**À relier** : Holter 24 h aussi pour : efficacité des bradycardisants, réglage des pacemakers, salves de TV post-infarctus (p. 415)."},{"id":"231-qcm-721","type":"QRM","rank":"A","objective":"231-obj-12","tags":["ECG","définition"],"difficulty":2,"stem":"Concernant les troubles du rythme supraventriculaires, quelles propositions sont exactes ?","options":[{"t":"Le terme « trouble du rythme » désigne en français aussi bien les tachycardies que les bradycardies","ok":false,"why":"Il est synonyme de tachycardie ; les bradycardies relèvent des troubles de la conduction."},{"t":"Le passage atrioventriculaire peut se faire en 1/1, 2/1 ou en alternance selon l'intensité du filtre du NAV","ok":true,"why":"Le filtre dépend de l'âge, du tonus vagal et des médicaments ralentisseurs du NAV."},{"t":"Ils peuvent s'associer à des QRS larges en cas de bloc de branche","ok":true,"why":"Par exemple FA ou tachycardie supraventriculaire sur bloc de branche complet."},{"t":"Ils sont à QRS fins dans la majorité des cas","ok":true,"why":"Ils sont à QRS fins (< 120 ms) sauf trouble de conduction intraventriculaire."},{"t":"Les manœuvres vagales accélèrent la conduction dans le NAV","ok":false,"why":"Elles créent un bloc atrioventriculaire transitoire, en intensifiant le filtre AV."}],"explanation":"TSV = fréquence trop élevée des oreillettes ou de la jonction ; QRS fins en général ; filtre du NAV variable.","src":"p. 389-390","deep":"**Pourquoi** : les troubles du rythme supraventriculaires naissent dans les oreillettes ou la jonction ; ils passent par le réseau normal (QRS fins) sauf bloc de branche ; le NAV filtre selon l'âge, le tonus vagal et les médicaments (1/1, 2/1, alterné) (p. 389-390).\n**Piège** : les manœuvres vagales INTENSIFIENT le filtre (bloc AV transitoire), elles ne l'accélèrent pas ; et « trouble du rythme » = tachycardie, les bradycardies étant des troubles de la conduction (p. 390).\n**À relier** : sans ce filtre, chaque FA donnerait une FV (p. 390)."}],"edn":[{"id":"231-kfp-01","type":"KFP","rank":"A","objective":"231-obj-15","difficulty":2,"scenario":"Une femme de 32 ans, sans antécédent, consulte aux urgences pour des palpitations à début et fin brutaux, sans douleur thoracique ni lipothymie. L'ECG objective une tachycardie régulière à QRS fins à 190 bpm, sans onde P clairement identifiable. La pression artérielle est à 110/70 mmHg, sans signe de mauvaise tolérance hémodynamique.","questions":[{"stem":"Parmi les éléments suivants, lesquels orientent vers une tachycardie jonctionnelle plutôt qu'une tachycardie sinusale ?","max":2,"options":["Début et fin brutaux de la tachycardie","Variation progressive de la fréquence cardiaque","Onde P sinusale bien visible avant chaque QRS","Absence d'activité atriale clairement identifiable","Contexte fébrile expliquant l'accélération","Ralentissement progressif et transitoire de la fréquence lors d'un massage sinocarotidien","Antécédent connu de cardiopathie ischémique","Fréquence cardiaque variant en fonction de la respiration"],"correct":[0,3],"explanation":"Une tachycardie sinusale garde des P sinusales (positives en D1, D2, D3, aVF) et varie progressivement, ce que peut montrer un massage sinocarotidien (p. 390-391) ; une tachycardie supraventriculaire non sinusale fait des « marches d'escalier ». Ici, l'absence d'activité atriale visible sur une tachycardie très régulière ≈ 190 bpm évoque une réentrée intranodale, où oreillettes et ventricules sont activés presque en même temps (p. 395) ; le début et la fin brutaux orientent aussi vers une tachycardie jonctionnelle (item 237, p. 422). Fièvre, variation respiratoire ou ralentissement progressif au massage sont au contraire des arguments pour le sinus."},{"stem":"Quelle est la prise en charge immédiate la plus appropriée devant cette tachycardie jonctionnelle bien tolérée ?","max":1,"options":["Cardioversion électrique externe immédiate","Manœuvre vagale, puis adénosine IV en cas d'échec","Bêtabloquant intraveineux d'emblée","Amiodarone intraveineuse d'emblée","Digoxine intraveineuse","Surveillance simple sans aucun geste diagnostique","Choc électrique externe synchronisé d'emblée","Massage cardiaque externe"],"correct":[1],"explanation":"Bonne tolérance hémodynamique → manœuvre vagale, puis adénosine IV en cas d'échec : elles bloquent transitoirement le NAV et réduisent la tachycardie jonctionnelle (p. 397, 405). La cardioversion électrique (ou le choc synchronisé) est réservée à la mauvaise tolérance (fig. 15.51, p. 405) ; le massage cardiaque concerne l'arrêt cardiaque (FV). Ne pas « surveiller sans geste » : la manœuvre est aussi diagnostique dans la majorité des cas. Avant l'adénosine, vérifier ses CI : asthme, hypotension (p. 390)."},{"stem":"Quel mécanisme électrophysiologique explique l'efficacité attendue de la manœuvre vagale ou de l'adénosine dans ce contexte ?","max":1,"options":["Blocage atrioventriculaire transitoire interrompant la réentrée dépendante du NAV","Effet inotrope négatif direct sur le myocarde ventriculaire","Vasodilatation coronaire","Accélération de la conduction dans le nœud atrioventriculaire","Stimulation sympathique du nœud sinusal","Diminution de la précharge cardiaque","Allongement de l'intervalle QT","Blocage exclusif d'une voie accessoire, sans effet sur le NAV"],"correct":[0],"explanation":"Manœuvres vagales et adénosine (vagomimétique, récepteurs purinergiques, effet d'une dizaine de secondes) intensifient le filtre du NAV et créent un bloc AV transitoire (p. 390) : la réentrée intranodale, qui tourne dans le NAV, est interrompue et la tachycardie s'arrête (p. 395, 397). Elles ralentissent le NAV (pas d'accélération) et n'agissent ni par effet inotrope ni sur le QT ; leur cible est le NAV, pas la voie accessoire (p. 390)."}],"src":"p. 390, 395-397"},{"id":"231-kfp-02","type":"KFP","rank":"A","objective":"231-obj-08","difficulty":2,"scenario":"Un homme de 78 ans consulte pour des lipothymies répétées depuis un mois. L'ECG per-critique montre une fréquence cardiaque des QRS à 38 bpm, avec des ondes P régulières à une fréquence de 75 bpm, plus nombreuses que les QRS, sans relation constante entre onde P et QRS.","questions":[{"stem":"Quelle structure du système de conduction est probablement en cause dans cette bradycardie ?","max":1,"options":["Le nœud sinusal","Le nœud atrioventriculaire","Le nerf vague isolément","Un foyer ectopique atrial","Une voie accessoire","L'oreillette gauche","Le système nerveux sympathique","La veine cave supérieure"],"correct":[1],"explanation":"Deux structures seulement donnent une bradycardie : le nœud sinusal et le NAV (p. 389). Ici les P sont régulières à 75 bpm (le nœud sinusal marche) mais plus nombreuses que les QRS sans lien constant : c'est le passage au ventricule qui est bloqué, donc un BAV (p. 389). Le nerf vague, le sympathique ou l'oreillette ne sont pas des structures de conduction AV ; une voie accessoire donne une préexcitation, pas une bradycardie."},{"stem":"Quelle caractéristique des ondes P permet d'orienter vers ce diagnostic plutôt que vers une dysfonction sinusale ?","max":1,"options":["Ondes P régulières à fréquence normale, plus nombreuses que les QRS","Ondes P trop lentes ou inexistantes","Onde P rétrograde négative en D2","Ondes P absentes avec tracé plat","Pauses sinusales itératives","Ondes P de morphologie variable d'un cycle à l'autre","Ondes P bloquées de façon totalement aléatoire","Absence totale d'activité atriale identifiable"],"correct":[0],"explanation":"Algorithme devant une bradycardie (fig. 15.27, p. 389) : regarder les P. Régulières à fréquence normale (ou tachycardes : FA, flutter) et plus nombreuses que les QRS → BAV ; trop lentes ou inexistantes → dysfonction sinusale. Les pauses sinusales, le tracé plat (asystole) et la P' rétrograde négative en D2 de l'échappement jonctionnel sont des aspects de dysfonction sinusale (p. 387-388)."},{"stem":"Compte tenu du tableau clinique et électrique, quelles affirmations sont exactes ?","max":2,"options":["Il s'agit probablement d'un bloc atrioventriculaire de haut degré ou complet","Une indication de pacemaker doit être discutée en l'absence de cause réversible","Le traitement de première intention est un bêtabloquant","Il n'y a aucune urgence à explorer ce trouble","Une origine fonctionnelle par hypertonie vagale explique toujours ce tableau chez le sujet âgé","Une cause médicamenteuse bradycardisante doit être recherchée mais ne change pas la prise en charge","Le monitorage ECG n'est pas indiqué dans ce contexte","Aucun bilan ionique n'est nécessaire"],"correct":[0,1],"explanation":"P à 75 bpm dissociées de QRS à 38 bpm = BAV de haut degré ou complet, ici symptomatique (lipothymies). En l'absence de cause réversible (médicament bradycardisant, trouble ionique comme l'hyperkaliémie, p. 408), une indication de pacemaker se discute : le Collège l'indique pour les BAV infrahissiens même sans symptôme et pour les bradycardies symptomatiques (p. 412). Un bêtabloquant aggraverait la bradycardie ; le monitorage ECG est indiqué en urgence (p. 414) ; la cause médicamenteuse, si elle est retrouvée, change la conduite."}],"src":"p. 385-389"},{"id":"231-kfp-03","type":"KFP","rank":"A","objective":"231-obj-05","difficulty":2,"scenario":"Un homme de 62 ans, hypertendu depuis quinze ans et mal suivi, consulte pour un bilan cardiologique systématique. L'ECG montre une onde S en V1 à 22 mm, une onde R en V5 à 20 mm, une onde T négative en D1, aVL et V6, et un discret sus-décalage du segment ST en V1-V2.","questions":[{"stem":"Quel diagnostic évoquez-vous en priorité devant ce tracé ?","max":1,"options":["Hypertrophie ventriculaire gauche avec anomalies secondaires de la repolarisation","Syndrome coronarien aigu du territoire antérieur","Péricardite aiguë","Bloc de branche gauche isolé","Embolie pulmonaire","Hyperkaliémie","Torsade de pointes","Fibrillation ventriculaire"],"correct":[0],"explanation":"Grande amplitude des QRS précordiaux + T négatives latérales (D1, aVL, V6) chez un hypertendu = HVG avec anomalies SECONDAIRES de la repolarisation, dans les dérivations qui regardent le VG (p. 406). L'HTA en est la première cause (p. 407). Le petit sus-ST en V1-V2 est un piège classique de l'HVG (p. 406), pas un SCA ; une péricardite donnerait un sus-ST diffus avec PQ sous-décalé (p. 409), une hyperkaliémie des T amples et pointues (p. 408)."},{"stem":"Quel indice, calculé à partir des amplitudes mesurées, permet de retenir ce diagnostic ?","max":1,"options":["L'indice de Sokolow (onde S en V1 ou V2 + onde R en V5 ou V6), supérieur à 35 mm","La durée du QRS supérieure à 120 ms","Un intervalle PR raccourci inférieur à 120 ms","Un axe du QRS entre -30° et +90°","Un rapport R/S supérieur à 1 en V1","La présence d'une onde delta","Un intervalle QT allongé","Une onde P biphasique en V1"],"correct":[0],"explanation":"Sokolow = S en V1 ou V2 + R en V5 ou V6, normal < 35 mm (p. 406) ; ici 22 + 20 = 42 mm (fig. 15.53 : HVG à 40 mm). Le QRS de l'HVG reste souvent < 120 ms (p. 406) ; un PR court et une onde delta évoquent une préexcitation (p. 410) ; un axe entre -30 et +90° est normal (p. 375)."},{"stem":"Concernant les pièges d'interprétation de ce tracé, quelles affirmations sont exactes ?","max":3,"options":["Le sus-décalage en V1-V2 peut mimer à tort un syndrome coronarien aigu (pseudonécrose)","L'hypertrophie ventriculaire gauche électrique peut donner un aspect QS trompeur en V1-V2","Ce tracé impose systématiquement une coronarographie en urgence","Le rétrécissement aortique est l'étiologie la plus fréquente de l'HVG, avant l'HTA","L'HTA est l'étiologie la plus fréquente de l'hypertrophie ventriculaire gauche","Une onde T négative dans ce contexte est toujours synonyme d'ischémie aiguë","Le diagnostic d'HVG élimine formellement toute coronaropathie associée","L'indice de Sokolow n'a aucune valeur diagnostique dans l'HVG"],"correct":[0,1,4],"explanation":"Une HVG électrique importante peut donner en V1-V2 un aspect QS (pseudonécrose) et/ou un sus-ST qui miment une séquelle d'infarctus ou un SCA (p. 406-407) : l'HVG marquée figure parmi les diagnostics différentiels du sus-ST (p. 412). Ce n'est ni une indication systématique de coronarographie, ni une T forcément ischémique, ni une preuve d'absence de coronaropathie. Ordre des étiologies : HTA puis rétrécissement aortique (p. 407). Sokolow = bon marqueur d'HVG (points clés, p. 415)."}],"src":"p. 406-407"},{"id":"231-kfp-04","type":"KFP","rank":"B","objective":"231-obj-21","difficulty":2,"scenario":"Une femme de 70 ans, traitée par fluoxétine et hydrochlorothiazide, consulte pour une asthénie profonde. Le ionogramme sanguin retrouve une kaliémie à 2,8 mmol/L. L'ECG montre un allongement de l'intervalle QT, une onde U visible après l'onde T, et des ondes T aplaties diffuses.","questions":[{"stem":"Quel trouble ionique explique le mieux ces anomalies électrocardiographiques ?","max":1,"options":["Hypokaliémie","Hyperkaliémie","Hypercalcémie","Hypocalcémie","Hypermagnésémie","Hypernatrémie","Hyponatrémie isolée","Acidose métabolique isolée"],"correct":[0],"explanation":"T aplaties diffuses, onde U et QT allongé (sans élargissement du QRS) = hypokaliémie (p. 408), ici confirmée à 2,8 mmol/L (thiazidique). L'hyperkaliémie donnerait des T amples pointues, un PR long et un QRS large (p. 408) ; l'hypocalcémie allonge aussi le QT (p. 404) mais n'explique pas l'onde U et les T plates décrites ici. Piège : ne pas inclure l'onde U dans la mesure du QT (p. 408)."},{"stem":"Quel trouble du rythme grave ce contexte fait-il craindre en priorité ?","max":1,"options":["Torsade de pointes","Flutter atrial typique","Bloc de branche droit isolé","Extrasystole atriale isolée","Tachycardie sinusale","Rythme jonctionnel accéléré","Hémibloc antérieur gauche isolé","Bloc atrioventriculaire du 1er degré isolé"],"correct":[0],"explanation":"Le QT long hypokaliémique expose à la torsade de pointes, TV polymorphe qui peut s'arrêter seule ou dégénérer en FV (p. 403) ; l'hypokaliémie expose aussi aux ESV, TV et FV (p. 408). Les autres propositions (bloc de branche, hémibloc, BAV1, ESA isolée) ne sont pas des complications attendues de l'hypokaliémie dans le Collège. Ici le risque est majoré par la fluoxétine (psychotrope allongeant le QT, p. 404)."},{"stem":"Quels éléments de la prise en charge sont appropriés dans ce contexte ?","max":3,"options":["Correction de l'hypokaliémie","Réévaluation des médicaments allongeant le QT, notamment la fluoxétine","Poursuite du traitement bradycardisant sans aucune modification","Accélération de la fréquence cardiaque en cas de torsade de pointes avérée","Absence de nécessité de surveillance ECG particulière","Introduction d'un antiarythmique allongeant le QT en première intention","Arrêt de toute surveillance après la seule correction ionique","Contre-indication formelle à toute perfusion de magnésium"],"correct":[0,1,3],"explanation":"Devant un QT long : vérifier les médicaments et le ionogramme pour corriger et prévenir la mort subite (p. 404). Prise en charge : corriger les troubles ioniques (hypokaliémie, mais aussi hypocalcémie et hypomagnésémie qui allongent le QT), arrêter les médicaments allongeant le QT (ici la fluoxétine, psychotrope), accélérer la FC en cas de torsade (p. 404). Un bradycardisant ou un antiarythmique allongeant le QT aggraverait le risque (bradycardie extrême = cause de QT long)."}],"src":"p. 408-409"},{"id":"231-tcs-01","type":"TCS","rank":"A","objective":"231-obj-18","difficulty":3,"vignette":"Un homme de 68 ans, aux antécédents d'infarctus du myocarde ancien, est admis pour une tachycardie régulière à QRS larges à 160 bpm, bien tolérée sur le plan hémodynamique.","items":[{"hypothesis":"Si vous pensiez à une tachycardie ventriculaire","newInfo":"et que vous constatez une dissociation ventriculo-atriale, avec davantage de QRS que d'ondes P","panel":[0,0,1,2,12],"explanation":"Plus de QRS que d'ondes P : la tachycardie ne peut venir que du ventricule, c'est un argument de CERTITUDE de TV (encadré 15.2, p. 400 ; fig. 15.42 : 13 QRS pour 9 P). À ne pas confondre avec la dissociation du BAV complet, où il y a plus de P que de QRS (p. 400)."},{"hypothesis":"Si vous pensiez à une tachycardie ventriculaire","newInfo":"et que vous constatez des complexes de fusion intercalés dans le tracé","panel":[0,0,1,3,11],"explanation":"Le complexe de fusion (QRS intermédiaire) naît de la compétition entre l'activation par la TV et l'influx sinusal ; il n'existe que s'il y a dissociation ventriculoatriale : argument de certitude de TV (p. 400-401). La capture, elle, donne un QRS fin précédé d'une P."},{"hypothesis":"Si vous pensiez à une tachycardie supraventriculaire avec bloc de branche fonctionnel","newInfo":"et que vous constatez une concordance négative des QRS (QS) de V1 à V6","panel":[10,3,1,1,0],"explanation":"Une concordance négative (QS de V1 à V6) est un argument EN FAVEUR d'une TV (p. 400) : un bloc de branche, même fonctionnel, garde une morphologie habituelle (V1 positif en BBD, négatif en BBG avec aspect inverse en V6, p. 381). L'hypothèse TSV + bloc est donc affaiblie, sans certitude (la certitude = dissociation, capture, fusion)."},{"hypothesis":"Si vous pensiez à une tachycardie ventriculaire","newInfo":"et que le patient présente une cardiopathie ischémique séquellaire connue","panel":[0,1,2,9,3],"explanation":"La plupart des TV sont favorisées par une cardiopathie : la réentrée autour d'une zone de fibrose (infarctus) est le mécanisme le plus fréquent (p. 399) ; la cardiopathie est donc un argument en faveur de la TV (p. 400), mais pas de certitude à elle seule (il existe des TV sur cœur sain par automatisme anormal, p. 398)."}],"src":"p. 398-402"},{"id":"231-tcs-02","type":"TCS","rank":"B","objective":"231-obj-10","difficulty":3,"vignette":"Une femme de 75 ans consulte pour des lipothymies répétées. Son ECG per-critique révèle une fréquence cardiaque à 42 bpm.","items":[{"hypothesis":"Si vous pensiez à une dysfonction sinusale","newInfo":"et que vous constatez des ondes P régulières à une fréquence de 80 bpm, plus nombreuses que les QRS","panel":[9,4,1,1,0],"explanation":"Dans la dysfonction sinusale, les P sont trop lentes ou inexistantes (pauses, échappement) ; des P régulières à 80 bpm, plus nombreuses que les QRS, prouvent que le nœud sinusal fonctionne et orientent vers un BAV (algorithme fig. 15.27, p. 389) : l'hypothèse de dysfonction sinusale est fortement affaiblie."},{"hypothesis":"Si vous pensiez à un bloc atrioventriculaire","newInfo":"et que vous constatez ce même tableau (ondes P régulières à 80 bpm, plus nombreuses que les QRS)","panel":[0,0,1,3,11],"explanation":"P régulières à fréquence normale, plus nombreuses que les QRS = le problème est le passage au ventricule : BAV (p. 389). Dans le BAV, les ondes P sont régulières et de fréquence normale (fig. 15.20, p. 385) ; reste à préciser le degré (2 ou 3) et le siège (QRS fins ou larges)."},{"hypothesis":"Si vous pensiez à un bloc atrioventriculaire de siège nodal (suprahissien)","newInfo":"et que l'échappement ventriculaire observé est à QRS fins, régulier et lent","panel":[0,1,2,9,3],"explanation":"Un échappement à QRS fins, régulier et lent traduit un bloc nodal (suprahissien) : la commande ventriculaire naît au-dessus de la bifurcation et emprunte le réseau normal (fig. 15.23, p. 387). Des QRS larges orienteraient vers un siège infrahissien (pacemaker même sans symptôme, p. 412)."},{"hypothesis":"Si vous pensiez à une dysfonction sinusale","newInfo":"et qu'une pause est observée, de durée égale au double de l'intervalle PP normal, sans aucune onde P pendant la pause","panel":[0,0,1,2,12],"explanation":"Pause par absence complète du complexe P-QRS-T, égale au double de l'intervalle PP = bloc sinoatrial du 2e degré (fig. 15.24, p. 387), forme de dysfonction sinusale. Dans un BAV, la P serait au contraire présente mais non suivie de QRS (p. 385)."}],"src":"p. 387-389"},{"id":"231-tcs-03","type":"TCS","rank":"A","objective":"231-obj-13","difficulty":3,"vignette":"Un homme de 60 ans, sans antécédent notable, consulte pour des palpitations. Son ECG montre une tachycardie à QRS fins à 140 bpm.","items":[{"hypothesis":"Si vous pensiez à une fibrillation atriale","newInfo":"et que les intervalles RR sont irrégulièrement irréguliers, sans onde P identifiable","panel":[0,0,1,2,12],"explanation":"RR irrégulièrement irréguliers (non multiples d'une valeur commune) sans P identifiable, à QRS fins = FA (p. 392) ; c'est même le seul diagnostic d'une tachycardie complètement irrégulière à QRS fins (points clés, p. 415). Diagnostic différentiel : ESA (p. 405)."},{"hypothesis":"Si vous pensiez à un flutter atrial","newInfo":"et que l'activité atriale est monomorphe à 300 bpm en dents de scie, avec une conduction ventriculaire régulière à 150 bpm","panel":[0,0,1,2,12],"explanation":"Activité atriale monomorphe à 300 bpm en dents de scie (boucle de réentrée permanente) avec conduction 2/1 régulière à 150 bpm = forme usuelle du flutter (p. 393-394). Si les F sont cachées, une manœuvre vagale les démasque (p. 395)."},{"hypothesis":"Si vous pensiez à une fibrillation atriale","newInfo":"et que la manœuvre vagale démasque une activité atriale organisée en dents de scie, sans jamais arrêter la tachycardie","panel":[9,4,1,1,0],"explanation":"La FA a une activité atriale anarchique (mailles ou trémulation) ; des ondes organisées en dents de scie démasquées par la manœuvre vagale, sans arrêt de la tachycardie, signent un flutter (p. 393-395) : la manœuvre ne fait que ralentir transitoirement la réponse ventriculaire."},{"hypothesis":"Si vous pensiez à une tachycardie jonctionnelle","newInfo":"et que la manœuvre vagale interrompt brutalement la tachycardie, avec retour en rythme sinusal","panel":[0,0,1,2,12],"explanation":"La manœuvre vagale crée un bloc AV transitoire : une tachycardie dont le circuit passe par le NAV (réentrée intranodale ou par voie accessoire) s'arrête alors brutalement, avec retour en rythme sinusal (p. 390, 397). Un flutter ou une FA ne seraient que ralentis transitoirement, l'activité atriale persistant."}],"src":"p. 390-395"},{"id":"231-tcs-04","type":"TCS","rank":"B","objective":"231-obj-25","difficulty":3,"vignette":"Une femme de 28 ans, connue porteuse d'un syndrome de Wolff-Parkinson-White, consulte pour des palpitations très rapides et irrégulières.","items":[{"hypothesis":"Si vous pensiez à une fibrillation atriale conduite par la voie accessoire (« super-Wolff »)","newInfo":"et que l'ECG montre une tachycardie irrégulière à QRS larges de largeur variable","panel":[0,0,1,2,12],"explanation":"La voie accessoire n'a pas la propriété décrémentielle du NAV : en FA, elle filtre mal les influx atriaux, d'où une tachycardie irrégulière, extrêmement rapide, à QRS larges de taille variable « en accordéon » (super-Wolff), pouvant dégénérer en FV (p. 411)."},{"hypothesis":"Si vous pensiez à ce diagnostic (super-Wolff)","newInfo":"et que vous envisagiez d'administrer de l'adénosine intraveineuse pour ralentir la fréquence ventriculaire","panel":[9,4,1,1,0],"explanation":"Bloquer le NAV force l'influx à passer uniquement par la voie accessoire : le Collège interdit de le faire en cas de FA (p. 410) et cite le super-Wolff comme contre-indication à l'adénosine, seule autre avec l'asthme selon la légende p. 411 (l'encadré p. 390 cite aussi l'hypotension). L'idée d'administrer de l'adénosine est donc à rejeter."},{"hypothesis":"Si vous pensiez à une tachycardie jonctionnelle par réentrée sur la voie accessoire (rythme réciproque)","newInfo":"et que le tracé en dehors des crises retrouve un PR court avec un empâtement du pied du QRS","panel":[0,1,2,9,3],"explanation":"Hors crise, PR court (< 120 ms) + empâtement du pied du QRS (onde delta) = préexcitation par voie accessoire (p. 410) : c'est le substrat de la tachycardie par rythme réciproque (réentrée par le faisceau de Kent, p. 396). Argument en faveur du terrain, sans prouver le mécanisme de la crise actuelle."}],"src":"p. 410-411"},{"id":"231-kfp-51","type":"KFP","rank":"B","objective":"231-obj-06","difficulty":2,"scenario":"Un homme de 74 ans est amené aux urgences pour une perte de connaissance brève sans prodrome, survenue en position assise, avec reprise de conscience immédiate. À l'arrivée, il est asymptomatique, PA 135/80 mmHg. L'ECG montre un rythme sinusal à 72 bpm, un PR à 180 ms, des QRS à 140 ms avec un aspect RsR' en V1 et une onde S traînante en V6, ainsi qu'un axe du QRS à –60° avec D2 négatif.","questions":[{"stem":"Quelles anomalies retenez-vous sur cet ECG ?","max":3,"options":["Bloc de branche droit complet","Hémibloc antérieur gauche","Bloc bifasciculaire","Bloc de branche gauche complet","Hémibloc postérieur gauche","BAV du 1er degré","BAV du 2e degré Mobitz 2","Rythme jonctionnel"],"correct":[0,1,2],"explanation":"QRS > 120 ms avec RsR' en V1 et S traînante en V6 = BBD complet (p. 378) ; axe au-delà de -30° avec D2 négatif = HBAG (p. 382) ; BBD + HBAG = bloc bifasciculaire (p. 383). Le PR à 180 ms est normal (120-200 ms) : pas de BAV1 ; un BBG donnerait un V1 négatif et un notch en V6 (p. 380) ; un HBPG un axe > +90° (p. 382)."},{"stem":"Quelle conduite adoptez-vous ?","max":2,"options":["Hospitalisation en cardiologie","Surveillance par télémétrie","Retour à domicile, le rythme étant sinusal","Test à l'adénosine IV","Compression carotidienne diagnostique","Implantation d'un défibrillateur en urgence","Prescription d'un bêtabloquant","Holter ambulatoire de 24 h à la place de l'hospitalisation"],"correct":[0,1],"explanation":"Avec deux fascicules atteints, la troisième branche peut dysfonctionner par intermittence : risque de BAV complet infrahissien (syncope, voire mort subite). D'où la règle : syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie (p. 383). Le défibrillateur traite les TV/FV, pas ce tableau (p. 413) ; adénosine et compression carotidienne bloquent le NAV et n'ont pas de place ici ; un Holter ambulatoire ne remplace pas la surveillance hospitalière."},{"stem":"Au cours de la surveillance, quels aspects ECG justifieraient l'implantation d'un pacemaker même en l'absence de symptôme ?","max":2,"options":["BAV du 2e degré Mobitz 2","BAV du 3e degré","BAV du 1er degré isolé à 220 ms","Bradycardie sinusale asymptomatique à 55 bpm","Extrasystoles atriales isolées","Hémibloc antérieur gauche isolé"],"correct":[0,1],"explanation":"Les BAV infrahissiens (Mobitz 2 et BAV3) indiquent un pacemaker même sans symptôme (p. 412). Un BAV1 isolé (PR fixe > 200 ms, sans P bloquée) n'est pas cité comme indication ; la bradycardie sinusale ne relève du pacemaker que si elle est symptomatique (p. 412) ; un hémibloc isolé montre une atteinte débutante avec faible risque de BAV infrahissien (p. 383)."}],"src":"p. 378-383, 412"},{"id":"231-kfp-52","type":"KFP","rank":"B","objective":"231-obj-23","difficulty":2,"scenario":"Un homme de 32 ans, sans antécédent ni facteur de risque cardiovasculaire, consulte aux urgences pour une douleur thoracique évoluant depuis 24 heures. L'ECG montre un rythme sinusal à 95 bpm et un sus-décalage du segment ST dans la plupart des dérivations des deux plans, sans onde Q.","questions":[{"stem":"Quelles caractéristiques ECG sont en faveur d'une péricardite aiguë en phase initiale ?","max":4,"options":["Sus-décalage du ST diffus","Sus-décalage du ST concave vers le haut","Absence d'image en miroir","Sous-décalage du segment PQ (PR)","Onde de Pardee avec sous-décalage en miroir","Sus-décalage limité à D2, D3, aVF avec sous-décalage en D1 et aVL","Rabotage de l'onde R en V2-V3","Allongement du PR à 240 ms"],"correct":[0,1,2,3],"explanation":"Phase 1 de la péricardite : sus-ST diffus, concordant, concave vers le haut, sans miroir, sous-décalage de PQ, microvoltage (p. 409). À l'inverse, une onde de Pardee avec miroir, un sus-ST limité à un territoire (D2, D3, aVF avec miroir en D1-aVL) ou un rabotage de R en V2-V3 orientent vers un SCA (p. 411-412). Piège : l'absence de miroir peut aussi se voir dans un SCA ST+ (p. 409)."},{"stem":"Parmi les causes suivantes, lesquelles font partie des cinq étiologies de sus-décalage du ST citées par le cours ?","max":5,"options":["SCA avec sus-décalage du ST","Anévrisme ventriculaire","Repolarisation précoce","Angor de Prinzmetal","Péricardite","Hypokaliémie","Hypertrophie atriale gauche","Extrasystoles atriales"],"correct":[0,1,2,3,4],"explanation":"Les cinq étiologies de sus-ST à connaître : SCA ST+ (Pardee + miroir), anévrisme ventriculaire (sus-ST qui persiste après l'infarctus), repolarisation précoce (inférolatérale), angor de Prinzmetal (spasme), péricardite (diffus, concave, sans miroir) (p. 412). L'hypokaliémie donne au contraire un sous-décalage du ST avec T plate (p. 408) ; diagnostics différentiels du sus-ST : BBG/stimulation et HVG marquée (p. 412)."},{"stem":"Le diagnostic de péricardite aiguë est retenu. Quelles évolutions ECG attendez-vous ensuite ?","max":3,"options":["Ondes T plates partout avec ST isoélectrique","Ondes T négatives persistantes","Retour progressif à la normale","Apparition d'ondes Q de nécrose","Apparition d'une onde de Pardee","Apparition d'une onde delta","BAV complet","Aspect S1Q3T3"],"correct":[0,1,2],"explanation":"Évolution classique en 4 phases : phase 1 brève (sus-ST), phase 2 (T plates partout, ST isoélectrique), phase 3 (T négatives persistantes), phase 4 (retour progressif à la normale) (p. 409). Ondes Q de nécrose et onde de Pardee appartiennent au SCA (p. 412), l'onde delta à la préexcitation (p. 410), le S1Q3T3 à l'embolie pulmonaire (p. 407)."}],"src":"p. 409, 411-412"},{"id":"231-tcs-51","type":"TCS","rank":"B","objective":"231-obj-24","difficulty":3,"vignette":"Un homme de 55 ans consulte aux urgences pour une douleur thoracique. L'ECG montre un sus-décalage du segment ST dans plusieurs dérivations.","items":[{"hypothesis":"Si vous pensiez à un SCA avec sus-décalage du ST,","newInfo":"et que vous constatez un sous-décalage du ST en miroir dans les dérivations opposées,","panel":[0,0,1,4,10],"explanation":"Le sus-ST indique le territoire de la coronaire occluse et le miroir (sous-décalage) le confirme : on traque le sus-décalage puis son miroir (p. 411). Sus-ST typé onde de Pardee avec miroir = SCA ST+ (p. 412) : hypothèse fortement renforcée."},{"hypothesis":"Si vous pensiez à un SCA avec sus-décalage du ST,","newInfo":"et que le sus-décalage est diffus, concave vers le haut, sans miroir, avec un sous-décalage de PQ,","panel":[7,6,2,0,0],"explanation":"Sus-ST diffus, concave vers le haut, sans miroir, avec PQ sous-décalé = phase 1 de péricardite (p. 409) : le SCA devient moins probable, sans être exclu, car l'image en miroir peut manquer dans un SCA ST+ (encadré « Attention », p. 409)."},{"hypothesis":"Si vous pensiez à un SCA avec sus-décalage du ST,","newInfo":"et que le sus-décalage n'intéresse que V1-V2 chez un patient présentant une HVG électrique marquée,","panel":[2,8,4,1,0],"explanation":"Une HVG marquée peut donner un sus-décalage en V1-V2 (et un sous-décalage latéral) : c'est un diagnostic différentiel du sus-ST (p. 412 ; fig. 15.53 p. 407). Un sus-ST limité à V1-V2 dans ce contexte affaiblit l'hypothèse de SCA, sans l'exclure (contexte clinique)."},{"hypothesis":"Si vous pensiez à un SCA avec sus-décalage du ST,","newInfo":"et que le sus-décalage, localisé en D2, D3 et aVF, englobe l'onde T (onde de Pardee),","panel":[0,0,1,6,8],"explanation":"Un sus-ST englobant l'onde T (onde de Pardee) sur des dérivations adjacentes d'un même territoire (ici inférieur : D2, D3, aVF) est typique du SCA ST+ (p. 412) ; seuil : ≥ 1 mm hors V1-V3, sur ≥ 2 dérivations adjacentes."}],"src":"p. 406, 409, 411-412"},{"id":"231-tcs-52","type":"TCS","rank":"A","objective":"231-obj-21","difficulty":2,"vignette":"Un homme de 70 ans, insuffisant rénal chronique, est hospitalisé pour une asthénie. Un ECG est réalisé avant l'obtention du ionogramme sanguin.","items":[{"hypothesis":"Si vous pensiez à une hyperkaliémie,","newInfo":"et que l'ECG montre des ondes T amples, pointues et symétriques,","panel":[0,0,0,4,11],"explanation":"T ample, pointue et symétrique = premier signe listé de l'hyperkaliémie (p. 408) ; les T peuvent être géantes alors que les QRS ne sont pas encore larges (fig. 15.55, p. 409) : l'ECG oriente avant le ionogramme."},{"hypothesis":"Si vous pensiez à une hyperkaliémie,","newInfo":"et que l'ECG montre des ondes T plates avec sous-décalage du ST et une onde U,","panel":[10,4,1,0,0],"explanation":"T plates, sous-décalage du ST et onde U sont les signes de l'HYPOkaliémie (avec QT long et QRS normal) (p. 408) : l'hypothèse d'hyperkaliémie est fortement affaiblie."},{"hypothesis":"Si vous pensiez à une hyperkaliémie,","newInfo":"et que l'ECG montre un allongement du PR et un élargissement des QRS,","panel":[0,0,1,7,7],"explanation":"L'hyperkaliémie ralentit la conduction : allongement du PR et élargissement du QRS font partie de ses signes (p. 408), à côté de la T ample et pointue ; elle peut aller jusqu'au BAV ou à la TV."},{"hypothesis":"Si vous pensiez à une hyperkaliémie,","newInfo":"et que l'ECG montre un échappement jonctionnel par dysfonction sinusale,","panel":[0,1,4,7,3],"explanation":"La dysfonction sinusale (ici avec échappement jonctionnel, fig. 15.55 p. 409) fait partie des troubles rythmiques de l'hyperkaliémie (p. 408), mais n'est pas spécifique (elle a d'autres causes) : renforcement modéré."}],"src":"p. 408"}],"trees":[{"id":"231-tree-01","title":"Vérifier qu'un ECG est normal","rank":"A","objective":"231-obj-01","intro":"md La normalité d'un ECG s'affirme par une lecture systématique en quatre temps : rythme, conduction, repolarisation, morphologie.","root":"n1","nodes":{"n1":{"type":"question","text":"Rythme sinusal : onde P positive en D1/D2, un QRS après chaque P et une P avant chaque QRS ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"e1"}]},"n2":{"type":"question","text":"Fréquence entre 60 et 100 bpm ?","note":"md FC = 300 / nombre de grands carreaux séparant deux QRS.","options":[{"label":"Oui","to":"n3"},{"label":"< 60 bpm","to":"e2"},{"label":"> 100 bpm","to":"e3"}]},"n3":{"type":"question","text":"Conduction normale : P < 120 ms, PR 120–200 ms, QRS fins 70–110 ms, axe entre -30° et +90° ?","options":[{"label":"Oui","to":"n4"},{"label":"Non","to":"e4"}]},"n4":{"type":"question","text":"Repolarisation normale : point J et ST isoélectriques, T positive sauf aVR/V1, QT < 450 ms ?","options":[{"label":"Oui","to":"n5"},{"label":"Non","to":"e5"}]},"n5":{"type":"action","text":"Vérifier la morphologie : indice de Sokolow < 35 mm, transition R/S progressive de V1 à V6, absence d'onde Q de nécrose.","to":"e6"},"e1":{"type":"end","tone":"warn","text":"Rythme non sinusal : analyser le trouble du rythme ou de conduction avant de conclure."},"e2":{"type":"end","tone":"info","text":"Bradycardie : rechercher une dysfonction sinusale ou un bloc atrioventriculaire."},"e3":{"type":"end","tone":"info","text":"Tachycardie : différencier tachycardie sinusale et trouble du rythme supraventriculaire."},"e4":{"type":"end","tone":"warn","text":"Anomalie de conduction : suspecter un bloc de branche, un hémibloc ou un trouble atrioventriculaire."},"e5":{"type":"end","tone":"warn","text":"Anomalie de repolarisation : orienter vers ischémie, péricardite, hypertrophie ou trouble ionique."},"e6":{"type":"end","tone":"ok","text":"ECG normal si la morphologie est également sans anomalie."}},"src":"p. 377-378"},{"id":"231-tree-02","title":"Analyser une bradycardie","rank":"A","objective":"231-obj-10","intro":"md Devant une fréquence des QRS inférieure à 50 bpm, seules deux structures peuvent être en cause : le nœud sinusal ou le nœud atrioventriculaire.","root":"n1","nodes":{"n1":{"type":"question","text":"Aspect des ondes P sur le tracé ?","options":[{"label":"Régulières, fréquence normale (ou tachycardes type FA/flutter), plus nombreuses que de QRS","to":"n2"},{"label":"Trop lentes ou absentes","to":"n3"}]},"n2":{"type":"action","text":"Le passage de l'oreillette au ventricule est en cause : bloc atrioventriculaire (BAV).","to":"n2b"},"n2b":{"type":"question","text":"QRS d'échappement fins ou larges ?","note":"md Un échappement à QRS fins traduit un bloc nodal (suprahissien) ; un échappement large oriente vers un bloc infrahissien.","options":[{"label":"Fins","to":"e1"},{"label":"Larges","to":"e2"}]},"n3":{"type":"action","text":"Le nœud sinusal est en cause : dysfonction sinusale.","to":"n3b"},"n3b":{"type":"question","text":"Pause avec disparition complète du complexe P-QRS-T (multiple de l'intervalle PP) ?","options":[{"label":"Oui","to":"e3"},{"label":"Non, échappement jonctionnel sans onde P visible devant le QRS","to":"e4"}]},"e1":{"type":"end","tone":"info","text":"BAV probablement suprahissien (nodal), mieux toléré."},"e2":{"type":"end","tone":"danger","text":"BAV probablement infrahissien : risque de syncope, voire de mort subite ; discuter un pacemaker."},"e3":{"type":"end","tone":"warn","text":"(rang B) Bloc sino-atrial du 2e degré : pause correspondant au double de l'intervalle PP normal."},"e4":{"type":"end","tone":"warn","text":"Dysfonction sinusale marquée avec échappement jonctionnel (activité atriale parfois rétrograde, cachée dans le segment ST)."}},"src":"p. 388-389"},{"id":"231-tree-03","title":"Décrypter une tachycardie","rank":"A","objective":"231-obj-12","intro":"md La démarche associe l'analyse de la régularité et de la largeur des QRS aux manœuvres vagales ou à l'adénosine.","root":"n1","nodes":{"n1":{"type":"question","text":"QRS réguliers ou irréguliers ?","options":[{"label":"Irréguliers","to":"e1"},{"label":"Réguliers","to":"n2"}]},"n2":{"type":"question","text":"QRS fins ou larges ?","options":[{"label":"Larges","to":"n3"},{"label":"Fins","to":"n4"}]},"n3":{"type":"question","text":"Tolérance hémodynamique mauvaise ?","note":"md Toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire.","options":[{"label":"Oui","to":"e2"},{"label":"Non","to":"n3b"}]},"n3b":{"type":"action","text":"Rechercher une dissociation ventriculo-atriale, des complexes de fusion/capture ou une déviation extrême en aVR.","to":"e3"},"n4":{"type":"question","text":"Tolérance hémodynamique mauvaise ?","options":[{"label":"Oui","to":"e2"},{"label":"Non","to":"n5"}]},"n5":{"type":"action","text":"Réaliser des manœuvres vagales, puis de l'adénosine IV en cas d'échec. (rang B) Adénosine contre-indiquée en cas d'asthme, d'hypotension ou de FA sur voie accessoire.","to":"n6"},"n6":{"type":"question","text":"Effet obtenu ?","options":[{"label":"Démasque une activité atriale sous-jacente","to":"e4"},{"label":"Arrête brutalement la tachycardie","to":"e5"}],"note":"md Dans l'algorithme du livre, l'absence d'effet correspond à la tachycardie ventriculaire (à QRS larges), qui ne dépend pas du NAV."},"e1":{"type":"end","tone":"warn","text":"Fibrillation atriale (diagnostic différentiel : extrasystoles atriales)."},"e2":{"type":"end","tone":"danger","text":"Cardioversion électrique externe en urgence."},"e3":{"type":"end","tone":"warn","text":"Tachycardie ventriculaire jusqu'à preuve du contraire."},"e4":{"type":"end","tone":"info","text":"Tachycardie atriale (sinusale, flutter ou TAF) : le ralentissement du passage au ventricule démasque l'activité atriale, sans arrêter la tachycardie."},"e5":{"type":"end","tone":"ok","text":"Tachycardie jonctionnelle (réentrée dépendante du NAV, ex. maladie de Bouveret)."}},"src":"p. 390, 392, 398-400, 405"},{"id":"231-tree-04","title":"Devant un sus-décalage du segment ST","rank":"A","objective":"231-obj-24","intro":"md Cinq étiologies principales partagent un sus-décalage de ST ; deux diagnostics différentiels y ressemblent sans en être.","root":"n1","nodes":{"n1":{"type":"question","text":"Sus-décalage diffus, concave vers le haut, sans miroir, avec sous-décalage de PQ ?","options":[{"label":"Oui","to":"e1"},{"label":"Non","to":"n2"}]},"n2":{"type":"question","text":"Sus-décalage systématisé à un territoire, avec miroir (onde de Pardee) ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n4"}]},"n3":{"type":"question","text":"Douleur thoracique aiguë avec contexte évocateur d'ischémie ?","options":[{"label":"Oui","to":"e2"},{"label":"Non, séquelle d'infarctus connue","to":"e3"},{"label":"Non, épisodes douloureux régressifs","to":"e4"}]},"n4":{"type":"question","text":"Sus-décalage dans les dérivations inféro-latérales, sujet jeune asymptomatique ?","options":[{"label":"Oui","to":"e5"},{"label":"Non","to":"n5"}]},"n5":{"type":"action","text":"Rechercher un bloc de branche gauche, une stimulation ventriculaire ou une hypertrophie ventriculaire gauche marquée.","to":"e6"},"e1":{"type":"end","tone":"info","text":"Péricardite aiguë (ne pas conclure à tort en cas de sus-décalage ischémique sans miroir visible)."},"e2":{"type":"end","tone":"danger","text":"Syndrome coronarien aigu avec sus-décalage du ST : prise en charge urgente."},"e3":{"type":"end","tone":"info","text":"Anévrisme ventriculaire (sus-décalage persistant sur séquelle marquée)."},"e4":{"type":"end","tone":"info","text":"Angor de Prinzmetal (spasme coronarien)."},"e5":{"type":"end","tone":"ok","text":"Repolarisation précoce, variante bénigne."},"e6":{"type":"end","tone":"warn","text":"Diagnostic différentiel : discordance appropriée d'un bloc de branche gauche/pacemaker, ou pseudonécrose d'une HVG sévère."}},"src":"p. 411-412"},{"id":"231-tree-05","title":"Poser l'indication d'un pacemaker devant un trouble de conduction","rank":"B","objective":"231-obj-08","intro":"md L'indication dépend du siège du trouble (nœud sinusal, nodal ou infrahissien) et de sa gravité potentielle.","root":"n1","nodes":{"n1":{"type":"question","text":"Bradycardie symptomatique par dysfonction sinusale, BAV2 Mobitz 1 ou bradycardie sinusale ?","options":[{"label":"Oui","to":"e1"},{"label":"Non","to":"n2"}]},"n2":{"type":"question","text":"BAV2 Mobitz 2 ou BAV3 (infrahissien) ?","options":[{"label":"Oui","to":"e2"},{"label":"Non","to":"n3"}]},"n3":{"type":"question","text":"Bloc bifasciculaire (BBD + hémibloc, ou BBG complet) avec syncope ?","options":[{"label":"Oui","to":"e3"},{"label":"Non","to":"e5"}]},"e1":{"type":"end","tone":"warn","text":"Indication de pacemaker (bradycardie symptomatique)."},"e2":{"type":"end","tone":"danger","text":"Indication de pacemaker même en l'absence de symptôme (BAV infrahissien)."},"e3":{"type":"end","tone":"danger","text":"Hospitalisation en cardiologie avec télémétrie : risque de BAV complet infrahissien (syncopes, voire mort subite)."},"e5":{"type":"end","tone":"ok","text":"Pas d'indication de pacemaker à ce stade ; surveillance du trouble de conduction."}},"src":"p. 383, 412-413"},{"id":"231-tree-06","title":"Conduite devant un QT allongé","rank":"B","objective":"231-obj-22","intro":"md L'allongement du QT expose à la torsade de pointes ; la démarche associe recherche de cause et correction en urgence si le trouble du rythme est déjà présent.","root":"n1","nodes":{"n1":{"type":"question","text":"QT corrigé (formule de Bazett) allongé au-delà des valeurs normales ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"e1"}]},"n2":{"type":"question","text":"Cause évidente retrouvée : médicament, hypokaliémie, hypocalcémie, hypomagnésémie, bradycardie extrême ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n4"}]},"n3":{"type":"action","text":"Corriger la cause : arrêt du médicament en cause, correction du trouble ionique.","to":"n5"},"n4":{"type":"action","text":"Évoquer un syndrome du QT long congénital ; avis spécialisé.","to":"n5"},"n5":{"type":"question","text":"Torsade de pointes ou fibrillation ventriculaire déjà survenue ?","options":[{"label":"Oui","to":"e2"},{"label":"Non","to":"e3"}]},"e1":{"type":"end","tone":"ok","text":"QT normal."},"e2":{"type":"end","tone":"danger","text":"Urgence : accélérer la fréquence cardiaque, corriger les troubles ioniques, arrêter tout médicament allongeant le QT."},"e3":{"type":"end","tone":"warn","text":"Surveillance rapprochée du QT et éviction des médicaments allongeant le QT pour prévenir une mort subite."}},"src":"p. 404"},{"id":"231-tree-07","title":"Diagnostiquer un bloc de branche","rank":"A","objective":"231-obj-06","intro":"md L'analyse suit un ordre fixe : rythme atrial, durée du QRS, aspect en V1 puis en V6.","root":"n1","nodes":{"n1":{"type":"question","text":"Rythme atrial déjà caractérisé (pour ne pas méconnaître une tachycardie supraventriculaire associée) ?","options":[{"label":"Oui","to":"n2"},{"label":"Non","to":"e1"}]},"n2":{"type":"question","text":"Durée du QRS > 120 ms ?","options":[{"label":"Oui","to":"n3"},{"label":"Non","to":"n2b"}]},"n2b":{"type":"question","text":"QRS entre 110 et 120 ms ?","options":[{"label":"Oui","to":"e2"},{"label":"Non","to":"e3"}]},"n3":{"type":"question","text":"En V1, QRS globalement positif (aspect RsR') ?","options":[{"label":"Oui","to":"e4"},{"label":"Non","to":"n3b"}]},"n3b":{"type":"question","text":"QRS globalement négatif en V1 (rS ou QS) avec notch en V6, D1, aVL ?","options":[{"label":"Oui","to":"e5"},{"label":"Non","to":"e6"}]},"e1":{"type":"end","tone":"info","text":"Rechercher d'abord une tachycardie supraventriculaire associée avant de conclure à un simple trouble de conduction."},"e2":{"type":"end","tone":"info","text":"Bloc incomplet de branche : anomalie de faible intérêt sémiologique."},"e3":{"type":"end","tone":"ok","text":"QRS de durée normale (70-110 ms) : pas de bloc de branche."},"e4":{"type":"end","tone":"warn","text":"Bloc de branche droit complet (confirmer l'aspect qRs traînant en V6)."},"e5":{"type":"end","tone":"warn","text":"Bloc de branche gauche complet."},"e6":{"type":"end","tone":"info","text":"Vérifier l'axe (hémibloc) et rechercher une association réalisant un bloc bifasciculaire."}},"src":"p. 378-381"}],"treatments":{"data":[{"id":"231-tx-01","rank":"B","class":"Manœuvres vagales","molecules":[],"context":"Premier geste diagnostique et parfois thérapeutique devant une tachycardie à QRS fins bien tolérée.","indications":["Tachycardie supraventriculaire régulière bien tolérée (diagnostic et/ou réduction)","Démasquer une activité atriale (flutter, tachycardie atriale focale) en cas de doute diagnostique"],"contraindications":["Compression carotidienne unilatérale contre-indiquée si athérome carotidien marqué ou souffle carotidien","Compression oculaire bilatérale non recommandée (risque de décollement de rétine chez le myope)"],"sideEffects":[],"monitoring":["Scope pendant la manœuvre"],"interactions":[],"pearls":["Manœuvre de Valsalva : expiration forcée à glotte fermée","Boire un grand verre d'eau froide","Utiles pour le diagnostic différentiel des tachycardies, pas seulement pour les traiter"],"src":"p. 390"},{"id":"231-tx-02","rank":"B","class":"Ralentisseur du NAV d'action flash (adénosine)","molecules":["Adénosine"],"context":"Utilisée en cas d'échec des manœuvres vagales pour créer un bloc atrioventriculaire transitoire.","indications":["Tachycardie supraventriculaire non élucidée par les manœuvres vagales","Réduction d'une tachycardie jonctionnelle par réentrée dépendante du NAV"],"contraindications":["Asthme (risque de bronchospasme intense, même chez le non-asthmatique)","Hypotension artérielle","Fibrillation atriale associée à une voie accessoire à conduction rapide (« super-Wolff »)"],"sideEffects":["Bronchospasme transitoire (rare)"],"monitoring":["Scope pendant l'injection"],"interactions":[],"pearls":["Administration en flash intraveineux","Durée d'effet d'une dizaine de secondes","Mécanisme vagomimétique via les récepteurs purinergiques"],"src":"p. 390, 411"},{"id":"231-tx-04","rank":"A","class":"Cardioversion électrique externe","molecules":[],"context":"Geste d'urgence devant une arythmie mal tolérée hémodynamiquement ou une fibrillation ventriculaire.","indications":["Fibrillation ventriculaire : geste à réaliser en priorité absolue avant tout autre","Tachycardie (régulière ou irrégulière, fine ou large) mal tolérée sur le plan hémodynamique"],"contraindications":[],"sideEffects":[],"monitoring":["Massage cardiaque en attendant la délivrance du choc électrique en cas de fibrillation ventriculaire"],"interactions":[],"pearls":[],"src":"p. 372, 405-406"},{"id":"231-tx-05","rank":"B","class":"Stimulateur cardiaque (pacemaker)","molecules":[],"context":"Traite les bradycardies symptomatiques et les BAV infrahissiens, même asymptomatiques.","indications":["Bradycardie symptomatique : dysfonction sinusale, BAV2 Mobitz 1, bradycardie sinusale","BAV infrahissien (Mobitz 2, BAV3), même en l'absence de symptôme"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Le spike de stimulation dure 0,4 à 1 ms, très court par rapport à tout signal physiologique","En cas de stimulation ventriculaire droite, le QRS est large avec un aspect de bloc de branche gauche"],"src":"p. 412-414"},{"id":"231-tx-06","rank":"B","class":"Défibrillateur implantable","molecules":[],"context":"Prévention de la mort subite par tachycardie ou fibrillation ventriculaire.","indications":["Risque de tachycardie ou de fibrillation ventriculaire"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Assure toujours aussi la fonction pacemaker, sauf modèle sous-cutané","Peut être associé à la resynchronisation (défibrillateur de resynchronisation)"],"src":"p. 412"},{"id":"231-tx-07","rank":"B","class":"Resynchronisation cardiaque","molecules":[],"context":"Corrige la désynchronisation des parois ventriculaires liée à un bloc de branche gauche complet évolutif.","indications":["Bloc de branche gauche complet contribuant à créer ou aggraver une insuffisance cardiaque"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":["Assure toujours la fonction pacemaker","Peut être associée à un défibrillateur"],"src":"p. 383, 412"},{"id":"231-tx-08","rank":"B","class":"Ablation par radiofréquence","molecules":[],"context":"Traitement curatif de certaines arythmies par réentrée, après confirmation lors d'une exploration électrophysiologique.","indications":["Flutter atrial (confirmation puis ablation de l'isthme cavotricuspide pour le flutter typique)"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 394"},{"id":"231-tx-09","rank":"A","class":"Correction des troubles ioniques","molecules":[],"context":"Prise en charge étiologique d'un allongement du QT ou d'une torsade de pointes.","indications":["Hypokaliémie","Hypocalcémie","Hypomagnésémie","Allongement du QT documenté"],"contraindications":[],"sideEffects":[],"monitoring":["Ionogramme","Surveillance ECG du QT"],"interactions":[],"pearls":["À associer à l'arrêt des médicaments allongeant le QT et à l'accélération de la fréquence cardiaque"],"src":"p. 404"},{"id":"231-tx-10","rank":"A","class":"Arrêt des médicaments à risque rythmique","molecules":[],"context":"Cause réversible fréquente d'un allongement du QT, d'une bradycardie ou d'un trouble de conduction.","indications":["Médicament allongeant le QT en cas de torsade de pointes ou de QT long","Médicament bradycardisant en cas de bradycardie ou de bloc atrioventriculaire symptomatique"],"contraindications":[],"sideEffects":[],"monitoring":[],"interactions":[],"pearls":[],"src":"p. 404, 412"}],"strategies":[{"id":"231-strat-01","rank":"A","title":"Prise en charge immédiate d'une tachycardie","content":"md 1. Évaluer la tolérance hémodynamique en premier lieu.\n2. Si mauvaise tolérance : cardioversion électrique externe sans délai.\n3. Si bonne tolérance : analyser la régularité puis la largeur des QRS.\n4. QRS larges réguliers → traiter comme une tachycardie ventriculaire jusqu'à preuve du contraire ; rechercher dissociation ventriculo-atriale, fusions/captures.\n5. QRS fins → manœuvres vagales, puis adénosine IV en flash si échec (sauf asthme, hypotension ou FA sur voie accessoire).\n6. Interpréter l'effet obtenu : arrêt brutal (tachycardie jonctionnelle), démasquage d'une activité atriale (tachycardie sinusale, flutter, tachycardie atriale focale) ou absence d'effet (tachycardie ventriculaire).\n7. QRS irréguliers → fibrillation atriale dans la grande majorité des cas.","src":"p. 405-406"},{"id":"231-strat-02","rank":"B","title":"Conduite devant un allongement du QT ou une torsade de pointes","content":"md 1. Confirmer l'allongement du QT corrigé (formule de Bazett), sans inclure une éventuelle onde U dans la mesure.\n2. Rechercher une cause : médicament allongeant le QT, hypokaliémie, hypocalcémie, hypomagnésémie, bradycardie extrême, ou forme congénitale.\n3. En cas de torsade de pointes ou de fibrillation ventriculaire déjà présente : corriger les troubles ioniques et accélérer la fréquence cardiaque en urgence.\n4. Dans tous les cas : arrêter les médicaments allongeant le QT en cause.\n5. Surveiller le QT après correction.","src":"p. 404"},{"id":"231-strat-03","rank":"B","title":"Choix de l'électroentraînement selon le trouble rythmique","content":"md 1. Problème hémodynamique lié à une bradycardie → pacemaker.\n2. Problème rythmique lié à un risque de tachycardie ou de fibrillation ventriculaire → défibrillateur (qui assure aussi la fonction pacemaker, sauf modèle sous-cutané).\n3. Bloc de branche gauche désynchronisant les parois du ventricule gauche avec insuffisance cardiaque → resynchronisation cardiaque.\n4. Les trois fonctions peuvent être associées (défibrillateur de resynchronisation) selon le profil du patient.","src":"p. 383, 412-414"}]},"cases":[{"id":"231-case-01","title":"M. Lefranc, 34 ans, palpitations brutales en pleine réunion","rank":"B","summary":"Crise de palpitations régulières et rapides chez un homme jeune sans cardiopathie, explorée pas à pas jusqu'au diagnostic de tachycardie jonctionnelle.","difficulty":2,"timeline":["Appel et premier contact","ECG per-critique","Manœuvres et traitement","Diagnostic","Exploration","Suivi"],"steps":[{"id":"231-case-01-s01","phase":0,"narrative":"md M. Lefranc, 34 ans, sans antécédent connu, ressent depuis vingt minutes des palpitations « qui ont démarré d'un coup », régulières, à une fréquence qu'il estime très rapide. Il n'a ni douleur thoracique ni dyspnée franche. Un collègue prend son pouls : régulier, très rapide, difficile à compter.","question":{"type":"QRM","stem":"Quels éléments, s'ils étaient présents, orienteraient plutôt vers une tachycardie sinusale que vers un trouble du rythme supraventriculaire ?","options":[{"t":"Une fréquence qui varie progressivement dans le temps plutôt que par paliers brusques","ok":true,"why":"La tachycardie sinusale varie progressivement, contrairement au trouble du rythme qui évolue « en marches d'escalier »."},{"t":"Un contexte de fièvre, de douleur ou de stress évident","ok":true,"why":"Une tachycardie sinusale s'explique par une cause qui augmente le métabolisme ; en son absence chez un sujet au repos, l'hypothèse doit être réévaluée."},{"t":"Un début et une fin brutaux, en quelques secondes","ok":false,"why":"C'est au contraire un argument pour un trouble du rythme supraventriculaire (début/fin brusques)."},{"t":"Une onde P sinusale bien visible devant chaque QRS, positive en D1, D2, D3, aVF","ok":true,"why":"C'est la définition électrique du rythme sinusal, quelle que soit la fréquence."},{"t":"Une fréquence stable autour de 190 bpm au repos strict","ok":false,"why":"Une fréquence aussi élevée et stable au repos est inhabituelle pour une simple tachycardie sinusale."}],"explanation":"md La distinction repose sur l'allure de la fréquence (progressive vs par paliers), le contexte clinique et la morphologie de l'onde P."},"reveal":"md Le collègue appelle les secours ; un premier ECG est réalisé dès l'arrivée de l'équipe.","src":"p. 390-391"},{"id":"231-case-01-s02","phase":1,"narrative":"md L'ECG montre une tachycardie régulière à QRS fins, à 195 bpm, sans onde P clairement identifiable avant les QRS. Le patient reste conscient, coloré, tension artérielle à 118/74 mmHg.","question":{"type":"QROC","question":"Quel est le premier geste, simple et non invasif, à proposer devant cette tachycardie régulière à QRS fins bien tolérée ?","answer":"Manœuvres vagales","accept":["manoeuvre vagale","manœuvre vagale","manoeuvres vagales"],"keywords":["vagal","Valsalva"],"explanation":"md Les manœuvres vagales (Valsalva, eau froide, compression carotidienne unilatérale en l'absence de souffle) sont le premier geste, à la fois diagnostique et parfois thérapeutique."},"reveal":"md Une manœuvre de Valsalva est tentée en premier lieu.","src":"p. 390, 405"},{"id":"231-case-01-s03","phase":2,"narrative":"md La manœuvre de Valsalva ne modifie pas le tracé. Le patient reste stable hémodynamiquement.","question":{"type":"QRM","stem":"Le patient étant stable et la manœuvre de Valsalva inefficace, quelles propositions sont exactes pour la suite de la prise en charge ?","options":[{"t":"L'adénosine en flash intraveineux est l'étape suivante logique","ok":true,"why":"En cas d'échec des manœuvres vagales chez un patient stable, l'adénosine IV en flash est l'étape suivante pour créer un bloc atrioventriculaire transitoire diagnostique et souvent thérapeutique."},{"t":"Une cardioversion électrique externe immédiate est indiquée","ok":false,"why":"Réservée aux tachycardies mal tolérées hémodynamiquement, ce qui n'est pas le cas ici."},{"t":"Une autre manœuvre vagale (compression carotidienne unilatérale ou eau froide) peut encore être tentée avant l'adénosine","ok":true,"why":"Les manœuvres vagales regroupent plusieurs techniques (Valsalva, eau froide, compression carotidienne unilatérale en l'absence de souffle) qui peuvent être essayées successivement."},{"t":"La compression oculaire bilatérale est une alternative recommandée","ok":false,"why":"Cette manœuvre n'est plus recommandée en raison du risque de décollement de rétine chez le myope."},{"t":"Une simple surveillance sans aucun geste supplémentaire est suffisante","ok":false,"why":"La tachycardie doit être documentée et si possible réduite ou expliquée, pas seulement surveillée."}],"explanation":"md Après échec d'une première manœuvre vagale, une autre manœuvre vagale peut être tentée, puis l'adénosine IV en flash chez un patient stable ; la compression oculaire bilatérale est proscrite."},"reveal":"md L'équipe tente une compression carotidienne unilatérale, sans succès, puis prépare l'injection d'adénosine.","src":"p. 390"},{"id":"231-case-01-s04","phase":2,"narrative":"md Interrogatoire rapide avant l'injection d'adénosine : pas d'asthme connu, tension artérielle correcte, pas d'antécédent de préexcitation connue.","question":{"type":"QRM","stem":"Quelles situations contre-indiquent l'utilisation de l'adénosine intraveineuse ?","options":[{"t":"Asthme","ok":true,"why":"Risque de bronchospasme intense transitoire, même chez un sujet non asthmatique connu."},{"t":"Hypotension artérielle","ok":true,"why":"C'est une contre-indication explicitement mentionnée."},{"t":"Fibrillation atriale associée à une voie accessoire à conduction rapide (« super-Wolff »)","ok":true,"why":"C'est la seule autre contre-indication citée, avec l'asthme."},{"t":"Grossesse au premier trimestre","ok":false,"why":"N'est pas mentionnée comme contre-indication dans le chapitre."},{"t":"Âge supérieur à 65 ans","ok":false,"why":"N'est pas une contre-indication retenue ici."}],"explanation":"md Les contre-indications retenues sont l'asthme, l'hypotension artérielle et la FA sur voie accessoire à conduction rapide."},"reveal":"md Aucune contre-indication n'étant retrouvée, l'adénosine est injectée en flash intraveineux.","src":"p. 390, 411"},{"id":"231-case-01-s05","phase":3,"narrative":"md Quelques secondes après l'injection, la tachycardie s'arrête brutalement et le tracé revient à un rythme sinusal régulier à 78 bpm.","question":{"type":"QRU","stem":"Quel diagnostic est le plus probable devant cet arrêt brutal de la tachycardie après adénosine ?","options":[{"t":"Flutter atrial démasqué par le ralentissement du NAV","ok":false,"why":"Dans le flutter, l'adénosine démasque l'activité atriale (ondes F) mais n'arrête pas l'arythmie car celle-ci ne dépend pas du NAV."},{"t":"Tachycardie sinusale","ok":false,"why":"Une tachycardie sinusale n'est pas interrompue par l'adénosine, elle ralentit transitoirement puis reprend."},{"t":"Tachycardie jonctionnelle par réentrée dépendante du NAV","ok":true,"why":"L'arrêt brutal de la tachycardie par l'adénosine signe une arythmie dont le circuit emprunte le NAV, typique des tachycardies jonctionnelles (dont la réentrée intranodale)."},{"t":"Tachycardie ventriculaire","ok":false,"why":"Le tracé initial était à QRS fins, incompatible avec une origine ventriculaire."},{"t":"Fibrillation atriale","ok":false,"why":"La FA donne une tachycardie « irrégulièrement irrégulière » ; or le tracé initial était une tachycardie régulière à QRS fins."}],"explanation":"md L'arrêt franc de la tachycardie par blocage du NAV signe une arythmie dont le circuit de réentrée dépend du nœud atrioventriculaire."},"reveal":"md Le diagnostic retenu est une tachycardie jonctionnelle, très probablement par réentrée intranodale.","src":"p. 391-392, 397, 405"},{"id":"231-case-01-s06","phase":3,"narrative":"md Le patient est rassuré ; l'épisode a duré environ vingt-cinq minutes au total.","question":{"type":"QRM","stem":"Quelles affirmations concernant les deux formes de tachycardies jonctionnelles décrites dans ce chapitre sont exactes ?","options":[{"t":"La réentrée intranodale est un mécanisme de réentrée au sein du nœud atrioventriculaire","ok":true,"why":"C'est la première forme de tachycardie jonctionnelle."},{"t":"La réentrée par voie accessoire fait intervenir le faisceau de Kent","ok":true,"why":"La seconde forme correspond à une réentrée par le faisceau de Kent, voie accessoire entre oreillette et ventricule."},{"t":"Les tachycardies jonctionnelles sont typiquement irrégulières","ok":false,"why":"Elles sont au contraire très régulières, souvent autour de 200 bpm."},{"t":"Dans la réentrée intranodale, l'activité atriale est souvent invisible ou devinée dans le segment ST","ok":true,"why":"L'activation atriale et ventriculaire y est quasi synchrone, rendant l'onde P difficile à voir."},{"t":"Ces deux mécanismes naissent en dessous de la bifurcation hissienne","ok":false,"why":"Les tachycardies jonctionnelles naissent au niveau de la jonction atrioventriculaire, au-dessus de cette bifurcation, à la différence des tachycardies ventriculaires."}],"explanation":"md Les deux formes de tachycardies jonctionnelles sont la réentrée intranodale (réentrée dans le NAV, activité atriale souvent invisible) et le rythme réciproque par voie accessoire (faisceau de Kent) ; elles sont très régulières, souvent autour de 200 bpm."},"reveal":"md Le patient est orienté vers une consultation de rythmologie pour discuter la suite de la prise en charge.","src":"p. 395"},{"id":"231-case-01-s07","phase":4,"narrative":"md En consultation, le cardiologue rythmologue propose une exploration électrophysiologique en cas de récidive gênante.","question":{"type":"QRU","stem":"Quel traitement, mentionné pour les arythmies par réentrée, peut être proposé après confirmation du mécanisme lors d'une exploration électrophysiologique ?","options":[{"t":"Ablation par radiofréquence","ok":true,"why":"C'est le traitement curatif des arythmies par réentrée confirmées en exploration électrophysiologique, comme pour le flutter."},{"t":"Implantation d'un défibrillateur","ok":false,"why":"Réservé au risque de tachycardie ou fibrillation ventriculaire, non à cette arythmie supraventriculaire bénigne."},{"t":"Implantation d'un pacemaker","ok":false,"why":"Indiqué dans les bradycardies ou blocs de conduction, pas dans cette tachycardie jonctionnelle."},{"t":"Resynchronisation cardiaque","ok":false,"why":"Concerne la désynchronisation ventriculaire liée à un bloc de branche gauche, sans rapport avec ce tableau."},{"t":"Coronarographie","ok":false,"why":"Aucun argument pour une origine coronarienne dans ce tableau."}],"explanation":"md L'ablation par radiofréquence, après repérage électrophysiologique du circuit, est le traitement curatif des arythmies par réentrée."},"reveal":"md Le patient choisit une simple surveillance dans un premier temps, avec consigne de refaire les manœuvres vagales en cas de récidive.","src":"p. 394"},{"id":"231-case-01-s08","phase":5,"narrative":"md Six mois plus tard, M. Lefranc revient en consultation : aucune récidive de palpitations n'est survenue.","question":{"type":"QROC","question":"Quelle conduite pratique doit-on lui rappeler en cas de nouvelle crise de palpitations régulières bien tolérées ?","answer":"Réaliser une manœuvre vagale (Valsalva, eau froide)","accept":["manoeuvre vagale","valsalva"],"keywords":["manœuvre vagale","Valsalva"],"explanation":"md Les manœuvres vagales restent le premier réflexe simple, disponible en autonomie, devant une récidive bien tolérée."},"reveal":"md Le patient repart rassuré, avec les coordonnées du service en cas de récidive prolongée ou mal tolérée.","src":"p. 390"},{"id":"231-case-01-s09","phase":5,"narrative":"md M. Lefranc demande si le fait d'avoir eu une seule crise, bien tolérée et rapidement résolue par l'adénosine, change le pronostic à long terme.","question":{"type":"QRM","stem":"Concernant le pronostic après une tachycardie jonctionnelle bien tolérée et rapidement réduite par l'adénosine, quelles affirmations sont exactes ?","options":[{"t":"Il s'agit d'un trouble du rythme fréquent, habituellement sans gravité immédiate","ok":true,"why":"C'est la description cohérente avec le chapitre pour les tachycardies jonctionnelles."},{"t":"Une ablation par radiofréquence peut être discutée en cas de récidives gênantes après exploration électrophysiologique","ok":true,"why":"C'est le traitement curatif proposé en cas de récidive gênante, après confirmation du mécanisme."},{"t":"Une évolution vers une fibrillation ventriculaire est habituelle à moyen terme","ok":false,"why":"Rien de tel n'est décrit pour ce mécanisme, qui naît au-dessus de la bifurcation hissienne."},{"t":"Une implantation de défibrillateur est systématique après un premier épisode","ok":false,"why":"Aucune indication de défibrillateur n'est décrite pour ce mécanisme supraventriculaire."},{"t":"Les manœuvres vagales restent un réflexe utile en cas de récidive bien tolérée","ok":true,"why":"Les manœuvres vagales restent le premier geste simple à proposer en cas de récidive bien tolérée."}],"explanation":"md Les tachycardies jonctionnelles par réentrée intranodale sont fréquentes, habituellement bénignes, traitées par manœuvres vagales, adénosine, et éventuellement ablation en cas de récidives gênantes."},"reveal":"md Le patient est rassuré sur le caractère bénin de l'épisode.","src":"p. 395"},{"id":"231-case-01-s10","phase":5,"narrative":"md Avant de conclure la consultation, le cardiologue résume les deux formes de tachycardies jonctionnelles évoquées dans le dossier.","question":{"type":"QROC","question":"Quel est le nom de la voie électrique surnuméraire à l'origine des tachycardies jonctionnelles par rythme réciproque (l'autre grand mécanisme, non retrouvé ici) ?","answer":"Le faisceau de Kent (voie accessoire)","accept":["faisceau de kent","voie accessoire"],"keywords":["Kent","voie accessoire"],"explanation":"md Le second mécanisme des tachycardies jonctionnelles est la réentrée par une voie accessoire, le faisceau de Kent, reliant l'oreillette au ventricule en dehors du NAV."},"reveal":"md Le dossier de M. Lefranc est clôturé après ce rappel physiopathologique.","src":"p. 396"}]},{"id":"231-case-02","title":"Mme Auger, 79 ans, malaise avec perte de connaissance brève","rank":"B","summary":"Syncope chez une patiente âgée révélant une bradycardie profonde ; la démarche distingue dysfonction sinusale et bloc atrioventriculaire jusqu'à la décision d'appareillage.","difficulty":2,"timeline":["Admission aux urgences","Premier ECG","Analyse du mécanisme","Bilan étiologique","Décision et implantation","Suivi post-implantation"],"steps":[{"id":"231-case-02-s01","phase":0,"narrative":"md Mme Auger, 79 ans, traitée pour une hypertension artérielle, est amenée aux urgences après une brève perte de connaissance survenue en se levant, sans mouvement anormal ni morsure de langue. Elle est consciente à l'arrivée, un peu fatiguée. Le pouls est estimé à environ 35 bpm, régulier.","question":{"type":"QRM","stem":"Devant cette bradycardie extrême, quelles sont les deux structures dont le dysfonctionnement peut en être responsable ?","options":[{"t":"Le nœud sinusal","ok":true,"why":"Une dysfonction sinusale est l'une des deux causes possibles d'une bradycardie marquée."},{"t":"Le nœud atrioventriculaire","ok":true,"why":"Un bloc atrioventriculaire de haut degré est l'autre cause possible d'une bradycardie marquée."},{"t":"Le faisceau de His isolément, en l'absence de toute autre atteinte","ok":false,"why":"Ce n'est pas la formulation retenue ; le trouble atrioventriculaire est envisagé de façon globale (nœud atrioventriculaire)."},{"t":"Le nœud atrioventriculaire ou le nœud sinusal, à distinguer par l'analyse des ondes P","ok":true,"why":"C'est la démarche proposée : l'aspect des ondes P oriente vers l'une ou l'autre structure."},{"t":"Le muscle ventriculaire lui-même, indépendamment de toute structure de conduction","ok":false,"why":"Ce n'est pas la cause d'une bradycardie décrite dans le chapitre."}],"explanation":"md Seules deux structures peuvent, en dysfonctionnant, entraîner une bradycardie : le nœud sinusal (dysfonction sinusale) ou le nœud atrioventriculaire (BAV)."},"reveal":"md Un ECG 12 dérivations est réalisé immédiatement.","src":"p. 389"},{"id":"231-case-02-s02","phase":1,"narrative":"md L'ECG montre des ondes P régulières à une fréquence proche de 75 bpm, mais on compte davantage d'ondes P que de complexes QRS, ceux-ci survenant de façon indépendante à environ 34 bpm.","question":{"type":"QRU","stem":"Quel diagnostic électrique cette dissociation entre une activité atriale normale et des QRS plus rares et indépendants évoque-t-elle ?","options":[{"t":"Dysfonction sinusale","ok":false,"why":"Dans la dysfonction sinusale, ce sont les ondes P elles-mêmes qui sont trop lentes ou absentes ; ici elles sont normales en fréquence."},{"t":"Bloc atrioventriculaire complet (BAV3)","ok":true,"why":"Des ondes P régulières à fréquence normale mais dissociées de QRS plus lents et réguliers signent un bloc atrioventriculaire complet avec rythme d'échappement."},{"t":"Fibrillation atriale à conduction lente","ok":false,"why":"L'activité atriale décrite ici est organisée et régulière, pas anarchique."},{"t":"Extrasystoles atriales bloquées itératives","ok":false,"why":"Ne rend pas compte d'une dissociation aussi complète et régulière."},{"t":"Tachycardie atriale focale avec bloc","ok":false,"why":"La fréquence atriale ici est normale, non tachycarde."}],"explanation":"md La présence de plus d'ondes P que de QRS, avec des ondes P régulières à fréquence normale, oriente vers un problème de passage au ventricule : le bloc atrioventriculaire."},"reveal":"md Le diagnostic de bloc atrioventriculaire complet est retenu ; l'équipe analyse la largeur de l'échappement.","src":"p. 389"},{"id":"231-case-02-s03","phase":2,"narrative":"md Les QRS d'échappement sont larges (150 ms), à une fréquence régulière d'environ 34 bpm.","question":{"type":"QROC","question":"Un échappement à QRS larges dans ce contexte de BAV oriente vers quel siège probable du bloc ?","answer":"Infrahissien","accept":["infra-hissien","sous hissien","bas situé"],"keywords":["infrahissien"],"explanation":"md Un échappement à QRS fins traduit un bloc nodal (suprahissien), alors qu'un échappement à QRS larges oriente vers un bloc infrahissien, de plus mauvais pronostic."},"reveal":"md L'équipe considère ce BAV comme probablement infrahissien.","src":"p. 387, 389"},{"id":"231-case-02-s04","phase":2,"narrative":"md La patiente reste stable hémodynamiquement mais somnolente.","question":{"type":"QRM","stem":"Quelles sont les conséquences potentielles d'un bloc atrioventriculaire infrahissien non traité ?","options":[{"t":"Syncopes à répétition","ok":true,"why":"Le BAV complet infrahissien peut entraîner des syncopes, voire une mort subite : c'est ce risque qui fait hospitaliser sous télémétrie une syncope sur bloc bifasciculaire."},{"t":"Mort subite","ok":true,"why":"La mort subite est citée parmi les conséquences possibles du BAV complet infrahissien."},{"t":"Fibrillation atriale obligatoire à court terme","ok":false,"why":"Aucun lien de causalité direct de ce type n'est décrit."},{"t":"Torsade de pointes favorisée par la bradycardie extrême","ok":true,"why":"La bradycardie extrême des BAV bas situés (échappement à QRS larges) allonge le QT et expose aux torsades de pointes."},{"t":"Hypertrophie ventriculaire gauche immédiate","ok":false,"why":"Ce n'est pas une conséquence rythmique directe d'un BAV."}],"explanation":"md Un BAV infrahissien expose à des syncopes, à la mort subite et, par la bradycardie extrême qui allonge le QT, aux torsades de pointes : la prise en charge doit être rapide."},"reveal":"md Une hospitalisation en unité de soins intensifs cardiologiques est décidée, avec scope.","src":"p. 383, 389, 404"},{"id":"231-case-02-s05","phase":3,"narrative":"md Avant toute décision d'appareillage définitif, le bilan recherche une cause réversible : ionogramme sanguin normal (kaliémie à 4,2 mmol/L), pas de médicament bradycardisant dans le traitement habituel de la patiente.","question":{"type":"QRM","stem":"Pourquoi est-il utile de rechercher une dyskaliémie ou un médicament bradycardisant avant de conclure à une indication définitive de pacemaker ?","options":[{"t":"Une hyperkaliémie peut elle-même provoquer un bloc atrioventriculaire ou une dysfonction sinusale","ok":true,"why":"L'hyperkaliémie s'accompagne notamment d'un allongement du PR, d'un élargissement du QRS, d'un BAV ou d'une dysfonction sinusale."},{"t":"Une hypokaliémie explique classiquement les blocs atrioventriculaires de haut degré","ok":false,"why":"L'hypokaliémie se traduit surtout par une onde T plate, un QT allongé et un risque de torsade de pointes, pas typiquement par un BAV."},{"t":"Un médicament bradycardisant peut être une cause réversible de bradycardie ou de bloc","ok":true,"why":"Il faut éliminer une cause pharmacologique réversible avant de poser une indication définitive d'appareillage."},{"t":"Ces éléments n'ont aucune incidence sur la décision thérapeutique","ok":false,"why":"Au contraire, ils orientent directement la décision d'implantation ou de simple correction d'une cause réversible."},{"t":"La correction d'une cause réversible peut éviter une implantation de pacemaker","ok":true,"why":"C'est l'intérêt principal de cette recherche systématique."}],"explanation":"md Avant toute décision d'appareillage, il faut écarter une cause réversible (dyskaliémie, médicament bradycardisant), en particulier l'hyperkaliémie qui peut mimer ou aggraver un trouble de conduction."},"reveal":"md Aucune cause réversible n'étant retrouvée, l'indication de pacemaker est confirmée.","src":"p. 408-409, 412"},{"id":"231-case-02-s06","phase":4,"narrative":"md Le bilan étant négatif, la décision d'implanter un stimulateur cardiaque est prise.","question":{"type":"QRU","stem":"Compte tenu du siège probablement infrahissien du bloc, quelle affirmation concernant l'indication de pacemaker est exacte ?","options":[{"t":"L'indication est posée même si la patiente était restée asymptomatique","ok":true,"why":"Les BAV infrahissiens (Mobitz 2, BAV3) sont une indication de pacemaker même en l'absence de symptôme."},{"t":"L'indication ne se discute qu'en présence de symptômes répétés","ok":false,"why":"C'est le cas pour la dysfonction sinusale ou le BAV2 Mobitz 1, pas pour le BAV infrahissien de haut degré."},{"t":"Un simple traitement médicamenteux suffit à corriger ce trouble","ok":false,"why":"Aucun traitement médicamenteux curatif de ce trouble structurel n'est décrit."},{"t":"Il faut attendre une deuxième syncope avant d'implanter","ok":false,"why":"Ce n'est pas la logique retenue : un BAV infrahissien (Mobitz 2, BAV3) est une indication de pacemaker même sans symptôme."},{"t":"Seule une surveillance ambulatoire par holter est proposée","ok":false,"why":"Insuffisant devant un bloc de haut degré symptomatique et à risque de mort subite."}],"explanation":"md Les blocs atrioventriculaires infrahissiens (Mobitz 2, BAV3) constituent une indication de pacemaker même sans symptôme, du fait du risque de mort subite."},"reveal":"md Un pacemaker double chambre est implanté sans complication.","src":"p. 383, 412"},{"id":"231-case-02-s07","phase":5,"narrative":"md L'ECG post-implantation montre un spike de stimulation suivi d'un QRS large avec un aspect de bloc de branche gauche.","question":{"type":"QROC","question":"Pourquoi la stimulation ventriculaire droite donne-t-elle un aspect de bloc de branche gauche à l'ECG ?","answer":"Parce que l'influx stimulé se propage de proche en proche depuis le ventricule droit vers le ventricule gauche, sans emprunter le réseau de conduction rapide","accept":["conduction de proche en proche","propagation lente depuis le ventricule droit"],"keywords":["proche en proche","ventricule droit","conduction lente"],"explanation":"md La stimulation ventriculaire droite se transmet lentement de proche en proche au reste des ventricules, contrairement à la conduction rapide du réseau de His-Purkinje, ce qui donne un aspect de bloc de branche gauche."},"reveal":"md Le boîtier est programmé et la patiente reçoit les consignes de suivi.","src":"p. 413-414"},{"id":"231-case-02-s09","phase":5,"narrative":"md Au contrôle du premier mois, le fonctionnement du pacemaker est normal ; Mme Auger n'a pas eu de nouveau malaise.","question":{"type":"QRU","stem":"Si un nouvel épisode de malaise survenait malgré le pacemaker bien fonctionnel, quelle démarche diagnostique reste pertinente pour en préciser la cause ?","options":[{"t":"Un enregistrement Holter ou l'interrogation de la mémoire du pacemaker, à la recherche d'un autre mécanisme (rythmique ou non)","ok":true,"why":"Le monitorage ECG prolongé et l'interrogation du dispositif restent les outils de choix pour documenter un symptôme épisodique, même chez un patient appareillé."},{"t":"Aucune exploration supplémentaire n'est jamais utile chez un patient porteur de pacemaker","ok":false,"why":"Le pacemaker corrige la bradycardie mais n'exclut pas une autre cause de malaise."},{"t":"Une nouvelle implantation systématique d'un deuxième dispositif","ok":false,"why":"Ce n'est pas la démarche proposée devant un malaise chez un patient déjà appareillé."},{"t":"Un scanner cérébral systématique en première intention","ok":false,"why":"N'est pas la démarche rythmologique décrite dans ce chapitre."},{"t":"Un arrêt du pacemaker pour réévaluer le rythme spontané","ok":false,"why":"Geste dangereux et non recommandé pour explorer un malaise."}],"explanation":"md Même appareillé, un patient présentant un nouveau malaise doit bénéficier d'une évaluation rythmique (Holter, mémoire du dispositif) pour rechercher une autre cause."},"reveal":"md Aucun nouvel épisode n'est survenu ; la surveillance se poursuit.","src":"p. 414, 415"},{"id":"231-case-02-s10","phase":5,"narrative":"md Un an plus tard, Mme Auger va bien et se demande si elle pourra un jour se passer de son pacemaker.","question":{"type":"QROC","question":"Que peut-on lui répondre concernant le caractère définitif de l'indication posée initialement (BAV infrahissien sans cause réversible retrouvée) ?","answer":"L'indication reste définitive, aucune cause réversible n'ayant été retrouvée","accept":["indication definitive","pas de cause reversible donc indication permanente"],"keywords":["définitive","pas de cause réversible"],"explanation":"md Le bilan initial n'ayant retrouvé aucune cause réversible (kaliémie normale, pas de médicament en cause), l'indication de pacemaker posée pour ce BAV infrahissien reste définitive."},"reveal":"md Mme Auger poursuit son suivi cardiologique annuel.","src":"p. 412"}]},{"id":"231-case-03","title":"M. Costa, 56 ans, douleur thoracique et bloc de branche gauche connu","rank":"B","summary":"Douleur thoracique aiguë chez un patient porteur d'un bloc de branche gauche complet, illustrant le piège de la discordance appropriée et les diagnostics différentiels du sus-décalage de ST.","difficulty":3,"timeline":["Arrivée aux urgences","Premier ECG","Analyse du tracé","Décision de prise en charge","Explorations et évolution","Suivi à distance"],"steps":[{"id":"231-case-03-s01","phase":0,"narrative":"md M. Costa, 56 ans, hypertendu et fumeur, se présente aux urgences pour une douleur thoracique constrictive apparue il y a quarante minutes, toujours présente. Il est connu porteur d'un bloc de branche gauche complet ancien, retrouvé sur un ECG systématique deux ans plus tôt.","question":{"type":"QRM","stem":"Quels éléments faut-il vérifier dans l'ordre pour caractériser ce bloc de branche sur l'ECG réalisé aux urgences ?","options":[{"t":"Le rythme atrial, en premier lieu","ok":true,"why":"Il faut toujours commencer par décrire le rythme atrial avant de décrire un trouble de conduction, pour ne pas méconnaître une tachycardie supraventriculaire associée."},{"t":"La durée du QRS (> 120 ms pour un bloc complet)","ok":true,"why":"C'est le deuxième critère à vérifier."},{"t":"L'aspect du QRS en V1 (positif ou négatif)","ok":true,"why":"Un QRS positif en V1 oriente vers un bloc droit, négatif vers un bloc gauche."},{"t":"La présence obligatoire d'un sus-décalage du segment ST en D2","ok":false,"why":"Ce n'est pas un critère de diagnostic du bloc de branche lui-même."},{"t":"L'aspect inverse en V6","ok":true,"why":"La vérification de l'aspect en V6, inverse de celui de V1, complète l'analyse."}],"explanation":"md La démarche recommandée est : rythme atrial, durée du QRS, aspect en V1, puis aspect inverse en V6."},"reveal":"md L'ECG confirme un bloc de branche gauche complet inchangé, avec un rythme sinusal sous-jacent.","src":"p. 381"},{"id":"231-case-03-s02","phase":1,"narrative":"md Le tracé montre en V1-V2 un segment ST légèrement sus-décalé, avec une onde T positive, dans un contexte de QRS négatif à cet endroit (aspect de bloc de branche gauche).","question":{"type":"QRM","stem":"Que faut-il savoir sur ce sus-décalage observé en V1-V2 chez ce patient porteur d'un bloc de branche gauche ?","options":[{"t":"Il peut correspondre à une « discordance appropriée », physiologique dans le bloc de branche gauche","ok":true,"why":"Quand le QRS est négatif, un petit sus-décalage de ST avec T positive est la discordance attendue et n'est pas en soi pathologique."},{"t":"Il élimine formellement un syndrome coronarien aigu","ok":false,"why":"Au contraire, l'interprétation de la repolarisation est difficile en présence d'un bloc de branche gauche et ne permet pas d'éliminer un SCA."},{"t":"Il peut faire évoquer à tort un syndrome coronarien aigu avec sus-décalage du ST","ok":true,"why":"C'est explicitement le piège décrit : la discordance appropriée peut mimer un authentique sus-décalage ischémique."},{"t":"Il doit systématiquement faire différer toute évaluation cardiologique en l'absence de troponine élevée","ok":false,"why":"C'est l'inverse : devant une douleur persistante avec bloc de branche gauche, l'évaluation cardiologique doit être rapide sans attendre le dosage de troponine."},{"t":"Sa signification dépend fortement de la présentation clinique associée","ok":true,"why":"En présence d'un bloc de branche gauche, la clinique prend une importance cruciale pour l'interprétation de la repolarisation."}],"explanation":"md La discordance appropriée du bloc de branche gauche peut mimer un authentique sus-décalage ischémique ; la clinique devient alors déterminante."},"reveal":"md Devant la persistance de la douleur, le cardiologue de garde est appelé sans délai.","src":"p. 381"},{"id":"231-case-03-s03","phase":2,"narrative":"md Le cardiologue examine le patient : douleur constrictive inchangée, non sensible à un test à la trinitrine, pas de signe de choc.","question":{"type":"QRU","stem":"Quelle est la conduite recommandée par le chapitre devant une douleur thoracique persistante avec bloc de branche gauche, avant même le résultat de la troponine ?","options":[{"t":"Attendre le résultat de la troponine avant toute évaluation spécialisée","ok":false,"why":"C'est justement ce qu'il ne faut pas faire : l'évaluation cardiologique doit être rapide sans attendre ce dosage."},{"t":"Évoquer un possible infarctus antérieur et faire évaluer rapidement le patient par un cardiologue, en recherchant des arguments cliniques et échographiques complémentaires","ok":true,"why":"C'est la conduite recommandée : évaluation rapide, analyse sémiologique de la douleur, réponse à la trinitrine, recherche de signes de choc, échocardiographie."},{"t":"Rassurer le patient car le bloc de branche gauche est connu et ancien","ok":false,"why":"Le caractère ancien du bloc ne permet pas d'éliminer un authentique infarctus en cours."},{"t":"Réaliser uniquement une surveillance scope sans autre exploration","ok":false,"why":"Insuffisant devant une douleur persistante avec ce trouble de conduction."},{"t":"Différer toute prise en charge de 24 heures pour un nouvel ECG de contrôle","ok":false,"why":"Le contexte impose une évaluation rapide, pas un délai de 24 heures."}],"explanation":"md Devant une douleur thoracique persistante avec bloc de branche gauche, il faut évoquer un infarctus antérieur et faire évaluer le patient en urgence par un cardiologue, sans attendre la troponine."},"reveal":"md Une échographie cardiaque est réalisée au lit du patient.","src":"p. 381"},{"id":"231-case-03-s04","phase":2,"narrative":"md L'échocardiographie retrouve un trouble de la cinétique segmentaire antérieur, absent sur un examen antérieur.","question":{"type":"QROC","question":"Quels éléments cliniques, en dehors de l'imagerie, peuvent aider à distinguer un authentique syndrome coronarien aigu chez ce patient porteur de bloc de branche gauche ?","answer":"L'analyse sémiologique de la douleur (caractère, effet de la trinitrine) et la recherche de signes de choc","accept":["semiologie de la douleur et signes de choc","effet de la trinitrine et signes de choc"],"keywords":["trinitrine","signes de choc","sémiologie"],"explanation":"md Le chapitre insiste sur l'analyse sémiologique de la douleur, dont l'effet de la trinitrine, et la recherche de signes de choc pour orienter le diagnostic dans ce contexte difficile."},"reveal":"md Devant ce faisceau d'arguments, le patient est pris en charge comme un syndrome coronarien aigu.","src":"p. 381"},{"id":"231-case-03-s05","phase":3,"narrative":"md Le patient est transféré en urgence en salle de coronarographie, en dehors de tout nouveau détail médicamenteux précisé ici.","question":{"type":"QRM","stem":"Parmi les cinq étiologies classiques d'un sus-décalage du segment ST citées dans ce chapitre, lesquelles sont exactes ?","options":[{"t":"Syndrome coronarien aigu avec sus-décalage du ST","ok":true,"why":"C'est la première étiologie citée, avec une image en miroir typique (onde de Pardee)."},{"t":"Anévrisme ventriculaire","ok":true,"why":"Le sus-décalage peut persister après un infarctus en cas de séquelle marquée avec anévrisme."},{"t":"Repolarisation précoce","ok":true,"why":"Sus-décalage bénin dans les dérivations inféro-latérales, notamment chez le sujet jeune."},{"t":"Angor de Prinzmetal","ok":true,"why":"Spasme coronarien pouvant donner un sus-décalage ressemblant à celui du SCA."},{"t":"Hypertrophie atriale gauche","ok":false,"why":"N'est pas citée parmi les cinq étiologies du sus-décalage de ST ; c'est un diagnostic différentiel portant sur l'onde P, pas le segment ST."}],"explanation":"md Les cinq étiologies citées sont le SCA avec sus-décalage, l'anévrisme ventriculaire, la repolarisation précoce, l'angor de Prinzmetal et la péricardite."},"reveal":"md La coronarographie retrouve une occlusion coronaire, traitée en urgence par le cardiologue interventionnel.","src":"p. 412"},{"id":"231-case-03-s06","phase":4,"narrative":"md Quelques jours plus tard, un ECG de contrôle montre un sus-décalage résiduel persistant en antérieur, alors que le patient est asymptomatique.","question":{"type":"QRU","stem":"Quelle explication est la plus probable devant ce sus-décalage résiduel persistant, asymptomatique, après un infarctus antérieur étendu ?","options":[{"t":"Récidive ischémique silencieuse systématique","ok":false,"why":"N'est pas l'explication retenue pour un sus-décalage résiduel chronique asymptomatique."},{"t":"Anévrisme ventriculaire sur séquelle d'infarctus marquée","ok":true,"why":"Le sus-décalage peut persister indéfiniment lorsque la séquelle d'infarctus entraîne un anévrisme de la paroi ventriculaire."},{"t":"Nouvelle péricardite aiguë associée","ok":false,"why":"Le sus-décalage de la péricardite est diffus et concave, non systématisé au territoire infarci comme ici."},{"t":"Artéfact technique sans signification","ok":false,"why":"Le chapitre décrit une explication physiopathologique précise pour ce tableau, pas un simple artéfact."},{"t":"Repolarisation précoce apparue secondairement","ok":false,"why":"N'est pas cohérent avec le contexte de séquelle d'infarctus étendu."}],"explanation":"md Un sus-décalage persistant après un infarctus avec séquelle marquée évoque un anévrisme ventriculaire."},"reveal":"md Une surveillance cardiologique régulière est organisée, avec réévaluation de la fonction ventriculaire gauche.","src":"p. 412"},{"id":"231-case-03-s07","phase":5,"narrative":"md Un an plus tard, le patient est stable, sans récidive douloureuse. L'ECG de suivi reste inchangé.","question":{"type":"QROC","question":"Quel type de dispositif serait à discuter si ce bloc de branche gauche s'accompagnait secondairement de signes d'insuffisance cardiaque liés à une désynchronisation ventriculaire ?","answer":"Une resynchronisation cardiaque","accept":["resynchronisation","stimulation biventriculaire"],"keywords":["resynchronisation"],"explanation":"md Un bloc de branche gauche complet peut contribuer à une désynchronisation des parois ventriculaires ; sa correction par resynchronisation cardiaque est indiquée en cas de signes d'insuffisance cardiaque associés."},"reveal":"md Le patient reste pour l'instant sans indication de resynchronisation, sa fonction ventriculaire étant stable au dernier contrôle.","src":"p. 383"},{"id":"231-case-03-s08","phase":5,"narrative":"md Lors d'une consultation ultérieure, M. Costa demande pourquoi il fallait absolument faire un ECG 18 dérivations lors de son passage aux urgences, alors que son bloc de branche gauche compliquait déjà l'interprétation.","question":{"type":"QROC","question":"Quelle anomalie postérieure pourrait passer inaperçue sur un ECG 12 dérivations standard devant une douleur thoracique, justifiant des dérivations supplémentaires ?","answer":"Un sus-décalage de ST en territoire postérieur (V7-V9), qui se traduit en miroir par un sous-décalage en V1-V3","accept":["infarctus posterieur avec miroir anterieur","sus decalage v7 v9"],"keywords":["V7","V8","V9","miroir"],"explanation":"md Un sous-décalage en antérieur (V1-V3) peut être le simple miroir d'un sus-décalage postérieur (V7-V9), ce qui justifie de réaliser un ECG 18 dérivations devant toute douleur thoracique."},"reveal":"md L'équipe confirme que ce complément n'a finalement pas été nécessaire dans son cas, l'atteinte antérieure étant déjà évidente.","src":"p. 411"},{"id":"231-case-03-s09","phase":5,"narrative":"md Le patient s'interroge également sur la surveillance rythmique qui lui a été proposée après sa sortie, en dehors de tout traitement médicamenteux détaillé ici.","question":{"type":"QRU","stem":"Quel examen, décrit dans ce chapitre, permettrait de détecter d'éventuelles salves de tachycardie ventriculaire asymptomatiques après un infarctus étendu ?","options":[{"t":"Un enregistrement Holter de 24 heures","ok":true,"why":"L'enregistrement Holter de 24 heures est utilisé pour évaluer le risque rythmique en détectant des salves de tachycardie ventriculaire asymptomatiques après infarctus."},{"t":"Une échographie transthoracique isolée","ok":false,"why":"L'échographie évalue la fonction et la cinétique, pas directement le risque rythmique."},{"t":"Un massage sino-carotidien","ok":false,"why":"Cette manœuvre sert à explorer une tachycardie ou une dysfonction sinusale, pas à dépister des salves de TV."},{"t":"Une radiographie thoracique de contrôle","ok":false,"why":"N'apporte pas d'information rythmique."},{"t":"Un dosage isolé de la troponine à distance","ok":false,"why":"N'a pas d'utilité pour dépister un trouble du rythme asymptomatique à distance."}],"explanation":"md Le Holter de 24 heures permet notamment d'évaluer le risque rythmique après un infarctus, en recherchant des salves de tachycardie ventriculaire asymptomatiques."},"reveal":"md Un Holter de contrôle est programmé à distance, sans anomalie majeure retrouvée.","src":"p. 415"},{"id":"231-case-03-s10","phase":5,"narrative":"md Deux ans après l'épisode initial, M. Costa reste asymptomatique et poursuit un suivi cardiologique régulier.","question":{"type":"QRM","stem":"Quels éléments de ce dossier illustrent la difficulté d'interpréter un ECG en présence d'un bloc de branche gauche ?","options":[{"t":"La discordance appropriée pouvant mimer un sus-décalage ischémique","ok":true,"why":"C'est le piège central illustré par ce dossier."},{"t":"La nécessité de s'appuyer davantage sur la clinique et l'échographie que sur le seul tracé","ok":true,"why":"Le chapitre insiste sur l'importance de la présentation clinique dans ce contexte."},{"t":"L'impossibilité totale de jamais diagnostiquer un infarctus chez un patient porteur de bloc de branche gauche","ok":false,"why":"Le diagnostic reste possible, mais nécessite une démarche clinique et paraclinique adaptée, pas une impossibilité totale."},{"t":"Le fait qu'un bloc de branche gauche complet ancien puisse rendre l'analyse de la repolarisation antérieure peu fiable","ok":true,"why":"C'est explicitement souligné dans le chapitre concernant l'interprétation du territoire antérieur en présence d'un BBG."},{"t":"Le fait que la troponine devienne totalement inutile dans ce contexte","ok":false,"why":"La troponine garde son utilité, simplement son résultat ne doit pas être attendu avant l'évaluation initiale."}],"explanation":"md Ce dossier illustre le piège de la discordance appropriée, l'importance de la clinique et de l'échographie, et la difficulté persistante d'analyser la repolarisation antérieure en présence d'un bloc de branche gauche."},"reveal":"md Le dossier de M. Costa est clôturé, avec un dernier rappel sur la vigilance à conserver devant toute nouvelle douleur thoracique.","src":"p. 381"}]},{"id":"231-case-51","title":"Mme B., 71 ans, palpitations régulières depuis la veille","rank":"B","summary":"Tachycardie régulière à QRS fins à 150 bpm : démarche diagnostique, manœuvres vagales, reconnaissance d'un flutter atrial typique et de sa conduction ventriculaire, puis documentation de palpitations épisodiques.","difficulty":2,"timeline":["Accueil","ECG initial","BAV transitoire","Diagnostic","Évolution","Suivi"],"steps":[{"phase":0,"narrative":"Mme B., 71 ans, consulte aux urgences pour des palpitations régulières et rapides apparues la veille. Elle est consciente, PA 125/75 mmHg, sans signe d'insuffisance cardiaque.","question":{"type":"QRM","stem":"Concernant l'enregistrement ECG dans ce contexte, quelles propositions sont exactes ?","options":[{"t":"Les palpitations sont une indication d'ECG 12 dérivations.","ok":true,"why":"Les palpitations figurent parmi les symptômes justifiant un ECG conventionnel."},{"t":"Un monitorage ECG continu est indiqué aux urgences.","ok":true,"why":"Toute urgence relève d'un monitorage par cardioscope."},{"t":"Les électrodes précordiales doivent être équidistantes.","ok":true,"why":"C'est la règle de placement rappelée par le cours."},{"t":"V1 et V2 doivent être placées en regard des foyers auscultatoires aortique et pulmonaire.","ok":false,"why":"C'est l'erreur classique (V1-V2 trop hautes et écartées), source de pseudonécrose ou d'atypie de repolarisation antérieure."},{"t":"L'ECG peut être différé à une consultation de cardiologie programmée.","ok":false,"why":"Des palpitations aux urgences imposent un ECG immédiat."}],"explanation":"Palpitations = indication d'ECG 12 dérivations, et toute urgence justifie un monitorage. Les précordiales doivent être équidistantes, en évitant de placer V1-V2 trop haut."},"reveal":"Un monitorage est installé et un ECG 12 dérivations est enregistré.","src":"p. 371, 414","id":"231-case-51-s01"},{"phase":1,"narrative":"L'ECG montre une tachycardie régulière à 150 bpm, à QRS fins (90 ms). L'activité atriale n'est pas clairement analysable.","question":{"type":"QRU","stem":"Selon l'algorithme devant une tachycardie, à quelle origine rattachez-vous cette tachycardie ?","options":[{"t":"Supraventriculaire","ok":true,"why":"Une tachycardie régulière à QRS fins est supraventriculaire."},{"t":"Ventriculaire jusqu'à preuve du contraire","ok":false,"why":"Cette règle s'applique aux tachycardies régulières à QRS larges."},{"t":"Fibrillation atriale","ok":false,"why":"La FA donne une tachycardie irrégulière."},{"t":"Fibrillation ventriculaire","ok":false,"why":"La FV est une tachycardie irrégulière à QRS larges polymorphes avec perte de connaissance."},{"t":"Bloc atrioventriculaire","ok":false,"why":"Un BAV donne une bradycardie, pas une tachycardie."}],"explanation":"Irrégulière → FA ; régulière à QRS larges → TV jusqu'à preuve du contraire ; régulière à QRS fins → supraventriculaire."},"reveal":"Il s'agit d'une tachycardie supraventriculaire dont le mécanisme reste à préciser.","src":"p. 389, 405","id":"231-case-51-s02"},{"phase":1,"narrative":"Vous discutez les hypothèses diagnostiques.","question":{"type":"QRM","stem":"Quels diagnostics évoquez-vous devant cette tachycardie régulière à QRS fins à 150 bpm ?","options":[{"t":"Tachycardie sinusale","ok":true,"why":"Diagnostic différentiel à évoquer : la manœuvre vagale peut démasquer une activité sinusale (au repos, sans cause d'hypermétabolisme, elle est toutefois peu probable)."},{"t":"Flutter atrial conduit en 2/1","ok":true,"why":"Le flutter donne classiquement une fréquence ventriculaire de 150 bpm en 2/1."},{"t":"Tachycardie jonctionnelle","ok":true,"why":"Tachycardie très régulière, autour de 200 bpm (130-260) : 150 bpm est compatible."},{"t":"Tachycardie atriale focale","ok":true,"why":"Tachycardie régulière à QRS fins, faisant partie des TSV."},{"t":"Fibrillation ventriculaire","ok":false,"why":"La FV est irrégulière à QRS larges et entraîne un arrêt cardiaque."}],"explanation":"Devant une tachycardie régulière à QRS fins, on discute tachycardie sinusale, flutter, TAF et tachycardie jonctionnelle ; la manœuvre vagale aide à trancher."},"reveal":"La patiente étant stable, vous décidez de créer un bloc atrioventriculaire transitoire.","src":"p. 389-396, 405","id":"231-case-51-s03"},{"phase":2,"narrative":"Avant la manœuvre, vous auscultez les carotides : pas de souffle.","question":{"type":"QRM","stem":"Concernant les manœuvres vagales, quelles propositions sont exactes ?","options":[{"t":"La manœuvre de Valsalva est une expiration forcée à glotte fermée.","ok":true,"why":"C'est la définition donnée par le cours."},{"t":"La compression carotidienne doit être unilatérale.","ok":true,"why":"Le cours décrit une compression carotidienne unilatérale."},{"t":"La compression carotidienne est contre-indiquée en cas de souffle carotidien ou d'athérome important.","ok":true,"why":"Ce sont les contre-indications citées."},{"t":"Boire un grand verre d'eau froide est une manœuvre vagale possible.","ok":true,"why":"Elle figure parmi les manœuvres vagales citées."},{"t":"La compression oculaire bilatérale est la manœuvre recommandée en 1re intention.","ok":false,"why":"Elle n'est plus recommandée (risque de décollement de rétine chez le myope)."}],"explanation":"Manœuvres vagales : Valsalva, compression carotidienne unilatérale (hors athérome ou souffle), grand verre d'eau froide ; la compression oculaire n'est plus recommandée."},"reveal":"La manœuvre de Valsalva ralentit transitoirement la fréquence ventriculaire.","src":"p. 390","id":"231-case-51-s04"},{"phase":2,"narrative":"Vous envisagez l'adénosine si une nouvelle manœuvre est nécessaire.","question":{"type":"QRU","stem":"Parmi les antécédents suivants, lequel contre-indiquerait l'adénosine IV chez cette patiente ?","options":[{"t":"Un asthme","ok":true,"why":"L'asthme contre-indique l'adénosine (bronchospasme intense transitoire possible)."},{"t":"Une hypercholestérolémie traitée","ok":false,"why":"Ce n'est pas une contre-indication citée (asthme, hypotension, FA préexcitée)."},{"t":"Une hypothyroïdie substituée","ok":false,"why":"Ce n'est pas une contre-indication citée."},{"t":"Une cataracte opérée","ok":false,"why":"Ce n'est pas une contre-indication citée."},{"t":"Un âge supérieur à 70 ans","ok":false,"why":"L'âge n'est pas une contre-indication citée."}],"explanation":"L'adénosine, injectée en flash IV avec un effet d'une dizaine de secondes, est contre-indiquée en cas d'asthme, d'hypotension et de FA préexcitée."},"reveal":"Aucune contre-indication n'est retrouvée, mais la manœuvre vagale a suffi à démasquer l'activité atriale.","src":"p. 390","id":"231-case-51-s05"},{"phase":3,"narrative":"Pendant le ralentissement, on observe une activité atriale monomorphe à 300/min, en dents de scie, sans retour à la ligne isoélectrique en D2, D3 et aVF.","question":{"type":"QROC","question":"Quel est votre diagnostic ?","answer":"Flutter atrial","accept":["flutter","flutter auriculaire"],"keywords":["flutter"],"explanation":"Activité atriale monomorphe vers 300 bpm, sans retour à la ligne isoélectrique, en toit d'usine / dents de scie, démasquée par la manœuvre vagale : flutter atrial."},"reveal":"Le diagnostic de flutter atrial est retenu.","src":"p. 393-394","id":"231-case-51-s06"},{"phase":3,"narrative":"Les ondes F sont négatives en D2, D3 et aVF, positives en V1 et négatives en V6.","question":{"type":"QRU","stem":"De quel type de flutter s'agit-il ?","options":[{"t":"Flutter typique (commun) antihoraire","ok":true,"why":"F négatives en D2, D3, aVF, positives en V1, négatives en V6 = flutter typique antihoraire."},{"t":"Flutter typique horaire","ok":false,"why":"Dans la forme horaire, les polarités sont inversées."},{"t":"Flutter atypique gauche","ok":false,"why":"Les flutters atypiques ont des ondes F variables et une fréquence de 120 à 320 bpm."},{"t":"Fibrillation atriale à petites mailles","ok":false,"why":"La FA correspond à une activation atriale anarchique (intervalles RR irrégulièrement irréguliers, trémulation de la ligne de base) ; ici l'activité atriale est organisée, monomorphe, en dents de scie."},{"t":"Tachycardie jonctionnelle par réentrée intranodale","ok":false,"why":"Elle serait réduite par la manœuvre vagale, sans démasquer d'ondes F."}],"explanation":"Le flutter typique antihoraire emprunte l'isthme cavotricuspide : F négatives en inférieur, positives en V1, négatives en V6."},"reveal":"Il s'agit d'un flutter d'aspect typique antihoraire.","src":"p. 392, 394","id":"231-case-51-s07"},{"phase":3,"narrative":"Vous confrontez la fréquence atriale (300/min) et la fréquence ventriculaire initiale (150 bpm).","question":{"type":"QROC","question":"Quel rapport de conduction atrioventriculaire explique cette fréquence ventriculaire ?","answer":"Conduction 2/1","accept":["2/1","2 pour 1","deux pour un"],"keywords":["2/1"],"explanation":"Le ventricule bat classiquement à 150 bpm en 2/1, 100 bpm en 3/1, 75 bpm en 4/1, grâce au filtre du NAV."},"reveal":"Le flutter était conduit en 2/1.","src":"p. 389, 394","id":"231-case-51-s08"},{"phase":4,"narrative":"Sous traitement ralentisseur, un nouvel ECG montre des ondes F persistantes à 300/min, avec une fréquence ventriculaire devenue irrégulière.","question":{"type":"QRU","stem":"Comment interprétez-vous cette irrégularité ventriculaire ?","options":[{"t":"Flutter à conduction variable","ok":true,"why":"Le flutter est régulier le plus souvent, sinon à conduction variable (alternance 2/1-3/1…)."},{"t":"Transformation en fibrillation ventriculaire","ok":false,"why":"La FV donne des QRS larges polymorphes avec arrêt cardiaque."},{"t":"Tachycardie ventriculaire","ok":false,"why":"Les QRS restent fins et l'activité atriale organisée persiste."},{"t":"BAV du 3e degré","ok":false,"why":"Un BAV complet associé à une arythmie atriale donne un rythme ventriculaire lent et régulier."},{"t":"Extrasystoles ventriculaires","ok":false,"why":"Elles donneraient des QRS larges prématurés."}],"explanation":"Selon la fréquence atriale et l'intensité du filtre nodal (âge, tonus vagal, ralentisseurs), la conduction peut devenir variable, rendant le rythme ventriculaire irrégulier."},"reveal":"La fréquence ventriculaire est contrôlée ; la prise en charge spécialisée est organisée.","src":"p. 389, 394","id":"231-case-51-s09"},{"phase":5,"narrative":"Plusieurs mois plus tard, en rythme sinusal, Mme B. décrit des palpitations brèves survenant de façon épisodique. L'ECG de repos est normal.","question":{"type":"QRM","stem":"Quels moyens de documentation sont adaptés ?","options":[{"t":"Holter ECG de 24 à 96 h si les symptômes ont une probabilité de récidiver pendant l'enregistrement","ok":true,"why":"C'est l'indication du Holter quand l'ECG standard n'a rien montré."},{"t":"ECG ambulatoire de très longue durée (jusqu'à 21 jours) si les symptômes sont rares","ok":true,"why":"Indiqué en cas de symptômes rares."},{"t":"Enregistreur d'événements, y compris une montre connectée ECG","ok":true,"why":"Ces outils sont très utiles pour documenter des palpitations peu fréquentes."},{"t":"Répéter un ECG de repos, qui suffit toujours à conclure","ok":false,"why":"L'ECG standard n'a rien montré : il faut un enregistrement de longue durée."},{"t":"Hospitalisation systématique en réanimation sous monitorage","ok":false,"why":"Ce n'est pas une indication citée du monitorage pour des palpitations épisodiques bien tolérées."}],"explanation":"Symptômes épisodiques avec ECG normal : Holter 24-96 h ; symptômes rares : ECG ambulatoire jusqu'à 21 jours, enregistreurs d'événements ou objets connectés."},"reveal":"Un Holter est programmé et la patiente est éduquée à l'enregistrement de ses symptômes.","src":"p. 415","id":"231-case-51-s10"}]}],"ecg":{"data":[{"id":"231-ecg-01","title":"ECG normal de l'adulte","rank":"A","objective":"231-obj-01","ecg":{"rhythm":"sinus","rate":72,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Tracé normal de repos, repolarisation physiologique."},"findings":["Rythme sinusal régulier à 72/min (onde P positive en D1, D2, D3, aVF, une P avant chaque QRS et un QRS après chaque P)","Onde P de durée et d'amplitude normales","PR constant à 160 ms (120-200 ms)","QRS fins à 80 ms, axe normal autour de 60°","Ondes T positives dans toutes les dérivations sauf en aVR","QT/QTc dans les limites de la normale (< 450 ms)"],"diagnosis":"ECG normal","teaching":"**Méthode de lecture systématique (à appliquer à chaque ECG) :**\n1. *Rythme* : sinusal si onde P positive en D1/D2/D3/aVF, une P avant chaque QRS et un QRS après chaque P, fréquence 60-100/min.\n2. *Conduction* : durée de P < 120 ms, PR entre 120 et 200 ms, QRS fins entre 70 et 110 ms avec un axe entre -30° et +90°.\n3. *Repolarisation* : point J et segment ST isoélectriques, ondes T positives sauf en aVR (et parfois V1, D3, aVL), QT < 450 ms.\n4. *Morphologie* : amplitude des ondes P et des QRS normales (indice de Sokolow < 35 mm), transition de l'onde R normale de V1 à V6, absence d'onde Q de nécrose (> 1/3 du QRS et > 40 ms).\n\n**Piège classique** : chez le sujet jeune, un léger sus-décalage du point J de V1 à V4 avec pente ascendante (repolarisation précoce physiologique) ne doit pas être pris pour une anomalie.","quiz":{"stem":"Quelle est la conclusion de cet ECG ?","options":["ECG normal","Bloc atrioventriculaire du 1er degré","Hypertrophie ventriculaire gauche","Bloc de branche droit incomplet"],"correct":0},"src":"p. 376-378"},{"id":"231-ecg-02","title":"Bloc atrioventriculaire du 1er degré","rank":"A","objective":"231-obj-08","ecg":{"rhythm":"sinus","rate":66,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.24,"avBlock":"1","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Allongement fixe et constant du PR, sans onde P bloquée."},"findings":["Rythme sinusal régulier","Chaque onde P est suivie d'un QRS (conduction 1/1)","PR allongé et constant à 240 ms (> 200 ms)","QRS fins, morphologie normale par ailleurs","Aucune onde P bloquée"],"diagnosis":"Bloc atrioventriculaire du 1er degré","teaching":"**Définition** : ralentissement de la conduction atrioventriculaire sans interruption — toutes les ondes P sont conduites, mais avec un PR fixe et allongé (> 200 ms).\n\n**Diagnostic différentiel** : à distinguer d'un BAV du 2e degré Mobitz 1 (allongement progressif du PR puis onde P bloquée).\n\n**Conduite à tenir** : généralement bénin et asymptomatique ; rechercher un contexte de bradycardie fonctionnelle (sportif) ou un traitement ralentisseur du NAV. Surveillance simple en l'absence de bloc de branche associé.","quiz":{"stem":"Quel est le mécanisme du bloc atrioventriculaire du premier degré ?","options":["Un ralentissement de la conduction atrioventriculaire sans blocage complet","Un blocage intermittent d'une onde P sur deux","Une dissociation complète entre oreillettes et ventricules","Un allongement progressif du PR jusqu'à une onde P bloquée"],"correct":0},"src":"p. 385-386"},{"id":"231-ecg-03","title":"Bloc atrioventriculaire du 2e degré, Mobitz 1 (Wenckebach)","rank":"A","objective":"231-obj-08","ecg":{"rhythm":"sinus","rate":60,"irregular":true,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.18,"avBlock":"2m1","ratio":"3:2","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Allongement progressif du PR à chaque cycle jusqu'à une onde P bloquée, puis reprise du cycle (périodicité de Wenckebach)."},"findings":["Rythme atrial sinusal régulier","Allongement progressif du PR d'un battement à l'autre","Une onde P bloquée termine la séquence (non suivie de QRS)","QRS fins, cycle qui se répète de façon périodique","Rythme ventriculaire irrégulier du fait des ondes P bloquées"],"diagnosis":"Bloc atrioventriculaire du 2e degré, Mobitz 1 (Luciani-Wenckebach)","teaching":"**Critères** : allongement progressif du PR jusqu'à une onde P bloquée, puis reprise du cycle avec un PR redevenu court.\n\n**Localisation** : suprahissien (nodal), à la différence du Mobitz 2, infrahissien.\n\n**Conduite à tenir** : pacemaker seulement si la bradycardie est symptomatique (le Mobitz 2 et le BAV3 relèvent d'un pacemaker même sans symptôme).","quiz":{"stem":"Quel signe caractérise le bloc atrioventriculaire du 2e degré Mobitz 1 ?","options":["Un allongement progressif du PR avant l'onde P bloquée","Un PR constant puis une onde P bloquée inopinée","Une onde P bloquée sur deux de façon fixe","Une dissociation atrioventriculaire complète"],"correct":0},"src":"p. 385-386, 412"},{"id":"231-ecg-04","title":"Bloc atrioventriculaire du 2e degré, Mobitz 2 (infrahissien)","rank":"A","objective":"231-obj-08","ecg":{"rhythm":"sinus","rate":55,"irregular":true,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"2m2","ratio":"3:2","qrs":{"dur":0.13,"bbb":"rbbb","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"PR constant puis onde P bloquée inopinée, QRS larges évoquant une atteinte infrahissienne."},"findings":["Rythme atrial sinusal régulier","PR constant sur les battements conduits","Onde P bloquée inopinée, sans allongement préalable du PR","QRS larges (atteinte infrahissienne associée)","Plus d'ondes P que de QRS : le problème est le passage au ventricule"],"diagnosis":"Bloc atrioventriculaire du 2e degré, Mobitz 2","teaching":"**Critères** : PR constant puis onde P bloquée inopinée, sans allongement préalable du PR.\n\n**Siège** : infrahissien ; des QRS larges orientent aussi vers un siège infrahissien (règle donnée pour le BAV 2/1).\n\n**Conduite à tenir** : indication de pacemaker même en l'absence de symptôme (BAV infrahissien), alors que le Mobitz 1 n'est appareillé que s'il est symptomatique.","quiz":{"stem":"Quelle caractéristique oriente vers un Mobitz 2 plutôt qu'un Mobitz 1 ?","options":["Un PR constant avant l'onde P bloquée","Un allongement progressif du PR","Une fréquence atriale irrégulière","L'absence totale d'onde P"],"correct":0},"src":"p. 385, 389, 412"},{"id":"231-ecg-05","title":"Bloc atrioventriculaire complet (3e degré)","rank":"A","objective":"231-obj-08","ecg":{"rhythm":"sinus","rate":38,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"3","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Dissociation atrioventriculaire complète : ondes P régulières indépendantes des QRS ; échappement jonctionnel à QRS fins, régulier et lent."},"findings":["Ondes P régulières à fréquence normale, sans relation avec les QRS (dissociation atrioventriculaire)","QRS fins, réguliers et lents (échappement jonctionnel nodal)","Fréquence ventriculaire basse, autour de 40/min","Plus d'ondes P que de QRS"],"diagnosis":"Bloc atrioventriculaire complet (3e degré) à QRS fins","teaching":"**Critères** : dissociation atrioventriculaire complète, ondes P régulières à fréquence normale indépendantes des QRS ; rythme d'échappement lent et régulier. Échappement à **QRS fins** = bloc nodal (suprahissien) ; échappement à **QRS larges** = BAV bas situé (infrahissien).\n\n**Diagnostic différentiel** : à ne pas confondre avec la dissociation par tachycardie ventriculaire (ici bradycardie).\n\n**Conduite à tenir** : indication de pacemaker, même en l'absence de symptôme.","quiz":{"stem":"Quel élément affirme le diagnostic de bloc atrioventriculaire complet ?","options":["Une dissociation complète entre ondes P régulières et QRS","Un allongement progressif du PR","Une onde P bloquée sur deux de façon fixe","Un PR court avec onde delta"],"correct":0},"src":"p. 385-387, 392, 400, 404, 412"},{"id":"231-ecg-06","title":"Bloc de branche droit complet","rank":"A","objective":"231-obj-06","ecg":{"rhythm":"sinus","rate":78,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.14,"bbb":"rbbb","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":1.6,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Aspect RsR' en V1, onde S traînante et arrondie en V6."},"findings":["Rythme sinusal régulier","Durée du QRS > 120 ms","Aspect RsR' en V1 (QRS globalement positif)","Onde S empâtée et arrondie en V6","Discordance appropriée : onde T négative en V1"],"diagnosis":"Bloc de branche droit complet","teaching":"**Critères** : QRS > 120 ms, aspect RsR' en V1 (QRS globalement positif), aspect qRs avec onde S traînante en V6.\n\n**Méthode** : vérifier d'abord le rythme atrial, puis la durée du QRS, puis la polarité en V1 (positive = droit), puis l'aspect inverse en V6.\n\n**Piège** : la discordance appropriée entre QRS et repolarisation (onde T négative si QRS positif) ne doit pas être confondue avec une ischémie.","quiz":{"stem":"Quel aspect en V1 oriente vers un bloc de branche droit complet ?","options":["QRS globalement positif avec aspect RsR'","QRS globalement négatif avec aspect rS","Onde delta avec PR court","Sus-décalage concave diffus du ST"],"correct":0},"src":"p. 379"},{"id":"231-ecg-07","title":"Bloc de branche gauche complet","rank":"A","objective":"231-obj-06","ecg":{"rhythm":"sinus","rate":80,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.15,"bbb":"lbbb","lvh":false,"rvh":false,"delta":false,"axis":-10,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{"V1":1,"V2":1},"dep":{},"shape":"concave"},"t":{"inverted":["I","aVL","V5","V6"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"QRS globalement négatif en V1 (rS ou QS), notch en V6/D1/aVL avec onde R exclusive ; discordance appropriée ST/T."},"findings":["Rythme sinusal régulier","Durée du QRS > 120 ms","QRS globalement négatif en V1 (aspect rS ou QS)","Notch (double pic) en V6, D1 et aVL avec onde R exclusive","Discordance appropriée : sus-décalage de ST en V1-V2, onde T négative en D1/aVL/V5/V6"],"diagnosis":"Bloc de branche gauche complet","teaching":"**Critères** : QRS > 120 ms, QRS négatif en V1, notch en V6/D1/aVL.\n\n**Piège majeur** : la discordance appropriée (ST ascendant en V1-V2) peut simuler un syndrome coronarien aigu avec sus-décalage du ST. Devant une douleur thoracique persistante avec BBG, il faut évoquer un infarctus antérieur et demander un avis cardiologique rapide sans attendre la troponine.\n\n**Conséquence hémodynamique** : un BBG complet désynchronise la contraction ventriculaire gauche et peut créer ou aggraver une insuffisance cardiaque, justifiant une resynchronisation cardiaque si l'insuffisance cardiaque apparaît.","quiz":{"stem":"Devant une douleur thoracique persistante avec un bloc de branche gauche complet, que faut-il faire ?","options":["Évoquer un infarctus et demander un avis cardiologique rapide sans attendre la troponine","Éliminer d'emblée le diagnostic de syndrome coronarien car le BBG masque tout","Attendre le résultat de la troponine avant toute décision","Considérer ce tracé comme un équivalent de péricardite aiguë"],"correct":0},"src":"p. 380-381"},{"id":"231-ecg-08","title":"Hémibloc antérieur gauche","rank":"A","objective":"231-obj-06","ecg":{"rhythm":"sinus","rate":74,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.11,"bbb":"lahb","lvh":false,"rvh":false,"delta":false,"axis":-60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Déviation axiale gauche au-delà de -30°, négativité de DII."},"findings":["Rythme sinusal régulier","Élargissement modéré du QRS (autour de 110 ms)","Déviation axiale gauche au-delà de -30° (négativité de DII et DIII)","Absence d'autre cause de déviation axiale gauche"],"diagnosis":"Hémibloc antérieur gauche","teaching":"**Critères** : élargissement modéré du QRS et déviation axiale gauche au-delà de -30° (négativité de DII).\n\n**Fréquence** : c'est l'hémibloc le plus fréquent car la branche antérieure gauche est fine et superficielle, donc fragile.\n\n**Valeur** : isolé, il traduit une atteinte débutante du réseau de conduction avec un faible risque de bloc atrioventriculaire infrahissien.","quiz":{"stem":"Quel signe définit l'hémibloc antérieur gauche ?","options":["Une déviation axiale gauche au-delà de -30° avec négativité de DII","Un QRS globalement positif en V1","Un PR court avec onde delta","Une onde P bloquée sur deux"],"correct":0},"src":"p. 382"},{"id":"231-ecg-09","title":"Bloc bifasciculaire (hémibloc antérieur gauche + bloc de branche droit)","rank":"A","objective":"231-obj-06","ecg":{"rhythm":"sinus","rate":72,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.13,"bbb":"bifascicular","lvh":false,"rvh":false,"delta":false,"axis":-60,"qWaves":[],"lowVoltage":false,"rsRatioV1":1.5,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Association d'un axe hypergauche (HBAG) et d'un aspect RsR' en V1 (BBD)."},"findings":["Rythme sinusal régulier","QRS > 120 ms","Axe hypergauche avec négativité en DII, DIII, aVF (hémibloc antérieur gauche)","Aspect RsR' en V1 (bloc de branche droit complet)"],"diagnosis":"Bloc bifasciculaire (hémibloc antérieur gauche + bloc de branche droit)","teaching":"**Sémiologie** : addition des critères de l'hémibloc et du bloc de branche droit.\n\n**Risque** : atteinte de deux des trois fascicules, avec un risque non négligeable de bloc atrioventriculaire complet infrahissien intermittent, pouvant se manifester par des syncopes voire une mort subite.\n\n**Conduite à tenir** : toute syncope associée à un bloc bifasciculaire impose une hospitalisation en cardiologie avec télémétrie.","quiz":{"stem":"Que faut-il faire devant une syncope associée à un bloc bifasciculaire ?","options":["Hospitaliser en cardiologie sous télémétrie","Rassurer et renvoyer le patient à domicile","Prescrire un traitement bêtabloquant en urgence","Réaliser uniquement un holter en ambulatoire différé"],"correct":0},"src":"p. 383"},{"id":"231-ecg-10","title":"Dysfonction sinusale (pause par bloc sino-atrial)","rank":"A","objective":"231-obj-10","ecg":{"rhythm":"sinusBrady","rate":46,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":2.0,"pacer":{"mode":"none"},"notes":"Pause correspondant au double de l'intervalle PP/RR normal, par manque intermittent d'une onde P (bloc sino-atrial du 2e degré)."},"findings":["Bradycardie sinusale de base","Pause avec absence complète d'un complexe P-QRS-T","La pause correspond au double de l'intervalle PP habituel","Reprise ensuite d'un rythme sinusal normal","Peut évoluer vers un échappement jonctionnel si la pause se prolonge"],"diagnosis":"Dysfonction sinusale (bloc sino-atrial du 2e degré)","teaching":"**Mécanismes** : ondes P trop lentes, onde P manquante isolée (bloc sino-atrial), pause sinusale, ou onde P inexistante remplacée par une activité rétrograde (échappement jonctionnel).\n\n**Piège devant une bradycardie** : regarder les ondes P — si elles sont régulières à fréquence normale (ou tachycardes comme en FA/flutter) avec plus d'ondes P que de QRS, le problème est le passage au ventricule (BAV) ; si les ondes P sont trop lentes ou absentes, le problème vient du nœud sinusal.\n\n**Conduite à tenir** : pacemaker si bradycardie symptomatique.","quiz":{"stem":"Devant une bradycardie, quel élément oriente vers une dysfonction sinusale plutôt qu'un bloc atrioventriculaire ?","options":["Des ondes P trop lentes ou absentes","Plus d'ondes P que de QRS à fréquence atriale normale","Un PR court avec onde delta","Un QRS large en dents de scie"],"correct":0},"src":"p. 387-389"},{"id":"231-ecg-11","title":"Fibrillation atriale","rank":"A","objective":"231-obj-13","ecg":{"rhythm":"af","rate":128,"irregular":true,"p":{"present":false,"amp":0.05,"dur":0.0,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.0,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Trémulation ou mailles anarchiques de la ligne de base, intervalles RR irrégulièrement irréguliers."},"findings":["Absence d'onde P, activité atriale anarchique (mailles amples ou fine trémulation)","Intervalles RR irrégulièrement irréguliers (non multiples d'une valeur commune)","QRS fins en l'absence de bloc de branche associé","Fréquence ventriculaire entre 100 et 200/min","Aucune relation constante entre activité atriale et QRS"],"diagnosis":"Fibrillation atriale","teaching":"**Critères** : tachycardie irrégulière à QRS fins (sauf bloc de branche associé), sans onde P identifiable.\n\n**Formes particulières** : association à un bloc atrioventriculaire complet (activité ventriculaire devenant lente et régulière), alternance avec une dysfonction sinusale (« maladie de l'oreillette »), ou association à un bloc de branche fonctionnel donnant une tachycardie irrégulière à QRS larges.\n\n**Conduite à tenir** : la fibrillation atriale est le seul diagnostic à évoquer devant une tachycardie complètement irrégulière à QRS fins.","quiz":{"stem":"Quel est le seul diagnostic à évoquer devant une tachycardie complètement irrégulière à QRS fins ?","options":["La fibrillation atriale","Le flutter atrial","La tachycardie jonctionnelle","La tachycardie ventriculaire"],"correct":0},"src":"p. 391-393"},{"id":"231-ecg-12","title":"Flutter atrial typique (antihoraire)","rank":"A","objective":"231-obj-14","ecg":{"rhythm":"flutter","rate":150,"irregular":false,"p":{"present":true,"amp":0.1,"dur":0.0,"inverted":["II","III","aVF"],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"2:1","ratio":"2:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Ondes F en dents de scie à ~300/min, négatives en II/III/aVF, positives en V1, sans retour à la ligne isoélectrique."},"findings":["Activité atriale monomorphe rapide, environ 300/min (ondes F)","Aspect en dents de scie, négatif en II, III, aVF, positif en V1, négatif en V6","Absence de retour à la ligne isoélectrique entre les ondes F","Conduction atrioventriculaire le plus souvent 2/1, donnant une cadence ventriculaire régulière à 150/min","Activité atriale démasquée par une manœuvre vagale"],"diagnosis":"Flutter atrial typique (antihoraire)","teaching":"**Mécanisme** : réentrée autour de l'isthme cavotricuspide, activation atriale organisée en circuit (par opposition au caractère fibrillatoire de la FA).\n\n**Cadence ventriculaire** : le plus souvent 150/min (conduction 2/1), parfois 100/min (3/1) ou à conduction variable.\n\n**Diagnostic** : les manœuvres vagales ou l'adénosine, en bloquant transitoirement le NAV, démasquent les ondes F sans arrêter le flutter (le circuit ne dépend pas du NAV).","quiz":{"stem":"Quel est l'effet d'une manœuvre vagale sur un flutter atrial ?","options":["Elle démasque l'activité atriale sans arrêter l'arythmie","Elle arrête définitivement le flutter","Elle n'a strictement aucun effet visible","Elle transforme le flutter en tachycardie ventriculaire"],"correct":0},"src":"p. 393-395"},{"id":"231-ecg-13","title":"Tachycardie jonctionnelle par réentrée intranodale (maladie de Bouveret)","rank":"A","objective":"231-obj-15","ecg":{"rhythm":"svt","rate":190,"irregular":false,"p":{"present":false,"amp":0.0,"dur":0.0,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Activité atriale non visible ou devinée dans le segment ST, activation atriale et ventriculaire quasi synchrone."},"findings":["Tachycardie très régulière à QRS fins, autour de 190/min","Absence d'onde P visible (activation atriale rétrograde quasi synchrone du QRS)","Début et fin brusques, non progressifs","Réduction par manœuvres vagales ou adénosine IV"],"diagnosis":"Tachycardie jonctionnelle par réentrée intranodale","teaching":"**Mécanisme** : réentrée au sein du nœud atrioventriculaire ; activation atriale et ventriculaire quasi synchrone, d'où une onde P invisible ou devinée dans le segment ST (maladie de Bouveret).\n\n**Diagnostic différentiel** : l'autre forme est la tachycardie par rythme réciproque, réentrée par une voie accessoire (faisceau de Kent).\n\n**Conduite à tenir** : manœuvres vagales ou adénosine IV en première intention, efficaces car la réentrée dépend du NAV.","quiz":{"stem":"Pourquoi l'adénosine est-elle efficace pour arrêter une tachycardie jonctionnelle par réentrée intranodale ?","options":["Parce que la réentrée dépend du nœud atrioventriculaire, qu'elle bloque transitoirement","Parce qu'elle a un effet inotrope négatif puissant","Parce qu'elle dépolarise directement le foyer atrial","Parce qu'elle accélère la conduction dans la voie accessoire"],"correct":0},"src":"p. 395-397"},{"id":"231-ecg-14","title":"Extrasystoles ventriculaires","rank":"A","objective":"231-obj-17","ecg":{"rhythm":"sinus","rate":70,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"pvc","every":6,"bigeminy":false,"run":1},"pause":0,"pacer":{"mode":"none"},"notes":"Battement prématuré à QRS large, non précédé d'onde P, suivi d'une pause compensatrice."},"findings":["Rythme de fond sinusal régulier","Battement prématuré à QRS large, non précédé d'une onde P","Pause compensatrice après l'extrasystole","Morphologie du QRS différente de celle du rythme de base","Onde T souvent de polarité opposée au QRS de l'extrasystole"],"diagnosis":"Extrasystoles ventriculaires","teaching":"**Définition** : activation prématurée par rapport au rythme attendu ; fréquentes et physiologiques sur cœur sain, leur charge augmentant avec l'âge et les cardiopathies.\n\n**Diagnostic différentiel** : extrasystole atriale (onde P prématurée puis QRS fin) et extrasystole jonctionnelle (QRS fin ± onde P' rétrograde), toutes deux à QRS fins, contrairement à l'extrasystole ventriculaire (QRS large).\n\n**Conduite à tenir** : des extrasystoles fréquentes ou polymorphes doivent faire rechercher une cardiopathie sous-jacente.","quiz":{"stem":"Quel critère distingue une extrasystole ventriculaire d'une extrasystole atriale ?","options":["Un QRS large non précédé d'une onde P","Une onde P prématurée suivie d'un QRS fin","Un PR progressivement allongé","Une fréquence cardiaque supérieure à 150/min"],"correct":0},"src":"p. 397-398"},{"id":"231-ecg-15","title":"Tachycardie ventriculaire monomorphe","rank":"A","objective":"231-obj-18","ecg":{"rhythm":"vt","rate":180,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.16,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":-100,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Dissociation ventriculo-atriale, complexes de fusion/capture, concordance des précordiales, axe extrême."},"findings":["Tachycardie régulière à QRS larges (> 120 ms), autour de 180/min","Dissociation ventriculo-atriale (plus de QRS que d'ondes P)","Complexes de fusion et de capture intercalés dans le tracé","Axe extrême avec positivité exclusive en aVR","Cardiopathie sous-jacente fréquemment retrouvée"],"diagnosis":"Tachycardie ventriculaire monomorphe","teaching":"**Règle d'or** : toute tachycardie régulière à QRS larges est une tachycardie ventriculaire jusqu'à preuve du contraire.\n\n**Arguments de certitude** : dissociation ventriculo-atriale, complexes de capture (QRS fin précédé d'une onde P) ou de fusion (QRS intermédiaire).\n\n**Arguments en faveur** : cardiopathie sous-jacente, concordance positive ou négative de V1 à V6, déviation axiale extrême (positivité en aVR), morphologie différente d'un bloc de branche habituel.\n\n**Conduite à tenir** : urgence — alerter (SAMU), se préparer à une réanimation ; distinguer TV non soutenue (≤ 30 s) de TV soutenue (> 30 s).","quiz":{"stem":"Face à une tachycardie régulière à QRS larges, quelle est l'attitude par défaut ?","options":["La considérer comme une tachycardie ventriculaire jusqu'à preuve du contraire","L'attribuer d'emblée à une tachycardie supraventriculaire avec bloc de branche","Réaliser un massage sino-carotidien immédiat sans surveillance","Attendre le résultat de la troponine avant toute décision"],"correct":0},"src":"p. 398-402"},{"id":"231-ecg-16","title":"Fibrillation ventriculaire","rank":"A","objective":"231-obj-19","ecg":{"rhythm":"vf","rate":280,"irregular":true,"p":{"present":false,"amp":0,"dur":0,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.2,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Tracé totalement anarchique, oscillations de taille et de forme variables, sans QRS identifiable."},"findings":["Activité ventriculaire totalement anarchique","Absence de QRS, de segment ST et d'onde T identifiables","Oscillations de taille et de forme variables (larges puis fines)","Absence d'activité mécanique efficace : arrêt cardiocirculatoire"],"diagnosis":"Fibrillation ventriculaire","teaching":"**Reconnaissance** : tracé anarchique sans complexe identifiable, urgence absolue.\n\n**Conduite à tenir** : cardioversion électrique (choc électrique) immédiate avant tout autre geste, massage cardiaque en attendant le choc.\n\n**Diagnostic différentiel** : parfois indiscernable d'une torsade de pointes installée ; seuls le QT long préalable et le contexte (ischémie/cardiopathie évoluée pour la FV) permettent de trancher.","quiz":{"stem":"Quelle est la conduite à tenir immédiate devant une fibrillation ventriculaire ?","options":["Cardioversion électrique immédiate et massage cardiaque en attendant le choc","Manœuvre vagale puis adénosine IV","Surveillance scope sans geste immédiat","Correction ionique puis réévaluation à 24 heures"],"correct":0},"src":"p. 402-403"},{"id":"231-ecg-17","title":"Torsades de pointes sur QT long","rank":"B","objective":"231-obj-20","ecg":{"rhythm":"torsades","rate":220,"irregular":true,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.54,"u":true,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Tachycardie ventriculaire polymorphe avec torsion des QRS autour de la ligne isoélectrique, survenant sur un QT long."},"findings":["QT long avant le trouble du rythme (souvent > 500 ms)","Tachycardie ventriculaire polymorphe à QRS d'amplitude et de polarité variables","Aspect de torsion des QRS autour de la ligne isoélectrique","Peut s'arrêter spontanément ou dégénérer en fibrillation ventriculaire","Rechercher une hypokaliémie, une hypocalcémie, une hypomagnésémie ou un médicament allongeant le QT"],"diagnosis":"Torsades de pointes","teaching":"**Reconnaissance** : forme particulière de tachycardie ventriculaire polymorphe, parfois indiscernable d'une fibrillation ventriculaire une fois installée ; seuls le QT long préexistant et le contexte orientent le diagnostic.\n\n**Étiologies** : bradycardie extrême, hypokaliémie, hypocalcémie, hypomagnésémie, médicaments allongeant le QT, syndrome du QT long congénital.\n\n**Conduite à tenir** : corriger les troubles ioniques, accélérer la fréquence cardiaque, arrêter les médicaments allongeant le QT.","quiz":{"stem":"Quel élément permet de différencier une torsade de pointes d'une fibrillation ventriculaire ?","options":["La présence d'un QT long avant le trouble du rythme et le contexte clinique","La largeur du QRS pendant l'arythmie","La fréquence cardiaque pendant l'arythmie","La présence d'ondes P visibles pendant l'arythmie"],"correct":0},"src":"p. 403-404"},{"id":"231-ecg-18","title":"Hyperkaliémie","rank":"A","objective":"231-obj-21","ecg":{"rhythm":"sinusBrady","rate":52,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.24,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.14,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":[],"peaked":true,"flat":false,"amp":0.9},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Ondes T amples, pointues et symétriques ; allongement du PR ; élargissement du QRS ; risque de BAV, TV, dysfonction sinusale."},"findings":["Ondes T amples, pointues et symétriques (« en tente »)","Allongement de l'intervalle PR","Élargissement progressif du QRS","Bradycardie ou dysfonction sinusale possible","Risque de bloc atrioventriculaire ou de tachycardie ventriculaire"],"diagnosis":"Hyperkaliémie","teaching":"**Signes ECG (par ordre d'apparition avec l'aggravation)** : ondes T amples, pointues et symétriques ; allongement du PR ; élargissement du QRS ; puis bloc atrioventriculaire, tachycardie ventriculaire ou dysfonction sinusale.\n\n**Conduite à tenir** : toute anomalie évocatrice impose un contrôle urgent de la kaliémie et un traitement adapté (risque de trouble du rythme grave).","quiz":{"stem":"Quel est le signe ECG le plus précoce de l'hyperkaliémie ?","options":["Des ondes T amples, pointues et symétriques","Un allongement isolé du QT","Une onde U proéminente","Un sus-décalage diffus du segment ST"],"correct":0},"src":"p. 408-409"},{"id":"231-ecg-19","title":"Hypokaliémie","rank":"A","objective":"231-obj-21","ecg":{"rhythm":"sinus","rate":82,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{"V2":0.5,"V3":0.5},"shape":"horizontal"},"t":{"inverted":[],"peaked":false,"flat":true,"amp":0.1},"qt":0.48,"u":true,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Onde T plate ou négative diffuse, sous-décalage de ST, allongement du QT et onde U."},"findings":["Onde T plate ou négative, de façon diffuse","Sous-décalage du segment ST","QRS de durée normale","Allongement de l'intervalle QT","Apparition d'une onde U (à ne pas inclure dans la mesure du QT)"],"diagnosis":"Hypokaliémie","teaching":"**Signes ECG** : onde T plate ou négative diffuse avec sous-décalage de ST, QRS normal, allongement du QT et apparition d'une onde U.\n\n**Risque rythmique** : extrasystoles, tachycardie ventriculaire, torsades de pointes, fibrillation ventriculaire.\n\n**Conduite à tenir** : correction de la kaliémie, recherche et traitement de la cause.","quiz":{"stem":"Quelle onde supplémentaire peut apparaître en cas d'hypokaliémie, sans devoir être incluse dans la mesure du QT ?","options":["L'onde U","L'onde delta","L'onde F","L'onde Q pathologique"],"correct":0},"src":"p. 408"},{"id":"231-ecg-20","title":"Allongement de l'intervalle QT","rank":"A","objective":"231-obj-22","ecg":{"rhythm":"sinus","rate":64,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.52,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Allongement isolé du QT, à corréler au contexte médicamenteux, ionique ou génétique."},"findings":["Rythme sinusal régulier","QT corrigé nettement allongé (> 480-500 ms)","QRS et PR de durée normale","Absence d'anomalie ionique visible sur ce tracé isolé","Rechercher une cause médicamenteuse, ionique (hypokaliémie, hypocalcémie, hypomagnésémie) ou génétique"],"diagnosis":"Allongement de l'intervalle QT","teaching":"**Mesure** : du début du Q à la fin de l'onde T, dans la dérivation où l'onde T est la plus ample (souvent V2-V3), corrigé par la formule de Bazett pour une fréquence de 60/min.\n\n**Étiologies** : bradycardie extrême, hypokaliémie, hypocalcémie, hypomagnésémie, médicaments allongeant le QT, syndrome du QT long congénital.\n\n**Conduite à tenir** : tout QT allongé impose de vérifier les traitements en cours et le ionogramme, afin de prévenir le risque de torsades de pointes et de mort subite.","quiz":{"stem":"Quelle formule est utilisée pour corriger le QT en fonction de la fréquence cardiaque ?","options":["La formule de Bazett","L'indice de Sokolow","La règle des grands carreaux","La formule de Wenckebach"],"correct":0},"src":"p. 404"},{"id":"231-ecg-21","title":"Péricardite aiguë (stade 1)","rank":"B","objective":"231-obj-23","ecg":{"rhythm":"sinus","rate":92,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":true,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{"I":1,"II":1.5,"III":1,"aVF":1,"V5":1.5,"V6":1.5},"dep":{},"shape":"concave"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":true,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Sus-décalage diffus concave vers le haut, sans image en miroir, sous-décalage du segment PQ, microvoltage possible."},"findings":["Sus-décalage du segment ST diffus, concave vers le haut, concordant","Absence d'image en miroir","Sous-décalage du segment PQ (PR)","Microvoltage possible, d'autant plus marqué que l'épanchement est abondant","Absence de territoire coronaire systématisé"],"diagnosis":"Péricardite aiguë (stade 1)","teaching":"**Évolution en 4 phases** : phase 1 (sus-décalage diffus concave sans miroir, sous-décalage de PQ, microvoltage), phase 2 (onde T plate, ST isoélectrique), phase 3 (onde T négative persistante), phase 4 (retour à la normale).\n\n**Piège** : ne pas conclure à tort à une péricardite devant un syndrome coronarien aigu avec sus-décalage de ST, car l'image en miroir peut manquer dans les deux cas ; le caractère diffus, concave et concordant, avec sous-décalage de PQ, oriente vers la péricardite.","quiz":{"stem":"Quel aspect du segment ST évoque une péricardite aiguë au stade initial ?","options":["Un sus-décalage diffus, concave vers le haut, sans image en miroir","Un sus-décalage localisé, convexe, avec miroir net","Un sous-décalage horizontal localisé","Une onde de Pardee systématisée à un territoire"],"correct":0},"src":"p. 409-410"},{"id":"231-ecg-22","title":"Syndrome coronarien aigu avec sus-décalage du ST (territoire inférieur)","rank":"A","objective":"231-obj-24","ecg":{"rhythm":"sinus","rate":88,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":["III"],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{"II":3,"III":3.5,"aVF":3},"dep":{"I":1,"aVL":1},"shape":"convex"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Sus-décalage convexe englobant l'onde T (onde de Pardee) dans le territoire inférieur, miroir en D1-aVL."},"findings":["Sus-décalage du segment ST ≥ 1 mm sur au moins 2 dérivations inférieures adjacentes (II, III, aVF)","Sus-décalage convexe englobant l'onde T (onde de Pardee)","Image en miroir en D1 et aVL (sous-décalage)","Onde Q de nécrose débutante possible en D3","Territoire inférieur : occlusion probable de la coronaire droite"],"diagnosis":"Syndrome coronarien aigu avec sus-décalage du ST (territoire inférieur)","teaching":"**Critères de sus-décalage significatif** : au moins 2 mm en V1-V3, au moins 1 mm dans les autres dérivations, sur au moins 2 dérivations adjacentes.\n\n**Méthode** : traquer d'abord le sus-décalage (qui indique le territoire occlus), puis chercher le miroir sous forme de sous-décalage, jamais l'inverse.\n\n**Ondes Q de nécrose** : apparaissent en général vers la 6e heure, mais peuvent être précoces ; leur présence ne doit pas faire renoncer à une reperfusion jugée utile.\n\n**Diagnostics différentiels du sus-décalage** : anévrisme ventriculaire, repolarisation précoce, angor de Prinzmetal, péricardite, bloc de branche gauche, hypertrophie ventriculaire gauche marquée.","quiz":{"stem":"Quelle est la démarche correcte pour interpréter un sus-décalage du ST évocateur de SCA ?","options":["Repérer le sus-décalage qui indique le territoire occlus, puis chercher le miroir sous forme de sous-décalage","Repérer d'abord le sous-décalage puis en déduire le territoire occlus","Ignorer le miroir car il est toujours présent","Considérer que l'absence de miroir élimine le diagnostic"],"correct":0},"src":"p. 411-412"},{"id":"231-ecg-23","title":"Syndrome coronarien aigu sans sus-décalage du ST","rank":"A","objective":"231-obj-24","ecg":{"rhythm":"sinus","rate":94,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.09,"bbb":"none","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{"V4":1.5,"V5":2,"V6":1.5},"shape":"horizontal"},"t":{"inverted":["V4","V5","V6"],"peaked":false,"flat":false,"amp":0.2},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Sous-décalage horizontal antérolatéral avec ondes T négatives ; un ECG normal n'élimine pas le diagnostic."},"findings":["Sous-décalage du segment ST horizontal dans le territoire antérolatéral","Ondes T négatives associées possibles","QRS fins, durée normale","Absence de sus-décalage du segment ST","Un ECG strictement normal n'élimine pas le diagnostic"],"diagnosis":"Syndrome coronarien aigu sans sus-décalage du ST","teaching":"**Aspects possibles** : sous-décalage de ST (lésion sous-endocardique), inversion des ondes T (ischémie sous-épicardique), pseudo-normalisation d'ondes T antérieurement négatives, aplatissement des ondes T, ou ECG normal.\n\n**Piège** : les anomalies peuvent être masquées par un pacemaker.\n\n**Conduite à tenir** : un ECG strictement normal ne permet jamais d'éliminer un syndrome coronarien aigu ; le diagnostic repose sur la clinique et la biologie (troponine).","quiz":{"stem":"Un ECG parfaitement normal permet-il d'éliminer un syndrome coronarien aigu sans sus-décalage du ST ?","options":["Non, un ECG normal est possible dans ce cadre","Oui, cela élimine formellement le diagnostic","Seulement si la fréquence cardiaque est basse","Seulement chez le sujet jeune"],"correct":0},"src":"p. 412-413"},{"id":"231-ecg-24","title":"Préexcitation ventriculaire (Wolff-Parkinson-White)","rank":"B","objective":"231-obj-25","ecg":{"rhythm":"wpw","rate":76,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.1,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.12,"bbb":"none","lvh":false,"rvh":false,"delta":true,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["V1","V2"],"peaked":false,"flat":false,"amp":0.2},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"PR court, empâtement du pied du QRS (onde delta), anomalies de repolarisation dans le territoire de la voie accessoire."},"findings":["PR court (< 120 ms)","Empâtement du pied du QRS (onde delta)","QRS légèrement élargi","Anomalies de repolarisation dans le territoire de la voie accessoire","Risque de tachycardie jonctionnelle par réentrée sur la voie accessoire"],"diagnosis":"Préexcitation ventriculaire (syndrome de Wolff-Parkinson-White si symptomatique)","teaching":"**Mécanisme** : une voie accessoire (faisceau de Kent) relie directement l'oreillette au ventricule, en compétition avec le nœud atrioventriculaire, entraînant une préexcitation.\n\n**Diagnostic** : PR court, onde delta, anomalies de repolarisation associées.\n\n**Danger** : en cas de fibrillation atriale associée, la voie accessoire (dépourvue de propriété décrémentielle) peut conduire très rapidement aux ventricules, donnant une tachycardie irrégulière à QRS larges « en accordéon », à haut risque de fibrillation ventriculaire (« super-Wolff »). L'adénosine et le blocage du NAV sont contre-indiqués en cas de FA sur voie accessoire.","quiz":{"stem":"Quel est le risque particulier d'une fibrillation atriale chez un patient porteur d'un Wolff-Parkinson-White ?","options":["Une conduction très rapide par la voie accessoire pouvant dégénérer en fibrillation ventriculaire","Un ralentissement bénéfique de la conduction par la voie accessoire","Un bloc atrioventriculaire complet immédiat","Aucun risque particulier par rapport à une FA habituelle"],"correct":0},"src":"p. 410-411"},{"id":"231-ecg-25","title":"Rythme électro-entraîné (pacemaker) ventriculaire","rank":"B","objective":"231-obj-26","ecg":{"rhythm":"paced","rate":70,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.16,"bbb":"lbbb","lvh":false,"rvh":false,"delta":false,"axis":60,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.2,"pathologicR":[]},"st":{"elev":{},"dep":{},"shape":"normal"},"t":{"inverted":["aVR"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"VVI"},"notes":"Spike de stimulation pathognomonique précédant chaque QRS ; aspect de bloc de branche gauche du fait de la stimulation ventriculaire droite."},"findings":["Spike de stimulation (très bref, 0,4 à 1 ms) précédant chaque QRS","QRS larges avec aspect de bloc de branche gauche (stimulation ventriculaire droite)","Rythme régulier imposé par le boîtier","Absence d'onde P propre visible avant le spike en mode ventriculaire seul","Fréquence proche de la fréquence programmée du boîtier"],"diagnosis":"Rythme électro-entraîné (pacemaker) ventriculaire","teaching":"**Reconnaissance** : le spike de stimulation est pathognomonique car il n'existe rien de physiologique d'aussi bref sur un ECG.\n\n**En cas de dysfonction sinusale** : le pacemaker stimule l'oreillette (onde P après le spike).\n\n**En cas de BAV** : le pacemaker écoute l'oreillette et stimule le ventricule après un délai AV programmé (QRS large après le spike, aspect de bloc de branche gauche car la stimulation ventriculaire droite se propage de proche en proche).\n\n**Piège** : les anomalies ischémiques peuvent être masquées par la stimulation.","quiz":{"stem":"Pourquoi un QRS stimulé par un pacemaker ventriculaire droit a-t-il un aspect de bloc de branche gauche ?","options":["Parce que la stimulation ventriculaire droite se propage lentement de proche en proche vers le ventricule gauche","Parce que le pacemaker stimule simultanément les deux ventricules","Parce que le nœud atrioventriculaire est systématiquement détruit","Parce que la sonde est toujours positionnée dans le ventricule gauche"],"correct":0},"src":"p. 413-414"},{"id":"231-ecg-26","title":"Hypertrophie ventriculaire gauche","rank":"A","objective":"231-obj-05","ecg":{"rhythm":"sinus","rate":72,"irregular":false,"p":{"present":true,"amp":0.15,"dur":0.09,"inverted":[],"biphasicV1":false,"wide":false},"pr":0.16,"avBlock":"none","ratio":"1:1","qrs":{"dur":0.1,"bbb":"none","lvh":true,"rvh":false,"delta":false,"axis":-15,"qWaves":[],"lowVoltage":false,"rsRatioV1":0.15,"pathologicR":[]},"st":{"elev":{"V1":1,"V2":1},"dep":{},"shape":"normal"},"t":{"inverted":["I","aVL","V6"],"peaked":false,"flat":false,"amp":0.3},"qt":0.4,"u":false,"prDep":false,"ectopy":{"type":"none","every":0,"bigeminy":false,"run":0},"pause":0,"pacer":{"mode":"none"},"notes":"Indice de Sokolow (S en V1/V2 + R en V5/V6) à 40 mm, très au-delà du seuil de 35 mm ; déviation axiale gauche modeste ; pseudo sus-décalage de ST en V1-V2 (piège de pseudonécrose) ; onde T négative en D1, aVL, V6 par anomalie secondaire de la repolarisation."},"findings":["Rythme sinusal régulier","Grande amplitude des QRS en précordiales : indice de Sokolow (S en V1/V2 + R en V5/V6) nettement supérieur à 35 mm","Déviation axiale gauche modeste","QRS le plus souvent inférieur à 120 ms malgré la masse myocardique augmentée","Onde T négative et sous-décalage du ST dans les dérivations latérales (D1, aVL, V5, V6)","Pseudo sus-décalage du ST et aspect QS trompeur possibles en V1-V2"],"diagnosis":"Hypertrophie ventriculaire gauche avec anomalies secondaires de la repolarisation","teaching":"**Diagnostic** : l'indice de Sokolow (amplitude de l'onde S en V1 ou V2 additionnée à celle de l'onde R en V5 ou V6) est l'indice le plus utilisé, normal en dessous de 35 mm.\n\n**Forme sévère** : onde T négative souvent associée à un sous-décalage du ST dans les dérivations latérales (D1, aVL, V5, V6), par anomalie secondaire de la repolarisation, avec disparition de l'onde Q septale physiologique dans ces mêmes dérivations. La déviation axiale est modeste, vers la gauche ; les QRS peuvent être un peu élargis du fait de la masse myocardique et de la fibrose intramyocardique, mais restent le plus souvent inférieurs à 120 ms.\n\n**Piège** : une HVG électrique importante peut donner en V1-V2 un aspect QS mimant une séquelle de nécrose (pseudonécrose) et/ou un pseudo sus-décalage du segment ST.\n\n**Étiologies** : l'hypertension artérielle est la plus fréquente, suivie du rétrécissement aortique.","quiz":{"stem":"Quel indice ECG permet de retenir le diagnostic d'hypertrophie ventriculaire gauche ?","options":["L'indice de Sokolow (S en V1/V2 + R en V5/V6), supérieur à 35 mm","L'aspect S1Q3T3","Le sous-décalage du segment PQ","L'allongement isolé du QT"],"correct":0},"src":"p. 406-407"}],"method":"**Démarche systématique de lecture d'un ECG (à appliquer dans cet ordre) :**\n\n1. **Fréquence** : rapide (FC = 300 / nombre de grands carreaux séparant deux QRS) ; distinguer bradycardie (< 60/min) et tachycardie (> 100/min).\n2. **Rythme** : déterminer s'il est sinusal (onde P positive en D1/D2/D3/aVF, une P avant chaque QRS, un QRS après chaque P) ou non.\n3. **Conduction** : mesurer les intervalles PR (120-200 ms), la durée du QRS (70-110 ms) et le QT (corrigé par la formule de Bazett), et déterminer l'axe du QRS (polarité de D1 et aVF pour situer le cadran).\n4. **En cas de bradycardie** : regarder les ondes P — si elles sont régulières à fréquence normale (ou tachycardes comme en FA/flutter) avec plus d'ondes P que de QRS, le problème est le passage au ventricule (bloc atrioventriculaire) ; si elles sont trop lentes ou absentes, le problème vient du nœud sinusal (dysfonction sinusale).\n5. **En cas de bloc de branche** : le diagnostic repose sur la durée du QRS et la polarité en V1 (globalement positif = droit, globalement négatif = gauche) ; le diagnostic d'hémibloc repose sur l'axe du QRS. Les blocs de branche isolés ne donnent pas de bradycardie.\n6. **En cas de tachycardie** : examiner la largeur des QRS (fins ou larges) et la régularité, puis s'aider le plus souvent des manœuvres vagales ou de l'adénosine IV (bloc atrioventriculaire transitoire) pour démasquer l'activité atriale ou arrêter une tachycardie dépendante du NAV. La fibrillation atriale est le seul diagnostic possible devant une tachycardie complètement irrégulière à QRS fins ; toute tachycardie régulière à QRS larges est une tachycardie ventriculaire jusqu'à preuve du contraire, et ne doit jamais être confondue avec un simple bloc de branche.\n7. **Repolarisation** : analyser le segment ST (isoélectrique en dehors des dérivations aVR/V1) et les ondes T (positives partout sauf en aVR, parfois V1/D3/aVL) ; traquer un sus-décalage pour localiser un territoire occlus, puis chercher le miroir (sous-décalage) — jamais l'inverse.\n8. **Morphologie** : amplitude des ondes P et des QRS (indice de Sokolow < 35 mm), transition normale de l'onde R de V1 à V6, absence d'onde Q de nécrose (> 1/3 du QRS et > 40 ms)."},"echo":{"data":[]},"flash":{"id":"231-ff","sections":[{"key":"identite","title":"Carte d'identité flash","src":"p. 375-377, 406","fields":[{"label":"Définition / seuil chiffré","value":"25 mm/s : 1 mm = 40 ms, grand carreau = 200 ms ; FC 60-100/min (= 300 / nb de grands carreaux) · P < 120 ms · **PR 120-200 ms** · **QRS 70-110 ms** · axe −30° à +90° · QTc (Bazett) < 450 ms · Sokolow (S V1/V2 + R V5/V6) < 35 mm"},{"label":"Lecture systématique en 4 temps","value":"Être **systématique** : rythme (sinusal : P + en D1-D2, QRS après chaque P, P avant chaque QRS) → conduction (PR, QRS, axe) → repolarisation (ST isoélectrique, T + sauf aVR/V1, QT sans onde U) → morphologie (Sokolow, transition V1-V6, pas de Q de nécrose)"}]},{"key":"pattern","title":"Le pattern de reconnaissance","src":"p. 374-375, 378-386, 399-400, 405-406","fields":[{"label":"Dérivations & territoires (où regarder)","value":"Antéroseptal V1-V3 · apical V4 · latéral D1-aVL (haut), V5-V6 (bas) · inférieur D2-D3-aVF · postérieur V7-V9 · VD : V1-V2, V3R-V4R ; D1 + et aVF + = axe normal ; HVG sévère : T négatives + sous-ST latéraux (D1, aVL, V5-V6)"},{"label":"Triptyque : tachycardie > 100/min","value":"**Irrégulière** = FA (DD : ESA) · régulière à **QRS larges** = TV jusqu'à preuve du contraire (certitude : dissociation VA = plus de QRS que de P, captures, fusions) · régulière à QRS fins = supraventriculaire"},{"label":"Signe discriminant : blocs et BAV","value":"QRS > 120 ms : V1 positif (RsR') = **BBD**, négatif (rS/QS, notch D1-aVL-V6) = **BBG** · hémibloc : axe < −30° (HBAG, fréquent), > +90° (HBPG, rare) · BAV1 PR > 200 ms · Mobitz 1 PR ↑ puis P bloquée · Mobitz 2 PR fixe puis P bloquée · BAV3 dissociation AV"}]},{"key":"gravite","title":"Le tri vital & la gravité","src":"p. 398-399, 402-405, 408, 411-412","fields":[{"label":"Alerte rouge immédiate","value":"**FV** : tachycardie irrégulière à QRS larges polymorphes, perte de connaissance en secondes · **TV** : FC > 100, QRS > 120 ms, ≥ 3 battements (prémonitoire d'arrêt cardiaque) · sus-ST significatif · QT long (torsade) · hyperK : QRS large, BAV, TV"},{"label":"Sus-ST et Q : critères chiffrés, 5 causes","value":"Sus-ST significatif : ≥ 2 mm en V1-V3, ≥ 1 mm ailleurs, sur ≥ 2 dérivations adjacentes ; sous-ST V1-V3 : chercher V7-V9 (ECG 18D) ; Q de nécrose ≥ 1/3 du QRS et > 30-40 ms ; 5 causes : SCA, anévrisme, repolarisation précoce, Prinzmetal, péricardite"}]},{"key":"paraclinique","title":"Le paraclinique de certitude","src":"p. 373, 377, 381-383, 389, 392-395, 406, 411, 414","fields":[{"label":"1re intention en urgence (timing)","value":"**ECG 12D** si douleur thoracique, palpitations, dyspnée, malaise ou syncope, dyskaliémie/dyscalcémie ; obligatoire dans le bilan d'HTA ; préop > 65 ans ou à risque ; 18D devant toute douleur thoracique"},{"label":"Signes de certitude des rythmes","value":"Bradycardie : plus de P que de QRS = BAV ; P lentes/absentes = dysfonction sinusale · FA : 100-200/min, irrégulièrement irrégulière · flutter : F monomorphes ≈ 300/min **sans retour isoélectrique** (ventricules 150 = 2/1) · Bouveret : très régulière ≈ 200/min"},{"label":"Piège paraclinique à éviter","value":"V1-V2 trop hautes ou HVG (QS, pseudo sus-ST) → fausse nécrose ; D1 négatif = inversion des électrodes avant HBPG ; **BBG** : discordance appropriée ≠ SCA, mais douleur thoracique persistante → infarctus antérieur sans attendre la troponine ; U exclue du QT"}]},{"key":"orientation","title":"L'aiguillage clinique","src":"p. 376-377, 381, 383-384, 390-391, 397, 414","fields":[{"label":"Ambulatoire : rythmes sinusaux et variantes","value":"Tachycardie sinusale : P + en D1-D2-D3-aVF, FC variable (TSV : marches d'escalier) · athlète : bradycardie vagale · jeune homme : point J sus-décalé V1-V4 normal · ESA = P précoce + QRS fin, ESV = QRS large ; fréquentes ou polymorphes → chercher cardiopathie"},{"label":"Hospitalisation conventionnelle","value":"Syncope + bloc bifasciculaire (BBG complet, ou BBD + hémibloc) → **hospitalisation en cardiologie avec télémétrie** (risque de BAV complet infrahissien) ; BAV infrahissien (Mobitz 2, BAV3) → pacemaker même asymptomatique"},{"label":"USIC / soins intensifs / réanimation","value":"**Scope** : urgence, réanimation, transfert médicalisé ; USIC pour pathologie aiguë (SCA) ; syncope de cause rythmique suspectée ; per-op et salle de réveil ; certains exercices de réadaptation cardiaque"}]},{"key":"traitement","title":"Le pack thérapeutique de 1re intention","src":"p. 390, 399, 402, 404-405, 408","fields":[{"label":"Geste salvateur / conditionnement","value":"**FV** : choc électrique immédiat avant tout autre geste, massage cardiaque en attendant ; suspicion de TV : alerter (15), préparer la réanimation ; tachycardie mal tolérée : cardioversion électrique externe"},{"label":"Molécule(s) reine(s) (DCI, voie, dose si cotée)","value":"Tachycardie bien tolérée : manœuvres vagales (Valsalva, compression carotidienne unilatérale, eau froide), puis **adénosine** IV en flash (effet ≈ 10 s) : démasque flutter/TAF/sinusale, arrête une jonctionnelle, sans effet sur une TV"},{"label":"Mesure non pharmacologique / étiologique","value":"QT long (médicaments, hypoK/hypoCa/hypoMg, bradycardie extrême, congénital) : corriger les ions, accélérer la FC, arrêter les médicaments ; hypoK : T plates, sous-ST, onde U ; **hyperK** : T amples pointues, PR long, QRS large"}]},{"key":"securite","title":"Les fautes graves & la sécurité","src":"p. 378, 381, 390, 398, 404, 409-411, 415","fields":[{"label":"Contre-indications absolues","value":"**Adénosine** : asthme, hypotension, FA préexcitée (super-Wolff) ; compression carotidienne : athérome important ou souffle carotidien ; compression oculaire bilatérale abandonnée (décollement de rétine du myope)"},{"label":"Fautes graves de lecture","value":"Décrire d'abord le rythme atrial (TSV + bloc de branche fréquents) ; QRS large : bloc de branche (sans conséquence immédiate) ≠ **TV** (mortelle) ; lésion ≠ miroir ; SCA ST+ sans miroir ≠ péricardite ; QT long : vérifier médicaments et ionogramme"}]}],"src":"p. 368-415"},"pareto":{"id":"231-pareto","points":[{"id":"231-par-01","rank":"A","cat":"examen","text":"Lecture systématique : **rythme** (P positive en D1-D2, QRS après chaque P) → **conduction** (PR, QRS, axe) → **repolarisation** (ST isoélectrique, T positive sauf aVR/V1, QT) → morphologie (Sokolow, pas de Q de nécrose)","src":"p. 377"},{"id":"231-par-02","rank":"A","cat":"chiffre","text":"ECG normal : FC **60-100**/min · P < 120 ms · PR **120-200 ms** · QRS **70-110 ms** · axe −30° à +90° · QTc < 450 ms · Sokolow < 35 mm · à 25 mm/s, 1 mm = 40 ms","src":"p. 375-377"},{"id":"231-par-03","rank":"A","cat":"clinique","text":"Tachycardie > 100/min : **irrégulière** = FA ; régulière à QRS **larges** = TV jusqu'à preuve du contraire ; régulière à QRS fins = supraventriculaire → manœuvres vagales puis adénosine","src":"p. 399, 405"},{"id":"231-par-04","rank":"A","cat":"gravité","text":"**TV** : FC > 100 + QRS > 120 ms sur ≥ 3 battements → alerter (15) ; mal tolérée = **cardioversion électrique** ; certitude : dissociation ventriculoatriale (plus de QRS que de P), captures, fusions","src":"p. 399-401, 405"},{"id":"231-par-05","rank":"A","cat":"gravité","text":"**FV** : tachycardie irrégulière à QRS larges polymorphes, perte de connaissance en quelques secondes → **choc électrique** immédiat, massage cardiaque en attendant","src":"p. 402-403"},{"id":"231-par-06","rank":"A","cat":"clinique","text":"QRS > 120 ms : V1 positif (RsR') = **BBD** ; V1 négatif (rS/QS) avec notch en V6/D1/aVL = **BBG** ; hémibloc : axe < −30° = HBAG (fréquent), > +90° = HBPG (rare)","src":"p. 378-382"},{"id":"231-par-07","rank":"A","cat":"clinique","text":"**BAV1** : PR > 200 ms · Mobitz 1 : PR s'allonge puis P bloquée · **Mobitz 2** : PR fixe puis P bloquée · **BAV3** : dissociation AV · bradycardie : plus de P que de QRS = BAV, P lentes ou absentes = dysfonction sinusale","src":"p. 385-389"},{"id":"231-par-08","rank":"A","cat":"clinique","text":"**FA** : QRS fins irrégulièrement irréguliers, 100-200/min, trémulation sans onde P · **flutter** : ondes F monomorphes ≈ 300/min **sans retour isoélectrique**, ventricules à 150/min (2/1)","src":"p. 392-394"},{"id":"231-par-09","rank":"A","cat":"traitement","text":"**Bouveret** (jonctionnelle) : très régulière ≈ 200/min, QRS fins, P souvent invisible ; réduite par manœuvres vagales ou **adénosine** IV (flash, effet ≈ 10 s ; contre-indiquée si asthme) · WPW : PR court + onde delta","src":"p. 390, 395-397, 410"},{"id":"231-par-10","rank":"A","cat":"clinique","text":"SCA ST+ : sus-décalage ≥ **2 mm** en V1-V3, ≥ 1 mm ailleurs, sur ≥ 2 dérivations adjacentes ; chercher le miroir ; sous-décalage en V1-V3 → ECG **18 dérivations** (V7-V9) ; onde de Pardee","src":"p. 411-412"},{"id":"231-par-11","rank":"A","cat":"piège","text":"5 causes de sus-décalage du ST : SCA ST+, anévrisme ventriculaire, repolarisation précoce, **Prinzmetal**, **péricardite** (diffuse, concave, sans miroir) · BBG : discordance appropriée, pas de faux SCA","src":"p. 381, 412"},{"id":"231-par-12","rank":"A","cat":"gravité","text":"**Hypokaliémie** : T plate, sous-ST, onde U, QT long (torsades) · **hyperkaliémie** : T ample pointue symétrique, PR long, QRS large, BAV · QT long : vérifier médicaments et ionogramme","src":"p. 404, 408"},{"id":"231-par-13","rank":"A","cat":"clinique","text":"**HVG** : **Sokolow** = S V1/V2 + R V5/V6 (normal < 35 mm) ; forme sévère : T négative + sous-ST en D1, aVL, V5-V6 ; pseudonécrose possible en V1-V2 ; 1re cause : **HTA**","src":"p. 406-407"},{"id":"231-par-14","rank":"B","cat":"gravité","text":"Syncope + **bloc bifasciculaire** (BBG complet, BBD + hémibloc) → hospitalisation avec télémétrie ; BAV infrahissien (Mobitz 2, BAV3) → **pacemaker** même sans symptôme","src":"p. 383, 412"},{"id":"231-par-15","rank":"A","cat":"examen","text":"ECG 12D : douleur thoracique, palpitations, malaise/syncope, dyspnée, dyskaliémie/dyscalcémie ; obligatoire dans le bilan d'**HTA** ; préopératoire si > **65 ans** ; scope en urgence ou réanimation","src":"p. 368, 414"}]},"extra":{"semio":[{"title":"ECG normal : lecture systématique en 4 temps","rank":"A","content":"1. **Rythme** : sinusal — P **positive en D1, D2** (et en inférieur), un QRS après chaque P, une P avant chaque QRS ; FC **60–100 bpm**.\n2. **Conduction** : P < 120 ms, **PR 120–200 ms**, **QRS fins 70–110 ms**, axe **–30° à +90°** (positif en D1 et D2).\n3. **Repolarisation** : point J et ST **isoélectriques** ; T positives partout sauf **aVR et V1**, parfois **D3 et aVL** ; QT < 450 ms.\n4. **Morphologie** : amplitudes de P et QRS normales (**Sokolow < 35 mm**), transition normale de V1 à V6 (R croît, S décroît — vérifie aussi la pose des électrodes), pas d'onde Q de nécrose (> 40 ms et > 1/3 du QRS).\n\n> Chez le jeune, surtout l'homme, un **point J sus-décalé de V1 à V4** avec ST jonctionnel ascendant est une **repolarisation physiologique**.\n\n- Piège de pose : **V1-V2 trop hautes et trop écartées** → faux aspect de **pseudonécrose** ou d'atypie de repolarisation antérieure.","src":"p. 371-378"},{"title":"Blocs de branche, hémiblocs et blocs bifasciculaires","rank":"A","content":"**Toujours décrire d'abord le rythme atrial** (TSV + bloc de branche : association non rare).\n\n| | BBD complet | BBG complet |\n|---|---|---|\n| QRS | **> 120 ms** | **> 120 ms** |\n| V1 | globalement **positif**, **RsR'** | globalement **négatif**, **rS ou QS** |\n| V6 | **qRs**, S traînante arrondie | **notch** (double pic), R souvent exclusive (aussi D1, aVL) |\n\n- **Discordance appropriée** : T de polarité inverse du QRS ; dans le BBG, le ST ascendant en V1-V2 peut **mimer un SCA ST+**.\n- **Blocs incomplets** [B] : mêmes aspects, QRS **110–120 ms**. **Bloc fonctionnel** [B] : n'apparaît qu'en **tachycardie** ou en **bradycardie** (à partir d'une fréquence donnée).\n- **HBAG** (fréquent) : axe au-delà de **–30°**, **D2 négatif**. **HBPG** (rare) : axe > **+90°**, **D1 négatif**, aspect **S1Q3** (hors pathologie du VD, sujet longiligne, infarctus latéral).\n- **Bifasciculaire** : **HBAG + BBD** ou **HBPG + BBD**, QRS > 120 ms.\n\n> D1 négatif : penser d'abord à une **inversion des électrodes** (P négative en D1) avant l'HBPG.","src":"p. 378-385"},{"title":"Blocs atrioventriculaires et dysfonction sinusale","rank":"A","content":"Dans un BAV, les **ondes P sont régulières et à fréquence normale**.\n\n| Type | Aspect | Siège |\n|---|---|---|\n| BAV1 | PR **constant > 200 ms**, aucune P bloquée | – |\n| Mobitz 1 (Luciani-Wenckebach) | PR s'allonge progressivement puis P bloquée | **suprahissien** |\n| BAV 2/1 | une P bloquée sur deux | infrahissien si QRS larges ; suprahissien si QRS fins et Mobitz 1 à d'autres moments |\n| Mobitz 2 | PR constant puis P bloquée inopinée | **infrahissien** |\n| BAV3 | dissociation AV complète (P bien vues en V1) | échappement à QRS fins = bloc **nodal** |\n\n> Une P « bloquée » plus précoce que les autres = **extrasystole atriale bloquée**.\n\n**Dysfonction sinusale**\n- **Asystole** (tracé plat) ; **pauses** = **BSA du 2e degré** [B] : pause = **double du PP (RR)**, sans P-QRS-T.\n- **Échappement jonctionnel** : pas de P devant le QRS, parfois P **rétrograde** dans le ST, **négative en D2**.\n- Aspects : P trop lentes, P manquante, pause sinusale, P inexistante avec P' rétrograde.","src":"p. 385-389"},{"title":"Tachycardies supraventriculaires et extrasystoles","rank":"A","content":"- QRS **fins (< 120 ms)** le plus souvent, larges si bloc de branche associé.\n- **Tachycardie sinusale** : P positives en **D1, D2, D3, aVF** ; FC **variant progressivement** (une TSV varie en **« marches d'escalier »**) ; au repos sans hypermétabolisme (fièvre, stress, douleur), une tachycardie marquée n'est pas sinusale.\n- **FA** : QRS **« irrégulièrement irréguliers »**, **100–200 bpm** ; ligne de base à **mailles amples** ou **fine trémulation**.\n  - [B] FA + **BAV complet** → rythme **lent et régulier** ; **maladie de l'oreillette** → alternance FA / bradycardie sinusale, **pauses de régularisation** ; FA + bloc de branche → tachycardie **irrégulière à QRS larges**.\n- **Flutter** : activité atriale **monomorphe ≈ 300 bpm (240–340)**, **sans retour à la ligne isoélectrique** dans au moins une dérivation, ondes **F en toit d'usine / dents de scie** ; ventricules classiquement à **150 bpm (2/1)**.\n  - **Typique antihoraire** : F **négatives en D2, D3, aVF**, **positives en V1**, **négatives en V6** (horaire : inversées).\n- **TAF** : la manœuvre vagale ou l'adénosine **démasque l'activité atriale** sans arrêter la tachycardie.\n- **Jonctionnelle (Bouveret)** : **très régulière**, ≈ **200 bpm** ; réentrée intranodale (P invisible ou devinée dans le ST) ou rythme réciproque par voie accessoire (faisceau de Kent).\n\n#### Extrasystoles\n- Activation **prématurée** d'une cavité ; fréquentes, physiologiques sur cœur sain. **Fréquentes ou polymorphes → rechercher une cardiopathie.**\n- **Atriale** : **P précoce de morphologie différente** puis **QRS fin** ; P parfois cachée dans la T précédente (dont elle modifie la polarité).\n- **Jonctionnelle** : QRS fin ± P' rétrograde ; rare (atteinte de la jonction nodohissienne).\n- **Ventriculaire** : **QRS large** ± P' rétrograde.\n- Répétitives : **doublets, triplets, salves**. Rythmées : **bigéminisme** (1 battement sur 2), **trigéminisme** (1 sur 3).","src":"p. 389-398"},{"title":"Troubles du rythme ventriculaire : TV, FV, torsades","rank":"A","content":"- QRS **larges** car naissance **sous la bifurcation hissienne** (conduction de proche en proche).\n- **TV** : **toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire**. Suspicion : **FC > 100 bpm + QRS > 120 ms sur ≥ 3 battements consécutifs** → alerte (15, préparer la réanimation).\n  - **Certitude** : **dissociation ventriculoatriale** (plus de QRS que de P), complexes de **capture** (QRS fin précédé d'une P) et de **fusion**.\n  - **En faveur** : cardiopathie +++, **concordance** positive ou négative de V1 à V6, **axe extrême** (QRS positif en aVR), aspect atypique de bloc de branche.\n- **FV** : tachycardie **irrégulière à QRS larges polymorphes** ; perte de connaissance en quelques secondes, pouls carotidien aboli = **arrêt cardiaque**.\n- **Torsade de pointes** [B] : TV **polymorphe** sur **QT long préalable**, s'arrêtant spontanément ou dégénérant en FV ; possible à QT normal (2 ESV, la 2e sur la T de la 1re).","src":"p. 398-405"},{"title":"Hypertrophies atriales et ventriculaires","rank":"A","content":"- **HAD** [B] : P **> 2,5 mm en D2** (souvent pointue) ou **> 2 mm en V1-V2**.\n- **HAG** [B] : P **> 110 ms** (120 ms en pratique), composante **négative > 40 ms en V1**.\n- **HVG** : **Sokolow** = S (V1 ou V2) + R (V5 ou V6), normal **< 35 mm** ; forme sévère : **T négative ± sous-ST latéraux** (D1, aVL, V5, V6) et **disparition de la q septale** ; déviation axiale gauche modeste ; QRS le plus souvent **< 120 ms**.\n  - Pièges : **QS en V1-V2** (pseudonécrose), **pseudo sus-décalage du ST** en V1-V2.\n- **HVD** [B] : **axe > 110°** (90° en pratique, signe le plus précoce), **R > 6 mm en V1**, **S > 7 mm en V5-V6**, HAD, **microvoltage** (BPCO), BBD souvent associé ; T négative asymétrique en V1 dans les formes sévères.\n- **Embolie pulmonaire** : **S1Q3T3**, déviation axiale droite, FA possible.","src":"p. 406-408"},{"title":"Dyskaliémies, QT long, péricardite, préexcitation","rank":"A","content":"| | Hypokaliémie | Hyperkaliémie |\n|---|---|---|\n| T | **plate ou négative**, diffuse, **sous-ST** | **ample, pointue, symétrique** |\n| PR / QRS | – / normal | **PR allongé** / **QRS élargi** |\n| QT / U | **QT long**, **onde U** | – |\n| Rythme | ESV, TV, **torsade**, FV | **BAV**, TV, **dysfonction sinusale** |\n\n- **QT long** : risque de **torsade de pointes** (causes médicamenteuses, ioniques, bradycardie extrême, congénitale).\n- **Péricardite aiguë** [B], phase 1 : **microvoltage**, **sus-ST concave vers le haut, diffus, concordant, sans miroir**, **sous-décalage de PQ**.\n- **Préexcitation** [B] : **PR court < 120 ms**, **onde delta** (empâtement du pied du QRS), troubles de repolarisation dans le territoire de la voie. En FA : tachycardie **irrégulière, très rapide, QRS de largeur variable « en accordéon »** (super-Wolff).","src":"p. 408-411"},{"title":"Maladie coronarienne et SCA à l'ECG","rank":"A","content":"- **Deux T négatives dans un même territoire = pathologique** (ex. D2 et D3 → inférieur).\n- **SCA ST+** : traquer le **sus-décalage** (territoire de l'artère occluse) **puis** le **miroir**. Sus-ST significatif : **≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes** ; englobant la T = **onde de Pardee**.\n- Sous-ST V1-V3 = possible miroir d'un sus-ST **postérieur (V7-V9)** → **ECG 18 dérivations**.\n- **Onde Q de nécrose** : ≥ 1/3 (ou 1/4) du QRS et > 30–40 ms, vers la **6e heure** ; équivalent : **rabotage de l'onde R** (V2-V3).\n- Après 48 h : **T négative « ischémique »**. Persistance du sus-ST : **anévrisme**.\n- **SCA sans ST+** : **sous-ST**, **inversion des T**, **pseudo-normalisation**, **aplatissement** des T, ou **ECG normal**.\n- Un **pacemaker** peut masquer les anomalies ischémiques.","src":"p. 411-412"},{"title":"Signes de gravité et situations urgentes à l'ECG","rank":"A","content":"- **FV** : urgence absolue → **choc électrique immédiat**, massage en attendant.\n- **Tachycardie régulière à QRS larges** = TV jusqu'à preuve du contraire ; **mauvaise tolérance hémodynamique → cardioversion électrique externe**.\n- **SCA ST+** (sus-ST significatif + miroir) ; **BBG complet + douleur thoracique** → éliminer un SCA ST+ **sans attendre la troponine**.\n- **Syncope + bloc bifasciculaire** → hospitalisation en cardiologie **avec télémétrie**.\n- **BAV infrahissiens** (Mobitz 2, BAV3) → pacemaker **même sans symptôme**.\n- **Hyperkaliémie** (T amples pointues, PR long, QRS large ; BAV, TV) ; **QT long** (torsade de pointes).\n- **FA préexcitée** (super-Wolff) : risque de **FV**.","src":"p. 381-412"},{"title":"Stimulateur cardiaque : reconnaître l'électroentraînement","rank":"B","content":"- **Spike** : impulsion de **0,4 à 1 ms**, **pathognomonique** d'une stimulation.\n- **Unipolaire** : spike bien visible ; **bipolaire** : spike peu visible.\n- Stimulation **atriale** (dysfonction sinusale) : **onde P après le spike**.\n- Stimulation **ventriculaire** (BAV) : après un **délai AV programmé**, **QRS large d'aspect BBG** (stimulation du VD).\n- Les anomalies **ischémiques** peuvent être masquées.","src":"p. 412-414"}],"criteres":[{"title":"Valeurs normales de l'ECG de l'adulte","rank":"A","content":"| Paramètre | Normale |\n|---|---|\n| FC | **60–100 bpm** |\n| Durée de P | **< 120 ms** (théorique < 110 ms) |\n| Axe de P | **60°** (maximum en D2) |\n| Amplitude de P | **< 2,5 mm en D2** |\n| PR | **120–200 ms** inclus |\n| QRS | **70–110 ms** |\n| Axe QRS | **–30° à +90°** |\n| Onde Q physiologique | **< 1/3 du QRS et < 40 ms** |\n| QTc | **< 450 ms** à 60 bpm (en pratique 470–480 ms) |\n| Sokolow | **< 35 mm** |\n\n- **Étalonnage** : 25 mm/s → 1 mm = **40 ms**, grand carreau = **200 ms** ; 1 mm = **0,1 mV**.\n- **FC = 300 / nombre de grands carreaux** entre deux QRS.\n- **QTc de Bazett** = QT / √RR (s), mesuré par la tangente à T, **sans l'onde U**.","src":"p. 375-378"},{"title":"Axe du QRS : méthode rapide D1 / aVF","rank":"A","content":"| D1 | aVF | Axe |\n|---|---|---|\n| + | + | 0 à +90° : **normal** |\n| + | – | 0 à –90° : normal si **D2 positif** (0 à –30°), sinon **hypergauche** |\n| – | + | +90 à +180° : **hyperdroit** |\n| – | – | –90 à –180° : **axe extrême** |\n\n- Double triaxe de **Bailey** : 30° en 30°, sens horaire, D1 = 0°.\n- Cœur **vertical** (filiforme) → axe proche de 90° ; **horizontal** (obèse, cardiomégalie) → proche de 0°.\n- Axe anormal : **hémibloc** gauche ou anomalie morphologique marquée d'un ventricule.","src":"p. 375"},{"title":"Territoires ECG","rank":"A","content":"| Territoire | Dérivations |\n|---|---|\n| Antéroseptal | **V1, V2, V3** |\n| Apical | **V4** |\n| Latéral haut | **D1, aVL** |\n| Latéral bas | **V5, V6** |\n| Inférieur | **D2, D3, aVF** |\n| Postérieur | **V7, V8, V9** |\n| Ventricule droit | **V1, V2, V3R, V4R** |\n\n- **ECG 18 dérivations** (V7-V9, V3R-V4R) devant toute douleur thoracique.","src":"p. 371-375"},{"title":"Algorithme devant une bradycardie (FC des QRS < 50 bpm)","rank":"A","content":"Seules deux structures en cause : **nœud sinusal** ou **NAV**.\n1. **Regarder les ondes P.**\n2. P régulières à fréquence normale (ou FA, flutter, TAF) avec **plus de P que de QRS** → **BAV**.\n3. P **trop lentes ou absentes** → **dysfonction sinusale**.","src":"p. 389"},{"title":"Algorithme devant une tachycardie (FC > 100 bpm)","rank":"A","content":"1. **Irrégulière** → **FA** (différentiel : ESA).\n2. **Régulière à QRS larges** → **ventriculaire** jusqu'à preuve du contraire (ou TSV + bloc de branche).\n3. **Régulière à QRS fins** → **supraventriculaire**.\n\n- **Mauvaise tolérance hémodynamique** → **cardioversion électrique externe**.\n- Bonne tolérance → **manœuvres vagales ± adénosine** (BAV transitoire) :\n  - **démasque l'activité atriale** → sinusale, flutter, TAF ;\n  - **arrête la tachycardie** → jonctionnelle ;\n  - **aucun effet** → TV ; certitude si dissociation AV.","src":"p. 405"},{"title":"Critères de la tachycardie ventriculaire","rank":"A","content":"- **Suspicion** : FC **> 100 bpm** + QRS **> 120 ms** sur **≥ 3 battements consécutifs**.\n- **Non soutenue** : 3 battements à 30 s ; **soutenue** : **> 30 s** ; préciser monomorphe / polymorphe.\n- **Certitude** : **dissociation ventriculoatriale** (plus de QRS que de P) ; **captures** et **fusions** (seulement s'il y a dissociation).\n- **En faveur** : cardiopathie sous-jacente, **concordance** V1-V6, **axe extrême** (QRS positif en aVR, jamais vu dans un BBD/BBG), aspect atypique de bloc.","src":"p. 398-400"},{"title":"Sus-décalage du ST : critères et diagnostic différentiel","rank":"A","content":"**Sus-ST significatif** : **≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes**.\n\n**Cinq étiologies**\n1. **SCA ST+** (Pardee avec miroir).\n2. **Anévrisme ventriculaire** (persistance après infarctus).\n3. **Repolarisation précoce** (inférolatérale).\n4. **Angor de Prinzmetal** (spasme).\n5. **Péricardite** (diffus, concave vers le haut, sans miroir).\n\nDifférentiels : **BBG ou stimulation ventriculaire** (sus-ST approprié) ; **HVG marquée** (sus-ST V1-V2).\n\n> Ne pas conclure à une péricardite devant un SCA ST+ dont le miroir manque.","src":"p. 409-412"},{"title":"Critères des hypertrophies","rank":"B","content":"| Anomalie | Critères |\n|---|---|\n| HAD | P **> 2,5 mm en D2** ou **> 2 mm en V1-V2** |\n| HAG | P **> 110 ms** (120 en pratique), composante négative **> 40 ms en V1** |\n| HVG | **Sokolow** S(V1/V2) + R(V5/V6), normal **< 35 mm** |\n| HVD | axe **> 110°** (90° en pratique), **R > 6 mm V1**, **S > 7 mm V5-V6** |","src":"p. 406-407"},{"title":"Tachycardie sinusale vs TSV ; manœuvres vagales et adénosine","rank":"B","content":"- **Sinusale** : P positives en D1, D2, D3, aVF ; FC variable **progressivement** ; contexte d'hypermétabolisme.\n- **TSV** : variation en **marches d'escalier**.\n- **Manœuvres vagales** : Valsalva, compression carotidienne **unilatérale** (CI si athérome important ou souffle carotidien), grand verre d'eau froide ; compression oculaire **n'est plus recommandée**.\n- **Adénosine IV en flash** (effet ≈ **dizaine de secondes**) : CI **asthme**, **hypotension**, **FA préexcitée**.","src":"p. 390-391"},{"title":"Indications de l'ECG, du monitorage et du Holter","rank":"A","content":"**Monitorage (cardioscope)** : urgence, réanimation, transfert médicalisé ; soins intensifs cardiologiques ; syncope de cause rythmique suspectée ; peropératoire et SSPI ; certains exercices de réadaptation.\n\n**ECG 12 dérivations ou plus** : bilans de santé ; aptitude professionnelle ou sportive ; **préopératoire > 65 ans**, patients ou interventions à risque ; enquêtes familiales ; **symptômes** (palpitations, douleur thoracique, dyspnée, malaise, perte de connaissance, syncope) ; **obligatoire dans le bilan de l'HTA** ; pathologies cardiaques ou à risque CV (diabète, AVC).\n\n**Holter** [B] : **2 à 12 dérivations**, **24 à 96 h** ; symptômes **épisodiques** non documentés par l'ECG standard ; efficacité des bradycardisants, réglage des pacemakers, risque rythmique. Symptômes rares : ECG ambulatoire **jusqu'à 21 jours**, enregistreurs d'événements ; **Holter implantable jusqu'à 3 ans** (syncopes inexpliquées, FA silencieuse).","src":"p. 414-415"}],"chiffres":[{"theme":"Examens","label":"Vitesse de déroulement standard de l'ECG","value":"25 mm/s","rank":"A","src":"p. 375"},{"theme":"Examens","label":"Durée d'un petit carreau (1 mm) à 25 mm/s","value":"40 ms","rank":"A","src":"p. 375"},{"theme":"Examens","label":"Durée d'un grand carreau (5 mm) à 25 mm/s","value":"200 ms","rank":"A","src":"p. 375"},{"theme":"Examens","label":"Étalonnage d'amplitude","value":"1 mm = 0,1 mV","rank":"A","src":"p. 375"},{"theme":"Examens","label":"Calcul rapide de la FC","value":"300 / nombre de grands carreaux (1 = 300, 2 = 150 bpm)","rank":"A","src":"p. 376"},{"theme":"Examens","label":"Graduation du double triaxe de Bailey","value":"30° en 30°, sens horaire, D1 = 0°","rank":"A","src":"p. 375"},{"theme":"Examens","label":"Dérivations précordiales","value":"V1 à V9 + V3R et V4R (enfant, suspicion de SCA)","rank":"A","src":"p. 371"},{"theme":"Examens","label":"ECG devant une douleur thoracique","value":"18 dérivations (V7-V9, V3R-V4R)","rank":"A","src":"p. 411-414"},{"theme":"Seuils et définitions","label":"Fréquence cardiaque normale de repos (adulte)","value":"60–100 bpm","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Bradycardie (adulte)","value":"< 60 bpm","rank":"A","src":"p. 376"},{"theme":"Seuils et définitions","label":"Tachycardie (adulte)","value":"> 100 bpm","rank":"A","src":"p. 376"},{"theme":"Seuils et définitions","label":"Durée normale de l'onde P","value":"< 120 ms (théorique < 110 ms)","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Axe normal de l'onde P","value":"60° (maximum en D2)","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Amplitude normale de l'onde P","value":"< 2,5 mm en D2","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Intervalle PR normal","value":"120–200 ms (inclus)","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Durée normale du QRS","value":"70–110 ms","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Axe normal du QRS","value":"–30° à +90° (théorique –45° à +110°)","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Onde Q physiologique","value":"< 1/3 du QRS et < 40 ms","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"QT corrigé normal","value":"< 450 ms à 60 bpm (en pratique 470–480 ms)","rank":"A","src":"p. 375"},{"theme":"Seuils et définitions","label":"Formule de Bazett","value":"QTc = QT / √RR (RR en s)","rank":"A","src":"p. 377"},{"theme":"Seuils et définitions","label":"Indice de Sokolow normal","value":"S (V1/V2) + R (V5/V6) < 35 mm","rank":"A","src":"p. 406"},{"theme":"Diagnostic","label":"Durée du QRS dans un bloc de branche complet","value":"> 120 ms","rank":"A","src":"p. 378"},{"theme":"Diagnostic","label":"Durée du QRS dans un bloc de branche incomplet","value":"110–120 ms","rank":"B","src":"p. 381"},{"theme":"Diagnostic","label":"Durée du QRS dans un hémibloc","value":"> 110 ms (> 120 ms si bloc de branche associé ou cardiopathie marquée)","rank":"A","src":"p. 382"},{"theme":"Diagnostic","label":"Axe de l'hémibloc antérieur gauche","value":"au-delà de –30° (D2 négatif)","rank":"A","src":"p. 382"},{"theme":"Diagnostic","label":"Axe de l'hémibloc postérieur gauche","value":"> +90° (D1 négatif, S1Q3)","rank":"A","src":"p. 382"},{"theme":"Diagnostic","label":"Durée du QRS dans un bloc bifasciculaire","value":"> 120 ms","rank":"A","src":"p. 383"},{"theme":"Diagnostic","label":"Définition du BAV1","value":"PR constant > 200 ms, sans P bloquée","rank":"A","src":"p. 386"},{"theme":"Diagnostic","label":"BAV 2/1","value":"1 onde P bloquée sur 2","rank":"A","src":"p. 385"},{"theme":"Diagnostic","label":"Seuil de bradycardie de l'algorithme diagnostique","value":"FC des QRS < 50 bpm","rank":"A","src":"p. 389"},{"theme":"Diagnostic","label":"Pause du bloc sinoatrial du 2e degré","value":"double de l'intervalle PP (RR) normal","rank":"B","src":"p. 387"},{"theme":"Diagnostic","label":"Largeur des QRS d'une TSV","value":"< 120 ms le plus souvent","rank":"A","src":"p. 389"},{"theme":"Diagnostic","label":"Fréquence ventriculaire de la FA","value":"100–200 bpm","rank":"A","src":"p. 392"},{"theme":"Diagnostic","label":"Fréquence atriale du flutter","value":"≈ 300 bpm (240–340)","rank":"A","src":"p. 393"},{"theme":"Diagnostic","label":"Fréquence atriale d'un flutter atypique","value":"120–320 bpm","rank":"A","src":"p. 394"},{"theme":"Diagnostic","label":"Fréquence ventriculaire du flutter en 2/1","value":"150 bpm","rank":"A","src":"p. 394"},{"theme":"Diagnostic","label":"Fréquence ventriculaire du flutter en 3/1","value":"100 bpm","rank":"A","src":"p. 394"},{"theme":"Diagnostic","label":"Fréquence ventriculaire du flutter en 4/1","value":"75 bpm","rank":"A","src":"p. 394"},{"theme":"Diagnostic","label":"Fréquence des tachycardies jonctionnelles","value":"≈ 200 bpm (130–260)","rank":"A","src":"p. 395"},{"theme":"Diagnostic","label":"Bigéminisme / trigéminisme","value":"1 battement sur 2 / 1 battement sur 3","rank":"A","src":"p. 397"},{"theme":"Diagnostic","label":"Critères de suspicion de TV","value":"FC > 100 bpm + QRS > 120 ms sur ≥ 3 battements consécutifs","rank":"A","src":"p. 399"},{"theme":"Diagnostic","label":"TV non soutenue","value":"3 battements à 30 s","rank":"A","src":"p. 399"},{"theme":"Diagnostic","label":"TV soutenue","value":"> 30 s","rank":"A","src":"p. 399"},{"theme":"Pronostic","label":"Part des morts subites précédées d'une TV","value":"> la moitié","rank":"A","src":"p. 398"},{"theme":"Examens","label":"Durée d'effet de l'adénosine IV (flash)","value":"une dizaine de secondes","rank":"B","src":"p. 390"},{"theme":"Diagnostic","label":"Hypertrophie atriale droite","value":"P > 2,5 mm en D2 ou > 2 mm en V1-V2","rank":"B","src":"p. 406"},{"theme":"Diagnostic","label":"Hypertrophie atriale gauche : durée de P","value":"> 110 ms (120 ms en pratique)","rank":"B","src":"p. 406"},{"theme":"Diagnostic","label":"Hypertrophie atriale gauche : composante négative de P en V1","value":"> 40 ms","rank":"B","src":"p. 406"},{"theme":"Diagnostic","label":"QRS dans l'HVG","value":"le plus souvent < 120 ms","rank":"A","src":"p. 406"},{"theme":"Diagnostic","label":"HVD : axe (signe le plus précoce)","value":"> 110° (90° en pratique)","rank":"B","src":"p. 407"},{"theme":"Diagnostic","label":"HVD : onde R en V1","value":"> 6 mm","rank":"B","src":"p. 407"},{"theme":"Diagnostic","label":"HVD : onde S en V5-V6","value":"> 7 mm","rank":"B","src":"p. 407"},{"theme":"Diagnostic","label":"PR de la préexcitation","value":"< 120 ms","rank":"B","src":"p. 410"},{"theme":"Seuils et définitions","label":"Sus-ST significatif en V1-V3","value":"≥ 2 mm","rank":"A","src":"p. 412"},{"theme":"Seuils et définitions","label":"Sus-ST significatif hors V1-V3","value":"≥ 1 mm","rank":"A","src":"p. 412"},{"theme":"Seuils et définitions","label":"Nombre de dérivations pour un sus-ST significatif","value":"≥ 2 dérivations adjacentes","rank":"A","src":"p. 412"},{"theme":"Seuils et définitions","label":"Onde Q de nécrose : amplitude","value":"≥ 1/3 (ou 1/4) du QRS","rank":"A","src":"p. 412"},{"theme":"Seuils et définitions","label":"Onde Q de nécrose : durée","value":"> 30–40 ms","rank":"A","src":"p. 412"},{"theme":"Diagnostic","label":"Délai d'apparition des ondes Q de nécrose","value":"vers la 6e heure","rank":"A","src":"p. 412"},{"theme":"Diagnostic","label":"Délai d'apparition de la T négative ischémique","value":"après 48 h","rank":"A","src":"p. 412"},{"theme":"Diagnostic","label":"Nombre de phases ECG de la péricardite aiguë","value":"4","rank":"B","src":"p. 409"},{"theme":"Seuils et définitions","label":"T négatives pathologiques dans un territoire","value":"2 T négatives dans un même territoire","rank":"A","src":"p. 411"},{"theme":"Diagnostic","label":"Durée du spike de stimulation","value":"0,4 à 1 ms","rank":"B","src":"p. 413"},{"theme":"Examens","label":"Nombre de dérivations du Holter","value":"2 à 12","rank":"B","src":"p. 415"},{"theme":"Examens","label":"Durée d'enregistrement du Holter","value":"24 à 96 h maximum","rank":"B","src":"p. 415"},{"theme":"Examens","label":"ECG ambulatoire de très longue durée","value":"jusqu'à 21 jours","rank":"B","src":"p. 415"},{"theme":"Examens","label":"Durée de suivi du Holter implantable","value":"jusqu'à 3 ans","rank":"B","src":"p. 415"},{"theme":"Examens","label":"Âge de l'ECG préopératoire","value":"> 65 ans (ou patient / intervention à risque)","rank":"A","src":"p. 414"}],"physio":[{"theme":"Mécanismes","title":"Rythmes d'échappement","rank":"A","content":"1. En cas de **dysfonction sinusale marquée**, un **rythme d'échappement jonctionnel** apparaît : l'onde P n'est plus visible devant le QRS (parfois rétrograde).\n2. Dans le **BAV complet**, la fréquence cardiaque devient **lente et régulière** grâce à un rythme d'échappement de mécanisme automatique.\n3. Échappement à **QRS fins** = bloc **nodal** (suprahissien) ; échappements à **QRS larges** = blocs atrioventriculaires **bas situés**.\n4. La **bradycardie extrême** des échappements bas situés allonge le QT et expose à la **torsade de pointes**.","src":"p. 387-388, 392, 404"},{"theme":"Mécanismes","title":"Électrogenèse : de l'influx à l'onde ECG","rank":"A","content":"- L'ECG enregistre la **somme des potentiels d'action** : **P** (oreillettes), **QRS** (ventricules), **T** (repolarisation).\n- Front de dépolarisation **vers** l'électrode → onde **positive** ; s'en **éloignant** → **négative** ; perpendiculaire → **isodiphasique**.\n- **T concordante** au QRS normal : dépolarisation **endocarde → épicarde**, repolarisation en sens inverse.\n- Le reste du plan de l'anneau est isolant : **le NAV est le seul passage AV physiologique** (p. 410).\n- QRS **fins** si l'influx emprunte les voies de conduction (NAV, His, branches, Purkinje) ; **larges** s'il chemine lentement de proche en proche, hors de ces voies (TV née sous la bifurcation hissienne, stimulation ventriculaire).\n- **Genèse du QRS** [B] : activation septale (petite **q** latérale, petit **r** en V1), puis vers la jambe gauche et l'avant (grande **R** en V3-V4 et D2), puis vers le haut et l'arrière (petite **S**).","src":"p. 371, 376, 398, 410, 414"},{"theme":"Conséquences hémodynamiques","title":"Filtre du NAV : conduction décrémentielle","rank":"A","content":"1. Au-delà d'une certaine fréquence atriale, le ventricule ne suit plus en 1/1 : **2/1**, alternance **1/1-2/1** ou **2/1-3/1** (conduction variable).\n2. L'intensité du filtre dépend de l'**âge**, du **tonus vagal**, des **ralentisseurs du NAV**.\n3. Sans ce filtre, **toute FA donnerait une FV** et un flutter à 300 bpm une tachycardie ventriculaire à 300 bpm.\n4. **Créer un BAV transitoire** (manœuvres vagales, **adénosine** via les récepteurs **purinergiques**) démasque l'activité atriale ou arrête une réentrée dépendante du NAV.\n\n→ La **voie accessoire** (Kent) n'a **pas de propriété décrémentielle** : en FA, conduction très rapide (super-Wolff) → **FV**.","src":"p. 389-411"},{"theme":"Mécanismes","title":"Réentrée, hyperautomatisme et troubles du rythme","rank":"A","content":"- **TSV** : réentrée, hyperautomatisme, mécanismes complexes ; au-delà de la bifurcation hissienne = trouble **ventriculaire**.\n- **Flutter** : boucle de **réentrée** autour d'un obstacle, activation « organisée » (≠ FA fibrillatoire) ; typique par l'**isthme cavotricuspide**.\n- **Jonctionnelle** : réentrée **intranodale** (dans le NAV) ou **rythme réciproque** par voie accessoire (faisceau de Kent).\n- **TV** : **réentrée** autour d'une **fibrose post-infarctus** (le plus fréquent sur cardiopathie) ; **automatisme anormal** sur cœur sain. Évolution **TV → FV → asystolie**.","src":"p. 389-400"},{"theme":"Mécanismes","title":"Blocs de branche : repolarisation secondaire et désynchronisation","rank":"B","content":"1. Interruption ou ralentissement marqué de la conduction dans une branche → **QRS larges** (> 120 ms).\n2. **Trouble de repolarisation secondaire** → **discordance appropriée** de T (peut mimer un SCA ST+ dans le BBG).\n3. **BBG complet** → **désynchronisation du VG** pouvant créer ou aggraver une cardiopathie → correction (**resynchronisation**) indiquée si insuffisance cardiaque.\n4. **Bloc bifasciculaire** → risque de **BAV complet infrahissien intermittent** (syncope, mort subite).\n5. **Bloc fonctionnel** : n'apparaît qu'à partir d'une fréquence donnée (en **tachycardie** ou en **bradycardie**).","src":"p. 378-383"},{"theme":"Facteurs déclenchants","title":"QT long et torsades de pointes","rank":"B","content":"- Causes : **bradycardie extrême**, **hypokaliémie**, **hypocalcémie**, **hypomagnésémie**, **médicaments** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…), **QT long congénital**.\n- QT long → **torsade de pointes** → arrêt spontané ou **FV**.\n- Traitement logique : **corriger les ions**, **accélérer la fréquence cardiaque**, **arrêter les médicaments** en cause.","src":"p. 403-410"},{"theme":"Histoire naturelle","title":"Évolution ECG du SCA ST+ et de la péricardite","rank":"A","content":"**SCA ST+**\n1. Sus-ST (± onde de Pardee) avec miroir.\n2. Ondes Q vers la **6e heure**.\n3. Régression rapide si reperfusion ; plusieurs jours sinon ; **persistance indéfinie** si **anévrisme**.\n4. Après **48 h** : T négative « ischémique », parfois très prolongée.\n\n**Péricardite aiguë (4 phases)**\n1. Microvoltage, sus-ST diffus concave sans miroir, sous-décalage de PQ.\n2. T plates, ST isoélectrique.\n3. T négatives persistantes.\n4. Retour progressif à la normale.","src":"p. 409-412"}],"parcours":[{"title":"Tachycardie aux urgences : de l'ECG au diagnostic du trouble du rythme","rank":"A","patient":"Homme de 68 ans, aux antécédents d'infarctus du myocarde ancien, amené aux urgences pour des palpitations rapides débutées il y a 2 heures. Il est conscient. Le scope affiche une tachycardie à 160 bpm.","steps":[{"phase":"Régulation / pré-hospitalier","title":"Monitorer et donner l'alerte","question":"Le patient est pris en charge par le SAMU puis arrive aux urgences : quelle surveillance ECG mets-tu en place et quel signe sur le scope doit déclencher l'alerte ?","answer":"- **Monitorage ECG (cardioscope)** indiqué dans : toute **urgence**, la réanimation et tout **transfert médicalisé** ; la **syncope** à cause rythmique suspectée ; la surveillance en **soins intensifs cardiologiques**.\n- **ECG 12 dérivations** indiqué devant des **palpitations** (symptôme = indication de l'ECG conventionnel).\n- **Alerte** (15, préparer la réanimation) si suspicion de **TV** : **FC > 100 bpm + QRS > 120 ms sur ≥ 3 battements consécutifs**.\n- La TV est un état **instable, prémonitoire de l'arrêt cardiaque** (> la moitié des morts subites) : **TV → FV → asystolie**.","cas":[{"si":"Si le scope montre une tachycardie irrégulière à QRS larges polymorphes avec perte de connaissance","alors":"**Fibrillation ventriculaire** = arrêt cardiaque (pouls carotidien aboli) → **choc électrique immédiat avant tout autre geste**, **massage cardiaque en attendant**."}],"pieges":["Attendre l'ECG 12 dérivations pour donner l'alerte devant ≥ 3 complexes larges et rapides au scope."],"src":"p. 398-399, 402-403, 414"},{"phase":"Accueil & gravité","title":"Évaluer la tolérance hémodynamique","question":"Avant même d'analyser finement le tracé, quelle est la première question à te poser et quelle en est la conséquence thérapeutique ?","answer":"- Première question : la tachycardie est-elle **bien ou mal tolérée sur le plan hémodynamique** ?\n- **Mauvaise tolérance hémodynamique → cardioversion électrique externe**, quel que soit le mécanisme.\n- **Bonne tolérance** → on a le temps de faire le diagnostic : ECG 12 dérivations, puis **manœuvres vagales ± adénosine** si le diagnostic n'est pas évident.\n- La **FV** est une **urgence absolue** : perte de connaissance en quelques secondes (débit nul), pouls carotidien aboli.","cas":[{"si":"Si FV (arrêt cardiaque)","alors":"**Choc électrique immédiat** avant tout autre geste ; **massage cardiaque** en attendant le défibrillateur."},{"si":"Si tachycardie mal tolérée (quel que soit le type)","alors":"**Cardioversion électrique externe**."}],"pieges":["Retarder le choc électrique d'une FV pour réaliser d'autres gestes."],"src":"p. 402-405"},{"phase":"Examens complémentaires","title":"Réaliser un ECG 12 (voire 18) dérivations de qualité","question":"Comment réalises-tu et vérifies-tu techniquement l'ECG, et comment calcules-tu rapidement la fréquence ?","answer":"- **Dérivations frontales** : D1, D2, D3 + aVR, aVL, aVF. **Précordiales** : **V1 à V9**, complétées par **V3R-V4R** (enfant ou suspicion de SCA) ; électrodes précordiales **équidistantes**.\n- **Étalonnage** : **25 mm/s** → 1 mm = **40 ms**, grand carreau (5 mm) = **200 ms** ; **1 mm = 0,1 mV**.\n- **FC = 300 / nombre de grands carreaux** entre deux QRS (1 carreau = 300, 2 = 150…), ou FC = 60 / RR (s).\n- Pour démasquer une activité atriale peu visible : **dérivations de Lewis** (électrode rouge sur la fourchette sternale, jaune au 5e espace intercostal droit ; lecture en **D1**).","cas":[{"si":"Si D1 est négatif","alors":"Penser d'abord à une **inversion des électrodes** frontales (P alors négative en D1)."}],"pieges":["V1 et V2 posées trop haut et trop écartées (confusion avec les foyers aortique et pulmonaire) → faux aspect de pseudonécrose ou d'atypie de repolarisation antérieure."],"src":"p. 371-376"},{"phase":"Diagnostic positif","title":"Classer la tachycardie : l'algorithme","question":"L'ECG montre une tachycardie (> 100 bpm). Quel algorithme appliques-tu pour l'orienter ?","answer":"Toujours **décrire d'abord le rythme atrial**, puis :\n\n| Aspect | Orientation |\n|---|---|\n| **Irrégulière** | **FA** (diagnostic différentiel : ESA) |\n| **Régulière à QRS larges** (> 120 ms) | **Ventriculaire jusqu'à preuve du contraire** (ou TSV + bloc de branche) |\n| **Régulière à QRS fins** (< 120 ms) | **Supraventriculaire** |\n\n- TSV = activation trop rapide des oreillettes ou de la jonction ; QRS fins le plus souvent, **larges si bloc de branche associé**.\n- Les tachycardies ventriculaires naissent **sous la bifurcation hissienne** → conduction de proche en proche → **QRS large**.","cas":[{"si":"Si tachycardie irrégulière à QRS larges","alors":"Évoquer une **FA + bloc de branche** (préexistant ou fonctionnel), une **FV** (QRS polymorphes, arrêt cardiaque) ou une **FA préexcitée** (QRS de largeur variable « en accordéon »)."},{"si":"Si FA avec rythme ventriculaire lent et régulier","alors":"**FA + BAV complet** (échappement automatique)."}],"pieges":["Conclure à une TSV avec bloc de branche devant une tachycardie régulière à QRS larges sans avoir éliminé une TV."],"src":"p. 378, 389, 392, 398, 405"},{"phase":"Diagnostic positif","title":"Affirmer la tachycardie ventriculaire","question":"La tachycardie est régulière à QRS larges (140 ms). Quels arguments ECG affirment ou orientent vers une TV ?","answer":"**Toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire.**\n\n- **Arguments de certitude** :\n  - **dissociation ventriculoatriale** : **plus de QRS que de P** (≠ dissociation AV du BAV3) ;\n  - complexes de **capture** (QRS fin précédé d'une P) et de **fusion** (QRS intermédiaire), possibles seulement s'il y a dissociation.\n- **Arguments en faveur** :\n  - **cardiopathie sous-jacente** +++ ;\n  - **concordance** positive ou négative de V1 à V6 ;\n  - **axe extrême** (QRS positif en aVR, jamais vu dans un BBD/BBG) ;\n  - QRS larges d'aspect **atypique** de bloc de branche.\n- Préciser : **non soutenue** (3 battements à 30 s) ou **soutenue** (> 30 s) ; **monomorphe** ou **polymorphe**.\n- Mécanismes : **réentrée** (le plus fréquent sur cardiopathie, autour d'une fibrose post-infarctus) ; **automatisme anormal** (cœur sain).","cas":[{"si":"Si les manœuvres vagales / l'adénosine n'ont aucun effet","alors":"Orientation vers une **TV** (indépendante du NAV) ; certitude si dissociation AV."}],"pieges":["Confondre la dissociation ventriculoatriale de la TV (plus de QRS que de P) avec la dissociation AV du BAV3 (plus de P que de QRS)."],"src":"p. 398-400, 405"},{"phase":"Diagnostic différentiel","title":"Tachycardie sinusale ou TSV non sinusale ?","question":"Devant une tachycardie régulière à QRS fins, comment distingues-tu une tachycardie sinusale d'une TSV non sinusale ?","answer":"- **P sinusales** : positives en **D1, D2, D3 et aVF**.\n- **Variation de fréquence** : **progressive** pour la sinusale (courbe de scope, télémétrie, holter, massage sinocarotidien) ; en **« marches d'escalier »** pour une TSV.\n- **Contexte** : au repos, une tachycardie marquée **sans cause d'hypermétabolisme** (fièvre, stress, douleur) **n'est pas sinusale**.\n- Seuils adulte : tachycardie **> 100 bpm** (attention au nouveau-né).","cas":[],"pieges":["Retenir une tachycardie sinusale chez un patient au repos sans fièvre, stress ni douleur."],"src":"p. 376, 390-391"},{"phase":"Traitement en urgence","title":"Créer un BAV transitoire : manœuvres vagales puis adénosine","question":"La tachycardie est bien tolérée et le diagnostic n'est pas évident. Que fais-tu, comment, et comment interprètes-tu la réponse ?","answer":"1. **Manœuvres vagales** :\n   - **Valsalva** (expiration forcée à glotte fermée) ;\n   - **compression carotidienne unilatérale** ;\n   - **grand verre d'eau froide**.\n2. Si échec : **adénosine IV en flash** (vagomimétique via les récepteurs purinergiques), effet d'une **dizaine de secondes**.\n\n| Réponse | Diagnostic |\n|---|---|\n| **Démasque l'activité atriale** | sinusale, **flutter**, **TAF** |\n| **Arrête la tachycardie** | **jonctionnelle** (réentrée dépendante du NAV) |\n| **Aucun effet** | **TV** (indépendante du NAV) ; certitude si dissociation AV |\n\n- Intérêt double : **diagnostic différentiel** des tachycardies et **réduction des tachycardies jonctionnelles**.","cas":[{"si":"Si athérome important ou souffle carotidien","alors":"**Compression carotidienne contre-indiquée**."},{"si":"Si asthme","alors":"**Adénosine contre-indiquée** (bronchospasme intense transitoire possible, même chez le non asthmatique)."},{"si":"Si hypotension","alors":"**Adénosine contre-indiquée**."},{"si":"Si FA préexcitée (super-Wolff)","alors":"**Adénosine contre-indiquée** ; ne **jamais** bloquer le NAV en cas de FA sur voie accessoire."}],"pieges":["Proposer une compression oculaire bilatérale : elle n'est plus recommandée (décollement de rétine du myope).","Faire une compression carotidienne bilatérale : elle est unilatérale."],"src":"p. 390, 405, 411"},{"phase":"Diagnostic étiologique","title":"Identifier la tachycardie supraventriculaire","question":"Quels sont les aspects ECG des différentes TSV que tu peux démasquer ?","answer":"| TSV | Aspect ECG |\n|---|---|\n| **FA** | activation atriale **anarchique**, pas de P ; **100–200 bpm** ; QRS **« irrégulièrement irréguliers »** ; ligne de base à **mailles amples** ou **fine trémulation** |\n| **Flutter typique antihoraire** | activité atriale **monomorphe ≈ 300 bpm (240–340)**, **sans retour à la ligne isoélectrique** ; ondes **F** en dents de scie **négatives en D2, D3, aVF, positives en V1, négatives en V6** ; circuit par l'**isthme cavotricuspide** ; ventricules classiquement à **150 bpm (2/1)**, ou 100 (3/1), 75… |\n| **Flutter atypique** | isthme non impliqué, **120–320 bpm**, F variables |\n| **TAF** | activité atriale **démasquée** par la manœuvre vagale ou l'adénosine, sans arrêt de la tachycardie |\n| **Tachycardie jonctionnelle (Bouveret)** | **très régulière**, ≈ **200 bpm (130–260)** |\n\nTachycardies jonctionnelles :\n- **réentrée intranodale** (réentrée dans le NAV) : activité atriale invisible ou devinée dans le ST ;\n- **rythme réciproque** : réentrée par une **voie accessoire (faisceau de Kent)**.","cas":[{"si":"Si flutter typique horaire","alors":"Polarités des ondes F **inversées**."},{"si":"Si flutter conduit en 1/1 ou 2/1","alors":"La manœuvre vagale **ralentit** et **démasque les F**."},{"si":"Si alternance FA / bradycardie sinusale avec pauses à l'arrêt de la FA","alors":"**Maladie de l'oreillette** (syndrome tachycardie-bradycardie)."},{"si":"Si ESA fréquentes ou polymorphes (ou ESV)","alors":"**Rechercher une cardiopathie**."}],"pieges":["Confondre une FA à grosses mailles avec un flutter : le flutter est monomorphe et organisé.","Parler de flutter typique avec certitude : on parle de flutter « d'aspect » typique/atypique, le diagnostic formel se fait par la fréquence ou l'exploration électrophysiologique."],"src":"p. 392-397"},{"phase":"Diagnostic étiologique","title":"Rechercher une préexcitation (Wolff-Parkinson-White)","question":"Sur l'ECG en rythme sinusal après réduction, que cherches-tu pour évoquer une voie accessoire et quel est le risque ?","answer":"- **Voie accessoire (faisceau de Kent)** : fibre musculaire AV ectopique conduisant typiquement dans les deux sens, en compétition avec le NAV.\n- **Préexcitation** : **PR court < 120 ms**, **onde delta** (empâtement du pied du QRS), **troubles de repolarisation** dans le territoire de la voie.\n- **Syndrome de WPW** = voie accessoire antérograde + palpitations par tachycardie jonctionnelle.\n- **Risque de mort subite** si période réfractaire courte (pas de propriété décrémentielle) : en FA → tachycardie **irrégulière, très rapide, à QRS de largeur variable « en accordéon »** (super-Wolff) → **FV**.","cas":[{"si":"Si préexcitation minime à démasquer","alors":"Bloquer le NAV (massage, adénosine) force le passage par la voie accessoire — **jamais en cas de FA**."}],"pieges":["Injecter de l'adénosine dans une FA préexcitée."],"src":"p. 410-411"},{"phase":"Traitement spécifique","title":"Torsade de pointes et QT long","question":"Le patient présente une TV polymorphe s'arrêtant spontanément ; l'ECG de base montre un QT long. Que fais-tu ?","answer":"- **Torsade de pointes** : TV **polymorphe** s'arrêtant spontanément ou dégénérant en **FV** ; installée, elle est indiscernable d'une FV → diagnostic sur le **QT long préalable** et le contexte.\n- **Mesure du QT** : du début de Q à la fin de T, dans la dérivation où T est la plus ample (souvent V2-V3), par la **tangente** ; **jamais d'onde U**. **Bazett** : QTc = QT / √RR (s). Normal **< 450 ms à 60 bpm** (en pratique 470–480 ms).\n- **Causes de QT long** : **bradycardie extrême** (échappements des BAV bas situés, intoxication aux bradycardisants), **hypokaliémie**, **hypocalcémie**, **hypomagnésémie**, **médicaments** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…), **QT long congénital**.\n- **Tout QT allongé → vérifier les médicaments et le ionogramme.**\n- **Prise en charge** : **corriger les ions**, **accélérer la fréquence cardiaque**, **arrêter les médicaments en cause**.\n\n| | Hypokaliémie | Hyperkaliémie |\n|---|---|---|\n| Onde T | plate ou négative, diffuse, avec sous-ST | ample, pointue, symétrique |\n| PR | – | allongé |\n| QRS | normal | élargi |\n| QT / U | QT allongé, onde U | – |\n| Rythme | ESV, TV, **torsade de pointes**, FV | BAV, TV, dysfonction sinusale |","cas":[{"si":"Si QT normal","alors":"Une torsade reste possible, déclenchée par deux ESV dont la 2e tombe sur la T de la 1re."}],"pieges":["Inclure l'onde U dans la mesure du QT.","Ralentir la fréquence cardiaque d'une torsade : il faut au contraire l'accélérer."],"src":"p. 377, 403-404, 408-409"},{"phase":"Suivi","title":"Documenter les récidives et protéger le patient","question":"À distance, comment documentes-tu des palpitations épisodiques et quelle prothèse protège d'une TV/FV ?","answer":"- **Holter ECG** : **2 à 12 dérivations**, **24 à 96 h maximum**, lecture différée ; pour palpitations, malaises, syncopes **épisodiques** quand l'ECG standard n'a rien montré et que les symptômes ont une probabilité de récidiver pendant l'enregistrement.\n- Symptômes rares : ECG ambulatoire **jusqu'à 21 jours**, **enregistreurs d'événements** (outils dédiés, montres connectées ECG).\n- **Holter implantable** : jusqu'à **3 ans** (syncopes inexpliquées, FA silencieuse).\n- Holter 24 h pour évaluer le **risque rythmique** (salves de TV asymptomatiques après infarctus ou dans les cardiomyopathies).\n- **TV / FV → défibrillateur** (fait toujours pacemaker, sauf sous-cutané).\n- **Flutter** : exploration électrophysiologique avant **ablation par radiofréquence**.","cas":[],"pieges":["Prescrire un Holter de 24 h pour des symptômes très rares : préférer un enregistrement de longue durée, un enregistreur d'événements ou un Holter implantable."],"src":"p. 394, 413-415"}]},{"title":"Bradycardie et syncope : BAV, dysfonction sinusale et blocs de branche","rank":"A","patient":"Femme de 79 ans, hypertendue, amenée aux urgences après un malaise avec perte de connaissance brève. À l'arrivée, elle est consciente, le pouls est lent à 38 bpm.","steps":[{"phase":"Régulation / pré-hospitalier","title":"Monitorer la syncope","question":"Quelle surveillance mets-tu en place dès la prise en charge ?","answer":"- **Monitorage ECG (cardioscope)** : **urgence**, **transfert médicalisé**, **syncope avec cause rythmique suspectée**.\n- **ECG 12 dérivations** : indiqué devant **malaise, perte de connaissance, syncope** ; en urgence aussi devant les **troubles hydroélectrolytiques (K, Ca)**.","cas":[],"pieges":[],"src":"p. 414"},{"phase":"Accueil & gravité","title":"Rechercher les signes de gravité","question":"Quels éléments ECG dois-tu repérer d'emblée pour juger de la gravité ?","answer":"- **Asystole** (tracé plat).\n- **Échappement à QRS larges** (bloc bas situé) : plus grave qu'un échappement jonctionnel à QRS fins (bloc nodal).\n- **BAV infrahissien** (BAV2 Mobitz 2, BAV3 ; le BAV 2/1 à QRS larges est infrahissien) : indication de **pacemaker même sans symptôme**.\n- **Bradycardie extrême** (échappements des BAV bas situés) : cause de **QT long → torsade de pointes**.\n- **Bloc bifasciculaire + syncope** : risque de **BAV complet infrahissien intermittent** (syncope, mort subite).","cas":[{"si":"Si bradycardie extrême avec QT long","alors":"Risque de torsade de pointes : **corriger les ions**, **accélérer la fréquence cardiaque**, arrêter les médicaments en cause."}],"pieges":[],"src":"p. 383, 387, 403-404, 412"},{"phase":"Interrogatoire","title":"Rechercher une cause médicamenteuse ou physiologique","question":"Que recherches-tu à l'interrogatoire devant cette bradycardie ?","answer":"- **Médicaments bradycardisants** : **intoxication aux bradycardisants** (cause de bradycardie extrême) ; **bêtabloquants**.\n- Médicaments allongeant le **QT** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…).\n- Contexte physiologique : **bradycardie sinusale de l'athlète** (tonus vagal).\n- Symptômes : malaises, lipothymies, syncopes (épisodiques ?), palpitations (syndrome tachycardie-bradycardie).","cas":[],"pieges":["Oublier que la bradycardie sinusale de l'athlète est physiologique."],"src":"p. 376, 393, 403-404"},{"phase":"Examens complémentaires","title":"ECG et ionogramme","question":"Quels examens demandes-tu en urgence ?","answer":"- **ECG 12 dérivations** (per-critique si possible).\n- **Ionogramme** (kaliémie, calcémie) : l'**hyperkaliémie** donne **BAV**, **dysfonction sinusale** (échappement jonctionnel), TV, avec **T amples, pointues, symétriques**, **PR allongé**, **QRS élargi**.\n- Tout QT allongé → vérifier **médicaments et ionogramme**.","cas":[{"si":"Si T amples pointues symétriques + PR long + QRS large","alors":"Évoquer une **hyperkaliémie**."}],"pieges":[],"src":"p. 403-404, 408, 414"},{"phase":"Diagnostic positif","title":"Algorithme devant une bradycardie","question":"La FC des QRS est à 38 bpm. Quel raisonnement appliques-tu ?","answer":"Bradycardie = **FC des QRS < 50 bpm** dans l'algorithme. Seules **deux structures** peuvent être en cause : le **nœud sinusal** ou le **NAV**.\n\n1. **Regarder les ondes P.**\n2. P **régulières à fréquence normale** (ou activité atriale rapide : FA, flutter, TAF) avec **plus de P que de QRS** → problème de passage au ventricule → **BAV**.\n3. P **trop lentes ou absentes** → problème du nœud sinusal → **dysfonction sinusale**.\n\n- Les bradycardies sont des **troubles de la conduction** (le terme « trouble du rythme » désigne les tachycardies).","cas":[],"pieges":[],"src":"p. 389-390"},{"phase":"Diagnostic positif","title":"Identifier le type de BAV et son siège","question":"Les P sont régulières à 75/min, plus nombreuses que les QRS. Comment caractérises-tu le BAV ?","answer":"Dans un BAV, les P sont **régulières et à fréquence normale**.\n\n| Type | Aspect | Siège |\n|---|---|---|\n| **BAV1** | PR **constant > 200 ms**, aucune P bloquée | – |\n| **Mobitz 1** (Luciani-Wenckebach) | PR s'**allonge progressivement** puis une P est bloquée | **suprahissien** |\n| **BAV 2/1** | une P bloquée sur deux | **infrahissien si QRS larges** ; suprahissien si QRS fins et Mobitz 1 à d'autres moments |\n| **Mobitz 2** | PR **constant** puis P bloquée **inopinée** | **infrahissien** |\n| **BAV3** | **dissociation AV complète**, P dissociées (bien vues en V1) | échappement à **QRS fins = bloc nodal** (suprahissien) |\n\n- Le PR explore **toute la conduction**, de la sortie du nœud sinusal au réseau de Purkinje (normal **120–200 ms**).","cas":[{"si":"Si la P « bloquée » est plus précoce que les autres","alors":"C'est une **extrasystole atriale bloquée**, pas un BAV."},{"si":"Si FA ou flutter avec rythme ventriculaire lent et régulier","alors":"**BAV du 3e degré associé** (échappement automatique)."}],"pieges":["Parler de rythme sinusal dans un BAV3 : des P sinusales régulières non conduites ne sont plus un rythme sinusal."],"src":"p. 376, 385-387, 392"},{"phase":"Diagnostic différentiel","title":"Reconnaître une dysfonction sinusale","question":"Si les P sont lentes ou absentes, quels aspects de dysfonction sinusale dois-tu reconnaître ?","answer":"- **Asystole** : tracé plat.\n- **Bloc sinoatrial du 2e degré** : pause par absence intermittente de P, égale au **double de l'intervalle PP (RR)** normal, avec absence complète de **P-QRS-T**.\n- **Échappement jonctionnel** (dysfonction marquée) : P non visible devant le QRS, parfois **rétrograde** derrière lui (dans le ST), **négative en D2** (activation atriale de bas en haut).\n- Aspects pratiques : P trop lentes, P manquante, pause sinusale, P inexistante avec P' rétrograde.\n- **Maladie de l'oreillette** (syndrome tachycardie-bradycardie) : alternance **FA / bradycardie sinusale**, **pauses de régularisation** à l'arrêt de la FA.","cas":[],"pieges":["Oublier que des T négatives dans toutes les précordiales sont pathologiques : éliminer d'abord une ischémie."],"src":"p. 387-389, 392"},{"phase":"Diagnostic positif","title":"Analyser les blocs de branche et hémiblocs","question":"Les QRS sont larges. Comment reconnais-tu un bloc de branche, un hémibloc ou un bloc bifasciculaire ?","answer":"Ordre de lecture : **rythme** → QRS **> 120 ms** ? → V1 positif (BBD) ou négatif (BBG) → aspect inverse en V6.\n\n| | BBD complet | BBG complet |\n|---|---|---|\n| V1 | QRS **positif**, **RsR'** | QRS **négatif**, **rS ou QS** |\n| V6 | **qRs**, S traînante arrondie | **notch**, R souvent exclusive (aussi D1, aVL) |\n\n- **Incomplet** : QRS **110–120 ms**. **Fonctionnel** : n'apparaît qu'en tachycardie ou en bradycardie.\n- **Hémiblocs** : QRS **> 110 ms** + déviation axiale :\n  - **HBAG** (fréquent) : axe au-delà de **–30°** (D2 négatif) ;\n  - **HBPG** (rare) : axe **> +90°** (D1 négatif, S1Q3), en l'absence de pathologie du VD, morphologie longiligne ou infarctus latéral.\n- **Bifasciculaire** : **HBAG + BBD** ou **HBPG + BBD**, QRS > 120 ms.\n- **Discordance appropriée** : T de polarité inverse du QRS.","cas":[],"pieges":["Conclure à un HBPG devant un D1 négatif sans éliminer une inversion d'électrodes (P alors négative en D1)."],"src":"p. 378-383"},{"phase":"Évaluation du risque / pronostic","title":"Estimer le risque de BAV complet","question":"Quel pronostic associes-tu à chaque type de bloc intraventriculaire ?","answer":"- **Hémibloc isolé ou bloc incomplet** : atteinte débutante, **risque de BAV infrahissien faible**.\n- **Bloc bifasciculaire** (BBG complet, ou BBD + hémibloc) : risque de **BAV complet infrahissien intermittent** (syncope, mort subite).\n- **BBG complet** → désynchronisation du VG pouvant créer ou aggraver une cardiopathie.","cas":[{"si":"Si syncope + bloc bifasciculaire","alors":"**Hospitalisation en cardiologie avec télémétrie**."}],"pieges":[],"src":"p. 383"},{"phase":"Hospitalisation & surveillance","title":"Surveiller et documenter","question":"Comment organises-tu la surveillance et la documentation des épisodes ?","answer":"- **Télémétrie / monitorage** en cardiologie (syncope + bloc bifasciculaire, syncope à cause rythmique suspectée).\n- **Holter** (24 à 96 h) si malaises, syncopes épisodiques non documentés par l'ECG standard et susceptibles de récidiver pendant l'enregistrement.\n- Symptômes rares : ECG ambulatoire **jusqu'à 21 jours**, enregistreurs d'événements.\n- **Holter implantable** (jusqu'à **3 ans**) : **syncopes inexpliquées**.\n- Holter 24 h aussi pour l'**efficacité des bradycardisants**.","cas":[],"pieges":[],"src":"p. 383, 414-415"},{"phase":"Traitement spécifique","title":"Poser l'indication d'une prothèse rythmique","question":"Quelles sont les indications de pacemaker et des autres prothèses ?","answer":"- **Pacemaker** :\n  - **bradycardies symptomatiques** : dysfonction sinusale, **BAV2 Mobitz 1**, bradycardie sinusale ;\n  - **BAV infrahissiens** (Mobitz 2, BAV3) : **même sans symptôme**.\n\n| Problème | Prothèse |\n|---|---|\n| Bradycardie | **pacemaker** |\n| TV / FV | **défibrillateur** (fait toujours pacemaker, sauf sous-cutané) |\n| BBG désynchronisant + insuffisance cardiaque | **resynchronisation cardiaque** |","cas":[],"pieges":["Attendre des symptômes pour appareiller un BAV infrahissien."],"src":"p. 412-414"},{"phase":"Suivi","title":"Lire l'ECG d'un patient appareillé","question":"Au suivi, comment reconnais-tu l'ECG d'un patient stimulé et comment le surveilles-tu ?","answer":"- **Spike** : impulsion de **0,4 à 1 ms**, **pathognomonique** d'une stimulation ; bien visible en **unipolaire**, peu visible en **bipolaire**.\n- **Stimulation atriale** (dysfonction sinusale) : une **onde P suit le spike**.\n- **Stimulation ventriculaire** (BAV) : le pacemaker écoute l'oreillette et stimule le ventricule après un **délai AV programmé** → **QRS large d'aspect BBG** après le spike.\n- **Holter 24 h** : surveillance et réglage des **pacemakers**.","cas":[],"pieges":["Oublier que le pacemaker peut masquer des anomalies ischémiques.","Interpréter le sus-ST des dérivations à QRS négatif d'un rythme stimulé comme un SCA."],"src":"p. 412-415"}]},{"title":"Douleur thoracique : lire l'ECG en urgence (SCA, péricardite, BBG, HVG, embolie pulmonaire)","rank":"A","patient":"Homme de 56 ans, fumeur et hypertendu, appelle le 15 pour une douleur thoracique constrictive persistante depuis 1 heure. Il est porteur d'un bloc de branche gauche connu.","steps":[{"phase":"Régulation / pré-hospitalier","title":"ECG et monitorage immédiats","question":"Quels examens ECG réalises-tu dès la prise en charge ?","answer":"- **Monitorage ECG** : urgence, transfert médicalisé, puis **soins intensifs cardiologiques** pour pathologie aiguë (syndrome coronarien).\n- **ECG 18 dérivations** devant **toute douleur thoracique** : 12 dérivations + **V7-V9** (postérieur) + **V3R-V4R** (VD).","cas":[],"pieges":["Se contenter de 12 dérivations devant une douleur thoracique : un SCA postérieur peut n'apparaître qu'en V7-V9."],"src":"p. 371, 411, 414"},{"phase":"Examens complémentaires","title":"Lire l'ECG de façon systématique","question":"Quelle démarche systématique appliques-tu à la lecture et quelles sont les valeurs normales ?","answer":"1. **Rythme** : sinusal (P + en D1, D2 ; un QRS après chaque P, une P avant chaque QRS), **60–100 bpm**.\n2. **Conduction** : P < 120 ms, **PR 120–200 ms**, **QRS 70–110 ms**, axe **–30° à +90°**.\n3. **Repolarisation** : point J et ST **isoélectriques** ; T positives partout sauf **aVR et V1** (parfois D3, aVL) ; **QTc < 450 ms**.\n4. **Morphologie** : amplitudes normales (**Sokolow < 35 mm**), transition normale V1→V6, **pas d'onde Q de nécrose** (> 40 ms et > 1/3 du QRS).\n\n| Territoire | Dérivations |\n|---|---|\n| Antéroseptal | V1, V2, V3 |\n| Apical | V4 |\n| Latéral haut | D1, aVL |\n| Latéral bas | V5, V6 |\n| Inférieur | D2, D3, aVF |\n| Postérieur | V7, V8, V9 |\n| VD | V1, V2, V3R, V4R |","cas":[],"pieges":["Ne pas vérifier la bonne pose des électrodes (transition V1-V6) avant d'interpréter une pseudonécrose antérieure."],"src":"p. 372-377"},{"phase":"Diagnostic positif","title":"Reconnaître un SCA avec sus-décalage de ST","question":"Comment affirmes-tu un SCA ST+ sur l'ECG ?","answer":"- **Traquer d'abord le sus-décalage** (il désigne le territoire de la **coronaire occluse**), **puis** chercher le **miroir** (sous-décalage) — pas l'inverse.\n- **Sus-ST significatif** : **≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes**.\n- S'il englobe la T : **onde de Pardee**.\n- **Deux T négatives dans un même territoire = pathologique**.","cas":[{"si":"Si sous-ST en V1-V3","alors":"Peut être le **miroir d'un sus-ST postérieur** → enregistrer **V7-V9**."}],"pieges":["Partir du sous-décalage pour chercher le sus-décalage."],"src":"p. 411-412"},{"phase":"Diagnostic positif","title":"Douleur thoracique sur bloc de branche gauche","question":"Le patient a un BBG complet et une douleur persistante. Comment interprètes-tu le ST et que fais-tu ?","answer":"- Dans le BBG, la **discordance appropriée** donne un **ST ascendant en V1-V2** (T positive et petit sus-ST dans les dérivations à QRS négatif) qui peut **mimer un SCA ST+**.\n- **Douleur thoracique persistante + BBG** : évoquer l'**infarctus antérieur** et obtenir une **évaluation cardiologique rapide sans attendre la troponine** :\n  - sémiologie de la douleur ;\n  - effet de la **TNT** ;\n  - **signes de choc** ;\n  - **ETT**.\n- **BBG complet + douleur thoracique aiguë** → **éliminer un SCA ST+** (échographie ± **coronarographie**).","cas":[{"si":"Si rythme électroentraîné (stimulation ventriculaire)","alors":"Même sus-ST approprié dans les dérivations à QRS négatif ; les anomalies ischémiques peuvent être **masquées** par le pacemaker."}],"pieges":["Attendre le résultat de la troponine devant une douleur persistante sur BBG."],"src":"p. 381, 411-413"},{"phase":"Diagnostic différentiel","title":"Les cinq causes de sus-décalage du ST","question":"Quelles sont les causes de sus-décalage du ST et les faux positifs à connaître ?","answer":"1. **SCA ST+** (Pardee avec miroir).\n2. **Anévrisme ventriculaire** (persistance après un infarctus à séquelle marquée).\n3. **Repolarisation précoce** (dérivations inférolatérales).\n4. **Angor de Prinzmetal** (spasme coronarien).\n5. **Péricardite** (diffus, concave vers le haut, sans miroir).\n\nDiagnostics différentiels : **BBG ou stimulation ventriculaire** (sus-ST approprié) ; **HVG marquée** (sus-ST en V1-V2).","cas":[{"si":"Si sujet jeune, surtout homme, avec point J sus-décalé de V1 à V4 et ST ascendant","alors":"**Repolarisation physiologique**."}],"pieges":[],"src":"p. 377, 412"},{"phase":"Diagnostic différentiel","title":"Péricardite aiguë ou SCA ?","question":"Comment distingues-tu une péricardite aiguë d'un SCA sur l'ECG ?","answer":"Péricardite : **4 phases** :\n1. brève : **microvoltage** (proportionnel à l'épanchement), **sus-ST concave vers le haut, diffus, concordant, sans miroir**, **sous-décalage de PQ (PR)** ;\n2. T plates partout, ST isoélectrique ;\n3. T **négatives** persistantes ;\n4. retour progressif à la normale.\n\nSCA ST+ : sus-ST désignant le **territoire de la coronaire occluse**, puis recherche du **miroir** (onde de Pardee avec miroir).","cas":[],"pieges":["Conclure à une péricardite devant un SCA ST+ dont le miroir manque."],"src":"p. 409"},{"phase":"Diagnostic positif","title":"SCA sans sus-décalage de ST","question":"L'ECG ne montre pas de sus-ST. Quelles anomalies peux-tu observer dans un SCA sans sus-décalage ?","answer":"- **Sous-décalage du ST** (lésion sous-endocardique).\n- **Inversion des T** (ischémie sous-épicardique).\n- **Pseudo-normalisation** de T auparavant négatives.\n- **Aplatissement** des T.\n- **ECG normal** possible.","cas":[{"si":"Si T négatives dans toutes les précordiales","alors":"Pathologique : éliminer d'abord une **ischémie**."},{"si":"Si patient porteur d'un pacemaker","alors":"Les anomalies peuvent être **masquées**."}],"pieges":["Éliminer un SCA sur un ECG normal."],"src":"p. 388, 412"},{"phase":"Hospitalisation & surveillance","title":"Suivre l'évolution ECG de l'infarctus","question":"En USIC, comment évolue l'ECG d'un SCA ST+ ?","answer":"- **Sus-ST** : régression **rapide si reperfusion** ; plusieurs jours sans reperfusion ; **persistance indéfinie** si **anévrisme** de la paroi infarcie.\n- **T négative « ischémique »** après **48 h**, parfois très prolongée.\n- **Ondes Q de nécrose** : en principe vers la **6e heure** (parfois plus tôt) ; critères **≥ 1/3 (ou 1/4) du QRS** et **> 30–40 ms** ; équivalent : **rabotage de l'onde R** (surtout V2-V3).\n- **Monitorage en soins intensifs cardiologiques** ; la **fibrose post-infarctus** est le substrat de la TV par réentrée.","cas":[],"pieges":["Considérer qu'une onde Q rend la reperfusion inutile : sa présence ne le signifie pas."],"src":"p. 398, 412, 414"},{"phase":"Diagnostic différentiel","title":"Hypertrophies et embolie pulmonaire","question":"Quels autres aspects ECG peuvent se discuter devant une douleur thoracique ou une dyspnée aiguë ?","answer":"- **HVG** : **Sokolow** = S (V1 ou V2) + R (V5 ou V6), normal **< 35 mm** ; forme sévère : T **négative** ± **sous-ST** latéraux (D1, aVL, V5, V6), disparition de la q septale ; QRS le plus souvent < 120 ms. Étiologies : **HTA**, puis **rétrécissement aortique**.\n- **Embolie pulmonaire** : hypertrophie VD aiguë → **S1Q3T3** (S en D1, Q en D3, T négative en D3), **déviation axiale droite**, FA possible.\n- **HVD** [B] : axe **> 110°** (90° en pratique), **R > 6 mm en V1**, **S > 7 mm en V5-V6**, souvent HAD, microvoltage (BPCO), BBD.\n- **HAD** : P > 2,5 mm en D2 ou > 2 mm en V1-V2 ; **HAG** : P > 110 ms (120 en pratique), composante négative > 40 ms en V1.","cas":[{"si":"Si HVG","alors":"Aspect **QS en V1-V2** (pseudonécrose) et **pseudo sus-ST** en V1-V2 pouvant mimer une séquelle d'infarctus ou un SCA."},{"si":"Si T négative asymétrique en V1 (parfois V2-V3) sur HVD sévère","alors":"Ne pas la confondre avec une ischémie."}],"pieges":[],"src":"p. 406-407"},{"phase":"Suivi","title":"Indications de l'ECG au long cours","question":"Après la sortie, dans quelles situations l'ECG est-il indiqué ?","answer":"- **Bilan initial et surveillance** des pathologies cardiaques, ou non cardiaques à risque cardiovasculaire (**diabète, AVC**).\n- **Obligatoire dans le bilan de l'HTA**.\n- **Bilan préopératoire** : patients **> 65 ans**, patients ou interventions à risque.\n- **Aptitude** professionnelle ou sportive ; **enquêtes familiales** de cardiopathies héréditaires.\n- **Symptômes** : palpitations, douleur thoracique, dyspnée, malaise, syncope.\n- **Monitorage** de certains exercices de **réadaptation cardiaque**.\n- **Holter 24 h** : évaluation du **risque rythmique** (salves de TV asymptomatiques après infarctus).","cas":[],"pieges":[],"src":"p. 414-415"}]}],"examens":[{"theme":"ECG & explorations électriques","title":"ECG 12 dérivations : réalisation, dérivations et territoires","rank":"A","content":"#### Indications\n- **Savoir réaliser un ECG 12 dérivations** (objectif de rang A).\n- Indications détaillées : voir la fiche « ECG conventionnel : indications ».\n\n#### Dérivations\n- **Frontales** (plan vertical) : **D1, D2, D3** (I, II, III) obtenues à partir des membres, complétées par les unipolaires **aVR, aVL, aVF**.\n- **Précordiales** (plan horizontal) : **V1 à V9**, complétées par **V3R et V4R** chez l'**enfant** ou en cas de **suspicion de SCA**.\n- Placement : électrodes précordiales **équidistantes**.\n\n#### Territoires explorés (localisation des infarctus)\n| Territoire | Dérivations |\n|---|---|\n| Antéroseptal (paroi antérieure du VG et septum) | V1, V2, V3 |\n| Apical | V4 |\n| Latéral haut | D1, aVL |\n| Latéral bas | V5, V6 |\n| Inférieur (diaphragmatique) | D2, D3, aVF |\n| Postérieur (face basale et inférieure du VG) | V7, V8, V9 |\n| Ventricule droit | V1, V2, V3R, V4R |\n\n#### Étalonnage\n- Vitesse **25 mm/s** : 1 mm = **40 ms** ; grand carreau (5 mm) = **200 ms**.\n- Amplitude : 1 mm = **0,1 mV**.\n\n#### Pièges\n- **V1 et V2 trop souvent placées trop haut et trop écartées** (confusion avec les foyers auscultatoires aortique et pulmonaire) → faux aspect de **pseudonécrose** ou d'atypie de repolarisation antérieure.\n- **D1 négatif** : penser d'abord à une **inversion des électrodes** frontales (P alors négative en D1).\n- La transition normale de V1 à V6 (R croît, S décroît) permet aussi de vérifier la **bonne pose des électrodes**.","src":"p. 371-375"},{"theme":"ECG & explorations électriques","title":"ECG 18 dérivations (V7-V9, V3R-V4R)","rank":"A","content":"#### Indications\n- **Devant toute douleur thoracique** : ECG 18 dérivations (**V7-V9, V3R-V4R**).\n- V3R et V4R : chez l'enfant ou en cas de suspicion de SCA.\n\n#### Ce qu'on recherche\n- **V7, V8, V9** : territoire **postérieur** (face basale et inférieure du VG).\n- **V1, V2, V3R, V4R** : **ventricule droit**.\n\n#### Pièges\n- Un **sous-décalage de ST en V1-V3** peut être le **miroir d'un sus-décalage postérieur (V7-V9)**.","src":"p. 371, 411, 414"},{"theme":"ECG & explorations électriques","title":"Dérivations de Lewis","rank":"A","content":"#### Indications\n- **Démasquer une activité atriale peu visible**.\n\n#### Technique\n- Électrode **rouge** (bras droit) sur la **fourchette sternale**.\n- Électrode **jaune** (bras gauche) au **5e espace intercostal droit**.\n- L'activité atriale est alors bien lue en **D1**.","src":"p. 371"},{"theme":"ECG & explorations électriques","title":"Lecture systématique et valeurs normales de l'ECG","rank":"A","content":"#### Valeurs normales (adulte)\n| Paramètre | Normale |\n|---|---|\n| Fréquence cardiaque | **60–100 bpm** (bradycardie < 60, tachycardie > 100) |\n| Durée de P | **< 120 ms** (théorique < 110 ms) |\n| Axe de P | **60°** (maximum en D2) |\n| Amplitude de P | **< 2,5 mm en D2** |\n| PR (début P → début QRS) | **120–200 ms** inclus |\n| Durée QRS | **70–110 ms** |\n| Axe QRS | **–30° à +90°** |\n| Onde Q physiologique | **< 1/3 du QRS et < 40 ms** |\n| QT corrigé | **< 450 ms à 60 bpm** (en pratique 470–480 ms) |\n\n#### Lecture systématique pour affirmer un ECG normal\n1. **Rythme** : sinusal (P + en D1, D2 ; un QRS après chaque P, une P avant chaque QRS), 60–100 bpm.\n2. **Conduction** : P < 120 ms, PR 120–200 ms, QRS fins 70–110 ms, axe –30° à +90° (positif en D1 et D2).\n3. **Repolarisation** : point J et ST **isoélectriques** ; T positives partout sauf **aVR et V1**, parfois **D3 et aVL** ; QT < 450 ms.\n4. **Morphologie** : amplitudes de P et QRS normales (**Sokolow < 35 mm**), transition normale V1 → V6, pas d'onde Q de nécrose (> 40 ms et > 1/3 du QRS).\n\n#### Rythme sinusal\n- P **positive en D1 et en inférieur** (activation atriale de haut à droite vers bas à gauche).\n- Chaque P suivie d'un QRS **et** chaque QRS précédé d'une P. Des P sinusales régulières non conduites (BAV3) ne sont **plus** un rythme sinusal.\n\n#### Calcul de la fréquence\n- FC = 60 / RR (s) ; en pratique **FC = 300 / nombre de grands carreaux** entre deux QRS (1 carreau = 300, 2 = 150…).\n\n#### Pièges\n- Bradycardie sinusale **physiologique de l'athlète** (tonus vagal) ; variation respiratoire chez le jeune ; valeurs de l'adulte : attention au **nouveau-né**.\n- Chez le jeune, surtout l'homme : **point J sus-décalé de V1 à V4 avec ST jonctionnel ascendant = repolarisation physiologique**.\n- **Deux T négatives dans un même territoire = pathologique** (ex. D2 et D3 → inférieur).\n- Des **T négatives dans toutes les précordiales** sont pathologiques : éliminer d'abord une **ischémie**.","src":"p. 375-378"},{"theme":"ECG & explorations électriques","title":"Axe du QRS","rank":"A","content":"#### Mesure\n- Plan frontal, **double triaxe de Bailey** : dérivations graduées de **30° en 30°** dans le sens horaire, D1 à l'horizontale (0°).\n\n#### Méthode rapide (D1 et aVF)\n| D1 | aVF | Axe |\n|---|---|---|\n| + | + | 0 à +90° : **normal** |\n| + | – | 0 à –90° : normal si **D2 positif** (0 à –30°), sinon **hypergauche** |\n| – | + | +90 à +180° : **hyperdroit** |\n| – | – | –90 à –180° : **axe extrême** |\n\n#### Interprétation\n- **Axe normal : –30° à +90°** (de aVL à aVF ; valeurs théoriques –45° à +110°).\n- Cœur **vertical** (sujet filiforme) → axe proche de 90° ; cœur **horizontal** (obèse, cardiomégalie) → axe proche de 0°.\n- Axe anormal : **hémibloc** gauche ou anomalie morphologique marquée d'un ventricule.\n- Onde **isodiphasique** : composantes positive et négative d'égale importance.","src":"p. 375"},{"theme":"ECG & explorations électriques","title":"Mesure du QT et QT corrigé","rank":"A","content":"#### Mesure\n- Du **début de Q à la fin de T**, dans la dérivation où T est la plus ample et la plus longue (**souvent V2-V3**), par la **tangente** à l'onde T.\n- **Bazett** : **QTc = QT mesuré / √RR** (RR en secondes) → une seule norme, celle de 60 bpm (RR = 1 s).\n\n#### Interprétation\n- Normal : **QTc < 450 ms à 60 bpm** (en pratique 470–480 ms).\n- QT long → risque de **torsade de pointes**. Causes : **médicamenteuses** (antiarythmiques, psychotropes, antibiotiques, antiémétiques, antipaludéens…), **ioniques** (hypoK, hypoCa, hypoMg), **bradycardie extrême**, **congénitale** (syndrome du QT long).\n- Tout QT allongé → **vérifier les médicaments et le ionogramme**, corriger.\n\n#### Pièges\n- **Ne jamais inclure une onde U** dans le QT (onde U de l'hypokaliémie).","src":"p. 377, 403-404, 408"},{"theme":"ECG & explorations électriques","title":"ECG des blocs de branche, hémiblocs et blocs bifasciculaires","rank":"A","content":"#### Ce qu'on recherche\n- **Toujours décrire d'abord le rythme atrial** (TSV + bloc de branche n'est pas rare).\n- Ordre : rythme sinusal ? → **QRS > 120 ms** ? → **V1 positif (BBD) ou négatif (BBG)** → aspect inverse en V6.\n\n| | BBD complet | BBG complet |\n|---|---|---|\n| V1 | globalement **positif**, **RsR'** | globalement **négatif**, **rS ou QS** |\n| V6 (et D1, aVL pour le BBG) | **qRs**, S traînante arrondie | **notch** (double pic), R souvent exclusive |\n\n- **Discordance appropriée** : T **discordante** du QRS (QRS négatif → T positive + petit sus-ST ; QRS positif → T négative + petit sous-ST).\n- **Blocs incomplets** (rang B) : mêmes anomalies avec QRS **110–120 ms**, faible intérêt sémiologique.\n- **Bloc fonctionnel** (rang B) : n'existe qu'à partir d'une fréquence donnée — en **tachycardie** ou en **bradycardie**.\n- **Hémiblocs** : QRS peu élargi (**> 110 ms**, > 120 ms si bloc de branche associé ou cardiopathie marquée) + **déviation axiale** :\n  - **HBAG** : axe au-delà de **–30°** (D2 négatif) ; **fréquent** ;\n  - **HBPG** : axe > **+90°** (D1 négatif, aspect **S1Q3**) en l'absence de pathologie du VD, de morphologie longiligne ou d'infarctus latéral ; **rare**.\n- **Bifasciculaire** : **HBAG + BBD** ou **HBPG + BBD**, QRS > 120 ms.\n\n#### Interprétation / conséquences (rang B)\n- Hémibloc isolé ou bloc incomplet : risque de BAV infrahissien faible.\n- Bloc bifasciculaire (BBG complet, ou BBD + hémibloc) : risque de **BAV complet infrahissien intermittent**. **Syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie.**\n- BBG complet → **désynchronisation** du VG ; correction indiquée si insuffisance cardiaque.\n\n#### Pièges\n- Dans le BBG, le **ST ascendant en V1-V2 peut mimer un SCA ST+**.\n- **Douleur thoracique persistante + BBG** : évoquer l'**infarctus antérieur**, évaluation cardiologique rapide **sans attendre la troponine**.\n- **D1 négatif** : penser d'abord à une **inversion des électrodes** avant l'HBPG.","src":"p. 378-385"},{"theme":"ECG & explorations électriques","title":"ECG des blocs atrioventriculaires","rank":"A","content":"#### Ce qu'on recherche\n- Dans un BAV, les ondes P sont **régulières et à fréquence normale**.\n\n| Type | Aspect | Siège |\n|---|---|---|\n| BAV1 | PR **constant > 200 ms**, aucune P bloquée | – |\n| BAV2 Mobitz 1 (Luciani-Wenckebach) | PR **s'allonge progressivement** puis P bloquée | suprahissien |\n| BAV 2/1 | une P bloquée sur deux | infrahissien si QRS larges ; suprahissien si QRS fins et Mobitz 1 à d'autres moments |\n| BAV2 Mobitz 2 | PR **constant** puis P bloquée inopinée | infrahissien |\n| BAV3 | **dissociation AV complète**, P dissociées (bien vues en V1) | échappement à QRS fins = bloc nodal (suprahissien) |\n\n- **BAV associés aux troubles du rythme** (rang B) : **FA + BAV complet** → rythme ventriculaire **lent et régulier** (échappement).\n\n#### Algorithme devant une bradycardie (FC des QRS < 50 bpm)\n1. **Regarder les ondes P.**\n2. P régulières à fréquence normale, ou activité atriale rapide (FA, flutter, TAF), avec **plus de P que de QRS** → **BAV**.\n3. P **trop lentes ou absentes** → **dysfonction sinusale**.\n\n#### Pièges\n- Une P « bloquée » **plus précoce** que les autres = **extrasystole atriale bloquée**.","src":"p. 385-389, 392"},{"theme":"ECG & explorations électriques","title":"ECG de la dysfonction sinusale","rank":"A","content":"#### Ce qu'on recherche\n- Cas simples : **asystole** (tracé plat) ; **pauses** par absence intermittente d'une onde P = **bloc sinoatrial du 2e degré** (rang B) : pause égale au **double de l'intervalle PP (RR)** normal, absence complète de P-QRS-T.\n- Dysfonction marquée : **échappement jonctionnel** ; P non visible devant le QRS, parfois **rétrograde** derrière lui (dans le ST), **négative en D2**.\n- Aspects pratiques : P trop lentes, P manquante, pause sinusale, P inexistante avec P' rétrograde.\n- **Maladie de l'oreillette** (rang B) : alternance FA / bradycardie sinusale, **pauses de régularisation** à l'arrêt de la FA.","src":"p. 385-389, 392"},{"theme":"ECG & explorations électriques","title":"ECG des tachycardies supraventriculaires (sinusale, FA, flutter, TAF, jonctionnelle)","rank":"A","content":"#### Ce qu'on recherche\n- TSV : QRS **fins (< 120 ms)** le plus souvent ; larges si bloc de branche associé.\n- **Tachycardie sinusale** : P positives en **D1, D2, D3 et aVF** ; FC **variable progressivement** (vs TSV : **« marches d'escalier »**).\n- **Fibrillation atriale** : activation atriale anarchique, **100–200 bpm**, QRS **« irrégulièrement irréguliers »** ; ligne de base : **mailles amples** ou **fine trémulation**.\n- **Flutter** : activité atriale **monomorphe ≈ 300 bpm (240–340)**, **sans retour à la ligne isoélectrique** dans au moins une dérivation, ondes **F** en toit d'usine / dents de scie.\n  - **Typique antihoraire** (isthme cavotricuspide) : F **négatives en D2, D3, aVF, positives en V1, négatives en V6** ; typique horaire : polarités inversées.\n  - **Atypiques** : **120–320 bpm**, F variables.\n  - Ventricules : **150 bpm (2/1)**, 100 (3/1), 75… ; sinon **conduction variable**.\n- **Tachycardie atriale focale** : la manœuvre vagale ou l'adénosine **démasque l'activité atriale** sans arrêter la tachycardie.\n- **Tachycardie jonctionnelle (Bouveret)** : **très régulière ≈ 200 bpm (130–260)** ; réentrée intranodale (P invisible ou devinée dans le ST) ou rythme réciproque par voie accessoire (faisceau de Kent).\n- **Extrasystoles** : atriale (P précoce de morphologie différente + QRS fin), jonctionnelle (QRS fin ± P' rétrograde), ventriculaire (QRS large ± P' rétrograde) ; **bigéminisme**, **trigéminisme**, doublets, triplets, salves.\n\n#### Formes difficiles (rang B)\n- **FA + BAV complet** : rythme **lent et régulier**.\n- **FA + bloc de branche** : tachycardie **irrégulière à QRS larges**.\n\n#### Pièges\n- Au repos, une tachycardie marquée **sans cause d'hypermétabolisme** (fièvre, stress, douleur) **n'est pas sinusale**.\n- Parler de flutter « d'aspect » typique/atypique : diagnostic formel par la fréquence ou l'**exploration électrophysiologique**.\n- Extrasystoles **fréquentes ou polymorphes** → rechercher une cardiopathie.","src":"p. 389-398"},{"theme":"ECG & explorations électriques","title":"ECG des troubles du rythme ventriculaire (TV, FV, torsades)","rank":"A","content":"#### Ce qu'on recherche\n- **TV** : suspicion si **FC > 100 bpm + QRS > 120 ms sur ≥ 3 battements consécutifs** → alerte (15, préparer la réanimation).\n  - **Non soutenue** : 3 battements à 30 s ; **soutenue** : > 30 s ; monomorphe / polymorphe.\n  - **Certitude** : **dissociation ventriculoatriale** (plus de QRS que de P), complexes de **capture** (QRS fin précédé d'une P) et de **fusion**.\n  - **En faveur** : cardiopathie sous-jacente +++, **concordance** positive ou négative de V1 à V6, **axe extrême** (QRS positif en aVR), QRS larges d'aspect atypique de bloc de branche.\n- **FV** : tachycardie **irrégulière à QRS larges polymorphes** ; **urgence absolue** (choc électrique immédiat).\n- **Torsades de pointes** (rang B) : TV **polymorphe** s'arrêtant spontanément ou dégénérant en FV ; diagnostic sur le **QT long préalable** et le contexte.\n\n#### Algorithme devant une tachycardie (FC > 100 bpm)\n1. **Irrégulière** → **FA** (diagnostic différentiel : ESA).\n2. **Régulière à QRS larges** → ventriculaire jusqu'à preuve du contraire (ou TSV + bloc de branche).\n3. **Régulière à QRS fins** → supraventriculaire.\n- **Mauvaise tolérance hémodynamique → cardioversion électrique externe**.\n\n#### Pièges\n- **Toute tachycardie régulière à QRS larges est une TV jusqu'à preuve du contraire.**\n- Dissociation **ventriculoatriale** de la TV (plus de QRS que de P) ≠ dissociation AV du BAV3.\n- Torsade possible **à QT normal**, déclenchée par deux ESV dont la 2e tombe sur la T de la 1re.","src":"p. 398-405"},{"theme":"ECG & explorations électriques","title":"ECG des hypertrophies atriales et ventriculaires","rank":"A","content":"#### Ce qu'on recherche\n| | Critères |\n|---|---|\n| **HAD** (rang B) | P **> 2,5 mm en D2** (souvent pointue) ou **> 2 mm en V1-V2** |\n| **HAG** (rang B) | P **> 110 ms** (120 ms en pratique), composante **négative > 40 ms en V1** |\n| **HVG** | **Sokolow** = S (V1 ou V2) + R (V5 ou V6), normal **< 35 mm** |\n| **HVD** (rang B) | **axe > 110°** (90° en pratique) — signe le plus précoce ; **R > 6 mm en V1**, **S > 7 mm en V5-V6** |\n\n- **HVG sévère** : T **négative** ± **sous-ST** dans les latérales (D1, aVL, V5, V6) et **disparition de la q septale** ; déviation axiale gauche modeste ; QRS le plus souvent **< 120 ms**. Étiologies : **HTA** puis **rétrécissement aortique**.\n- **HVD** : association fréquente à une **HAD**, un **microvoltage** (BPCO), un **BBD** ; T négative asymétrique en V1 (parfois V2-V3) dans les formes sévères.\n- **Embolie pulmonaire** : **S1Q3T3** (S en D1, Q en D3, T négative en D3), déviation axiale droite, FA possible.\n\n#### Limites\n- HVD : intérêt modeste **à l'ère de l'échographie** ; utile chez le **BPCO** ou l'atteinte pulmonaire sévère.\n\n#### Pièges\n- HVG : aspect **QS en V1-V2** (pseudonécrose) et **pseudo sus-décalage du ST en V1-V2** mimant une séquelle d'infarctus ou un SCA.\n- HVD : T négative en V1-V3 à ne pas confondre avec une **ischémie** ; même aspect possible dans l'**HBPG** ou chez le sujet **longiligne**.","src":"p. 406-408"},{"theme":"ECG & explorations électriques","title":"ECG des dyskaliémies","rank":"A","content":"#### Ce qu'on recherche\n| | Hypokaliémie | Hyperkaliémie |\n|---|---|---|\n| Onde T | **plate ou négative**, diffuse, **sous-ST** | **ample, pointue, symétrique** |\n| PR | – | **allongé** |\n| QRS | normal | **élargi** |\n| QT / U | **QT allongé**, **onde U** | – |\n| Rythme | ESV, TV, **torsade de pointes**, FV | **BAV**, TV, **dysfonction sinusale** (échappement jonctionnel) |\n\n#### Pièges\n- L'**onde U** est **exclue** de la mesure du QT.","src":"p. 408"},{"theme":"ECG & explorations électriques","title":"ECG de la péricardite aiguë","rank":"B","content":"#### Ce qu'on recherche : 4 phases\n1. Phase 1, brève : **microvoltage** (proportionnel à l'épanchement), **sus-ST concave vers le haut, diffus, concordant, sans miroir**, **sous-décalage de PQ (PR)**.\n2. T **plates** partout, ST isoélectrique.\n3. T **négatives** persistantes.\n4. Retour progressif à la normale.\n\n#### Pièges\n- **Ne pas conclure à une péricardite devant un SCA ST+ dont le miroir manque.**","src":"p. 409"},{"theme":"ECG & explorations électriques","title":"ECG de la préexcitation (Wolff-Parkinson-White)","rank":"B","content":"#### Ce qu'on recherche\n- **PR court < 120 ms**.\n- **Onde delta** : élargissement du QRS par empâtement de son pied.\n- **Troubles de repolarisation** dans le territoire de la voie.\n- **Syndrome de WPW** = voie accessoire antérograde + palpitations par tachycardie jonctionnelle.\n- FA sur voie accessoire (**super-Wolff**) : tachycardie **irrégulière, très rapide, à QRS de largeur variable « en accordéon »** → risque de FV.\n\n#### Précautions\n- Bloquer le NAV (massage, adénosine) démasque une préexcitation minime — **jamais en cas de FA**.","src":"p. 410"},{"theme":"ECG & explorations électriques","title":"ECG de la maladie coronarienne et des SCA","rank":"A","content":"#### Ce qu'on recherche\n- **SCA ST+** : **traquer le sus-décalage** (territoire de la coronaire occluse), **puis** chercher le **miroir**.\n- Sus-ST significatif : **≥ 2 mm en V1-V3**, **≥ 1 mm ailleurs**, sur **≥ 2 dérivations adjacentes** ; englobant la T : **onde de Pardee**.\n- Évolution : régression rapide si reperfusion ; plusieurs jours sans ; persistance si **anévrisme** ; après **48 h**, **T négative « ischémique »**.\n- **Ondes Q de nécrose** : vers la **6e heure** ; **≥ 1/3 (ou 1/4) du QRS** et **> 30–40 ms** ; équivalent : **rabotage de l'onde R** (V2-V3).\n- **SCA sans sus-ST** : **sous-ST** (lésion sous-endocardique), **inversion des T** (ischémie sous-épicardique), **pseudo-normalisation**, **aplatissement** des T, ou **ECG normal**.\n\n#### Cinq étiologies de sus-décalage du ST\n1. **SCA ST+** (Pardee avec miroir).\n2. **Anévrisme ventriculaire**.\n3. **Repolarisation précoce** (inférolatérale).\n4. **Angor de Prinzmetal**.\n5. **Péricardite** (diffus, concave, sans miroir).\n\n#### Pièges\n- Sous-ST en V1-V3 = possible **miroir d'un sus-ST postérieur** → **ECG 18 dérivations**.\n- **BBG complet + douleur thoracique aiguë** → éliminer un SCA ST+ (échographie ± coronarographie).\n- Faux sus-ST : **BBG ou stimulation ventriculaire** (dérivations à QRS négatif), **HVG marquée** (V1-V2).\n- Les ondes Q ne signifient pas qu'une reperfusion serait inutile.\n- Un **pacemaker** peut masquer les anomalies ischémiques.","src":"p. 411-412"},{"theme":"ECG & explorations électriques","title":"ECG du porteur de stimulateur cardiaque","rank":"B","content":"#### Ce qu'on recherche\n- **Spike** : impulsion de **0,4 à 1 ms**, **pathognomonique** d'une stimulation (pacemaker ou sonde d'entraînement électrosystolique).\n- **Unipolaire** : spike bien visible ; **bipolaire** : spike peu visible.\n- Stimulation **atriale** (dysfonction sinusale) : une **onde P suit le spike**.\n- Stimulation **ventriculaire** (BAV, après un délai AV programmé) : **QRS large d'aspect BBG** après le spike.\n\n#### Pièges\n- Le pacemaker peut **masquer les anomalies ischémiques**.\n- Stimulation ventriculaire : sus-ST approprié dans les dérivations à QRS négatif (diagnostic différentiel du SCA ST+).","src":"p. 412-414"},{"theme":"ECG & explorations électriques","title":"ECG conventionnel : indications","rank":"A","content":"#### Indications\n- Systématique dans les **centres de santé** (bilans de santé).\n- **Aptitude** professionnelle (conducteurs, pilotes) ou sportive (sports à risque, compétition, professionnels).\n- **Bilan préopératoire** : patients **> 65 ans**, patients à risque, interventions à risque.\n- **Enquêtes familiales** de certaines cardiopathies héréditaires.\n- **Symptômes** : palpitations, douleur thoracique, dyspnée aiguë ou chronique, malaise, perte de connaissance, syncope.\n- **Obligatoire dans le bilan de l'HTA**.\n- Bilan initial et surveillance des pathologies cardiaques, ou non cardiaques à risque cardiovasculaire (diabète, AVC).\n- Urgence (objectif) : défaillance d'organe, douleur thoracique, palpitations, syncope, troubles hydroélectrolytiques (K, Ca).\n- **ECG 18 dérivations** devant une douleur thoracique.","src":"p. 414"},{"theme":"ECG & explorations électriques","title":"Monitorage ECG (cardioscope, télémétrie)","rank":"A","content":"#### Indications\n- Toute **urgence**, réanimation et **transfert médicalisé**.\n- Surveillance en **soins intensifs cardiologiques** (ex. syndrome coronarien).\n- **Syncope** avec cause rythmique suspectée ; **syncope + bloc bifasciculaire** → hospitalisation en cardiologie **avec télémétrie**.\n- **Peropératoire** et salle de réveil.\n- Certains exercices de **réadaptation cardiaque**.\n\n#### Ce qu'on recherche\n- La courbe de fréquence (scope, télémétrie, holter) distingue la **tachycardie sinusale** (variation progressive) d'une **TSV** (marches d'escalier).","src":"p. 383, 391, 414"},{"theme":"ECG & explorations électriques","title":"Holter ECG","rank":"B","content":"#### Indications\n- Malaises, syncopes, pertes de connaissance ou palpitations **épisodiques** quand l'ECG standard n'a rien montré et que les symptômes ont une probabilité de récidiver pendant l'enregistrement.\n- Holter de 24 h : efficacité des **bradycardisants**, surveillance et réglage des **pacemakers**, évaluation du **risque rythmique** (salves de TV asymptomatiques après infarctus ou dans les cardiomyopathies).\n\n#### Technique\n- ECG de longue durée, **2 à 12 dérivations** simultanées, **24 à 96 h maximum**, support numérique, **lecture différée**.\n\n#### Limites\n- Symptômes rares : ECG ambulatoire de très longue durée (**jusqu'à 21 jours**) ou **enregistreurs d'événements** (voir fiche dédiée).","src":"p. 415"},{"theme":"ECG & explorations électriques","title":"Enregistrements ECG de très longue durée et objets connectés","rank":"B","content":"#### Indications\n- **Symptômes rares** : ECG ambulatoire de très longue durée (**jusqu'à 21 jours**) ou **enregistreurs d'événements** (outils dédiés, montres connectées ECG).","src":"p. 415"},{"theme":"ECG & explorations électriques","title":"Holter implantable (moniteur ECG sous-cutané)","rank":"B","content":"#### Indications\n- **Syncopes inexpliquées**, **FA silencieuse**.\n\n#### Caractéristiques\n- Suivi **jusqu'à 3 ans**.","src":"p. 413-415"},{"theme":"ECG & explorations électriques","title":"Exploration électrophysiologique","rank":"B","content":"#### Indications (citées)\n- Diagnostic formel du type de **flutter** (typique/atypique), avant **ablation par radiofréquence**.","src":"p. 394"},{"theme":"Gestes & procédures","title":"Manœuvres vagales","rank":"B","content":"#### Indications\n- Créer un **BAV transitoire** : diagnostic différentiel des tachycardies, **réduction des tachycardies jonctionnelles**.\n- Démasquer les ondes **F** du flutter (utile en 1/1 ou 2/1) ; analyser une activité atriale difficile en FA.\n\n#### Technique\n- **Valsalva** (expiration forcée à glotte fermée).\n- **Compression carotidienne unilatérale**.\n- **Grand verre d'eau froide**.\n\n#### Résultats & interprétation\n- **Démasque l'activité atriale** → sinusale, flutter, TAF.\n- **Arrête la tachycardie** → jonctionnelle (réentrée dépendante du NAV).\n- **Aucun effet** → TV (indépendante du NAV) ; certitude si dissociation AV.\n\n#### Contre-indications\n- Compression carotidienne : **athérome important** ou **souffle carotidien**.\n- **Compression oculaire bilatérale : n'est plus recommandée** (décollement de rétine du myope).\n- Bloquer le NAV pour démasquer une préexcitation : **jamais en cas de FA**.","src":"p. 390, 405, 410"},{"theme":"Gestes & procédures","title":"Test à l'adénosine IV","rank":"B","content":"#### Indications\n- **Si échec des manœuvres vagales** : créer un BAV transitoire (diagnostic des tachycardies, réduction des tachycardies jonctionnelles, démasquer une préexcitation minime).\n\n#### Technique\n- Vagomimétique via les **récepteurs purinergiques**, en **flash IV**, effet d'une **dizaine de secondes**.\n\n#### Contre-indications\n- **Asthme** (bronchospasme intense transitoire possible **même chez le non asthmatique**).\n- **Hypotension**.\n- **FA préexcitée** (super-Wolff).","src":"p. 390, 410"},{"theme":"Gestes & procédures","title":"Choc électrique externe (cardioversion, défibrillation)","rank":"A","content":"#### Indications\n- Tachycardie **mal tolérée sur le plan hémodynamique** → **cardioversion électrique externe**.\n- **FV** : **choc électrique immédiat avant tout autre geste**, massage cardiaque en attendant.","src":"p. 402-405"},{"theme":"Gestes & procédures","title":"Implantation d'un stimulateur cardiaque (pacemaker)","rank":"B","content":"#### Indications\n- **Bradycardies symptomatiques** : dysfonction sinusale, BAV2 Mobitz 1, bradycardie sinusale.\n- **BAV infrahissiens** (BAV2 Mobitz 2, BAV3) : **même sans symptôme**.\n\n#### Principe\n- Stimulation locale de quelques myocytes puis conduction de proche en proche.","src":"p. 412-413"},{"theme":"Gestes & procédures","title":"Défibrillateur implantable et resynchronisation cardiaque","rank":"B","content":"#### Indications\n- **Défibrillateur** : **TV / FV** (champ électrique réinitialisant tous les myocytes) ; fait toujours pacemaker, **sauf sous-cutané**.\n- **Resynchronisation** : **BBG désynchronisant le VG avec insuffisance cardiaque** (stimulateur, donc toujours pacemaker).\n- Fonctions associables : **défibrillateur de resynchronisation**.","src":"p. 383, 413"},{"theme":"Biologie","title":"Ionogramme sanguin (kaliémie, calcémie, magnésémie)","rank":"A","content":"#### Indications\n- **Tout QT allongé** → vérifier les **médicaments et le ionogramme**.\n- Urgence ECG en cas de **troubles hydroélectrolytiques (K, Ca)**.\n\n#### Interprétation\n- Causes ioniques de QT long / torsade : **hypokaliémie**, **hypocalcémie**, **hypomagnésémie** → **corriger les ions**.\n- Traduction ECG des dyskaliémies : voir fiche « ECG des dyskaliémies ».","src":"p. 403-404, 408"},{"theme":"Biologie","title":"Troponine","rank":"A","content":"#### Pièges\n- **Douleur thoracique persistante + BBG** : évoquer l'infarctus antérieur et obtenir une évaluation cardiologique rapide **sans attendre la troponine** (sémiologie de la douleur, effet de la TNT, signes de choc, ETT).","src":"p. 381"},{"theme":"Imagerie","title":"Échocardiographie transthoracique","rank":"A","content":"#### Indications\n- **BBG + douleur thoracique** : ETT dans l'évaluation cardiologique rapide ; éliminer un SCA ST+ (échographie ± coronarographie).\n\n#### Limites\n- L'ECG de l'HVD a un **intérêt modeste à l'ère de l'échographie**.","src":"p. 381, 407, 411"},{"theme":"Gestes & procédures","title":"Coronarographie","rank":"A","content":"#### Indications\n- **BBG complet + douleur thoracique aiguë** → éliminer un SCA ST+ (échographie **± coronarographie**).","src":"p. 411"}]}});
